export default BittingCut;

"use client";

// ---------------------------------------------------------------------------
// BlastRoundPattern — a bench-blast shot pattern: a grid of charged holes
// that fires row by row on a fixed delay wave, not all at once. Real
// electronic detonators run 25-50ms between rows (far too fast to read as
// a sequence), so the row cadence here is deliberately decoupled from that
// real rate and rendered 36x slower at 900ms/row — the real number is
// documented, the animation is the legible one.
//
// Each cell is a div whose crater is painted from two CSS custom properties,
// --fire (0 unfired -> 1 peak flash) and --spent (0 fresh -> 1 spent-dark),
// set directly on the row wrapper each frame (never React state) and read
// by every cell in that row through ordinary CSS inheritance — one rAF
// write per row, not per cell. Every colour is `var(--foreground)` /
// `var(--ns-muted)` mixed against itself or scaled with `filter:brightness`,
// so direction (darker/lighter) tracks whichever theme is active without
// ever branching on it in JS.
// ---------------------------------------------------------------------------

import { useEffect, useRef, useState } from "react";

const MIN_GRID = 6;
const MAX_GRID = 9;
const TARGET_CELL_PX = 32;

const ROW_DELAY_MS = 900; // decoupled render rate; real electronic-det. delay is 25-50ms/row
const RISE_MS = 80;
const HOLD_MS = 120;
const DECAY_MS = 600;
const FLASH_MS = RISE_MS + HOLD_MS + DECAY_MS; // 800ms — a row is fully spent 100ms before the next fires
const CLEARED_PAUSE_MS = 2000;
const RECHARGE_PER_ROW_MS = 250;

// loop-start phase: mounts mid-hold on row 0 so t0 already shows motion
const START_PHASE_MS = RISE_MS + HOLD_MS / 2;

const SPENT_BRIGHTNESS_FLOOR = 0.38; // filter:brightness() applied to muted — always darker, both themes

function computeGridSize(minDim: number): number {
  const n = Math.round(minDim / TARGET_CELL_PX);
  return Math.min(MAX_GRID, Math.max(MIN_GRID, n));
}

// ease-out for the rise, ease-in for the decay — fast punch, slow settle
function easeOutCubic(t: number): number {
  const u = 1 - t;
  return 1 - u * u * u;
}
function easeInCubic(t: number): number {
  return t * t * t;
}

// Per-row (--fire, --spent) at a given time-into-pattern (can be negative
// before the row's own fireStart, and keeps returning "spent" indefinitely
// after the row finishes until the recharge sweep resets it explicitly).
function rowFireState(tSinceRowStart: number): { fire: number; spent: number } {
  if (tSinceRowStart < 0) return { fire: 0, spent: 0 };
  if (tSinceRowStart < RISE_MS) {
    return { fire: easeOutCubic(tSinceRowStart / RISE_MS), spent: 0 };
  }
  if (tSinceRowStart < RISE_MS + HOLD_MS) {
    return { fire: 1, spent: 0 };
  }
  if (tSinceRowStart < FLASH_MS) {
    const d = easeInCubic((tSinceRowStart - RISE_MS - HOLD_MS) / DECAY_MS);
    return { fire: 1 - d, spent: d };
  }
  return { fire: 0, spent: 1 };
}

export interface BlastRoundPatternProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible label for the pattern */
  "aria-label"?: string;
}

export function BlastRoundPattern({
  className = "",
  "aria-label": ariaLabel = "Blast round delay sequence",
}: BlastRoundPatternProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const rowRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [gridSize, setGridSize] = useState(MIN_GRID);

  // grid size tracks the container's smaller dimension, so the pattern
  // reads as 6x6 at card scale and grows toward 9x9 on a larger card
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const box = entry.contentBoxSize?.[0];
      const w = box ? box.inlineSize : entry.contentRect.width;
      const h = box ? box.blockSize : entry.contentRect.height;
      setGridSize(computeGridSize(Math.min(w, h)));
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rowEls = rowRefs.current.slice(0, gridSize);

    const cycleFireMs = gridSize * ROW_DELAY_MS;
    const cycleMs = cycleFireMs + CLEARED_PAUSE_MS + gridSize * RECHARGE_PER_ROW_MS;

    const paint = (phase: number) => {
      for (let r = 0; r < rowEls.length; r++) {
        const el = rowEls[r];
        if (!el) continue;

        const rowFireStart = r * ROW_DELAY_MS;
        const rechargeStart = cycleFireMs + CLEARED_PAUSE_MS + r * RECHARGE_PER_ROW_MS;

        let fire = 0;
        let spent: number;

        if (phase < cycleFireMs + CLEARED_PAUSE_MS) {
          // firing phase + the cleared pause that follows it
          const st = rowFireState(phase - rowFireStart);
          fire = st.fire;
          spent = st.spent;
        } else if (phase < rechargeStart) {
          // row hasn't reached its turn in the recharge sweep yet
          spent = 1;
        } else if (phase < rechargeStart + RECHARGE_PER_ROW_MS) {
          // quiet reset, no flash: spent eases back to 0 over its 250ms slot
          const t = (phase - rechargeStart) / RECHARGE_PER_ROW_MS;
          spent = 1 - t;
        } else {
          spent = 0;
        }

        el.style.setProperty("--fire", fire.toFixed(4));
        el.style.setProperty("--spent", spent.toFixed(4));
      }
    };

    if (reduced) {
      // frozen freeze-frame: rows before "4" spent-dark, row 4 (index 3) at
      // peak flash, the rest still unfired-dim — the one frame that shows
      // all three states at once, which no point in the live loop pins down
      const frozenRow = Math.min(3, gridSize - 1);
      for (let r = 0; r < rowEls.length; r++) {
        const el = rowEls[r];
        if (!el) continue;
        if (r < frozenRow) {
          el.style.setProperty("--fire", "0");
          el.style.setProperty("--spent", "1");
        } else if (r === frozenRow) {
          el.style.setProperty("--fire", "1");
          el.style.setProperty("--spent", "0");
        } else {
          el.style.setProperty("--fire", "0");
          el.style.setProperty("--spent", "0");
        }
      }
      return;
    }

    let raf = 0;
    let visible = true;
    const start = performance.now() - START_PHASE_MS;

    const loop = (now: number) => {
      if (visible) {
        const phase = (now - start) % cycleMs;
        paint(phase < 0 ? phase + cycleMs : phase);
      }
      raf = requestAnimationFrame(loop);
    };

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
      },
      { threshold: 0 }
    );
    const root = rootRef.current;
    if (root) io.observe(root);

    raf = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
    };
  }, [gridSize]);

  const cells = Array.from({ length: gridSize });

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={ariaLabel}
      className={`relative flex items-center justify-center overflow-hidden bg-background p-[6%] ${className}`}
    >
      <style>{`
.ns-bhds-grid{
  display: grid;
  gap: 12%;
  width: 100%;
  height: 100%;
  aspect-ratio: 1 / 1;
  max-width: 100%;
  max-height: 100%;
}
.ns-bhds-row{
  display: contents;
}
.ns-bhds-cell{
  position: relative;
  border-radius: 999px;
  background-color: color-mix(
    in oklch,
    var(--ns-muted),
    var(--foreground) calc(var(--fire, 0) * 100%)
  );
  filter: brightness(calc(1 - var(--spent, 0) * ${1 - SPENT_BRIGHTNESS_FLOOR}));
  box-shadow: 0 0 calc(var(--fire, 0) * 18%)
    color-mix(in srgb, var(--foreground) calc(var(--fire, 0) * 60%), transparent);
  transition: filter 60ms linear;
}
.ns-bhds-cell::after{
  content: "";
  position: absolute;
  inset: 22%;
  border-radius: 999px;
  background: color-mix(in srgb, var(--background) calc(38% - var(--fire, 0) * 30%), transparent);
}
`}</style>
      <div
        className="ns-bhds-grid"
        style={{ gridTemplateColumns: `repeat(${gridSize}, 1fr)`, gridTemplateRows: `repeat(${gridSize}, 1fr)` }}
      >
        {cells.map((_, r) => (
          <div
            key={r}
            ref={(el) => {
              rowRefs.current[r] = el;
            }}
            className="ns-bhds-row"
            style={{ gridRow: r + 1 }}
          >
            {cells.map((__, c) => (
              <div key={c} className="ns-bhds-cell" style={{ gridRow: r + 1, gridColumn: c + 1 }} />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// WipBoard — a kanban board whose column frames are real box-drawing glyphs.
// Each column header reads `┌─ In Progress ───── 3/3 ─┐`; when the card count
// exceeds the limit the counter gains a `▲1` suffix and the whole frame
// switches from the resting muted ink to the accent token. Dragging a card
// renders a ╌╌╌╌ placeholder at the live insertion point and drives the TARGET
// column's counter with the PREDICTED count while the card is still in the air.
// Over-limit drops are allowed: a WIP limit is a policy signal, not a lock, and
// `onOverLimit` lets the consumer decide. Plain React state, no rAF loop and no
// canvas; the only motion is a 120ms FLIP transform on card reflow, skipped
// entirely under prefers-reduced-motion.
// ---------------------------------------------------------------------------

export interface WipCard {
  id: string;
  /** short issue key rendered at the head of the row, e.g. "ATL-214" */
  ref?: string;
  title: string;
  /** right-aligned trailing note: assignee, age, review count */
  meta?: string;
}

export interface WipColumn {
  id: string;
  title: string;
  /** the column's WIP limit — the denominator of the header counter */
  limit: number;
  cards: WipCard[];
}

export interface WipBoardProps {
  /** the board's columns, each with its own WIP limit */
  columns: WipColumn[];
  /** column width in monospace character cells (the frame tiles to exactly this) */
  width?: number;
  /** fires on every committed move, pointer or keyboard */
  onChange?: (columns: WipColumn[]) => void;
  /** fires per commit for the receiving column: `over` is count - limit, 0 when within policy */
  onOverLimit?: (columnId: string, over: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the board */
  "aria-label"?: string;
}

const DRAG_THRESHOLD = 4; // px of travel before a pointerdown becomes a live drag
const REFLOW_MS = 120;
const DASH = "╌";
// the resting frame ink. NOT `text-border` — --border is tuned for 1px
// hairlines and is invisible as type on the light theme (#ebebeb on #ffffff),
// which would leave the box-drawing frame — the whole point of the component —
// blank at rest. A muted tint reads in both themes and still sits below the
// card text in the hierarchy.
const FRAME_INK = "text-ns-muted/55";

/** `┌─ In Progress ───────── 3/3 ─┐` — exactly `width` characters wide. */
function headerLine(title: string, count: number, limit: number, width: number) {
  const over = Math.max(0, count - limit);
  const label = over > 0 ? `${count}/${limit} ▲${over}` : `${count}/${limit}`;
  const rule = "─".repeat(Math.max(1, width - 8 - title.length - label.length));
  return `┌─ ${title} ${rule} ${label} ─┐`;
}

function moveCard(
  cols: WipColumn[],
  cardId: string,
  toColId: string,
  toIndex: number
): WipColumn[] {
  let card: WipCard | undefined;
  const stripped = cols.map((c) => {
    const found = c.cards.find((x) => x.id === cardId);
    if (!found) return c;
    card = found;
    return { ...c, cards: c.cards.filter((x) => x.id !== cardId) };
  });
  if (!card) return cols;
  const picked = card;
  return stripped.map((c) => {
    if (c.id !== toColId) return c;
    const i = Math.min(c.cards.length, Math.max(0, toIndex));
    return { ...c, cards: [...c.cards.slice(0, i), picked, ...c.cards.slice(i)] };
  });
}

type Drop = { col: string; index: number };

type DragState = {
  id: string;
  fromCol: string;
  pointerId: number;
  offsetX: number;
  offsetY: number;
  startX: number;
  startY: number;
  active: boolean;
  width: number;
  /** column boxes cached at pickup — recomputing them mid-drag would chase the placeholder */
  colRects: { id: string; left: number; right: number }[];
  /** per-column card mid-Y cached at pickup, in committed order */
  cardMids: Map<string, { id: string; mid: number }[]>;
};

export function WipBoard({
  columns,
  width = 34,
  onChange,
  onOverLimit,
  className = "",
  "aria-label": ariaLabel = "Kanban board with WIP limits",
}: WipBoardProps) {
  const [cols, setCols] = useState<WipColumn[]>(columns);
  const [drop, setDrop] = useState<Drop | null>(null);
  const [dragId, setDragId] = useState<string | null>(null);
  const [liveMsg, setLiveMsg] = useState("");

  const colsRef = useRef(cols);
  colsRef.current = cols;
  const dragRef = useRef<DragState | null>(null);
  const dropRef = useRef<Drop | null>(null);
  dropRef.current = drop;

  const boardRef = useRef<HTMLDivElement>(null);
  const colEls = useRef<Map<string, HTMLDivElement>>(new Map());
  const cardEls = useRef<Map<string, HTMLButtonElement>>(new Map());
  const prevRects = useRef<Map<string, DOMRect>>(new Map());
  const focusNext = useRef<string | null>(null);
  const reducedRef = useRef(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      reducedRef.current = mq.matches;
    };
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // FLIP: cards live in normal flow, so a commit is measured before/after and
  // played back as one short transform. Never runs mid-drag (the lifted card is
  // position:fixed and its neighbours have already collapsed) or under
  // reduced motion, where the reflow is simply instant.
  useLayoutEffect(() => {
    const next = new Map<string, DOMRect>();
    cardEls.current.forEach((el, id) => next.set(id, el.getBoundingClientRect()));
    if (!reducedRef.current && !dragRef.current) {
      next.forEach((r, id) => {
        const p = prevRects.current.get(id);
        const el = cardEls.current.get(id);
        if (!p || !el) return;
        const dx = p.left - r.left;
        const dy = p.top - r.top;
        if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) return;
        el.style.transition = "none";
        el.style.transform = `translate3d(${dx.toFixed(1)}px, ${dy.toFixed(1)}px, 0)`;
        requestAnimationFrame(() => {
          if (!el.isConnected) return;
          el.style.transition = `transform ${REFLOW_MS}ms cubic-bezier(0.2, 0, 0, 1)`;
          el.style.transform = "";
        });
      });
    }
    prevRects.current = next;
  });

  useEffect(() => {
    const id = focusNext.current;
    if (!id) return;
    focusNext.current = null;
    cardEls.current.get(id)?.focus();
  }, [cols]);

  const announce = useCallback(
    (card: WipCard, next: WipColumn[], toColId: string) => {
      const col = next.find((c) => c.id === toColId);
      if (!col) return;
      const count = col.cards.length;
      const over = Math.max(0, count - col.limit);
      setLiveMsg(
        `Moved ${card.title} to ${col.title}. ${count} of ${col.limit}` +
          (over > 0 ? `, over limit by ${over}.` : ", within limit.")
      );
      onOverLimit?.(col.id, over);
    },
    [onOverLimit]
  );

  const commit = useCallback(
    (cardId: string, toColId: string, toIndex: number, refocus: boolean) => {
      const prev = colsRef.current;
      const card = prev.flatMap((c) => c.cards).find((x) => x.id === cardId);
      const next = moveCard(prev, cardId, toColId, toIndex);
      setCols(next);
      onChange?.(next);
      if (card) announce(card, next, toColId);
      if (refocus) focusNext.current = cardId;
    },
    [announce, onChange]
  );

  const liftEnd = useCallback((id: string) => {
    const el = cardEls.current.get(id);
    if (!el) return;
    el.style.position = "";
    el.style.left = "";
    el.style.top = "";
    el.style.width = "";
    el.style.zIndex = "";
    el.style.transition = "";
    el.style.transform = "";
  }, []);

  // Move/up live on the document, not on the card. A real pointer would be
  // retargeted to the card by its own pointer capture, but the preview driver
  // dispatches synthetic events to whatever it hit-tests under the cursor — so
  // a card-scoped handler goes silent the moment the pointer crosses into
  // another column. Document listeners receive both, and the drag survives.
  const moveHandler = useRef<((e: PointerEvent) => void) | null>(null);
  const upHandler = useRef<((e: PointerEvent) => void) | null>(null);

  const detach = useCallback(() => {
    if (moveHandler.current) document.removeEventListener("pointermove", moveHandler.current);
    if (upHandler.current) {
      document.removeEventListener("pointerup", upHandler.current);
      document.removeEventListener("pointercancel", upHandler.current);
    }
    moveHandler.current = null;
    upHandler.current = null;
  }, []);

  const cancelDrag = useCallback(() => {
    detach();
    const d = dragRef.current;
    if (!d) return;
    dragRef.current = null;
    // Escape ends the drag with no pointerup coming, so the capture the card
    // took on pointerdown has to be handed back explicitly or the card keeps
    // swallowing the pointer stream until the button is physically released.
    const el = cardEls.current.get(d.id);
    if (el?.hasPointerCapture(d.pointerId)) el.releasePointerCapture(d.pointerId);
    if (d.active) liftEnd(d.id);
    setDragId(null);
    setDrop(null);
  }, [detach, liftEnd]);

  const handleMove = useCallback((e: PointerEvent) => {
    const d = dragRef.current;
    if (!d || d.pointerId !== e.pointerId) return;
    const el = cardEls.current.get(d.id);
    if (!el) return;

    if (!d.active) {
      const moved = Math.hypot(e.clientX - d.startX, e.clientY - d.startY);
      if (moved <= DRAG_THRESHOLD) return;
      d.active = true;
      el.style.transition = "none";
      el.style.transform = "";
      el.style.position = "fixed";
      el.style.width = `${d.width}px`;
      el.style.zIndex = "30";
      setDragId(d.id);
    }

    el.style.left = `${e.clientX - d.offsetX}px`;
    el.style.top = `${e.clientY - d.offsetY}px`;

    // target column: the box the pointer is inside, else the nearest edge
    let colId = d.colRects[0]?.id ?? d.fromCol;
    let best = Infinity;
    for (const c of d.colRects) {
      const dist = e.clientX < c.left ? c.left - e.clientX : e.clientX > c.right ? e.clientX - c.right : 0;
      if (dist < best) {
        best = dist;
        colId = c.id;
      }
    }
    const mids = (d.cardMids.get(colId) ?? []).filter((m) => m.id !== d.id);
    let index = 0;
    while (index < mids.length && mids[index].mid < e.clientY) index++;

    const cur = dropRef.current;
    if (!cur || cur.col !== colId || cur.index !== index) setDrop({ col: colId, index });
  }, []);

  const handleUp = useCallback(
    (e: PointerEvent) => {
      const d = dragRef.current;
      if (!d || d.pointerId !== e.pointerId) return;
      detach();
      const card = cardEls.current.get(d.id);
      if (card?.hasPointerCapture(e.pointerId)) card.releasePointerCapture(e.pointerId);
      const target = dropRef.current;
      const wasActive = d.active;
      dragRef.current = null;
      if (wasActive) liftEnd(d.id);
      setDragId(null);
      setDrop(null);
      if (wasActive && target && e.type !== "pointercancel") {
        commit(d.id, target.col, target.index, false);
      }
    },
    [commit, detach, liftEnd]
  );

  const onPointerDown = useCallback(
    (cardId: string, colId: string, e: ReactPointerEvent<HTMLButtonElement>) => {
      const board = boardRef.current;
      if (!board || e.button !== 0) return;
      const rect = e.currentTarget.getBoundingClientRect();
      e.currentTarget.setPointerCapture(e.pointerId);

      const colRects = colsRef.current.map((c) => {
        const el = colEls.current.get(c.id);
        const r = el?.getBoundingClientRect();
        return { id: c.id, left: r?.left ?? 0, right: r?.right ?? 0 };
      });
      const cardMids = new Map<string, { id: string; mid: number }[]>();
      for (const c of colsRef.current) {
        cardMids.set(
          c.id,
          c.cards.map((card) => {
            const r = cardEls.current.get(card.id)?.getBoundingClientRect();
            return { id: card.id, mid: r ? r.top + r.height / 2 : 0 };
          })
        );
      }

      dragRef.current = {
        id: cardId,
        fromCol: colId,
        pointerId: e.pointerId,
        offsetX: e.clientX - rect.left,
        offsetY: e.clientY - rect.top,
        startX: e.clientX,
        startY: e.clientY,
        active: false,
        width: rect.width,
        colRects,
        cardMids,
      };

      detach();
      moveHandler.current = handleMove;
      upHandler.current = handleUp;
      document.addEventListener("pointermove", handleMove);
      document.addEventListener("pointerup", handleUp);
      document.addEventListener("pointercancel", handleUp);
    },
    [detach, handleMove, handleUp]
  );

  // a drag can outlive the component (unmount mid-flight); never leave the
  // document listening to a handler whose state is gone
  useEffect(() => detach, [detach]);

  // Escape is a document listener, not a key handler on the card: the drag is
  // in flight regardless of where focus happens to sit.
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape" && dragRef.current) cancelDrag();
    }
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [cancelDrag]);

  const onCardKeyDown = useCallback(
    (cardId: string, colId: string, e: ReactKeyboardEvent<HTMLButtonElement>) => {
      const cur = colsRef.current;
      const ci = cur.findIndex((c) => c.id === colId);
      if (ci < 0) return;
      const idx = cur[ci].cards.findIndex((x) => x.id === cardId);
      if (idx < 0) return;

      if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
        const to = ci + (e.key === "ArrowLeft" ? -1 : 1);
        if (to < 0 || to >= cur.length) return;
        e.preventDefault();
        commit(cardId, cur[to].id, Math.min(idx, cur[to].cards.length), true);
        return;
      }
      if (e.key === "ArrowUp" || e.key === "ArrowDown") {
        const to = idx + (e.key === "ArrowUp" ? -1 : 1);
        if (to < 0 || to >= cur[ci].cards.length) return;
        e.preventDefault();
        commit(cardId, colId, to, true);
      }
    },
    [commit]
  );

  const rowCount = Math.max(1, ...cols.map((c) => c.cards.length)) + 1;
  const blank = `│${" ".repeat(Math.max(0, width - 2))}│`;
  const footer = `└${"─".repeat(Math.max(0, width - 2))}┘`;

  return (
    <div
      ref={boardRef}
      data-board
      role="group"
      aria-label={ariaLabel}
      className={`flex select-none items-start gap-3 font-mono text-xs leading-[1.7] ${className}`}
    >
      <div aria-live="polite" role="status" className="sr-only">
        {liveMsg}
      </div>

      {cols.map((col) => {
        const isSource = dragId != null && col.cards.some((c) => c.id === dragId);
        const isTarget = drop?.col === col.id;
        // the predicted count: the lifted card has already left its source
        // column and is already counted by whichever column it is over
        const count = col.cards.length - (isSource ? 1 : 0) + (isTarget ? 1 : 0);
        const over = Math.max(0, count - col.limit);
        const rows: ReactNode[] = [];
        const placeholder = (
          <div key="ph" className="flex whitespace-pre text-ns-accent">
            <span aria-hidden>│</span>
            <span aria-hidden className="min-w-0 flex-1 overflow-hidden px-1">
              {DASH.repeat(Math.max(0, width - 4))}
            </span>
            <span aria-hidden>│</span>
          </div>
        );
        // `slot` counts only the rows that actually occupy space: the lifted
        // card is position:fixed, so it stays in the DOM (its pointer capture
        // depends on it) but its slot has already collapsed.
        let slot = 0;
        let placed = false;

        col.cards.forEach((card, i) => {
          if (isTarget && drop && !placed && slot === drop.index) {
            rows.push(placeholder);
            placed = true;
          }
          if (card.id !== dragId) slot++;
          rows.push(
            // the lifted card is position:fixed, so its row must stop occupying
            // a line too — otherwise the source column stands one row taller
            // than its neighbours and the footers stop aligning mid-drag.
            // `overflow-hidden` here cannot clip the card: no ancestor is
            // transformed, so a fixed descendant escapes this box.
            <div
              key={card.id}
              className={`flex whitespace-pre ${dragId === card.id ? "h-0 overflow-hidden" : ""}`}
            >
              <span aria-hidden>│</span>
              <button
                type="button"
                ref={(el) => {
                  if (el) cardEls.current.set(card.id, el);
                  else cardEls.current.delete(card.id);
                }}
                data-card={card.id}
                aria-label={`${card.title}${card.ref ? `, ${card.ref}` : ""}. ${col.title}, position ${
                  i + 1
                } of ${col.cards.length}, column at ${col.cards.length} of ${col.limit}. Arrow keys move and reorder.`}
                onPointerDown={(e) => onPointerDown(card.id, col.id, e)}
                onKeyDown={(e) => onCardKeyDown(card.id, col.id, e)}
                className={`flex min-w-0 flex-1 cursor-grab touch-none items-baseline gap-2 rounded-sm px-1 text-left text-ns-muted transition-colors duration-150 hover:bg-surface hover:text-foreground focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent active:cursor-grabbing ${
                  dragId === card.id ? "bg-surface text-foreground" : ""
                }`}
              >
                {card.ref ? <span className="shrink-0 opacity-60">{card.ref}</span> : null}
                <span className="min-w-0 flex-1 truncate">{card.title}</span>
                {card.meta ? <span className="shrink-0 opacity-60">{card.meta}</span> : null}
              </button>
              <span aria-hidden>│</span>
            </div>
          );
        });

        // insertion past the last card
        if (isTarget && drop && !placed) {
          rows.push(placeholder);
          placed = true;
        }

        const occupied = slot + (placed ? 1 : 0);
        for (let i = occupied; i < rowCount; i++) {
          rows.push(
            <div key={`b${i}`} aria-hidden className="whitespace-pre">
              {blank}
            </div>
          );
        }

        return (
          <div
            key={col.id}
            ref={(el) => {
              if (el) colEls.current.set(col.id, el);
              else colEls.current.delete(col.id);
            }}
            data-column={col.id}
            data-over={over > 0 ? "true" : undefined}
            role="group"
            aria-label={`${col.title}, ${col.cards.length} of ${col.limit}${
              col.cards.length > col.limit ? `, over limit by ${col.cards.length - col.limit}` : ""
            }`}
            style={{ width: `${width}ch` }}
            className={`shrink-0 transition-colors duration-150 ${over > 0 ? "text-ns-accent" : FRAME_INK}`}
          >
            <div className="whitespace-pre" aria-hidden>
              {headerLine(col.title, count, col.limit, width)}
            </div>
            <div aria-hidden className="whitespace-pre">
              {blank}
            </div>
            {rows}
            <div className="whitespace-pre" aria-hidden>
              {footer}
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// BobbinLacePricking — a decorative divider/empty-state motif: a narrow
// WORKING BAND of pins works its way down a pricked grid, twisting a pair of
// threads into a locked X at each active pin, while pins two rows behind the
// band are pulled free once their crossing has secured into the growing lace
// ground. Source: bobbin lace (pillow/pricking) construction.
//
// The load-bearing, uncontested part of this mechanic (per spec) is that a
// pin is a TEMPORARY fixture — placed, used, then physically removed as work
// progresses — which is what separates it from every other lattice/mesh
// sibling in the registry (mesh-lash, seep-lattice, pin-register): none of
// those remove a placed element as the pattern advances.
//
// TIMELINE (one continuous clock, no per-pin React state):
//   continuousRow = elapsedMs / ROW_INTERVAL   (smooth fractional row depth)
//   currentRow    = floor(continuousRow)        (the row being actively worked)
//   rowElapsedMs  = fractional part * ROW_INTERVAL
//
// Every row is classified purely by `age = currentRow - rowIndex`:
//   age < 0   not yet reached      -> border-token pricking dot only
//   age == 0  actively crossing    -> pin dot + a per-column-batch twist
//                                     animation (3 batches, 700ms apart,
//                                     850ms twist each, mirroring "3 pins/
//                                     row roughly staggered 700ms" scaled to
//                                     any column count via `col % 3`)
//   age == 1  just secured         -> pin dot + locked X, full strength,
//                                     static (already crossed, not yet pulled)
//   age == 2  pull row             -> exactly one column (cycling every
//                                     interval) animates its pin sliding out
//                                     + fading over 180ms while its locked X
//                                     stays put; every other column in the
//                                     row still shows a plain locked X + dot
//   age >= 3  finished ground      -> locked X only, no pin dot (already
//                                     pulled), rendered at low-moderate
//                                     opacity, never re-animated
//
// Exactly one row has age===2 at any instant, so exactly one pull event is
// ever in flight — the single, unmistakable "old pin behind the band" cue
// the spec names as the ONE thing to follow, on a ~2.6s cadence well above
// the ~1s legibility floor.
//
// The whole field scrolls continuously (band pinned at a fixed screen
// fraction, rows drift upward under it), so the loop never simply stops —
// new pricking keeps entering from the bottom, matching the spec's
// unbounded-scrolling-field option.
// ---------------------------------------------------------------------------

const ROW_INTERVAL_MS = 2600; // one full working-band row advance
const CROSS_MS = 850; // per-pin twist-and-lock duration
const BATCH_STAGGER_MS = 700; // stagger between the 3 within-row batches
const PULL_MS = 180; // pin slide-out + fade duration
const BAND_Y_FRAC = 1 / 3; // active row's screen position, fraction of height
const MIN_PITCH = 12;
const MAX_PITCH = 20;
const TARGET_PINS_ACROSS = 10; // used to derive pitch from the smaller dimension
const FINISHED_ALPHA = 0.38; // low-moderate opacity for set lace ground
const CROSS_HALF_LEN = 0.42; // fraction of pitch, half-length of each thread stroke
const STATIC_ROW = 3; // reduced-motion: currentRow at freeze
const STATIC_ROW_ELAPSED = 375; // ms into that row -> mid-cross on batch 0

function easeOutCubic(x: number): number {
  const t = 1 - x;
  return 1 - t * t * t;
}

export interface BobbinLacePrickingProps {
  className?: string;
}

export function BobbinLacePricking({ className = "" }: BobbinLacePrickingProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "currentColor";
    let border = "currentColor";
    let width = 0;
    let height = 0;
    let dpr = 1;
    let sized = false;
    let disposed = false;
    let visible = true;

    let pitch = 16;
    let cols = 0;
    let bandScreenY = 0;

    const readTokens = () => {
      const s = getComputedStyle(document.documentElement);
      fg = s.getPropertyValue("--foreground").trim() || "currentColor";
      border = s.getPropertyValue("--border").trim() || fg;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const smaller = Math.min(width, height);
      pitch = Math.min(MAX_PITCH, Math.max(MIN_PITCH, smaller / TARGET_PINS_ACROSS));
      cols = Math.max(2, Math.floor(width / pitch));
      bandScreenY = height * BAND_Y_FRAC;
      sized = true;
    };

    // Two strokes rotating from parallel (theta=0) to a locked X (theta=45deg)
    // around (cx, cy), eased. `full` (age>=1) draws the settled X directly.
    const drawTwist = (cx: number, cy: number, progress: number, alpha: number) => {
      const eased = easeOutCubic(Math.min(1, Math.max(0, progress)));
      const theta = (eased * 45 * Math.PI) / 180;
      const len = pitch * CROSS_HALF_LEN;
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = fg;
      ctx.lineWidth = 1;
      ctx.lineCap = "round";
      // thread A: rotates clockwise from vertical
      ctx.beginPath();
      ctx.moveTo(cx - Math.sin(theta) * len, cy - Math.cos(theta) * len);
      ctx.lineTo(cx + Math.sin(theta) * len, cy + Math.cos(theta) * len);
      ctx.stroke();
      // thread B: rotates counter-clockwise from vertical
      ctx.beginPath();
      ctx.moveTo(cx + Math.sin(theta) * len, cy - Math.cos(theta) * len);
      ctx.lineTo(cx - Math.sin(theta) * len, cy + Math.cos(theta) * len);
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    const drawPinDot = (cx: number, cy: number, alpha: number, radius: number) => {
      ctx.globalAlpha = alpha;
      ctx.fillStyle = fg;
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    };

    const drawHole = (cx: number, cy: number) => {
      ctx.globalAlpha = 1;
      ctx.fillStyle = border;
      ctx.beginPath();
      ctx.arc(cx, cy, 1, 0, Math.PI * 2);
      ctx.fill();
    };

    const drawField = (continuousRow: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);

      const currentRow = Math.floor(continuousRow);
      const rowElapsedMs = (continuousRow - currentRow) * ROW_INTERVAL_MS;
      const pullCol = ((currentRow % cols) + cols) % cols;
      const pullProgress = Math.min(1, Math.max(0, rowElapsedMs / PULL_MS));

      const minRow = Math.floor(continuousRow + (0 - bandScreenY) / pitch) - 1;
      const maxRow = Math.ceil(continuousRow + (height - bandScreenY) / pitch) + 1;

      for (let rowIndex = Math.max(0, minRow); rowIndex <= maxRow; rowIndex++) {
        const age = currentRow - rowIndex;
        const cy = bandScreenY + (rowIndex - continuousRow) * pitch;
        const xOffset = (rowIndex % 2) * (pitch / 2);

        for (let col = 0; col < cols; col++) {
          const cx = xOffset + col * pitch + pitch / 2;
          if (cx > width + pitch) continue;

          if (age < 0) {
            drawHole(cx, cy);
            continue;
          }

          if (age === 0) {
            const batch = col % 3;
            const batchStart = batch * BATCH_STAGGER_MS;
            const localProgress = (rowElapsedMs - batchStart) / CROSS_MS;
            if (localProgress <= 0) {
              drawPinDot(cx, cy, 1, 1.5);
            } else {
              drawTwist(cx, cy, localProgress, 1);
              drawPinDot(cx, cy, 1, 1.5);
            }
            continue;
          }

          if (age === 1) {
            drawTwist(cx, cy, 1, 1);
            drawPinDot(cx, cy, 1, 1.5);
            continue;
          }

          if (age === 2) {
            drawTwist(cx, cy, 1, 1);
            if (col === pullCol) {
              const slideY = -6 * easeOutCubic(pullProgress);
              const dotAlpha = 1 - pullProgress;
              if (dotAlpha > 0.01) drawPinDot(cx, cy + slideY, dotAlpha, 1.5);
            } else {
              drawPinDot(cx, cy, 1, 1.5);
            }
            continue;
          }

          // age >= 3: finished ground, pin long since pulled
          drawTwist(cx, cy, 1, FINISHED_ALPHA);
        }
      }
    };

    let raf = 0;
    let startTime = 0;

    const loop = (now: number) => {
      if (!startTime) startTime = now;
      const continuousRow = (now - startTime) / ROW_INTERVAL_MS;
      drawField(continuousRow);
      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };

    const drawReducedStatic = () => {
      const continuousRow = STATIC_ROW + STATIC_ROW_ELAPSED / ROW_INTERVAL_MS;
      drawField(continuousRow);
    };

    const start = () => {
      if (reduced) {
        drawReducedStatic();
        return;
      }
      startTime = 0;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(loop);
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) drawReducedStatic();
      }, 120);
    };

    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible && !reduced) start();
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      if (!document.hidden && visible && !reduced) start();
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced && sized) drawReducedStatic();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    readTokens();
    resize();
    start();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      void disposed;
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className={`block h-full w-full ${className}`}
    />
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// BombeDrumHalt — a search/lookup loading indicator built as the Bombe's
// drum-and-stop search cycle: banks of rotating drums spin continuously
// through a hypothesis space; a sensing relay bank tests each position as
// the drums pass it, and when a candidate briefly satisfies the test the
// whole bank locks dead for a beat (a diagonal-board-style check running
// against it) before releasing and resuming — almost every stop a false
// positive. Sourced from the drum-and-stop search cycle itself, not the
// electrical/plugboard logic the real machine tested.
//
// Four vertical drum columns, each an overflow:hidden window over a
// repeating tick-mark strip. The strip is NOT a uniform 1-tick gradient —
// a uniform pattern repeats every single tick, which makes a drum's visible
// state alias back to itself dozens of times a second and leaves t0/2.5s/5s
// screenshots indistinguishable whenever no halt happens to be mid-flight.
// Instead each drum's strip is one 26-position revolution (one per rotor
// letter, historically the right count for a Bombe drum): every 5th
// position is a heavier tick and position 0 is a distinct brighter datum
// mark, so a screenshot of a drum's resting phase is legible and never
// repeats for ~2s of continuous scan.
//
// All four columns share ONE driving clock (a single rAF loop tracking one
// `phase` state machine: scan -> decel -> hold -> reaccel -> scan) rather
// than four independent CSS animation timelines, specifically so a halt can
// pause that clock precisely instead of fighting four separately-running
// loops back into sync. Each drum's on-screen offset is (accumulated
// scroll px) mod (one full 26-tick revolution); the per-drum phase stagger
// (drum N reads N*0.6s "ahead") is nothing more than a different starting
// offset on that same shared clock, so the drums never need independent
// timers to stay out of lock-step.
//
// A halt is scheduled 4-6s out (re-rolled after every resume, never a fixed
// metronome). Decel eases speed 1 -> 0 over 180ms while the sensing bar
// brightens from its idle 20% opacity toward peak; hold hangs at zero
// velocity for 900ms at 90% bar opacity (the "check running" beat); reaccel
// eases 0 -> 1 back over 220ms as the bar dims back to idle. On 15% of
// resumes a single randomly-chosen drum gets a 40%-opacity outline ring at
// the sensing line (where its current tick mark sits under test) for one
// extra 600ms after motion resumes — a rarer "this one got a second look"
// variant that still resolves and never latches.
//
// prefers-reduced-motion renders the single most-structured frame directly
// (no rAF loop at all): drums stopped at their phase-staggered rest
// offsets, sensing bar at peak 90% opacity — the mid-hold instant, not a
// mid-scroll blur.
// ---------------------------------------------------------------------------

// Rendered scan speed is a decoupled rate, not the historical one: the real
// Bombe tested on the order of hundreds of rotor-hypotheses/s, far above
// anything that reads as motion (rather than noise/strobe) on a 60Hz
// screen. 180px/s here is a visually smooth continuous scroll — roughly 13
// tick-marks/s at the default tick spacing — chosen the same way round-9's
// rate-decoupling rule chose a slow sweep over a literal 180marks/s
// (2520px/s), which would alias against 60Hz paint exactly like the strobe
// bug that rule was written for.
const SCROLL_SPEED_PX_S = 180;
const STRIP_TICKS = 26; // one revolution = 26 rotor-letter positions
const DRUM_COUNT = 4;
const PHASE_STEP_S = 0.6; // drum N starts N*0.6s "ahead" of drum 0
const HALT_MIN_S = 4;
const HALT_MAX_S = 6;
const DECEL_MS = 180;
const HOLD_MS = 900;
const REACCEL_MS = 220;
const RING_CHANCE = 0.15;
const RING_MS = 600;
const SENSING_BAR_Y_RATIO = 0.42; // fixed height across drums, fraction of drum height
const BAR_IDLE_OPACITY = 0.2;
const BAR_PEAK_OPACITY = 0.9;

type Phase = "scan" | "decel" | "hold" | "reaccel";

function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

interface Tick {
  top: number;
  height: number;
  opacity: number;
}

/** Builds `repeats` back-to-back 26-position revolutions of tick marks —
 * a datum mark every 26th position, a heavier mark every 5th, a plain tick
 * otherwise — so the drum window always has enough rendered strip above
 * and below the visible offset range to cover a full modulo sweep. */
function buildTicks(tickPeriod: number, repeats: number): Tick[] {
  const ticks: Tick[] = [];
  const total = STRIP_TICKS * repeats;
  for (let i = 0; i < total; i++) {
    const pos = i % STRIP_TICKS;
    const isDatum = pos === 0;
    const isHeavy = pos % 5 === 0;
    ticks.push({
      top: i * tickPeriod,
      height: isDatum ? tickPeriod * 0.32 : isHeavy ? tickPeriod * 0.22 : tickPeriod * 0.14,
      opacity: isDatum ? 0.9 : isHeavy ? 0.68 : 0.45,
    });
  }
  return ticks;
}

export interface BombeDrumHaltProps {
  /** accessible label for the ambient search/loading status */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BombeDrumHalt({ label = "Searching", className = "" }: BombeDrumHaltProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const drumRefs = useRef<(HTMLDivElement | null)[]>([]);
  const ringRefs = useRef<(HTMLDivElement | null)[]>([]);
  const barRef = useRef<HTMLDivElement>(null);
  const [smaller, setSmaller] = useState(0);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const { width, height } = entry.contentRect;
      setSmaller(Math.min(width, height));
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  // Geometry derives from the container's smaller dimension so the
  // component reads at card scale regardless of aspect ratio.
  const drumWidth = smaller > 0 ? smaller / 9 : 0;
  const drumHeight = smaller > 0 ? smaller * 0.85 : 0;
  const tickPeriod = drumHeight > 0 ? Math.max(4, drumHeight / 45) : 4;
  const stripLength = STRIP_TICKS * tickPeriod;
  const repeats = drumHeight > 0 ? Math.max(3, Math.ceil((drumHeight + stripLength) / stripLength) + 1) : 3;
  const ticks = useMemo(
    () => (drumHeight > 0 ? buildTicks(tickPeriod, repeats) : []),
    [tickPeriod, repeats, drumHeight]
  );

  useEffect(() => {
    if (drumWidth <= 0 || drumHeight <= 0) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // accumulated scroll offset per drum, px, seeded by the phase stagger
    const positions = Array.from(
      { length: DRUM_COUNT },
      (_, i) => i * PHASE_STEP_S * SCROLL_SPEED_PX_S
    );

    const applyDrumTransform = (i: number) => {
      const el = drumRefs.current[i];
      if (!el) return;
      const offset = ((positions[i] ?? 0) % stripLength + stripLength) % stripLength;
      el.style.transform = `translateY(${-offset}px)`;
    };

    const setBarOpacity = (v: number) => {
      const el = barRef.current;
      if (el) el.style.opacity = String(v);
    };

    const setRing = (drum: number, opacity: number) => {
      ringRefs.current.forEach((el, i) => {
        if (el) el.style.opacity = i === drum ? String(opacity) : "0";
      });
    };

    if (reduced) {
      // freeze on the mid-hold instant: drums stopped, bar at peak brightness
      positions.forEach((_, i) => applyDrumTransform(i));
      setBarOpacity(BAR_PEAK_OPACITY);
      setRing(-1, 0);
      return;
    }

    let raf = 0;
    let visible = true;
    let last = 0;
    let phase: Phase = "scan";
    let phaseStart = 0;
    let nextHaltAt = 0;
    let ringDrum = -1;
    let ringUntil = 0;

    const scheduleNextHalt = (now: number) => {
      nextHaltAt = now + (HALT_MIN_S + Math.random() * (HALT_MAX_S - HALT_MIN_S)) * 1000;
    };

    const advance = (dt: number, speedFactor: number) => {
      const delta = (SCROLL_SPEED_PX_S * speedFactor * dt) / 1000;
      for (let i = 0; i < positions.length; i++) {
        positions[i] = (positions[i] ?? 0) + delta;
      }
    };

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (!visible) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;

      if (phase === "scan") {
        if (nextHaltAt === 0) scheduleNextHalt(now);
        advance(dt, 1);
        if (ringDrum >= 0 && now >= ringUntil) {
          setRing(-1, 0);
          ringDrum = -1;
        }
        if (now >= nextHaltAt) {
          phase = "decel";
          phaseStart = now;
        }
      } else if (phase === "decel") {
        const t = Math.min(1, (now - phaseStart) / DECEL_MS);
        advance(dt, 1 - easeInOutCubic(t));
        setBarOpacity(BAR_IDLE_OPACITY + (BAR_PEAK_OPACITY - BAR_IDLE_OPACITY) * t);
        if (t >= 1) {
          phase = "hold";
          phaseStart = now;
        }
      } else if (phase === "hold") {
        const t = Math.min(1, (now - phaseStart) / HOLD_MS);
        setBarOpacity(BAR_PEAK_OPACITY);
        if (t >= 1) {
          phase = "reaccel";
          phaseStart = now;
        }
      } else if (phase === "reaccel") {
        const t = Math.min(1, (now - phaseStart) / REACCEL_MS);
        advance(dt, easeInOutCubic(t));
        setBarOpacity(BAR_PEAK_OPACITY - (BAR_PEAK_OPACITY - BAR_IDLE_OPACITY) * t);
        if (t >= 1) {
          phase = "scan";
          scheduleNextHalt(now);
          // false-positive resolve: 15% of halts leave a "second look" ring
          if (Math.random() < RING_CHANCE) {
            ringDrum = Math.floor(Math.random() * DRUM_COUNT);
            ringUntil = now + RING_MS;
            setRing(ringDrum, 0.4);
          }
        }
      }

      for (let i = 0; i < DRUM_COUNT; i++) applyDrumTransform(i);
    };

    raf = requestAnimationFrame(tick);

    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible) {
        last = 0; // resync elapsed-time base on resume
        // A halt frozen mid-flight while offscreen has a stale phaseStart;
        // rather than resolve decel/hold/reaccel in one jumped frame,
        // treat the away period as invalidating it and resume scanning.
        if (phase !== "scan") {
          phase = "scan";
          setBarOpacity(BAR_IDLE_OPACITY);
          setRing(-1, 0);
          ringDrum = -1;
        }
        scheduleNextHalt(performance.now());
      }
    });
    if (rootRef.current) io.observe(rootRef.current);

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
    };
  }, [drumWidth, drumHeight, stripLength]);

  const drums = useMemo(() => Array.from({ length: DRUM_COUNT }, (_, i) => i), []);
  const ringInset = Math.max(1, drumWidth * 0.1);

  return (
    <div
      ref={rootRef}
      role="status"
      aria-label={label}
      className={`relative flex h-full w-full min-h-[120px] items-center justify-center ${className}`}
    >
      <div className="relative flex items-stretch" style={{ gap: drumWidth * 0.35 }}>
        {drums.map((i) => (
          <div
            key={i}
            className="relative overflow-hidden"
            style={{
              width: drumWidth,
              height: drumHeight,
              borderLeft: i === 0 ? "none" : "1px solid var(--border)",
            }}
          >
            <div
              ref={(el) => {
                drumRefs.current[i] = el;
              }}
              className="absolute inset-x-0 top-0 will-change-transform"
              style={{ height: repeats * stripLength }}
            >
              {ticks.map((t, idx) => (
                <div
                  key={idx}
                  className="absolute inset-x-0"
                  style={{
                    top: t.top,
                    height: t.height,
                    background: "var(--foreground)",
                    opacity: t.opacity,
                  }}
                />
              ))}
            </div>
            <div
              ref={(el) => {
                ringRefs.current[i] = el;
              }}
              className="pointer-events-none absolute"
              style={{
                left: ringInset,
                right: ringInset,
                top: drumHeight * SENSING_BAR_Y_RATIO - tickPeriod / 2,
                height: tickPeriod,
                border: "1px solid var(--foreground)",
                borderRadius: 1,
                opacity: 0,
                transition: "opacity 200ms ease",
              }}
            />
          </div>
        ))}
        <div
          ref={barRef}
          className="pointer-events-none absolute left-0 right-0"
          style={{
            top: drumHeight * SENSING_BAR_Y_RATIO,
            height: 1,
            background: "var(--foreground)",
            opacity: BAR_IDLE_OPACITY,
          }}
        />
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// BowditchClose — a geofence/traverse editor built like a real closed survey
// traverse, not a stock "click a ring" polygon tool. Every corner you place
// is a leg; when you click back near the start the loop does NOT snap shut —
// that click becomes its own vertex (the point where your closing sight
// actually landed), and the gap between it and the true start is drawn as an
// --ns-accent hairline: the misclosure. Nothing is hidden or auto-corrected.
//
// The ONE governing scalar is the misclosure vector (dx, dy) between the
// closing vertex and vertex 0. Pressing "Balance traverse" runs the 1807
// Bowditch compass rule: each vertex i is corrected by
//   misclosure * (chainage_i / totalPerimeter)
// — chainage_i being the cumulative leg distance walked to reach it. Vertex 0
// (chainage 0) never moves; the closing vertex (chainage = totalPerimeter)
// gets the FULL misclosure and lands exactly on vertex 0, merging into it.
// Every vertex in between moves a fraction set by how much distance it
// carries — never equal-per-vertex, never all dumped on the last point. That
// gradation IS the falsifiable content of the rule: short first legs stay
// almost put, the long final leg absorbs most of the correction, because
// error is assumed proportional to distance run, not to vertex count.
//
// All corrections are pre-computed once (target_i = origin_i + correction_i)
// and then every vertex is driven by ONE shared spring scalar s: 0 -> 1
// (near-critically damped, one small overshoot), position_i = origin_i +
// (target_i - origin_i) * s. That is what makes it read as a drawstring
// pulling the whole ring taut at once, not one point jumping to close a gap.
//
// Distinct from stock polygon tools: this never silently teleports the last
// click onto the first. The gap is drawn, its precision graded live
// ("1:4300", Geist Mono) as a Bowditch survey report would, and closing it is
// an explicit, announced, undoable-until-pressed action. DOM + SVG + CSS
// only, tokens only, no canvas.
// ---------------------------------------------------------------------------

export interface BowditchPoint {
  x: number;
  y: number;
}

export interface BowditchCloseResult {
  ratio: number;
  areaHectares: number;
  perimeterMeters: number;
}

export interface BowditchCloseProps {
  /** vertices already placed, in local px coordinates */
  initialVertices?: BowditchPoint[];
  /** true when the last entry of initialVertices is already the misclosure/closing point */
  initialClosed?: boolean;
  /** canvas size in px */
  width?: number;
  height?: number;
  /** px per metre — governs the 1 m / 10 m nudge step and the area readout */
  pxPerMeter?: number;
  /** fires once, the moment Balance finishes */
  onBalance?: (result: BowditchCloseResult) => void;
  /** accessible label prefix for the drawing region */
  label?: string;
  className?: string;
}

type Phase = "drawing" | "unbalanced" | "balancing" | "balanced";

const CLOSE_RADIUS = 22; // px — how near vertex 0 a click must land to become the closing vertex
const VERTEX_R = 6; // 12px circle, visible dot size
const VERTEX_HIT_R = 12; // 24px invisible hit area, centered on the same point
const SPRING_K = 230;
const SPRING_ZETA = 0.9; // just under critical — one small overshoot, like a drawstring taking up the last of the slack
const SPRING_C = 2 * SPRING_ZETA * Math.sqrt(SPRING_K);
const REST_S = 0.01;
const REST_V = 0.015;

function dist(a: BowditchPoint, b: BowditchPoint) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function chainageOf(vs: BowditchPoint[]): number[] {
  const c = [0];
  for (let i = 1; i < vs.length; i++) c.push(c[i - 1] + dist(vs[i - 1], vs[i]));
  return c;
}

function shoelaceArea(vs: BowditchPoint[]): number {
  let s = 0;
  for (let i = 0; i < vs.length; i++) {
    const a = vs[i];
    const b = vs[(i + 1) % vs.length];
    s += a.x * b.y - b.x * a.y;
  }
  return Math.abs(s) / 2;
}

function pathFrom(vs: BowditchPoint[], close: boolean): string {
  if (vs.length === 0) return "";
  let d = `M ${vs[0].x.toFixed(2)} ${vs[0].y.toFixed(2)}`;
  for (let i = 1; i < vs.length; i++) d += ` L ${vs[i].x.toFixed(2)} ${vs[i].y.toFixed(2)}`;
  if (close) d += " Z";
  return d;
}

export function BowditchClose({
  initialVertices,
  initialClosed = false,
  width = 440,
  height = 300,
  pxPerMeter = 5,
  onBalance,
  label = "Geofence traverse",
  className = "",
}: BowditchCloseProps) {
  const uid = useId().replace(/[:]/g, "");

  const startPhase: Phase = initialClosed && (initialVertices?.length ?? 0) >= 4 ? "unbalanced" : "drawing";

  const [verts, setVerts] = useState<BowditchPoint[]>(() => initialVertices?.map((p) => ({ ...p })) ?? []);
  const [phase, setPhase] = useState<Phase>(startPhase);
  const [renderVerts, setRenderVerts] = useState<BowditchPoint[] | null>(null);
  const [frozenRatio, setFrozenRatio] = useState<number | null>(null);
  const [reducedGhost, setReducedGhost] = useState<BowditchPoint[] | null>(null);
  const [reduced, setReduced] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const vertexRefs = useRef<Map<number, HTMLButtonElement>>(new Map());
  const springRef = useRef<{
    raf: number;
    s: number;
    vel: number;
    origins: BowditchPoint[];
    targets: BowditchPoint[];
    lastT: number;
  } | null>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  useEffect(
    () => () => {
      if (springRef.current) cancelAnimationFrame(springRef.current.raf);
    },
    []
  );

  // pts is the single source both the ring/hairline drawing and the vertex
  // buttons read from — during the tween that is the interpolated frame,
  // otherwise it is the committed vertex list.
  const pts = phase === "balancing" && renderVerts ? renderVerts : verts;

  const chainage = useMemo(() => chainageOf(verts), [verts]);
  const totalRun = chainage[chainage.length - 1] ?? 0;
  const misclosureMag =
    phase !== "drawing" && verts.length > 0 ? dist(verts[0], verts[verts.length - 1]) : 0;
  const liveRatio = misclosureMag > 0 && totalRun > 0 ? totalRun / misclosureMag : null;
  const ratioToShow = phase === "balanced" || phase === "balancing" ? frozenRatio : liveRatio;

  const finalize = useCallback(
    (targets: BowditchPoint[], ratio: number) => {
      const closedRing = targets.slice(0, -1);
      const perimeterPx = chainageOf(targets)[targets.length - 1] ?? 0;
      const areaPx2 = shoelaceArea(closedRing);
      const perimeterMeters = perimeterPx / pxPerMeter;
      const areaHectares = areaPx2 / (pxPerMeter * pxPerMeter) / 10000;

      setVerts(closedRing);
      setPhase("balanced");
      setRenderVerts(null);
      springRef.current = null;
      onBalance?.({ ratio, areaHectares, perimeterMeters });

      // the closing vertex just merged into vertex 0 — if it (or anything
      // past the new end) held focus, land it on vertex 0 rather than losing
      // focus to the document.
      const active = document.activeElement;
      const stillMounted = active instanceof HTMLElement && containerRef.current?.contains(active);
      if (!stillMounted || (active && !closedRing.some((_, i) => vertexRefs.current.get(i) === active))) {
        vertexRefs.current.get(0)?.focus();
      }
    },
    [onBalance, pxPerMeter]
  );

  const runSpring = useCallback(
    (origins: BowditchPoint[], targets: BowditchPoint[], ratio: number) => {
      springRef.current = { raf: 0, s: 0, vel: 0, origins, targets, lastT: 0 };
      const tick = (now: number) => {
        const st = springRef.current;
        if (!st) return;
        const dt = st.lastT === 0 ? 1 / 60 : Math.min(0.032, (now - st.lastT) / 1000);
        st.lastT = now;
        const disp = st.s - 1;
        st.vel += (-SPRING_K * disp - SPRING_C * st.vel) * dt;
        st.s += st.vel * dt;
        const frame = st.origins.map((o, i) => ({
          x: o.x + (st.targets[i].x - o.x) * st.s,
          y: o.y + (st.targets[i].y - o.y) * st.s,
        }));
        setRenderVerts(frame);
        if (Math.abs(st.s - 1) < REST_S && Math.abs(st.vel) < REST_V) {
          finalize(st.targets, ratio);
          return;
        }
        st.raf = requestAnimationFrame(tick);
      };
      springRef.current.raf = requestAnimationFrame(tick);
    },
    [finalize]
  );

  const onBalancePress = useCallback(() => {
    if (phase !== "unbalanced") return;
    const n = verts.length - 1;
    const total = chainage[n] ?? 0;
    if (total <= 0 || liveRatio === null) return;
    const ratioAtClose = liveRatio;
    const misclosure = { dx: verts[0].x - verts[n].x, dy: verts[0].y - verts[n].y };
    const targets = verts.map((v, i) => ({
      x: v.x + misclosure.dx * (chainage[i] / total),
      y: v.y + misclosure.dy * (chainage[i] / total),
    }));
    setFrozenRatio(ratioAtClose);

    if (reduced) {
      setReducedGhost(verts.slice(0, -1));
      finalize(targets, ratioAtClose);
      return;
    }
    setPhase("balancing");
    runSpring(
      verts.map((v) => ({ ...v })),
      targets,
      ratioAtClose
    );
  }, [phase, verts, chainage, liveRatio, reduced, finalize, runSpring]);

  const onReset = useCallback(() => {
    if (springRef.current) cancelAnimationFrame(springRef.current.raf);
    springRef.current = null;
    setVerts([]);
    setPhase("drawing");
    setRenderVerts(null);
    setFrozenRatio(null);
    setReducedGhost(null);
  }, []);

  const localPoint = useCallback(
    (e: { clientX: number; clientY: number }): BowditchPoint => {
      const el = containerRef.current;
      if (!el) return { x: 0, y: 0 };
      const rect = el.getBoundingClientRect();
      const sx = width / rect.width;
      const sy = height / rect.height;
      return { x: (e.clientX - rect.left) * sx, y: (e.clientY - rect.top) * sy };
    },
    [width, height]
  );

  const onCanvasClick = useCallback(
    (e: React.MouseEvent) => {
      if (phase !== "drawing") return;
      const pt = localPoint(e);
      if (verts.length >= 3 && dist(pt, verts[0]) <= CLOSE_RADIUS) {
        setVerts([...verts, pt]);
        setPhase("unbalanced");
        return;
      }
      setVerts((vs) => [...vs, pt]);
    },
    [phase, verts, localPoint]
  );

  const onVertexKeyDown = useCallback(
    (i: number, e: React.KeyboardEvent) => {
      if (phase === "balancing") return;
      let dx = 0;
      let dy = 0;
      const step = (e.shiftKey ? 10 : 1) * pxPerMeter;
      if (e.key === "ArrowUp") dy = -step;
      else if (e.key === "ArrowDown") dy = step;
      else if (e.key === "ArrowLeft") dx = -step;
      else if (e.key === "ArrowRight") dx = step;
      else return;
      e.preventDefault();
      setVerts((vs) => vs.map((v, idx) => (idx === i ? { x: v.x + dx, y: v.y + dy } : v)));
    },
    [phase, pxPerMeter]
  );

  const closed = phase === "balanced";
  const showHairline = phase === "unbalanced" || phase === "balancing";
  const showCloseHint = phase === "drawing" && verts.length >= 3;
  const ringPath = pathFrom(pts, closed);
  const gapFrom = pts[pts.length - 1];
  const gapTo = pts[0];

  const areaHa = closed ? shoelaceArea(verts) / (pxPerMeter * pxPerMeter) / 10000 : null;

  const statusText =
    phase === "drawing"
      ? verts.length === 0
        ? "click to place the first corner"
        : `placing corners — ${verts.length} placed${showCloseHint ? ", click near the start to close" : ""}`
      : phase === "unbalanced"
        ? `traverse closed, 1:${ratioToShow ? Math.round(ratioToShow) : "—"} — balance to close the gap`
        : phase === "balancing"
          ? "balancing…"
          : `closed, 1:${ratioToShow ? Math.round(ratioToShow) : "—"}`;

  return (
    <div className={`flex w-full flex-col gap-3 ${className}`}>
      <div
        ref={containerRef}
        className="relative touch-none select-none rounded-md border border-border bg-background"
        style={{ width, height }}
        aria-label={label}
      >
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          aria-hidden
          className="absolute inset-0"
        >
          <defs>
            <pattern id={`${uid}-stipple`} x={0} y={0} width={8} height={8} patternUnits="userSpaceOnUse">
              <circle cx={2} cy={2} r={1} fill="var(--border)" />
            </pattern>
          </defs>

          {/* background click surface — pointer-only, placing a vertex has no
              natural keyboard equivalent; editing (arrow-key nudge) is fully
              keyboard operable below */}
          <rect
            x={0}
            y={0}
            width={width}
            height={height}
            fill="transparent"
            onClick={onCanvasClick}
            style={{ cursor: phase === "drawing" ? "crosshair" : "default" }}
          />

          {reducedGhost && closed ? (
            <path
              d={pathFrom(reducedGhost, false)}
              fill="none"
              stroke="var(--ns-muted)"
              strokeWidth={1}
              strokeDasharray="3 3"
            />
          ) : null}

          {showCloseHint ? (
            <circle
              cx={verts[0].x}
              cy={verts[0].y}
              r={CLOSE_RADIUS}
              fill="none"
              stroke="var(--ns-muted)"
              strokeWidth={1}
              strokeDasharray="2 3"
            />
          ) : null}

          {ringPath ? (
            <path
              d={ringPath}
              fill={closed ? `url(#${uid}-stipple)` : "none"}
              stroke="var(--border)"
              strokeWidth={1.5}
              strokeLinejoin="round"
            />
          ) : null}

          {showHairline && gapFrom && gapTo ? (
            <line
              x1={gapFrom.x}
              y1={gapFrom.y}
              x2={gapTo.x}
              y2={gapTo.y}
              stroke="var(--ns-accent)"
              strokeWidth={1.5}
            />
          ) : null}
        </svg>

        {/* pointer-events-none: this wrapper spans the full canvas so its
            children can be absolutely positioned at each vertex, but an
            empty positioned div still counts as a hit-test target for its
            whole box in Chrome/Safari even with nothing painted in it — left
            at the default (auto) it silently ate every click meant for the
            SVG's onCanvasClick rect underneath, so drawing-phase clicks never
            placed a vertex. Re-enabled per-button below. */}
        <div className="pointer-events-none absolute inset-0">
          {pts.map((p, i) => (
            <button
              key={i}
              ref={(el) => {
                if (el) vertexRefs.current.set(i, el);
                else vertexRefs.current.delete(i);
              }}
              type="button"
              disabled={phase === "balancing"}
              onKeyDown={(e) => onVertexKeyDown(i, e)}
              aria-label={`Vertex ${i + 1} of ${pts.length}${i === pts.length - 1 && phase === "unbalanced" ? ", misclosure point" : ""}`}
              className="group pointer-events-auto absolute flex items-center justify-center focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              style={{
                left: p.x - VERTEX_HIT_R,
                top: p.y - VERTEX_HIT_R,
                width: VERTEX_HIT_R * 2,
                height: VERTEX_HIT_R * 2,
              }}
            >
              {/* visible dot stays VERTEX_R; the button itself widens the hit
                  area to VERTEX_HIT_R without changing what's drawn */}
              <span
                aria-hidden
                className="rounded-full border border-border bg-background transition-colors duration-150 group-hover:border-ns-muted"
                style={{ width: VERTEX_R * 2, height: VERTEX_R * 2 }}
              />
            </button>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <button
            type="button"
            data-bowditch-balance
            disabled={phase !== "unbalanced"}
            onClick={onBalancePress}
            className="rounded-sm border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground transition-colors duration-150 hover:border-ns-muted disabled:pointer-events-none disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            Balance traverse
          </button>
          <button
            type="button"
            data-bowditch-reset
            disabled={phase === "balancing"}
            onClick={onReset}
            className="rounded-sm border border-border bg-background px-3 py-1.5 text-xs text-ns-muted transition-colors duration-150 hover:border-ns-muted disabled:pointer-events-none disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            New traverse
          </button>
        </div>

        <div role="status" aria-live="polite" className="font-mono text-[11px] text-ns-muted">
          {statusText}
          {closed && areaHa !== null ? (
            <span data-bowditch-area className="text-foreground">
              {`, area ${areaHa.toFixed(1)} ha`}
            </span>
          ) : null}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// BoxplotAsciiWhisker — the registry's first distribution instrument.
// Nearest neighbours: histogram-live-grain tallies a rolling window into
// fixed bins, stem-and-leaf-live keeps every raw digit in ascending stem
// rows, chart-ridgeline-terrain renders many distributions as overlapping
// density silhouettes — none of the three computes quartiles, a fence, or
// classifies individual samples as outliers.
//
// The mechanic: ONE shared fence handle — a real <input type="range">,
// visually replaced by a custom track/thumb the way slider-range-shear
// carries its a11y — controls k, the IQR multiplier that defines the
// whisker fence (Q1 - k*IQR .. Q3 + k*IQR) for every box on the chart at
// once. Dragging or keying it re-cuts the whisker caps live against the
// REAL underlying sample (not a cached summary): the farthest sample still
// inside the fence becomes the new whisker end, and every sample outside it
// renders as an outlier glyph that fades in; a sample that re-enters the
// fence as k grows fades back into the whisker instead of vanishing. Box
// bodies are filled with the family's shared ASCII ramp ' .:-=+*#%@' tiled
// at a constant mid density — box height already encodes the interquartile
// spread, so ink here is texture, not a second value channel — pure
// var(--foreground), var(--ns-accent) reserved for the focused/hovered group
// and the fence handle itself.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const BOX_CH = RAMP[6];

export interface BoxplotGroup {
  label: string;
  samples: number[];
}

export interface BoxplotAsciiWhiskerProps {
  /** the plotted groups, one boxplot each */
  groups?: BoxplotGroup[];
  /** heading above the chart */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// deterministic synthetic samples — three clearly fabricated batches
function defaultGroups(): BoxplotGroup[] {
  let seed = 11;
  const rand = () => {
    seed = (seed * 48271) % 2147483647;
    return (seed - 1) / 2147483646;
  };
  const gauss = (mean: number, sd: number) => {
    let u = 0;
    let v = 0;
    while (u === 0) u = rand();
    while (v === 0) v = rand();
    return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const make = (mean: number, sd: number, n: number, outliers: number[]) => {
    const out: number[] = [];
    for (let i = 0; i < n; i++) out.push(Math.round(gauss(mean, sd) * 10) / 10);
    return out.concat(outliers);
  };
  return [
    { label: "Batch A", samples: make(40, 6, 34, [12, 68]) },
    { label: "Batch B", samples: make(52, 9, 34, [18, 22, 96]) },
    { label: "Batch C", samples: make(34, 4, 34, [55]) },
  ];
}

function quantile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  if (sorted.length === 1) return sorted[0];
  const idx = p * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

const K_MIN = 0.5;
const K_MAX = 3;
const K_STEP = 0.1;

interface GroupStats {
  label: string;
  sorted: number[];
  q1: number;
  median: number;
  q3: number;
  iqr: number;
  // samples that are outliers at the tightest possible fence (k = K_MIN) —
  // the maximal candidate pool across the whole draggable range
  candidates: number[];
}

function computeStats(g: BoxplotGroup): GroupStats {
  const sorted = [...g.samples].sort((a, b) => a - b);
  const q1 = quantile(sorted, 0.25);
  const median = quantile(sorted, 0.5);
  const q3 = quantile(sorted, 0.75);
  const iqr = Math.max(1e-6, q3 - q1);
  const lowAtMin = q1 - K_MIN * iqr;
  const highAtMin = q3 + K_MIN * iqr;
  const candidates = sorted.filter((v) => v < lowAtMin || v > highAtMin);
  return { label: g.label, sorted, q1, median, q3, iqr, candidates };
}

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

const GROUP_W = 110;
const BOX_W = 46;
const PLOT_H = 220;
const TOP_PAD = 16;
const BOTTOM_PAD = 30;
const LEFT_PAD = 40;
const RIGHT_PAD = 16;

export function BoxplotAsciiWhisker({ groups, title = "Chart", className = "" }: BoxplotAsciiWhiskerProps) {
  const data = useMemo(() => groups ?? defaultGroups(), [groups]);
  const stats = useMemo(() => data.map(computeStats), [data]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();
  const [k, setK] = useState(1.5);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  // useId, not Math.random(): the id is serialized into element ids on the
  // server and must match what the client renders, or React discards the
  // subtree as a hydration mismatch
  const uid = `baw-${useId().replace(/:/g, "")}`;
  const trackRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const globalMin = useMemo(() => Math.min(...stats.map((s) => s.sorted[0] ?? 0)), [stats]);
  const globalMax = useMemo(() => Math.max(...stats.map((s) => s.sorted[s.sorted.length - 1] ?? 0)), [stats]);
  const span = Math.max(1e-6, globalMax - globalMin);
  const pad = span * 0.08;
  const domainMin = globalMin - pad;
  const domainMax = globalMax + pad;
  const domainSpan = domainMax - domainMin;

  const n = stats.length;
  const viewW = LEFT_PAD + n * GROUP_W + RIGHT_PAD;
  const viewH = TOP_PAD + PLOT_H + BOTTOM_PAD;
  const valueToY = (v: number) => TOP_PAD + PLOT_H - ((v - domainMin) / domainSpan) * PLOT_H;

  const cuts = useMemo(
    () =>
      stats.map((s) => {
        const lowFence = s.q1 - k * s.iqr;
        const highFence = s.q3 + k * s.iqr;
        const within = s.sorted.filter((v) => v >= lowFence && v <= highFence);
        const whiskerLow = within.length ? within[0] : s.q1;
        const whiskerHigh = within.length ? within[within.length - 1] : s.q3;
        const outliers = s.candidates.filter((v) => v < lowFence || v > highFence);
        return { whiskerLow, whiskerHigh, outliers };
      }),
    [stats, k]
  );

  // animated display state: per-group whisker ends lerp toward target;
  // per-candidate alpha lerps toward 1 (outlier) or 0 (reclassified inlier)
  const displayWhiskerRef = useRef<{ lo: number; hi: number }[]>([]);
  const alphaRef = useRef<number[][]>([]);
  const rafRef = useRef(0);

  useEffect(() => {
    if (displayWhiskerRef.current.length !== n) {
      displayWhiskerRef.current = cuts.map((c) => ({ lo: c.whiskerLow, hi: c.whiskerHigh }));
    }
    if (alphaRef.current.length !== n) {
      alphaRef.current = stats.map((s) => s.candidates.map(() => 0));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [n, stats]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const draw = () => {
      ctx.clearRect(0, 0, viewW, viewH);

      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      [0, 0.25, 0.5, 0.75, 1].forEach((f) => {
        const y = Math.round(TOP_PAD + PLOT_H * f) + 0.5;
        ctx.beginPath();
        ctx.moveTo(LEFT_PAD, y);
        ctx.lineTo(viewW - RIGHT_PAD, y);
        ctx.stroke();
      });
      ctx.fillStyle = tokens.muted;
      ctx.font = `9px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "right";
      ctx.fillText(domainMax.toFixed(0), LEFT_PAD - 6, TOP_PAD + 4);
      ctx.fillText(domainMin.toFixed(0), LEFT_PAD - 6, TOP_PAD + PLOT_H);

      let stillAnimating = false;

      stats.forEach((s, i) => {
        const cx = LEFT_PAD + i * GROUP_W + GROUP_W / 2;
        const boxX = cx - BOX_W / 2;
        // hoverIndex alone carries real interaction (pointer hover AND
        // keyboard focus both set it) — activeIndex is only roving-tabindex
        // bookkeeping and must never tint a resting, unfocused group
        const isActive = hoverIndex === i;
        const ink = isActive ? tokens.accent : tokens.fg;

        const cut = cuts[i];
        const dw = displayWhiskerRef.current[i] ?? { lo: cut.whiskerLow, hi: cut.whiskerHigh };
        const nextLo = reducedRef.current ? cut.whiskerLow : dw.lo + (cut.whiskerLow - dw.lo) * 0.25;
        const nextHi = reducedRef.current ? cut.whiskerHigh : dw.hi + (cut.whiskerHigh - dw.hi) * 0.25;
        displayWhiskerRef.current[i] = {
          lo: Math.abs(nextLo - cut.whiskerLow) < 0.05 ? cut.whiskerLow : nextLo,
          hi: Math.abs(nextHi - cut.whiskerHigh) < 0.05 ? cut.whiskerHigh : nextHi,
        };
        if (
          Math.abs(displayWhiskerRef.current[i].lo - cut.whiskerLow) >= 0.05 ||
          Math.abs(displayWhiskerRef.current[i].hi - cut.whiskerHigh) >= 0.05
        ) {
          stillAnimating = true;
        }

        const yWhiskerLo = valueToY(displayWhiskerRef.current[i].lo);
        const yWhiskerHi = valueToY(displayWhiskerRef.current[i].hi);
        const yQ1 = valueToY(s.q1);
        const yQ3 = valueToY(s.q3);
        const yMed = valueToY(s.median);

        // whisker stem + caps
        ctx.strokeStyle = ink;
        ctx.lineWidth = 1.25;
        ctx.beginPath();
        ctx.moveTo(cx, yWhiskerHi);
        ctx.lineTo(cx, yQ3);
        ctx.moveTo(cx, yQ1);
        ctx.lineTo(cx, yWhiskerLo);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - 10, yWhiskerHi);
        ctx.lineTo(cx + 10, yWhiskerHi);
        ctx.moveTo(cx - 10, yWhiskerLo);
        ctx.lineTo(cx + 10, yWhiskerLo);
        ctx.stroke();

        // box body — glyph texture fill, clipped, constant mid density
        ctx.save();
        ctx.beginPath();
        ctx.rect(boxX, yQ3, BOX_W, Math.max(1, yQ1 - yQ3));
        ctx.clip();
        ctx.fillStyle = ink;
        ctx.font = `9px "GeistMono", ui-monospace, monospace`;
        ctx.textAlign = "left";
        ctx.textBaseline = "top";
        for (let y = yQ3; y < yQ1; y += 10) {
          for (let x = boxX; x < boxX + BOX_W; x += 8) {
            ctx.fillText(BOX_CH, x, y);
          }
        }
        ctx.restore();
        ctx.strokeStyle = ink;
        ctx.lineWidth = 1.25;
        ctx.strokeRect(boxX + 0.5, yQ3 + 0.5, BOX_W, Math.max(1, yQ1 - yQ3));

        // median — heavier solid row
        ctx.fillStyle = ink;
        ctx.fillRect(boxX, yMed - 1, BOX_W, 2);

        // outliers — animated alpha per candidate
        const alphas = alphaRef.current[i] ?? [];
        s.candidates.forEach((v, ci) => {
          const target = cut.outliers.includes(v) ? 1 : 0;
          const cur = alphas[ci] ?? 0;
          const next = reducedRef.current ? target : cur + (target - cur) * 0.28;
          alphas[ci] = Math.abs(next - target) < 0.01 ? target : next;
          if (Math.abs(alphas[ci] - target) >= 0.01) stillAnimating = true;
          if (alphas[ci] <= 0.01) return;
          const y = valueToY(v);
          ctx.globalAlpha = alphas[ci];
          ctx.beginPath();
          ctx.arc(cx, y, 3, 0, Math.PI * 2);
          ctx.strokeStyle = ink;
          ctx.lineWidth = 1.25;
          ctx.stroke();
          ctx.globalAlpha = 1;
        });
        alphaRef.current[i] = alphas;

        ctx.fillStyle = tokens.muted;
        ctx.font = `9.5px "GeistMono", ui-monospace, monospace`;
        ctx.textAlign = "center";
        ctx.fillText(s.label, cx, TOP_PAD + PLOT_H + BOTTOM_PAD - 12);
      });

      if (stillAnimating && !reducedRef.current) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [stats, cuts, tokens, viewW, viewH, domainMin, domainSpan, hoverIndex, activeIndex]);

  const focusGroup = (i: number) => {
    if (i < 0 || i >= n) return;
    setActiveIndex(i);
    document.getElementById(`${uid}-hit-${i}`)?.focus();
  };

  const kFromClientX = (clientX: number): number => {
    const el = trackRef.current;
    if (!el) return k;
    const rect = el.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    const raw = K_MIN + frac * (K_MAX - K_MIN);
    return Math.round(raw / K_STEP) * K_STEP;
  };

  const hovered = hoverIndex !== null ? stats[hoverIndex] : null;
  const hoveredCut = hoverIndex !== null ? cuts[hoverIndex] : null;

  return (
    <figure className={`ns-baw inline-block ${className}`} aria-label={`${title}, box plot`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <span className="font-mono text-[11px] text-ns-muted tabular-nums">k = {k.toFixed(1)}× IQR</span>
      </div>

      <div className="relative" style={{ width: viewW, maxWidth: "100%" }}>
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="ns-baw-canvas"
          style={{ width: viewW, height: viewH, maxWidth: "100%", display: "block" }}
        />

        {stats.map((s, i) => (
          <button
            key={s.label}
            type="button"
            id={`${uid}-hit-${i}`}
            tabIndex={activeIndex === i ? 0 : -1}
            aria-label={`${s.label}: median ${s.median.toFixed(1)}, Q1 ${s.q1.toFixed(1)}, Q3 ${s.q3.toFixed(1)}, ${cuts[i].outliers.length} outlier${cuts[i].outliers.length === 1 ? "" : "s"}`}
            className="ns-baw-hit absolute cursor-pointer border-0 bg-transparent p-0 outline-none"
            style={{ left: LEFT_PAD + i * GROUP_W, top: TOP_PAD - 10, width: GROUP_W, height: PLOT_H + 10 }}
            onPointerEnter={() => setHoverIndex(i)}
            onPointerLeave={() => setHoverIndex((c) => (c === i ? null : c))}
            onFocus={() => {
              setActiveIndex(i);
              setHoverIndex(i);
            }}
            onBlur={() => setHoverIndex((c) => (c === i ? null : c))}
            onKeyDown={(e) => {
              if (e.key === "ArrowLeft") {
                e.preventDefault();
                focusGroup(i - 1);
              } else if (e.key === "ArrowRight") {
                e.preventDefault();
                focusGroup(i + 1);
              }
            }}
          />
        ))}

        {hovered && hoveredCut && (
          <div
            aria-hidden="true"
            className="ns-baw-tip pointer-events-none absolute z-10 rounded-sm border border-border bg-background px-2 py-1 font-mono text-[11px] shadow-sm"
            style={{
              left: `${((LEFT_PAD + hoverIndex! * GROUP_W + GROUP_W / 2) / viewW) * 100}%`,
              top: `${(Math.max(0, valueToY(hovered.q3) - 46) / viewH) * 100}%`,
              transform: "translateX(-50%)",
            }}
          >
            <strong className="text-foreground">{hovered.median.toFixed(1)}</strong>{" "}
            <span className="text-ns-muted">
              med · Q1 {hovered.q1.toFixed(1)} · Q3 {hovered.q3.toFixed(1)} · {hoveredCut.outliers.length} out
            </span>
          </div>
        )}
      </div>

      <div className="mt-4 flex items-center gap-3">
        <span className="font-mono text-[10px] tracking-widest text-ns-muted">FENCE</span>
        <div
          ref={trackRef}
          className="ns-baw-track relative h-4 flex-1 cursor-pointer rounded-full bg-border/60"
          onPointerDown={(e) => {
            setK(kFromClientX(e.clientX));
            inputRef.current?.focus();
            const move = (ev: PointerEvent) => setK(kFromClientX(ev.clientX));
            const up = () => {
              window.removeEventListener("pointermove", move);
              window.removeEventListener("pointerup", up);
            };
            window.addEventListener("pointermove", move);
            window.addEventListener("pointerup", up);
          }}
        >
          <input
            ref={inputRef}
            type="range"
            min={K_MIN}
            max={K_MAX}
            step={K_STEP}
            value={k}
            onChange={(e) => setK(Number(e.target.value))}
            aria-label="Whisker fence, multiplier of interquartile range"
            className="ns-baw-range sr-only"
          />
          <div
            aria-hidden="true"
            className="ns-baw-thumb absolute top-1/2 h-3 w-3 -translate-y-1/2 rounded-full border-2 border-ns-accent bg-background"
            style={{ left: `${((k - K_MIN) / (K_MAX - K_MIN)) * 100}%`, transform: "translate(-50%, -50%)" }}
          />
        </div>
      </div>
    </figure>
  );
}

const CSS = `
.ns-baw-hit { touch-action: manipulation; }
.ns-baw-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
.ns-baw-range:focus-visible ~ .ns-baw-thumb { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// BrassCheck — the active-sessions list as a pit-head lamp-room check board.
// Every live session is a stamped brass tag (its number in Geist Mono)
// hanging on its own hook; signing one out is unhooking it, not deleting a
// row. One governing scalar per tag: hang angle `theta` on a damped harmonic
// spring (`accel = -K*(theta-target) - C*vel`), written straight to an SVG
// <g>'s `transform` every frame — never React state in the hot path.
//
//   - idle:  target = 0deg
//   - hover: target = 2deg (the tag answers the pointer, proving it's live)
//   - hold:  target = 48deg (well past the 28deg release angle) — pressing
//     and holding the sign-out button drives the spring toward it
//
// If the hold is released (pointerup/keyup/pointerleave) BEFORE the tag's
// actual angle has crossed 28deg AND at least MIN_HOLD_MS has elapsed, the
// gesture aborts: target snaps back to 0 (or 2 if still hovered) and the
// same spring visibly swings the tag back and re-seats it — never an
// ambiguous static reset. Only once both conditions are true does the hold
// COMMIT: the row is removed from the board immediately (an instant list
// reflow, not a fade or a height-collapse) and a separate ballistic "ghost"
// tag takes over — free-fall under gravity with one 0.18-restitution
// bounce off the tray floor, no easing curve, real per-frame integration
// (vy += g*dt; y += vy*dt) written to `transform: translate3d(...) rotate(...)`.
// Once the ghost settles it is retired and a real <li> is appended to the
// tray's `role="log"` — THAT DOM insertion, with the li's accessible name
// set to "{device} signed out, N sessions remain", is the announcement.
//
// This two-phase handoff (rest -> spring resists -> commit -> gravity owns
// it) is the falsifiable bit: revocation is a one-way physical transfer,
// never an opacity fade or a height collapse standing in for it. It is also
// why a stray click can't revoke anything — a fast pointerdown/up never
// accumulates MIN_HOLD_MS, so the verifier's incidental "press" pass on the
// first control just nudges the tag and lets it swing back, exactly like an
// aborted hold from a real user.
//
// The current device's tag has no sign-out control at all (a decorative
// lanyard loop through the ring instead of a hook) — not a disabled button,
// since there is nothing to confirm or explain, just nothing there.
//
// prefers-reduced-motion: hover/hold produce no continuous spring animation
// (poses are set instantly, no interpolation), and a committed hold moves
// the tag from hook to tray in a single paint — no ghost, no flight — with
// the identical log announcement.
// ---------------------------------------------------------------------------

export interface CheckSession {
  id: string;
  device: string;
  location: string;
  lastSeen: string;
  /** the session driving this render — gets a lanyard, no sign-out control */
  current?: boolean;
}

export interface BrassCheckProps {
  /** every live session; order fixes each tag's stamped number */
  sessions: CheckSession[];
  /** accessible name for the board */
  label?: string;
  /** fires the instant a tag leaves the hook (not when it lands in the tray) */
  onSignOut?: (id: string) => void;
  className?: string;
}

const HOVER_DEG = 2;
const RELEASE_ANGLE = 28;
const HOLD_TARGET_DEG = 48;
const MIN_HOLD_MS = 620;
const SPRING_K = 18;
const SPRING_C = 7;
const REST_EPS = 0.06;
const GRAVITY = 2200; // px/s^2
const RESTITUTION = 0.18;
const ROT_DAMP = 3.2; // 1/s decay on the tumble
const SLIP_VX = 46; // px/s lateral slip at the moment of release

function restTilt(tagNumber: number) {
  return ((tagNumber * 53) % 13) - 6;
}

function formatClock(d: Date) {
  const p = (n: number) => n.toString().padStart(2, "0");
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

interface RowRuntime {
  theta: number;
  vel: number;
  target: number;
  holding: boolean;
  hovered: boolean;
  holdStart: number | null;
  released: boolean;
  rafId: number | undefined;
  lastTs: number | undefined;
  reducedTimer: number | undefined;
  groupEl: SVGGElement | null;
  buttonEl: HTMLButtonElement | null;
}

interface GhostRuntime {
  x: number;
  y: number;
  vx: number;
  vy: number;
  rot: number;
  vRot: number;
  floorY: number;
  bounced: boolean;
  rafId: number | undefined;
  lastTs: number | undefined;
  el: HTMLDivElement | null;
}

interface GhostView {
  id: string;
  tagNumber: number;
}

interface TrayEntry {
  id: string;
  device: string;
  tagNumber: number;
  time: string;
  remaining: number;
  tilt: number;
}

export function BrassCheck({ sessions, label = "Active sessions", onSignOut, className = "" }: BrassCheckProps) {
  const [removedIds, setRemovedIds] = useState<Set<string>>(() => new Set());
  const [ghosts, setGhosts] = useState<GhostView[]>([]);
  const [tray, setTray] = useState<TrayEntry[]>([]);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const trayRef = useRef<HTMLUListElement | null>(null);
  const reducedRef = useRef(false);
  const runtimes = useRef(new Map<string, RowRuntime>()).current;
  const ghostRuntimes = useRef(new Map<string, GhostRuntime>()).current;
  const tagNumbers = useRef(new Map(sessions.map((s, i) => [s.id, i + 1]))).current;
  const pendingFocusRef = useRef<number | null>(null);
  // Not derived from `removedIds` state: the in-flight rAF chain that calls
  // `commitRelease` was captured when its hold started, so if a second row
  // finishes falling while a first row's ghost is still airborne, that
  // stale closure would otherwise read a `removedIds` from its own render
  // and undercount by however many revocations landed since. This ref is
  // mutated synchronously, so every commit sees the true running total.
  const removedCountRef = useRef(0);
  const trayLabelId = useId();

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(
    () => () => {
      runtimes.forEach((r) => {
        if (r.rafId !== undefined) cancelAnimationFrame(r.rafId);
        if (r.reducedTimer !== undefined) window.clearTimeout(r.reducedTimer);
      });
      ghostRuntimes.forEach((g) => {
        if (g.rafId !== undefined) cancelAnimationFrame(g.rafId);
      });
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  const getRuntime = useCallback(
    (id: string): RowRuntime => {
      let r = runtimes.get(id);
      if (!r) {
        r = {
          theta: 0,
          vel: 0,
          target: 0,
          holding: false,
          hovered: false,
          holdStart: null,
          released: false,
          rafId: undefined,
          lastTs: undefined,
          reducedTimer: undefined,
          groupEl: null,
          buttonEl: null,
        };
        runtimes.set(id, r);
      }
      return r;
    },
    [runtimes]
  );

  const applyRowPose = (r: RowRuntime) => {
    if (r.groupEl) r.groupEl.style.transform = `rotate(${r.theta.toFixed(2)}deg)`;
  };

  const commitRelease = useCallback(
    (id: string, theta: number, angularVel: number) => {
      const runtime = getRuntime(id);
      if (runtime.released) return;
      runtime.released = true;
      runtime.holding = false;
      if (runtime.rafId !== undefined) {
        cancelAnimationFrame(runtime.rafId);
        runtime.rafId = undefined;
      }

      const session = sessions.find((s) => s.id === id);
      if (!session) return;
      onSignOut?.(id);

      const root = rootRef.current;
      if (root) {
        const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>(".ns-bc-signout"));
        const idx = buttons.indexOf(runtime.buttonEl as HTMLButtonElement);
        pendingFocusRef.current = idx >= 0 ? idx : null;
      }

      removedCountRef.current += 1;
      const remaining = sessions.length - removedCountRef.current;
      const tagNumber = tagNumbers.get(id) ?? 0;
      const tilt = restTilt(tagNumber);

      const rootRect = root?.getBoundingClientRect();
      const trayRect = trayRef.current?.getBoundingClientRect();
      const groupRect = runtime.groupEl?.getBoundingClientRect();

      setRemovedIds((prev) => {
        const next = new Set(prev);
        next.add(id);
        return next;
      });

      if (reducedRef.current || !rootRect || !trayRect || !groupRect) {
        // one paint: land immediately, no ghost flight.
        setTray((prev) => [
          { id: `${id}-${Date.now()}`, device: session.device, tagNumber, time: formatClock(new Date()), remaining, tilt },
          ...prev,
        ]);
        return;
      }

      const ghostId = `${id}-${Date.now()}`;
      const startX = groupRect.left - rootRect.left + groupRect.width / 2;
      const startY = groupRect.top - rootRect.top + groupRect.height / 2;
      // Aim the ghost's center at roughly where a landed ticket's own
      // center sits (tray padding + half the ~26px ticket row height),
      // not just the tray's outer top edge, so the handoff to the real
      // <li> reads as a landing rather than a teleport.
      const floorY = trayRect.top - rootRect.top + 12 + 13;
      const vx = SLIP_VX * (theta >= 0 ? 1 : -1);

      ghostRuntimes.set(ghostId, {
        x: startX,
        y: startY,
        vx,
        vy: 30,
        rot: theta,
        vRot: Math.max(-260, Math.min(260, angularVel * 12)),
        floorY,
        bounced: false,
        rafId: undefined,
        lastTs: undefined,
        el: null,
      });
      setGhosts((prev) => [...prev, { id: ghostId, tagNumber }]);

      const tick = (ts: number) => {
        const g = ghostRuntimes.get(ghostId);
        if (!g) return;
        const last = g.lastTs ?? ts;
        const dt = Math.min((ts - last) / 1000, 0.032);
        g.lastTs = ts;

        g.vy += GRAVITY * dt;
        g.y += g.vy * dt;
        g.x += g.vx * dt;
        g.vx *= Math.max(0, 1 - 1.6 * dt);
        g.vRot *= Math.max(0, 1 - ROT_DAMP * dt);
        g.rot += g.vRot * dt;

        let landed = false;
        if (g.y >= g.floorY) {
          if (!g.bounced) {
            g.y = g.floorY;
            g.vy = -g.vy * RESTITUTION;
            g.bounced = true;
          } else {
            g.y = g.floorY;
            g.vy = 0;
            g.vx = 0;
            g.vRot = 0;
            g.rot = tilt;
            landed = true;
          }
        }

        if (g.el) {
          g.el.style.transform = `translate3d(${g.x.toFixed(1)}px, ${g.y.toFixed(1)}px, 0) rotate(${g.rot.toFixed(1)}deg)`;
        }

        if (landed) {
          ghostRuntimes.delete(ghostId);
          setGhosts((prev) => prev.filter((gh) => gh.id !== ghostId));
          setTray((prev) => [{ id: ghostId, device: session.device, tagNumber, time: formatClock(new Date()), remaining, tilt }, ...prev]);
          return;
        }
        g.rafId = requestAnimationFrame(tick);
      };
      ghostRuntimes.get(ghostId)!.rafId = requestAnimationFrame(tick);
    },
    [sessions, onSignOut, getRuntime, ghostRuntimes, tagNumbers]
  );

  const tickRow = useCallback(
    (id: string, ts: number) => {
      const r = getRuntime(id);
      const last = r.lastTs ?? ts;
      const dt = Math.min((ts - last) / 1000, 0.032);
      r.lastTs = ts;

      const accel = -SPRING_K * (r.theta - r.target) - SPRING_C * r.vel;
      r.vel += accel * dt;
      r.theta += r.vel * dt;
      applyRowPose(r);

      if (r.holding && !r.released && r.theta >= RELEASE_ANGLE && r.holdStart !== null && ts - r.holdStart >= MIN_HOLD_MS) {
        commitRelease(id, r.theta, r.vel);
        return;
      }

      if (!r.holding && Math.abs(r.theta - r.target) < REST_EPS && Math.abs(r.vel) < REST_EPS) {
        r.theta = r.target;
        r.vel = 0;
        applyRowPose(r);
        r.lastTs = undefined;
        r.rafId = undefined;
        return;
      }
      r.rafId = requestAnimationFrame((t) => tickRow(id, t));
    },
    [getRuntime, commitRelease]
  );

  const ensureRowLoop = useCallback(
    (id: string) => {
      const r = getRuntime(id);
      if (r.rafId === undefined) {
        r.rafId = requestAnimationFrame((ts) => tickRow(id, ts));
      }
    },
    [getRuntime, tickRow]
  );

  const startHold = useCallback(
    (id: string) => {
      const r = getRuntime(id);
      if (r.released || r.holding) return;
      if (reducedRef.current) {
        r.holding = true;
        r.holdStart = performance.now();
        if (r.reducedTimer !== undefined) window.clearTimeout(r.reducedTimer);
        r.reducedTimer = window.setTimeout(() => {
          if (r.holding && !r.released) commitRelease(id, RELEASE_ANGLE, 0);
        }, MIN_HOLD_MS);
        return;
      }
      r.holding = true;
      r.holdStart = performance.now();
      r.target = HOLD_TARGET_DEG;
      ensureRowLoop(id);
    },
    [getRuntime, ensureRowLoop, commitRelease]
  );

  const endHold = useCallback(
    (id: string) => {
      const r = getRuntime(id);
      if (r.released) return;
      r.holding = false;
      r.holdStart = null;
      if (r.reducedTimer !== undefined) {
        window.clearTimeout(r.reducedTimer);
        r.reducedTimer = undefined;
      }
      if (reducedRef.current) {
        r.theta = r.hovered ? HOVER_DEG : 0;
        r.target = r.theta;
        r.vel = 0;
        applyRowPose(r);
        return;
      }
      r.target = r.hovered ? HOVER_DEG : 0;
      ensureRowLoop(id);
    },
    [getRuntime, ensureRowLoop]
  );

  const setHover = useCallback(
    (id: string, hovered: boolean) => {
      const r = getRuntime(id);
      if (r.released || r.holding) {
        r.hovered = hovered;
        return;
      }
      r.hovered = hovered;
      if (reducedRef.current) {
        r.target = hovered ? HOVER_DEG : 0;
        r.theta = r.target;
        r.vel = 0;
        applyRowPose(r);
        return;
      }
      r.target = hovered ? HOVER_DEG : 0;
      ensureRowLoop(id);
    },
    [getRuntime, ensureRowLoop]
  );

  useEffect(() => {
    const idx = pendingFocusRef.current;
    pendingFocusRef.current = null;
    if (idx === null) return;
    const root = rootRef.current;
    if (!root) return;
    const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>(".ns-bc-signout"));
    const target = buttons[Math.min(idx, buttons.length - 1)];
    target?.focus();
  }, [removedIds]);

  const visible = sessions.filter((s) => !removedIds.has(s.id));

  const onKeyDown = (id: string) => (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if ((e.key === "Enter" || e.key === " ") && !e.repeat) {
      e.preventDefault();
      startHold(id);
    }
  };
  const onKeyUp = (id: string) => (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      endHold(id);
    }
  };
  const onPointerDown = (id: string) => (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    startHold(id);
  };

  return (
    <div ref={rootRef} className={`ns-bc-root ${className}`}>
      <style>{CSS}</style>

      <ul className="ns-bc-board" aria-label={label}>
        {visible.map((s) => {
          const num = tagNumbers.get(s.id) ?? 0;
          const runtime = getRuntime(s.id);
          const tagLabel = String(num).padStart(2, "0");
          return (
            <li key={s.id} className="ns-bc-row">
              {s.current ? (
                <span className="ns-bc-hookslot" aria-hidden="true">
                  <svg width="52" height="60" viewBox="0 0 52 60" focusable="false">
                    <path d="M20 3c4 -3.6 8 -3.6 12 0" fill="none" stroke="var(--ns-muted)" strokeWidth="1.3" strokeLinecap="round" />
                    <circle cx="26" cy="12" r="4" fill="none" stroke="var(--ns-muted)" strokeWidth="1.3" />
                    <path
                      d="M23.4 15 L20 46 M28.6 15 L32 46"
                      fill="none"
                      stroke="var(--ns-muted)"
                      strokeWidth="1"
                      strokeDasharray="1.5 2.5"
                      strokeLinecap="round"
                    />
                    <rect x="10" y="17" width="32" height="34" rx="8" fill="var(--background)" stroke="var(--foreground)" strokeWidth="1.3" />
                    <text x="26" y="39" textAnchor="middle" fontFamily="var(--font-mono)" fontSize="14" fill="var(--foreground)">
                      {tagLabel}
                    </text>
                  </svg>
                </span>
              ) : (
                <button
                  type="button"
                  className="ns-bc-signout"
                  aria-label={`Sign out ${s.device}`}
                  ref={(el) => {
                    runtime.buttonEl = el;
                  }}
                  onPointerEnter={() => setHover(s.id, true)}
                  onPointerLeave={() => {
                    setHover(s.id, false);
                    endHold(s.id);
                  }}
                  onPointerDown={onPointerDown(s.id)}
                  onPointerUp={() => endHold(s.id)}
                  onPointerCancel={() => endHold(s.id)}
                  onKeyDown={onKeyDown(s.id)}
                  onKeyUp={onKeyUp(s.id)}
                >
                  <svg width="52" height="60" viewBox="0 0 52 60" aria-hidden="true" focusable="false">
                    <path d="M20 3c4 -3.6 8 -3.6 12 0" fill="none" stroke="var(--ns-muted)" strokeWidth="1.3" strokeLinecap="round" />
                    <g
                      ref={(el) => {
                        runtime.groupEl = el;
                      }}
                      style={{ transformOrigin: "26px 12px" }}
                    >
                      <circle cx="26" cy="12" r="4" fill="none" stroke="var(--ns-muted)" strokeWidth="1.3" />
                      <rect x="10" y="17" width="32" height="34" rx="8" fill="var(--background)" stroke="var(--foreground)" strokeWidth="1.3" />
                      <text x="26" y="39" textAnchor="middle" fontFamily="var(--font-mono)" fontSize="14" fill="var(--foreground)">
                        {tagLabel}
                      </text>
                    </g>
                  </svg>
                </button>
              )}
              <span className="ns-bc-info">
                <span className="ns-bc-device">
                  {s.device}
                  {s.current && <span className="ns-bc-thisdevice">This device</span>}
                </span>
                <span className="ns-bc-meta">
                  {s.location} · {s.lastSeen}
                </span>
              </span>
            </li>
          );
        })}
      </ul>

      {ghosts.map((g) => (
        <div
          key={g.id}
          aria-hidden="true"
          className="ns-bc-ghost"
          ref={(el) => {
            const gr = ghostRuntimes.get(g.id);
            if (gr) gr.el = el;
          }}
        >
          <svg width="52" height="52" viewBox="0 0 52 52" focusable="false">
            <circle cx="26" cy="10" r="4" fill="none" stroke="var(--ns-muted)" strokeWidth="1.3" />
            <rect x="10" y="14" width="32" height="32" rx="8" fill="var(--background)" stroke="var(--foreground)" strokeWidth="1.3" />
            <text x="26" y="34" textAnchor="middle" fontFamily="var(--font-mono)" fontSize="13" fill="var(--foreground)">
              {String(g.tagNumber).padStart(2, "0")}
            </text>
          </svg>
        </div>
      ))}

      <div className="ns-bc-traywrap">
        <h3 id={trayLabelId} className="ns-bc-traylabel">
          Sign-out history
        </h3>
        <ul ref={trayRef} role="log" aria-live="polite" aria-relevant="additions" aria-labelledby={trayLabelId} className="ns-bc-tray">
          {tray.length === 0 ? (
            <li className="ns-bc-trayempty" aria-hidden="true">
              Tray empty
            </li>
          ) : (
            tray.map((t) => (
              <li key={t.id} className="ns-bc-trayrow" style={{ transform: `rotate(${t.tilt}deg)` }}>
                <span className="sr-only">
                  {t.device} signed out, {t.remaining} session{t.remaining === 1 ? "" : "s"} remain
                </span>
                <span className="ns-bc-traynum" aria-hidden="true">
                  {String(t.tagNumber).padStart(2, "0")}
                </span>
                <span className="ns-bc-traydevice" aria-hidden="true">
                  {t.device}
                </span>
                <span className="ns-bc-traytime" aria-hidden="true">
                  {t.time}
                </span>
              </li>
            ))
          )}
        </ul>
      </div>
    </div>
  );
}

const CSS = `
