              strokeLinecap="round"
            />
            <circle className="ns-flyball-part" cx={ballLeftX.toFixed(2)} cy={ballY.toFixed(2)} r={BALL_R} fill="var(--foreground)" />
            <circle className="ns-flyball-part" cx={ballRightX.toFixed(2)} cy={ballY.toFixed(2)} r={BALL_R} fill="var(--foreground)" />
          </g>

          {/* sleeve collar — height is purely a function of arm angle, never of spent/cap */}
          <rect
            className="ns-flyball-part"
            x={CX - COLLAR_W / 2}
            y={collarY.toFixed(2)}
            width={COLLAR_W}
            height={COLLAR_H}
            rx={2}
            fill={capReached ? "var(--foreground)" : "none"}
            stroke="var(--foreground)"
            strokeWidth={2}
          />
        </svg>
      </div>

      <div role="status" aria-live="polite" className="sr-only">
        {announce}
      </div>

      <div className="mt-4 flex items-center gap-2">
        <button
          type="button"
          aria-disabled={capReached}
          aria-describedby={capReached ? `${descId} ${closedNoteId}` : descId}
          onClick={() => {
            if (!capReached) onNewPurchase?.();
          }}
          className={`${btnBase} ${capReached ? btnDead : btnLive}`}
        >
          New purchase
        </button>
        <button
          type="button"
          aria-disabled={capReached}
          aria-describedby={capReached ? `${descId} ${closedNoteId}` : descId}
          onClick={() => {
            if (!capReached) onRaiseLimit?.();
          }}
          className={`${btnBase} ${capReached ? btnDead : btnLive}`}
        >
          Raise limit
        </button>
      </div>

      {capReached ? (
        <p id={closedNoteId} data-flyball-closed-note className="mt-2 font-mono text-[11px] text-ns-muted">
          Disabled — the {fmtMoney(cap, currency)} cap for this period has been reached. New purchases and
          limit increases resume next period.
        </p>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// FlyingSplice — a logo ribbon whose subject is the roll stand feeding it, not
// the ribbon of marks itself. ONE stand, one roll, unwinding at constant web
// speed: the roll's radius falls and its RPM climbs continuously as it empties
// (v/r rises as r shrinks), then the radius rebuilds on the exact time-reverse
// of the same schedule while the roll keeps turning the same way. That inverse
// radius/RPM relationship is the whole mechanic; the ribbon of marks is the
// OUTPUT the roll feeds and is deliberately the plainer half of this component.
//
// The cycle wraps by oscillating the radius, not by resetting it: 15s of
// run-down (R_max -> R_min, omega v/R_max -> v/R_min) then 7s of rebuild
// (R_min -> R_max) — so there is never a pop back to a full roll, and never a
// second disc on screen. Angular velocity is omega = v/r throughout, so it is
// continuous at BOTH turning points (both sides evaluate to v/R_min and
// v/R_max respectively); only dr/dt changes sign, and the rebuild is simply
// the same inverse relationship traversed backward.
//
// Every visual quantity is a pure, closed-form function of absolute time —
// never a per-frame accumulator — because prefers-reduced-motion has to render
// exactly t = STATIC_TIME byte-stably without simulating up to it at mount,
// and because the integrals involved have exact closed forms:
//   down: r = sqrt(R_max^2 - B_dn*p),  theta = 2*v*(R_max - r)/B_dn
//   up:   r = sqrt(R_min^2 + B_up*q),  theta = 2*v*(r - R_min)/B_up
// The swept angle accumulates across cycles as `cycle*THETA_CYCLE + theta(p)`
// rather than restarting each cycle, so the index lines do not snap at the
// wrap — with a single persistent roll there is no role swap to hide a reset
// behind.
// ---------------------------------------------------------------------------

export interface FlyingSpliceProps {
  /** Freezes the mechanism on the composed reduced-motion still frame. */
  paused?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

type RGB = [number, number, number];

function parseHex(raw: string): RGB | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}
function mixRGB(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function luminance([r, g, b]: RGB): number {
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function rgbCss([r, g, b]: RGB, a = 1): string {
  return `rgba(${Math.round(r * 255)},${Math.round(g * 255)},${Math.round(b * 255)},${a})`;
}
// Neutral achromatic mixing points only — never a sourced or fallback colour,
// just the poles used to lighten/darken a token-derived value (same pattern
// weld-pool uses for its ramp).
const BLACK: RGB = [0, 0, 0];
const WHITE: RGB = [1, 1, 1];

// mulberry32 — deterministic seeded PRNG so the mark pattern is identical on
// every mount/render, which prefers-reduced-motion's byte-stability needs.
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- cycle timing (seconds), all named so a reviewer can check them against
// the spec directly ------------------------------------------------------
const CYCLE = 22.0; // unbounded, never terminating
// The roll empties over RUNDOWN_DUR and rebuilds over the remainder. Asymmetric
// on purpose: the run-down is the subject and gets the long, slow read; the
// rebuild is the wrap, and a shorter rebuild keeps it from reading as a second,
// competing event. Both legs share the same sqrt-of-time radius law, so the
// rebuild is the run-down time-reversed rather than an arbitrary eased return.
const RUNDOWN_DUR = 15.0;
const REBUILD_DUR = CYCLE - RUNDOWN_DUR; // 7.0
// Reduced-motion freeze: 65% through the run-down, where the roll is visibly
// part-spent — a clear gap between its wrap edge and the dashed capacity ring,
// index lines already noticeably closer-spaced than on a full roll. Freezing on
// a full roll (the old 22.09s, chosen for a splice that no longer exists) would
// show zero run-down at all.
export const STATIC_TIME = RUNDOWN_DUR * 0.65; // 9.75s

export function FlyingSplice({ paused = false, className = "", style }: FlyingSpliceProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let disposed = false;
    let raf = 0;
    let running = false;
    let staticMode = false;
    let cssW = 0;
    let cssH = 0;
    let dpr = 1;
    let simTime = 0;
    let lastMs = performance.now();

    // ---- tokens: read before anything paints ----------------------------
    let bg: RGB = [1, 1, 1];
    let fg: RGB = [0.09, 0.09, 0.09];
    let border: RGB = [0.92, 0.92, 0.92];
    let dark = false;
    let colorsReady = false;
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      bg = parseHex(cs.getPropertyValue("--background")) ?? bg;
      fg = parseHex(cs.getPropertyValue("--foreground")) ?? fg;
      border = parseHex(cs.getPropertyValue("--border")) ?? border;
      dark = luminance(bg) < 0.5;
      colorsReady = true;
    };
    readColors(); // first statement in the effect — no paint precedes this

    // Paper has to READ as paper against the band: at 0.16 in dark theme the
    // rolls were near-black discs on a near-black band and the whole
    // mechanism was invisible, however correct its motion was.
    const paperColor = () => mixRGB(bg, fg, dark ? 0.34 : 0.13);
    const markColor = () => rgbCss(fg, 0.78);

    // --- seeded mark generator: 3 abstract families (concentric arcs, bar
    // clusters, a lattice), each deterministic per pattern slot -----------
    const rand = mulberry32(0x9e3779b9);
    const markSeeds = Array.from({ length: 16 }, () => ({
      kind: Math.floor(rand() * 3),
      a: rand(),
      b: rand(),
      c: rand(),
    }));

    const drawMark = (
      c: CanvasRenderingContext2D,
      cx: number,
      cy: number,
      size: number,
      seed: { kind: number; a: number; b: number; c: number }
    ) => {
      c.save();
      c.translate(cx, cy);
      c.strokeStyle = markColor();
      c.fillStyle = markColor();
      c.lineWidth = Math.max(1, size * 0.06);
      const r = size / 2;
      if (seed.kind === 0) {
        // concentric arcs
        const n = 3;
        for (let i = 0; i < n; i++) {
          const rr = r * (0.35 + (i / (n - 1)) * 0.65);
          c.beginPath();
          c.arc(0, 0, rr, seed.a * Math.PI * 2, seed.a * Math.PI * 2 + Math.PI * (0.9 + seed.b * 0.6));
          c.stroke();
        }
      } else if (seed.kind === 1) {
        // bar cluster
        const n = 4;
        for (let i = 0; i < n; i++) {
          const h = r * (0.4 + ((seed.a + i * 0.27 + seed.b) % 1) * 1.2);
          const x = -r + (i / (n - 1)) * r * 2;
          c.fillRect(x - size * 0.05, r - h, size * 0.1, h);
        }
      } else {
        // lattice
        const n = 3;
        c.beginPath();
        for (let i = 0; i <= n; i++) {
          const x = -r + (i / n) * r * 2;
          c.moveTo(x, -r);
          c.lineTo(x, r);
        }
        for (let i = 0; i <= n; i++) {
          const y = -r + (i / n) * r * 2;
          c.moveTo(-r, y);
          c.lineTo(r, y);
        }
        c.stroke();
      }
      c.restore();
    };

    // ---- geometry ---------------------------------------------------------
    let M = 1;
    let W = 1;
    let H = 1;
    let RMAX = 1;
    let RMIN = 1;
    const RMIN_RATIO = 27.5 / 64.6; // preserves the spec's radius ratio
    let cy = 0;
    let standX = 0; // the stand's centre x
    let nipX = 0;
    let markCount = 9;
    let indexLines = 4;

    const computeGeometry = () => {
      M = Math.min(cssW, cssH);
      W = cssW;
      H = cssH;
      // R_max = 0.19*M is the spec's checkable number at typical aspect
      // ratios; the max() with a fraction of W is a floor that engages on wide
      // bands (card crops especially), where 0.19*M would leave a spent roll
      // too small to read as wound paper. The floor is 0.11*W: with ONE stand
      // the cluster is a single 2*R_max-wide disc, so 0.11*W puts it at 22% of
      // the band — still clear of the 30%-of-band-width kill criterion that
      // the old 0.075*W floor was sized for when two stands shared the space.
      RMAX = Math.max(0.19 * M, 0.11 * W);
      RMIN = RMAX * RMIN_RATIO;
      cy = H / 2;
      const marginR = RMAX * 0.2;
      standX = W - marginR - RMAX;
      nipX = standX - RMAX * 1.05;
      markCount = M < 200 ? 6 : 9;
      indexLines = M < 200 ? 3 : 4;
    };

    // ---- pure functions of absolute time ---------------------------------
    const v = () => 0.42 * W; // web speed, px/s
    const spacing = () => 0.155 * W;
    const markSize = () => 0.14 * M;

    // radius law constants: r^2 is linear in time on both legs, which is what
    // constant web speed off a wound roll actually gives you.
    const BDN = () => (RMAX * RMAX - RMIN * RMIN) / RUNDOWN_DUR;
    const BUP = () => (RMAX * RMAX - RMIN * RMIN) / REBUILD_DUR;

    const radiusAt = (phase: number) => {
      if (phase <= RUNDOWN_DUR) {
        return Math.sqrt(Math.max(RMAX * RMAX - BDN() * phase, RMIN * RMIN));
      }
      const q = Math.min(phase - RUNDOWN_DUR, REBUILD_DUR);
      return Math.sqrt(Math.min(RMIN * RMIN + BUP() * q, RMAX * RMAX));
    };
    // exact integral of omega = v/r on each leg; omega itself is continuous at
    // both turning points (v/RMIN at the bottom, v/RMAX at the wrap), so the
    // index lines never stall, reverse or jump.
    const angleDownTotal = () => (2 * v() * (RMAX - RMIN)) / BDN();
    const angleUpTotal = () => (2 * v() * (RMAX - RMIN)) / BUP();
    const angleAt = (phase: number) => {
      if (phase <= RUNDOWN_DUR) {
        return (2 * v() * (RMAX - radiusAt(phase))) / BDN();
      }
      return angleDownTotal() + (2 * v() * (radiusAt(phase) - RMIN)) / BUP();
    };
    const cycleAngle = () => angleDownTotal() + angleUpTotal();

    interface RollState {
      radius: number;
      angle: number;
    }

    // The single roll's complete state at absolute time t. The swept angle
    // accumulates across cycles rather than restarting, so nothing snaps at the
    // wrap; it is reduced mod 2*PI only at draw time to keep float precision
    // bounded over long sessions.
    const rollState = (t: number): RollState => {
      const cycle = Math.floor(t / CYCLE);
      const phase = t - cycle * CYCLE;
      return {
        radius: radiusAt(phase),
        angle: (cycle * cycleAngle() + angleAt(phase)) % (Math.PI * 2),
      };
    };

    // ---- draw --------------------------------------------------------------
    const drawRoll = (
      c: CanvasRenderingContext2D,
      x: number,
      state: RollState
    ) => {
      const py = cy;
      c.save();
      const base = paperColor();
      const hi = mixRGB(base, WHITE, 0.10);
      const lo = mixRGB(base, BLACK, 0.12);
      // single-lamp Lambert shade: a radial gradient whose centre is offset
      // toward the light azimuth (118deg), i.e. the classic sphere-shading
      // trick, cheap in 2D canvas and value-only (no hue).
      const az = (118 * Math.PI) / 180;
      // a shallow offset: at 0.55 the shading read as a billiard ball rather
      // than as the flat end of a wound coil.
      const gx = x + Math.cos(az) * state.radius * 0.22;
      const gy = py + Math.sin(az) * state.radius * 0.22;
      const grad = c.createRadialGradient(gx, gy, state.radius * 0.05, x, py, state.radius * 1.05);
      grad.addColorStop(0, rgbCss(hi));
      grad.addColorStop(0.55, rgbCss(base));
      grad.addColorStop(1, rgbCss(lo));
      c.beginPath();
      c.arc(x, py, state.radius, 0, Math.PI * 2);
      c.fillStyle = grad;
      c.fill();
      // wrap edge = the outer boundary itself; it recedes toward the core as
      // radius falls, which is the entire "aliveness" of the shot.
      c.lineWidth = Math.max(1, state.radius * 0.02);
      c.strokeStyle = rgbCss(lo, 0.9);
      c.stroke();
      // fine paper-layer banding: sparse concentric rings, not the spec's
      // literal micro-period (impractical to render distinctly at this
      // scale and cost), tuned for a visible "wound paper" read instead.
      const rings = Math.min(14, Math.max(4, Math.round(state.radius / 8)));
      c.lineWidth = 1;
      for (let i = 1; i < rings; i++) {
        const rr = (state.radius * i) / rings;
        c.beginPath();
        c.arc(x, py, rr, 0, Math.PI * 2);
        c.strokeStyle = rgbCss(i % 2 === 0 ? hi : lo, 0.3);
        c.stroke();
      }
      // core: a roll of paper has a visible hub, and the hub is what tells
      // you the wrap edge is receding toward it as the roll runs down.
      c.beginPath();
      c.arc(x, py, Math.max(3, state.radius * 0.17), 0, Math.PI * 2);
      c.fillStyle = rgbCss(bg, 0.92);
      c.fill();
      c.lineWidth = 1;
      c.strokeStyle = rgbCss(fg, 0.45);
      c.stroke();

      // radial index lines — what makes rotation and RPM legible.
      c.strokeStyle = rgbCss(fg, dark ? 0.55 : 0.4);
      c.lineWidth = Math.max(1, state.radius * 0.035);
      for (let i = 0; i < indexLines; i++) {
        const a = state.angle + (i / indexLines) * Math.PI * 2;
        c.beginPath();
        c.moveTo(x, py);
        c.lineTo(x + Math.cos(a) * state.radius * 0.92, py + Math.sin(a) * state.radius * 0.92);
        c.stroke();
      }
      c.restore();
    };

    const draw = () => {
      if (!colorsReady || cssW <= 0 || cssH <= 0) return;
      const t = staticMode ? STATIC_TIME : simTime;
      const state = rollState(t);

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, cssW, cssH);

      // band separator hairlines — the only legitimate use of --border here.
      ctx.strokeStyle = rgbCss(border);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, 0.5);
      ctx.lineTo(cssW, 0.5);
      ctx.moveTo(0, cssH - 0.5);
      ctx.lineTo(cssW, cssH - 0.5);
      ctx.stroke();

      // The web itself. Without a visible strip of paper leaving the roll
      // there is no ribbon, only marks floating on the band — which is
      // exactly how the first cut read. The web leaves the roll at its wrap
      // edge, so it must end just inside the CURRENT radius: anchored to the
      // stand centre it would jut out past a run-down roll as a bare
      // rectangle, and the strip visibly lengthening as the roll empties is
      // itself part of the run-down read.
      const webEnd = standX - state.radius * 0.35;
      const webH = markSize() * 1.95;
      const paper = paperColor();
      ctx.fillStyle = rgbCss(paper);
      ctx.fillRect(0, cy - webH / 2, webEnd, webH);
      ctx.strokeStyle = rgbCss(mixRGB(paper, BLACK, 0.35), 0.8);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, cy - webH / 2 + 0.5);
      ctx.lineTo(webEnd, cy - webH / 2 + 0.5);
      ctx.moveTo(0, cy + webH / 2 - 0.5);
      ctx.lineTo(webEnd, cy + webH / 2 - 0.5);
      ctx.stroke();

      // ribbon of marks, spawned at the nip and scrolling left at v(t).
      const spc = spacing();
      const ms = markSize();
      const speed = v();
      const firstX = nipX - ((speed * t) % spc);
      let step = 0;
      for (let x = firstX; x > -ms; x -= spc) {
        step += 1;
        const slot = ((Math.round((nipX - x) / spc) % markCount) + markCount) % markCount;
        const seed = markSeeds[slot % markSeeds.length];
        drawMark(ctx, x, cy, ms, seed);
        if (step > 200) break; // pathological-width safety, never hit in practice
      }

      // the stand hardware, then the roll sitting on it.
      const footY = cy + RMAX * 1.18;
      ctx.save();
      ctx.strokeStyle = rgbCss(fg, 0.38);
      ctx.lineWidth = Math.max(2, RMAX * 0.06);
      ctx.beginPath();
      ctx.moveTo(standX, cy);
      ctx.lineTo(standX, footY);
      ctx.stroke();
      ctx.lineWidth = Math.max(1, RMAX * 0.045);
      ctx.beginPath();
      ctx.moveTo(standX - RMAX * 0.42, footY);
      ctx.lineTo(standX + RMAX * 0.42, footY);
      ctx.stroke();
      ctx.restore();

      // The stand's capacity ring: a full roll fills it, and the gap between
      // it and the roll's wrap edge IS the run-down, readable in a single
      // still instead of only across the cycle. Its alpha is tied to that gap,
      // so it fades out entirely as the roll fills: at R_max the dashed ring
      // sits directly on the roll's own wrap-edge stroke and the doubled
      // outline reads as a jagged artefact — for the ~2s centred exactly on
      // the wrap, which is the one moment that has to be unobtrusive.
      ctx.save();
      ctx.globalAlpha = 0.5 * ((RMAX - state.radius) / (RMAX - RMIN));
      ctx.setLineDash([3, 5]);
      ctx.lineWidth = 1;
      ctx.strokeStyle = rgbCss(fg, 0.55);
      ctx.beginPath();
      ctx.arc(standX, cy, RMAX, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();

      drawRoll(ctx, standX, state);

      ctx.restore();
    };

    const loop = (nowMs: number) => {
      const dt = Math.min(0.05, Math.max(0, (nowMs - lastMs) / 1000));
      lastMs = nowMs;
      simTime += dt;
      draw();
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (running || disposed) return;
      running = true;
      lastMs = performance.now();
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const applyBacking = () => {
      if (cssW < 2 || cssH < 2) return;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const pw = Math.round(cssW * dpr);
      const ph = Math.round(cssH * dpr);
      if (canvas.width !== pw || canvas.height !== ph) {
        canvas.width = pw;
        canvas.height = ph;
      }
      canvas.style.width = `${cssW}px`;
      canvas.style.height = `${cssH}px`;
      draw();
    };

    const resize = () => {
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      cssW = rect.width;
      cssH = rect.height;
      computeGeometry();
      applyBacking();
      draw();
    };

    const ro = new ResizeObserver(resize);
    ro.observe(wrap);
    resize(); // ResizeObserver's initial fire path also lands after readColors() above

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const applyMode = () => {
      if (reduced || pausedRef.current) {
        staticMode = true;
        sleep();
        draw();
      } else {
        staticMode = false;
        wake();
      }
    };
    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);

    let onScreen = true;
    const io = new IntersectionObserver(
      (entries) => {
        onScreen = entries.some((en) => en.isIntersecting);
        if (!onScreen) sleep();
        else if (!staticMode && !document.hidden) wake(); // resume path — colors already read at mount
      },
      { threshold: 0 }
    );
    io.observe(wrap);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!staticMode && onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    const themeObserver = new MutationObserver(() => {
      readColors();
      draw();
    });
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let lastPolledPaused = pausedRef.current;
    let poll = 0;
    const tick = () => {
      if (pausedRef.current !== lastPolledPaused) {
        lastPolledPaused = pausedRef.current;
        applyMode();
      }
      poll = window.setTimeout(tick, 140);
    };
    tick();

    applyMode();

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      window.clearTimeout(poll);
      sleep();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      ref={wrapRef}
      className={`relative h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
      role="img"
      aria-label="A single paper roll feeding a ribbon of placeholder logo marks, shrinking and spinning faster as it empties, then rebuilding to full and slowing again"
    >
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
    </div>
  );
}

FlyingSplice.displayName = "FlyingSplice";

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// FooterAsciiRule — a footer whose "back to top" control is an honest
// instrument, not a decoration: an aria-hidden vertical rail beside the
// copyright line always reads real, continuous scroll position (a passive
// scroll listener, not a fixed-duration animation on its own clock), and its
// button drives a real semi-implicit-Euler spring toward scrollY=0 rather
// than a native instant jump or CSS smooth-scroll. Because the rail's
// position comes from window.scrollY every frame, a user who grabs the
// wheel or a key mid-flight sees the car respond to what they're actually
// doing — and the flight itself is cancelled the instant that happens,
// rather than fighting the user for control of the page.
// ---------------------------------------------------------------------------

const RAIL_ROWS = 6;
const SPRING_K = 120;
const SPRING_C = 22;
const SETTLE_POS_EPS = 0.6;
const SETTLE_VEL_EPS = 4;
const SETTLE_MS = 2500;

export interface FooterLinkItem {
  label: string;
  href: string;
}

export interface FooterColumn {
  heading: string;
  links: FooterLinkItem[];
}

export interface FooterAsciiRuleProps {
  /** brand text on the left */
  brand?: string;
  /** the footer's link columns */
  columns: FooterColumn[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function FooterAsciiRule({ brand = "ns-ui", columns, className = "" }: FooterAsciiRuleProps) {
  const railRef = useRef<HTMLPreElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const flightRef = useRef<{ raf: number; cancel: () => void } | null>(null);

  // -- honest readout: the rail always reflects real scroll, all the time --
  useEffect(() => {
    const rail = railRef.current;
    if (!rail) return;

    const paint = () => {
      const doc = document.documentElement;
      const max = Math.max(1, doc.scrollHeight - window.innerHeight);
      const progress = Math.min(1, Math.max(0, window.scrollY / max));
      // progress 0 (at top) -> car at row 0; progress 1 (scrolled away) -> car at last row
      const carRow = Math.round(progress * (RAIL_ROWS - 1));
      const lines: string[] = [];
      for (let i = 0; i < RAIL_ROWS; i++) lines.push(i === carRow ? "●" : "│");
      rail.textContent = lines.join("\n");
    };

    let ticking = false;
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        ticking = false;
        paint();
      });
    };
    paint();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  useEffect(() => {
    return () => flightRef.current?.cancel();
  }, []);

  const backToTop = () => {
    flightRef.current?.cancel();

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      window.scrollTo(0, 0);
      return;
    }

    let y = window.scrollY;
    let v = 0;
    const deadline = performance.now() + SETTLE_MS;
    let raf = 0;
    let cancelled = false;

    const stopInterrupt = () => {
      window.removeEventListener("wheel", onInterrupt);
      window.removeEventListener("touchstart", onInterrupt);
      window.removeEventListener("keydown", onKeyInterrupt);
    };
    const onInterrupt = () => cancel();
    const onKeyInterrupt = (e: KeyboardEvent) => {
      if (["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End", " "].includes(e.key)) cancel();
    };

    function cancel() {
      if (cancelled) return;
      cancelled = true;
      cancelAnimationFrame(raf);
      stopInterrupt();
      flightRef.current = null;
    }

    window.addEventListener("wheel", onInterrupt, { passive: true });
    window.addEventListener("touchstart", onInterrupt, { passive: true });
    window.addEventListener("keydown", onKeyInterrupt);

    let last = performance.now();
    const tick = (now: number) => {
      if (cancelled) return;
      const dt = Math.min(0.032, (now - last) / 1000);
      last = now;
      v += (-SPRING_K * y - SPRING_C * v) * dt;
      y += v * dt;
      const settled = Math.abs(y) < SETTLE_POS_EPS && Math.abs(v) < SETTLE_VEL_EPS;
      if (settled || now >= deadline) {
        window.scrollTo(0, 0);
        cancel();
        return;
      }
      window.scrollTo(0, Math.max(0, y));
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    flightRef.current = { raf, cancel };
  };

  return (
    <footer data-footer-ascii-rule className={`border-t border-border bg-surface ${className}`}>
      <div className="mx-auto max-w-5xl px-4 py-12 sm:px-6">
        <div aria-hidden className="select-none font-mono text-[11px] text-border">
          {"─".repeat(64)}
        </div>

        <div className="mt-8 grid grid-cols-2 gap-8 sm:grid-cols-4">
          {columns.map((col) => (
            <div key={col.heading}>
              <h2 className="font-mono text-xs font-semibold uppercase tracking-[0.15em] text-foreground">
                {col.heading}
              </h2>
              <ul className="mt-3 flex flex-col gap-2">
                {col.links.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      className="rounded-sm text-sm text-ns-muted transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="mt-10 flex items-center justify-between gap-4 border-t border-border pt-6">
          <p className="font-mono text-xs text-ns-muted">
            © {new Date().getFullYear()} {brand}
          </p>

          <button
            ref={buttonRef}
            type="button"
            onClick={backToTop}
            aria-label="Back to top"
            className="group inline-flex items-center gap-2 rounded-sm border border-border px-2.5 py-1.5 font-mono text-xs text-foreground transition-colors hover:border-foreground/25 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            <pre
              ref={railRef}
              aria-hidden
              className="pointer-events-none whitespace-pre text-center leading-[1.1] text-ns-muted transition-colors group-hover:text-ns-accent"
            />
            <span>back to top</span>
          </button>
        </div>
      </div>
    </footer>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FrankRegister — a postal franking meter for paying out of a prepaid wallet.
// Committing stamps an indicium (amount / date / serial) onto an invoice
// while two odometer stacks roll: the descending BALANCE register rolls
// down by exactly the paid amount, the ascending SPENT register rolls up by
// the same amount. The two are never tracked as independent numbers — spent
// is *derived* as (creditsPurchased - balance) every render, so the
// reconciliation invariant (balance + spent === creditsPurchased) holds by
// construction, not by hoping two separately-animated counters stay in
// sync. One `commit(amountCents)` call is the single governing scalar that
// feeds the balance delta, the frank's printed amount, and the die-drop
// trigger — one gear train, not three independent tweens.
//
// ODOMETER MECHANISM: each digit column is a vertically clipped cell over a
// 30-row strip of the sequence 0..9 repeated three times (indices 0-29).
// The "home" band is indices 10-19, where index (10+d) shows digit d. A
// commit computes, per column, a `rest` row (home row for the old digit),
// a `play` row (home row for the new digit, OVERSHOT by +10 if the digit
// wrapped forward, or UNDERSHOT by -10 if it wrapped backward), and a
// `final` row (home row for the new digit, always back in 10-19). The cell
// renders at `rest` while unarmed and `play` once armed, transitioning
// over 400ms; once the transition settles, state snaps instantly (no
// transition) from `play` to `final` — a jump of exactly one strip period,
// so the same digit is on screen before and after and the cut is
// invisible. Because the ascending register's row only ever climbs and the
// descending register's row only ever falls, the two wheel families spin
// in opposite senses from the same 400ms drive — mechanically mirrored,
// not two unrelated tweens. Carries stagger 40ms per column, right-to-left
// (rightmost changed place first), computed the same way as this
// registry's counter-carry-ripple digit diffing, but the visual here is a
// continuous odometer roll, never a single flipped glyph.
//
// Pure DOM + SVG + CSS, no canvas. All ink is token-relative (--background,
// --foreground, --ns-muted, --border; --ns-accent only for the keyboard
// focus ring). Reduced motion snaps every wheel straight to its final
// digit and the die never travels.
// ---------------------------------------------------------------------------

const ROW_EM = 1.15; // one digit row's clipped height
const STRIP_LEN = 30; // three full 0-9 cycles; home band is 10-19
const HOME = 10;
const STRIP = Array.from({ length: STRIP_LEN }, (_, i) => String(i % 10));

const ROLL_MS = 400; // wheel roll duration (one gear train, both registers)
const STAGGER_MS = 40; // per-column carry stagger, right-to-left
const ROLL_EASE = "cubic-bezier(0.65, 0, 0.35, 1)"; // mechanical, not springy

const DIE_DROP_MS = 140;
const DIE_DWELL_MS = 120;
const DIE_RETURN_MS = 180;
const DIE_DROP_EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out-expo
const PRESS_MS = 90; // frank's one-frame press-darken

const MONTHS = [
  "JAN", "FEB", "MAR", "APR", "MAY", "JUN",
  "JUL", "AUG", "SEP", "OCT", "NOV", "DEC",
];

// ---------------------------------------------------------------------------
// money helpers — everything animatable is tracked in integer cents so
// repeated commits can never drift from float rounding.
// ---------------------------------------------------------------------------

function toCents(dollars: number): number {
  return Math.round(Math.max(0, dollars) * 100);
}

function fmt(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function digitAt(cents: number, place: number): number {
  if (place >= 0) {
    const dollars = Math.floor(cents / 100);
    return Math.floor(dollars / 10 ** place) % 10;
  }
  const frac = cents % 100;
  return place === -1 ? Math.floor(frac / 10) % 10 : frac % 10;
}

function formatFrankDate(d: Date): string {
  const day = String(d.getDate()).padStart(2, "0");
  return `${day} ${MONTHS[d.getMonth()]} ${String(d.getFullYear()).slice(-2)}`;
}

// ---------------------------------------------------------------------------
// wheel column model
// ---------------------------------------------------------------------------

interface Col {
  place: number;
  rest: number;
  play: number;
  final: number;
  delay: number;
}

function idleCols(cents: number, places: number[]): Col[] {
  return places.map((place) => {
    const row = HOME + digitAt(cents, place);
    return { place, rest: row, play: row, final: row, delay: 0 };
  });
}

// `dir` fixes which way THIS register is allowed to wrap: "asc" only ever
// carries forward (9 -> 0), "desc" only ever borrows backward (0 -> 9) —
// true for any single addition/subtraction of one amount, which is all a
// single commit ever does.
function commitCols(prevCents: number, nextCents: number, places: number[], dir: "asc" | "desc"): Col[] {
  const changed = places.filter((p) => digitAt(prevCents, p) !== digitAt(nextCents, p));
  const minChanged = changed.length ? Math.min(...changed) : 0;

  return places.map((place) => {
    const d0 = digitAt(prevCents, place);
    const d1 = digitAt(nextCents, place);
    const rest = HOME + d0;
    const final = HOME + d1;
    let play = final;
    if (dir === "asc" && d1 < d0) play = final + STRIP_LEN / 3; // overshoot: carried through 9->0
    if (dir === "desc" && d1 > d0) play = final - STRIP_LEN / 3; // undershoot: borrowed through 0->9
    const delay = changed.includes(place) ? STAGGER_MS * (place - minChanged) : 0;
    return { place, rest, play, final, delay };
  });
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function WheelRow({ cols, armed }: { cols: Col[]; armed: boolean }) {
  return (
    <div aria-hidden="true" className="ns-fr-wheel">
      {cols.map((col) => {
        const row = armed ? col.play : col.rest;
        return (
          <span key={col.place} className="ns-fr-wcell">
            <span
              className="ns-fr-wtrack"
              style={{
                transform: `translateY(-${(row * ROW_EM).toFixed(3)}em)`,
                transition: armed
                  ? `transform ${ROLL_MS}ms ${ROLL_EASE} ${col.delay}ms`
                  : "none",
              }}
            >
              {STRIP.map((d, i) => (
                <span key={i} className="ns-fr-wdigit">
                  {d}
                </span>
              ))}
            </span>
          </span>
        );
      })}
    </div>
  );
}

// ---------------------------------------------------------------------------

export interface FrankRegisterProps {
  /** total credits ever purchased for this wallet — the reconciliation invariant: balance + spent always equals this. */
  creditsPurchased: number;
  /** current balance; supplying this makes the component controlled (pair with onCommit). */
  balance?: number;
  /** starting balance when uncontrolled. @default creditsPurchased */
  defaultBalance?: number;
  /** the amount debited on each commit. */
  amount: number;
  /** what the charge is for, printed above the amount. */
  description?: string;
  /** verb on the commit button, e.g. "Charge" or "Pay". @default "Charge" */
  actionLabel?: string;
  /** fires once a commit lands, with the amount paid and the resulting balance (both in dollars). */
  onCommit?: (amount: number, nextBalance: number) => void;
  /** extra classes merged onto the root element. */
  className?: string;
}

interface Frank {
  amountCents: number;
  date: string;
  serial: string;
}

export function FrankRegister({
  creditsPurchased,
  balance,
  defaultBalance,
  amount,
  description,
  actionLabel = "Charge",
  onCommit,
  className = "",
}: FrankRegisterProps) {
  const creditsCents = toCents(creditsPurchased);
  const isControlled = balance !== undefined;
  const [internalCents, setInternalCents] = useState(() =>
    Math.min(creditsCents, toCents(defaultBalance ?? creditsPurchased))
  );
  const balanceCents = Math.min(
    creditsCents,
    isControlled ? toCents(balance as number) : internalCents
  );
  const spentCents = creditsCents - balanceCents; // derived, not tracked — the invariant can't drift

  if (process.env.NODE_ENV !== "production") {
    console.assert(
      balanceCents + spentCents === creditsCents,
      "frank-register: descending + ascending registers do not reconcile with creditsPurchased"
    );
  }

  const amountCents = toCents(amount);
  const canCommit = amountCents > 0 && amountCents <= balanceCents;

  const intDigits = Math.max(4, String(Math.floor(creditsCents / 100)).length);
  const places = [...Array.from({ length: intDigits }, (_, i) => intDigits - 1 - i), -1, -2];

  const reducedMotion = useReducedMotion();

  const [descCols, setDescCols] = useState<Col[]>(() => idleCols(balanceCents, places));
  const [ascCols, setAscCols] = useState<Col[]>(() => idleCols(spentCents, places));
  const [armed, setArmed] = useState(false);
  const prevBalanceRef = useRef(balanceCents);
  const settleTimer = useRef<number | undefined>(undefined);
  const armRaf = useRef<number | undefined>(undefined);
  const mountedRef = useRef(false);

  useLayoutEffect(() => {
    const prevBalance = prevBalanceRef.current;
    prevBalanceRef.current = balanceCents;

    if (!mountedRef.current) {
      mountedRef.current = true;
      return;
    }
    if (prevBalance === balanceCents) return;

    window.clearTimeout(settleTimer.current);
    if (armRaf.current !== undefined) cancelAnimationFrame(armRaf.current);

    const prevSpent = creditsCents - prevBalance;

    if (reducedMotion) {
      setDescCols(idleCols(balanceCents, places));
      setAscCols(idleCols(spentCents, places));
      setArmed(false);
      return;
    }

    const nextDesc = commitCols(prevBalance, balanceCents, places, "desc");
    const nextAsc = commitCols(prevSpent, spentCents, places, "asc");
    setDescCols(nextDesc);
    setAscCols(nextAsc);
    setArmed(false);

    // two rAFs: the reset above hasn't painted yet this frame, so arming on
    // the very next rAF can collapse the "rest" and "play" frames into one
    // and skip the transition. waiting an extra frame guarantees the rest
    // pose actually painted before the transition is armed.
    armRaf.current = requestAnimationFrame(() => {
      armRaf.current = requestAnimationFrame(() => setArmed(true));
    });

    const maxDelay = Math.max(
      0,
      ...nextDesc.map((c) => c.delay),
      ...nextAsc.map((c) => c.delay)
    );
    settleTimer.current = window.setTimeout(() => {
      setDescCols((cols) => cols.map((c) => ({ ...c, rest: c.final, play: c.final, delay: 0 })));
      setAscCols((cols) => cols.map((c) => ({ ...c, rest: c.final, play: c.final, delay: 0 })));
      setArmed(false);
    }, maxDelay + ROLL_MS + 30);

    return () => {
      if (armRaf.current !== undefined) cancelAnimationFrame(armRaf.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [balanceCents]);

  useEffect(
    () => () => {
      window.clearTimeout(settleTimer.current);
      if (armRaf.current !== undefined) cancelAnimationFrame(armRaf.current);
    },
    []
  );

  const [frank, setFrank] = useState<Frank | null>(null);
  const [batch, setBatch] = useState(0);
  const [diePhase, setDiePhase] = useState<"rest" | "down" | "up">("rest");
  const [announced, setAnnounced] = useState("");
  const serialRef = useRef(0);
  const dieTimers = useRef<number[]>([]);

  const commit = () => {
    if (!canCommit) return;
    const nextBalanceCents = balanceCents - amountCents;
    serialRef.current += 1;
    const now = new Date();
    const nextFrank: Frank = {
      amountCents,
      date: formatFrankDate(now),
      serial: String(serialRef.current).padStart(6, "0"),
    };

    // one commit, one governing scalar (amountCents) feeding the balance
    // update, the frank, and the die trigger together — never three
    // independently-timed writes.
    setFrank(nextFrank);
    setBatch((b) => b + 1);
    if (!isControlled) setInternalCents(nextBalanceCents);
    onCommit?.(amountCents / 100, nextBalanceCents / 100);
    setAnnounced(
      `Stamped — ${fmt(amountCents)}. Balance ${fmt(nextBalanceCents)} remaining, ` +
        `${fmt(creditsCents - nextBalanceCents)} spent to date, registers reconcile.`
    );

    dieTimers.current.forEach((t) => window.clearTimeout(t));
    dieTimers.current = [];
    if (!reducedMotion) {
      setDiePhase("down");
      dieTimers.current.push(
        window.setTimeout(() => setDiePhase("up"), DIE_DROP_MS + DIE_DWELL_MS)
      );
      dieTimers.current.push(
        window.setTimeout(() => setDiePhase("rest"), DIE_DROP_MS + DIE_DWELL_MS + DIE_RETURN_MS)
      );
    }
  };

  useEffect(() => () => dieTimers.current.forEach((t) => window.clearTimeout(t)), []);

  const dieTransform = diePhase === "down" ? "translateY(8px)" : "translateY(0px)";
  const dieTransition =
    reducedMotion || diePhase === "rest"
      ? "none"
      : diePhase === "down"
        ? `transform ${DIE_DROP_MS}ms ${DIE_DROP_EASE}`
        : `transform ${DIE_RETURN_MS}ms ease-in`;

  const frankAlt = frank
    ? `Franking indicium: ${fmt(frank.amountCents)}, stamped ${frank.date}, serial ${frank.serial}`
    : "";

  return (
    <div className={`ns-fr-root ${className}`} data-reduced={reducedMotion || undefined}>
      <div className="ns-fr-card">
        <div className="ns-fr-head">
          <span className="ns-fr-kicker">Invoice</span>
          {description && <span className="ns-fr-desc">{description}</span>}
        </div>

        <div className="ns-fr-amount-row">
          <span className="ns-fr-amount">{fmt(amountCents)}</span>
          <span className="ns-fr-amount-label">due</span>
        </div>

        <div className="ns-fr-stampzone">
          {frank && (
            <svg
              key={batch}
              role="img"
              aria-label={frankAlt}
              viewBox="0 0 168 76"
              className="ns-fr-frank"
              style={{ animationDelay: reducedMotion ? "0ms" : `${DIE_DROP_MS}ms` }}
            >
              <rect x="1" y="1" width="166" height="74" rx="6" className="ns-fr-frank-border" />
              <g transform="translate(38, 38)" className="ns-fr-frank-rosette">
                {Array.from({ length: 12 }, (_, i) => {
                  const a = (i * 30 * Math.PI) / 180;
                  const x1 = Math.cos(a) * 9;
                  const y1 = Math.sin(a) * 9;
                  const x2 = Math.cos(a) * 15;
                  const y2 = Math.sin(a) * 15;
                  return (
                    <line
                      key={i}
                      x1={x1.toFixed(2)}
                      y1={y1.toFixed(2)}
                      x2={x2.toFixed(2)}
                      y2={y2.toFixed(2)}
                      className="ns-fr-frank-ray"
                    />
                  );
                })}
                <circle r="16" className="ns-fr-frank-ring" />
                <circle r="2.5" className="ns-fr-frank-hub" />
              </g>
              <line x1="70" y1="8" x2="70" y2="68" className="ns-fr-frank-div" />
              <text x="80" y="34" className="ns-fr-frank-amt">
                {fmt(frank.amountCents)}
              </text>
              <text x="80" y="49" className="ns-fr-frank-date">
                {frank.date}
              </text>
              <text x="80" y="63" className="ns-fr-frank-serial">
                SER {frank.serial}
              </text>
            </svg>
          )}
        </div>

        <button
          type="button"
          className="ns-fr-die"
          aria-label={`${actionLabel} ${fmt(amountCents)}`}
          disabled={!canCommit}
          onClick={commit}
          style={{ transform: reducedMotion ? undefined : dieTransform, transition: dieTransition }}
        >
          <span aria-hidden="true" className="ns-fr-die-label">
            {actionLabel}
          </span>
          <span aria-hidden="true" className="ns-fr-die-amt">
            {fmt(amountCents)}
          </span>
        </button>
      </div>

      <div className="ns-fr-registers">
        <div className="ns-fr-register">
          <span className="ns-fr-reg-caption">Balance</span>
          <WheelRow cols={descCols} armed={armed} />
          <span className="ns-fr-reg-mirror">{fmt(balanceCents)}</span>
        </div>
        <div className="ns-fr-register">
          <span className="ns-fr-reg-caption">Spent to date</span>
          <WheelRow cols={ascCols} armed={armed} />
          <span className="ns-fr-reg-mirror">{fmt(spentCents)}</span>
        </div>
      </div>

      <p className="ns-fr-reconcile">registers reconcile: {fmt(creditsCents)}</p>

      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announced}
      </div>

      <style>{`
