"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FuseeCone — a burn-rate alert POLICY editor built as a clock fusee. The
// error budget is the mainspring barrel; a chain rides down a tapering cone
// as budget depletes; alert sensitivity at any budget level is the cone's
// local radius at that point. You author the policy by dragging exactly 4
// control points along a monotone cubic spline (Fritsch-Carlson — the
// interpolation itself never overshoots between knots, not just at them),
// never a free-form curve: the spline's y is a burn-rate TRIP MULTIPLIER,
// and it is enforced monotone NON-INCREASING toward the empty end (index 0
// = full budget .. index 3 = exhausted) — a drag or keystroke that would
// raise a point above its predecessor (or lower it below its successor) is
// clamped to that band, the handle audibly/visually springs back, and a
// polite live region explains why. That single constraint is what forbids
// authoring a policy that gets LESS sensitive as budget runs out.
//
// One governing scalar — remaining budget — sets the chain's axial position
// on the cone. "Alert torque" = current burn multiplier x the cone's local
// radius at that position; fired/quiet, the derived multi-window rule
// table, and the chain's drawn catenary sag all come from that product (a
// value fires when the delivered torque exceeds the torque the mechanism
// would carry if burn rate exactly equalled the authored threshold there —
// algebraically just burn >= radius(x), read through the torque lens). The
// rule table is a real <table>, the screen-reader-primary surface, and
// updates only on commit (drag release / keypress), never mid-drag. The
// cone, barrel and chain are aria-hidden SVG+DOM decoration; the 4 control
// points are real role=slider elements. Replay streams a recorded burn-rate
// history through the same mechanism, spinning the barrel and stamping
// where the escapement would have tripped against the CURRENT authored
// policy. Reduced motion: the chain repositions instantly and the barrel
// stops spinning; every value still updates and everything stays usable.
// Colors are token classes only; --ns-accent appears only on drag/focus,
// never as a data-state color. DOM + SVG + CSS only, no canvas.
// ---------------------------------------------------------------------------

export interface FuseeConeProps {
  /**
   * Initial policy: 4 trip-multiplier control points in burn-rate "x"
   * units, index 0 = full-budget end .. index 3 = exhausted end. Each must
   * be <= the one before it (monotone non-increasing); an out-of-order
   * default is silently clamped down on mount rather than crashing.
   * Default [14.4, 6, 2, 1] — the two headline values from the brief.
   */
  defaultProfile?: [number, number, number, number];
  /** Fires when a control-point drag RELEASES or a keystroke commits — never mid-drag. */
  onPolicyChange?: (profile: [number, number, number, number]) => void;
  /** Initial remaining error-budget fraction, 0-100 (100 = full mainspring). */
  defaultRemainingBudgetPct?: number;
  /** Initial observed burn rate, in multiples of nominal (1x = exactly on pace to exhaust the budget at period end). */
  defaultCurrentBurnMultiplier?: number;
  /**
   * Recorded burn-rate history to stream through Replay. remainingBudgetPct
   * should be non-increasing across the array for the barrel to visibly
   * unwind. Falls back to a built-in sample incident.
   */
  replayData?: { remainingBudgetPct: number; burn: number }[];
  /** What SLO this policy protects, shown above the instrument. */
  label?: string;
  /** Extra classes merged onto the rendered root element. */
  className?: string;
}

// ---- geometry / domain constants ------------------------------------------
const CP_X = [0, 1 / 3, 2 / 3, 1] as const; // fixed axial positions of the 4 control points
const MULT_MIN = 1;
const MULT_MAX = 20;
const DEFAULT_PROFILE: [number, number, number, number] = [14.4, 6, 2, 1];

const VIEW_W = 480;
const VIEW_H = 200;
const CY = 100;
const BARREL_CX = 50;
const BARREL_R = 32;
const CONE_X0 = 118;
const CONE_X1 = 452;
const R_MIN_PIX = 3;
const R_MAX_PIX = 62;
const MAX_SAG = 24;
const CONE_SAMPLES = 40;

const TABLE_X = [0, 0.25, 0.5, 0.75, 1];
const TABLE_WINDOW = ["1h", "3h", "12h", "1d", "3d"];

const DEFAULT_REPLAY: { remainingBudgetPct: number; burn: number }[] = [
  { remainingBudgetPct: 100, burn: 1.1 },
  { remainingBudgetPct: 92, burn: 1.4 },
  { remainingBudgetPct: 80, burn: 2.6 },
  { remainingBudgetPct: 68, burn: 4.8 },
  { remainingBudgetPct: 55, burn: 3.2 },
  { remainingBudgetPct: 47, burn: 8.5 },
  { remainingBudgetPct: 40, burn: 2.1 },
  { remainingBudgetPct: 33, burn: 1.6 },
  { remainingBudgetPct: 22, burn: 5.5 },
  { remainingBudgetPct: 14, burn: 2.9 },
  { remainingBudgetPct: 8, burn: 1.3 },
  { remainingBudgetPct: 2, burn: 1.1 },
];

const SPIKE_BURN = 25; // > MULT_MAX: always trips, whatever the policy or budget position — the gate's idempotent target
const REPLAY_STEP_MS = 700;

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function fmt(n: number) {
  if (!Number.isFinite(n)) return "0";
  return n >= 10 ? Math.round(n).toString() : n.toFixed(1);
}

function sanitizeProfile(arr: number[]): [number, number, number, number] {
  const c = arr.map((v) => clamp(v, MULT_MIN, MULT_MAX));
  for (let i = 1; i < 4; i++) c[i] = Math.min(c[i], c[i - 1]);
  return [c[0], c[1], c[2], c[3]];
}

// ---- monotone cubic Hermite (Fritsch-Carlson) ------------------------------
// Guarantees the interpolated curve never overshoots between knots, so a
// monotone non-increasing set of control points always produces a monotone
// non-increasing curve everywhere in between — not just at the 4 points.
function buildTangents(xs: readonly number[], ys: readonly number[]): number[] {
  const n = xs.length;
  const dx: number[] = [];
  const dy: number[] = [];
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    dx.push(xs[i + 1] - xs[i]);
    dy.push(ys[i + 1] - ys[i]);
    m.push(dx[i] === 0 ? 0 : dy[i] / dx[i]);
  }
  const t: number[] = new Array(n);
  t[0] = m[0] ?? 0;
  t[n - 1] = m[n - 2] ?? 0;
  for (let i = 1; i < n - 1; i++) {
    if (m[i - 1] === 0 || m[i] === 0 || m[i - 1] * m[i] < 0) {
      t[i] = 0;
    } else {
      const w1 = 2 * dx[i] + dx[i - 1];
      const w2 = dx[i] + 2 * dx[i - 1];
      t[i] = (w1 + w2) / (w1 / m[i - 1] + w2 / m[i]);
    }
  }
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const tau = 3 / Math.sqrt(s);
      t[i] = tau * a * m[i];
      t[i + 1] = tau * b * m[i];
    }
  }
  return t;
}

function evalHermite(xs: readonly number[], ys: readonly number[], t: number[], x: number): number {
  const n = xs.length;
  let i = 0;
  while (i < n - 2 && x > xs[i + 1]) i++;
  const h = xs[i + 1] - xs[i];
  const s = h === 0 ? 0 : (x - xs[i]) / h;
  const s2 = s * s;
  const s3 = s2 * s;
  const h00 = 2 * s3 - 3 * s2 + 1;
  const h10 = s3 - 2 * s2 + s;
  const h01 = -2 * s3 + 3 * s2;
  const h11 = s3 - s2;
  return h00 * ys[i] + h10 * h * t[i] + h01 * ys[i + 1] + h11 * h * t[i + 1];
}

function buildRadiusFn(ys: readonly number[]) {
  const t = buildTangents(CP_X, ys);
  return (x: number) => evalHermite(CP_X, ys, t, clamp(x, 0, 1));
}

function rPix(value: number) {
  return clamp(
    R_MIN_PIX + ((value - MULT_MIN) / (MULT_MAX - MULT_MIN)) * (R_MAX_PIX - R_MIN_PIX),
    R_MIN_PIX,
    R_MAX_PIX
  );
}

function screenX(x: number) {
  return CONE_X0 + clamp(x, 0, 1) * (CONE_X1 - CONE_X0);
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function FuseeCone({
  defaultProfile,
  onPolicyChange,
  defaultRemainingBudgetPct = 100,
  defaultCurrentBurnMultiplier = 3,
  replayData,
  label = "Checkout latency SLO",
  className = "",
}: FuseeConeProps) {
  const uid = useId();
  const reduced = useReducedMotion();

  const [profile, setProfile] = useState<[number, number, number, number]>(() =>
    sanitizeProfile(defaultProfile ?? DEFAULT_PROFILE)
  );
  const [remainingPct, setRemainingPct] = useState(clamp(defaultRemainingBudgetPct, 0, 100));
  const [burn, setBurn] = useState(Math.max(0, defaultCurrentBurnMultiplier));

  const [dragIndex, setDragIndex] = useState<number | null>(null);
  const [dragPreviewValue, setDragPreviewValue] = useState<number | null>(null);
  const [springBackIndex, setSpringBackIndex] = useState<number | null>(null);
  const [announce, setAnnounce] = useState("");
  const [replaying, setReplaying] = useState(false);
  const [tripLog, setTripLog] = useState<string[]>([]);

  const trackRefs = useRef<(HTMLDivElement | null)[]>([null, null, null, null]);
  const gestureAnnouncedRef = useRef(false);
  const springTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const replayTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const replayIndexRef = useRef(0);
  const firedPrevRef = useRef<boolean | null>(null);

  useEffect(
    () => () => {
      if (springTimeoutRef.current) clearTimeout(springTimeoutRef.current);
      if (replayTimerRef.current) clearInterval(replayTimerRef.current);
    },
    []
  );

  // committed policy — feeds the <table> (updated on commit only) and replay's trip test
  const radiusFn = useMemo(() => buildRadiusFn(profile), [profile]);

  // live policy — feeds the drawn cone/chain, reacting mid-drag so the shape
  // being argued about is always what's on screen, even before release
  const effectiveProfile = useMemo<[number, number, number, number]>(() => {
    if (dragIndex === null || dragPreviewValue === null) return profile;
    const next = [...profile] as [number, number, number, number];
    next[dragIndex] = dragPreviewValue;
    return next;
  }, [profile, dragIndex, dragPreviewValue]);
  const liveRadiusFn = useMemo(() => buildRadiusFn(effectiveProfile), [effectiveProfile]);

  const xCurrent = clamp(1 - remainingPct / 100, 0, 1);
  const radiusAtCurrent = liveRadiusFn(xCurrent);
  const ratio = radiusAtCurrent > 0 ? burn / radiusAtCurrent : Infinity;
  const torque = burn * radiusAtCurrent;
  const fired = ratio >= 1;

  // edge-triggered announcement on the escapement's own state changing —
  // not on every burn/budget tick, only the crossing itself
  useEffect(() => {
    if (firedPrevRef.current === null) {
      firedPrevRef.current = fired;
      return;
    }
    if (firedPrevRef.current !== fired) {
      firedPrevRef.current = fired;
      setAnnounce(
        fired
          ? `Escapement tripped — burn ${fmt(burn)}x meets or exceeds the ${fmt(radiusAtCurrent)}x threshold at ${Math.round(remainingPct)}% budget remaining.`
          : `Quiet — burn ${fmt(burn)}x is back under the ${fmt(radiusAtCurrent)}x threshold.`
      );
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fired]);

  const commitProfile = useCallback(
    (index: number, value: number) => {
      setProfile((prev) => {
        const next = [...prev] as [number, number, number, number];
        next[index] = value;
        onPolicyChange?.(next);
        return next;
      });
    },
    [onPolicyChange]
  );

  const triggerSpringBack = useCallback((index: number, dir: "above" | "below") => {
    setSpringBackIndex(index);
    if (springTimeoutRef.current) clearTimeout(springTimeoutRef.current);
    springTimeoutRef.current = setTimeout(() => setSpringBackIndex(null), 220);
    if (!gestureAnnouncedRef.current) {
      gestureAnnouncedRef.current = true;
      setAnnounce(
        dir === "above"
          ? "Cannot raise this point above the previous one."
          : "Cannot lower this point below the next one."
      );
    }
  }, []);

  const bandMax = useCallback((i: number) => (i > 0 ? profile[i - 1] : MULT_MAX), [profile]);
  const bandMin = useCallback((i: number) => (i < 3 ? profile[i + 1] : MULT_MIN), [profile]);

  const updateFromClientY = useCallback(
    (index: number, clientY: number) => {
      const el = trackRefs.current[index];
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const frac = clamp((clientY - rect.top) / rect.height, 0, 1);
      const viewY = frac * VIEW_H;
      const wantedPix = clamp(CY - viewY, R_MIN_PIX, R_MAX_PIX);
      const wantedValue =
        MULT_MIN + ((wantedPix - R_MIN_PIX) / (R_MAX_PIX - R_MIN_PIX)) * (MULT_MAX - MULT_MIN);
      const lo = bandMin(index);
      const hi = bandMax(index);
      const clamped = clamp(wantedValue, lo, hi);
      if (Math.abs(clamped - wantedValue) > 1e-6) {
        triggerSpringBack(index, wantedValue > hi ? "above" : "below");
      }
      setDragPreviewValue(clamped);
    },
    [bandMin, bandMax, triggerSpringBack]
  );

  const onPointerDown = (index: number) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (replaying) return;
    e.preventDefault();
    gestureAnnouncedRef.current = false;
    trackRefs.current[index]?.setPointerCapture(e.pointerId);
    setDragIndex(index);
    setDragPreviewValue(profile[index]);
    updateFromClientY(index, e.clientY);
  };

  const onPointerMove = (index: number) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (dragIndex !== index) return;
    updateFromClientY(index, e.clientY);
  };

  const endDrag = (index: number) => () => {
    if (dragIndex !== index) return;
    setDragIndex(null);
    if (dragPreviewValue !== null) commitProfile(index, dragPreviewValue);
    setDragPreviewValue(null);
  };

  const onKeyDown = (index: number) => (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (replaying) return;
    const cur = profile[index];
    const lo = bandMin(index);
    const hi = bandMax(index);
    const STEP = 1.15;
    let next = cur;
    switch (e.key) {
      case "ArrowUp":
      case "ArrowRight":
        next = cur * STEP;
        break;
      case "ArrowDown":
      case "ArrowLeft":
        next = cur / STEP;
        break;
      case "PageUp":
        next = cur * STEP * STEP;
        break;
      case "PageDown":
        next = cur / (STEP * STEP);
        break;
      case "Home":
        next = lo;
        break;
      case "End":
        next = hi;
        break;
      default:
        return;
    }
    e.preventDefault();
    gestureAnnouncedRef.current = false;
    const clamped = clamp(next, lo, hi);
    if (Math.abs(clamped - next) > 1e-6) {
      triggerSpringBack(index, next > hi ? "above" : "below");
    }
    commitProfile(index, clamped);
  };

  const stopReplay = useCallback(() => {
    if (replayTimerRef.current) {
      clearInterval(replayTimerRef.current);
      replayTimerRef.current = null;
    }
    setReplaying(false);
  }, []);

  const startReplay = useCallback(() => {
    const data = replayData && replayData.length > 0 ? replayData : DEFAULT_REPLAY;
    replayIndexRef.current = 0;
    setTripLog([]);
    setReplaying(true);
    const stepOnce = () => {
      const sample = data[replayIndexRef.current];
      if (!sample) {
        stopReplay();
        return;
      }
      setRemainingPct(sample.remainingBudgetPct);
      setBurn(sample.burn);
      const x = clamp(1 - sample.remainingBudgetPct / 100, 0, 1);
      const threshold = radiusFn(x);
      if (sample.burn >= threshold) {
        const line = `Would have tripped at ${Math.round(sample.remainingBudgetPct)}% budget remaining — burn ${fmt(sample.burn)}x >= ${fmt(threshold)}x threshold.`;
        setTripLog((log) => [...log, line]);
        setAnnounce(line);
      }
      replayIndexRef.current += 1;
      if (replayIndexRef.current >= data.length) stopReplay();
    };
    stepOnce();
    replayTimerRef.current = setInterval(stepOnce, REPLAY_STEP_MS);
  }, [replayData, radiusFn, stopReplay]);

  // ---- diagram geometry -----------------------------------------------
  const conePoints = useMemo(() => {
    const pts: { sx: number; r: number }[] = [];
    for (let k = 0; k < CONE_SAMPLES; k++) {
      const x = k / (CONE_SAMPLES - 1);
      pts.push({ sx: screenX(x), r: rPix(liveRadiusFn(x)) });
    }
    return pts;
  }, [liveRadiusFn]);
  const coneTopD = "M " + conePoints.map((p) => `${p.sx.toFixed(1)},${(CY - p.r).toFixed(1)}`).join(" L ");
  const coneBottomD = "M " + conePoints.map((p) => `${p.sx.toFixed(1)},${(CY + p.r).toFixed(1)}`).join(" L ");

  const barrelAngle = (100 - remainingPct) * 10.8; // 3 full turns across the whole budget
  const tickX2 = BARREL_CX + (BARREL_R - 5);
  const tickY2 = CY;

  const contactX = screenX(xCurrent);
  const contactY = CY - rPix(radiusAtCurrent);
  const barrelRimX = BARREL_CX + BARREL_R;
  const barrelRimY = CY;
  const sagFrac = clamp(1 - Math.min(ratio, 1), 0.08, 1);
  const sagPix = sagFrac * MAX_SAG;
  const chainMidX = (barrelRimX + contactX) / 2;
  const chainMidY = (barrelRimY + contactY) / 2 + sagPix;
  const chainD = `M ${barrelRimX},${barrelRimY} Q ${chainMidX.toFixed(1)},${chainMidY.toFixed(1)} ${contactX.toFixed(1)},${contactY.toFixed(1)}`;

  const chainTransition = reduced ? "none" : "d 240ms cubic-bezier(0.16,1,0.3,1)";
  const barrelTransition = reduced ? "none" : "transform 480ms cubic-bezier(0.16,1,0.3,1)";

  const handleTransition = (i: number) =>
    reduced || dragIndex === i ? "none" : "top 220ms cubic-bezier(0.34,1.56,0.64,1)";

  const labelId = `${uid}-label`;
  const descId = `${uid}-desc`;

  return (
    <div className={className}>
      <style>{`
.ns-fusee-chain{transition-property:d}
.ns-fusee-barrel-tick{transition-property:transform}
@keyframes ns-fusee-springback{
  0%{transform:translate(-50%,-50%) scale(1)}
  35%{transform:translate(-50%,-50%) scale(1.4)}
  100%{transform:translate(-50%,-50%) scale(1)}
}
.ns-fusee-springback{animation:ns-fusee-springback 220ms cubic-bezier(0.34,1.56,0.64,1)}
@media (prefers-reduced-motion: reduce){
  .ns-fusee-chain,.ns-fusee-barrel-tick{transition:none !important}
  .ns-fusee-springback{animation:none !important}
}
`}</style>

      <div className="flex items-baseline justify-between gap-3">
        <span id={labelId} className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        {fired ? (
          <span
            data-fusee-fired-badge
            className="rounded-full border border-foreground bg-foreground px-2 py-0.5 font-mono text-[10px] font-semibold tracking-wide text-background"
          >
            TRIPPED
          </span>
        ) : (
          <span
            data-fusee-quiet-badge
            className="rounded-full border border-border px-2 py-0.5 font-mono text-[10px] tracking-wide text-ns-muted"
          >
            QUIET
          </span>
        )}
      </div>

      <p className="mt-1 font-mono text-[11px] text-ns-muted">
        burn {fmt(burn)}x · {Math.round(remainingPct)}% budget remaining · needs {fmt(radiusAtCurrent)}x here
      </p>

      {/* diagram: barrel + cone + chain — decorative, all state lives in the sliders below */}
      <div className="relative mt-3 w-full" style={{ aspectRatio: `${VIEW_W} / ${VIEW_H}` }} aria-hidden>
        <svg viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} className="h-full w-full" focusable="false">
          <circle cx={BARREL_CX} cy={CY} r={BARREL_R} fill="none" className="stroke-current text-border" strokeWidth={1.5} />
          <g
            className="ns-fusee-barrel-tick"
            style={{ transformOrigin: `${BARREL_CX}px ${CY}px`, transform: `rotate(${barrelAngle}deg)`, transition: barrelTransition }}
          >
            <line
              x1={BARREL_CX}
              y1={CY}
              x2={tickX2}
              y2={tickY2}
              className="stroke-current text-ns-muted"
              strokeWidth={2}
              strokeLinecap="round"
            />
          </g>

          <path d={coneTopD} fill="none" className="stroke-current text-foreground" strokeWidth={1.5} strokeLinecap="round" />
          <path d={coneBottomD} fill="none" className="stroke-current text-foreground" strokeWidth={1.5} strokeLinecap="round" />

          <path
            d={chainD}
            fill="none"
            className="ns-fusee-chain stroke-current text-ns-muted"
            strokeWidth={2}
            strokeLinecap="round"
            style={{ transition: chainTransition }}
          />

          <circle
            cx={contactX}
            cy={contactY}
            r={4.5}
            className={fired ? "fill-current text-foreground" : "fill-none stroke-current text-border"}
            strokeWidth={fired ? 0 : 1.5}
          />
        </svg>

        {/* 4 control points — the entire accessible/interactive surface of the diagram */}
        {CP_X.map((cx, i) => {
          const val = dragIndex === i && dragPreviewValue !== null ? dragPreviewValue : profile[i];
          const yFrac = (CY - rPix(val)) / VIEW_H;
          const budgetPct = Math.round((1 - cx) * 100);
          return (
            <div
              key={i}
              ref={(el) => {
                trackRefs.current[i] = el;
              }}
              data-fusee-track={i}
              className={`absolute top-0 h-full w-9 -translate-x-1/2 touch-none select-none ${replaying ? "" : "cursor-ns-resize"}`}
              style={{ left: `${(screenX(cx) / VIEW_W) * 100}%` }}
              onPointerDown={onPointerDown(i)}
              onPointerMove={onPointerMove(i)}
              onPointerUp={endDrag(i)}
              onPointerCancel={endDrag(i)}
              onLostPointerCapture={endDrag(i)}
            >
              <div
                role="slider"
                tabIndex={0}
                aria-label={`Alert sensitivity control point ${i + 1} of 4`}
                aria-orientation="vertical"
                aria-valuemin={Number(bandMin(i).toFixed(2))}
                aria-valuemax={Number(bandMax(i).toFixed(2))}
                aria-valuenow={Number(val.toFixed(2))}
                aria-valuetext={`at ${budgetPct}% budget remaining, alert at ${val.toFixed(1)}x burn`}
                aria-disabled={replaying || undefined}
                onKeyDown={onKeyDown(i)}
                className={`absolute left-1/2 h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
                  dragIndex === i ? "border-ns-accent bg-ns-accent" : "border-foreground/70 bg-background hover:border-foreground"
                } ${springBackIndex === i ? "ns-fusee-springback" : ""}`}
                style={{ top: `${yFrac * 100}%`, transition: handleTransition(i) }}
              />
            </div>
          );
        })}
      </div>

      {/* manual scrub controls — the governing scalars, disabled while replay owns them */}
      <div className="mt-4 grid grid-cols-2 gap-3">
        <label className="block">
          <span className="font-mono text-[10px] tracking-wide text-ns-muted">REMAINING BUDGET</span>
          <input
            type="range"
            min={0}
            max={100}
            step={1}
            value={Math.round(remainingPct)}
            disabled={replaying}
            onChange={(e) => setRemainingPct(Number(e.target.value))}
            aria-label="Remaining error budget percent"
            className="mt-1 w-full accent-ns-accent disabled:opacity-40"
          />
        </label>
        <label className="block">
          <span className="font-mono text-[10px] tracking-wide text-ns-muted">CURRENT BURN RATE</span>
          <input
            type="range"
            min={0}
            max={20}
            step={0.1}
            value={burn}
            disabled={replaying}
            onChange={(e) => setBurn(Number(e.target.value))}
            aria-label="Current observed burn rate multiplier"
            className="mt-1 w-full accent-ns-accent disabled:opacity-40"
          />
        </label>
      </div>

      <div className="mt-3 flex items-center gap-2">
        <button
          type="button"
          data-fusee-replay-toggle
          aria-pressed={replaying}
          onClick={() => (replaying ? stopReplay() : startReplay())}
          className="rounded-sm border border-border px-3 py-1.5 font-mono text-[11px] tracking-widest text-ns-muted transition-colors duration-200 hover:border-foreground/40 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          {replaying ? "STOP REPLAY" : "REPLAY"}
        </button>
        <button
          type="button"
          data-fusee-firetest
          disabled={replaying}
          onClick={() => setBurn(SPIKE_BURN)}
          className="rounded-sm border border-border px-3 py-1.5 font-mono text-[11px] tracking-widest text-ns-muted transition-colors duration-200 hover:border-foreground/40 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-40"
        >
          PREVIEW SPIKE
        </button>
      </div>

      {/* derived rule table — real HTML table, the screen-reader-primary surface */}
      <div className="mt-4 overflow-x-auto rounded-md border border-border">
        <table className="w-full border-collapse font-mono text-[11px]">
          <caption className="sr-only">Derived multi-window burn-rate alert rule table for {label}</caption>
          <thead>
            <tr className="border-b border-border text-left text-ns-muted">
              <th scope="col" className="px-3 py-2 font-medium">
                Budget remaining
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                Window
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                Burn multiplier
              </th>
            </tr>
          </thead>
          <tbody>
            {TABLE_X.map((x, i) => (
              <tr key={x} className={i === TABLE_X.length - 1 ? "" : "border-b border-border"}>
                <td className="px-3 py-1.5 text-foreground tabular-nums">{Math.round((1 - x) * 100)}%</td>
                <td className="px-3 py-1.5 text-foreground tabular-nums">{TABLE_WINDOW[i]}</td>
                <td className="px-3 py-1.5 text-foreground tabular-nums">{fmt(radiusFn(x))}x</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p id={descId} className="mt-2 font-mono text-[11px] text-ns-muted">
        {fired
          ? `Tripped: burn ${fmt(burn)}x meets or exceeds the ${fmt(radiusAtCurrent)}x threshold at ${Math.round(remainingPct)}% budget remaining.`
          : `Quiet: burn ${fmt(burn)}x is under the ${fmt(radiusAtCurrent)}x threshold at ${Math.round(remainingPct)}% budget remaining.`}
      </p>

      {tripLog.length > 0 ? (
        <ul className="mt-2 space-y-0.5 font-mono text-[10px] text-ns-muted">
          {tripLog.slice(-4).map((line, i) => (
            <li key={i}>{line}</li>
          ))}
        </ul>
      ) : null}

      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GalleryAsciiGradientOrientation — a gallery grid whose tiles stand in for
// photographic content with self-generated imagery: each tile runs its own
// 3-octave value-noise loop (same wave-octave family as background-ascii-
// plasma) into a small offscreen scalar buffer, mulberry32-seeded per tile
// index so every tile settles into a distinct, phase-locked drifting field
// instead of all nine looking identical. A 3x3 SOBEL operator on that raw
// buffer — never on rendered pixels — gives every glyph cell a gradient
// ANGLE, bucketed into '-', '/', '|', '\' the same 4-way slope split
// background-ascii-flow uses for velocity heading. This is a categorically
// different input: flow keys the alphabet to a simulated field's direction
// of TRAVEL, this keys it to a generated image's own gradient NORMAL,
// recomputed from the noise scalar every frame. Only the strongest ~12% of
// cells by magnitude survive an adaptive per-frame percentile cut (never a
// fixed threshold — sparsity has to track the scene's own shifting local
// contrast), so the field reads as a moving edge sketch, not a wash. The
// buffer is supersampled ~3x the glyph grid's own resolution so the Sobel
// estimate isn't degenerate at 1:1 with the glyph pitch. Color never
// touches the buffer: every cell's selection and angle are decided on the
// bare 0..1 scalar array, and --foreground is assigned only at the final
// glyph-draw step — so edge selection is byte-identical between themes.
// ---------------------------------------------------------------------------

const DIR_CHARS = ["-", "/", "|", "\\"] as const;
const SUPERSAMPLE = 3; // buffer cells per glyph cell, each axis
const TOP_PERCENT = 0.12; // fraction of cells kept after the magnitude cut
const FIELD_SPEED = 0.5; // t units / s

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// three summed sine octaves, same family as background-ascii-plasma's
// fieldValue: a slow isotropic swell, a mid-frequency crossing band, a fast
// fine ripple — offset per axis by a mulberry32-drawn phase so each tile's
// field is a distinct variant of the same recipe, never a copy.
function fieldValue(x: number, y: number, t: number, px: number, py: number, pt: number): number {
  const xx = x + px;
  const yy = y + py;
  const tt = t + pt;
  const a = Math.sin(xx * 0.5 + tt * 0.7) + Math.sin(yy * 0.46 - tt * 0.55) + Math.sin((xx - yy) * 0.33 + tt * 0.4);
  const b = Math.sin(xx * 1.35 - tt * 1.4) + Math.sin(yy * 1.1 + tt * 1.1);
  const c = Math.sin(xx * 2.5 + yy * 2.1 + tt * 2.6) + Math.sin((xx + yy) * 2.8 - tt * 3.1);
  const v = a * 0.5 + b * 0.32 + c * 0.18;
  return v / 5 + 0.5; // rough-normalize to ~0..1
}

function dirChar(gx: number, gy: number): string {
  // angle of the gradient VECTOR itself, folded to [0, PI) since an edge's
  // orientation is undirected — same fold+bucket background-ascii-flow uses
  // for velocity heading, applied here to a gradient normal instead.
  let a = Math.atan2(gy, gx) % Math.PI;
  if (a < 0) a += Math.PI;
  const idx = Math.round(a / (Math.PI / 4)) % 4;
  return DIR_CHARS[idx]!;
}

interface Tile {
  seed: number;
  px: number;
  py: number;
  pt: number;
}

interface TileGeom {
  cellW: number;
  cellH: number;
  cols: number;
  rows: number;
  bufW: number;
  bufH: number;
  field: Float32Array;
  gx: Float32Array;
  gy: Float32Array;
  mag: Float32Array;
  sizedW: number;
  sizedH: number;
}

export interface GalleryAsciiGradientOrientationProps {
  /** number of generated tiles */
  tileCount?: number;
  /** grid columns at the default breakpoint */
  columns?: number;
  /** glyph grid cell size in px */
  cellSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GalleryAsciiGradientOrientation({
  tileCount = 9,
  columns = 3,
  cellSize = 9,
  className = "",
}: GalleryAsciiGradientOrientationProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRefs = useRef<(HTMLCanvasElement | null)[]>([]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "currentColor";
    let disposed = false;
    let ready = false;
    let raf = 0;
    let last = 0;
    let t = 0;

    const tiles: Tile[] = Array.from({ length: tileCount }, (_, i) => {
      // mulberry32 seeded per tile index -> the phase draw itself is the
      // "per tile position" seed: distinct tiles never share a field.
      const rand = mulberry32(0x9e3779b1 ^ (i * 0x2545f491 + 1));
      return {
        seed: i,
        px: rand() * 1000,
        py: rand() * 1000,
        pt: rand() * 1000,
      };
    });

    const geoms: (TileGeom | null)[] = new Array(tileCount).fill(null);

    const readTokens = () => {
      fg = getComputedStyle(document.documentElement).getPropertyValue("--foreground").trim() || fg;
    };

    // measured post-fonts.ready, off-DOM — a fallback-font advance width
    // bakes in the wrong grid ratio otherwise.
    const measureCell = () => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return { cellW: cellSize, cellH: cellSize };
      const fontFamily = getComputedStyle(container).fontFamily || "ui-monospace, monospace";
      octx.font = `${cellSize}px ${fontFamily}`;
      const cellW = Math.max(3, octx.measureText("MMMMMMMMMM").width / 10);
      return { cellW, cellH: cellSize };
    };

    const buildGeom = (canvas: HTMLCanvasElement): TileGeom | null => {
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;
      if (width < 4 || height < 4) return null;
      const { cellW, cellH } = measureCell();
      const cols = Math.max(2, Math.floor(width / cellW));
      const rows = Math.max(2, Math.floor(height / cellH));
      const bufW = cols * SUPERSAMPLE + 2; // +2 border for the Sobel kernel
      const bufH = rows * SUPERSAMPLE + 2;
      return {
        cellW,
        cellH,
        cols,
        rows,
        bufW,
        bufH,
        field: new Float32Array(bufW * bufH),
        gx: new Float32Array(cols * rows),
        gy: new Float32Array(cols * rows),
        mag: new Float32Array(cols * rows),
        sizedW: width,
        sizedH: height,
      };
    };

    const sizeCanvas = (canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D, geom: TileGeom) => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(geom.sizedW * dpr));
      canvas.height = Math.max(1, Math.round(geom.sizedH * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily || "ui-monospace, monospace";
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
    };

    const resizeAll = () => {
      let anySized = false;
      canvasRefs.current.forEach((canvas, i) => {
        if (!canvas) return;
        const geom = buildGeom(canvas);
        geoms[i] = geom;
        if (!geom) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        sizeCanvas(canvas, ctx, geom);
        anySized = true;
      });
      return anySized;
    };

    // Sobel + adaptive-threshold + draw for one tile at time `tt`. Every
    // step reads the raw Float32Array noise buffer directly — never
    // ctx.getImageData — so the two themes select byte-identical cells;
    // color is assigned only in the final fillText loop.
    const renderTile = (canvas: HTMLCanvasElement, tile: Tile, geom: TileGeom, tt: number) => {
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      const { cellW, cellH, cols, rows, bufW, bufH, field, gx, gy, mag } = geom;

      // fill the raw noise scalar buffer, one field sample per supersampled
      // cell (buffer coords run -1..cols*SUPERSAMPLE so the Sobel kernel has
      // a real neighbor on every edge cell it evaluates).
      for (let by = 0; by < bufH; by++) {
        const ny = ((by - 1) / (rows * SUPERSAMPLE)) * rows;
        for (let bx = 0; bx < bufW; bx++) {
          const nx = ((bx - 1) / (cols * SUPERSAMPLE)) * cols;
          field[by * bufW + bx] = fieldValue(nx, ny, tt, tile.px, tile.py, tile.pt);
        }
      }

      // 3x3 Sobel over the raw scalar buffer, aggregated (vector-summed) per
      // glyph cell's SUPERSAMPLE x SUPERSAMPLE block so the gradient
      // estimate isn't degenerate at 1:1 with the glyph pitch.
      let maxMag = 1e-6;
      for (let gyi = 0; gyi < rows; gyi++) {
        for (let gxi = 0; gxi < cols; gxi++) {
          let sumGx = 0;
          let sumGy = 0;
          for (let dy = 0; dy < SUPERSAMPLE; dy++) {
            for (let dx = 0; dx < SUPERSAMPLE; dx++) {
              // +1 shifts into the padded buffer; the 3x3 kernel then always
              // has a real neighbor in every direction.
              const cx = gxi * SUPERSAMPLE + dx + 1;
              const cy = gyi * SUPERSAMPLE + dy + 1;
              const tl = field[(cy - 1) * bufW + (cx - 1)]!;
              const tc = field[(cy - 1) * bufW + cx]!;
              const tr = field[(cy - 1) * bufW + (cx + 1)]!;
              const ml = field[cy * bufW + (cx - 1)]!;
              const mr = field[cy * bufW + (cx + 1)]!;
              const bl = field[(cy + 1) * bufW + (cx - 1)]!;
              const bc = field[(cy + 1) * bufW + cx]!;
              const br = field[(cy + 1) * bufW + (cx + 1)]!;
              sumGx += -tl + tr - 2 * ml + 2 * mr - bl + br;
              sumGy += -tl - 2 * tc - tr + bl + 2 * bc + br;
            }
          }
          const idx = gyi * cols + gxi;
          gx[idx] = sumGx;
          gy[idx] = sumGy;
          const m = Math.hypot(sumGx, sumGy);
          mag[idx] = m;
          if (m > maxMag) maxMag = m;
        }
      }

      // adaptive percentile cut: recomputed every frame over this tile's own
      // magnitude distribution, so sparsity tracks the field's own shifting
      // local contrast rather than a fixed cutoff.
      const cellCount = cols * rows;
      const sorted = Array.from(mag).sort((a, b) => a - b);
      const cutIdx = Math.min(cellCount - 1, Math.floor(cellCount * (1 - TOP_PERCENT)));
      const threshold = sorted[cutIdx] ?? 0;

      ctx.clearRect(0, 0, geom.sizedW, geom.sizedH);
      ctx.fillStyle = fg;
      for (let gyi = 0; gyi < rows; gyi++) {
        for (let gxi = 0; gxi < cols; gxi++) {
          const idx = gyi * cols + gxi;
          if (mag[idx]! < threshold) continue;
          const ch = dirChar(gx[idx]!, gy[idx]!);
          ctx.fillText(ch, gxi * cellW + cellW / 2, gyi * cellH + cellH / 2);
        }
      }
    };

    const drawAll = (tt: number) => {
      canvasRefs.current.forEach((canvas, i) => {
        const geom = geoms[i];
        if (!canvas || !geom) return;
        renderTile(canvas, tiles[i]!, geom, tt);
      });
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        if (resizeAll() && reduced) drawAll(0);
      }, 150);
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt * FIELD_SPEED;
      drawAll(t);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) drawAll(0);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const ro = new ResizeObserver(() => onResize());
    ro.observe(container);

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resizeAll();
      ready = true;
      if (reduced) {
        // freeze at t=0: the mulberry32 seed guarantees per-tile structure
        // from frame one, so t=0 is never a degenerate all-flat frame.
        drawAll(0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tileCount, cellSize]);

  return (
    <div
      ref={containerRef}
      className={`grid gap-3 font-mono ${className}`}
      style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
    >
      {Array.from({ length: tileCount }, (_, i) => (
        <button
          key={i}
          type="button"
          aria-label={`Gallery item ${i + 1}: generative edge-sketch pattern`}
          className="relative aspect-square overflow-hidden rounded-md border border-border outline-none transition-colors hover:border-ns-accent focus-visible:border-ns-accent focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          <canvas
            ref={(el) => {
              canvasRefs.current[i] = el;
            }}
            aria-hidden
            className="block h-full w-full"
          />
        </button>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// CausticCoverflow — 3D coverflow gallery whose cards sit behind frosted
// glass running a lightweight caustic-light simulation. Three drifting light
// pools (Lissajous paths, 7s/11s/13s periods) refract across each pane —
// drawn into a quarter-resolution buffer and upscaled with image smoothing
// for soft pool edges. Drag velocity drives chromatic aberration on the
// focused card's border (red/blue channel restrokes) that decays to zero at
// rest under a forced-settle deadline. Direct-DOM rAF: React renders once,
// the loop is the sole writer of transforms and canvas frames.
// ---------------------------------------------------------------------------

type RGB = { r: number; g: number; b: number };

function parseColor(raw: string): RGB | null {
  const v = raw.trim();
  if (v.startsWith("#")) {
    const hex = v.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    return null;
  }
  const m = v.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i);
  if (!m) return null;
  return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
}

function mixRGB(a: RGB, b: RGB, t: number): RGB {
  return {
    r: a.r + (b.r - a.r) * t,
    g: a.g + (b.g - a.g) * t,
    b: a.b + (b.b - a.b) * t,
  };
}

// deterministic 2-octave value noise for the generated thumbs — no deps
function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.62 * vnoise(x, y) + 0.38 * vnoise(x * 2.3 + 19.7, y * 2.3 + 7.3);
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}
function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}
function rrectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number
) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// coverflow pose for a card at signed index distance d from the focus point:
// center card scale 1, sides rotateY ±35° / scale 0.82, x-spacing in px,
// translateZ -60px per index of distance. Offsets from the stage center —
// never absolute coords (the -50%,-50% anchor does the centering).
function cardTransform(d: number, spacing: number) {
  const a = clamp(d, -1, 1);
  const rot = -35 * a;
  const scale = 1 - 0.18 * Math.min(1, Math.abs(d));
  const dx = d * spacing;
  const z = -60 * Math.abs(d);
  return `translate(-50%, -50%) translateX(${dx.toFixed(2)}px) translateZ(${z.toFixed(
    1
  )}px) rotateY(${rot.toFixed(2)}deg) scale(${scale.toFixed(4)})`;
}

export type CausticCoverflowItem = {
  /** card title, Geist Sans */
  title: string;
  /** mono meta line (date + index); auto-numbered when omitted */
  meta?: string;
  /** seed for the generated abstract thumb + caustic phases */
  seed?: number;
};

const DEFAULT_ITEMS: CausticCoverflowItem[] = [
  { title: "Meltwater channel, dawn", meta: "JAN 07 · 01" },
  { title: "Condensation study", meta: "JAN 19 · 02" },
  { title: "Caustic net, tank 4", meta: "FEB 02 · 03" },
  { title: "Refraction drift", meta: "FEB 21 · 04" },
  { title: "Surface tension map", meta: "MAR 05 · 05" },
  { title: "Foam decay series", meta: "MAR 18 · 06" },
  { title: "Light pool census", meta: "APR 02 · 07" },
];

// Lissajous pools: periods 7s / 11s / 13s, incommensurate x/y ratios so the
// paths never close, foreground-ink alphas in the 0.05–0.10 band
const POOLS = [
  { T: 7, rx: 1.0, ry: 1.31, a: 0.1 },
  { T: 11, rx: 0.83, ry: 1.0, a: 0.07 },
  { T: 13, rx: 1.19, ry: 0.71, a: 0.05 },
] as const;

export function CausticCoverflow({
  items = DEFAULT_ITEMS,
  initialIndex,
  cardWidth = 264,
  cardHeight = 330,
  className = "",
  "aria-label": ariaLabel = "Coverflow gallery",
}: {
  /** the gallery images, in order */
  items?: CausticCoverflowItem[];
  /** starting focused card; defaults to the middle */
  initialIndex?: number;
  /** card width in px (shrinks responsively on narrow containers) */
  cardWidth?: number;
  /** card height in px */
  cardHeight?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the gallery. Default "Coverflow gallery". */
  "aria-label"?: string;
}) {
  const n = Math.max(1, items.length);
  const start = clamp(initialIndex ?? Math.floor((n - 1) / 2), 0, n - 1);

  const rootRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const liveRef = useRef<HTMLSpanElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const thumbRefs = useRef<(HTMLCanvasElement | null)[]>([]);
  const fxRefs = useRef<(HTMLCanvasElement | null)[]>([]);
  const dotRefs = useRef<(HTMLButtonElement | null)[]>([]);

  useEffect(() => {
    const root = rootRef.current;
    const stage = stageRef.current;
    if (!root || !stage) return;
    const cardsRaw = cardRefs.current.slice(0, n);
    const fxRaw = fxRefs.current.slice(0, n);
    const thumbRaw = thumbRefs.current.slice(0, n);
    if (
      cardsRaw.length < n ||
      fxRaw.length < n ||
      thumbRaw.length < n ||
      cardsRaw.includes(null) ||
      fxRaw.includes(null) ||
      thumbRaw.includes(null)
    )
      return;
    const cards = cardsRaw as HTMLDivElement[];
    const fxs = fxRaw as HTMLCanvasElement[];
    const thumbs = thumbRaw as HTMLCanvasElement[];

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const seedOf = (i: number) => items[i]?.seed ?? i * 7 + 3;

    // --- theme tokens: every canvas ink derives from these, never hardcoded
    let fg: RGB = { r: 237, g: 237, b: 237 };
    let mut: RGB = { r: 143, g: 143, b: 143 };
    let brd: RGB = { r: 46, g: 46, b: 46 };
    let srf: RGB = { r: 23, g: 23, b: 23 };
    let dark = true;
    const deriveTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
      mut = parseColor(cs.getPropertyValue("--ns-muted")) ?? mut;
      brd = parseColor(cs.getPropertyValue("--border")) ?? brd;
      srf = parseColor(cs.getPropertyValue("--surface")) ?? srf;
      const bg = parseColor(cs.getPropertyValue("--background")) ?? srf;
      dark = 0.2126 * bg.r + 0.7152 * bg.g + 0.0722 * bg.b < 128;
    };
    deriveTokens();

    // --- geometry (responsive: cards shrink on narrow containers)
    let cw = cardWidth;
    let ch = cardHeight;
    let spacing = cw * 0.46;
    let sized = false;
    // quarter-resolution offscreen buffer shared by all cards, upscaled with
    // imageSmoothing for soft pool edges
    const qc = document.createElement("canvas");
    const qctx = qc.getContext("2d");
    // tiny buffer for the generated thumbs
    const tiny = document.createElement("canvas");
    const tctx = tiny.getContext("2d");
    if (!qctx || !tctx) return;

    const layout = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 40 || rect.height < 10) {
        sized = false; // zero-size guard — never draw into a collapsed stage
        return;
      }
      sized = true;
      cw = Math.max(140, Math.round(Math.min(cardWidth, rect.width * 0.58)));
      ch = Math.round(cw * (cardHeight / cardWidth));
      spacing = cw * 0.46;
      stage.style.height = `${ch + 48}px`;
      qc.width = Math.max(1, Math.round(cw / 4));
      qc.height = Math.max(1, Math.round(ch / 4));
      for (let i = 0; i < n; i++) {
        cards[i].style.width = `${cw}px`;
        cards[i].style.height = `${ch}px`;
        // gotcha: a <canvas> is a replaced element — CSS inset does not size
        // it. Explicit style.width/height + dpr backing store, always.
        for (const c of [fxs[i], thumbs[i]]) {
          c.style.width = `${cw}px`;
          c.style.height = `${ch}px`;
          c.width = Math.max(1, Math.round(cw * dpr));
          c.height = Math.max(1, Math.round(ch * dpr));
        }
      }
    };

    // --- generated abstract thumbs: token-gray value-noise fields, one per
    // seed, redrawn per theme (no external images)
    const paintThumb = (i: number) => {
      if (!sized) return;
      const th = thumbs[i];
      const ctx = th.getContext("2d");
      if (!ctx) return;
      const seed = seedOf(i);
      const gw = 26;
      const gh = Math.max(8, Math.round((gw * ch) / cw));
      tiny.width = gw;
      tiny.height = gh;
      const img = tctx.createImageData(gw, gh);
      const data = img.data;
      for (let y = 0; y < gh; y++) {
        for (let x = 0; x < gw; x++) {
          const v = clamp(
            noise2(x * 0.33 + seed * 13.7, y * 0.33 + seed * 5.1),
            0,
            1
          );
          let c: RGB;
          if (v < 0.62) c = mixRGB(srf, brd, v / 0.62);
          else if (v < 0.88) c = mixRGB(brd, mut, (v - 0.62) / 0.26);
          else c = mixRGB(mut, fg, ((v - 0.88) / 0.12) * 0.55);
          // sink toward surface near the footer so the caption stays legible
          const settle = (y / gh) * 0.45;
          c = mixRGB(c, srf, settle);
          const o = (y * gw + x) * 4;
          data[o] = Math.round(c.r);
          data[o + 1] = Math.round(c.g);
          data[o + 2] = Math.round(c.b);
          data[o + 3] = 255;
        }
      }
      tctx.putImageData(img, 0, 0);
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.clearRect(0, 0, th.width, th.height);
      ctx.drawImage(tiny, 0, 0, gw, gh, 0, 0, th.width, th.height);
    };
    const paintThumbs = () => {
      for (let i = 0; i < n; i++) paintThumb(i);
    };

    // --- caustics: 3 radial light pools on Lissajous paths, drawn into the
    // quarter-res buffer on a fully cleared frame (no alpha accumulation),
    // then upscaled onto the card's overlay canvas
    const drawCaustics = (i: number, timeSec: number, amp: number) => {
      if (!sized) return;
      const fx = fxs[i];
      const ctx = fx.getContext("2d");
      if (!ctx) return;
      const qw = qc.width;
      const qh = qc.height;
      qctx.setTransform(1, 0, 0, 1, 0, 0);
      qctx.clearRect(0, 0, qw, qh);
      const seed = seedOf(i);
      for (let j = 0; j < POOLS.length; j++) {
        const p = POOLS[j];
        const ph = seed * 1.7 + j * 2.399;
        const x =
          qw * 0.5 +
          qw * 0.3 * amp * Math.sin(((timeSec / p.T) * 2 * Math.PI) * p.rx + ph);
        const y =
          qh * 0.5 +
          qh *
            0.3 *
            amp *
            Math.sin(((timeSec / p.T) * 2 * Math.PI) * p.ry + ph * 1.83);
        const r = Math.max(2, qw * 0.4); // 40% of card width, quarter space
        const g = qctx.createRadialGradient(x, y, 0, x, y, r);
        g.addColorStop(0, `rgba(${fg.r},${fg.g},${fg.b},${p.a})`);
        g.addColorStop(1, `rgba(${fg.r},${fg.g},${fg.b},0)`);
        qctx.fillStyle = g;
        qctx.fillRect(0, 0, qw, qh);
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, cw, ch);
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(qc, 0, 0, qw, qh, 0, 0, cw, ch);
    };

    // static frame for cards outside the live trio (and for reduced motion):
    // one fixed-phase caustic frame at half amplitude
    const paintStatic = () => {
      for (let i = 0; i < n; i++) drawCaustics(i, seedOf(i) * 0.37, 0.5);
    };

    // --- chromatic aberration: the focused card's border restroked twice
    // with horizontal offsets ±k in red/blue channel inks split from the
    // foreground token (fg.r → red pass, fg.b → blue pass). Additive
    // 'lighter' on dark themes; source-over fringes on light. Drawn onto the
    // freshly cleared caustic frame each tick — never accumulates.
    const drawAberration = (i: number, k: number) => {
      if (!sized) return;
      const ctx = fxs[i].getContext("2d");
      if (!ctx) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const alpha = clamp(0.18 + (k / 6) * 0.55, 0, 0.85);
      ctx.lineWidth = 1.25;
      ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
      // fixed minimum-saturation floor on the split channel: a pure
      // channel-split off a near-black --foreground (light theme) degrades
      // to a gray smudge, not a color, without a floor to keep it visible
      const redV = Math.max(fg.r, 190);
      const blueV = Math.max(fg.b, 190);
      ctx.save();
      ctx.translate(-k, 0);
      rrectPath(ctx, 1, 1, cw - 2, ch - 2, 11);
      ctx.strokeStyle = `rgba(${redV},0,0,${alpha})`;
      ctx.stroke();
      ctx.restore();
      ctx.save();
      ctx.translate(k, 0);
      rrectPath(ctx, 1, 1, cw - 2, ch - 2, 11);
      ctx.strokeStyle = `rgba(0,0,${blueV},${alpha})`;
      ctx.stroke();
      ctx.restore();
      ctx.globalCompositeOperation = "source-over";
    };

    // --- motion state (refs/locals only — never React state on hot paths)
    let pos = start;
    let prevPos = start;
    let vel = 0; // idx/s
    let effVel = 0; // smoothed, drives aberration
    let mode: "idle" | "drag" | "momentum" | "spring" | "tween" = "idle";
    let springStart = 0;
    let springTarget = start;
    let tweenFrom = 0;
    let tweenTarget = 0;
    let tweenStart = 0;
    let tweenDur = 250;
    let aberK = 0;
    let aberDeadline = 0;
    let lastWindow: number[] = [];
    let ambient = 0.5; // pool amplitude scale: 0.5 idle ↔ 1 interacting
    let raf = 0;
    let running = false;
    let last = 0;
    let lastCaustic = 0;
    let intersecting = true;
    let activeShown = -1;

    const applyTransforms = () => {
      for (let i = 0; i < n; i++) {
        const d = i - pos;
        cards[i].style.transform = cardTransform(d, spacing);
        // depth sort via explicit z-index (no preserve-3d intersection risk)
        cards[i].style.zIndex = String(200 - Math.round(Math.abs(d) * 10));
      }
    };

    const syncActive = () => {
      const a = Math.round(clamp(pos, 0, n - 1));
      if (a === activeShown) return;
      activeShown = a;
      const dots = dotRefs.current;
      for (let i = 0; i < n; i++) {
        const dot = dots[i];
        if (dot) dot.dataset.active = i === a ? "true" : "false";
      }
      if (liveRef.current)
        liveRef.current.textContent = `${items[a]?.title ?? ""}, item ${
          a + 1
        } of ${n}`;
    };

    const settledNow = () => mode === "idle" && aberK < 0.02;

    const frame = (now: number) => {
      raf = 0;
      const dt = Math.min(0.05, last === 0 ? 1 / 60 : (now - last) / 1000);
      last = now;

      if (mode === "momentum") {
        vel *= Math.pow(0.92, dt * 60); // friction 0.92/frame, fps-normalized
        pos += vel * dt;
        if (pos < 0) {
          pos += (0 - pos) * Math.min(1, dt * 10);
          vel *= 0.8;
        } else if (pos > n - 1) {
          pos += (n - 1 - pos) * Math.min(1, dt * 10);
          vel *= 0.8;
        }
        if (Math.abs(vel) < 0.05) {
          mode = "spring";
          springTarget = Math.round(clamp(pos, 0, n - 1));
          springStart = now;
        }
      } else if (mode === "spring") {
        const kk = 170;
        const cc = 2 * Math.sqrt(kk) * 0.95;
        vel += (-kk * (pos - springTarget) - cc * vel) * dt;
        pos += vel * dt;
        // forced-settle deadline: a flick can never oscillate past 900ms
        if (
          (Math.abs(pos - springTarget) < 0.0015 && Math.abs(vel) < 0.02) ||
          now - springStart > 900
        ) {
          pos = springTarget;
          vel = 0;
          mode = "idle";
        }
      } else if (mode === "tween") {
        const t = Math.min(1, (now - tweenStart) / tweenDur);
        pos = tweenFrom + (tweenTarget - tweenFrom) * easeOutExpo(t);
        if (t >= 1) {
          pos = tweenTarget;
          mode = "idle";
        }
      }
      // mode === "drag": pointermove writes pos directly between frames

      // posChanged must be read before prevPos updates — a spring/tween that
      // just force-settled flipped mode to "idle" this frame, but its final
      // pos snap still needs one applyTransforms pass
      const posChanged = pos !== prevPos;
      const inst = (pos - prevPos) / Math.max(dt, 1e-4);
      prevPos = pos;
      effVel += (inst - effVel) * 0.4;

      // aberration: k = min(6, |angular velocity| * 0.04), angular velocity
      // of the focused card = 35 deg per index of travel; exponential decay
      // at rest (τ=100ms → settles < 500ms) under a 900ms hard deadline
      const moving = mode !== "idle" || posChanged;
      if (moving) {
        aberK = Math.min(6, Math.abs(effVel) * 35 * 0.04);
        if (aberK > 0.05) aberDeadline = now + 900;
      } else {
        aberK *= Math.exp(-dt * 10);
        if (aberK < 0.03 || now > aberDeadline) aberK = 0;
      }

      // idle pools drift at half amplitude — ambient is the default look
      const ambTarget = moving ? 1 : 0.5;
      ambient += (ambTarget - ambient) * Math.min(1, dt * 4);

      if (sized) {
        if (moving) applyTransforms();
        syncActive();
        const a = activeShown;
        // full-rate while interacting or aberrating; 30fps cap at rest
        const draw = moving || aberK >= 0.02 || now - lastCaustic >= 33;
        if (draw) {
          lastCaustic = now;
          const t = now / 1000;
          // only the focused card and its two neighbors run live caustics
          const winStart = Math.max(0, a - 1);
          const winEnd = Math.min(n - 1, a + 1);
          // unconditionally wipe any index the live window left behind —
          // e.g. a fast multi-card navigate tween where `a` jumps 2+ cards
          // in one frame — regardless of aberK's decay state, so a stale
          // aberration fringe can never strand on an unattended card
          for (const idx of lastWindow) {
            if (idx < winStart || idx > winEnd) drawCaustics(idx, t, ambient);
          }
          lastWindow = [];
          for (let i = winStart; i <= winEnd; i++) {
            drawCaustics(i, t, ambient);
            lastWindow.push(i);
          }
          if (aberK >= 0.02) drawAberration(a, aberK);
        }
      }

      // sleep policy: offscreen → stop; settled AND tab hidden → full sleep;
      // otherwise the ambient 30fps drift keeps running
      if (!intersecting || (settledNow() && document.hidden)) {
        running = false;
        return;
      }
      raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (reduced || running || !intersecting) return;
      running = true;
      last = 0;
      raf = requestAnimationFrame(frame);
    };

    const navigate = (target: number, dur: number) => {
      const t = clamp(Math.round(target), 0, n - 1);
      if (reduced) {
        // reduced motion: instant 200ms CSS ease, no momentum, no aberration
        pos = t;
        vel = 0;
        applyTransforms();
        syncActive();
        return;
      }
      tweenFrom = pos;
      tweenTarget = t;
      tweenStart = performance.now();
      tweenDur = dur;
      mode = "tween";
      wake();
    };

    // --- pointer: drag scrubs the index continuously, release applies
    // momentum, taps center the tapped card
    let dragging = false;
    let dragMoved = 0;
    let dragTotal = 0;
    let lastX = 0;
    let lastT = 0;
    let dragVel = 0;
    const onDown = (e: PointerEvent) => {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      dragging = true;
      dragMoved = 0;
      dragTotal = 0;
      lastX = e.clientX;
      lastT = performance.now();
      dragVel = 0;
      if (!reduced) {
        mode = "drag";
        vel = 0;
        stage.style.cursor = "grabbing";
        wake();
      }
      try {
        stage.setPointerCapture(e.pointerId);
      } catch {
        /* capture unsupported */
      }
    };
    const onMove = (e: PointerEvent) => {
      if (!dragging) return;
      const now = performance.now();
      const dx = e.clientX - lastX;
      lastX = e.clientX;
      dragMoved += Math.abs(dx);
      dragTotal += dx;
      if (reduced) return;
      const dtm = Math.max(4, now - lastT) / 1000;
      lastT = now;
      let next = pos - dx / spacing;
      if (next < 0) next *= 0.3; // rubber band past the ends
      else if (next > n - 1) next = n - 1 + (next - (n - 1)) * 0.3;
      dragVel += ((next - pos) / dtm - dragVel) * 0.35;
      pos = next;
    };
    const onUp = (e: PointerEvent) => {
      if (!dragging) return;
      dragging = false;
      stage.style.cursor = "grab";
      try {
        stage.releasePointerCapture(e.pointerId);
      } catch {
        /* already released */
      }
      if (dragMoved < 5) {
        // click: center the card under the pointer
        const rect = stage.getBoundingClientRect();
        const rel = (e.clientX - rect.left - rect.width / 2) / spacing;
        navigate(pos + rel, 300);
        return;
      }
      if (reduced) {
        if (Math.abs(dragTotal) > 30)
          navigate(Math.round(pos) - Math.sign(dragTotal), 200);
        return;
      }
      vel = clamp(dragVel, -8, 8);
      mode = "momentum";
      wake();
    };
    const onCancel = () => {
      if (!dragging) return;
      dragging = false;
      stage.style.cursor = "grab";
      if (!reduced) {
        vel = clamp(dragVel, -8, 8);
        mode = "momentum";
        wake();
      }
    };

    // --- wheel steps one card (250ms ease-out-expo), locked per step
    let wheelLock = 0;
    const onWheel = (e: WheelEvent) => {
      const delta =
        Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
      if (delta === 0) return;
      e.preventDefault();
      const now = performance.now();
      if (now < wheelLock) return;
      wheelLock = now + 260;
      navigate(Math.round(pos) + (delta > 0 ? 1 : -1), 250);
    };

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        navigate(Math.round(pos) - 1, 250);
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        navigate(Math.round(pos) + 1, 250);
      }
    };

    const dotCleanups: (() => void)[] = [];
    dotRefs.current.slice(0, n).forEach((dot, i) => {
      if (!dot) return;
      const h = () => navigate(i, 300);
      dot.addEventListener("click", h);
      dotCleanups.push(() => dot.removeEventListener("click", h));
    });

    // --- observers
    const io = new IntersectionObserver((entries) => {
      intersecting = entries[0]?.isIntersecting ?? true;
      if (intersecting) wake();
    });
    io.observe(root);

    const ro = new ResizeObserver(() => {
      const wasSized = sized;
      layout();
      if (!sized) return;
      paintThumbs();
      paintStatic();
      applyTransforms();
      if (!wasSized) syncActive();
      wake();
    });
    ro.observe(root);

    // live theme re-derive: regenerate thumbs and static frames per theme;
    // the live trio re-inks on the next frame
    const mo = new MutationObserver(() => {
      deriveTokens();
      paintThumbs();
      paintStatic();
      wake();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    if (reduced) {
      for (const c of cards) c.style.transition = "transform 200ms ease";
    }
    stage.addEventListener("pointerdown", onDown);
    stage.addEventListener("pointermove", onMove);
    stage.addEventListener("pointerup", onUp);
    stage.addEventListener("pointercancel", onCancel);
    stage.addEventListener("wheel", onWheel, { passive: false });
    stage.addEventListener("keydown", onKey);

    // initial paint
    layout();
    paintThumbs();
    paintStatic();
    applyTransforms();
    syncActive();
    wake();

    return () => {
      cancelAnimationFrame(raf);
      running = false;
      io.disconnect();
      ro.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      stage.removeEventListener("pointerdown", onDown);
      stage.removeEventListener("pointermove", onMove);
      stage.removeEventListener("pointerup", onUp);
      stage.removeEventListener("pointercancel", onCancel);
      stage.removeEventListener("wheel", onWheel);
      stage.removeEventListener("keydown", onKey);
      for (const c of dotCleanups) c();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, n, start, cardWidth, cardHeight]);

  return (
    <div ref={rootRef} className={`w-full ${className}`}>
      <div
        ref={stageRef}
        role="group"
        aria-roledescription="carousel"
        aria-label={ariaLabel}
        tabIndex={0}
        className="relative w-full touch-pan-y select-none overflow-hidden rounded-md outline-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
        style={{
          height: cardHeight + 48,
          perspective: "1200px",
          cursor: "grab",
        }}
      >
        {items.map((item, i) => {
          const d = i - start;
          return (
            <div
              key={i}
              ref={(el) => {
                cardRefs.current[i] = el;
              }}
              className="absolute left-1/2 top-1/2"
              style={{
                width: cardWidth,
                height: cardHeight,
                transform: cardTransform(d, cardWidth * 0.46),
                zIndex: 200 - Math.round(Math.abs(d) * 10),
                willChange: "transform",
              }}
            >
              {/* hover lift + border shift on an inner wrapper so the rAF
                  loop's 3D transform on the outer node is never fought.
                  clip-path (not just overflow-hidden+rounded-md) contains the
                  backdrop-filter pane and canvases: this wrapper sits inside
                  an ancestor that's both will-change:transform'd and
                  rotateY/translateZ'd for the coverflow pose, and on that
                  combination Chromium/WebKit can rasterize a border-radius +
                  overflow:hidden clip as its full rectangular layer bounds
                  instead of the rounded mask — a rectangular box behind the
                  center card, sharp corner wedges poking past the radius on
                  the rotated side cards. clip-path is evaluated as its own
                  mask primitive every paint and doesn't share that failure
                  mode, so it stays authoritative regardless of compositing. */}
              <div
                className="relative h-full w-full overflow-hidden rounded-md border border-border bg-surface transition-[translate,border-color] duration-200 hover:-translate-y-0.5 hover:border-foreground/25"
                style={{ clipPath: "inset(0 round var(--radius-md))" }}
              >
                <canvas
                  ref={(el) => {
                    thumbRefs.current[i] = el;
                  }}
                  aria-hidden
                  className="absolute left-0 top-0"
                />
                {/* frosted pane over the generated thumb */}
                <div
                  aria-hidden
                  className="absolute inset-0"
                  style={{
                    backdropFilter: "blur(14px) saturate(1.1)",
                    WebkitBackdropFilter: "blur(14px) saturate(1.1)",
                    background:
                      "color-mix(in srgb, var(--surface) 60%, transparent)",
                  }}
                />
                <div className="absolute inset-x-0 bottom-0 p-4">
                  <p className="text-sm font-semibold tracking-tight text-foreground">
                    {item.title}
                  </p>
                  <p className="mt-1 font-mono text-[10px] tracking-widest text-ns-muted">
                    {item.meta ?? `NO. ${String(i + 1).padStart(2, "0")}`}
                  </p>
                </div>
                {/* caustic + aberration overlay */}
                <canvas
                  ref={(el) => {
                    fxRefs.current[i] = el;
                  }}
                  aria-hidden
                  className="pointer-events-none absolute left-0 top-0"
                />
              </div>
            </div>
          );
        })}
      </div>
      <div className="mt-5 flex items-center justify-center gap-2">
        {items.map((item, i) => (
          <button
            key={i}
            ref={(el) => {
              dotRefs.current[i] = el;
            }}
            type="button"
            data-active={i === start ? "true" : "false"}
            aria-label={`Go to ${item.title}`}
            className="h-1.5 w-6 rounded-full bg-border transition-colors duration-200 hover:bg-ns-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent data-[active=true]:bg-foreground"
          />
        ))}
      </div>
      <span ref={liveRef} aria-live="polite" className="sr-only" />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GalleyBracket — remote collaborators' live selections drawn as proofreader's
// marks, not highlight washes: a thin corner bracket at each end of a range,
// a hairline underline between them, and the selector's initials set small in
// the left margin at the opening bracket. Ranges are measured off the real
// rendered text with Range.getClientRects() (a Range over one text node, the
// same primitive selecting the text and reading getClientRects() would use),
// so a multi-line selection gets one underline per wrapped line and brackets
// only at its true start/end — never one per line. When ranges overlap, the
// only thing that varies per selection is its arrival index within that
// overlap group (arrival order, not z-index or hue): later arrivals' brackets
// stand outward from the text by index*3px and draw slightly lighter, so
// concurrent selections nest like stacked proof brackets instead of blending
// into a third, unreadable color. Marks draw in with a 160ms stroke-dashoffset
// reveal on first arrival only — the same selection re-ranging (a drag) never
// replays it, which is what keeps rapid re-selection from strobing. The SVG
// layer is aria-hidden; the real accessible surface is a debounced (2s)
// role=status summary ("Ana selected 12 words") plus a keyboard-reachable
// list of jump buttons that move the platform's own Selection into the named
// range. Every stroke is --foreground at reduced opacity — no filled
// highlights, ever, because two overlapping fills produce a third value that
// identifies nobody. DOM+SVG+CSS only, no canvas.
// ---------------------------------------------------------------------------

export interface GalleyBracketSelection {
  /** stable id for this collaborator's current range */
  id: string;
  /** full name — used in the debounced summary and the jump list */
  name: string;
  /** short code drawn small in the margin at the opening bracket; derived from `name` if omitted */
  initials?: string;
  /** character offset into `text` where the range starts */
  start: number;
  /** character offset into `text` where the range ends (exclusive) */
  end: number;
  /** arrival order key, lower = earlier. Defaults to this selection's index in the array, so
   *  passing a freshly-appended selection last is enough to make it the latest arrival. */
  arrivedAt?: number;
}

export interface GalleyBracketProps {
  /** the shared paragraph's plain text. One instance renders one paragraph — for a
   *  multi-paragraph editor, render one GalleyBracket per paragraph so range offsets
   *  stay simple character indices into a single text node. */
  text: string;
  /** remote collaborators' current ranges into `text` */
  selections: GalleyBracketSelection[];
  /** named in the debounced summary ("Ana selected 12 words in paragraph 3") */
  contextLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type LocalRect = { left: number; top: number; right: number; bottom: number };

const BRACKET_ARM = 6; // px, horizontal foot length
const OFFSET_STEP = 3; // px, outward nesting distance per arrival index
const UNDER_GAP = 4; // px, underline distance below the line's own baseline box
const BASE_OPACITY = 0.55;
const OPACITY_STEP = 0.09;
const MIN_OPACITY = 0.22;
const DEBOUNCE_MS = 2000;

function clamp(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(n, hi));
}

function deriveInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return (parts[0] ?? "").slice(0, 2).toUpperCase();
  return `${parts[0]?.[0] ?? ""}${parts[1]?.[0] ?? ""}`.toUpperCase();
}

function wordCount(text: string, start: number, end: number): number {
  const len = text.length;
  const s = clamp(start, 0, len);
  const e = clamp(end, s, len);
  const slice = text.slice(s, e).trim();
  return slice ? slice.split(/\s+/).length : 0;
}

function opacityFor(localIndex: number): number {
  return Math.max(MIN_OPACITY, BASE_OPACITY - localIndex * OPACITY_STEP);
}

function overlaps(a: { start: number; end: number }, b: { start: number; end: number }): boolean {
  return a.start < b.end && b.start < a.end;
}

// Groups selections whose [start,end) ranges transitively overlap, then ranks each
// member by arrival order within its own group. That local rank — not the raw
// arrivedAt value, not DOM order — is the one scalar every other visual property
// derives from (outward offset, stroke opacity).
function computeArrivalIndex(sels: GalleyBracketSelection[]): Map<string, number> {
  const n = sels.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x] as number] as number;
      x = parent[x] as number;
    }
    return x;
  };
  const union = (a: number, b: number) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  };
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = sels[i];
      const b = sels[j];
      if (a && b && overlaps(a, b)) union(i, j);
    }
  }
  const arrivalKey = (i: number) => sels[i]?.arrivedAt ?? i;
  const groups = new Map<number, number[]>();
  for (let i = 0; i < n; i++) {
    const r = find(i);
    const g = groups.get(r);
    if (g) g.push(i);
    else groups.set(r, [i]);
  }
  const result = new Map<string, number>();
  for (const idxs of groups.values()) {
    idxs.sort((a, b) => arrivalKey(a) - arrivalKey(b));
    idxs.forEach((idx, local) => {
      const sel = sels[idx];
      if (sel) result.set(sel.id, local);
    });
  }
  return result;
}

function toLocal(rects: DOMRect[], originLeft: number, originTop: number): LocalRect[] {
  return rects
    .filter((r) => r.width > 0 && r.height > 0)
    .map((r) => ({
      left: r.left - originLeft,
      top: r.top - originTop,
      right: r.right - originLeft,
      bottom: r.bottom - originTop,
    }))
    .sort((a, b) => a.top - b.top);
}

function BracketMark({
  rect,
  side,
  localIndex,
  opacity,
}: {
  rect: LocalRect;
  side: "open" | "close";
  localIndex: number;
  opacity: number;
}) {
  const topY = rect.top - localIndex * OFFSET_STEP;
  const footY = rect.bottom + UNDER_GAP + localIndex * OFFSET_STEP;
  const x = side === "open" ? rect.left : rect.right;
  const footX = side === "open" ? x + BRACKET_ARM : x - BRACKET_ARM;
  return (
    <>
      <line
        x1={x}
        y1={topY}
        x2={x}
        y2={footY}
        pathLength={1}
        strokeDasharray={1}
        className="ns-galley-draw"
        stroke="var(--foreground)"
        strokeWidth={1}
        strokeLinecap="round"
        opacity={opacity}
      />
      <line
        x1={x}
        y1={footY}
        x2={footX}
        y2={footY}
        pathLength={1}
        strokeDasharray={1}
        className="ns-galley-draw"
        stroke="var(--foreground)"
        strokeWidth={1}
        strokeLinecap="round"
        opacity={opacity}
      />
    </>
  );
}

export function GalleyBracket({ text, selections, contextLabel, className = "" }: GalleyBracketProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);

  const [size, setSize] = useState({ width: 0, height: 0 });
  const [marks, setMarks] = useState<Record<string, LocalRect[]>>({});
  const [liveMessage, setLiveMessage] = useState("");
  const [reducedMotion, setReducedMotion] = useState(false);

  const prevSelRef = useRef<Map<string, { start: number; end: number }>>(new Map());
  const debounceTimer = useRef(0);

  const arrivalIndex = useMemo(() => computeArrivalIndex(selections), [selections]);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const measure = useCallback(() => {
    const container = containerRef.current;
    const p = textRef.current;
    if (!container || !p) return;
    const box = container.getBoundingClientRect();
    setSize({ width: box.width, height: box.height });
    const node = p.firstChild;
    if (!(node instanceof Text)) {
      setMarks({});
      return;
    }
    const len = node.data.length;
    const next: Record<string, LocalRect[]> = {};
    for (const sel of selections) {
      const s = clamp(sel.start, 0, len);
      const e = clamp(sel.end, s, len);
      if (e <= s) continue;
      const range = document.createRange();
      try {
        range.setStart(node, s);
        range.setEnd(node, e);
        const rects = toLocal(Array.from(range.getClientRects()), box.left, box.top);
        if (rects.length) next[sel.id] = rects;
      } catch {
        // stale offsets against a text node mid-update — skip this selection's marks this frame
      }
    }
    setMarks(next);
  }, [selections]);

  useLayoutEffect(() => {
    measure();
    const container = containerRef.current;
    if (!container) return;
    const ro = new ResizeObserver(() => measure());
    ro.observe(container);
    const onResize = () => measure();
    window.addEventListener("resize", onResize);
    document.fonts?.ready?.then(() => measure()).catch(() => {});
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", onResize);
    };
  }, [measure]);

  // debounced accessible summary — announces only the range that most recently
  // changed, 2s after changes stop, so a drag-selection in progress never floods
  // the live region with one announcement per pointermove.
  useEffect(() => {
    const prev = prevSelRef.current;
    let changed: GalleyBracketSelection | undefined;
    for (const sel of selections) {
      const p = prev.get(sel.id);
      if (!p || p.start !== sel.start || p.end !== sel.end) changed = sel;
    }
    prevSelRef.current = new Map(selections.map((s) => [s.id, { start: s.start, end: s.end }]));
    if (!changed) return;
    const target = changed;
    window.clearTimeout(debounceTimer.current);
    debounceTimer.current = window.setTimeout(() => {
      const words = wordCount(text, target.start, target.end);
      const where = contextLabel ? ` in ${contextLabel}` : "";
      setLiveMessage(`${target.name} selected ${words} word${words === 1 ? "" : "s"}${where}.`);
    }, DEBOUNCE_MS);
  }, [selections, text, contextLabel]);

  useEffect(() => {
    const timer = debounceTimer;
    return () => window.clearTimeout(timer.current);
  }, []);

  const jumpTo = (sel: GalleyBracketSelection) => {
    const node = textRef.current?.firstChild;
    if (!(node instanceof Text)) return;
    const len = node.data.length;
    const s = clamp(sel.start, 0, len);
    const e = clamp(sel.end, s, len);
    if (e <= s) return;
    const range = document.createRange();
    try {
      range.setStart(node, s);
      range.setEnd(node, e);
    } catch {
      return;
    }
    const live = window.getSelection();
    live?.removeAllRanges();
    live?.addRange(range);
    textRef.current?.scrollIntoView({
      block: "center",
      behavior: reducedMotion ? "auto" : "smooth",
    });
  };

  return (
    <div className={["ns-galley relative", className].filter(Boolean).join(" ")}>
      <style>{`
.ns-galley-draw{ stroke-dashoffset: 1; animation: ns-galley-draw-in 160ms cubic-bezier(0.16,1,0.3,1) forwards; }
@keyframes ns-galley-draw-in{ from{ stroke-dashoffset: 1; } to{ stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce){
  .ns-galley-draw{ animation: none !important; stroke-dashoffset: 0 !important; }
}
`}</style>

      <div ref={containerRef} className="relative py-2 pl-9 pr-2">
        <p ref={textRef} className="text-base leading-[2.2] text-foreground">
          {text}
        </p>
        <svg
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
          viewBox={`0 0 ${Math.max(size.width, 1)} ${Math.max(size.height, 1)}`}
          preserveAspectRatio="none"
        >
          {selections.map((sel) => {
            const rects = marks[sel.id];
            if (!rects || rects.length === 0) return null;
            const first = rects[0];
            const last = rects[rects.length - 1];
            if (!first || !last) return null;
            const local = arrivalIndex.get(sel.id) ?? 0;
            const op = opacityFor(local);
            const initials = sel.initials?.trim() || deriveInitials(sel.name);
            return (
              <g key={sel.id} data-selection={sel.id}>
                {rects.map((r, i) => {
                  const y = r.bottom + UNDER_GAP + local * OFFSET_STEP;
                  return (
                    <line
                      key={i}
                      x1={r.left}
                      y1={y}
                      x2={r.right}
                      y2={y}
                      pathLength={1}
                      strokeDasharray={1}
                      className="ns-galley-draw"
                      stroke="var(--foreground)"
                      strokeWidth={1}
                      opacity={op}
                    />
                  );
                })}
                <BracketMark rect={first} side="open" localIndex={local} opacity={op} />
                <BracketMark rect={last} side="close" localIndex={local} opacity={op} />
                <text
                  x={4}
                  y={first.top - local * OFFSET_STEP + 9}
                  className="font-mono text-[8px]"
                  fill="var(--foreground)"
                  opacity={op}
                >
                  {initials}
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      <div role="status" aria-live="polite" className="sr-only">
        {liveMessage}
      </div>

      {selections.length > 0 && (
        <div className="mt-4">
          <p className="mb-1.5 font-mono text-[10px] uppercase tracking-[0.14em] text-ns-muted">
            Active selections
          </p>
          <ul className="flex flex-wrap gap-2">
            {selections.map((sel) => {
              const words = wordCount(text, sel.start, sel.end);
              return (
                <li key={sel.id}>
                  <button
                    type="button"
                    data-jump
                    onClick={() => jumpTo(sel)}
                    className="rounded-full border border-border px-2.5 py-1 font-mono text-[11px] text-ns-muted outline-none transition-colors hover:border-foreground/25 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
                  >
                    {sel.name} · {words} word{words === 1 ? "" : "s"}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GanttAsciiCriticalPath — a project schedule whose critical path is COMPUTED,
// not annotated. A real CPM pass (Kahn topological order -> ES/EF forward ->
// LS/LF backward -> totalFloat = LS - ES) runs in one useMemo and decides one
// thing: a task with zero float draws the heavy accented set (┝━━┥), every
// other task the light set (├──┤). Dragging a bar re-runs the pass on the same
// frame, so handing slack to a different chain swaps the weights mid-gesture.
//
// No canvas, no rAF: every recompute is a direct response to pointer or key
// input. Empty timeline cells render nothing at all — the ink sits in the bars,
// the week ticks and the one `┊` today column.
//
// NO DEPENDENCY ARROWS. A connector lane anchored to the successor's row can
// place a predecessor's corner glyph at the right COLUMN but never at the right
// ROW, so every edge reads as leaving whatever task sits directly above. Doing
// it truthfully needs vertical routing across intervening rows — more apparatus
// than the edge earns: the bar WEIGHT already says which chain the ship date
// rides on, and that reads at rest with no pointer.
//
// PITCH: the timeline grid is laid out in `ch` units, not pixels. In a
// monospace face 1ch is exactly one advance width, so consecutive `─`/`━`
// glyphs butt up into a continuous rule at ANY font size and in any fallback
// font — a hardcoded px pitch dashes the bars the moment the two disagree.
// The drag handler needs a pixel figure, so it measures the row grid's real
// width / cols at pointerdown rather than assuming one.
// ---------------------------------------------------------------------------

export interface GanttTask {
  /** stable id, referenced by other tasks' deps */
  id: string;
  label: string;
  /** duration in days */
  duration: number;
  /** ids this task cannot start before */
  deps?: string[];
}

export interface GanttAsciiCriticalPathProps {
  /** the scheduled tasks */
  tasks?: GanttTask[];
  /** timeline cells drawn per row */
  cols?: number;
  /** day index marked by the `┊` column. A fixed prop, never new Date() */
  today?: number;
  /** week number printed at the first tick */
  startWeek?: number;
  /** heading above the chart */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const LABEL_CHARS = 16;

const DEFAULT_TASKS: GanttTask[] = [
  { id: "discovery", label: "Discovery interviews", duration: 4, deps: [] },
  { id: "wireframes", label: "Wireframe review", duration: 3, deps: ["discovery"] },
  { id: "design-system", label: "Design system", duration: 5, deps: ["wireframes"] },
  { id: "api-contract", label: "API contract", duration: 3, deps: ["discovery"] },
  { id: "integrate-payments", label: "Integrate payments", duration: 7, deps: ["api-contract"] },
  { id: "checkout-ui", label: "Checkout UI build", duration: 6, deps: ["design-system"] },
  { id: "launch-comms", label: "Launch comms", duration: 2, deps: ["design-system"] },
  {
    id: "qa-regression",
    label: "QA regression pass",
    duration: 4,
    deps: ["checkout-ui", "integrate-payments"],
  },
  { id: "ship", label: "Production rollout", duration: 3, deps: ["qa-regression", "launch-comms"] },
];

type Computed = {
  es: number;
  ef: number;
  ls: number;
  lf: number;
  float: number;
  critical: boolean;
  cyclic: boolean;
};

function padLabel(label: string): string {
  if (label.length <= LABEL_CHARS) return label.padEnd(LABEL_CHARS, " ");
  return `${label.slice(0, LABEL_CHARS - 1)}…`;
}

export function GanttAsciiCriticalPath({
  tasks = DEFAULT_TASKS,
  cols = 32,
  today = 9,
  startWeek = 12,
  title = "Checkout replatform",
  className = "",
}: GanttAsciiCriticalPathProps) {
  const [offsets, setOffsets] = useState<Record<string, number>>({});
  const [hovered, setHovered] = useState<string | null>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const [dragId, setDragId] = useState<string | null>(null);
  const dragRef = useRef<{
    id: string;
    startX: number;
    startOffset: number;
    prev: number;
    cellPx: number;
  } | null>(null);

  // --- CPM: Kahn topological order, forward pass, backward pass -------------
  const { plan, projectEnd, scale, bases } = useMemo(() => {
    const byId = new Map(tasks.map((t) => [t.id, t]));
    const indeg = new Map<string, number>();
    const succ = new Map<string, string[]>();
    for (const t of tasks) {
      const deps = (t.deps ?? []).filter((d) => byId.has(d) && d !== t.id);
      indeg.set(t.id, deps.length);
      for (const d of deps) succ.set(d, [...(succ.get(d) ?? []), t.id]);
    }
    const queue = tasks.filter((t) => (indeg.get(t.id) ?? 0) === 0).map((t) => t.id);
    const order: string[] = [];
    while (queue.length) {
      const id = queue.shift() as string;
      order.push(id);
      for (const s of succ.get(id) ?? []) {
        const n = (indeg.get(s) ?? 0) - 1;
        indeg.set(s, n);
        if (n === 0) queue.push(s);
      }
    }
    // Anything Kahn never drained sits on a cycle: excluded, never hung on.
    const inOrder = new Set(order);

    // FORWARD: ES = max(0, max(EF of deps) + manualOffset), EF = ES + duration
    const es = new Map<string, number>();
    const ef = new Map<string, number>();
    // earliest day a task could start on dependencies alone, before its manual
    // offset — the floor an ArrowLeft nudge must not drift below.
    const base0 = new Map<string, number>();
    for (const id of order) {
      const t = byId.get(id) as GanttTask;
      let base = 0;
      for (const d of t.deps ?? []) if (inOrder.has(d)) base = Math.max(base, ef.get(d) ?? 0);
      base0.set(id, base);
      const start = Math.max(0, base + (offsets[id] ?? 0));
      es.set(id, start);
      ef.set(id, start + Math.max(1, t.duration));
    }
    const end = order.reduce((m, id) => Math.max(m, ef.get(id) ?? 0), 1);

    // BACKWARD, reverse topological: LF = min(LS of successors) or projectEnd
    const ls = new Map<string, number>();
    const lf = new Map<string, number>();
    for (let i = order.length - 1; i >= 0; i--) {
      const id = order[i];
      const t = byId.get(id) as GanttTask;
      const outs = (succ.get(id) ?? []).filter((s) => inOrder.has(s));
      const late = outs.length ? Math.min(...outs.map((s) => ls.get(s) ?? end)) : end;
      lf.set(id, late);
      ls.set(id, late - Math.max(1, t.duration));
    }

    const map = new Map<string, Computed>();
    for (const t of tasks) {
      if (!inOrder.has(t.id)) {
        map.set(t.id, { es: 0, ef: 0, ls: 0, lf: 0, float: 0, critical: false, cyclic: true });
        continue;
      }
      const f = (ls.get(t.id) as number) - (es.get(t.id) as number);
      map.set(t.id, {
        es: es.get(t.id) as number,
        ef: ef.get(t.id) as number,
        ls: ls.get(t.id) as number,
        lf: lf.get(t.id) as number,
        float: f,
        // <= rather than ===: a drag can push a task to negative float
        // mid-gesture, and that row is still the tight one, not a slack one.
        critical: f <= 0,
        cyclic: false,
      });
    }
    return { plan: map, projectEnd: end, bases: base0, scale: Math.max(1, Math.ceil(end / cols)) };
  }, [tasks, offsets, cols]);

  // --- drag: pixel dx -> whole cells -> manualOffset, CPM re-runs live ------
  useEffect(() => {
    if (!dragId) return;
    const move = (e: PointerEvent) => {
      const d = dragRef.current;
      if (!d) return;
      const cells = Math.round((e.clientX - d.startX) / d.cellPx);
      setOffsets((o) => ({ ...o, [d.id]: d.startOffset + cells * scale }));
    };
    const end = () => {
      dragRef.current = null;
      setDragId(null);
    };
    const key = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      const d = dragRef.current;
      if (d) setOffsets((o) => ({ ...o, [d.id]: d.prev }));
      dragRef.current = null;
      setDragId(null);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    window.addEventListener("keydown", key);
    return () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
      window.removeEventListener("keydown", key);
    };
  }, [dragId, scale]);

  // Clamped both ways against the task's dependency-earliest start: at −base so
  // repeated ArrowLeft on a task already sitting at day 0 cannot accumulate
  // invisible negative offset that a later ArrowRight has to spend itself
  // unwinding, and at cols*scale − base so held ArrowRight cannot run ES past
  // aria-valuemax while the bar saturates at the last column. aria-valuenow
  // (the clamped ES) therefore stays in step with the stored offset.
  const nudge = (id: string, dir: number) =>
    setOffsets((o) => {
      const base = bases.get(id) ?? 0;
      const next = (o[id] ?? 0) + dir * scale;
      return { ...o, [id]: Math.min(cols * scale - base, Math.max(-base, next)) };
    });

  const colOf = (day: number) => Math.floor(day / scale);
  const todayCol = colOf(today);

  const geom = (id: string) => {
    const c = plan.get(id) as Computed;
    const start = Math.min(cols - 2, Math.max(0, colOf(c.es)));
    const len = Math.max(2, Math.min(cols - start, Math.round((c.ef - c.es) / scale)));
    return { start, len, c };
  };

  const active = hovered ?? focused;

  const readout = (() => {
    if (!active) {
      const crit = tasks.filter((t) => plan.get(t.id)?.critical && !plan.get(t.id)?.cyclic).length;
      const slack = tasks.length - crit;
      return `${projectEnd} days  critical chain ${crit} tasks  ${slack} tasks carry float`;
    }
    const t = tasks.find((x) => x.id === active) as GanttTask;
    const c = plan.get(active) as Computed;
    if (c.cyclic) return `${t.label}  ×  circular dependency, excluded from the pass`;
    return `${t.label}  ES ${c.es}  EF ${c.ef}  LS ${c.ls}  LF ${c.lf}  float ${c.float} day${
      c.float === 1 ? "" : "s"
    }`;
  })();

  // 1ch === one monospace advance, so `─` runs join with no seam at any size.
  const cell = "inline-block text-center";
  const cellStyle = { width: "1ch" } as const;
  const labelStyle = { width: `${LABEL_CHARS}ch` } as const;
  const trackStyle = { gridTemplateColumns: `repeat(${cols}, 1ch)` } as const;

  return (
    <section
      data-gantt
      aria-label={`${title} — Gantt chart with computed critical path`}
      className={`inline-flex select-none flex-col gap-3 font-mono text-[15px] leading-none ${className}`}
    >
      <div className="flex items-baseline justify-between gap-6">
        <span className="text-[11px] uppercase tracking-[0.18em] text-ns-muted">{title}</span>
        <span className="text-[10px] uppercase tracking-[0.18em] text-ns-muted">
          <span className="text-ns-accent">━</span> critical &nbsp; ─ has float
        </span>
      </div>

      <div className="flex flex-col gap-[3px]">
        {/* week labels */}
        <div className="flex items-center">
          <span className="shrink-0 whitespace-pre" style={labelStyle} />
          <span className={cell} style={cellStyle} />
          <div className="grid" style={trackStyle}>
            {Array.from({ length: cols }, (_, i) => {
              const day = i * scale;
              if (day % 7 !== 0) return null;
              return (
                <span
                  key={i}
                  className="whitespace-pre text-[10px] leading-none text-ns-muted"
                  style={{ gridColumn: `${i + 1} / span 4` }}
                >
                  {`W${startWeek + day / 7}`}
                </span>
              );
            })}
          </div>
        </div>

        {/* ruler: `┬` every 7 days over a `─` rule, `┊` at today */}
        <div className="flex items-center">
          <span className="shrink-0 whitespace-pre" style={labelStyle} />
          <span className={`${cell} text-border`} style={cellStyle}>
            ┌
          </span>
          <div className="flex">
            {Array.from({ length: cols }, (_, i) => {
              const day = i * scale;
              const tick = day % 7 === 0;
              const isToday = i === todayCol;
              return (
                <span
                  key={i}
                  className={`${cell} ${
                    isToday ? "text-foreground" : tick ? "text-ns-muted" : "text-ns-muted/40"
                  }`}
                  style={cellStyle}
                >
                  {isToday ? "┊" : tick ? "┬" : "─"}
                </span>
              );
            })}
          </div>
        </div>

        {tasks.map((t) => {
          const { start, len, c } = geom(t.id);
          const isActive = active === t.id;
          const barGlyphs = c.critical
            ? `┝${"━".repeat(Math.max(0, len - 2))}┥`
            : `├${"─".repeat(Math.max(0, len - 2))}┤`;
          const todayFree = todayCol < start || todayCol >= start + len;

          return (
            <div
              key={t.id}
              data-task-row={t.id}
              className="flex items-center"
              onPointerEnter={() => setHovered(t.id)}
              onPointerLeave={() => setHovered((h) => (h === t.id ? null : h))}
            >
              <span
                className={`shrink-0 whitespace-pre text-[13px] transition-colors duration-[140ms] motion-reduce:transition-none ${
                  isActive || c.critical ? "text-foreground" : "text-ns-muted"
                }`}
                style={labelStyle}
              >
                {padLabel(t.label)}
              </span>
              <span className={`${cell} text-border`} style={cellStyle}>
                │
              </span>

              {c.cyclic ? (
                <span className="whitespace-pre pl-1 text-[13px] text-ns-muted">
                  ×  cycle — excluded
                </span>
              ) : (
                <div className="relative grid" style={trackStyle}>
                  <button
                    type="button"
                    role="slider"
                    aria-orientation="horizontal"
                    aria-valuemin={0}
                    aria-valuemax={cols * scale}
                    aria-valuenow={c.es}
                    aria-valuetext={`starts day ${c.es}, ends day ${c.ef}, ${
                      c.critical ? "on the critical path, no float" : `${c.float} days of float`
                    }`}
                    aria-label={`${t.label} schedule. Drag or use arrow keys to reschedule.`}
                    className="flex cursor-ew-resize items-center rounded-[2px] outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ns-accent"
                    style={{ gridColumn: `${start + 1} / span ${len}`, gridRow: 1 }}
                    onFocus={() => setFocused(t.id)}
                    onBlur={() => setFocused((f) => (f === t.id ? null : f))}
                    onPointerDown={(e) => {
                      // Measure the real pitch off the laid-out track instead
                      // of trusting a px constant to match the font metric.
                      const track = e.currentTarget.parentElement;
                      const w = track ? track.getBoundingClientRect().width : 0;
                      dragRef.current = {
                        id: t.id,
                        startX: e.clientX,
                        startOffset: offsets[t.id] ?? 0,
                        prev: offsets[t.id] ?? 0,
                        cellPx: w > 0 ? w / cols : 9,
                      };
                      setDragId(t.id);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "ArrowLeft") {
                        e.preventDefault();
                        nudge(t.id, -1);
                      } else if (e.key === "ArrowRight") {
                        e.preventDefault();
                        nudge(t.id, 1);
                      } else if (e.key === "Escape" && !dragId) {
                        // Guarded on !dragId: mid-drag the window keydown
                        // listener owns Escape (it restores the pre-drag
                        // offset) and both firing would fight.
                        e.preventDefault();
                        setOffsets((o) => ({ ...o, [t.id]: 0 }));
                      }
                    }}
                  >
                    {barGlyphs.split("").map((ch, k) => (
                      <span
                        key={k}
                        className={`${cell} ${c.critical ? "text-ns-accent" : "text-ns-muted"}`}
                        style={cellStyle}
                      >
                        {ch}
                      </span>
                    ))}
                  </button>

                  {todayFree && todayCol >= 0 && todayCol < cols && (
                    <span
                      aria-hidden
                      className={`${cell} text-foreground`}
                      style={{
                        gridColumn: `${todayCol + 1} / span 1`,
                        gridRow: 1,
                        width: "1ch",
                      }}
                    >
                      ┊
                    </span>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <p
        aria-live="polite"
        className="rounded-sm border border-border bg-background px-3 py-2 text-[11px] tabular-nums text-ns-muted"
      >
        {readout}
      </p>
    </section>
  );
}

"use client";

// GatherMarver — a file-upload / processing indicator sourced from the real
// gather-and-marver sequence in hot-glass work. A gaffer gathers a molten
// gob on the end of a blowpipe — it comes off the furnace lopsided — then
// rolls it back and forth on the marver, a flat steel table, to centre its
// mass around the pipe's axis and skin its surface before any blowing
// starts. That correction is the whole mechanic: an irregular, off-centre
// blob rolls across a flat baseline, visibly losing its lumps the longer it
// runs, while the pipe keeps spinning underneath it the entire time.
//
// The blob outline is a closed Catmull-Rom spline over 12 control points.
// Each point carries a fixed noise offset (up to ±35% of the base radius,
// seeded once per mount) representing the gob's initial lopsidedness. That
// offset is scaled every frame by 0.82 raised to the number of roll passes
// elapsed (continuous, not stepped, so the shrink itself reads smooth
// rather than snapping once per pass) — one roll pass being one full
// left-travel-then-right-travel cycle, 1.8s. Horizontal travel swings the
// blob's centre ±28% of the container's width around the marver's centre
// on that same 1.8s period. Independent of both the correction decay and
// the travel, the blob spins continuously at 24°/s — the pipe rotating
// under the gaffer's hand — which is what keeps the loop alive forever
// even after the gob reads as fully round: a perfectly centred disc still
// visibly turns.
//
// Two modes read off the same real-time clock. Indeterminate (no `progress`
// prop): the correction decay runs off genuine elapsed time and never
// stops, asymptotically approaching a round disc and staying there,
// spinning, for as long as the component is mounted. Determinate (a
// `progress` 0-100 prop supplied): the correction decay is driven by
// `progress` instead of elapsed time — 0.82^(progress/100 * 18), a
// mapping calibrated so progress=100 lands under 3% residual deviation,
// i.e. a settled, fully-round disc — while travel and spin keep running
// off the real clock regardless, so a HELD progress value still visibly
// rolls and turns rather than idling. Completion is never marked with
// --ns-accent: the finished state is just an evenly-lit --foreground disc.
import { useEffect, useLayoutEffect, useRef } from "react";

const CONTROL_POINTS = 12;
const RADIUS_FRAC = 0.42; // base blob radius, fraction of the container's SMALLER dimension
const MAX_LOPSIDE = 0.35; // initial control-point deviation, fraction of base radius
const DECAY_PER_PASS = 0.82; // deviation multiplier per roll pass (continuous exponent)
const PASS_PERIOD_MS = 1800; // one full left+right travel cycle
const TRAVEL_FRAC = 0.28; // horizontal travel amplitude, fraction of container width
const SPIN_DEG_PER_SEC = 24; // continuous pipe rotation, independent of travel/correction
const DETERMINATE_MAX_PASSES = 18; // progress=100 -> 0.82^18 ≈ 2.8% residual deviation

const STATIC_PASS = 5; // reduced-motion freeze: mid-correction, ~37% of starting deviation

interface Tokens {
  fg: string;
  muted: string;
  border: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    muted: get("--ns-muted", "#6b6b6b"),
    border: get("--border", "#e5e5e5"),
  };
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Uniform Catmull-Rom through a closed loop of points, drawn as cubic
 * beziers (tension 1) — a real spline, not a polygon smoothed by rounding
 * canvas joins. */
function tracePath(ctx: CanvasRenderingContext2D, pts: { x: number; y: number }[]) {
  const n = pts.length;
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n]!;
    const p1 = pts[i]!;
    const p2 = pts[(i + 1) % n]!;
    const p3 = pts[(i + 2) % n]!;
    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;
    if (i === 0) ctx.moveTo(p1.x, p1.y);
    ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, p2.x, p2.y);
  }
  ctx.closePath();
}

export interface GatherMarverProps {
  /** controlled progress, 0-100 — maps onto the correction decay instead of
   * elapsed time; travel and spin keep running off the real clock regardless.
   * Omit for the default indeterminate, self-driving loop. */
  progress?: number;
  /** accessible label. */
  "aria-label"?: string;
  /** extra classes merged onto the rendered root element — size it here; the canvas fills whatever box it's given */
  className?: string;
}

export function GatherMarver({
  progress,
  "aria-label": ariaLabel = "Processing",
  className = "",
}: GatherMarverProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokensRef = useRef<Tokens>({ fg: "", muted: "", border: "" });
  const progressRef = useRef(progress);

  // token derive — synchronous, before first paint, so nothing can ever
  // draw with an empty/default ink colour
  useLayoutEffect(() => {
    tokensRef.current = readTokens();
  }, []);

  useEffect(() => {
    progressRef.current = progress;
  }, [progress]);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = mulberry32(0x6a2b1f);
    const lopside: number[] = Array.from({ length: CONTROL_POINTS }, () => (rand() * 2 - 1) * MAX_LOPSIDE);
    const baseAngles = Array.from({ length: CONTROL_POINTS }, (_, i) => (i / CONTROL_POINTS) * Math.PI * 2);

    let width = 0;
    let height = 0;
    let visible = true;
    let raf = 0;
    let clockMs = 0; // accumulated visible elapsed time — drives the indeterminate decay + travel + spin
    let last = 0;

    const computeGeometry = () => {
      const rect = container.getBoundingClientRect();
      width = Math.max(1, rect.width);
      height = Math.max(1, rect.height);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.ceil(width * dpr);
      canvas.height = Math.ceil(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      if (reduced) {
        drawFrame(true);
      } else {
        draw();
      }
    };

    const draw = () => drawFrame(false);

    const drawFrame = (staticFrame: boolean) => {
      if (width === 0 || height === 0) return;
      ctx.clearRect(0, 0, width, height);
      const { fg, muted, border } = tokensRef.current;

      const baseRadius = RADIUS_FRAC * Math.min(width, height);
      const baselineY = height * 0.66;
      const cx0 = width / 2;

      let travelFrac: number;
      let spinRad: number;
      let devFactor: number;

      if (staticFrame) {
        travelFrac = 0; // centred — the structured, legible freeze frame
        spinRad = 0;
        devFactor = Math.pow(DECAY_PER_PASS, STATIC_PASS);
      } else {
        const p = clockMs / PASS_PERIOD_MS;
        travelFrac = TRAVEL_FRAC * Math.sin(p * Math.PI * 2 - Math.PI / 2);
        spinRad = ((clockMs / 1000) * SPIN_DEG_PER_SEC * Math.PI) / 180;
        const heldProgress = progressRef.current;
        if (typeof heldProgress === "number") {
          const passesEq = (Math.max(0, Math.min(100, heldProgress)) / 100) * DETERMINATE_MAX_PASSES;
          devFactor = Math.pow(DECAY_PER_PASS, passesEq);
        } else {
          devFactor = Math.pow(DECAY_PER_PASS, p);
        }
      }

      const centerX = cx0 + travelFrac * width;
      const centerY = baselineY - baseRadius;

      // marver line — a static 1px separator the blob rolls along, never a
      // fill or stroke of the blob itself
      ctx.strokeStyle = border;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, baselineY + 0.5);
      ctx.lineTo(width, baselineY + 0.5);
      ctx.stroke();

      const pts = baseAngles.map((angle, i) => {
        const r = baseRadius * (1 + lopside[i]! * devFactor);
        const a = angle + spinRad;
        return { x: centerX + r * Math.cos(a), y: centerY + r * Math.sin(a) };
      });

      tracePath(ctx, pts);
      const grad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, baseRadius * (1 + MAX_LOPSIDE));
      grad.addColorStop(0, fg);
      grad.addColorStop(1, muted);
      ctx.fillStyle = grad;
      ctx.fill();
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return; // paused: no reschedule, resume path restarts it
      if (last === 0) last = now;
      clockMs += Math.min(100, now - last);
      last = now;
      draw();
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (raf || reduced) return;
      last = 0;
      raf = requestAnimationFrame(loop);
    };

    const ro = new ResizeObserver(computeGeometry);
    ro.observe(container);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible) start();
      },
      { threshold: 0 }
    );
    io.observe(container);

    const onVisibility = () => {
      if (!document.hidden) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        drawFrame(true);
      } else {
        start();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const mo = new MutationObserver(() => {
      tokensRef.current = readTokens();
      if (reduced) drawFrame(true);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });

    computeGeometry();

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      mq.removeEventListener("change", onReducedChange);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const hasProgress = typeof progress === "number";
  const clamped = hasProgress ? Math.max(0, Math.min(100, progress as number)) : undefined;

  return (
    <div
      ref={containerRef}
      role={hasProgress ? "progressbar" : "img"}
      aria-valuemin={hasProgress ? 0 : undefined}
      aria-valuemax={hasProgress ? 100 : undefined}
      aria-valuenow={hasProgress ? Math.round(clamped as number) : undefined}
      aria-label={ariaLabel}
      className={`relative block overflow-hidden ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="block h-full w-full" />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";

// ---------------------------------------------------------------------------
// PlimsollGauge — a capacity/legal-limit meter drawn as a ship's side-profile
// hull with Plimsoll load-line marks (TF/F/S/W), not a liquid-in-a-vessel
// meter (that's meter-quota-meniscus's job) and not an input-strength meter (that's
// password-strength-tide's). Two independent, small effects read as one physical
// system: the waterline (an SVG rect+line pinned to a fixed frame) rises
// directly with `value`, while the hull silhouette itself (a sibling <g>)
// sinks a few px on a separate, smaller spring — cargo settling under its own
// weight, not just a rising tide. The "S" mark sits exactly at `limit`; once
// `value` passes it, that one mark (only that one) flips to --warning amber.
// Every other mark (TF/F/W) is a fixed decorative reference line near it,
// always muted ink, never colored.
//
// Motion: a single rAF loop drives two critically-damped springs (waterline Y,
// hull sink offset) plus, only when motion is allowed, a continuous sine lap
// added on top of the waterline — its amplitude doubles while overloaded.
// prefers-reduced-motion drops the ambient lap entirely and swaps the two
// springs for stiffer, critically-damped ones (no overshoot, well under
// 200ms to settle): value/limit changes still visibly travel to their new
// level rather than teleporting there, since the waterline height is the
// only passive signal of the current value. The
// depth-sounding line (hover or keyboard focus) is a direct, event-driven DOM
// write — two plain divs (a hairline + a mono readout chip), never SVG
// dasharray tricks, following the project's known dash/non-scaling-stroke
// trap for straight indicator lines.
// ---------------------------------------------------------------------------

export interface PlimsollGaugeProps {
  /** Current load, 0-150+ (%). Values above `limit` are overload. */
  value: number;
  /** Legal capacity limit (%) — where the "S" load line sits. Default 100. */
  limit?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const STAGE_W = 280;
const STAGE_H = 170;
const DECK_Y = 26;
const KEEL_Y = 150;
const HULL_LEFT = 34;

// Boat-shaped, not egg-shaped: a wide flat deck, sides that taper firmly
// inward, and a shallow, relatively flat keel line — a hull cross-section,
// not a lens.
const HULL_PATH =
  "M 40 26 L 260 26 C 266 26 268 34 266 48 C 262 90 246 128 210 146 C 190 154 110 154 90 146 C 54 128 38 90 34 48 C 32 34 34 26 40 26 Z";

const SPRING_K = 150;
const SPRING_ZETA = 0.85;
const SPRING_C = 2 * SPRING_ZETA * Math.sqrt(SPRING_K);
const HULL_K = 90;
const HULL_C = 2 * 0.9 * Math.sqrt(HULL_K);
const LAP_AMP = 1.6;
const LAP_AMP_OVERLOAD = 3.4;
const LAP_FREQ = 0.55; // Hz
// Reduced-motion still needs the waterline to visibly travel to its new
// level — a snap-to-target with no interpolation reads as "nothing
// happened," not as reduced motion. These are critically damped (no
// overshoot, no ambient lap) and stiff enough to settle in well under
// 200ms, short of a spring "effect" but long enough to register as motion.
const REDUCED_K = 500;
const REDUCED_ZETA = 1;
const REDUCED_C = 2 * REDUCED_ZETA * Math.sqrt(REDUCED_K);
const REDUCED_HULL_K = 400;
const REDUCED_HULL_C = 2 * 1 * Math.sqrt(REDUCED_HULL_K);

function toY(percent: number): number {
  const y = KEEL_Y - (percent / 100) * (KEEL_Y - DECK_Y);
  return Math.min(KEEL_Y, Math.max(4, y));
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

type MarkKey = "TF" | "F" | "S" | "W";
interface Mark {
  key: MarkKey;
  percent: number;
  isLimit: boolean;
}

// toY() already clamps its own output to a sane pixel range, so these only
// need a loose guard against pathological negative/huge `limit` inputs — a
// tight ceiling here is what previously made TF and F collide at the same y.
function buildMarks(limit: number): Mark[] {
  return [
    { key: "TF", percent: clamp(limit + 28, 2, 140), isLimit: false },
    { key: "F", percent: clamp(limit + 14, 2, 140), isLimit: false },
    { key: "S", percent: clamp(limit, 2, 140), isLimit: true },
    { key: "W", percent: clamp(limit - 14, 2, 140), isLimit: false },
  ];
}

interface Spring {
  pos: number;
  v: number;
  target: number;
}

export function PlimsollGauge({ value, limit = 100, className = "" }: PlimsollGaugeProps) {
  const rootRef = useRef<HTMLButtonElement | null>(null);
  const hullGroupRef = useRef<SVGGElement | null>(null);
  const waterRectRef = useRef<SVGRectElement | null>(null);
  const waterLineRef = useRef<SVGLineElement | null>(null);
  const soundLineRef = useRef<HTMLDivElement | null>(null);
  const soundChipRef = useRef<HTMLDivElement | null>(null);

  const reducedRef = useRef(false);
  const overloadRef = useRef(false);
  const waterSpring = useRef<Spring>({ pos: toY(value), v: 0, target: toY(value) });
  const hullSpring = useRef<Spring>({ pos: 0, v: 0, target: 0 });
  const rafRef = useRef(0);
  const lastRef = useRef(0);
  const pointerXRef = useRef(STAGE_W / 2);

  const [hovering, setHovering] = useState(false);
  const [announce, setAnnounce] = useState("");
  const wasOverloadRef = useRef(false);

  const marks = buildMarks(limit);
  const overload = value > limit;
  overloadRef.current = overload;

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    if (overload !== wasOverloadRef.current) {
      wasOverloadRef.current = overload;
      setAnnounce(overload ? "Over capacity limit" : "Within capacity limit");
    }
  }, [overload]);

  const writeWater = (y: number) => {
    const rect = waterRectRef.current;
    const line = waterLineRef.current;
    if (rect) {
      rect.setAttribute("y", String(y));
      rect.setAttribute("height", String(Math.max(0, STAGE_H - y)));
    }
    if (line) {
      line.setAttribute("y1", String(y));
      line.setAttribute("y2", String(y));
    }
  };

  const writeHull = (offset: number) => {
    const g = hullGroupRef.current;
    if (g) g.style.transform = `translateY(${offset.toFixed(2)}px)`;
  };

  useEffect(() => {
    const targetWaterY = toY(value);
    const targetHullSink = Math.min(10, Math.max(0, (Math.min(value, 130) / 100) * 8));
    waterSpring.current.target = targetWaterY;
    hullSpring.current.target = targetHullSink;
    ensureLoop();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  function ensureLoop() {
    if (rafRef.current) return;
    lastRef.current = 0;
    rafRef.current = requestAnimationFrame(loop);
  }

  function loop(now: number) {
    const dt = Math.min(0.032, lastRef.current ? (now - lastRef.current) / 1000 : 1 / 60);
    lastRef.current = now;

    const reduced = reducedRef.current;
    const kWater = reduced ? REDUCED_K : SPRING_K;
    const cWater = reduced ? REDUCED_C : SPRING_C;
    const kHull = reduced ? REDUCED_HULL_K : HULL_K;
    const cHull = reduced ? REDUCED_HULL_C : HULL_C;

    const w = waterSpring.current;
    const wA = kWater * (w.target - w.pos) - cWater * w.v;
    w.v += wA * dt;
    w.pos += w.v * dt;

    const h = hullSpring.current;
    const hA = kHull * (h.target - h.pos) - cHull * h.v;
    h.v += hA * dt;
    h.pos += h.v * dt;

    // The idle lap is the continuous, ambient part — dropped entirely under
    // reduced motion. The spring settle above stays (critically damped, no
    // overshoot) so a value change still visibly travels to its new level.
    const lap = reduced
      ? 0
      : Math.sin(now / 1000 * Math.PI * 2 * LAP_FREQ) *
        (overloadRef.current ? LAP_AMP_OVERLOAD : LAP_AMP);

    writeWater(w.pos + lap);
    writeHull(h.pos);

    // the idle lap never settles, so the loop simply runs for as long as the
    // component is mounted and visible (paused via visibilitychange below)
    rafRef.current = requestAnimationFrame(loop);
  }

  useEffect(() => {
    const onVis = () => {
      if (document.hidden) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = 0;
      } else if (!reducedRef.current) {
        ensureLoop();
      }
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const positionSounding = (clientX: number) => {
    const root = rootRef.current;
    if (!root) return;
    const rect = root.getBoundingClientRect();
    const scaleX = STAGE_W / rect.width;
    const localX = clamp((clientX - rect.left) * scaleX, 10, STAGE_W - 10);
    pointerXRef.current = localX;
    const scale = rect.width / STAGE_W;
    const line = soundLineRef.current;
    const chip = soundChipRef.current;
    const topPx = 4 * scale;
    const waterYPx = waterSpring.current.pos * scale;
    if (line) {
      line.style.left = `${localX * scale}px`;
      line.style.top = `${topPx}px`;
      line.style.height = `${Math.max(0, waterYPx - topPx)}px`;
    }
    if (chip) {
      chip.style.left = `${localX * scale}px`;
      chip.style.top = `${Math.max(0, waterYPx - 20 * scale)}px`;
    }
  };

  const onEnter = (e: ReactPointerEvent<HTMLButtonElement>) => {
    setHovering(true);
    positionSounding(e.clientX);
  };
  const onMove = (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (hovering) positionSounding(e.clientX);
  };
  const onLeave = () => setHovering(false);
  const onFocus = () => {
    setHovering(true);
    const root = rootRef.current;
    if (root) {
      const rect = root.getBoundingClientRect();
      positionSounding(rect.left + rect.width / 2);
    }
  };
  const onBlur = () => setHovering(false);

  const roundedValue = Math.round(value);
  const ariaLabel = `Capacity gauge: ${roundedValue}% of ${limit}% legal limit${overload ? ", over limit" : ""}`;

  return (
    <button
      type="button"
      ref={rootRef}
      aria-label={ariaLabel}
      onPointerEnter={onEnter}
      onPointerMove={onMove}
      onPointerLeave={onLeave}
      onFocus={onFocus}
      onBlur={onBlur}
      className={`relative block rounded-[12px] border border-border bg-surface p-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
      style={{ width: STAGE_W, height: STAGE_H }}
    >
      <style>{CSS}</style>
      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>

      <svg
        viewBox={`0 0 ${STAGE_W} ${STAGE_H}`}
        width="100%"
        height="100%"
        aria-hidden="true"
        focusable="false"
        className="block"
      >
        <g ref={hullGroupRef} className="ns-pg-hull">
          <path d={HULL_PATH} fill="var(--foreground)" fillOpacity={0.05} stroke="var(--foreground)" strokeWidth={1.25} />
          {marks.map((m) => {
            const y = toY(m.percent);
            const flip = m.isLimit && overload;
            const color = flip ? "var(--warning)" : "var(--ns-muted)";
            return (
              <g key={m.key} className="ns-pg-mark">
                <line
                  x1={HULL_LEFT - 16}
                  x2={HULL_LEFT}
                  y1={y}
                  y2={y}
                  stroke={color}
                  strokeWidth={m.isLimit ? 1.75 : 1}
                />
                <text
                  x={HULL_LEFT - 20}
                  y={y + 3}
                  fontSize={9}
                  textAnchor="end"
                  fill={color}
                  className="font-mono"
                  style={{ fontWeight: m.isLimit ? 700 : 400 }}
                >
                  {m.key}
                </text>
              </g>
            );
          })}
        </g>

        <line ref={waterLineRef} x1={0} x2={STAGE_W} y1={toY(value)} y2={toY(value)} stroke="var(--foreground)" strokeOpacity={0.45} strokeWidth={1} />
        <rect
          ref={waterRectRef}
          x={0}
          y={toY(value)}
          width={STAGE_W}
          height={Math.max(0, STAGE_H - toY(value))}
          fill="var(--foreground)"
          fillOpacity={0.08}
        />
      </svg>

      <div
        ref={soundLineRef}
        aria-hidden="true"
        className="pointer-events-none absolute w-px bg-foreground/60"
        style={{ opacity: hovering ? 1 : 0 }}
      />
      <div
        ref={soundChipRef}
        aria-hidden="true"
        className="pointer-events-none absolute -translate-x-1/2 -translate-y-full whitespace-nowrap rounded-[6px] border border-border bg-background px-1.5 py-0.5 font-mono text-[10px] text-foreground shadow-sm"
        style={{ opacity: hovering ? 1 : 0 }}
      >
        {roundedValue}%
      </div>
    </button>
  );
}

export const CSS = `
.ns-pg-hull{transform-box:fill-box;transform-origin:center;}
@media (prefers-reduced-motion: reduce){
  .ns-pg-hull{transition:none !important;}
}
`;

"use client";

import { useCallback, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GitGraphAsciiLanes — a commit DAG drawn the way `git log --graph` draws one.
//
// The mechanic is a real lane allocator, not a pretty picture of one: a single
// `active: (string|null)[]` array is walked top-to-bottom over the commit list,
// each commit claiming the slot that already expects it (or the lowest free
// slot, or a new one), freeing every OTHER slot that also expected it (a branch
// converging), and opening a slot per extra parent (a merge fanning out). The
// pairs of lanes that open and close between two commit rows are exactly what
// the `├─┐` / `├─┘` connector rows draw, and any live lane a horizontal run
// crosses becomes `┼`.
//
// The whole grid is one `useMemo` over (commits, collapsedMerges) that starts
// from an EMPTY `active` array every time. Nothing is ever patched in place —
// collapsing a merge's side branch re-derives all of it, which is why the braid
// visibly straightens instead of leaving a stale column behind.
// ---------------------------------------------------------------------------

export interface GitCommit {
  id: string;
  subject: string;
  author: string;
  date: string;
  parents: string[];
  /** Branch name, used only to label a collapsed side branch. */
  branch?: string;
}

export interface GitGraphAsciiLanesProps {
  /** the commits, newest first */
  commits?: GitCommit[];
  /** Commit id HEAD points at. Defaults to the first (newest) commit. */
  head?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const MAX_LANES = 6;

const DEFAULT_COMMITS: GitCommit[] = [
  { id: "4e1b7a2", subject: "Bump lockfile after security audit", author: "nik", date: "2h", parents: ["9d2f014"] },
  { id: "9d2f014", subject: "Merge branch 'feat/router' into main", author: "nik", date: "5h", parents: ["1f8a4c3", "3ad91e0"] },
  { id: "1f8a4c3", subject: "Fix range clamp on resize", author: "dee", date: "1d", parents: ["7c02be9"] },
  { id: "7c02be9", subject: "Merge branch 'fix/hydration' into main", author: "sam", date: "2d", parents: ["b6e5170", "0c9d3f4"] },
  { id: "3ad91e0", subject: "Guard against an empty route table", author: "rui", date: "1d", branch: "feat/router", parents: ["c81ba07"] },
  { id: "c81ba07", subject: "Cache compiled matchers per segment", author: "rui", date: "2d", branch: "feat/router", parents: ["5f47d92"] },
  { id: "5f47d92", subject: "Move param parsing off the hot path", author: "rui", date: "3d", branch: "feat/router", parents: ["e29c1b8"] },
  { id: "e29c1b8", subject: "Sketch the segment router interface", author: "rui", date: "3d", branch: "feat/router", parents: ["b6e5170"] },
  { id: "0c9d3f4", subject: "Drop the client-only theme read", author: "dee", date: "2d", branch: "fix/hydration", parents: ["d4a8e6b"] },
  { id: "d4a8e6b", subject: "Reproduce the hydration mismatch in a test", author: "dee", date: "3d", branch: "fix/hydration", parents: ["f70b25c"] },
  { id: "b6e5170", subject: "Split the token map out of the theme provider", author: "nik", date: "4d", parents: ["f70b25c"] },
  { id: "f70b25c", subject: "Add lane allocation to the history view", author: "sam", date: "5d", parents: ["8ae3c40"] },
  { id: "8ae3c40", subject: "Initial commit", author: "nik", date: "6d", parents: [] },
];

type Cell = { ch: string; owner: string | null; lane: number };

type Row =
  | { kind: "commit"; key: string; commit: GitCommit; lane: number; isMerge: boolean; cells: (Cell | null)[] }
  | { kind: "connector"; key: string; cells: (Cell | null)[] }
  | { kind: "group"; key: string; count: number; branch: string; cells: (Cell | null)[] };

/** Every commit reachable from `start` by walking `parents`. */
function reachable(byId: Map<string, GitCommit>, start: string): Set<string> {
  const seen = new Set<string>();
  const queue = [start];
  while (queue.length) {
    const id = queue.shift() as string;
    if (seen.has(id)) continue;
    seen.add(id);
    const node = byId.get(id);
    if (node) for (const p of node.parents) if (!seen.has(p)) queue.push(p);
  }
  return seen;
}

function buildGrid(commits: GitCommit[], collapsed: ReadonlySet<string>) {
  const byId = new Map(commits.map((c) => [c.id, c]));

  // --- which rows are hidden behind a collapsed merge -----------------------
  const hidden = new Set<string>();
  const groups = new Map<string, { count: number; branch: string }>();
  for (const mergeId of collapsed) {
    const m = byId.get(mergeId);
    if (!m || m.parents.length < 2) continue;
    const mainline = reachable(byId, m.parents[0]);
    const side = new Set<string>();
    for (const p of m.parents.slice(1)) {
      for (const id of reachable(byId, p)) if (!mainline.has(id)) side.add(id);
    }
    if (side.size === 0) continue;
    // A side commit that some OTHER visible commit still points at must stay
    // visible: hiding it would leave the lane expecting it open all the way to
    // the bottom of the graph. Refuse the collapse rather than emit a stray lane.
    let escapes = false;
    for (const other of commits) {
      if (other.id === mergeId || side.has(other.id) || hidden.has(other.id)) continue;
      if (other.parents.some((p) => side.has(p))) {
        escapes = true;
        break;
      }
    }
    if (escapes) continue;
    for (const id of side) hidden.add(id);
    groups.set(mergeId, {
      count: side.size,
      branch: byId.get(m.parents[1])?.branch ?? "side branch",
    });
  }

  // --- the lane allocator ---------------------------------------------------
  const active: (string | null)[] = [];
  let laneCount = 0;
  type Pair = { a: number; b: number; open: boolean };
  const raw: {
    commit: GitCommit;
    lane: number;
    isMerge: boolean;
    snapshot: (string | null)[];
    after: (string | null)[];
    pairs: Pair[];
  }[] = [];

  for (const c of commits) {
    if (hidden.has(c.id)) continue;
    // A collapsed merge is walked as if it had only its first parent, so the
    // side lane is never opened at all — that is what straightens the braid.
    const parents = collapsed.has(c.id) && groups.has(c.id) ? c.parents.slice(0, 1) : c.parents;

    let lane = active.indexOf(c.id);
    if (lane === -1) lane = active.indexOf(null);
    if (lane === -1) lane = active.push(null) - 1;
    active[lane] = c.id;

    const snapshot = active.slice();
    const pairs: Pair[] = [];

    // every OTHER slot expecting this commit is a branch converging here
    for (let i = 0; i < active.length; i++) {
      if (i !== lane && active[i] === c.id) {
        active[i] = null;
        pairs.push({ a: i, b: lane, open: false });
      }
    }

    active[lane] = parents[0] ?? null;

    for (let k = 1; k < parents.length; k++) {
      const p = parents[k];
      let pLane = active.indexOf(p);
      if (pLane === -1) pLane = active.indexOf(null);
      if (pLane === -1) pLane = active.push(null) - 1;
      active[pLane] = p;
      pairs.push({ a: lane, b: pLane, open: true });
    }

    laneCount = Math.max(laneCount, active.length, snapshot.length);
    raw.push({ commit: c, lane, isMerge: c.parents.length > 1, snapshot, after: active.slice(), pairs });
  }

  // --- glyph emission -------------------------------------------------------
  const overflow = laneCount > MAX_LANES;
  const colOf = (lane: number) => Math.min(lane, MAX_LANES - 1) * 2;
  const laneGlyph = (lane: number, ch: string) => (overflow && lane >= MAX_LANES - 1 ? "⋯" : ch);
  const width = Math.min(laneCount, MAX_LANES) * 2 - 1;

  const blank = (): (Cell | null)[] => new Array(Math.max(width, 1)).fill(null);
  const rows: Row[] = [];

  for (const r of raw) {
    // commit row: ● (or ◍ for a merge) at its own lane, │ at every other live lane
    const cells = blank();
    for (let i = 0; i < r.snapshot.length; i++) {
      const owner = r.snapshot[i];
      if (!owner) continue;
      const ch = i === r.lane ? (r.isMerge ? "◍" : "●") : "│";
      cells[colOf(i)] = { ch: laneGlyph(i, ch), owner, lane: i };
    }
    rows.push({ kind: "commit", key: r.commit.id, commit: r.commit, lane: r.lane, isMerge: r.isMerge, cells });

    const group = groups.get(r.commit.id);
    if (group) {
      const gcells = blank();
      for (let i = 0; i < r.after.length; i++) {
        const owner = r.after[i];
        if (owner) gcells[colOf(i)] = { ch: laneGlyph(i, "│"), owner, lane: i };
      }
      rows.push({ kind: "group", key: `${r.commit.id}:group`, count: group.count, branch: group.branch, cells: gcells });
    }

    if (r.pairs.length === 0) continue;

    // connector row: live lanes first, then every open/close pair drawn over them
    const cc = blank();
    for (let i = 0; i < r.after.length; i++) {
      const owner = r.after[i];
      if (owner) cc[colOf(i)] = { ch: laneGlyph(i, "│"), owner, lane: i };
    }
    for (const pair of r.pairs) {
      const lo = Math.min(pair.a, pair.b);
      const hi = Math.max(pair.a, pair.b);
      const cLo = colOf(lo);
      const cHi = colOf(hi);
      cc[cLo] = { ch: "├", owner: r.commit.id, lane: lo };
      for (let x = cLo + 1; x < cHi; x++) {
        const held = cc[x];
        cc[x] = held && held.ch === "│" ? { ...held, ch: "┼" } : { ch: "─", owner: r.commit.id, lane: -1 };
      }
      cc[cHi] = { ch: pair.open ? "┐" : "┘", owner: r.commit.id, lane: hi };
    }
    rows.push({ kind: "connector", key: `${r.commit.id}:conn`, cells: cc });
  }

  return { rows, byId };
}

export function GitGraphAsciiLanes({
  commits = DEFAULT_COMMITS,
  head,
  className = "",
}: GitGraphAsciiLanesProps) {
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set<string>());
  const [hoverId, setHoverId] = useState<string | null>(null);
  const [pinnedId, setPinnedId] = useState<string | null>(null);
  const [focusIndex, setFocusIndex] = useState(0);
  const buttonsRef = useRef<(HTMLButtonElement | null)[]>([]);

  const headId = head ?? commits[0]?.id ?? null;
  const activeId = hoverId ?? pinnedId;

  const { rows, byId } = useMemo(() => buildGrid(commits, collapsed), [commits, collapsed]);

  const ancestors = useMemo(() => {
    if (!activeId) return null;
    return reachable(byId, activeId);
  }, [activeId, byId]);

  const commitRows = rows.filter((r) => r.kind === "commit") as Extract<Row, { kind: "commit" }>[];
  // Collapsing a merge removes rows, so a stale focusIndex could point past the
  // end and leave NO row with tabIndex 0 — Tab would then skip the graph
  // entirely. Clamp at render instead of trusting the stored index.
  const rovingIndex = Math.min(focusIndex, Math.max(0, commitRows.length - 1));
  buttonsRef.current.length = commitRows.length;

  const lit = useCallback(
    (owner: string | null) => !ancestors || (owner !== null && ancestors.has(owner)),
    [ancestors],
  );

  const toneOf = (cell: Cell) => {
    if (ancestors) {
      if (!lit(cell.owner)) return "text-border";
      if (cell.owner === headId && (cell.ch === "●" || cell.ch === "◍")) return "text-ns-accent";
      return "text-foreground";
    }
    if (cell.owner === headId && (cell.ch === "●" || cell.ch === "◍")) return "text-ns-accent";
    // At rest the whole braid must be legible — the trunk reads at full ink and
    // every other lane at --ns-muted. --border is reserved for the DIMMED state
    // above, so "not an ancestor" stays visually distinct from "off-trunk".
    return cell.lane === 0 ? "text-foreground" : "text-ns-muted";
  };

  const glyphs = (cells: (Cell | null)[]) => (
    <span aria-hidden className="whitespace-pre">
      {cells.map((cell, i) =>
        cell ? (
          <span key={i} className={`transition-colors duration-[140ms] motion-reduce:transition-none ${toneOf(cell)}`}>
            {cell.ch}
          </span>
        ) : (
          <span key={i}> </span>
        ),
      )}
    </span>
  );

  const moveFocus = (next: number) => {
    const clamped = Math.max(0, Math.min(commitRows.length - 1, next));
    setFocusIndex(clamped);
    buttonsRef.current[clamped]?.focus();
  };

  const toggleCollapse = (id: string) => {
    setCollapsed((prev) => {
      const nx = new Set(prev);
      if (nx.has(id)) nx.delete(id);
      else nx.add(id);
      return nx;
    });
  };

  let commitIndex = -1;

  return (
    <div className={`ns-gga font-mono text-[12px] leading-[20px] ${className}`}>
      <style>{CSS}</style>
      <div role="group" aria-label="Commit history graph">
        {rows.map((row) => {
          if (row.kind === "connector") {
            return (
              <div key={row.key} className="ns-gga-line select-none" aria-hidden>
                {glyphs(row.cells)}
              </div>
            );
          }

          if (row.kind === "group") {
            return (
              <div key={row.key} data-commit-group className="ns-gga-line flex items-center gap-3 select-none">
                {glyphs(row.cells)}
                <span className="text-ns-muted">
                  ⋯ {row.count} commits from {row.branch}
                </span>
              </div>
            );
          }

          commitIndex += 1;
          const idx = commitIndex;
          const c = row.commit;
          const dim = ancestors !== null && !ancestors.has(c.id);
          const isHead = c.id === headId;
          const shaTone = dim ? "text-border" : isHead ? "text-ns-accent" : "text-ns-muted";
          const subjectTone = dim ? "text-border" : "text-foreground";
          const metaTone = dim ? "text-border" : "text-ns-muted";

          return (
            <button
              key={row.key}
              type="button"
              ref={(el) => {
                buttonsRef.current[idx] = el;
              }}
              data-commit={c.id}
              {...(row.isMerge ? { "data-commit-merge": "" } : {})}
              tabIndex={idx === rovingIndex ? 0 : -1}
              aria-expanded={row.isMerge ? !collapsed.has(c.id) : undefined}
              aria-label={
                `${c.subject}. Commit ${c.id} by ${c.author}, ${c.date} ago` +
                (isHead ? ", HEAD" : "") +
                (row.isMerge
                  ? `. Merge commit — press Enter to ${collapsed.has(c.id) ? "expand" : "collapse"} the merged branch`
                  : ". Press Enter to hold its ancestor highlight")
              }
              className="ns-gga-row ns-gga-line flex w-full items-center gap-3 text-left"
              onPointerEnter={() => setHoverId(c.id)}
              onPointerLeave={() => setHoverId((cur) => (cur === c.id ? null : cur))}
              onFocus={() => {
                setFocusIndex(idx);
                setHoverId(c.id);
              }}
              onBlur={() => setHoverId((cur) => (cur === c.id ? null : cur))}
              onClick={() => {
                if (row.isMerge) toggleCollapse(c.id);
                else setPinnedId((cur) => (cur === c.id ? null : c.id));
              }}
              onKeyDown={(e) => {
                if (e.key === "ArrowDown") {
                  e.preventDefault();
                  moveFocus(idx + 1);
                } else if (e.key === "ArrowUp") {
                  e.preventDefault();
                  moveFocus(idx - 1);
                } else if (e.key === "Home") {
                  e.preventDefault();
                  moveFocus(0);
                } else if (e.key === "End") {
                  e.preventDefault();
                  moveFocus(commitRows.length - 1);
                } else if (e.key === "Escape") {
                  setHoverId(null);
                  setPinnedId(null);
                }
              }}
            >
              {glyphs(row.cells)}
              <span className={`shrink-0 transition-colors duration-[140ms] motion-reduce:transition-none ${shaTone}`}>
                {c.id}
              </span>
              <span
                className={`flex-1 truncate transition-colors duration-[140ms] motion-reduce:transition-none ${subjectTone}`}
              >
                {c.subject}
              </span>
              <span
                className={`shrink-0 tabular-nums transition-colors duration-[140ms] motion-reduce:transition-none ${metaTone}`}
              >
                {c.author} · {c.date}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

const CSS = `
.ns-gga-line { min-height: 20px; }
.ns-gga-row { cursor: pointer; }
.ns-gga-row:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: -2px; }
`;

"use client";

import { useLayoutEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GlazeCrawlHeal — a live status badge drawn as a glaze surface mid-firing,
// not three arbitrary colour chips. In a kiln the glaze goes molten and gas
// bubbles rise through the melt and burst at the surface, leaving craters;
// whether the melt's viscosity and surface tension let it FLOW BACK over
// that crater (heals smooth) or not (crawling — the glaze pulls away from
// the body into a bare patch that never closes) is a real, named ceramics
// defect, not an invented metaphor. That gives the badge one physical state
// axis instead of a colour code: healthy = bubbles burst and heal in well
// under a second; degraded = the melt is thicker, craters linger for
// seconds before closing; down = surface tension has failed outright —
// bubbles still burst (gas still escapes) but the melt never flows back, so
// ragged, beaded-rim bare patches accumulate and persist. Unlike craze-rule
// (a static fracture-crack divider that draws in once and idles), this has
// no crack geometry at all — it is continuous bubble nucleation, bursting
// and healing/failing-to-heal, forever, because the glaze stays molten for
// as long as the system is up. The canvas is pure decoration on top of a
// real, always-present text status (STATUS_LABEL) inside a role="status"
// aria-live region — colour never carries the message alone. Ink is read
// once via getComputedStyle(canvas).color (the canvas carries text-
// foreground) in useLayoutEffect, before first paint, and re-read on a
// documentElement class MutationObserver; craters/patches are punched with
// globalCompositeOperation="destination-out" rather than painted in a
// second token, so a "hole" always reveals whatever sits behind the badge —
// dark-on-light in light theme, light-on-dark in dark, for free. Zero deps,
// one DPR-capped canvas, one rAF loop paused on prefers-reduced-motion,
// tab-hidden and unmount.
// ---------------------------------------------------------------------------

export type GlazeStatus = "healthy" | "degraded" | "down";

export interface GlazeCrawlHealProps {
  /** the kiln state to render. default "healthy". */
  status?: GlazeStatus;
  /**
   * accessible text announced via the component's own role="status" region
   * on every change. Defaults to the plain status name ("Operational").
   */
  label?: string;
  /** render `label` as a visible text node beside the badge (still announced either way). default true — a status control's text is not optional. */
  showLabel?: boolean;
  /** badge diameter in px. Reads down to ~14; below that the mechanic itself stops resolving and only the text still carries the state — see component header. default 16. */
  size?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const STATUS_LABEL: Record<GlazeStatus, string> = {
  healthy: "Operational",
  degraded: "Degraded",
  down: "Down",
};

const TAU = Math.PI * 2;
const JAG_POINTS = 11; // ragged-edge vertex count for a crawled (bare) patch

// Per-status kiln parameters. healMs is the viscosity/surface-tension read:
// short = fluid enough to close fast, long = it only just manages to close.
// A "down" patch never gets a healMs of its own — it doesn't heal — until
// the badge recovers to a status that has one (see the status-change effect
// below), at which point the melt finally flows back over it.
const BUBBLE_CONFIG: Record<
  "healthy" | "degraded",
  {
    spawnMs: [number, number];
    openMs: number;
    healMs: [number, number];
    maxRFrac: number;
    maxConcurrent: number;
  }
> = {
  healthy: { spawnMs: [650, 1500], openMs: 150, healMs: [350, 550], maxRFrac: 0.3, maxConcurrent: 1 },
  degraded: { spawnMs: [1100, 2200], openMs: 220, healMs: [1700, 3100], maxRFrac: 0.42, maxConcurrent: 2 },
};
const PATCH_CONFIG = {
  spawnMs: [900, 1800] as [number, number],
  creepTauMs: 1300,
  maxRFrac: 0.52,
  maxConcurrent: 3,
};

function easeOutCubic(t: number) {
  const p = 1 - t;
  return 1 - p * p * p;
}
function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

/** mulberry32 — small, fast, deterministic given a seed */
function mulberry32(seed: number) {
  let s = seed | 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** per-vertex radius multipliers (0.72..1.06) for a crawled patch's ragged rim */
function makeJag(seed: number): number[] {
  const rng = mulberry32(seed);
  const out: number[] = [];
  for (let i = 0; i < JAG_POINTS; i++) out.push(0.72 + rng() * 0.34);
  return out;
}

// fixed seeds -> deterministic, byte-stable jag shapes for the
// prefers-reduced-motion freeze frame (no Math.random there, ever).
const DOWN_JAG_A = makeJag(101);
const DOWN_JAG_B = makeJag(202);

type Feature = {
  kind: "bubble" | "patch";
  x: number;
  y: number; // offset from disc centre, CSS px
  maxR: number; // CSS px
  bornAt: number;
  openMs: number;
  healMs: number; // set once healing begins; Infinity/unused until then
  healingSince: number | null;
  healStartR: number;
  creepTau: number;
  wobblePhase: number;
  jag: number[] | null; // null = perfect circle (bubble); set = ragged patch
};

type DrawSpec = {
  x: number;
  y: number;
  r: number;
  jag: number[] | null;
  rimAlpha: number;
  flash: number;
};

function drawFeature(
  ctx: CanvasRenderingContext2D,
  ink: string,
  cx: number,
  cy: number,
  R0: number,
  f: DrawSpec,
) {
  if (f.r <= 0.3) return;
  ctx.save();
  ctx.translate(cx + f.x, cy + f.y);

  ctx.globalCompositeOperation = "destination-out";
  ctx.beginPath();
  if (f.jag) {
    for (let i = 0; i < JAG_POINTS; i++) {
      const a = (i / JAG_POINTS) * TAU;
      const rad = f.r * f.jag[i]!;
      const px = Math.cos(a) * rad;
      const py = Math.sin(a) * rad;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  } else {
    ctx.arc(0, 0, f.r, 0, TAU);
  }
  ctx.fill();

  ctx.globalCompositeOperation = "source-over";
  if (f.jag) {
    // beaded rim: glaze that pulled away balls up at the receding edge
    // instead of flowing back — the visible signature of crawling.
    ctx.fillStyle = ink;
    for (let i = 0; i < JAG_POINTS; i++) {
      const a = (i / JAG_POINTS) * TAU;
      const rad = f.r * f.jag[i]!;
      const px = Math.cos(a) * rad;
      const py = Math.sin(a) * rad;
      ctx.globalAlpha = 0.5 + 0.35 * ((i * 5) % 4) / 4;
      ctx.beginPath();
      ctx.arc(px, py, Math.max(0.55, R0 * 0.045), 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  } else if (f.rimAlpha > 0) {
    // healing crater's raised lip
    ctx.strokeStyle = ink;
    ctx.globalAlpha = f.rimAlpha;
    ctx.lineWidth = Math.max(0.6, R0 * 0.05);
    ctx.beginPath();
    ctx.arc(0, 0, f.r + R0 * 0.02, 0, TAU);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  if (f.flash > 0) {
    ctx.strokeStyle = ink;
    ctx.globalAlpha = f.flash;
    ctx.lineWidth = Math.max(0.8, R0 * 0.09);
    ctx.beginPath();
    ctx.arc(0, 0, f.r * 1.02, 0, TAU);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  ctx.restore();
}

function renderFrame(
  ctx: CanvasRenderingContext2D,
  ink: string,
  w: number,
  h: number,
  cx: number,
  cy: number,
  R0: number,
  sheenAngle: number,
  specs: DrawSpec[],
) {
  ctx.clearRect(0, 0, w, h);
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = ink;
  ctx.globalAlpha = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, R0, 0, TAU);
  ctx.fill();

  // a slow-drifting specular dim patch — the melt still reads as liquid in
  // the gaps between bubble events, never a flat dead disc.
  ctx.globalCompositeOperation = "destination-out";
  const sx = cx + Math.cos(sheenAngle) * R0 * 0.5;
  const sy = cy + Math.sin(sheenAngle) * R0 * 0.5;
  ctx.globalAlpha = 0.08;
  ctx.beginPath();
  ctx.ellipse(sx, sy, R0 * 0.42, R0 * 0.3, sheenAngle, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";

  for (const f of specs) drawFeature(ctx, ink, cx, cy, R0, f);
}

/** deterministic freeze frame per status — craters/patches at varied stages of healing, never mid-t0 */
function staticSpecs(status: GlazeStatus, R0: number): DrawSpec[] {
  if (status === "healthy") {
    const maxR = R0 * BUBBLE_CONFIG.healthy.maxRFrac;
    return [
      { x: -R0 * 0.3, y: -R0 * 0.12, r: maxR * 0.55, jag: null, rimAlpha: 0.35, flash: 0 },
      { x: R0 * 0.34, y: R0 * 0.28, r: maxR * 0.15, jag: null, rimAlpha: 0.45, flash: 0 },
    ];
  }
  if (status === "degraded") {
    const maxR = R0 * BUBBLE_CONFIG.degraded.maxRFrac;
    return [
      { x: -R0 * 0.3, y: -R0 * 0.22, r: maxR * 0.92, jag: null, rimAlpha: 0.5, flash: 0 },
      { x: R0 * 0.28, y: R0 * 0.1, r: maxR * 0.55, jag: null, rimAlpha: 0.4, flash: 0 },
      { x: 0, y: R0 * 0.36, r: maxR * 0.2, jag: null, rimAlpha: 0.45, flash: 0 },
    ];
  }
  const maxR = R0 * PATCH_CONFIG.maxRFrac;
  return [
    { x: -R0 * 0.24, y: -R0 * 0.18, r: maxR * 0.9, jag: DOWN_JAG_A, rimAlpha: 0, flash: 0 },
    { x: R0 * 0.3, y: R0 * 0.26, r: maxR * 0.4, jag: DOWN_JAG_B, rimAlpha: 0, flash: 0 },
  ];
}

export function GlazeCrawlHeal({
  status = "healthy",
  label,
  showLabel = true,
  size = 16,
  className = "",
}: GlazeCrawlHealProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<{ setStatus: (s: GlazeStatus) => void } | null>(null);

  // -- token derivation happens before first paint, so nothing ever paints
  // with a default/unset ink colour --
  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let ink = "";
    let w = 0;
    let h = 0;
    let cx = 0;
    let cy = 0;
    let R0 = 0;
    let raf = 0;
    let nextSpawnAt = 0;
    let statusCur: GlazeStatus = status;
    const features: Feature[] = [];

    const readInk = () => {
      ink = getComputedStyle(canvas).color;
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = size;
      h = size;
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cx = w / 2;
      cy = h / 2;
      R0 = (Math.min(w, h) / 2) * 0.86;
    };

    const drawStatic = () => {
      renderFrame(ctx, ink, w, h, cx, cy, R0, -0.8, staticSpecs(statusCur, R0));
    };

    const maxRFor = (kind: "healthy" | "degraded" | "down") =>
      R0 * (kind === "down" ? PATCH_CONFIG.maxRFrac : BUBBLE_CONFIG[kind].maxRFrac);

    let featureSeed = 1;

    const maybeSpawn = (now: number) => {
      if (now < nextSpawnAt) return;
      if (statusCur === "down") {
        if (features.length < PATCH_CONFIG.maxConcurrent) {
          const margin = Math.max(0, R0 * 0.9 - maxRFor("down"));
          const ang = Math.random() * TAU;
          const dist = Math.random() * margin;
          features.push({
            kind: "patch",
            x: Math.cos(ang) * dist,
            y: Math.sin(ang) * dist,
            maxR: maxRFor("down") * (0.6 + Math.random() * 0.4),
            bornAt: now,
            openMs: 0,
            healMs: 0,
            healingSince: null,
            healStartR: 0,
            creepTau: PATCH_CONFIG.creepTauMs * (0.8 + Math.random() * 0.5),
            wobblePhase: Math.random() * TAU,
            jag: makeJag(featureSeed++),
          });
        }
        const [a, b] = PATCH_CONFIG.spawnMs;
        nextSpawnAt = now + a + Math.random() * (b - a);
        return;
      }
      const cfg = BUBBLE_CONFIG[statusCur];
      if (features.length < cfg.maxConcurrent) {
        const margin = Math.max(0, R0 * 0.9 - maxRFor(statusCur));
        const ang = Math.random() * TAU;
        const dist = Math.random() * margin;
        const [hMin, hMax] = cfg.healMs;
        features.push({
          kind: "bubble",
          x: Math.cos(ang) * dist,
          y: Math.sin(ang) * dist,
          maxR: R0 * cfg.maxRFrac * (0.7 + Math.random() * 0.5),
          bornAt: now,
          openMs: cfg.openMs,
          healMs: hMin + Math.random() * (hMax - hMin),
          healingSince: null,
          healStartR: 0,
          creepTau: 0,
          wobblePhase: 0,
          jag: null,
        });
      }
      const [a, b] = cfg.spawnMs;
      nextSpawnAt = now + a + Math.random() * (b - a);
    };

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (document.hidden) return;

      maybeSpawn(now);

      const specs: DrawSpec[] = [];
      for (let i = features.length - 1; i >= 0; i--) {
        const f = features[i]!;
        const age = now - f.bornAt;
        let r = 0;
        let rimAlpha = 0;
        let flash = 0;
        let dead = false;

        if (f.kind === "bubble") {
          if (f.healingSince == null) {
            if (age < f.openMs) {
              r = f.maxR * easeOutCubic(f.openMs > 0 ? age / f.openMs : 1);
            } else {
              f.healingSince = f.bornAt + f.openMs;
            }
          }
          if (f.healingSince != null) {
            const hAge = now - f.healingSince;
            if (hAge >= f.healMs) {
              dead = true;
            } else {
              r = f.maxR * (1 - easeInOutCubic(hAge / f.healMs));
              rimAlpha = 0.15 + 0.35 * (1 - hAge / f.healMs);
            }
          }
          const peak = f.bornAt + f.openMs;
          const df = Math.abs(now - peak);
          if (df < 120) flash = 1 - df / 120;
        } else {
          // patch — burst once (gas still escapes) then either creeps
          // (still failing to close) or, post-recovery, heals like a bubble
          if (f.healingSince == null) {
            r = f.maxR * (1 - Math.exp(-age / f.creepTau));
            r *= 1 + 0.03 * Math.sin(age * 0.0025 + f.wobblePhase);
            if (age < 130) flash = 1 - age / 130;
          } else {
            const hAge = now - f.healingSince;
            if (hAge >= f.healMs) {
              dead = true;
            } else {
              r = f.healStartR * (1 - easeInOutCubic(hAge / f.healMs));
            }
          }
        }

        if (dead) {
          features.splice(i, 1);
          continue;
        }
        specs.push({ x: f.x, y: f.y, r, jag: f.jag, rimAlpha, flash });
      }

      const sheenAngle = now * 0.00015;
      renderFrame(ctx, ink, w, h, cx, cy, R0, sheenAngle, specs);
    };

    const start = () => {
      if (reduced || raf) return;
      raf = requestAnimationFrame(tick);
    };
    const stop = () => {
      cancelAnimationFrame(raf);
      raf = 0;
    };

    engineRef.current = {
      setStatus: (next) => {
        const prev = statusCur;
        statusCur = next;
        if (prev === "down" && next !== "down") {
          // conditions recovered — the melt can finally flow back over
          // whatever crawled while it was down.
          const now = performance.now();
          const cfg = BUBBLE_CONFIG[next];
          const [hMin, hMax] = cfg.healMs;
          for (const f of features) {
            if (f.kind === "patch" && f.healingSince == null) {
              const age = now - f.bornAt;
              const r =
                f.maxR *
                (1 - Math.exp(-age / f.creepTau)) *
                (1 + 0.03 * Math.sin(age * 0.0025 + f.wobblePhase));
              f.healStartR = r;
              f.healingSince = now;
              f.healMs = hMin + Math.random() * (hMax - hMin);
            }
          }
        }
        if (reduced) drawStatic();
        else start();
      },
    };

    const onVis = () => {
      if (!document.hidden) start();
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      readInk();
      if (reduced) drawStatic();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    readInk();
    resize();
    if (reduced) drawStatic();
    else start();

    return () => {
      engineRef.current = null;
      stop();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [size]);

  useLayoutEffect(() => {
    engineRef.current?.setStatus(status);
  }, [status]);

  const text = label ?? STATUS_LABEL[status];

  return (
    <span
      role="status"
      aria-live="polite"
      data-glaze-status={status}
      className={`inline-flex shrink-0 items-center gap-2 ${className}`}
    >
      <span
        aria-hidden
        className="inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full border border-border"
        style={{ width: size, height: size }}
      >
        <canvas ref={canvasRef} className="block text-foreground" />
      </span>
      {showLabel ? (
        <span className="font-mono text-xs text-foreground">{text}</span>
      ) : (
        <span className="sr-only">{text}</span>
      )}
    </span>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GloryHoleCycle — a "still actively processing" status chip modeled on a
// glassblower's glory-hole reheat cycle, not a generic pulsing dot. Real hot
// glass cools the instant it leaves the furnace mouth, so a gaffer plunges
// the piece back in on a steady beat to bring it back to working heat, then
// pulls it out to work it while hot — repeat for as long as the piece is
// still being formed. The chip's small circular canvas plays that exact
// rhythm: a fast reheat ramp (cubic ease-out, 0.7s) up to peak "hot" then a
// slow radiative cool (exponential decay, tau=1.1s) back down, on a fixed,
// non-negotiable 4.0s beat for as long as the process is active. Both ends
// of the sweep interpolate luminance ONLY — the disc's colour is a straight
// RGB lerp between the live var(--ns-muted) and var(--foreground) values (no
// hue, ever, and never var(--ns-accent), which is interaction chrome only).
// A subtle 1px inner ring pulses opacity in lockstep with the same
// rise/decay curve, reading as a discrete "reinsertion" event on every beat
// rather than a continuous shimmer.
//
// Tokens are read once via getComputedStyle(document.documentElement) before
// any paint, and re-read on every class-attribute mutation of <html> (a
// MutationObserver) so a live theme toggle repaints the next frame with the
// new muted/foreground pair — no literal colour anywhere, including the
// gradient's alpha fallback stops. The canvas is a fixed 36x36 CSS-px circle
// (DPR-scaled on mount and on resize, since that's the one thing that can
// change this chip's device pixel ratio without remounting it) — the spec
// for this exact mechanic hard-codes that size rather than deriving it from
// a container, since the chip is always rendered at this one physical scale
// next to a text label, never stretched to fill a card.
//
// The animation loop pauses via IntersectionObserver when the chip scrolls
// off-screen and resumes on a fresh cycle boundary, and is cancelled outright
// on unmount along with both observers — no leaked rAF, no leaked observer.
// prefers-reduced-motion skips the loop entirely and paints one frozen frame
// at t=0.7s into the cycle (L=Lmax, ring=0.4) — the peak of the reheat ramp,
// the single frame that most clearly reads "hot" rather than an ambiguous
// mid-decay grey.
// ---------------------------------------------------------------------------

const CYCLE_MS = 4000; // fixed, non-negotiable cadence
const RAMP_MS = 700; // reheat ramp: cubic ease-out, Lmin -> Lmax
const DECAY_TAU_MS = 1100; // cool decay: exponential, tau = 1.1s
const L_MIN = 0.18; // near --ns-muted
const L_MAX = 0.92; // near --foreground
const RING_MIN = 0.15;
const RING_MAX = 0.4;
const CANVAS_CSS = 36; // fixed 36x36 CSS px, per spec

type Rgb = [number, number, number];

function parseColor(input: string): Rgb {
  const trimmed = input.trim();
  const fn = trimmed.match(/rgba?\(([^)]+)\)/i);
  if (fn) {
    const parts = fn[1]!.split(",").map((s) => parseFloat(s.trim()));
    return [parts[0] ?? 0, parts[1] ?? 0, parts[2] ?? 0];
  }
  const hex = trimmed.replace("#", "");
  const full = hex.length === 3 ? hex.split("").map((c) => c + c).join("") : hex;
  const num = parseInt(full || "808080", 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

// cubic ease-out, 0..1 -> 0..1
function easeOutCubic(t: number): number {
  const p = 1 - t;
  return 1 - p * p * p;
}

interface GlowState {
  L: number;
  ring: number;
}

// where the cycle is at msInCycle: fast eased rise for the reheat ramp, then
// an exponential radiative decay for the rest of the 4.0s beat. The ring
// opacity rides the identical curve mapped onto its own 0.15-0.4 range, so
// the two read as one discrete "reinsertion" pulse rather than two loops.
function stateAt(msInCycle: number): GlowState {
  if (msInCycle < RAMP_MS) {
    const p = easeOutCubic(msInCycle / RAMP_MS);
    return { L: lerp(L_MIN, L_MAX, p), ring: lerp(RING_MIN, RING_MAX, p) };
  }
  const k = Math.exp(-(msInCycle - RAMP_MS) / DECAY_TAU_MS);
  return {
    L: L_MIN + (L_MAX - L_MIN) * k,
    ring: RING_MIN + (RING_MAX - RING_MIN) * k,
  };
}

export interface GloryHoleCycleProps {
  /** status text rendered beside the glow and announced on the live region. default "Processing". */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GloryHoleCycle({
  label = "Processing",
  className = "",
}: GloryHoleCycleProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);
  const mutedRgb = useRef<Rgb>([128, 128, 128]);
  const fgRgb = useRef<Rgb>([0, 0, 0]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ring = ringRef.current;
    if (!canvas || !ring) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      mutedRgb.current = parseColor(cs.getPropertyValue("--ns-muted") || "#808080");
      fgRgb.current = parseColor(cs.getPropertyValue("--foreground") || "#000000");
    };

    // no paint before the first token read
    readTokens();

    let dpr = Math.max(1, window.devicePixelRatio || 1);

    const sizeCanvas = () => {
      dpr = Math.max(1, window.devicePixelRatio || 1);
      canvas.width = Math.round(CANVAS_CSS * dpr);
      canvas.height = Math.round(CANVAS_CSS * dpr);
      canvas.style.width = `${CANVAS_CSS}px`;
      canvas.style.height = `${CANVAS_CSS}px`;
    };
    sizeCanvas();

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const paint = ({ L, ring: ringOpacity }: GlowState) => {
      const t = (L - L_MIN) / (L_MAX - L_MIN);
      const [mr, mg, mb] = mutedRgb.current;
      const [fr, fg, fb] = fgRgb.current;
      const r = Math.round(lerp(mr, fr, t));
      const g = Math.round(lerp(mg, fg, t));
      const b = Math.round(lerp(mb, fb, t));

      const cx = CANVAS_CSS / 2;
      const cy = CANVAS_CSS / 2;
      const radius = Math.min(CANVAS_CSS, CANVAS_CSS) * 0.6;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, CANVAS_CSS, CANVAS_CSS);

      const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
      grad.addColorStop(0, `rgba(${r}, ${g}, ${b}, 1)`);
      grad.addColorStop(0.7, `rgba(${r}, ${g}, ${b}, 0.55)`);
      grad.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.fill();

      ring.style.opacity = ringOpacity.toFixed(3);
      ring.style.borderColor = `rgb(${fr}, ${fg}, ${fb})`;
    };

    let raf = 0;
    let startTime = 0;

    const loop = (now: number) => {
      if (startTime === 0) startTime = now;
      const msInCycle = (now - startTime) % CYCLE_MS;
      paint(stateAt(msInCycle));
      raf = requestAnimationFrame(loop);
    };

    if (reduced) {
      paint(stateAt(RAMP_MS)); // frozen at the peak of the reheat ramp
    } else {
      raf = requestAnimationFrame(loop);
    }

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) paint(stateAt(RAMP_MS));
      // animated path just picks the fresh tokens up on its next rAF frame
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let io: IntersectionObserver | null = null;
    if (!reduced) {
      io = new IntersectionObserver((entries) => {
        const visible = entries[0]?.isIntersecting ?? true;
        if (visible && !raf) {
          startTime = 0; // resume clean on a fresh cycle boundary
          raf = requestAnimationFrame(loop);
        } else if (!visible && raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      });
      io.observe(canvas);
    }

    const onResize = () => sizeCanvas();
    window.addEventListener("resize", onResize);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      mo.disconnect();
      io?.disconnect();
      window.removeEventListener("resize", onResize);
    };
  }, []);

  return (
    <span
      role="status"
      aria-live="polite"
      className={`inline-flex shrink-0 items-center gap-2 rounded-full border border-border bg-surface py-1 pl-1 pr-3 ${className}`}
    >
      <span className="relative inline-flex h-9 w-9 shrink-0 items-center justify-center">
        <canvas ref={canvasRef} aria-hidden="true" className="block" />
        <span
          ref={ringRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-[3px] rounded-full"
          style={{ borderWidth: 1, borderStyle: "solid", opacity: RING_MIN }}
        />
      </span>
      <span className="text-sm text-foreground">{label}</span>
    </span>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GlutenWindowpane — the baker's windowpane test as a background-task
// progress indicator: a dough membrane is stretched, held, and released on a
// repeating 4-cycle knead loop, going from opaque/jittery-stranded (cycle 1)
// to translucent/straight-stranded (cycle 4) as kneading "develops" the
// gluten. Strand geometry (count, angular jitter off the horizontal stretch
// axis) and membrane translucency are fixed per cycle — what animates within
// a cycle is the stretch itself: scaleX 1 -> 1.6 over 1800ms, a 600ms hold
// at full stretch, an 800ms snap-back, 3200ms per cycle. After cycle 4 the
// membrane rests fully developed for 1500ms before a fresh dough test
// begins (full loop 14.3s). Translucency is genuine canvas alpha: the
// membrane's own dough-tinted fill is painted at (1 - translucency) opacity
// over a transparent canvas, so the real page --background underneath shows
// through more as kneading progresses — no painted background layer. The
// radial "light passes through most" highlight is the same fill pushed
// toward whichever of --background/--foreground is the lighter of the two
// (computed by luminance, never hardcoded), so it reads as a bright glow in
// dark theme and, in light theme, as the surrounding membrane leaning
// slightly toward the darker token so the near-white highlight still has
// something to contrast against.
// ---------------------------------------------------------------------------

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const probe = parseColor.ctx ?? (parseColor.ctx = document.createElement("canvas").getContext("2d"));
  if (!probe) return null;
  probe.fillStyle = "#000";
  try {
    probe.fillStyle = raw;
  } catch {
    return null;
  }
  const m = probe.fillStyle.match(/\d+/g);
  if (!m || m.length < 3) return null;
  return [Number(m[0]), Number(m[1]), Number(m[2])];
}
parseColor.ctx = null as CanvasRenderingContext2D | null;

function luminance([r, g, b]: RGB): number {
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function mix(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function rgbaStr(c: RGB, a: number): string {
  return `rgba(${c[0].toFixed(0)},${c[1].toFixed(0)},${c[2].toFixed(0)},${a.toFixed(3)})`;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const easeInOut = (t: number) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

interface CycleParams {
  count: number;
  jitterDeg: number;
  alpha: number;
}

// real numbers: strand count 8 -> 14 -> 22 -> 34, jitter +-35deg -> +-4deg,
// membrane alpha (translucency, 0 = opaque) 0.05 -> 0.62
const CYCLES: CycleParams[] = [
  { count: 8, jitterDeg: 35, alpha: 0.05 },
  { count: 14, jitterDeg: 22, alpha: 0.18 },
  { count: 22, jitterDeg: 11, alpha: 0.35 },
  { count: 34, jitterDeg: 4, alpha: 0.62 },
];

const STRETCH_MS = 1800;
const HOLD_MS = 600;
const SNAP_MS = 800;
const CYCLE_MS = STRETCH_MS + HOLD_MS + SNAP_MS; // 3200
const POST_REST_MS = 1500;
const LOOP_MS = CYCLE_MS * CYCLES.length + POST_REST_MS; // 14300
const MAX_STRANDS = CYCLES[CYCLES.length - 1]!.count;
const MEMBRANE_TINT = 0.22; // how far the dough fill leans off the lighter token toward the darker one (by luminance, not a fixed --background/--foreground direction)

// Midpoint-subdivision activation order over the 34 strand slots: any
// prefix of this order is itself evenly spread across the full slot range,
// so raising strand count only ever ADDS a strand between two that already
// exist — a slot, once occupied, never moves or vacates. This is what lets
// a strand keep its own jitter/position identity as count climbs within a
// stretch (5 -> 34 across the whole loop) instead of every strand
// reshuffling on each integer step.
function buildSlotOrder(n: number): number[] {
  const order = [0, n - 1];
  const queue: [number, number][] = [[0, n - 1]];
  while (queue.length) {
    const [lo, hi] = queue.shift()!;
    if (hi - lo < 2) continue;
    const mid = (lo + hi) >> 1;
    order.push(mid);
    queue.push([lo, mid], [mid, hi]);
  }
  return order;
}
const SLOT_ORDER = buildSlotOrder(MAX_STRANDS);

interface FrameState {
  count: number;
  jitterDeg: number;
  alpha: number;
  scaleX: number;
  thin: number; // 0..1, how "thinned" (stretched) the membrane is right now
}

// a synthetic "cycle -1" baseline the first cycle's stretch departs from, so
// cycle 1 also shows a within-cycle develop, not just a pop to its target
const BASELINE: CycleParams = { count: 5, jitterDeg: 45, alpha: 0.02 };

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

function frameState(tMs: number): FrameState {
  const loopT = ((tMs % LOOP_MS) + LOOP_MS) % LOOP_MS;
  if (loopT >= CYCLE_MS * CYCLES.length) {
    // post-cycle-4 rest: fully developed, relaxed, no active stretch
    const p = CYCLES[CYCLES.length - 1]!;
    return { count: p.count, jitterDeg: p.jitterDeg, alpha: p.alpha * 0.85, scaleX: 1, thin: 0 };
  }
  const cycleIdx = Math.min(CYCLES.length - 1, Math.floor(loopT / CYCLE_MS));
  const local = loopT - cycleIdx * CYCLE_MS;
  const from = cycleIdx === 0 ? BASELINE : CYCLES[cycleIdx - 1]!;
  const to = CYCLES[cycleIdx]!;
  let scaleX: number;
  let thin: number;
  // develop: the ONE thing a viewer follows — opaque/jittery -> translucent/
  // aligned across the 1800ms stretch, holding its arrival through hold+snap
  let develop: number;
  if (local < STRETCH_MS) {
    const f = easeInOut(local / STRETCH_MS);
    scaleX = 1 + 0.6 * f;
    thin = f;
    develop = f;
  } else if (local < STRETCH_MS + HOLD_MS) {
    scaleX = 1.6;
    thin = 1;
    develop = 1;
  } else {
    const f = easeInOut((local - STRETCH_MS - HOLD_MS) / SNAP_MS);
    scaleX = 1.6 - 0.6 * f;
    thin = 1 - f;
    develop = 1;
  }
  const count = lerp(from.count, to.count, develop);
  const jitterDeg = lerp(from.jitterDeg, to.jitterDeg, develop);
  const alpha = lerp(from.alpha, to.alpha, develop) * (0.85 + 0.15 * thin);
  return { count, jitterDeg, alpha, scaleX, thin };
}

// reduced-motion freeze: cycle 4's own 600ms hold, mid-point — max
// translucency, tightest strand alignment, full stretch, the most
// structured frame (never t0).
const REDUCED_FREEZE_MS = CYCLE_MS * (CYCLES.length - 1) + STRETCH_MS + HOLD_MS / 2;

export interface GlutenWindowpaneProps {
  /** accessible label for the status region */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GlutenWindowpane({
  label = "Processing",
  className = "",
}: GlutenWindowpaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = mulberry32(0x9a10a9); // stable per-strand jitter/spread seed

    let disposed = false;
    let visible = true;
    let raf = 0;
    let w = 0;
    let h = 0;
    let dpr = 1;

    // -- token read: no paint happens before this runs at least once. -----
    let lightColor: RGB = [255, 255, 255];
    let darkColor: RGB = [23, 23, 23];
    let isDarkTheme = false;
    const deriveColors = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = parseColor(cs.getPropertyValue("--background").trim()) ?? lightColor;
      const fg = parseColor(cs.getPropertyValue("--foreground").trim()) ?? darkColor;
      isDarkTheme = luminance(bg) < luminance(fg);
      lightColor = isDarkTheme ? fg : bg;
      darkColor = isDarkTheme ? bg : fg;
    };

    // per-strand stable jitter angle sign/magnitude and perpendicular spread
    // slot, precomputed once so a given strand index keeps its identity as
    // count grows across cycles (34 slots, subsets used at lower counts)
    const strandJitterUnit = new Float32Array(MAX_STRANDS);
    for (let i = 0; i < MAX_STRANDS; i++) strandJitterUnit[i] = (rand() - 0.5) * 2;

    // pointer-driven stretch-center bias (springed, decays to container
    // center when idle) — luminance-only highlight, never accent-tinted
    let centerX = 0;
    let centerY = 0;
    let targetX = 0;
    let targetY = 0;

    const build = () => {
      const rect = container.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) return;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      centerX = w / 2;
      centerY = h / 2;
      targetX = centerX;
      targetY = centerY;
    };

    const draw = (state: FrameState) => {
      if (w < 2 || h < 2) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const minDim = Math.min(w, h);
      const baseLen = minDim * 0.8;
      const patchHalfW = (baseLen / 2) * state.scaleX;
      const patchHalfH = minDim * 0.34;

      // clip to the membrane patch ellipse — translucency and highlight only
      // ever apply within the dough itself, never the surrounding card
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(centerX, centerY, patchHalfW * 1.05, patchHalfH * 1.05, 0, 0, Math.PI * 2);
      ctx.clip();

      // dough base fill: a fixed tint off the lighter token toward the
      // darker one, painted at (1 - translucency) so more of the real page
      // --background shows through the transparent canvas as alpha climbs
      const doughColor = mix(lightColor, darkColor, MEMBRANE_TINT);
      ctx.fillStyle = rgbaStr(doughColor, Math.max(0, 1 - state.alpha));
      ctx.fillRect(centerX - patchHalfW * 1.1, centerY - patchHalfH * 1.1, patchHalfW * 2.2, patchHalfH * 2.2);

      // radial light-through highlight: pushes further toward the LIGHTER
      // token at the hotspot, fading back to the dough tint — brightness
      // only, never var(--ns-accent)
      const hotR = Math.max(patchHalfW, patchHalfH) * (0.35 + 0.25 * state.thin);
      const grad = ctx.createRadialGradient(targetX, targetY, 0, targetX, targetY, hotR);
      const hotColor = mix(doughColor, lightColor, 0.9);
      grad.addColorStop(0, rgbaStr(hotColor, 0.16 + 0.5 * state.alpha));
      grad.addColorStop(1, rgbaStr(hotColor, 0));
      ctx.fillStyle = grad;
      ctx.fillRect(centerX - patchHalfW * 1.1, centerY - patchHalfH * 1.1, patchHalfW * 2.2, patchHalfH * 2.2);

      // strands: thin --foreground lines, angle jitter around the
      // horizontal stretch axis, evenly spread across the patch height.
      // Strands activate in SLOT_ORDER (fixed, midpoint-subdivided) rather
      // than by live index into `count`, so a slot once drawn keeps its own
      // jitter/position for the rest of the loop — raising count only adds
      // strands between the ones already there, never reshuffles them. The
      // newest (fractional) strand fades in by alpha instead of popping.
      const drawCount = Math.min(MAX_STRANDS, Math.ceil(state.count));
      const jitterRad = (state.jitterDeg * Math.PI) / 180;
      // floor kept well above the "invisible at dpr-scaled subpixel" line
      const lineWidth = Math.max(0.85, 1.9 - drawCount * 0.03);
      // strands read as --foreground: the darker-reading token carries ink
      const strandColor = isDarkTheme ? lightColor : darkColor;
      ctx.lineWidth = lineWidth;
      ctx.lineCap = "round";
      for (let i = 0; i < drawCount; i++) {
        const slotIdx = SLOT_ORDER[i] ?? Math.floor(MAX_STRANDS / 2);
        const slot = slotIdx / (MAX_STRANDS - 1) - 0.5;
        const unit = strandJitterUnit[slotIdx] ?? 0;
        const angle = unit * jitterRad;
        const len = baseLen * state.scaleX * (0.92 + 0.08 * Math.abs(unit));
        const dx = Math.cos(angle);
        const dy = Math.sin(angle);
        const px = -dy; // perpendicular for spread offset
        const py = dx;
        const spread = slot * patchHalfH * 1.7;
        const ox = centerX + px * spread;
        const oy = centerY + py * spread;
        const fade = Math.max(0, Math.min(1, state.count - i));
        ctx.strokeStyle = rgbaStr(strandColor, 0.82 * fade);
        ctx.beginPath();
        ctx.moveTo(ox - (dx * len) / 2, oy - (dy * len) / 2);
        ctx.lineTo(ox + (dx * len) / 2, oy + (dy * len) / 2);
        ctx.stroke();
      }

      ctx.restore();
    };

    let last = 0;
    const startPerf = performance.now();
    // phase-desync the mount so any two page loads show different states
    const mountOffsetMs = Date.now() % LOOP_MS;

    const loop = (now: number) => {
      if (disposed || !visible) {
        raf = 0;
        return;
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      const springRate = 1 - Math.exp(-dt * 10);
      centerX += (targetX - centerX) * springRate;
      centerY += (targetY - centerY) * springRate;

      const elapsedMs = now - startPerf + mountOffsetMs;
      draw(frameState(elapsedMs));
      raf = requestAnimationFrame(loop);
    };

    const startLoop = () => {
      if (!raf && !reduced) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const drawReduced = () => {
      draw(frameState(REDUCED_FREEZE_MS));
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const px = e.clientX - rect.left;
      const py = e.clientY - rect.top;
      // shift toward the cursor, clamped to a modest fraction of the patch
      // so the stretch center never leaves the dough itself
      const maxShift = Math.min(w, h) * 0.18;
      targetX = w / 2 + Math.max(-maxShift, Math.min(maxShift, px - w / 2)) * 0.6;
      targetY = h / 2 + Math.max(-maxShift, Math.min(maxShift, py - h / 2)) * 0.6;
    };
    const onPointerLeave = () => {
      targetX = w / 2;
      targetY = h / 2;
    };

    deriveColors();
    build();
    if (reduced) {
      drawReduced();
    } else {
      startLoop();
    }

    const ro = new ResizeObserver(() => {
      build();
      if (reduced) drawReduced();
    });
    ro.observe(container);

    const mo = new MutationObserver(() => {
      deriveColors();
      if (reduced) drawReduced();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced) startLoop();
    });
    io.observe(container);

    if (!reduced) {
      container.addEventListener("pointermove", onPointerMove);
      container.addEventListener("pointerleave", onPointerLeave);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      role="status"
      className={`relative aspect-[4/3] w-full max-w-[320px] touch-none overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      <span className="sr-only">{label}</span>
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 h-full w-full" />
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// GravureCellWipe — a divider / texture strip driven by rotogravure cylinder
// engraving and doctor-blade ink metering, the standard packaging/publication
// print process. An engraved cylinder carries a matrix of ink-retaining cells
// whose DEPTH sets tonal value (deeper cell, more ink, darker print). Every
// rotation the cylinder floods with ink, then a steel doctor blade wipes the
// land area clean, leaving ink only inside the cells.
//
// Cell depth comes from a single low-frequency value-noise field, generated
// ONCE per grid size from a FIXED seed — the engraving never changes shape
// even when a theme flip forces a re-derive of colour tokens, only the wipe
// cycle moves.
//
// The doctor blade is a vertical band (BLADE_WIDTH_CELLS wide) sweeping
// left-to-right and wrapping at the grid edge — the cylinder is
// circumferential, column W-1 is adjacent to column 0 — completing one full
// rotation every ROTATION_S seconds. Because the ink pan floods a different
// angular position on the cylinder than the blade wipes, at any instant the
// grid is genuinely split into three regions measured by `behind`, the
// wrap-safe cell-count since the blade's leading edge reached a column:
//   - `behind < BLADE_WIDTH_CELLS`      — currently under the blade: RAW
//     ink (undamped, theme-aware multiplier) plus a small per-cell flicker
//     standing in for ink still wet from the flood pass.
//   - `BLADE_WIDTH_CELLS <= behind <= FLOOD_OFFSET_FRAC * cols` — already
//     wiped this rotation: settled steady state (depth * cap, cap = 0.85
//     dark / 0.7 light) plus a decaying +0.12 luminance boost (tau 900ms)
//     for the freshly-wiped brightening that trails every pass.
//   - beyond that — re-flooded ahead of the blade's next pass: RAW again.
// The settled/raw boundary opposite the blade translates smoothly with
// rotation (never a hard once-per-cycle reset), so at any moment roughly
// half the strip reads unwiped-dense and half reads settled — exactly the
// simultaneous "ahead vs behind" picture the resting loop and the reduced-
// motion freeze frame (blade at 50% across the grid) both depend on.
//
// Pointer proximity (within 3 cell-pitches) nudges the LOCAL displayed depth
// +0.15 — a "peek" at more ink under the cursor — decaying linearly over
// 600ms once the pointer leaves the canvas. Luminance-only: it modulates the
// same --foreground alpha everything else uses, never --ns-accent, and
// leaves nothing behind once it decays to zero.
//
// Rendering is bucketed, not per-cell: alpha is quantized into ALPHA_BUCKETS
// levels and every cell's arc is appended to that bucket's Path2D, so a
// frame costs one fill() per occupied bucket (~24 max) instead of one per
// cell.
// ---------------------------------------------------------------------------

export interface GravureCellWipeProps {
  /** strip height in px; short axis geometry (cell pitch) derives from this */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
}

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    if (hex.length < 6) return null;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return Number.isNaN(r + g + b) ? null : [r, g, b];
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

// wrap-safe positive modulo
function wrapMod(a: number, m: number): number {
  return ((a % m) + m) % m;
}

const ROTATION_S = 20; // one full wipe pass (18deg/s equivalent)
const BLADE_WIDTH_CELLS = 3;
const FLOOD_OFFSET_FRAC = 0.5; // ink pan sits opposite the blade on the cylinder
const CELL_RADIUS_FACTOR = 0.75; // of pitch — leaves visible land/gutter
const CAP_DARK = 0.85;
const CAP_LIGHT = 0.7;
const RAW_MUL_DARK = 1;
const RAW_MUL_LIGHT = 0.85; // undamped ink over half the strip is too heavy at 1.0 in light theme
const WIPE_BOOST = 0.12;
const WIPE_BOOST_TAU_S = 0.9;
const PEEK_RADIUS_CELLS = 3;
const PEEK_DEPTH_BOOST = 0.15;
const PEEK_DECAY_MS = 600;
const NOISE_RES_DIVISOR = 6; // coarse noise-lattice cell spans this many grid cells
const NOISE_SEED = 0x6b7a11e; // fixed — the engraving must not reshuffle on theme flips
const FLICKER_AMP = 0.05; // raw-region "unsettled wet ink" wobble
const ALPHA_BUCKETS = 24;

// reduced-motion freeze: blade at 50% across the grid — the one frame that
// shows both the unwiped field ahead and the wiped/settled field behind at
// once
const FREEZE_PHASE = 0.5;

export function GravureCellWipe({ height = 192, className = "", style }: GravureCellWipeProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let disposed = false;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    // -- token-derived ink: no paint before the first successful read --
    let fg: RGB | null = null;
    let dark = true;
    const derive = () => {
      dark = document.documentElement.classList.contains("dark");
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    derive();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let pitch = 8;
    let cols = 0;
    let rows = 0;
    let depth = new Float32Array(0); // static engraving, rebuilt only on resize
    let raf = 0;
    let visible = true;

    // pointer "peek" state — canvas-local coords, frozen at the moment the
    // pointer leaves so the decay has something to fade from
    let pointerActive = false;
    let pointerX = 0;
    let pointerY = 0;
    let leaveAt = 0;
    let peekTailRaf = 0;

    // -- low-frequency value noise: bilinear lattice built once per grid
    // size from a FIXED seed, never regenerated per frame and never
    // reshuffled by a colour re-derive. -----------------------------------
    const buildDepth = () => {
      const rand = mulberry32(NOISE_SEED);
      const latCols = Math.max(2, Math.ceil(cols / NOISE_RES_DIVISOR) + 1);
      const latRows = Math.max(2, Math.ceil(rows / NOISE_RES_DIVISOR) + 1);
      const lattice = new Float32Array(latCols * latRows);
      for (let i = 0; i < lattice.length; i++) lattice[i] = rand();
      depth = new Float32Array(cols * rows);
      for (let ry = 0; ry < rows; ry++) {
        const ly = ry / NOISE_RES_DIVISOR;
        const y0 = Math.min(latRows - 2, Math.floor(ly));
        const fy = ly - y0;
        for (let rx = 0; rx < cols; rx++) {
          const lx = rx / NOISE_RES_DIVISOR;
          const x0 = Math.min(latCols - 2, Math.floor(lx));
          const fx = lx - x0;
          const v00 = lattice[y0 * latCols + x0] ?? 0;
          const v10 = lattice[y0 * latCols + x0 + 1] ?? 0;
          const v01 = lattice[(y0 + 1) * latCols + x0] ?? 0;
          const v11 = lattice[(y0 + 1) * latCols + x0 + 1] ?? 0;
          const top = v00 + (v10 - v00) * fx;
          const bot = v01 + (v11 - v01) * fx;
          depth[ry * cols + rx] = top + (bot - top) * fy;
        }
      }
    };

    const draw = (now: number) => {
      if (!fg || w <= 0 || h <= 0 || cols <= 0 || rows <= 0) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const t = reduced ? FREEZE_PHASE * ROTATION_S : now / 1000;
      const cap = dark ? CAP_DARK : CAP_LIGHT;
      const rawMul = dark ? RAW_MUL_DARK : RAW_MUL_LIGHT;
      const dwell = (BLADE_WIDTH_CELLS / cols) * ROTATION_S;
      const bandLead = wrapMod((t / ROTATION_S) * cols, cols);
      const floodBoundaryCells = FLOOD_OFFSET_FRAC * cols;

      // peek: distance-based falloff live while the pointer is present,
      // frozen position + linear decay for 600ms after it leaves
      let peekActive = pointerActive;
      let peekFrac = 1;
      if (!pointerActive && leaveAt > 0) {
        const sinceLeave = now - leaveAt;
        if (sinceLeave >= 0 && sinceLeave < PEEK_DECAY_MS) {
          peekActive = true;
          peekFrac = Math.min(1, Math.max(0, 1 - sinceLeave / PEEK_DECAY_MS));
        }
      }
      const peekRadiusPx = PEEK_RADIUS_CELLS * pitch;

      const r = pitch * CELL_RADIUS_FACTOR * 0.5;
      const buckets: (Path2D | null)[] = new Array(ALPHA_BUCKETS + 1).fill(null);

      for (let ry = 0; ry < rows; ry++) {
        const cy = ry * pitch + pitch / 2;
        for (let rx = 0; rx < cols; rx++) {
          const cx = rx * pitch + pitch / 2;
          let d = depth[ry * cols + rx] ?? 0;

          if (peekActive) {
            const dx = cx - pointerX;
            const dy = cy - pointerY;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < peekRadiusPx) {
              const falloff = 1 - smoothstep(0, peekRadiusPx, dist);
              d = Math.min(1, d + PEEK_DEPTH_BOOST * falloff * peekFrac);
            }
          }

          // wrap-safe cell count since the blade's leading edge passed here
          const behind = wrapMod(bandLead - rx, cols);
          let alpha: number;
          if (behind < BLADE_WIDTH_CELLS) {
            // under the blade right now — raw, unsettled
            const flicker = Math.sin(rx * 12.9898 + ry * 78.233 + t * 9) * 0.5 * FLICKER_AMP;
            alpha = Math.min(1, Math.max(0, d * rawMul + flicker));
          } else if (behind <= floodBoundaryCells) {
            // wiped this rotation — settled, with a decaying just-wiped flash
            const sinceWipeS = ((behind - BLADE_WIDTH_CELLS) / cols) * ROTATION_S;
            const boost = WIPE_BOOST * Math.exp(-sinceWipeS / WIPE_BOOST_TAU_S);
            alpha = Math.min(1, d * cap + boost);
          } else {
            // re-flooded ahead of the blade's next pass — raw again
            const flicker = Math.sin(rx * 12.9898 + ry * 78.233 + t * 9) * 0.5 * FLICKER_AMP;
            alpha = Math.min(1, Math.max(0, d * rawMul + flicker));
          }
          if (alpha <= 0.008) continue;

          const bi = Math.min(ALPHA_BUCKETS, Math.max(1, Math.round(alpha * ALPHA_BUCKETS)));
          let path = buckets[bi];
          if (!path) {
            path = new Path2D();
            buckets[bi] = path;
          }
          path.moveTo(cx + r, cy);
          path.arc(cx, cy, r, 0, Math.PI * 2);
        }
      }

      ctx.fillStyle = `rgb(${fg[0]},${fg[1]},${fg[2]})`;
      for (let bi = 1; bi <= ALPHA_BUCKETS; bi++) {
        const path = buckets[bi];
        if (!path) continue;
        ctx.globalAlpha = bi / ALPHA_BUCKETS;
        ctx.fill(path);
      }
      ctx.globalAlpha = 1;
    };

    const loop = (now: number) => {
      draw(now);
      if (!reduced && visible) raf = requestAnimationFrame(loop);
      else raf = 0;
    };
    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      pitch = Math.min(14, Math.max(6, Math.min(w, h) / 48));
      cols = Math.max(1, Math.floor(w / pitch));
      rows = Math.max(1, Math.floor(h / pitch));
      buildDepth();
      draw(performance.now());
    };

    resize();
    if (!reduced) wake();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    // theme flips re-derive colour + the light/dark cap only — the
    // engraving itself is fixed per grid size and must not reshuffle
    const mo = new MutationObserver(() => {
      derive();
      draw(performance.now());
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        draw(performance.now());
      } else {
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      pointerX = e.clientX - rect.left;
      pointerY = e.clientY - rect.top;
      pointerActive = true;
      leaveAt = 0;
      if (peekTailRaf) {
        cancelAnimationFrame(peekTailRaf);
        peekTailRaf = 0;
      }
      if (reduced) draw(performance.now());
    };
    const onPointerLeave = () => {
      pointerActive = false;
      leaveAt = performance.now();
      if (reduced) {
        // let the decay play out once even under reduced motion, then
        // settle back to the frozen frame with the peek fully gone
        const start = leaveAt;
        const tick = () => {
          const now = performance.now();
          draw(now);
          if (now - start < PEEK_DECAY_MS) {
            peekTailRaf = requestAnimationFrame(tick);
          } else {
            leaveAt = 0;
            peekTailRaf = 0;
            draw(performance.now());
          }
        };
        peekTailRaf = requestAnimationFrame(tick);
      }
    };
    canvas.addEventListener("pointermove", onPointerMove);
    canvas.addEventListener("pointerleave", onPointerLeave);

    document.fonts.ready.then(() => {
      if (!disposed) resize();
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (peekTailRaf) cancelAnimationFrame(peekTailRaf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="separator"
      aria-orientation="horizontal"
      className={`ns-gcw relative w-full overflow-hidden bg-background ${className}`}
      style={{ height, ...style }}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
    </div>
  );
}

GravureCellWipe.displayName = "GravureCellWipe";

export default GravureCellWipe;

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  type HTMLAttributes,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// GrazingLight — a feature card whose icon and heading are blind-embossed
// into the surface: no fill color change, just a pair of 1px light/dark
// text-shadows offset by cos/sin of ONE angle, --rake-angle. At rest that
// angle eases through a slow 24s circuit (ease-in-out per 90deg quadrant, so
// it lingers at each compass point) — the relief brightens and vanishes as
// the simulated light rakes across, with zero layout motion. On pointermove
// anywhere over the grid, every card computes its OWN bearing to the cursor
// (atan2 of cursor-minus-center) and springs its angle there — the whole
// grid reads as one lit surface tracking a single light source, not N
// independent hover effects.
//
// Mechanism, driven by one number: each frame writes --rake-angle (deg) on
// the card root, then derives cos/sin of that angle once and applies it to
// (a) the heading's dual text-shadow bevel, (b) two feDropShadow primitives
// stacked in the icon's SVG filter — literal duplicates of the same offset,
// not a CSS approximation — and (c) a one-sided inset box-shadow standing in
// for the card border catching the same light. All three are recomputed
// from that one angle every tick; nothing else on the card moves.
//
// GrazingLightGrid is an optional wrapping provider: it runs the ONE rAF
// loop and the ONE pointermove listener for however many cards it contains
// (matching MagneticDock's single-loop idiom elsewhere in this repo) and
// broadcasts {idle angle, pointer position} to every subscribed card each
// frame — the shared clock is what keeps the idle circuit phase-coherent
// across cards that may have mounted at different times. A card rendered
// without a GrazingLightGrid ancestor falls back to running the identical
// math on its own loop, scoped to its own bounding box, so it still works
// standalone.
//
// A11y: the card is a single <a>, its accessible name comes from the real
// heading + body text (never hidden behind the emboss) — remove the shadows
// entirely and the text is still fully legible; the emboss only adds
// texture; it never IS the text. Hover/focus affordance is a plain
// border-color shift (interaction-only --ns-accent), never the rake itself,
// so "which card is interactive" is never answered by the moving light.
// prefers-reduced-motion pins the rake at 315deg and skips every listener.
// ---------------------------------------------------------------------------

interface TickPayload {
  idleAngleDeg: number;
  pointer: { x: number; y: number } | null;
}

type TickFn = (payload: TickPayload) => void;

interface GridApi {
  subscribe(fn: TickFn): () => void;
}

const GridContext = createContext<GridApi | null>(null);

const IDLE_PERIOD_MS = 12000;
const QUADRANT_MS = IDLE_PERIOD_MS / 4;
const REDUCED_ANGLE_DEG = 315;
const SPRING = 0.12;
const DEG_TO_RAD = Math.PI / 180;
// Unit-vector offsets (cos/sin of --rake-angle) were capped at ~1px, which
// measured as byte-identical screenshots 2.5s apart in light mode — --border
// and --ns-muted sit too close to --background there for a sub-pixel shadow
// to round to a different pixel. Scaling by these magnitudes keeps the same
// cos/sin direction but pushes the emboss past the perceptual floor in both
// themes without changing the mechanism.
const BEVEL_PX = 1.8; // text-shadow + feDropShadow dx/dy
const RIM_PX = 2.6; // inset box-shadow standing in for the border catching light

function easeInOutCubic(f: number): number {
  return f < 0.5 ? 4 * f * f * f : 1 - Math.pow(-2 * f + 2, 3) / 2;
}

/** Angle (deg) of the 24s idle circuit at a given elapsed ms: 4 quadrants of
 * 90deg each, eased in-out per quadrant so the light lingers near every
 * compass point instead of sweeping at constant speed. */
function idleAngleAt(elapsedMs: number): number {
  const t = ((elapsedMs % IDLE_PERIOD_MS) + IDLE_PERIOD_MS) % IDLE_PERIOD_MS;
  const quadrant = Math.floor(t / QUADRANT_MS);
  const f = (t - quadrant * QUADRANT_MS) / QUADRANT_MS;
  return quadrant * 90 + easeInOutCubic(f) * 90;
}

/** Shortest signed delta (deg, -180..180) from `from` to `to`, so a spring
 * never takes the long way around the circle. */
function shortestDelta(from: number, to: number): number {
  let d = (to - from) % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

// ---------------------------------------------------------------------------
// Card — declared before the grid provider below purely so this file's
// PROP-SHAPE SCANNER (scripts/build-llms.ts), which greps for the first
// `export interface *Props` in the file, resolves to the primary
// component's props (GrazingLightCardProps) rather than the wrapper's.
// No runtime meaning to the position — same convention as
// registry/core/tooltip-delay-group/component.tsx.
// ---------------------------------------------------------------------------

export interface GrazingLightCardProps {
  /** Card heading — embossed, still full-contrast plain text underneath. */
  heading: string;
  /** Supporting copy. Never embossed, always flat and fully legible. */
  body: string;
  /** The card is a single link; this is its destination. */
  href: string;
  /** Icon content: one or more <path>/<g> nodes drawn in a 0 0 24 24
   * viewBox, fill="currentColor". Defaults to a built-in sparkle glyph. */
  icon?: ReactNode;
  className?: string;
}

const DEFAULT_ICON_PATH =
  "M12 3c.6 3.4 1.7 5.6 3 7 1.4 1.3 3.6 2.4 7 3-3.4.6-5.6 1.7-7 3-1.3 1.4-2.4 3.6-3 7-.6-3.4-1.7-5.6-3-7-1.4-1.3-3.6-2.4-7-3 3.4-.6 5.6-1.7 7-3 1.3-1.4 2.4-3.6 3-7z";

export function GrazingLightCard({ heading, body, href, icon, className = "" }: GrazingLightCardProps) {
  const reactId = useId().replace(/:/g, "");
  const filterId = `ns-gl-filter-${reactId}`;
  const rootRef = useRef<HTMLAnchorElement>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const lightShadowRef = useRef<SVGFEDropShadowElement>(null);
  const darkShadowRef = useRef<SVGFEDropShadowElement>(null);
  const angleRef = useRef(REDUCED_ANGLE_DEG);
  const grid = useContext(GridContext);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const paint = (deg: number) => {
      const rad = deg * DEG_TO_RAD;
      const cosA = Math.cos(rad);
      const sinA = Math.sin(rad);
      root.style.setProperty("--rake-angle", `${deg.toFixed(1)}deg`);
      if (headingRef.current) {
        headingRef.current.style.textShadow =
          `${(-cosA * BEVEL_PX).toFixed(2)}px ${(-sinA * BEVEL_PX).toFixed(2)}px 0 var(--border), ` +
          `${(cosA * BEVEL_PX).toFixed(2)}px ${(sinA * BEVEL_PX).toFixed(2)}px 0 var(--ns-muted)`;
      }
      lightShadowRef.current?.setAttribute("dx", (-cosA * BEVEL_PX).toFixed(2));
      lightShadowRef.current?.setAttribute("dy", (-sinA * BEVEL_PX).toFixed(2));
      darkShadowRef.current?.setAttribute("dx", (cosA * BEVEL_PX).toFixed(2));
      darkShadowRef.current?.setAttribute("dy", (sinA * BEVEL_PX).toFixed(2));
      root.style.boxShadow = `inset ${(-cosA * RIM_PX).toFixed(2)}px ${(-sinA * RIM_PX).toFixed(2)}px 0 0 color-mix(in srgb, var(--foreground) 14%, transparent)`;
    };

    if (prefersReducedMotion()) {
      angleRef.current = REDUCED_ANGLE_DEG;
      paint(REDUCED_ANGLE_DEG);
      return;
    }

    // Start the spring at the idle circuit's own t=0 angle rather than the
    // reduced-motion resting angle: the two are unrelated, so springing
    // 315deg -> ~0deg on mount read as a glitchy snap, the only motion in
    // the whole first second.
    angleRef.current = idleAngleAt(0);
    paint(angleRef.current);

    const tick = ({ idleAngleDeg, pointer }: TickPayload) => {
      const rect = root.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const target = pointer
        ? (((Math.atan2(pointer.y - cy, pointer.x - cx) * 180) / Math.PI) + 360) % 360
        : idleAngleDeg;
      const delta = shortestDelta(angleRef.current, target);
      angleRef.current = (angleRef.current + delta * SPRING + 360) % 360;
      paint(angleRef.current);
    };

    if (grid) {
      return grid.subscribe(tick);
    }

    // Standalone fallback: no GrazingLightGrid ancestor, so this card runs
    // the identical idle-circuit + bearing-spring math on its own loop,
    // tracking pointer movement over its own box only.
    const origin = performance.now();
    let pointer: { x: number; y: number } | null = null;
    let raf = 0;
    const onMove = (e: PointerEvent) => {
      pointer = { x: e.clientX, y: e.clientY };
    };
    const onLeave = () => {
      pointer = null;
    };
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerleave", onLeave);
    const loop = () => {
      tick({ idleAngleDeg: idleAngleAt(performance.now() - origin), pointer });
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(raf);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
    };
  }, [grid]);

  return (
    <a
      ref={rootRef}
      href={href}
      className={`ns-gl-card relative flex flex-col gap-3 rounded-lg border border-border bg-background p-6 no-underline transition-colors duration-200 hover:border-ns-accent/40 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent ${className}`}
      style={{ ["--rake-angle" as string]: `${REDUCED_ANGLE_DEG}deg` }}
    >
      <svg width="28" height="28" viewBox="0 0 24 24" aria-hidden="true" className="text-foreground">
        <defs>
          <filter id={filterId} x="-60%" y="-60%" width="220%" height="220%">
            <feDropShadow
              ref={lightShadowRef}
              dx="0"
              dy="0"
              stdDeviation="0"
              floodColor="var(--border)"
              floodOpacity="0.9"
            />
            <feDropShadow
              ref={darkShadowRef}
              dx="0"
              dy="0"
              stdDeviation="0"
              floodColor="var(--ns-muted)"
              floodOpacity="0.9"
            />
          </filter>
        </defs>
        <g style={{ filter: `url(#${filterId})` }} fill="currentColor">
          {icon ?? <path d={DEFAULT_ICON_PATH} />}
        </g>
      </svg>
      <h3 ref={headingRef} className="text-base font-semibold tracking-tight text-foreground">
        {heading}
      </h3>
      <p className="text-sm leading-relaxed text-ns-muted">{body}</p>
    </a>
  );
}

export default GrazingLightCard;

// ---------------------------------------------------------------------------
// Grid provider — one rAF loop, one pointermove listener, N subscribers.
// ---------------------------------------------------------------------------

export interface GrazingLightGridProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onPointerMove" | "onPointerLeave"> {
  children: ReactNode;
}

export function GrazingLightGrid({ children, className = "", ...rest }: GrazingLightGridProps) {
  const subsRef = useRef<Set<TickFn>>(new Set());
  const pointerRef = useRef<{ x: number; y: number } | null>(null);
  const apiRef = useRef<GridApi>({
    subscribe(fn: TickFn) {
      subsRef.current.add(fn);
      return () => {
        subsRef.current.delete(fn);
      };
    },
  });

  useEffect(() => {
    if (prefersReducedMotion()) return; // subscribers detect this themselves and skip ticks entirely
    const origin = performance.now();
    let raf = 0;
    const loop = () => {
      const idleAngleDeg = idleAngleAt(performance.now() - origin);
      const payload: TickPayload = { idleAngleDeg, pointer: pointerRef.current };
      subsRef.current.forEach((fn) => fn(payload));
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    pointerRef.current = { x: e.clientX, y: e.clientY };
  };
  const onPointerLeave = () => {
    pointerRef.current = null;
  };

  return (
    <GridContext.Provider value={apiRef.current}>
      <div {...rest} onPointerMove={onPointerMove} onPointerLeave={onPointerLeave} className={className}>
        {children}
      </div>
    </GridContext.Provider>
  );
}

"use client";

import { useState, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// GridBentoAscii — a 2x2 bento layout primitive where the seams between
// cells are real box-drawing structure, not a picture of one: the grid is
// built on its own track grid (content / seam / content, on both axes), so
// there is exactly one vertical rule, one horizontal rule and one ┼
// junction glyph, all as real elements at real grid positions. Activating a
// cell doesn't recolor anything — it re-spans that cell across every track,
// content and seam alike, so the seam literally has nowhere left to be
// drawn and disappears as a structural consequence, not an animation
// playing on its own clock. Collapsing brings the topology, and the seam,
// back. This mechanic does not exist on a single box: it needs the seam's
// topology to have something to gain or lose.
// ---------------------------------------------------------------------------

export interface BentoCell {
  id: string;
  title: string;
  description?: string;
  content?: ReactNode;
}

export interface GridBentoAsciiProps {
  /** the grid's four tiles */
  cells: [BentoCell, BentoCell, BentoCell, BentoCell];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GridBentoAscii({ cells, className = "" }: GridBentoAsciiProps) {
  const [heroId, setHeroId] = useState<string | null>(null);

  const positions: Record<number, { col: string; row: string }> = {
    0: { col: "1 / 2", row: "1 / 2" },
    1: { col: "3 / 4", row: "1 / 2" },
    2: { col: "1 / 2", row: "3 / 4" },
    3: { col: "3 / 4", row: "3 / 4" },
  };

  const heroIndex = heroId ? cells.findIndex((c) => c.id === heroId) : -1;
  const expanded = heroIndex !== -1;

  return (
    <div
      data-grid-bento-ascii
      className={`relative grid aspect-square w-full max-w-md gap-0 font-mono ${className}`}
      style={{
        gridTemplateColumns: "1fr 1.4em 1fr",
        gridTemplateRows: "1fr 1.4em 1fr",
      }}
    >
      {/* seams: real elements at real grid tracks, only rendered while every
          cell is at its own resting position */}
      {!expanded && (
        <>
          <div
            aria-hidden
            className="pointer-events-none bg-border transition-opacity duration-150 motion-reduce:transition-none"
            style={{ gridColumn: "2 / 3", gridRow: "1 / 4", width: 1, justifySelf: "center" }}
          />
          <div
            aria-hidden
            className="pointer-events-none bg-border transition-opacity duration-150 motion-reduce:transition-none"
            style={{ gridColumn: "1 / 4", gridRow: "2 / 3", height: 1, alignSelf: "center" }}
          />
          <span
            aria-hidden
            className="pointer-events-none grid select-none place-items-center text-border transition-opacity duration-150 motion-reduce:transition-none"
            style={{ gridColumn: "2 / 3", gridRow: "2 / 3" }}
          >
            +
          </span>
        </>
      )}

      {cells.map((cell, i) => {
        const isHero = heroId === cell.id;
        const hiddenByHero = expanded && !isHero;
        const style = isHero && expanded ? { col: "1 / 4", row: "1 / 4" } : positions[i]!;

        return (
          <button
            key={cell.id}
            type="button"
            data-cell={cell.id}
            aria-pressed={isHero}
            aria-label={isHero ? `Collapse ${cell.title}` : `Expand ${cell.title}`}
            aria-hidden={hiddenByHero || undefined}
            tabIndex={hiddenByHero ? -1 : 0}
            onClick={() => setHeroId(isHero ? null : cell.id)}
            className={`group relative flex flex-col items-start justify-end overflow-hidden rounded-sm border border-border bg-surface p-3 text-left transition-[opacity,border-color] duration-150 motion-reduce:transition-none hover:border-foreground/25 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
              hiddenByHero ? "pointer-events-none opacity-0" : "opacity-100"
            }`}
            style={{ gridColumn: style.col, gridRow: style.row }}
          >
            {isHero && expanded && (
              <span
                aria-hidden
                data-hero-badge
                className="absolute right-2 top-2 select-none rounded-sm border border-border bg-background px-2 py-1 text-[10px] uppercase tracking-wider text-ns-muted"
              >
                click to collapse
              </span>
            )}
            {cell.content}
            <span className="text-sm font-semibold text-foreground">{cell.title}</span>
            {cell.description && (
              <span className="mt-1 text-xs text-ns-muted group-hover:text-foreground/80">
                {cell.description}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";

export type BentoSize = "1x1" | "2x1" | "1x2";

export interface BentoCell {
  /** Stable id — also the roving-tabindex key and the FLIP measurement key. */
  id: string;
  title: string;
  meta?: string;
  body?: ReactNode;
  /** Resting footprint. Ignored while this cell is featured (always 2x2). */
  size?: BentoSize;
}

export interface BentoGridProps {
  /** the grid's tiles */
  cells: BentoCell[];
  /** number of grid columns */
  cols?: number;
  /** id of the cell that starts featured (always 2x2). Defaults to the first cell. */
  defaultFeaturedId?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const SPAN: Record<BentoSize, { c: number; r: number }> = {
  "1x1": { c: 1, r: 1 },
  "2x1": { c: 2, r: 1 },
  "1x2": { c: 1, r: 2 },
};

const ROW_PX = 108;

function spanFor(cell: BentoCell, isFeatured: boolean, cols: number) {
  if (isFeatured) return { c: Math.min(2, cols), r: 2 };
  return SPAN[cell.size ?? "1x1"];
}

// Worst-case row count across every possible featured cell — computed once
// from the cell list, not the live state — so the grid's own box height
// never jumps as different cells get promoted. Dense packing may leave a
// little trailing slack in the non-worst states; it never overflows.
function computeRows(cells: BentoCell[], cols: number): number {
  let worst = 0;
  for (const candidate of cells) {
    let units = 0;
    for (const cell of cells) {
      const { c, r } = spanFor(cell, cell.id === candidate.id, cols);
      units += c * r;
    }
    worst = Math.max(worst, units);
  }
  return Math.max(1, Math.ceil(worst / cols));
}

/**
 * A bento grid where cells reflow for real: activating one promotes it to a
 * 2x2 slot and every other cell re-packs around it via CSS `grid-auto-flow:
 * dense` — the browser's own layout engine, not a fixed grid-template-areas
 * arrangement. The reflow is FLIP-animated (translate only, size changes
 * instantly) so it reads as tiles sliding into new slots rather than
 * teleporting or smearing under a scale transform. Arrow keys move focus
 * spatially between tiles by their actual on-screen geometry, not DOM order.
 */
export function BentoGrid({ cells, cols = 4, defaultFeaturedId, className = "" }: BentoGridProps) {
  const initial = defaultFeaturedId ?? cells[0]?.id ?? "";
  const [featuredId, setFeaturedId] = useState(initial);
  const [activeId, setActiveId] = useState(initial);
  const [announce, setAnnounce] = useState("");
  const refs = useRef(new Map<string, HTMLDivElement>());
  const pendingFirst = useRef<Map<string, DOMRect> | null>(null);

  const rows = useMemo(() => computeRows(cells, cols), [cells, cols]);

  const activate = (id: string) => {
    setActiveId(id);
    if (id === featuredId) return;
    const reduce =
      typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduce) {
      const first = new Map<string, DOMRect>();
      refs.current.forEach((el, key) => first.set(key, el.getBoundingClientRect()));
      pendingFirst.current = first;
    }
    setFeaturedId(id);
    const cell = cells.find((c) => c.id === id);
    if (cell) setAnnounce(`${cell.title} featured`);
  };

  // FLIP: positions were captured synchronously before the state write above;
  // once the new layout has painted, invert each moved cell back to its old
  // position with transitions off, then release it into a transform
  // transition back to zero. Size changes (1x1 -> 2x2) happen instantly —
  // scaling a bordered, rounded card is what smears its border and text.
  useLayoutEffect(() => {
    const first = pendingFirst.current;
    pendingFirst.current = null;
    if (!first) return;
    refs.current.forEach((el, key) => {
      const from = first.get(key);
      if (!from) return;
      const to = el.getBoundingClientRect();
      const dx = from.left - to.left;
      const dy = from.top - to.top;
      if (!dx && !dy) return;
      el.style.transition = "none";
      el.style.transform = `translate(${dx}px, ${dy}px)`;
      void el.getBoundingClientRect(); // force reflow before releasing
      requestAnimationFrame(() => {
        el.style.transition = "transform 380ms cubic-bezier(0.22, 1, 0.36, 1)";
        el.style.transform = "";
      });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [featuredId]);

  // Spatial nav: candidates are filtered to the pressed half-plane by their
  // actual rendered centre, then scored by distance along the pressed axis
  // plus double the perpendicular drift — reading order plays no part.
  const move = (dir: "up" | "down" | "left" | "right") => {
    const cur = refs.current.get(activeId)?.getBoundingClientRect();
    if (!cur) return;
    const cx = cur.left + cur.width / 2;
    const cy = cur.top + cur.height / 2;
    let bestId: string | null = null;
    let bestScore = Infinity;
    refs.current.forEach((el, id) => {
      if (id === activeId) return;
      const r = el.getBoundingClientRect();
      const x = r.left + r.width / 2 - cx;
      const y = r.top + r.height / 2 - cy;
      let primary: number;
      let secondary: number;
      if (dir === "right") {
        if (x <= 1) return;
        primary = x;
        secondary = Math.abs(y);
      } else if (dir === "left") {
        if (x >= -1) return;
        primary = -x;
        secondary = Math.abs(y);
      } else if (dir === "down") {
        if (y <= 1) return;
        primary = y;
        secondary = Math.abs(x);
      } else {
        if (y >= -1) return;
        primary = -y;
        secondary = Math.abs(x);
      }
      const score = primary + secondary * 2;
      if (score < bestScore) {
        bestScore = score;
        bestId = id;
      }
    });
    if (bestId) {
      setActiveId(bestId);
      refs.current.get(bestId)?.focus();
    }
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>, id: string) => {
    switch (e.key) {
      case "ArrowRight":
        e.preventDefault();
        move("right");
        break;
      case "ArrowLeft":
        e.preventDefault();
        move("left");
        break;
      case "ArrowDown":
        e.preventDefault();
        move("down");
        break;
      case "ArrowUp":
        e.preventDefault();
        move("up");
        break;
      case "Enter":
      case " ":
        e.preventDefault();
        activate(id);
        break;
      default:
        break;
    }
  };

  return (
    <div className="w-full">
      <div
        role="group"
        aria-label="Bento grid. Arrow keys move between tiles, Enter or Space features one."
        className={`grid gap-3 ${className}`}
        style={{
          gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
          gridTemplateRows: `repeat(${rows}, ${ROW_PX}px)`,
          gridAutoFlow: "dense",
        }}
      >
        {cells.map((cell) => {
          const isFeatured = cell.id === featuredId;
          const { c, r } = spanFor(cell, isFeatured, cols);
          return (
            <div
              key={cell.id}
              ref={(el) => {
                if (el) refs.current.set(cell.id, el);
                else refs.current.delete(cell.id);
              }}
              role="button"
              tabIndex={cell.id === activeId ? 0 : -1}
              aria-pressed={isFeatured}
              aria-label={cell.title}
              data-cell-id={cell.id}
              data-featured={String(isFeatured)}
              onClick={() => activate(cell.id)}
              onKeyDown={(e) => onKeyDown(e, cell.id)}
              onFocus={() => setActiveId(cell.id)}
              className="group relative flex cursor-pointer flex-col justify-between overflow-hidden rounded-md border border-border bg-surface p-4 text-left transition-colors duration-150 hover:border-ns-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              style={{ gridColumn: `span ${c}`, gridRow: `span ${r}` }}
            >
              {isFeatured && (
                <span aria-hidden className="absolute right-3 top-3 h-1.5 w-1.5 rounded-full bg-ns-accent" />
              )}
              <div>
                {cell.meta && (
                  <p className="mb-1 font-mono text-[10px] uppercase tracking-widest text-ns-muted">{cell.meta}</p>
                )}
                <h3 className={`font-medium text-foreground ${isFeatured ? "text-base" : "text-sm"}`}>
                  {cell.title}
                </h3>
              </div>
              {cell.body && <div className="mt-2 flex-1 text-sm text-ns-muted">{cell.body}</div>}
              <span
                aria-hidden
                className="pointer-events-none mt-2 block text-right font-mono text-[10px] uppercase tracking-widest text-ns-muted opacity-0 transition-opacity duration-150 group-hover:opacity-100 group-focus-visible:opacity-100"
              >
                {isFeatured ? "featured" : "feature this"}
              </span>
            </div>
          );
        })}
      </div>
      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// WarpLattice — a functional card grid drawn on its own visible lattice.
// The lattice is the magnetized medium: hairline grid lines bend toward the
// cursor, and the DOM cards sample the exact same displacement field, riding
// the bent sheet instead of floating over it. One pure field function feeds
// both the canvas and the card transforms from a single rAF loop.
// ---------------------------------------------------------------------------

const DEFAULT_LABELS = ["01", "02", "03", "04", "05", "06"];

// Idle ambient drift — a slow lissajous orbit sampled by the same field so
// the lattice never sits dead flat when nothing is hovering it.
const IDLE_AMT = 0.16; // fraction of full field strength at rest
const IDLE_ANGULAR_SPEED = 0.00022; // rad/ms

// Reads a `#rrggbb` custom property into a "r,g,b" string for rgba() strings.
function hexToRgbString(hex: string): string | null {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m || !m[1]) return null;
  const int = parseInt(m[1], 16);
  return `${(int >> 16) & 255},${(int >> 8) & 255},${int & 255}`;
}

type FieldSample = { ox: number; oy: number; w: number };

// The shared displacement field. Pull toward the cursor with gaussian
// falloff: pull = (cursor - p) * A * exp(-r^2 / (2 sigma^2)), magnitude
// clamped to 0.35 * r so a point can never cross the pointer (dead zone).
// `w` is the normalized field influence (0..1) used for line alpha.
// Written into `out` — no allocations on the hot path.
function sampleField(
  px: number,
  py: number,
  cx: number,
  cy: number,
  amp: number,
  twoSigma2: number,
  amt: number,
  out: FieldSample
) {
  const dx = cx - px;
  const dy = cy - py;
  const r2 = dx * dx + dy * dy;
  if (amt < 0.001 || r2 < 1e-6) {
    out.ox = 0;
    out.oy = 0;
    out.w = 0;
    return;
  }
  const g = Math.exp(-r2 / twoSigma2);
  const r = Math.sqrt(r2);
  let m = amp * r * g;
  const cap = 0.35 * r; // dead zone: lines relax near the pointer, never cross it
  if (m > cap) m = cap;
  m *= amt;
  const inv = m / r;
  out.ox = dx * inv;
  out.oy = dy * inv;
  out.w = g * amt;
}

export function WarpLattice({
  labels = DEFAULT_LABELS,
  cell = 32,
  sampleStep = 8,
  sigma = 140,
  peakBend = 22,
  cursorLerp = 0.14,
  className = "min-h-[520px]",
  "aria-label": ariaLabel = "Card grid on a cursor-warped lattice",
}: {
  /** mono label per card (3x2 grid by default) */
  labels?: string[];
  /** lattice cell size in px */
  cell?: number;
  /** sampling interval along each line in px */
  sampleStep?: number;
  /** gaussian falloff radius of the field in px */
  sigma?: number;
  /** maximum line bend in px (peaks at r = sigma) */
  peakBend?: number;
  /** smoothed-cursor lerp per frame — flicks lag, the sheet relaxes behind them */
  cursorLerp?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the grid */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const grid = gridRef.current;
    if (!root || !canvas || !grid) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const items = Array.from(grid.children) as HTMLElement[];
    const n = items.length;

    // A tuned so the peak bend (at r = sigma) equals peakBend px:
    // max of r * exp(-r^2 / (2 sigma^2)) is sigma * exp(-0.5)
    const amp = (peakBend * Math.exp(0.5)) / sigma;
    const twoSigma2 = 2 * sigma * sigma;

    // hot-path state — locals only, never React state
    let raf = 0;
    let w = 0;
    let h = 0;
    let dpr = 1;
    let tx = 0; // raw pointer (root space)
    let ty = 0;
    let sx = 0; // smoothed pointer — lags flicks, sheet visibly relaxes behind
    let sy = 0;
    let amt = 0; // field strength, eases 0 <-> 1 with the same lerp
    let hovering = false;
    let litIdx = -1; // card carrying the accent border
    let visible = true; // IntersectionObserver — pause the loop offscreen
    let lineRGB = "46,46,46"; // overwritten by readLineColor() before first draw
    const centerX = new Float32Array(n);
    const centerY = new Float32Array(n);
    const scaleCur = new Float32Array(n).fill(1);
    const prevTx = new Float32Array(n);
    const prevTy = new Float32Array(n);
    const out: FieldSample = { ox: 0, oy: 0, w: 0 };

    // Line color tracks the theme's border token — read once at mount and
    // re-read whenever the root's class list flips (dark <-> light), so
    // contrast stays correct in both instead of a color coincidentally
    // tuned for dark mode.
    const readLineColor = () => {
      const raw = getComputedStyle(document.documentElement)
        .getPropertyValue("--border")
        .trim();
      lineRGB = hexToRgbString(raw) ?? lineRGB;
    };
    readLineColor();

    const measure = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      // untransformed offsets (offsetLeft/Top ignore transforms — no feedback)
      const gx = grid.offsetLeft;
      const gy = grid.offsetTop;
      items.forEach((el, i) => {
        centerX[i] = gx + el.offsetLeft + el.offsetWidth / 2;
        centerY[i] = gy + el.offsetTop + el.offsetHeight / 2;
      });
    };
    measure();

    // Lattice pass: every line sampled every `sampleStep` px, each segment
    // bucketed by field influence so strokes batch into 6 alpha levels —
    // the theme's --border color rising 0.25 -> 0.6 inside the field.
    const NB = 6;
    const draw = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.lineWidth = 1;
      const paths: Path2D[] = [];
      const counts: number[] = [];
      for (let b = 0; b < NB; b++) {
        paths.push(new Path2D());
        counts.push(0);
      }
      const seg = (
        x0: number,
        y0: number,
        x1: number,
        y1: number,
        influence: number
      ) => {
        const b = Math.min(NB - 1, Math.floor(influence * NB));
        const p = paths[b];
        if (!p) return;
        p.moveTo(x0, y0);
        p.lineTo(x1, y1);
        counts[b] = (counts[b] ?? 0) + 1;
      };

      // vertical lines
      const vSteps = Math.ceil(h / sampleStep);
      for (let x = 0; x <= w; x += cell) {
        let px = 0;
        let py = 0;
        let pw = 0;
        for (let s = 0; s <= vSteps; s++) {
          const y = Math.min(h, s * sampleStep);
          sampleField(x, y, sx, sy, amp, twoSigma2, amt, out);
          const dx = x + out.ox;
          const dy = y + out.oy;
          if (s > 0) seg(px, py, dx, dy, (pw + out.w) / 2);
          px = dx;
          py = dy;
          pw = out.w;
        }
      }
      // horizontal lines
      const hSteps = Math.ceil(w / sampleStep);
      for (let y = 0; y <= h; y += cell) {
        let px = 0;
        let py = 0;
        let pw = 0;
        for (let s = 0; s <= hSteps; s++) {
          const x = Math.min(w, s * sampleStep);
          sampleField(x, y, sx, sy, amp, twoSigma2, amt, out);
          const dx = x + out.ox;
          const dy = y + out.oy;
          if (s > 0) seg(px, py, dx, dy, (pw + out.w) / 2);
          px = dx;
          py = dy;
          pw = out.w;
        }
      }
      for (let b = 0; b < NB; b++) {
        if ((counts[b] ?? 0) === 0) continue;
        const a = 0.25 + (0.35 * b) / (NB - 1);
        const p = paths[b];
        if (!p) continue;
        ctx.strokeStyle = `rgba(${lineRGB},${a})`;
        ctx.stroke(p);
      }
    };
    draw(); // initial flat lattice

    if (reduced) {
      // static fallback: flat lattice, static cards — hover highlight is
      // handled in CSS via the motion-reduce variant on each card
      const ro = new ResizeObserver(() => {
        measure();
        draw();
      });
      ro.observe(root);
      const mo = new MutationObserver(() => {
        readLineColor();
        draw();
      });
      mo.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
      return () => {
        ro.disconnect();
        mo.disconnect();
      };
    }

    const loop = (now: number) => {
      // resting state drifts a slow lissajous orbit through the field at low
      // amplitude — ambient motion is the default look, not an extra that
      // only appears on hover
      let targetX: number;
      let targetY: number;
      let amtTarget: number;
      if (hovering) {
        targetX = tx;
        targetY = ty;
        amtTarget = 1;
      } else {
        const ang = now * IDLE_ANGULAR_SPEED;
        targetX = w / 2 + Math.cos(ang) * w * 0.22;
        targetY = h / 2 + Math.sin(ang * 1.3) * h * 0.22;
        amtTarget = IDLE_AMT;
      }
      // smoothed cursor: lerp per frame, flicks lag and the sheet relaxes
      sx += (targetX - sx) * cursorLerp;
      sy += (targetY - sy) * cursorLerp;
      amt += (amtTarget - amt) * cursorLerp;

      // nearest card = the focused one — accent border, the only accent
      let nearest = -1;
      if (hovering) {
        let best = Infinity;
        for (let i = 0; i < n; i++) {
          const dx = (centerX[i] ?? 0) - sx;
          const dy = (centerY[i] ?? 0) - sy;
          const d2 = dx * dx + dy * dy;
          if (d2 < best) {
            best = d2;
            nearest = i;
          }
        }
      }
      if (nearest !== litIdx) {
        const prev = items[litIdx];
        if (prev) prev.style.borderColor = "";
        const next = items[nearest];
        if (next) next.style.borderColor = "var(--ns-accent)";
        litIdx = nearest;
      }

      draw();

      // cards sample the same field: translate field(center) * 0.35,
      // nearest gets 0.6x plus scale 1.02 (dock-cursor-magnify pull)
      let maxDelta = 0;
      items.forEach((el, i) => {
        sampleField(
          centerX[i] ?? 0,
          centerY[i] ?? 0,
          sx,
          sy,
          amp,
          twoSigma2,
          amt,
          out
        );
        const gain = i === nearest ? 0.6 : 0.35;
        const cx = out.ox * gain;
        const cy = out.oy * gain;
        const targetS = i === nearest ? 1.02 : 1;
        const s = (scaleCur[i] ?? 1) + (targetS - (scaleCur[i] ?? 1)) * cursorLerp;
        scaleCur[i] = s;
        const dx = Math.abs(cx - (prevTx[i] ?? 0));
        const dy = Math.abs(cy - (prevTy[i] ?? 0));
        const ds = Math.abs(targetS - s) * 100;
        if (dx > maxDelta) maxDelta = dx;
        if (dy > maxDelta) maxDelta = dy;
        if (ds > maxDelta) maxDelta = ds;
        prevTx[i] = cx;
        prevTy[i] = cy;
        el.style.transform = `translate3d(${cx}px, ${cy}px, 0) scale(${s})`;
      });

      // sleep when everything has settled — pointer events wake the loop.
      // While at rest the idle target itself keeps drifting, so this only
      // fires once a steady hover position has fully caught up.
      const cursorErr = Math.abs(targetX - sx) + Math.abs(targetY - sy);
      const settled =
        cursorErr < 0.05 &&
        Math.abs(amtTarget - amt) < 0.001 &&
        maxDelta < 0.02;
      if (settled && amtTarget === 0) {
        amt = 0;
        items.forEach((el) => {
          el.style.transform = "";
        });
        draw();
      }
      raf = settled ? 0 : requestAnimationFrame(loop);
    };
    const wake = () => {
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const onMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      tx = e.clientX - rect.left;
      ty = e.clientY - rect.top;
      if (!hovering && amt < 0.01) {
        // field is asleep — snap the smoothed cursor so the sheet does not
        // swing in from a stale position
        sx = tx;
        sy = ty;
      }
      hovering = true;
      wake();
    };
    const onLeave = () => {
      // eases everything home with the same lerp — interruptible by re-entry
      hovering = false;
      wake();
    };

    const ro = new ResizeObserver(() => {
      measure();
      draw();
    });
    ro.observe(root);
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onMove);
    root.addEventListener("pointerleave", onLeave);

    // idle ambient motion only costs cycles while the lattice is on screen
    const io = new IntersectionObserver(
      ([entry]) => {
        visible = entry?.isIntersecting ?? true;
        if (visible) {
          wake();
        } else if (raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: 0 }
    );
    io.observe(root);

    // re-derive the line color from the theme token whenever dark/light
    // toggles the root's class list
    const mo = new MutationObserver(() => {
      readLineColor();
      draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    if (visible) wake(); // start the ambient orbit immediately, not on first pointer event

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onMove);
      root.removeEventListener("pointerleave", onLeave);
    };
  }, [labels, cell, sampleStep, sigma, peakBend, cursorLerp]);

  return (
    <div
      ref={rootRef}
      aria-label={ariaLabel}
      className={`relative w-full overflow-hidden bg-background ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
      <div
        ref={gridRef}
        className="relative grid h-full grid-cols-2 gap-4 p-6 sm:grid-cols-3 sm:gap-6 sm:p-10"
      >
        {labels.map((label) => (
          <div
            key={label}
            className="flex min-h-28 items-end rounded-md border border-border bg-surface p-4 transition-colors duration-300 will-change-transform motion-reduce:hover:border-ns-accent"
          >
            <span className="font-mono text-xs text-ns-muted">{label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// GrindingChatterLobes — a card-scale loader substitute built on regenerative
// chatter in cylindrical (OD) grinding (Tobias/Merritt theory as applied to
// grinding-process control): the wheel re-cuts the wavy profile its own
// previous pass left on the workpiece, and under the right speed ratio that
// wave self-amplifies into a stable N-lobed pattern before saturating against
// contact stiffness. A dress event clears the regenerative memory and a new
// lobe count begins. Canvas 2D, DPR clamp 2, direct-DOM rAF, sleeps for
// nothing (the loop is unbounded by design — this stands in for "busy").
// The rim profile is recomputed from a coefficient (N, amplitude, phase)
// every frame, never accumulated pixel history, so cost stays flat.

const TWO_PI = Math.PI * 2;
const DEG = Math.PI / 180;

const LOBE_COUNTS = [5, 6, 7, 8, 9, 10, 11];
const WORKPIECE_REV_PER_S = 0.15; // slowed from real 1-5 rev/s wheelhead speeds
const RADIUS_RATIO = 0.38; // disc radius = 0.38 * min(w, h)
const AMAX_RATIO = 0.06; // Amax = 0.06 * radius
const GROWTH_S = 40; // dress event every 40s
const DRESS_MS = 1200; // lobes fade to a smooth circle over 1.2s
const PERIOD_S = GROWTH_S + DRESS_MS / 1000;
// logistic center + rate chosen so amplitude visibly ramps ~5% -> ~95% of
// Amax over the first 6s of a growth cycle, then plateaus (self-limiting
// saturation against contact stiffness, not unbounded growth).
const LOGISTIC_CENTER_S = 3;
const LOGISTIC_RATE = Math.log(19) / 3;

const BOOST_WINDOW_RAD = 15 * DEG; // half-width of the 30deg pointer window
const BOOST_MULT = 1.5; // local amplitude growth boost while pointer is near
const BOOST_TAU_MS = 500 / 3; // ~3 tau to settle within the spec's 500ms decay

// reduced-motion freeze frame: a static mid-growth profile, not tied to the
// live logistic curve's exact constants — deliberately the most structured
// single frame, named explicitly per the round 9 rule.
const FREEZE_PHASE = "lobe-70pct";
const FREEZE_AMPLITUDE_RATIO = 0.7;
const FREEZE_LOBE_COUNT = 8;
const FREEZE_ROTATION_RAD = -20 * DEG;

const BINS = 360;

function wrapPi(a: number) {
  a = ((a + Math.PI) % TWO_PI + TWO_PI) % TWO_PI;
  return a - Math.PI;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function logisticAmplitude(t: number, amax: number) {
  const f = 1 / (1 + Math.exp(-LOGISTIC_RATE * (t - LOGISTIC_CENTER_S)));
  return f * amax;
}

function easeOutCubic(x: number) {
  const inv = 1 - x;
  return 1 - inv * inv * inv;
}

export interface GrindingChatterLobesProps {
  /** accessible status text announced to assistive tech */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GrindingChatterLobes({
  label = "Loading",
  className = "",
}: GrindingChatterLobesProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let disposed = false;
    let visible = true;
    let raf = 0;

    let w = 0;
    let h = 0;
    let dpr = 1;
    let radius = 0;

    let fgColor = "#171717";
    let bgColor = "#ffffff";
    let mutedRGBA = "rgba(140,140,140,0.55)";

    // -- token read: no paint happens before this runs at least once. -----
    const deriveColors = () => {
      const cs = getComputedStyle(document.documentElement);
      const fg = cs.getPropertyValue("--foreground").trim();
      const bg = cs.getPropertyValue("--background").trim();
      const muted = cs.getPropertyValue("--ns-muted").trim();
      if (fg) fgColor = fg;
      if (bg) bgColor = bg;
      if (muted) {
        const probe = document.createElement("canvas").getContext("2d");
        if (probe) {
          probe.fillStyle = muted;
          const [r, g, b] = probe.fillStyle.match(/\d+/g)?.map(Number) ?? [];
          // alpha 0.55 compresses the gradient's contrast so scalloping
          // stays legible in light theme without approaching border-adjacent
          // values (checked against --border #ebebeb at the light tokens).
          if (r !== undefined) mutedRGBA = `rgba(${r},${g},${b},0.55)`;
        }
      }
    };

    // -- per-cycle state, reseeded from the mount clock so a phase-desynced
    // start (not always t=0) means any two page loads show different
    // states, per spec. --------------------------------------------------
    const seedBase = Math.floor(Date.now()) >>> 0;
    const mountOffsetS = (Date.now() / 1000) % PERIOD_S;
    const startPerf = performance.now();

    let cycleIndex = -1;
    let lobeCount = LOBE_COUNTS[0]!;
    let basePhase = 0;

    const loadCycle = (idx: number) => {
      if (idx === cycleIndex) return;
      cycleIndex = idx;
      const rand = mulberry32(seedBase + idx * 0x9e3779b1);
      lobeCount = LOBE_COUNTS[Math.floor(rand() * LOBE_COUNTS.length)]!;
      basePhase = rand() * TWO_PI;
    };

    let rotationAngle = 0;

    // -- pointer boost: locally applied contact pressure. Angle is tracked
    // in screen space (the contact point stays put while the disc spins
    // under it), decays to 0 over ~500ms after the pointer leaves. Never
    // touches the global dress-event clock. --------------------------------
    let pointerActive = false;
    let pointerAngleScreen = 0;
    let boostEnvelope = 0;

    const build = () => {
      const rect = container.getBoundingClientRect();
      w = Math.round(rect.width);
      h = Math.round(rect.height);
      if (w < 2 || h < 2) return;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      radius = RADIUS_RATIO * Math.min(w, h);
    };

    const localAmpMult = (thetaLocal: number, pointerAngleLocal: number) => {
      if (boostEnvelope <= 0.001) return 1;
      const d = Math.abs(wrapPi(thetaLocal - pointerAngleLocal));
      if (d >= BOOST_WINDOW_RAD) return 1;
      const falloff = 0.5 * (1 + Math.cos((Math.PI * d) / BOOST_WINDOW_RAD));
      return 1 + (BOOST_MULT - 1) * boostEnvelope * falloff;
    };

    const drawRim = (
      amplitude: number,
      lobes: number,
      phase: number,
      rotation: number,
      pointerAngleLocal: number
    ) => {
      const cx = w / 2;
      const cy = h / 2;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(rotation);

      ctx.beginPath();
      for (let i = 0; i <= BINS; i++) {
        const theta = (i % BINS) * DEG;
        const mult = localAmpMult(theta, pointerAngleLocal);
        const r = radius + amplitude * Math.cos(lobes * theta + phase) * mult;
        const x = r * Math.cos(theta);
        const y = r * Math.sin(theta);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();

      const grad = ctx.createRadialGradient(
        0,
        0,
        0,
        0,
        0,
        radius * (1 + AMAX_RATIO)
      );
      grad.addColorStop(0, bgColor);
      grad.addColorStop(1, mutedRGBA);
      ctx.fillStyle = grad;
      ctx.fill();

      ctx.lineWidth = 1.5;
      ctx.strokeStyle = fgColor;
      ctx.stroke();
      ctx.restore();
    };

    // -- static reduced-motion frame: freeze on the named, deliberately
    // chosen most-structured frame, not t0. No loop, no listeners beyond
    // resize/theme so colours still stay correct. -------------------------
    const drawReduced = () => {
      if (w < 2 || h < 2 || radius <= 0) return;
      const amax = AMAX_RATIO * radius;
      drawRim(
        FREEZE_AMPLITUDE_RATIO * amax,
        FREEZE_LOBE_COUNT,
        0,
        FREEZE_ROTATION_RAD,
        0
      );
    };

    let last = 0;

    const loop = (now: number) => {
      if (disposed || !visible) {
        raf = 0;
        return;
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      rotationAngle = (rotationAngle + TWO_PI * WORKPIECE_REV_PER_S * dt) % TWO_PI;

      boostEnvelope +=
        ((pointerActive ? 1 : 0) - boostEnvelope) *
        (1 - Math.exp(-dt * 1000 / BOOST_TAU_MS));

      const elapsed = (now - startPerf) / 1000 + mountOffsetS;
      const idx = Math.floor(elapsed / PERIOD_S);
      const tc = elapsed - idx * PERIOD_S;
      loadCycle(idx);

      const amax = AMAX_RATIO * radius;
      let amplitude: number;
      if (tc < GROWTH_S) {
        amplitude = logisticAmplitude(tc, amax);
      } else {
        const plateau = logisticAmplitude(GROWTH_S, amax);
        const dressT = Math.min(1, (tc - GROWTH_S) / (DRESS_MS / 1000));
        amplitude = plateau * (1 - easeOutCubic(dressT));
      }

      const pointerAngleLocal = wrapPi(pointerAngleScreen - rotationAngle);
      if (w >= 2 && h >= 2 && radius > 0) {
        drawRim(amplitude, lobeCount, basePhase, rotationAngle, pointerAngleLocal);
      }

      raf = requestAnimationFrame(loop);
    };

    const startLoop = () => {
      if (!raf && !reduced) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const pointerAngleFromEvent = (e: PointerEvent) => {
      const r = container.getBoundingClientRect();
      return Math.atan2(
        e.clientY - (r.top + r.height / 2),
        e.clientX - (r.left + r.width / 2)
      );
    };
    const onPointerMove = (e: PointerEvent) => {
      pointerActive = true;
      pointerAngleScreen = pointerAngleFromEvent(e);
    };
    const onPointerLeave = () => {
      pointerActive = false;
    };

    deriveColors();
    build();
    if (reduced) {
      drawReduced();
    } else {
      startLoop();
    }

    const ro = new ResizeObserver(() => {
      build();
      if (reduced) drawReduced();
    });
    ro.observe(container);

    const mo = new MutationObserver(() => {
      deriveColors();
      if (reduced) drawReduced();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced) startLoop();
    });
    io.observe(container);

    if (!reduced) {
      container.addEventListener("pointermove", onPointerMove);
      container.addEventListener("pointerleave", onPointerLeave);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      role="status"
      className={`relative aspect-square w-full max-w-[280px] touch-none overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      <span className="sr-only">{label}</span>
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="absolute inset-0 h-full w-full"
      />
    </div>
  );
}

export { FREEZE_PHASE };

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GroovePitch — an ambient, indeterminate loader modeling a real mastering-
// lathe artifact: variable groove pitch. A cutting lathe varies the radial
// spacing between adjacent spiral turns in real time, based on program
// level, so loud/bassy passages get pulled wider (fewer grooves per inch,
// avoiding wall-to-wall breakthrough) and quiet passages get packed tight.
// The spiral here grows outward from a small lead-in at the center, its own
// turn spacing continuously widening and narrowing on a baked envelope, and
// a bright cutting-point marker rides its leading edge.
//
// Real vs. rendered rates are deliberately decoupled (round-9 legibility
// rule): real lathe rotation is 33 1/3 RPM and real pitch varies ~2x across
// ~40 grooves/mm — both documented below, neither animated 1:1. The
// rendered sweep is slowed to something a viewer can actually track: one
// revolution per 3s, one full "side" (lead-in to outer edge) over 42s, and
// a pitch-band transition roughly every 4s.
//
// Zero colour literals: --foreground is read via getComputedStyle at mount
// and re-read on a MutationObserver watching documentElement's class, with
// no paint before that first read. Canvas is DPR-capped, resized via
// ResizeObserver, paused via IntersectionObserver + visibilitychange.
// prefers-reduced-motion freezes on one drawn frame at 35% traversal,
// parked right where the pitch is visibly mid-transition.
// ---------------------------------------------------------------------------

const ANGULAR_RATE = (Math.PI * 2) / 3; // rad/s — 1 rendered rev / 3s (real: 33 1/3 RPM, documented only)
const TRAVERSAL_S = 42; // s — one full lead-in-to-edge sweep before reset
const PITCH_PERIOD_S = 8; // s — one wide/narrow modulation cycle (transition every ~4s)
const PITCH_RATIO = 5.8 / 2.2; // reference contrast at typical card scale, preserved at any size
const LEAD_IN_FRAC = 0.055; // inner radius as a fraction of the max drawn radius
const STATIC_PROGRESS = 0.35; // reduced-motion freeze: traversal fraction, mid pitch-transition

function parseHex(raw: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** Radial gain per revolution at traversal-time t, oscillating between the
 * ratio's two poles around a mid pitch sized so the spiral's outer edge is
 * reached almost exactly at TRAVERSAL_S regardless of container size. */
function pitchAt(t: number, midPitch: number): number {
  const amp = (midPitch * (PITCH_RATIO - 1)) / (PITCH_RATIO + 1);
  return midPitch + amp * Math.sin((Math.PI * 2 * t) / PITCH_PERIOD_S);
}

/** Sample the spiral's polyline points, its own leading-edge angle/radius,
 * and the total revolutions swept, from t = 0 up to `tEnd` (traversal
 * seconds). Deterministic integration — same result every call for the same
 * tEnd, which is what lets the reduced-motion path just call it once. */
function buildSpiral(tEnd: number, maxR: number, r0: number, midPitch: number) {
  const dt = 1 / 60; // integration step, independent of the caller's paint rate
  let t = 0;
  let theta = 0;
  let r = r0;
  const pts: { x: number; y: number }[] = [];
  pts.push({ x: r, y: 0 });
  while (t < tEnd && r < maxR) {
    const dTheta = ANGULAR_RATE * dt;
    const pitch = pitchAt(t, midPitch);
    r += (pitch / (Math.PI * 2)) * dTheta;
    theta += dTheta;
    t += dt;
    pts.push({ x: r * Math.cos(theta), y: r * Math.sin(theta) });
  }
  return { pts, theta, r: Math.min(r, maxR) };
}

export interface GroovePitchProps {
  /** accessible label for the loading status. @default "Loading" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GroovePitch({ label = "Loading", className = "" }: GroovePitchProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;
    let dpr = 1;
    let w = 0;
    let h = 0;
    let intersecting = true;
    let pageVisible = document.visibilityState === "visible";
    let visible = intersecting && pageVisible;
    let startedAt = 0;

    let fg: [number, number, number] = [23, 23, 23];

    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseHex(cs.getPropertyValue("--foreground").trim()) ?? fg;
    };
    readTokens();

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      const elapsed = startedAt === 0 ? 0 : performance.now() / 1000 - startedAt;
      draw(reduced ? STATIC_PROGRESS * TRAVERSAL_S : elapsed);
    };

    // geometry keyed off the container's SMALLER dimension, so this reads
    // at card scale rather than only at full-bleed
    const geom = () => {
      const minDim = Math.min(w, h);
      const maxR = minDim * 0.425; // spiral fits inside 0.85 * minDim diameter
      const r0 = maxR * LEAD_IN_FRAC;
      const midPitch = (maxR - r0) / ((TRAVERSAL_S * ANGULAR_RATE) / (Math.PI * 2));
      return { maxR, r0, midPitch };
    };

    const draw = (tSeconds: number) => {
      if (w <= 0 || h <= 0) return;
      const { maxR, r0, midPitch } = geom();
      const t = Math.max(0, Math.min(TRAVERSAL_S, tSeconds % TRAVERSAL_S));
      const { pts } = buildSpiral(t, maxR, r0, midPitch);

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.save();
      ctx.translate(w / 2, h / 2);

      ctx.beginPath();
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i];
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      }
      ctx.strokeStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},0.85)`;
      ctx.lineWidth = Math.max(1, Math.min(w, h) * 0.006);
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.stroke();

      // the cutting-point marker riding the spiral's leading edge — the one
      // thing a viewer should follow
      const tip = pts[pts.length - 1];
      if (tip) {
        ctx.beginPath();
        ctx.arc(tip.x, tip.y, Math.max(2, Math.min(w, h) * 0.018), 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},1)`;
        ctx.fill();
      }

      ctx.restore();
    };

    const loop = (now: number) => {
      if (!visible || reduced) {
        raf = 0;
        return;
      }
      if (startedAt === 0) startedAt = now / 1000;
      draw(now / 1000 - startedAt);
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    resize();
    if (reduced) draw(STATIC_PROGRESS * TRAVERSAL_S);
    else wake();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const mo = new MutationObserver(() => {
      readTokens();
      const elapsed = startedAt === 0 ? 0 : performance.now() / 1000 - startedAt;
      draw(reduced ? STATIC_PROGRESS * TRAVERSAL_S : elapsed);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const io = new IntersectionObserver(
      (entries) => {
        intersecting = entries[0]?.isIntersecting ?? true;
        visible = intersecting && pageVisible;
        if (visible) wake();
        else {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: 0 }
    );
    io.observe(root);

    const onVisibility = () => {
      pageVisible = document.visibilityState === "visible";
      visible = intersecting && pageVisible;
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        draw(STATIC_PROGRESS * TRAVERSAL_S);
      } else {
        startedAt = 0;
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      mq.removeEventListener("change", onReducedChange);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="status"
      aria-label={label}
      data-groove-pitch
      className={`relative aspect-square w-full max-w-[220px] ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
    </div>
  );
}

"use client";

import { useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GrowthRing — version history as a dendrochronological cross-section. The
// authoritative control is the listbox on the left: every fact (`v14 ·
// Priya Shah · +340 words · 14:02 · Restore`) lives there as real text, and
// keyboard/click drive it exactly like any other listbox. The SVG cross-
// section beside it is pure `aria-hidden` decoration that mirrors the same
// data geometrically — radius is the version's position in time (index,
// strictly monotonic; never re-sorted by author), ring width is the
// version's change magnitude clamped 2-14px, and a tight dark "latewood"
// line marks every boundary where authorship changed hands. Restoring is
// modeled as a literal cut: arming a version tilts every ring OUTSIDE it
// open on a shared hinge and dims them, so what a restore discards is shown
// before it happens; confirming is a distinct second step.
// ---------------------------------------------------------------------------

export type GrowthRingVersion = {
  id: string;
  /** short version tag, e.g. "v14" */
  label: string;
  author: string;
  /** magnitude of the change this version made — the scalar ring width derives from */
  delta: number;
  /** pre-formatted display string for the delta, e.g. "+340 words" */
  deltaLabel: string;
  /** pre-formatted display string for when it saved, e.g. "14:02" */
  time: string;
};

export interface GrowthRingProps {
  /** newest first, like a git log — the ring chart reads it in reverse (oldest at the core) */
  versions: GrowthRingVersion[];
  /** called once a restore is actually confirmed, with the version restored to */
  onRestore?: (version: GrowthRingVersion) => void;
  /** accessible name for the listbox; default "Version history" */
  ariaLabel?: string;
  className?: string;
}

const INNER_RADIUS = 20;
const MIN_RING_WIDTH = 2;
const MAX_RING_WIDTH = 14;
// A raw character/word delta of a few thousand (one giant paste) would
// otherwise dwarf every other ring and flatten the chart to "one huge band
// plus noise" — dividing before the clamp is what keeps normal edits in a
// readable 2-14px band while still clamping the outlier rather than trusting
// the divisor alone.
const DELTA_TO_PX = 25;
const PADDING_MIN = 14;
// The discard flap tilts open about its own bottom tangent via a 3D
// rotateX fold (see the "discarded" group below), not a flat in-plane
// rotate — a flat rotate of a full closed ring just produces a second,
// off-center ring, which is the actual bug this was chasing. The fold's
// foreshortening still pushes the far edge outward a bit. A fixed pixel
// padding runs out once the ring stack gets big enough — a proportional
// floor keeps the swing inside the viewBox no matter how many versions or
// how wide their rings get.
const HINGE_CLEARANCE_RATIO = 0.2;
const HINGE_DEG = 8;

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function plural(n: number, word: string) {
  return `${n} ${word}${n === 1 ? "" : "s"}`;
}

// A near-full circular arc, used only as an invisible <textPath> guide for
// the focused ring's author-initials label — never rendered with a stroke.
function arcGuide(cx: number, cy: number, r: number) {
  return `M ${cx} ${cy - r} A ${r} ${r} 0 1 1 ${cx - 0.01} ${cy - r}`;
}

type Ring = {
  id: string;
  version: GrowthRingVersion;
  chronoIndex: number; // 0 = oldest
  inner: number;
  outer: number;
  mid: number;
  width: number;
  handover: boolean; // author differs from the previous (older) version
};

function buildRings(versions: GrowthRingVersion[]): Ring[] {
  const chrono = [...versions].reverse(); // oldest first — radius follows time, nothing else
  let r = INNER_RADIUS;
  return chrono.map((v, i) => {
    const width = clamp(Math.round(Math.abs(v.delta) / DELTA_TO_PX), MIN_RING_WIDTH, MAX_RING_WIDTH);
    const inner = r;
    const outer = r + width;
    r = outer;
    const handover = i > 0 && chrono[i - 1].author !== v.author;
    return { id: v.id, version: v, chronoIndex: i, inner, outer, mid: (inner + outer) / 2, width, handover };
  });
}

export function GrowthRing({
  versions,
  onRestore,
  ariaLabel = "Version history",
  className = "",
}: GrowthRingProps) {
  const uid = useId();
  const [items, setItems] = useState(versions);
  const [activeId, setActiveId] = useState(items[0]?.id ?? "");
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [armedId, setArmedId] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const optionRefs = useRef(new Map<string, HTMLLIElement>());

  const rings = useMemo(() => buildRings(items), [items]);
  const outerMost = rings.length ? rings[rings.length - 1].outer : INNER_RADIUS;
  const padding = Math.max(PADDING_MIN, Math.round(outerMost * HINGE_CLEARANCE_RATIO));
  const size = outerMost + padding;
  const cx = size;
  const cy = size;
  const hingeX = cx;
  const hingeY = cy + outerMost; // bottom tangent of the whole disc

  const armedRing = armedId ? rings.find((r) => r.id === armedId) ?? null : null;
  const discardedRings = armedRing ? rings.filter((r) => r.chronoIndex > armedRing.chronoIndex) : [];
  const keptRings = armedRing ? rings.filter((r) => r.chronoIndex <= armedRing.chronoIndex) : rings;
  const discardedAuthors = new Set(discardedRings.map((r) => r.version.author));
  const discardCount = discardedRings.length;

  function arm(id: string) {
    const idx = items.findIndex((v) => v.id === id);
    if (idx <= 0) return; // the newest version is already current — nothing to preview or restore
    setArmedId(id);
    const target = items[idx];
    const authorsAhead = new Set(items.slice(0, idx).map((v) => v.author));
    setAnnouncement(
      `Restoring to ${target.label} removes ${plural(idx, "newer version")} by ${plural(authorsAhead.size, "author")}.`
    );
  }

  function disarm(announce: boolean) {
    setArmedId(null);
    if (announce) setAnnouncement("Restore cancelled.");
  }

  function commit() {
    if (!armedRing) return;
    const idx = items.findIndex((v) => v.id === armedRing.id);
    if (idx < 0) return;
    const restored = items[idx];
    const next = items.slice(idx); // the cut: everything newer than the restored version is gone
    setItems(next);
    setArmedId(null);
    setActiveId(restored.id);
    setAnnouncement(`Restored to ${restored.label}.`);
    onRestore?.(restored);
  }

  function focusOption(id: string) {
    setActiveId(id);
    optionRefs.current.get(id)?.focus();
  }

  function handleOptionKeyDown(e: React.KeyboardEvent<HTMLLIElement>, id: string) {
    const idx = items.findIndex((v) => v.id === id);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      const next = items[Math.min(idx + 1, items.length - 1)];
      if (next) focusOption(next.id);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      const prev = items[Math.max(idx - 1, 0)];
      if (prev) focusOption(prev.id);
    } else if (e.key === "Home") {
      e.preventDefault();
      if (items[0]) focusOption(items[0].id);
    } else if (e.key === "End") {
      e.preventDefault();
      const last = items[items.length - 1];
      if (last) focusOption(last.id);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      arm(id);
    } else if (e.key === "Escape" && armedId) {
      e.preventDefault();
      disarm(true);
    }
  }

  function ringStroke(chronoIndex: number) {
    return chronoIndex % 2 === 0 ? "var(--ns-muted)" : "var(--background)";
  }

  function renderRingGroup(group: Ring[], isCutFace: boolean) {
    return group.map((ring) => {
      const pulsed = ring.id === focusedId || ring.id === hoveredId;
      const strokeWidth = pulsed ? ring.width + 3 : ring.width;
      const showLabel = ring.id === focusedId;
      const guideId = `${uid}-arc-${ring.chronoIndex}`;
      return (
        <g key={ring.id}>
          <circle
            cx={cx}
            cy={cy}
            r={ring.mid}
            fill="none"
            stroke={ringStroke(ring.chronoIndex)}
            strokeWidth={strokeWidth}
            className="ns-growth-ring"
          />
          <circle
            cx={cx}
            cy={cy}
            r={ring.inner}
            fill="none"
            stroke={ring.handover ? "var(--foreground)" : "var(--border)"}
            strokeWidth={ring.handover ? 1.6 : 1}
          />
          {showLabel ? (
            <>
              <path id={guideId} d={arcGuide(cx, cy, ring.mid)} fill="none" stroke="none" />
              <text
                className="font-mono"
                fontSize={Math.max(7, Math.min(9, ring.width))}
                fill="var(--foreground)"
              >
                <textPath href={`#${guideId}`} startOffset="2%">
                  {initials(ring.version.author)}
                </textPath>
              </text>
            </>
          ) : null}
        </g>
      );
    });
  }

  return (
    <div data-growth-root className={className}>
      <style>{`
.ns-growth-ring{transition:stroke-width 200ms cubic-bezier(0.16,1,0.3,1)}
.ns-growth-outer{transition:transform 420ms cubic-bezier(0.16,1,0.3,1),opacity 420ms cubic-bezier(0.16,1,0.3,1)}
.ns-growth-option{transition:background-color 160ms ease,border-color 160ms ease}
@media (prefers-reduced-motion: reduce){
  .ns-growth-ring{transition:none}
  .ns-growth-outer{transition:opacity 150ms linear !important;transform:none !important}
  .ns-growth-option{transition:none}
}
`}</style>

      <div className="flex flex-col gap-6 sm:flex-row sm:items-start">
        <ul
          role="listbox"
          aria-label={ariaLabel}
          className="min-w-0 flex-1 divide-y divide-border rounded-md border border-border"
        >
          {items.map((v, idx) => {
            const isArmed = v.id === armedId;
            const isActive = v.id === activeId;
            const isFocused = v.id === focusedId;
            return (
              <li
                key={v.id}
                ref={(el) => {
                  if (el) optionRefs.current.set(v.id, el);
                  else optionRefs.current.delete(v.id);
                }}
                role="option"
                aria-selected={isArmed}
                tabIndex={isActive ? 0 : -1}
                data-growth-version={v.id}
                onFocus={() => setFocusedId(v.id)}
                onBlur={() => setFocusedId((f) => (f === v.id ? null : f))}
                onMouseEnter={() => setHoveredId(v.id)}
                onMouseLeave={() => setHoveredId((h) => (h === v.id ? null : h))}
                onClick={() => {
                  setActiveId(v.id);
                  arm(v.id);
                }}
                onKeyDown={(e) => handleOptionKeyDown(e, v.id)}
                className={
                  "ns-growth-option flex cursor-pointer flex-wrap items-baseline gap-x-2.5 gap-y-0.5 px-3 py-2 text-sm focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent " +
                  (isFocused
                    ? "border-l-2 border-ns-accent bg-surface pl-[10px]"
                    : "border-l-2 border-transparent pl-[10px]") +
                  (isArmed ? " bg-surface" : "")
                }
              >
                <span className="font-mono text-foreground">{v.label}</span>
                <span className="text-foreground">{v.author}</span>
                <span className="font-mono tabular-nums text-ns-muted">{v.deltaLabel}</span>
                <span className="font-mono tabular-nums text-ns-muted">{v.time}</span>
                <span className="ml-auto shrink-0 rounded-full border border-border px-2 py-0.5 font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                  {idx === 0 ? "Current" : "Restore"}
                </span>
              </li>
            );
          })}
        </ul>

        <svg
          aria-hidden="true"
          focusable="false"
          viewBox={`0 0 ${size * 2} ${size * 2}`}
          className="h-48 w-48 shrink-0 sm:h-56 sm:w-56"
        >
          <g>{renderRingGroup(keptRings, false)}</g>
          {armedRing ? (
            <circle
              cx={cx}
              cy={cy}
              r={armedRing.outer}
              fill="none"
              stroke="var(--foreground)"
              strokeWidth={2}
            />
          ) : (
            <circle cx={cx} cy={cy} r={outerMost} fill="none" stroke="var(--border)" strokeWidth={1} />
          )}
          {discardedRings.length ? (
            <g
              data-discarded="true"
              className="ns-growth-outer"
              style={{
                transformOrigin: `${hingeX}px ${hingeY}px`,
                // A flat in-plane rotate() here was the actual bug: these
                // are full closed rings, and rotating a closed circle about
                // a point on its own rim in 2D just produces a second,
                // same-radius circle with a *different center* — it reads
                // as "misaligned," not "hinged open," because there's no
                // such thing as a partial-arc 2D rotation of a full ring
                // that stays concentric. A hinge that lifts away from the
                // viewer needs the Z axis: rotateX about the hinge line
                // keeps the near (bottom) edge anchored to the kept rings
                // and tilts the far edge back/up with real foreshortening,
                // which is what "opening like a lid" actually looks like.
                transform: `perspective(560px) rotateX(-${HINGE_DEG}deg)`,
                transformStyle: "preserve-3d",
                opacity: 0.4,
              }}
            >
              {renderRingGroup(discardedRings, true)}
            </g>
          ) : null}
        </svg>
      </div>

      {armedRing ? (
        <div data-growth-confirm-panel className="mt-4 rounded-md border border-border bg-surface p-3">
          <p className="text-sm text-foreground">
            This removes {plural(discardCount, "newer version")} by{" "}
            {plural(discardedAuthors.size, "author")}.
          </p>
          <div className="mt-2.5 flex gap-2">
            <button
              type="button"
              onClick={() => disarm(true)}
              className="rounded-sm border border-border px-3 py-1.5 text-sm text-foreground transition-colors hover:bg-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              Cancel
            </button>
            <button
              type="button"
              data-growth-confirm
              onClick={commit}
              className="rounded-sm bg-ns-accent px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              Confirm restore to {armedRing.version.label}
            </button>
          </div>
        </div>
      ) : null}

      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// KeyInterlock — output guardrails drawn as a trapped-key interlock.
//
// Every policy gate physically holds one key. A gate that passed has its key
// SEATED in its keyway; a gate still evaluating has an EMPTY keyway with a
// breathing dashed outline; a gate that tripped has an empty keyway with a
// solid bar drawn across it, so it cannot accept a key at all. Every state is
// shape-coded — seated / empty-dashed / empty-barred — and there is no status
// hue anywhere in the component, so it survives monochrome and both themes.
//
// Released keys travel to the RELEASE LOCK on the right. The lock's bolt only
// retracts once every slot is filled; until then it stays shut across the
// output port and the output panel below renders dimmed behind a diagonal
// hatch. Overriding a tripped gate seats a HATCHED key instead of a solid one
// and writes a permanent audit line — an overridden interlock stays visually
// distinguishable from a passed one forever. That is the safety property.
// ---------------------------------------------------------------------------

export type InterlockGateState = "pending" | "released" | "tripped";

export type InterlockGate = {
  /** rule id, shown in Geist Mono and used in the audit line, e.g. "pii_scan" */
  id: string;
  label: string;
  state: InterlockGateState;
  /** one line shown in the mono strip while the gate is hovered or focused */
  detail?: string;
};

export interface KeyInterlockProps {
  /** the interlock's rules, each independently tripped/released */
  gates: InterlockGate[];
  /** the model output the lock is holding */
  output: string;
  /** accessible name for the interlock group */
  label?: string;
  /** short caption above the row */
  title?: string;
  /** who is recorded on an override audit line */
  operator?: string;
  /** fired when a tripped gate is overridden — the owner flips that gate to
   * "released" (this component never mutates the gates it was handed) */
  onOverride?: (id: string) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const GATE_W = 40;
const GATE_H = 54;
const LOCK_W = 88;
/** keeps the slot run off the lock's own side walls, so the outermost slot is
 * never drawn half on top of the body outline */
const SLOT_INSET = 10;
const TRAVEL_MS = 420;
const TRAVEL_EASE = "cubic-bezier(0.22,1,0.36,1)";

type Flight = {
  id: string;
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  hatched: boolean;
  moved: boolean;
};

function stamp() {
  return new Date().toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });
}

function stateWord(g: InterlockGate, overridden: boolean) {
  if (g.state === "released")
    return overridden ? "released by override" : "key seated";
  if (g.state === "tripped") return "tripped, keyway barred";
  return "awaiting key";
}

/** the key glyph: a 7px bit filling the keyway over a 3px stem */
function KeyGlyph({
  hatch,
  patternId,
}: {
  hatch: boolean;
  patternId: string;
}) {
  const fill = hatch ? `url(#${patternId})` : "currentColor";
  return (
    <>
      <rect
        x="0.5"
        y="0"
        width="7"
        height="8"
        fill={fill}
        stroke={hatch ? "currentColor" : "none"}
        strokeWidth={hatch ? 1 : 0}
      />
      <rect x="2.5" y="8" width="3" height="18" fill="currentColor" />
    </>
  );
}

export function KeyInterlock({
  gates,
  output,
  label = "Output guardrails",
  title = "Output interlock",
  operator = "operator",
  onOverride,
  className = "",
}: KeyInterlockProps) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const hatchId = `ns-ilk-hatch-${uid}`;

  const rowRef = useRef<HTMLDivElement>(null);
  const gateKeyRefs = useRef<Record<string, HTMLSpanElement | null>>({});
  const lockSlotRefs = useRef<Record<string, HTMLSpanElement | null>>({});

  // seeded from props so the very first paint (server and client alike) already
  // shows the keys that are in, instead of flashing an empty lock
  const arrivedRef = useRef<Set<string>>(
    new Set(gates.filter((g) => g.state === "released").map((g) => g.id))
  );
  const inFlightRef = useRef<Set<string>>(new Set());
  const overriddenRef = useRef<Set<string>>(new Set());
  const announcedRef = useRef<Set<string>>(new Set());
  const mountedRef = useRef(false);
  const timersRef = useRef<number[]>([]);
  const [, bump] = useReducer((n: number) => n + 1, 0);

  const [flights, setFlights] = useState<Flight[]>([]);
  const [audit, setAudit] = useState<string[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  useEffect(
    () => () => {
      timersRef.current.forEach((t) => window.clearTimeout(t));
    },
    []
  );

  const later = useCallback((fn: () => void, ms: number) => {
    const t = window.setTimeout(fn, ms);
    timersRef.current.push(t);
  }, []);

  const startFlight = useCallback(
    (id: string) => {
      const row = rowRef.current;
      const from = gateKeyRefs.current[id];
      const to = lockSlotRefs.current[id];
      if (!row || !from || !to) {
        arrivedRef.current.add(id);
        bump();
        return;
      }
      const r = row.getBoundingClientRect();
      const a = from.getBoundingClientRect();
      const b = to.getBoundingClientRect();
      inFlightRef.current.add(id);
      const flight: Flight = {
        id,
        x0: a.left - r.left,
        y0: a.top - r.top,
        x1: b.left - r.left,
        y1: b.top - r.top,
        hatched: overriddenRef.current.has(id),
        moved: false,
      };
      setFlights((f) => [...f.filter((x) => x.id !== id), flight]);
      requestAnimationFrame(() =>
        requestAnimationFrame(() =>
          setFlights((f) =>
            f.map((x) => (x.id === id ? { ...x, moved: true } : x))
          )
        )
      );
      later(() => {
        inFlightRef.current.delete(id);
        arrivedRef.current.add(id);
        setFlights((f) => f.filter((x) => x.id !== id));
        bump();
      }, TRAVEL_MS);
    },
    [later]
  );

  // reconcile the lock against the gates it was handed: a gate that reaches
  // "released" sends its key across; a gate that leaves "released" (re-armed
  // upstream) takes its key back out of the lock.
  useEffect(() => {
    let changed = false;
    for (const g of gates) {
      const arrived = arrivedRef.current.has(g.id);
      const flying = inFlightRef.current.has(g.id);
      if (g.state === "released" && !arrived && !flying) {
        if (!mountedRef.current || reduced) {
          arrivedRef.current.add(g.id);
          changed = true;
        } else {
          startFlight(g.id);
        }
      }
      if (g.state !== "released" && arrived) {
        arrivedRef.current.delete(g.id);
        changed = true;
      }
    }
    mountedRef.current = true;
    if (changed) bump();
  }, [gates, reduced, startFlight]);

  // announce each trip exactly once
  useEffect(() => {
    const fresh = gates.filter(
      (g) => g.state === "tripped" && !announcedRef.current.has(g.id)
    );
    for (const g of gates) {
      if (g.state !== "tripped") announcedRef.current.delete(g.id);
    }
    if (fresh.length === 0) return;
    fresh.forEach((g) => announcedRef.current.add(g.id));
    setAnnounce(
      fresh.map((g) => `${g.id} tripped, output held`).join(". ") + "."
    );
  }, [gates]);

  useEffect(() => {
    if (!activeId) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setActiveId(null);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [activeId]);

  const seated = gates.filter((g) => arrivedRef.current.has(g.id)).length;
  const released = seated === gates.length && gates.length > 0;
  const tripped = gates.filter((g) => g.state === "tripped");
  const active = gates.find((g) => g.id === activeId) ?? null;

  const slotXs = useMemo(() => {
    const n = Math.max(gates.length, 1);
    const step = (LOCK_W - SLOT_INSET * 2) / n;
    return gates.map((_, i) => SLOT_INSET + step * (i + 0.5));
  }, [gates]);

  function override(g: InterlockGate) {
    if (g.state !== "tripped") return;
    overriddenRef.current.add(g.id);
    // newest first, and the list is height-bounded rather than unbounded: an
    // audit trail that grows the component's own box forever makes the card
    // reframe on every entry. Nothing is ever dropped — it scrolls.
    setAudit((a) => [`override ${g.id} · ${operator} · ${stamp()}`, ...a]);
    setAnnounce(`${g.id} overridden by ${operator}`);
    onOverride?.(g.id);
  }

  return (
    <div
      data-interlock
      role="group"
      aria-label={label}
      className={"font-sans " + className}
    >
      <style>{`
.ns-ilk-breathe{animation:ns-ilk-breathe 3.2s ease-in-out infinite alternate}
@keyframes ns-ilk-breathe{from{opacity:.45}to{opacity:1}}
.ns-ilk-gate{transition:transform 180ms ease-out,opacity 180ms ease-out}
.ns-ilk-strip{transition:opacity 180ms ease-out,transform 180ms ease-out}
.ns-ilk-bolt{transition:transform ${TRAVEL_MS}ms cubic-bezier(0.34,1.8,0.64,1)}
.ns-ilk-fly{transition:transform ${TRAVEL_MS}ms ${TRAVEL_EASE}}
.ns-ilk-veil{transition:opacity 320ms ease-out}
@media (prefers-reduced-motion: reduce){
  .ns-ilk-breathe{animation:none;opacity:.75}
  .ns-ilk-gate,.ns-ilk-strip,.ns-ilk-bolt,.ns-ilk-fly,.ns-ilk-veil{transition:none}
}
`}</style>

      <div className="mb-4 flex items-end justify-between gap-4">
        <p className="font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted">
          {title}
        </p>
        <p
          data-interlock-readout
          className="shrink-0 font-mono text-[11px] text-foreground"
        >
          {seated}/{gates.length} keys
          <span className="px-1.5 text-ns-muted">·</span>
          {released ? "output released" : "output held"}
        </p>
      </div>

      {/* ---- the interlock row ------------------------------------------ */}
      <div
        ref={rowRef}
        data-interlock-row
        className="relative flex items-start"
        onPointerLeave={() => setActiveId(null)}
        onBlur={() => setActiveId(null)}
      >
        <div className="flex items-start gap-3">
          {gates.map((g, i) => {
            const dim = activeId !== null && activeId !== g.id;
            const lift = activeId === g.id;
            const overridden = overriddenRef.current.has(g.id);
            return (
              <button
                key={g.id}
                type="button"
                data-interlock-gate={g.id}
                data-state={g.state}
                aria-label={`${g.label}: ${stateWord(g, overridden)}${
                  g.detail ? `. ${g.detail}` : ""
                }`}
                onPointerEnter={() => setActiveId(g.id)}
                onFocus={() => setActiveId(g.id)}
                // a tap/click pins this gate's detail. Deliberately NOT a
                // toggle: pointerenter has already set activeId, so toggling
                // would blank the strip on the very click that asked for it.
                onClick={() => setActiveId(g.id)}
                className={
                  "ns-ilk-gate group flex w-16 flex-col items-center rounded-sm text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent " +
                  (dim ? "opacity-30 " : "opacity-100 ") +
                  (lift ? "-translate-y-0.5" : "translate-y-0")
                }
              >
                <span className="relative block">
                  {/* keyway centre marker — the flight origin */}
                  <span
                    ref={(el) => {
                      gateKeyRefs.current[g.id] = el;
                    }}
                    aria-hidden
                    className="pointer-events-none absolute left-[16.5px] top-[3px] block h-0 w-0"
                  />
                  <svg
                    width={GATE_W}
                    height={GATE_H}
                    viewBox={`0 0 ${GATE_W} ${GATE_H}`}
                    fill="none"
                    aria-hidden
                    className="block text-foreground"
                  >
                    <defs>
                      <pattern
                        id={`${hatchId}-${i}`}
                        width="4"
                        height="4"
                        patternUnits="userSpaceOnUse"
                        patternTransform="rotate(45)"
                      >
                        <rect
                          width="2"
                          height="4"
                          fill="currentColor"
                          opacity="0.85"
                        />
                      </pattern>
                    </defs>
                    {/* slot body with the keyway notch cut into its top edge */}
                    <path
                      d="M0.5 53.5 V0.5 H16.5 V14 H23.5 V0.5 H39.5 V53.5 Z"
                      className="stroke-border"
                      strokeWidth="1"
                    />
                    {g.state === "released" ? (
                      <g transform="translate(16,3.5)">
                        <KeyGlyph
                          hatch={overridden}
                          patternId={`${hatchId}-${i}`}
                        />
                      </g>
                    ) : null}
                    {g.state === "pending" ? (
                      <rect
                        className="ns-ilk-breathe stroke-foreground"
                        style={{ animationDelay: `${((i * 260) % 1040) - 520}ms` }}
                        x="16.75"
                        y="2.75"
                        width="6.5"
                        height="10.5"
                        strokeWidth="1.5"
                        strokeDasharray="2 2"
                        fill="none"
                      />
                    ) : null}
                    {g.state === "tripped" ? (
                      <line
                        x1="8"
                        y1="18"
                        x2="32"
                        y2="4.1"
                        className="stroke-foreground"
                        strokeWidth="2"
                        strokeLinecap="round"
                      />
                    ) : null}
                  </svg>
                </span>
                <span
                  className={
                    "mt-2 block w-full break-all text-center font-mono text-[10px] leading-[1.15] " +
                    (g.state === "tripped"
                      ? "font-medium text-foreground"
                      : "text-ns-muted")
                  }
                  title={g.id}
                >
                  {g.id}
                </span>
              </button>
            );
          })}
        </div>

        {/* rail from the gates to the lock */}
        <div className="relative mx-3 h-[54px] w-8 shrink-0" aria-hidden>
          <div className="absolute inset-x-0 top-[9px] h-px bg-border" />
        </div>

        {/* ---- the release lock ----------------------------------------- */}
        <div className="flex shrink-0 flex-col items-center">
          <span className="relative block">
            {gates.map((g, i) => (
              <span
                key={g.id}
                ref={(el) => {
                  lockSlotRefs.current[g.id] = el;
                }}
                aria-hidden
                className="pointer-events-none absolute top-[8px] block h-0 w-0"
                style={{ left: `${slotXs[i] - 3.5}px` }}
              />
            ))}
            <svg
              width={LOCK_W}
              height={GATE_H}
              viewBox={`0 0 ${LOCK_W} ${GATE_H}`}
              fill="none"
              aria-hidden
              className="block text-foreground"
            >
              <defs>
                <pattern
                  id={`${hatchId}-lock`}
                  width="4"
                  height="4"
                  patternUnits="userSpaceOnUse"
                  patternTransform="rotate(45)"
                >
                  <rect width="2" height="4" fill="currentColor" opacity="0.85" />
                </pattern>
              </defs>
              {/* lock body, open at the bottom where the output port is */}
              <path
                d="M32.5 53.5 H0.5 V0.5 H87.5 V53.5 H55.5"
                className="stroke-border"
                strokeWidth="1"
              />
              {gates.map((g, i) => {
                const filled = arrivedRef.current.has(g.id);
                const overridden = overriddenRef.current.has(g.id);
                return (
                  <rect
                    key={g.id}
                    data-lock-slot={g.id}
                    data-filled={filled ? "true" : "false"}
                    x={slotXs[i] - 3.5}
                    y="8"
                    width="7"
                    height="12"
                    fill={
                      filled
                        ? overridden
                          ? `url(#${hatchId}-lock)`
                          : "currentColor"
                        : "none"
                    }
                    className={filled ? "stroke-foreground" : "stroke-border"}
                    strokeWidth="1"
                  />
                );
              })}
              {/* the bolt: shut across the output port until every key is in */}
              <rect
                data-interlock-bolt
                data-retracted={released ? "true" : "false"}
                className="ns-ilk-bolt fill-current"
                x="33"
                y="44"
                width="22"
                height="6"
                rx="1"
                style={{
                  transform: released ? "translateX(20px)" : "translateX(0)",
                }}
              />
            </svg>
          </span>
          <span className="mt-2 block font-mono text-[9px] leading-none text-ns-muted">
            release lock
          </span>
        </div>

        {/* ---- key travel overlay --------------------------------------- */}
        <div className="pointer-events-none absolute inset-0" aria-hidden>
          {flights.length > 0 ? (
            <svg className="absolute inset-0 h-full w-full" fill="none">
              {flights.map((f) => (
                <line
                  key={f.id}
                  x1={f.x0 + 4}
                  y1={f.y0 + 4}
                  x2={f.x1 + 4}
                  y2={f.y1 + 4}
                  className="stroke-border"
                  strokeWidth="1"
                />
              ))}
            </svg>
          ) : null}
          {flights.map((f) => (
            <svg
              key={f.id}
              width="8"
              height="26"
              viewBox="0 0 8 26"
              fill="none"
              className="ns-ilk-fly absolute left-0 top-0 text-foreground"
              style={{
                transform: f.moved
                  ? `translate(${f.x1}px, ${f.y1}px)`
                  : `translate(${f.x0}px, ${f.y0}px)`,
              }}
            >
              <defs>
                <pattern
                  id={`${hatchId}-fly-${f.id}`}
                  width="4"
                  height="4"
                  patternUnits="userSpaceOnUse"
                  patternTransform="rotate(45)"
                >
                  <rect width="2" height="4" fill="currentColor" opacity="0.85" />
                </pattern>
              </defs>
              <KeyGlyph
                hatch={f.hatched}
                patternId={`${hatchId}-fly-${f.id}`}
              />
            </svg>
          ))}
        </div>
      </div>

      {/* ---- detail strip ------------------------------------------------ */}
      <div
        id={`${uid}-strip`}
        className="ns-ilk-strip mt-4 h-[16px] font-mono text-[11px] leading-[16px] text-ns-muted"
        style={{
          opacity: active ? 1 : 0,
          transform: active ? "translateY(0)" : "translateY(-2px)",
        }}
      >
        {active ? (
          <>
            <span className="text-foreground">{active.id}</span>
            <span className="px-1.5">·</span>
            {active.detail ?? stateWord(active, overriddenRef.current.has(active.id))}
          </>
        ) : null}
      </div>

      {/* ---- override controls ------------------------------------------- */}
      {tripped.length > 0 ? (
        <div className="mt-3 flex flex-wrap gap-2">
          {tripped.map((g) => (
            <button
              key={g.id}
              type="button"
              data-override={g.id}
              onClick={() => override(g)}
              className="rounded-sm border border-border px-2.5 py-1 font-mono text-[11px] uppercase tracking-wide text-foreground transition-colors hover:bg-surface focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              override {g.id}
            </button>
          ))}
        </div>
      ) : null}

      {/* ---- the held output --------------------------------------------- */}
      <div className="relative mt-5">
        <div
          className="ns-ilk-veil rounded-md border border-border bg-surface p-4"
          style={{ opacity: released ? 1 : 0.35 }}
        >
          <p className="mb-2 font-mono text-[10px] uppercase tracking-[0.18em] text-ns-muted">
            model output
          </p>
          <p className="text-sm leading-relaxed text-foreground">{output}</p>
        </div>
        <div
          aria-hidden
          className="ns-ilk-veil pointer-events-none absolute inset-0 rounded-md"
          style={{
            opacity: released ? 0 : 1,
            backgroundImage:
              "repeating-linear-gradient(45deg, color-mix(in srgb, var(--foreground) 8%, transparent) 0 1px, transparent 1px 4px)",
          }}
        />
      </div>

      {/* ---- permanent audit trail --------------------------------------- */}
      {audit.length > 0 ? (
        <div className="mt-4 border-t border-border pt-3">
          <p className="mb-1.5 font-mono text-[10px] uppercase tracking-[0.18em] text-ns-muted">
            audit
          </p>
          {/* exactly three 17px lines + two 4px gaps — a partial clipped line
              would read as a rendering bug rather than a scroll affordance */}
          <ul className="max-h-[59px] space-y-1 overflow-y-auto">
            {audit.map((line, i) => (
              <li
                key={i}
                data-audit-line
                className="font-mono text-[11px] text-foreground"
              >
                {line}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <p role="status" aria-live="polite" className="sr-only">
        {announce}
      </p>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// HachureFall — a route elevation profile drawn the way 18th-century military
// engravers drew slope: short strokes perpendicular to the profile line,
// hanging down the fall direction, whose LENGTH and DENSITY are both driven
// by one governing scalar, the local grade g = dh/dx. A flat kilometre earns
// no ink; a 12% ramp earns a dense comb. There is deliberately no colour
// ramp anywhere in this file — colour is the legend hachures were invented
// to remove, and re-introducing it here would defeat the point.
//
// GEOMETRY: the elevation curve itself is auto-fit to a fixed internal band
// (CURVE_BAND_H) purely so the route has a recognisable silhouette — that
// vertical fit is an ordinary chart auto-scale, computed once from the data,
// never exposed as a control. It is NOT the source of stroke length. Stroke
// length comes from the real-world grade percentage (elevation-metres over
// distance-metres), multiplied by the fixed constant K = STROKE_UNIT_PX /
// UNIT_GRADE_PCT, printed in the corner as "1 stroke-height = 5% grade".
// Because the two scales are independent, two routes drawn at different
// auto-fit heights still produce numerically comparable hachures — which is
// the whole reason a vertical-exaggeration SLIDER is refused here: exposing
// one would let a reader silently change what an identical stroke length
// means between two profiles, exactly the dishonesty hachure marks exist to
// prevent. K is a module constant, not a prop.
//
// Every segment's hachures are emitted as ONE <path> (a run of "M..L.."
// subpaths), not one DOM node per stroke — generated from data, never
// hand-placed. Spacing follows spacing = S0 / (1 + |g|) (g as a fraction),
// so a steep segment's ticks crowd together while a flat one thins to
// nothing under MIN_LEN_PX and draws no ticks at all.
//
// SCRUB CURSOR: pointer or keyboard sets a target km; the rendered cursor
// (and which segment is "active" — promoted from --ns-muted to --foreground,
// its ticks lifted ~2px like bristles under a thumb) tracks a 90ms
// critically damped spring toward that target, not the raw input. An
// undamped 1:1 follow flickers across segment boundaries on noisy real
// elevation data; a longer/underdamped spring feels detached from the
// pointer. The spring only runs while hovered or focused — there is no
// resting position to relax back to, the cursor simply appears/disappears.
//
// A11Y: the track itself is role="slider" over distance (km), with
// aria-valuetext "km 14.2, 220 m elevation, 9% climb". PageUp/PageDown do
// not step a fixed distance — they jump to the next point where the grade's
// classification bucket (flat / easy / moderate / steep / very steep, signed
// by climb vs descent) changes, a real navigation unit for a route rather
// than an arbitrary number of km. aria-describedby points at a static
// plain-text shape summary (total climb, named climbs, the single steepest
// point) so the drawing's information survives without vision, independent
// of live scrubbing.
// ---------------------------------------------------------------------------

export interface ElevationPoint {
  /** distance along the route, kilometres, strictly increasing */
  km: number;
  /** elevation at that distance, metres */
  m: number;
}

export interface HachureFallProps {
  /** elevation samples, ordered by km. Needs at least 2 points. */
  data?: ElevationPoint[];
  /** accessible name for the slider. Default "Route elevation profile". */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// -- fixed constants: the falsifiable, non-adjustable half of the contract --
const VW = 760; // internal SVG coordinate width
const PAD_X = 12; // internal px, left/right inset for the plotted curve
const TOP_PAD = 18; // internal px above the curve band
const CURVE_BAND_H = 88; // internal px the elevation silhouette auto-fits into
const HACHURE_ROOM = 66; // internal px reserved below the curve for strokes
const VH = TOP_PAD + CURVE_BAND_H + HACHURE_ROOM;

const STROKE_UNIT_PX = 14; // "1 stroke-height" — the printed legend unit
const UNIT_GRADE_PCT = 5; // ...corresponds to this many percent grade
const K = STROKE_UNIT_PX / UNIT_GRADE_PCT; // px of stroke per percent grade — FIXED
const MAX_LEN_PX = 58; // hard visual ceiling so absurd grades don't blow the layout
const MIN_LEN_PX = 0.6; // below this, draw nothing — the "nearly blank" flat case
const S0 = 9; // base tick spacing (internal px) at ~0 grade

const CURSOR_LIFT_PX = 2; // bristle lift near the scrub cursor
const CURSOR_WINDOW_PX = 42; // internal px falloff radius for the lift

const SPRING_K = 4200; // s^-2 — tuned so the critically damped response settles ~90ms
const SPRING_C = 2 * Math.sqrt(SPRING_K); // critical damping: c = 2*sqrt(k)

const CLASS_BOUNDS = [2, 4, 7, 10]; // abs% grade thresholds separating classes

const DEFAULT_DATA: ElevationPoint[] = [
  { km: 0, m: 140 },
  { km: 1, m: 142 },
  { km: 2, m: 146 },
  { km: 3, m: 148 },
  { km: 4, m: 150 },
  { km: 4.5, m: 172 },
  { km: 5, m: 210 },
  { km: 5.5, m: 258 },
  { km: 6, m: 298 },
  { km: 6.5, m: 322 },
  { km: 7, m: 330 },
  { km: 8, m: 332 },
  { km: 9, m: 328 },
  { km: 10, m: 330 },
  { km: 11, m: 335 },
  { km: 12, m: 338 },
  { km: 13, m: 336 },
  { km: 14, m: 340 },
  { km: 15, m: 344 },
  { km: 16, m: 342 },
  { km: 17, m: 300 },
  { km: 17.5, m: 260 },
  { km: 18, m: 224 },
  { km: 18.5, m: 196 },
  { km: 19, m: 180 },
  { km: 20, m: 178 },
  { km: 21, m: 182 },
  { km: 21.5, m: 210 },
  { km: 22, m: 254 },
  { km: 22.4, m: 296 },
  { km: 22.8, m: 336 },
  { km: 23.2, m: 372 },
  { km: 23.6, m: 400 },
  { km: 24, m: 412 },
  { km: 25, m: 414 },
  { km: 26, m: 410 },
  { km: 27, m: 412 },
  { km: 28, m: 408 },
];

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

function classIndexFor(gradePct: number): number {
  const mag = Math.abs(gradePct);
  let bucket = 0;
  for (let i = 0; i < CLASS_BOUNDS.length; i++) {
    if (mag >= CLASS_BOUNDS[i]) bucket = i + 1;
  }
  if (bucket === 0) return 0; // flat, sign doesn't matter
  return gradePct > 0 ? bucket : -bucket;
}

function gradeWord(gradePct: number): string {
  const r = Math.round(Math.abs(gradePct));
  if (gradePct > 0.5) return `${r}% climb`;
  if (gradePct < -0.5) return `${r}% descent`;
  return "flat";
}

interface Point {
  x: number;
  y: number;
}

interface Tick {
  frac: number; // 0..1 along the segment
  bx: number;
  by: number;
  px: number; // unit perpendicular x
  py: number; // unit perpendicular y
  baseLen: number;
}

interface Segment {
  index: number;
  kmStart: number;
  kmEnd: number;
  gradePct: number;
  p0: Point;
  p1: Point;
  dx: number;
  dy: number;
  lenPx: number;
  dBase: string;
  ticks: Tick[];
}

function tickPathD(bx: number, by: number, px: number, py: number, len: number): string {
  const ex = bx + px * len;
  const ey = by + py * len;
  return `M${bx.toFixed(2)},${by.toFixed(2)}L${ex.toFixed(2)},${ey.toFixed(2)}`;
}

function buildSegments(data: ElevationPoint[]): Segment[] {
  if (data.length < 2) return [];
  const elevs = data.map((d) => d.m);
  const minElev = Math.min(...elevs);
  const maxElev = Math.max(...elevs);
  const range = Math.max(1, maxElev - minElev);
  const totalKm = data[data.length - 1].km || 1;
  const plotW = VW - PAD_X * 2;

  const project = (p: ElevationPoint): Point => ({
    x: PAD_X + (p.km / totalKm) * plotW,
    y: TOP_PAD + CURVE_BAND_H * (1 - (p.m - minElev) / range),
  });

  const segments: Segment[] = [];
  for (let i = 0; i < data.length - 1; i++) {
    const a = data[i];
    const b = data[i + 1];
    const p0 = project(a);
    const p1 = project(b);
    const dx = p1.x - p0.x;
    const dy = p1.y - p0.y;
    const lenPx = Math.hypot(dx, dy);
    const distM = (b.km - a.km) * 1000;
    const gradePct = distM > 0 ? ((b.m - a.m) / distM) * 100 : 0;

    if (lenPx < 0.01) {
      segments.push({ index: i, kmStart: a.km, kmEnd: b.km, gradePct, p0, p1, dx, dy, lenPx: 0.01, dBase: "", ticks: [] });
      continue;
    }

    const tx = dx / lenPx;
    const ty = dy / lenPx;
    // perpendicular, oriented so its y-component is non-negative — "down"
    // in screen space, i.e. the fall direction, regardless of climb or
    // descent sign
    let px = -ty;
    let py = tx;
    if (py < 0 || (py === 0 && px < 0)) {
      px = -px;
      py = -py;
    }

    const strokeLen = clamp(K * Math.abs(gradePct), 0, MAX_LEN_PX);
    const ticks: Tick[] = [];
    let dParts = "";

    if (strokeLen >= MIN_LEN_PX) {
      const spacing = S0 / (1 + Math.abs(gradePct) / 100);
      const nTicks = Math.max(1, Math.min(400, Math.floor(lenPx / spacing)));
      for (let k = 0; k < nTicks; k++) {
        const frac = (k + 0.5) / nTicks;
        const bx = p0.x + dx * frac;
        const by = p0.y + dy * frac;
        ticks.push({ frac, bx, by, px, py, baseLen: strokeLen });
        dParts += tickPathD(bx, by, px, py, strokeLen);
      }
    }

    segments.push({
      index: i,
      kmStart: a.km,
      kmEnd: b.km,
      gradePct,
      p0,
      p1,
      dx,
      dy,
      lenPx,
      dBase: dParts,
      ticks,
    });
  }
  return segments;
}

function profilePath(data: ElevationPoint[], segments: Segment[]): string {
  if (segments.length === 0) return "";
  let d = `M${segments[0].p0.x.toFixed(2)},${segments[0].p0.y.toFixed(2)}`;
  for (const s of segments) d += `L${s.p1.x.toFixed(2)},${s.p1.y.toFixed(2)}`;
  return d;
}

interface Climb {
  startKm: number;
  endKm: number;
  avgGradePct: number;
}

interface RouteSummary {
  text: string;
  boundaries: number[]; // km positions where the grade class changes
}

function summarizeRoute(data: ElevationPoint[], segments: Segment[]): RouteSummary {
  if (segments.length === 0) {
    return { text: "No elevation data.", boundaries: [] };
  }

  let totalClimbM = 0;
  for (let i = 0; i < data.length - 1; i++) {
    const rise = data[i + 1].m - data[i].m;
    if (rise > 0) totalClimbM += rise;
  }

  const boundaries: number[] = [];
  let prevClass = classIndexFor(segments[0].gradePct);
  for (let i = 1; i < segments.length; i++) {
    const cls = classIndexFor(segments[i].gradePct);
    if (cls !== prevClass) boundaries.push(segments[i].kmStart);
    prevClass = cls;
  }

  // group consecutive "climbing" segments (>3% grade) into named climbs,
  // weighting the average grade by distance
  const climbs: Climb[] = [];
  let cur: { startKm: number; endKm: number; distM: number; gainM: number } | null = null;
  for (const s of segments) {
    if (s.gradePct > 3) {
      const distM = (s.kmEnd - s.kmStart) * 1000;
      const gainM = distM * (s.gradePct / 100);
      if (cur) {
        cur.endKm = s.kmEnd;
        cur.distM += distM;
        cur.gainM += gainM;
      } else {
        cur = { startKm: s.kmStart, endKm: s.kmEnd, distM, gainM };
      }
    } else if (cur) {
      climbs.push({ startKm: cur.startKm, endKm: cur.endKm, avgGradePct: (cur.gainM / cur.distM) * 100 });
      cur = null;
    }
  }
  if (cur) climbs.push({ startKm: cur.startKm, endKm: cur.endKm, avgGradePct: (cur.gainM / cur.distM) * 100 });

  let steepest = segments[0];
  for (const s of segments) if (Math.abs(s.gradePct) > Math.abs(steepest.gradePct)) steepest = s;
  const steepestKm = (steepest.kmStart + steepest.kmEnd) / 2;

  const climbText = climbs.length
    ? `${climbs.length} climb${climbs.length === 1 ? "" : "s"}: ${climbs
        .map((c) => `km ${c.startKm.toFixed(0)}–${c.endKm.toFixed(0)} avg ${Math.round(c.avgGradePct)}%`)
        .join(", ")}`
    : "no sustained climbs";

  const text = `total climb ${Math.round(totalClimbM)} m; ${climbText}; steepest ${Math.round(
    Math.abs(steepest.gradePct)
  )}% at km ${steepestKm.toFixed(1)}`;

  return { text, boundaries };
}

function findSegmentIndex(segments: Segment[], km: number): number {
  if (segments.length === 0) return -1;
  if (km <= segments[0].kmStart) return 0;
  const last = segments[segments.length - 1];
  if (km >= last.kmEnd) return segments.length - 1;
  for (let i = 0; i < segments.length; i++) {
    if (km >= segments[i].kmStart && km <= segments[i].kmEnd) return i;
  }
  return segments.length - 1;
}

function elevationAt(data: ElevationPoint[], km: number): number {
  if (data.length === 0) return 0;
  if (km <= data[0].km) return data[0].m;
  const last = data[data.length - 1];
  if (km >= last.km) return last.m;
  for (let i = 0; i < data.length - 1; i++) {
    const a = data[i];
    const b = data[i + 1];
    if (km >= a.km && km <= b.km) {
      const frac = b.km === a.km ? 0 : (km - a.km) / (b.km - a.km);
      return a.m + (b.m - a.m) * frac;
    }
  }
  return last.m;
}

export function HachureFall({
  data = DEFAULT_DATA,
  label = "Route elevation profile",
  className = "",
}: HachureFallProps) {
  const uid = useId().replace(/:/g, "");
  const rootRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const pathRefs = useRef<Array<SVGPathElement | null>>([]);
  const cursorGroupRef = useRef<SVGGElement>(null);
  const cursorDotRef = useRef<SVGCircleElement>(null);

  const segments = useMemo(() => buildSegments(data), [data]);
  const totalKm = data.length > 0 ? data[data.length - 1].km : 0;
  const outline = useMemo(() => profilePath(data, segments), [data, segments]);
  const summary = useMemo(() => summarizeRoute(data, segments), [data, segments]);

  const [active, setActive] = useState(false);
  const [announceKm, setAnnounceKm] = useState(0);

  const reducedRef = useRef(false);
  const targetKmRef = useRef(0);
  const springKmRef = useRef(0);
  const velRef = useRef(0);
  const activeSegRef = useRef(-1);
  const rafRef = useRef(0);
  const lastTRef = useRef(0);
  const lastAnnouncedRef = useRef(-1);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // reset any lifted path back to its resting geometry/colour
  const restoreSegment = useCallback((idx: number) => {
    const el = pathRefs.current[idx];
    const seg = segments[idx];
    if (!el || !seg) return;
    el.setAttribute("d", seg.dBase);
    el.setAttribute("stroke", "var(--ns-muted)");
  }, [segments]);

  const applyFrame = useCallback(() => {
    const km = clamp(springKmRef.current, 0, totalKm);
    const segIdx = findSegmentIndex(segments, km);

    if (segIdx !== activeSegRef.current) {
      if (activeSegRef.current >= 0) restoreSegment(activeSegRef.current);
      activeSegRef.current = segIdx;
      const el = pathRefs.current[segIdx];
      if (el) el.setAttribute("stroke", "var(--foreground)");
    }

    const seg = segments[segIdx];
    if (seg) {
      const el = pathRefs.current[segIdx];
      if (el && seg.ticks.length > 0) {
        const segFrac = seg.lenPx > 0 ? clamp((km - seg.kmStart) / Math.max(1e-6, seg.kmEnd - seg.kmStart), 0, 1) : 0;
        let d = "";
        for (const t of seg.ticks) {
          const distPx = seg.lenPx * Math.abs(t.frac - segFrac);
          const liftFactor = reducedRef.current ? 0 : clamp(1 - distPx / CURSOR_WINDOW_PX, 0, 1);
          const len = t.baseLen + CURSOR_LIFT_PX * liftFactor;
          d += tickPathD(t.bx, t.by, t.px, t.py, len);
        }
        el.setAttribute("d", d);
      }

      const p0 = seg.p0;
      const frac = clamp((km - seg.kmStart) / Math.max(1e-6, seg.kmEnd - seg.kmStart), 0, 1);
      const cx = p0.x + seg.dx * frac;
      const cy = p0.y + seg.dy * frac;
      if (cursorGroupRef.current) cursorGroupRef.current.setAttribute("transform", `translate(${cx.toFixed(2)},0)`);
      if (cursorDotRef.current) {
        cursorDotRef.current.setAttribute("cx", "0");
        cursorDotRef.current.setAttribute("cy", cy.toFixed(2));
      }
    }

    const rounded = Math.round(km * 10) / 10;
    if (rounded !== lastAnnouncedRef.current) {
      lastAnnouncedRef.current = rounded;
      setAnnounceKm(rounded);
    }
  }, [segments, totalKm, restoreSegment]);

  const stopLoop = useCallback(() => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = 0;
    }
  }, []);

  const startLoop = useCallback(() => {
    if (rafRef.current) return;
    lastTRef.current = 0;
    const tick = (now: number) => {
      const dt = lastTRef.current === 0 ? 1 / 60 : Math.min(0.05, (now - lastTRef.current) / 1000);
      lastTRef.current = now;

      if (reducedRef.current) {
        springKmRef.current = targetKmRef.current;
        velRef.current = 0;
      } else {
        // semi-implicit Euler on this spring's stiffness needs omega*h well
        // under 1 to stay stable (omega = sqrt(SPRING_K) ~= 65 rad/s, so a
        // single 60fps step of ~16.7ms already overshoots that badly and
        // diverges exponentially frame over frame). Substep at a fixed small
        // h so the 90ms settle time from SPRING_K is preserved without
        // blowing up the integrator.
        const H = 0.004;
        const steps = Math.max(1, Math.ceil(dt / H));
        const h = dt / steps;
        for (let i = 0; i < steps; i++) {
          const err = springKmRef.current - targetKmRef.current;
          const acc = -SPRING_K * err - SPRING_C * velRef.current;
          velRef.current += acc * h;
          springKmRef.current += velRef.current * h;
        }
        // hard guard: no retune of the constants above should ever be able
        // to hand a NaN/out-of-range value to setAttribute downstream.
        springKmRef.current = clamp(springKmRef.current, 0, totalKm);
      }

      applyFrame();
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  }, [applyFrame]);

  useEffect(() => stopLoop, [stopLoop]);

  const setTarget = useCallback(
    (km: number, immediate = false) => {
      const c = clamp(km, 0, totalKm);
      targetKmRef.current = c;
      if (immediate || reducedRef.current) {
        springKmRef.current = c;
        velRef.current = 0;
      }
      if (!active) setActive(true);
      startLoop();
    },
    [active, startLoop, totalKm]
  );

  const kmFromClientX = useCallback(
    (clientX: number) => {
      const rect = svgRef.current?.getBoundingClientRect();
      if (!rect || rect.width === 0) return targetKmRef.current;
      const frac = clamp((clientX - rect.left) / rect.width, 0, 1);
      return frac * totalKm;
    },
    [totalKm]
  );

  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    setTarget(kmFromClientX(e.clientX));
  };

  const onPointerLeave = () => {
    if (document.activeElement === rootRef.current) return;
    setActive(false);
    stopLoop();
    if (activeSegRef.current >= 0) {
      restoreSegment(activeSegRef.current);
      activeSegRef.current = -1;
    }
  };

  const onFocus = () => {
    setTarget(targetKmRef.current || 0, true);
  };

  const onBlur = () => {
    setActive(false);
    stopLoop();
    if (activeSegRef.current >= 0) {
      restoreSegment(activeSegRef.current);
      activeSegRef.current = -1;
    }
  };

  const stepSize = Math.max(0.1, totalKm / 200);

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const current = clamp(springKmRef.current, 0, totalKm);
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        e.preventDefault();
        setTarget(current + stepSize);
        break;
      case "ArrowLeft":
      case "ArrowDown":
        e.preventDefault();
        setTarget(current - stepSize);
        break;
      case "PageUp": {
        e.preventDefault();
        const next = summary.boundaries.find((b) => b > current + 1e-6);
        setTarget(next ?? totalKm);
        break;
      }
      case "PageDown": {
        e.preventDefault();
        const prev = [...summary.boundaries].reverse().find((b) => b < current - 1e-6);
        setTarget(prev ?? 0);
        break;
      }
      case "Home":
        e.preventDefault();
        setTarget(0);
        break;
      case "End":
        e.preventDefault();
        setTarget(totalKm);
        break;
      default:
        break;
    }
  };

  const elevNow = elevationAt(data, announceKm);
  const segNow = segments[findSegmentIndex(segments, announceKm)];
  const gradeNow = segNow ? segNow.gradePct : 0;
  const valueText = `km ${announceKm.toFixed(1)}, ${Math.round(elevNow)} m elevation, ${gradeWord(gradeNow)}`;
  const describeId = `hachure-fall-summary-${uid}`;

  return (
    <div className={`relative ${className}`}>
      <div
        ref={rootRef}
        data-hachure-fall-track=""
        role="slider"
        tabIndex={0}
        aria-orientation="horizontal"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={totalKm}
        aria-valuenow={Math.round(announceKm * 10) / 10}
        aria-valuetext={valueText}
        aria-describedby={describeId}
        className="relative w-full cursor-crosshair select-none rounded-[12px] border border-border bg-background px-2 pb-8 pt-2 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        onPointerMove={onPointerMove}
        onPointerLeave={onPointerLeave}
        onFocus={onFocus}
        onBlur={onBlur}
        onKeyDown={onKeyDown}
      >
        <svg
          ref={svgRef}
          viewBox={`0 0 ${VW} ${VH}`}
          className="block h-auto w-full"
          aria-hidden="true"
        >
          {/* the profile line itself — thin, subordinate to the hachures */}
          <path d={outline} fill="none" stroke="var(--border)" strokeWidth={1.25} />

          {segments.map((seg, i) => (
            <path
              key={seg.index}
              ref={(el) => {
                pathRefs.current[i] = el;
              }}
              d={seg.dBase}
              fill="none"
              stroke="var(--ns-muted)"
              strokeWidth={1}
              strokeLinecap="round"
            />
          ))}

          <g ref={cursorGroupRef} style={{ opacity: active ? 1 : 0, transition: active ? undefined : "opacity 120ms ease-out" }}>
            <line x1={0} y1={0} x2={0} y2={VH} stroke="var(--ns-accent)" strokeWidth={1} strokeDasharray="2 3" />
            <circle ref={cursorDotRef} r={2.75} fill="var(--ns-accent)" />
          </g>
        </svg>

        <div
          aria-hidden="true"
          className="pointer-events-none absolute bottom-1.5 left-2 font-mono text-[10px] tabular-nums text-ns-muted transition-opacity"
          style={{ opacity: active ? 1 : 0 }}
        >
          km {announceKm.toFixed(1)} · {Math.round(elevNow)} m · {gradeWord(gradeNow)}
        </div>

        <div
          aria-hidden="true"
          className="pointer-events-none absolute bottom-1.5 right-2 font-mono text-[10px] text-ns-muted"
        >
          1 stroke-height = 5% grade
        </div>
      </div>

      <p id={describeId} className="sr-only">
        {summary.text}
      </p>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ScrollIsland — a header that morphs between a full-width quiet nav bar (at
// page top) and a floating, centered pill (once scrolled), tracking a
// "dynamic island" reference. Everything that moves every frame — pill
// width/radius/padding/translateY, the section-label roll, the progress
// hairline width, the lift/border-brighten on hover — is written straight to
// refs' inline styles inside a single rAF loop; React state only holds
// discrete things (which section is active, open/closed banding, reduced
// motion) that change rarely and are fine to re-render on.
//
// Scroll math: a single continuous "openness" value in [0,1] (0 = compact
// pill, 1 = full bar) is derived from scrollY with a hysteresis band — it
// only starts closing past CLOSE_Y and only starts reopening once scrollY
// drops back under OPEN_Y, so resting exactly on a single pixel threshold
// can never flutter between states. A fast upward scroll (large negative
// scrollY delta inside one rAF tick) snaps openness toward 1 immediately
// and plays a brief overshoot (a scale pulse past 1 that eases back) rather
// than the normal lerped approach.
// ---------------------------------------------------------------------------

export interface ScrollIslandSection {
  id: string;
  label: string;
}

export interface ScrollIslandProps {
  /** brand text on the left */
  wordmark?: string;
  /** the tracked page sections */
  sections?: ScrollIslandSection[];
  /** id of the currently active section; the label rolls when this changes */
  activeId?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_SECTIONS: ScrollIslandSection[] = [
  { id: "intro", label: "Intro" },
  { id: "work", label: "Work" },
  { id: "process", label: "Process" },
  { id: "contact", label: "Contact" },
];

const CLOSE_Y = 72; // px scrolled before it starts compacting
const OPEN_Y = 40; // px scrolled below which it starts reopening (< CLOSE_Y = hysteresis band)
const LERP_RATE = 10; // 1/s — approach speed toward target openness
const FLICK_DELTA = -28; // px/frame upward delta that counts as a "fast flick"
const OVERSHOOT_MS = 260;

const PILL_W_PX = 300;
const BAR_RADIUS = 0;
const PILL_RADIUS = 999;
const BAR_PAD_X = 24;
const PILL_PAD_X = 18;
const BAR_H = 60;
const PILL_H = 44;
const PILL_TOP = 14;

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function clamp01(v: number) {
  return Math.min(1, Math.max(0, v));
}

export function ScrollIsland({
  wordmark = "ns-ui",
  sections = DEFAULT_SECTIONS,
  activeId,
  className = "",
}: ScrollIslandProps) {
  const pillRef = useRef<HTMLDivElement | null>(null);
  const barLinksRef = useRef<HTMLDivElement | null>(null);
  const labelTrackRef = useRef<HTMLSpanElement | null>(null);
  const hairlineRef = useRef<HTMLDivElement | null>(null);

  const [reduced, setReduced] = useState(false);
  const [internalActive, setInternalActive] = useState(sections[0]?.id);
  const [focusExpanded, setFocusExpanded] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [compact, setCompact] = useState(false); // discrete: drives reduced-motion + a11y state only

  const active = activeId ?? internalActive;
  const activeIndex = useMemo(
    () => Math.max(0, sections.findIndex((s) => s.id === active)),
    [sections, active]
  );

  // ---- reduced motion -------------------------------------------------
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // ---- section auto-detection (only when caller doesn't control it) --
  useEffect(() => {
    if (activeId !== undefined) return;
    const els = sections
      .map((s) => document.getElementById(s.id))
      .filter((el): el is HTMLElement => !!el);
    if (els.length === 0) return;
    const io = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) {
          const id = visible.target.id;
          setInternalActive(id);
        }
      },
      { rootMargin: "-40% 0px -50% 0px", threshold: [0, 0.25, 0.5, 0.75, 1] }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, [sections, activeId]);

  // ---- label vertical roll on section change --------------------------
  const prevLabelRef = useRef(sections[activeIndex]?.label ?? "");
  useEffect(() => {
    const label = sections[activeIndex]?.label ?? "";
    const track = labelTrackRef.current;
    if (!track) {
      prevLabelRef.current = label;
      return;
    }
    if (prevLabelRef.current === label) return;
    prevLabelRef.current = label;
    if (reduced) {
      track.textContent = label;
      return;
    }
    // roll: slide current out upward, swap text, slide in from below
    track.style.transition = "none";
    track.style.transform = "translateY(0%)";
    track.textContent = label;
    // force reflow so the "from" transform is committed before animating
    void track.offsetHeight;
    track.style.transform = "translateY(-100%)";
    requestAnimationFrame(() => {
      track.style.transition = "transform 260ms cubic-bezier(0.16,1,0.3,1)";
      track.style.transform = "translateY(0%)";
    });
  }, [activeIndex, sections, reduced]);

  // ---- rAF scroll-driven morph -----------------------------------------
  const opennessRef = useRef(1);
  const lastYRef = useRef(0);
  const overshootUntilRef = useRef(0);

  const applyFrame = useCallback(
    (openness: number, overshoot: number, expanded: boolean, lift: boolean) => {
      const pill = pillRef.current;
      const links = barLinksRef.current;
      const hairline = hairlineRef.current;
      if (!pill) return;

      const o = expanded ? 1 : openness;
      const width = lerp(PILL_W_PX, window.innerWidth, o);
      const widthCss = o > 0.985 ? "100%" : `${width}px`;
      const radius = lerp(PILL_RADIUS, BAR_RADIUS, o);
      const padX = lerp(PILL_PAD_X, BAR_PAD_X, o);
      const height = lerp(PILL_H, BAR_H, o);
      const top = lerp(PILL_TOP, 0, o);
      const scale = 1 + overshoot * 0.02;
      const liftPx = lift && o < 0.5 ? -1 : 0;

      pill.style.width = widthCss;
      pill.style.borderRadius = `${radius}px`;
      pill.style.paddingLeft = `${padX}px`;
      pill.style.paddingRight = `${padX}px`;
      pill.style.height = `${height}px`;
      pill.style.marginTop = `${top}px`;
      pill.style.transform = `translateY(${liftPx}px) scale(${scale})`;
      pill.style.borderColor = lift && o < 0.5 ? "var(--foreground)" : "var(--border)";

      // shares the same 0.5 threshold as the `compact` state (which drives
      // these links' aria-hidden/tabIndex) so they can never be focusable
      // while still invisible, or visible while still unreachable
      if (links) links.style.opacity = o > 0.5 ? String((o - 0.5) / 0.5) : "0";
      if (hairline) {
        const t = sections.length > 1 ? activeIndex / (sections.length - 1) : 0;
        hairline.style.width = `${clamp01(t) * 100}%`;
        hairline.style.opacity = o < 0.5 ? "1" : "0";
      }
    },
    [activeIndex, sections.length]
  );

  useEffect(() => {
    let raf = 0;
    let last = performance.now();

    if (reduced) {
      // discrete: fully open at top, fully compact once scrolled, plain
      // opacity crossfade handled via the CSS classes below — still apply
      // the two static states directly so it's correct on first paint.
      // focus-forced expansion must also flip the discrete `compact` state
      // (not just the visual frame) — it's what makes the links reachable
      // at all, not just visible
      const y = window.scrollY;
      const isCompact = !focusExpanded && y > CLOSE_Y;
      setCompact(isCompact);
      applyFrame(isCompact ? 0 : 1, 0, focusExpanded, false);
      const onScroll = () => {
        const c = !focusExpanded && window.scrollY > CLOSE_Y;
        setCompact((prev) => (prev === c ? prev : c));
        applyFrame(c ? 0 : 1, 0, focusExpanded, false);
      };
      window.addEventListener("scroll", onScroll, { passive: true });
      return () => window.removeEventListener("scroll", onScroll);
    }

    lastYRef.current = window.scrollY;

    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;

      const y = window.scrollY;
      const dy = y - lastYRef.current;
      lastYRef.current = y;

      // hysteresis banded target: only flips state at the far edge of the band
      let target = opennessRef.current > 0.5 ? (y > CLOSE_Y ? 0 : 1) : y < OPEN_Y ? 1 : 0;

      const fastFlick = dy < FLICK_DELTA;
      if (fastFlick) {
        target = 1;
        overshootUntilRef.current = now + OVERSHOOT_MS;
      }

      const inOvershoot = now < overshootUntilRef.current;
      const overshoot = inOvershoot
        ? Math.sin(((overshootUntilRef.current - now) / OVERSHOOT_MS) * Math.PI) * 0.6
        : 0;

      const rate = fastFlick ? LERP_RATE * 2.4 : LERP_RATE;
      opennessRef.current = lerp(opennessRef.current, target, 1 - Math.exp(-rate * dt));

      // focus-forced expansion must also flip the discrete `compact` state
      // (not just the visual frame) — it's what makes the links reachable
      // at all, not just visible
      const isCompact = !focusExpanded && opennessRef.current < 0.5;
      setCompact((prev) => (prev === isCompact ? prev : isCompact));

      applyFrame(opennessRef.current, overshoot, focusExpanded, hovered);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [reduced, focusExpanded, hovered, applyFrame]);

  // re-apply immediately on hover/focus toggles so it doesn't wait a frame
  useEffect(() => {
    if (reduced) {
      applyFrame(compact ? 0 : 1, 0, focusExpanded, hovered);
    }
  }, [hovered, focusExpanded, reduced, compact, applyFrame]);

  return (
    <header className={`ns-hsp-header fixed inset-x-0 top-0 z-40 flex justify-center ${className}`}>
      <div
        ref={pillRef}
        role="navigation"
        aria-label="Primary"
        tabIndex={-1}
        onFocus={() => setFocusExpanded(true)}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node)) setFocusExpanded(false);
        }}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        className={`relative flex items-center justify-between overflow-hidden border bg-background text-foreground transition-[background-color,border-color] duration-200 ${
          reduced ? "duration-150" : ""
        }`}
        style={{ borderColor: "var(--border)", willChange: "width, height, border-radius" }}
      >
        <a
          href="#top"
          className="shrink-0 whitespace-nowrap font-mono text-sm font-medium tracking-tight text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          {wordmark}
        </a>

        <div
          ref={barLinksRef}
          className="flex items-center gap-6 transition-opacity"
          aria-hidden={compact}
        >
          {sections.map((s) => (
            <a
              key={s.id}
              href={`#${s.id}`}
              aria-current={s.id === active ? "location" : undefined}
              tabIndex={compact ? -1 : 0}
              className={`whitespace-nowrap text-sm transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
                s.id === active ? "text-foreground" : "text-ns-muted hover:text-foreground"
              }`}
            >
              {s.label}
            </a>
          ))}
        </div>

        {/* compact-state active-section label with a 1-line vertical roll */}
        <div
          className="pointer-events-none absolute inset-0 flex items-center justify-center overflow-hidden"
          aria-hidden="true"
          style={{ opacity: compact ? 1 : 0, transition: "opacity 200ms" }}
        >
          <span className="relative block h-4 overflow-hidden font-mono text-xs uppercase tracking-wide">
            <span ref={labelTrackRef} className="block">
              {sections[activeIndex]?.label ?? ""}
            </span>
          </span>
        </div>

        {/* progress hairline along the pill's bottom edge — a div, never svg
            dasharray (see project wiki: pathLength + non-scaling-stroke is
            broken in Chromium for exactly this kind of straight indicator) */}
        <div
          className="absolute inset-x-0 bottom-0 h-px"
          aria-hidden="true"
          style={{ background: "var(--border)" }}
        >
          <div
            ref={hairlineRef}
            className="h-full"
            style={{ background: "var(--foreground)", width: "0%" }}
          />
        </div>
      </div>
    </header>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// StippleYear — a GitHub-style year activity calendar where intensity is
// STIPPLE DENSITY, not color: every day cell holds 0-8 tiny ink dots placed
// by a deterministic, date-seeded jitter (an engraving/print metaphor, pure
// var(--foreground) on var(--background)). Dot positions are generated once
// in NORMALIZED [0,1] space per date (`stippleUnits`) and only scaled to
// pixels at render time — the loupe renders the exact same normalized
// points at 2x, so it's a literal zoomed copy, not a re-roll.
//
// Every cell is a focusable role="button" (roving tabindex — one cell has
// tabIndex 0 at a time, arrow keys move which one) so the automatic
// hover/press/focus screenshot pass and the a11y audit exercise the same
// interaction keyboard users get. Hover or focus opens a fixed loupe panel
// plus a Geist Mono tooltip; the cell's own aria-label already carries the
// same fact in text for anyone not using either.
// ---------------------------------------------------------------------------

export interface StippleYearProps {
  /** Map of ISO date ("YYYY-MM-DD") to an activity count. */
  values?: Record<string, number>;
  /** Last day of the 371-day window. Defaults to today. */
  endDate?: Date;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const CELL = 16;
const GAP = 4;
const STEP = CELL + GAP;
const MARGIN = 1.9;
const MAX_DOTS = 8;
const DOT_R = 1.35;
const LOUPE_CELL = 68;
const LOUPE_MARGIN = 6;
const LOUPE_DOT_R = 3.2;
/** Fixed footprint of the side panel that holds the loupe — always reserved
 *  (even when nothing is hovered) so it never overlaps the grid's own cells
 *  and never shifts the component's box on hover. Wide enough for the
 *  longest realistic one-line caption ("20 contributions - Dec 25"). */
const LOUPE_PANEL_W = 172;
const LEFT_LABEL_W = 30;
const TOP_LABEL_H = 20;

/** Loupe ink-settle — every time a new cell is magnified into the loupe,
 *  its dots don't just appear: each one starts flung a short distance from
 *  its resting position (offset derived from the same per-dot mulberry32
 *  stream that placed it, so it's deterministic and replays identically for
 *  a given date, never Math.random()) and springs into place on an
 *  ease-out-expo curve, staggered a few ms apart per dot so the settle
 *  reads as ink landing on paper rather than one uniform pop. Kept well
 *  clear of the loupe's own 160ms zoom-in (LOUPE_SETTLE_MS is longer and
 *  starts from the same frame) so the two read as two distinct events, not
 *  one blurred bloom. */
const LOUPE_SETTLE_MS = 460;
const LOUPE_SETTLE_MAX = 22;
const LOUPE_SETTLE_STAGGER = 18;

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const WEEKDAY_LABELS = ["", "Mon", "", "Wed", "", "Fri", ""];

function startOfDay(d: Date): Date {
  const c = new Date(d);
  c.setHours(0, 0, 0, 0);
  return c;
}
function addDays(d: Date, n: number): Date {
  const c = new Date(d);
  c.setDate(c.getDate() + n);
  return c;
}
function isoDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function hashStr(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
function mulberry32(seed: number) {
  let a = seed;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function dotCountFor(value: number, max: number): number {
  if (value <= 0) return 0;
  return Math.min(MAX_DOTS, 1 + Math.round((value / max) * (MAX_DOTS - 1)));
}

/** Normalized [0,1] dot positions for a date, deterministic and reused at any scale. */
function stippleUnits(iso: string, count: number): { x: number; y: number }[] {
  const rng = mulberry32(hashStr(iso));
  return Array.from({ length: count }, () => ({ x: rng(), y: rng() }));
}

/** Per-dot starting offset for the loupe's ink-settle entrance — a distinct
 *  PRNG stream (own hash suffix) so it never correlates with the dot's own
 *  resting position, but is still fully deterministic for a given date. */
function loupeSettleOffsets(iso: string, count: number): { dx: number; dy: number }[] {
  const rng = mulberry32(hashStr(`${iso}:settle`));
  return Array.from({ length: count }, () => {
    const angle = rng() * Math.PI * 2;
    const dist = LOUPE_SETTLE_MAX * (0.4 + rng() * 0.6);
    return { dx: Math.cos(angle) * dist, dy: Math.sin(angle) * dist };
  });
}

interface DayCell {
  date: Date;
  iso: string;
  inRange: boolean;
  col: number;
  row: number;
}

export function StippleYear({ values = {}, endDate, className = "" }: StippleYearProps) {
  const today = useMemo(() => startOfDay(endDate ?? new Date()), [endDate]);
  const loupeClipId = useId();

  const { cells, weeks, monthLabels } = useMemo(() => {
    const roughStart = addDays(today, -364);
    const start = addDays(roughStart, -roughStart.getDay());
    const totalDays = Math.round((today.getTime() - start.getTime()) / 86400000) + 1;
    const weeksN = Math.ceil(totalDays / 7);
    const list: DayCell[] = [];
    for (let i = 0; i < weeksN * 7; i++) {
      const date = addDays(start, i);
      list.push({ date, iso: isoDate(date), inRange: date <= today, col: Math.floor(i / 7), row: i % 7 });
    }
    const labels: { col: number; text: string }[] = [];
    let lastMonth = -1;
    for (const c of list) {
      if (c.row === 0 && c.date.getDate() <= 7 && c.date.getMonth() !== lastMonth) {
        labels.push({ col: c.col, text: MONTHS[c.date.getMonth()]! });
        lastMonth = c.date.getMonth();
      }
    }
    return { cells: list, weeks: weeksN, monthLabels: labels };
  }, [today]);

  const maxValue = useMemo(
    () => Math.max(1, ...cells.filter((c) => c.inRange).map((c) => values[c.iso] ?? 0)),
    [cells, values]
  );

  const [activeIndex, setActiveIndex] = useState(() => {
    const idx = cells.findIndex((c) => c.inRange && c.iso === isoDate(today));
    return idx === -1 ? 0 : idx;
  });
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const cellRefs = useRef<(SVGRectElement | null)[]>([]);

  const reducedMotionRef = useRef(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedMotionRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  // Column/row-aware, not flat-index ±1/±7 — at a row boundary (top/bottom
  // of a week column) a flat index just wraps into the adjacent week's
  // opposite row, which reads as a diagonal jump instead of stopping.
  const focusCell = (col: number, row: number) => {
    if (row < 0 || row > 6 || col < 0 || col >= weeks) return;
    const next = col * 7 + row;
    if (!cells[next]?.inRange) return;
    setActiveIndex(next);
    cellRefs.current[next]?.focus();
  };

  const loupeIdx = hoverIndex;
  const loupeCell = loupeIdx !== null ? cells[loupeIdx] : null;
  const loupeValue = loupeCell ? (values[loupeCell.iso] ?? 0) : 0;
  const loupeUnits = loupeCell ? stippleUnits(loupeCell.iso, dotCountFor(loupeValue, maxValue)) : [];
  const loupeSettle = loupeCell ? loupeSettleOffsets(loupeCell.iso, loupeUnits.length) : [];

  const labelFor = (c: DayCell) => {
    const v = values[c.iso] ?? 0;
    const noun = v === 1 ? "contribution" : "contributions";
    return `${v} ${noun}, ${MONTHS[c.date.getMonth()]} ${c.date.getDate()}`;
  };

  const viewW = LEFT_LABEL_W + weeks * STEP;
  const viewH = TOP_LABEL_H + 7 * STEP;

  return (
    <div className={`ns-sy-grid inline-flex items-start gap-3 ${className}`}>
      <style>{CSS}</style>
      <svg
        className="ns-sy-canvas"
        viewBox={`0 0 ${viewW} ${viewH}`}
        width={viewW}
        style={{ maxWidth: "100%" }}
        focusable="false"
      >
        <g aria-hidden="true" className="font-mono" style={{ fontSize: 8.5 }}>
          {monthLabels.map((m, i) => (
            <text key={i} x={LEFT_LABEL_W + m.col * STEP} y={TOP_LABEL_H - 4} fill="var(--ns-muted)">
              {m.text}
            </text>
          ))}
          {WEEKDAY_LABELS.map((label, row) =>
            label ? (
              <text key={row} x={0} y={TOP_LABEL_H + row * STEP + CELL - 2} fill="var(--ns-muted)">
                {label}
              </text>
            ) : null
          )}
        </g>

        {cells.map((c, i) => {
          if (!c.inRange) return null;
          const value = values[c.iso] ?? 0;
          const count = dotCountFor(value, maxValue);
          const units = stippleUnits(c.iso, count);
          const x = LEFT_LABEL_W + c.col * STEP;
          const y = TOP_LABEL_H + c.row * STEP;
          const isActive = i === activeIndex;
          const isHovered = i === hoverIndex;
          return (
            <g key={c.iso}>
              <rect
                ref={(el) => {
                  cellRefs.current[i] = el;
                }}
                role="button"
                tabIndex={isActive ? 0 : -1}
                aria-label={labelFor(c)}
                x={x}
                y={y}
                width={CELL}
                height={CELL}
                rx={2}
                fill="transparent"
                stroke={isHovered ? "var(--foreground)" : "var(--border)"}
                strokeWidth={isHovered ? 1.25 : 0.9}
                strokeOpacity={isHovered ? 0.7 : 0.6}
                className="ns-sy-cell"
                style={{ outlineOffset: 1 }}
                onPointerEnter={() => setHoverIndex(i)}
                onPointerLeave={() => setHoverIndex((cur) => (cur === i ? null : cur))}
                onFocus={() => {
                  setActiveIndex(i);
                  setHoverIndex(i);
                }}
                onBlur={() => setHoverIndex((cur) => (cur === i ? null : cur))}
                onKeyDown={(e) => {
                  if (e.key === "ArrowUp") {
                    e.preventDefault();
                    focusCell(c.col, c.row - 1);
                  } else if (e.key === "ArrowDown") {
                    e.preventDefault();
                    focusCell(c.col, c.row + 1);
                  } else if (e.key === "ArrowLeft") {
                    e.preventDefault();
                    focusCell(c.col - 1, c.row);
                  } else if (e.key === "ArrowRight") {
                    e.preventDefault();
                    focusCell(c.col + 1, c.row);
                  }
                }}
              />
              <g className="ns-sy-dots">
                {units.map((u, k) => (
                  <circle
                    key={k}
                    cx={x + MARGIN + u.x * (CELL - 2 * MARGIN)}
                    cy={y + MARGIN + u.y * (CELL - 2 * MARGIN)}
                    r={DOT_R}
                    fill="var(--foreground)"
                    aria-hidden="true"
                  />
                ))}
              </g>
            </g>
          );
        })}
      </svg>

      {/* Fixed-footprint side panel, always rendered so the component's own
          box never resizes on hover — only its contents toggle. It sits
          beside the grid (not layered on top), so it can never occlude the
          cell that's actually being hovered. */}
      <div
        className="pointer-events-none flex shrink-0 flex-col items-center justify-center gap-1 rounded-[6px] border border-border bg-background p-1.5 shadow-sm"
        style={{ width: LOUPE_PANEL_W, height: viewH, visibility: loupeCell ? "visible" : "hidden" }}
      >
        {loupeCell && (
          <>
            <svg
              key={loupeCell.iso}
              viewBox={`0 0 ${LOUPE_CELL} ${LOUPE_CELL}`}
              width={LOUPE_CELL}
              height={LOUPE_CELL}
              className="ns-sy-loupe"
              aria-hidden="true"
            >
              <defs>
                <clipPath id={loupeClipId}>
                  <rect x={1} y={1} width={LOUPE_CELL - 2} height={LOUPE_CELL - 2} rx={4} />
                </clipPath>
              </defs>
              <rect x={0} y={0} width={LOUPE_CELL} height={LOUPE_CELL} rx={4} fill="var(--background)" stroke="var(--border)" strokeWidth={1} />
              <g clipPath={`url(#${loupeClipId})`}>
                {loupeUnits.map((u, k) => {
                  const settle = loupeSettle[k] ?? { dx: 0, dy: 0 };
                  return (
                    <circle
                      key={k}
                      cx={LOUPE_MARGIN + u.x * (LOUPE_CELL - 2 * LOUPE_MARGIN)}
                      cy={LOUPE_MARGIN + u.y * (LOUPE_CELL - 2 * LOUPE_MARGIN)}
                      r={LOUPE_DOT_R}
                      fill="var(--foreground)"
                      className="ns-sy-loupe-dot"
                      style={
                        {
                          "--sx": `${settle.dx.toFixed(2)}px`,
                          "--sy": `${settle.dy.toFixed(2)}px`,
                          animationDelay: `${k * LOUPE_SETTLE_STAGGER}ms`,
                        } as CSSProperties
                      }
                    />
                  );
                })}
              </g>
            </svg>
            <span className="whitespace-nowrap font-mono text-[10px] text-foreground">
              {loupeValue} {loupeValue === 1 ? "contribution" : "contributions"} - {MONTHS[loupeCell.date.getMonth()]}{" "}
              {loupeCell.date.getDate()}
            </span>
          </>
        )}
      </div>
    </div>
  );
}

