"use client";

import { useEffect, useRef, useState, type InputHTMLAttributes } from "react";

// ---------------------------------------------------------------------------
// deterministic 2-octave value noise — no deps, stable across frames
// ---------------------------------------------------------------------------
function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.65 * vnoise(x, y) + 0.35 * vnoise(x * 2.1 + 19.7, y * 2.1 + 7.3);
}

// cubic-bezier(0.22, 1, 0.36, 1) solved via Newton–Raphson
function makeBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 6; i++) {
      const s = slopeX(t);
      if (Math.abs(s) < 1e-6) break;
      t -= (sampleX(t) - x) / s;
    }
    return sampleY(Math.min(1, Math.max(0, t)));
  };
}
const glideEase = makeBezier(0.22, 1, 0.36, 1);

const TAU = Math.PI * 2;
const PAD = 24; // canvas overhang — worst-case displacement (6+8+~3px) fits
const POINTS = 96;
// the brief's noise2(s*3, ·) frequency (3 noise units per lap) sampled on a
// closed ring so the membrane has no seam where s wraps: circumference
// 2πR = 3 → R = 3/2π
const NOISE_R = 3 / TAU;
const SIGMA = 0.06; // gaussian pulse width, normalized perimeter
const PULSE_SPEED = 1.2; // perimeters per second
const PULSE_TAU = 0.6; // seconds
const TWO_SIGMA2 = 2 * SIGMA * SIGMA;

// ---------------------------------------------------------------------------
// RespireField — a real, fully native <input> under a decoration-only canvas
// membrane: a 96-point noise-displaced loop that breathes on idle, dilates on
// focus, sends a peristaltic pulse around the loop from the caret on each
// keystroke, constricts and quivers on error, and exhales once on valid
// submit. Direct-DOM rAF is the sole writer; the loop sleeps when blurred and
// every transient has settled below 0.05px.
// ---------------------------------------------------------------------------
export function RespireField({
  error = false,
  exhaleKey = 0,
  className = "",
  ...inputProps
}: {
  /** constricts the membrane -3px, quivers once, blends stroke toward red */
  error?: boolean;
  /** bump after a valid submit to trigger the single 8px exhale */
  exhaleKey?: number;
  /** classes for the wrapper; input styling is internal */
  className?: string;
} & Omit<InputHTMLAttributes<HTMLInputElement>, "className">) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const errorRef = useRef(false);
  const quiverStartRef = useRef(-1);
  const exhaleStartRef = useRef(-1);
  const prevErrRef = useRef(false);
  const prevExRef = useRef(exhaleKey);
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    setReduced(window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  }, []);

  useEffect(() => {
    if (reduced) return;
    const wrap = wrapRef.current;
    const input = inputRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !input || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const measure = document.createElement("canvas").getContext("2d");

    // geometry — rebuilt on resize, read every frame
    let w = 0;
    let h = 0;
    let dpr = 1;
    let radius = 6;
    let font = "";
    let padLeft = 14;
    let L = 1; // perimeter length in px
    const px = new Float32Array(POINTS);
    const py = new Float32Array(POINTS);
    const nx = new Float32Array(POINTS);
    const ny = new Float32Array(POINTS);
    const dx = new Float32Array(POINTS); // displaced ring, rebuilt every frame
    const dy = new Float32Array(POINTS);

    // stroke endpoints resolved from CSS tokens (muted → foreground, error),
    // re-resolved when the theme class on <html> flips
    let mutC: [number, number, number] = [143, 143, 143];
    let fgC: [number, number, number] = [237, 237, 237];
    let errC: [number, number, number] = [234, 0, 29];
    const parseColor = (
      v: string,
      fb: [number, number, number]
    ): [number, number, number] => {
      if (!measure || !v) return fb;
      measure.fillStyle = "#000000";
      measure.fillStyle = v.trim();
      const m = /^#([0-9a-f]{6})$/.exec(measure.fillStyle);
      if (!m || !m[1]) return fb;
      const n = parseInt(m[1], 16);
      return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
    };
    const deriveColors = () => {
      const root = getComputedStyle(document.documentElement);
      mutC = parseColor(root.getPropertyValue("--ns-muted"), [143, 143, 143]);
      fgC = parseColor(root.getPropertyValue("--foreground"), [237, 237, 237]);
      errC = parseColor(root.getPropertyValue("--error"), [234, 0, 29]);
    };
    deriveColors();

    // s=0 at the left end of the top edge, clockwise: top → TR arc → right
    // → BR arc → bottom → BL arc → left → TL arc. Positions + outward normals.
    const rebuild = () => {
      const r = Math.min(6, w / 2, h / 2);
      radius = r;
      const sw = w - 2 * r;
      const sh = h - 2 * r;
      const arc = (Math.PI * r) / 2;
      L = Math.max(1, 2 * sw + 2 * sh + 4 * arc);
      const seg = [sw, arc, sh, arc, sw, arc, sh, arc];
      for (let i = 0; i < POINTS; i++) {
        let d = (i / POINTS) * L;
        let k = 0;
        while (k < 7 && d > (seg[k] ?? 0)) {
          d -= seg[k] ?? 0;
          k++;
        }
        let x = 0;
        let y = 0;
        let ox = 0;
        let oy = 0;
        switch (k) {
          case 0:
            x = r + d;
            ox = 0;
            oy = -1;
            break;
          case 1: {
            const a = -Math.PI / 2 + d / r;
            x = w - r + r * Math.cos(a);
            y = r + r * Math.sin(a);
            ox = Math.cos(a);
            oy = Math.sin(a);
            break;
          }
          case 2:
            x = w;
            y = r + d;
            ox = 1;
            break;
          case 3: {
            const a = d / r;
            x = w - r + r * Math.cos(a);
            y = h - r + r * Math.sin(a);
            ox = Math.cos(a);
            oy = Math.sin(a);
            break;
          }
          case 4:
            x = w - r - d;
            y = h;
            oy = 1;
            break;
          case 5: {
            const a = Math.PI / 2 + d / r;
            x = r + r * Math.cos(a);
            y = h - r + r * Math.sin(a);
            ox = Math.cos(a);
            oy = Math.sin(a);
            break;
          }
          case 6:
            x = 0;
            y = h - r - d;
            ox = -1;
            break;
          default: {
            const a = Math.PI + d / r;
            x = r + r * Math.cos(a);
            y = r + r * Math.sin(a);
            ox = Math.cos(a);
            oy = Math.sin(a);
            break;
          }
        }
        px[i] = x + PAD;
        py[i] = y + PAD;
        nx[i] = ox;
        ny[i] = oy;
      }
    };

    const resize = () => {
      const rect = wrap.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round((w + PAD * 2) * dpr));
      canvas.height = Math.max(1, Math.round((h + PAD * 2) * dpr));
      // a canvas is a replaced element: absolute + inset does NOT stretch it,
      // it lays out at its intrinsic (buffer) size — dpr× too big. Pin the
      // CSS size explicitly so buffer*1/dpr === CSS px and the membrane hugs
      // the field instead of rendering as a giant dpr-scaled polygon.
      canvas.style.width = `${w + PAD * 2}px`;
      canvas.style.height = `${h + PAD * 2}px`;
      const cs = getComputedStyle(input);
      font = cs.font || `${cs.fontSize} ${cs.fontFamily}`;
      padLeft = parseFloat(cs.paddingLeft) || 0;
      rebuild();
    };
    resize();

    // hot-path state — locals only, never React state
    let raf = 0;
    let last = 0;
    let focused = document.activeElement === input;
    let fp = focused ? 1 : 0; // focus progress 0..1 (offset, breath, stroke)
    let focusFrom = fp;
    let focusTo = fp;
    let focusStart = -1;
    let errMix = 0;
    const pulses: { s: number; t: number }[] = [];

    // caret x → normalized position on the top-edge run of the perimeter
    const caretS = () => {
      if (!measure) return 0.05;
      let caret = input.value.length;
      try {
        const sel = input.selectionStart;
        if (sel != null) caret = sel;
      } catch {
        // email/number inputs refuse the selection API — caret ≈ end of value
      }
      measure.font = font;
      const tx =
        padLeft +
        measure.measureText(input.value.slice(0, caret)).width -
        input.scrollLeft;
      const d = Math.min(
        Math.max(tx - radius, 0),
        Math.max(1, w - 2 * radius)
      );
      return d / L;
    };

    const loop = (now: number) => {
      const t = now / 1000;
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      // focus dilation: 0 → +6px over 350ms on the glide bezier, reversible
      if (focusStart >= 0) {
        const q = (now - focusStart) / 350;
        if (q >= 1) {
          fp = focusTo;
          focusStart = -1;
        } else {
          fp = focusFrom + (focusTo - focusFrom) * glideEase(q);
        }
      }

      // error blend eases toward its target, then snaps so sleep can trigger
      const errTarget = errorRef.current ? 1 : 0;
      errMix += (errTarget - errMix) * (1 - Math.exp(-dt * 12));
      if (Math.abs(errMix - errTarget) < 0.01) errMix = errTarget;

      // quiver: 14Hz, 1.2px, fading out over its 500ms window
      let quiver = 0;
      const qs = quiverStartRef.current;
      if (qs >= 0) {
        const age = now - qs;
        if (age >= 500) quiverStartRef.current = -1;
        else quiver = Math.sin(TAU * 14 * (age / 1000)) * 1.2 * (1 - age / 500);
      }

      // exhale: amplitude spikes +8px, decays over 700ms ease-out (cubic)
      let exhale = 0;
      const es = exhaleStartRef.current;
      if (es >= 0) {
        const p = (now - es) / 700;
        if (p >= 1) exhaleStartRef.current = -1;
        else {
          const e = 1 - p;
          exhale = 8 * e * e * e;
        }
      }

      // prune dead pulses (5px * e^-2.6/0.6 ≈ 0.06px — under threshold)
      for (let j = pulses.length - 1; j >= 0; j--) {
        const pu = pulses[j];
        if (!pu || now - pu.t > 2600) pulses.splice(j, 1);
      }

      const base = 6 * fp - 3 * errMix + quiver;
      // idle breath 1.5px → 2.5px focused, on a 4.5s sine period; the sine
      // never fully deflates the noise so the membrane always reads alive
      const breathAmp =
        (1.5 + 1.0 * fp) * (0.6 + 0.4 * Math.sin((TAU * t) / 4.5));

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w + PAD * 2, h + PAD * 2);
      for (let i = 0; i < POINTS; i++) {
        const s = i / POINTS;
        const n = noise2(
          NOISE_R * Math.cos(s * TAU) + 7.3 + t * 0.15,
          NOISE_R * Math.sin(s * TAU) + 3.1 + t * 0.12
        );
        let disp = base + n * (breathAmp + exhale);
        // peristaltic pulses: two gaussian wavefronts leave the caret and
        // travel opposite ways around the loop at 1.2 perimeters/s
        for (const pu of pulses) {
          const age = (now - pu.t) / 1000;
          const amp = 5 * Math.exp(-age / PULSE_TAU);
          const travel = PULSE_SPEED * age;
          let d1 = Math.abs(s - ((pu.s + travel) % 1));
          d1 = Math.min(d1, 1 - d1);
          let d2 = Math.abs(s - ((((pu.s - travel) % 1) + 1) % 1));
          d2 = Math.min(d2, 1 - d2);
          disp +=
            amp *
            (Math.exp(-(d1 * d1) / TWO_SIGMA2) +
              Math.exp(-(d2 * d2) / TWO_SIGMA2));
        }
        // hard ceiling: transients can momentarily stack — never leave the
        // canvas overhang, so the ring always hugs the field
        if (disp > PAD - 1) disp = PAD - 1;
        dx[i] = (px[i] ?? 0) + (nx[i] ?? 0) * disp;
        dy[i] = (py[i] ?? 0) + (ny[i] ?? 0) * disp;
      }
      // closed Catmull-Rom spline through the displaced ring (bezier form,
      // tangents (p2-p0)/6) — 96 linear segments leave each 6px corner arc
      // with ~1 sample and read as sharp angles; the spline keeps it round
      ctx.beginPath();
      ctx.moveTo(dx[0] ?? 0, dy[0] ?? 0);
      for (let i = 0; i < POINTS; i++) {
        const p0 = (i + POINTS - 1) % POINTS;
        const p2 = (i + 1) % POINTS;
        const p3 = (i + 2) % POINTS;
        ctx.bezierCurveTo(
          (dx[i] ?? 0) + ((dx[p2] ?? 0) - (dx[p0] ?? 0)) / 6,
          (dy[i] ?? 0) + ((dy[p2] ?? 0) - (dy[p0] ?? 0)) / 6,
          (dx[p2] ?? 0) - ((dx[p3] ?? 0) - (dx[i] ?? 0)) / 6,
          (dy[p2] ?? 0) - ((dy[p3] ?? 0) - (dy[i] ?? 0)) / 6,
          dx[p2] ?? 0,
          dy[p2] ?? 0
        );
      }
      ctx.closePath();
      // stroke: muted token blurred → foreground token focused, blended
      // toward the error token at 0.6 alpha while error holds (status only)
      const cr0 = mutC[0] + (fgC[0] - mutC[0]) * fp;
      const cg0 = mutC[1] + (fgC[1] - mutC[1]) * fp;
      const cb0 = mutC[2] + (fgC[2] - mutC[2]) * fp;
      const cr = Math.round(cr0 + (errC[0] - cr0) * errMix);
      const cg = Math.round(cg0 + (errC[1] - cg0) * errMix);
      const cb = Math.round(cb0 + (errC[2] - cb0) * errMix);
      ctx.strokeStyle = `rgba(${cr},${cg},${cb},${1 - 0.4 * errMix})`;
      ctx.lineWidth = 1;
      ctx.lineJoin = "round";
      ctx.stroke();

      // sleep: blurred and every transient fully settled (< 0.05px) — the
      // idle breath freezes at its current phase until the next wake
      const settled =
        !focused &&
        focusStart < 0 &&
        fp === 0 &&
        pulses.length === 0 &&
        errMix === 0 &&
        !errorRef.current &&
        quiverStartRef.current < 0 &&
        exhaleStartRef.current < 0;
      if (settled) {
        raf = 0;
        last = 0;
        return;
      }
      raf = requestAnimationFrame(loop);
    };

    let onscreen = true;
    const wake = () => {
      if (onscreen && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    wakeRef.current = wake;
    wake(); // first paint; settles immediately if nothing is alive

    const onFocus = () => {
      focused = true;
      focusFrom = fp;
      focusTo = 1;
      focusStart = performance.now();
      wake();
    };
    const onBlur = () => {
      focused = false;
      focusFrom = fp;
      focusTo = 0;
      focusStart = performance.now();
      wake();
    };
    const onInput = () => {
      pulses.push({ s: caretS(), t: performance.now() });
      if (pulses.length > 24) pulses.shift();
      wake();
    };
    input.addEventListener("focus", onFocus);
    input.addEventListener("blur", onBlur);
    input.addEventListener("input", onInput);
    const ro = new ResizeObserver(() => {
      resize();
      wake();
    });
    ro.observe(wrap);
    // theme flip (class change on <html>) → re-derive stroke tokens + repaint
    const mo = new MutationObserver(() => {
      deriveColors();
      wake();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    // offscreen → park the rAF loop; back onscreen → repaint and resume
    const io = new IntersectionObserver((entries) => {
      onscreen = entries[entries.length - 1]?.isIntersecting ?? true;
      if (!onscreen && raf) {
        cancelAnimationFrame(raf);
        raf = 0;
        last = 0;
      } else if (onscreen) {
        wake();
      }
    });
    io.observe(wrap);

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      input.removeEventListener("focus", onFocus);
      input.removeEventListener("blur", onBlur);
      input.removeEventListener("input", onInput);
    };
  }, [reduced]);

  // error is a prop, not hot-path state: refs carry it into the loop
  useEffect(() => {
    errorRef.current = error;
    if (error && !prevErrRef.current) {
      quiverStartRef.current = performance.now();
    }
    prevErrRef.current = error;
    wakeRef.current?.();
  }, [error]);

  useEffect(() => {
    if (exhaleKey === prevExRef.current) return;
    prevExRef.current = exhaleKey;
    exhaleStartRef.current = performance.now();
    wakeRef.current?.();
  }, [exhaleKey]);

  return (
    <div ref={wrapRef} className={`relative ${className}`}>
      <input
        ref={inputRef}
        {...inputProps}
        aria-invalid={error}
        className={
          reduced
            ? // reduced motion: canvas hidden, standard border + default ring;
              // error still visible via the border (canvas quiver is gone)
              `w-full rounded-sm border bg-surface px-3.5 py-2.5 text-sm text-foreground placeholder:text-ns-muted/60 ${
                error ? "border-[#ea001d]" : "border-border"
              }`
            : "w-full rounded-sm border border-transparent bg-surface px-3.5 py-2.5 text-sm text-foreground outline-none placeholder:text-ns-muted/60"
        }
      />
      {!reduced && (
        <canvas
          ref={canvasRef}
          aria-hidden
          className="pointer-events-none absolute"
          style={{ inset: -PAD }}
        />
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// JacquardCardChain — an ambient status/activity strip modelled on the
// Jacquard loom's control mechanism, not a spinner or an indeterminate bar.
// A chain of punched cards, laced end to end into a loop, feeds over a
// rotating cylinder that presses each card against a bank of spring-loaded
// needles: where the card has a hole, its needle passes through and the
// corresponding hook stays engaged; where the card is solid, the needle is
// pushed back and its hook disengages. The chain is a literal physical
// program that loops forever, repeating (in the real machine) as long as
// the loom runs.
//
// This deliberately does NOT render as a static hole/patch data grid (that
// territory belongs to punch-patch's permissions matrix) — the load-bearing
// part here is the CHAIN IN MOTION: cards continuously advance past a fixed
// read gate, a needle bank ripples to the new card's pattern, holds, then
// the next card slides in. Real jacquard read rates (100-1000 picks/min)
// sit at or above the 60Hz paint rate, so per the round-9 legibility rule
// the whole read-and-settle cycle is decoupled to one legible event every
// 900ms rather than animated 1:1: a 16-needle-wide ripple resolves over
// ~160ms (staggered ~4ms/needle so it reads as a wave, not a snap), holds
// for the remainder of the card's dwell, then a 220ms card slide gives a
// clear departure/arrival before the next read begins — never a blink.
//
// Card patterns are generated by a small integer hash keyed on (needle
// index, card index) rather than Math.random(), so the sequence is
// deterministic and never literally repeats card-to-card while staying
// stable across re-renders and reduced-motion freezes.
//
// Card body is drawn with a low-alpha --ns-muted fill standing in for card
// stock (never a --border fill — --border is used only as the thin outline
// stroke and the fixed read-gate guide line, its correct use as a separator
// token) with holes cut through to solid --background so the punched
// pattern reads as negative space rather than an inked colour, in both
// themes. Needles: extended (hole present) draws at --foreground, retracted
// (no hole) at --ns-muted, a shorter, lower-contrast peg. No --ns-accent
// anywhere in the mechanism — this is ambient, not interaction chrome.
// ---------------------------------------------------------------------------

export interface JacquardCardChainProps {
  /** card heading */
  title?: string;
  /** card body copy */
  description?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
}

const CARD_MS = 900; // one full card read-and-settle cycle
const RIPPLE_MS = 160; // window in which the needle bank resolves to the new pattern
const SLIDE_MS = 220; // card-to-card slide transition (departure + arrival)
const HOLD_END_MS = CARD_MS - SLIDE_MS; // 680 — hold ends, next card's slide begins
const NEEDLE_STAGGER_MS = 4; // per-needle start delay across the bank
const NEEDLE_TRAVEL_MS = 100; // one needle's own travel+settle duration

// Reduced motion freezes mid-hold (not mid-ripple, not mid-slide) on a card
// with a roughly mixed pattern — the most structured single frame.
const FREEZE_PHASE = "CARD_READ_HOLD";
const FREEZE_CARD_INDEX = 2;
const FREEZE_LOCAL_T = 400; // inside the 160-680ms hold window

function easeOutBack(t: number): number {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  const x = t - 1;
  return 1 + c3 * x * x * x + c1 * x * x;
}

function easeOutCubic(t: number): number {
  const x = 1 - t;
  return 1 - x * x * x;
}

function clamp01(v: number): number {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

// deterministic pseudo-random bit for (needle index i, card index k) —
// stable forever, never repeats identically across nearby card indices.
function patternBit(i: number, k: number): 0 | 1 {
  let h = (i * 2654435761 + k * 40503 + 12345) >>> 0;
  h = Math.imul(h ^ (h >>> 15), h | 1);
  h ^= h + Math.imul(h ^ (h >>> 7), h | 61);
  h = (h ^ (h >>> 14)) >>> 0;
  return h % 100 < 50 ? 1 : 0;
}

export function JacquardCardChain({
  title = "Weaving pattern",
  description = "A chain of punched cards feeds past a needle bank, one read every beat — the program loops forever.",
  className = "",
  style,
}: JacquardCardChainProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    let bg = "#0a0a0a";
    let fg = "#ededed";
    let muted = "#8f8f8f";
    let border = "#2e2e2e";
    const deriveColors = () => {
      const cs = getComputedStyle(document.documentElement);
      bg = cs.getPropertyValue("--background").trim() || bg;
      fg = cs.getPropertyValue("--foreground").trim() || fg;
      muted = cs.getPropertyValue("--ns-muted").trim() || muted;
      border = cs.getPropertyValue("--border").trim() || border;
    };
    deriveColors();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let visible = true;
    let raf = 0;
    let startAt = 0; // performance.now() at first paint of this mount

    const drawFrame = (elapsedMs: number) => {
      if (w <= 0 || h <= 0) return;

      // mechanism occupies the lower ~58% of the card so it never collides
      // with the heading/caption text stacked in the top padding above it.
      const visualTop = h * 0.42;
      const needleZoneH = h * 0.34; // vertical room the needle bank travels within
      const needleBaseY = visualTop + needleZoneH; // baseline needles rise from
      const chainTop = needleBaseY + h * 0.06;
      const chainH = h * 0.18;
      const cardH = chainH * 0.9;
      const readGateX = w * 0.42;
      const cardW = Math.max(24, w * 0.34);

      const needleCount = Math.max(12, Math.min(20, Math.round(cardW / 9)));
      const pitch = cardW / (needleCount + 1);
      const needleStartX = readGateX - ((needleCount - 1) * pitch) / 2;
      const extendedLen = needleZoneH * 0.85;
      const retractedLen = needleZoneH * 0.38;

      const cardIndex = Math.floor(elapsedMs / CARD_MS);
      const localT = elapsedMs - cardIndex * CARD_MS;
      const prevPatternIndex = cardIndex - 1;
      const currPatternIndex = cardIndex;

      const slideT =
        localT < HOLD_END_MS ? 0 : easeOutCubic((localT - HOLD_END_MS) / SLIDE_MS);

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      // -- read-gate guide line: --border is a separator token, correct use --
      ctx.strokeStyle = border;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(readGateX, needleBaseY - extendedLen - 4);
      ctx.lineTo(readGateX, chainTop + chainH);
      ctx.stroke();

      // -- card chain, clipped to its lane so cards entering/leaving the
      //    canvas edges are simply cropped by the window, no fade needed --
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, chainTop, w, chainH);
      ctx.clip();

      for (let k = cardIndex - 1; k <= cardIndex + 2; k++) {
        const posUnits = k - cardIndex - slideT;
        const centerX = readGateX + posUnits * cardW;
        if (centerX < -cardW || centerX > w + cardW) continue;

        const left = centerX - cardW / 2 + 2;
        const right = centerX + cardW / 2 - 2;
        const top = chainTop + (chainH - cardH) / 2;

        ctx.globalAlpha = 0.35;
        ctx.fillStyle = muted;
        ctx.fillRect(left, top, right - left, cardH);
        ctx.globalAlpha = 1;

        ctx.strokeStyle = border;
        ctx.lineWidth = 1;
        ctx.strokeRect(left + 0.5, top + 0.5, right - left - 1, cardH - 1);

        const holeR = Math.max(1.5, pitch * 0.26);
        for (let i = 0; i < needleCount; i++) {
          if (patternBit(i, k) !== 1) continue;
          const hx = needleStartX + i * pitch;
          if (hx < left + holeR || hx > right - holeR) continue;
          ctx.beginPath();
          ctx.fillStyle = bg;
          ctx.arc(hx, top + cardH / 2, holeR, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.restore();

      // -- needle bank: ripple from the previous card's pattern to the
      //    current one, staggered per needle, then hold --
      for (let i = 0; i < needleCount; i++) {
        const startDelay = i * NEEDLE_STAGGER_MS;
        const needleLocalT = localT - startDelay;
        let progress: number;
        if (needleLocalT <= 0) progress = 0;
        else if (needleLocalT >= NEEDLE_TRAVEL_MS) progress = 1;
        else progress = easeOutBack(clamp01(needleLocalT / NEEDLE_TRAVEL_MS));

        const prevBit = patternBit(i, prevPatternIndex);
        const currBit = patternBit(i, currPatternIndex);
        const prevLen = prevBit === 1 ? extendedLen : retractedLen;
        const currLen = currBit === 1 ? extendedLen : retractedLen;
        const len = prevLen + (currLen - prevLen) * clamp01(progress);
        const extended = len > (extendedLen + retractedLen) / 2;

        const nx = needleStartX + i * pitch;
        ctx.strokeStyle = extended ? fg : muted;
        ctx.lineWidth = extended ? 2 : 1.5;
        ctx.beginPath();
        ctx.moveTo(nx, needleBaseY);
        ctx.lineTo(nx, needleBaseY - Math.max(retractedLen * 0.6, len));
        ctx.stroke();
      }
    };

    const loop = (now: number) => {
      if (startAt === 0) startAt = now;
      drawFrame(now - startAt);
      if (!reduced && visible) raf = requestAnimationFrame(loop);
      else raf = 0;
    };
    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) return;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));

      if (reduced) {
        drawFrame(FREEZE_CARD_INDEX * CARD_MS + FREEZE_LOCAL_T);
      } else {
        drawFrame(startAt === 0 ? 0 : performance.now() - startAt);
      }
    };

    resize();
    if (!reduced) wake();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
      else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    const mo = new MutationObserver(() => {
      deriveColors();
      if (reduced) drawFrame(FREEZE_CARD_INDEX * CARD_MS + FREEZE_LOCAL_T);
      else drawFrame(startAt === 0 ? 0 : performance.now() - startAt);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        drawFrame(FREEZE_CARD_INDEX * CARD_MS + FREEZE_LOCAL_T);
      } else {
        startAt = 0;
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      if (document.visibilityState === "visible") wake();
      else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      data-reduced-motion-freeze={FREEZE_PHASE}
      className={`ns-jacquard-card-chain relative w-full max-w-sm min-h-[180px] overflow-hidden rounded-[14px] border border-border bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
      <div className="pointer-events-none relative flex flex-col gap-3 p-6">
        <h3 className="text-balance font-sans text-lg font-medium text-foreground">{title}</h3>
        <p className="text-pretty font-mono text-xs leading-relaxed text-ns-muted">{description}</p>
      </div>
    </div>
  );
}

JacquardCardChain.displayName = "JacquardCardChain";

export default JacquardCardChain;

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// JamKickoutLoop — an ambient "background job with retries" status line,
// sourced from bulk-mail sortation conveyor jam handling: a photo-eye pair
// spanning the belt flags a mis-timed piece, a solenoid-driven diverter arm
// kicks that single piece off the main line onto a recirculation loop before
// it reaches the sort point, and the loop re-merges it one cycle later for
// another pass — the line never stops to clear it by hand.
//
// Geometry derives from the container's SMALLER dimension: loop depth =
// 0.3 * min(w,h); the main line and the loop's diverter/re-entry points
// scale off the container's full width. Every tile's position is a pure
// function of elapsed time since its own spawn (t=0 at the left edge),
// evaluated fresh each rAF tick and written straight to that tile's
// transform — nothing is animated with CSS transitions or React state.
//
// Timing (all fixed, none randomised):
//  - spawn: one tile every 900ms at the left edge.
//  - main line rate: reaches the diverter point (72% of track width) at
//    1.6s after spawn — this rate is held constant for the whole tile
//    lifetime, before and after the loop.
//  - kickout: exactly every 6th tile (a counter, never Math.random()) is
//    diverted. ~16.7% is a deliberate legibility amplification over the
//    real ~2-5% recirculation rate, documented, not a claim about real
//    jam frequency.
//  - diverter swing: 150ms, the tile visibly leaves the main line onto the
//    loop path (not a fade) as the arm swings out and re-seats.
//  - loop transit: 1.9s around the side loop, re-entering the main line at
//    a fixed point 18% of track width (behind the diverter) — a second
//    full attempt, not a respawn — then continuing to the right edge at
//    the same constant rate as any other tile.
//  - exit: both first-pass and recirculated tiles fade over 250ms on
//    reaching the right edge.
//
// Legibility: the one thing to follow is the diverter arm swinging a
// single tile off the line onto the loop and back — cadence is one
// kickout roughly every 5.4s (900ms * 6), well inside "watch it happen"
// pacing, and the swing is a visible mechanical gesture rather than an
// instant cut so the eye can track departure and arrival, not a blink.
// ---------------------------------------------------------------------------

const SPAWN_MS = 900;
const KICK_EVERY = 6; // 1-in-6 tiles diverted, fixed counter
const T_MAIN1 = 1600; // ms, left edge -> diverter point (72% of track)
const DIVERT_FRAC = 0.72;
const REENTRY_FRAC = 0.18;
const T_SWING = 150; // ms, diverter arm swing
const T_LOOP = 1900; // ms, loop transit
const T_FADE = 250; // ms, exit fade
const TILE_W = 13;
const TILE_H = 7;
const POOL_SIZE = 20; // headroom above max concurrently-alive tiles

interface Item {
  id: number;
  spawnTime: number;
  kicked: boolean;
}

interface Geometry {
  w: number;
  h: number;
  x0: number; // left edge (spawn x)
  trackW: number; // usable track width
  mainY: number;
  loopY: number; // bottom of the side loop
  dx: number; // diverter x (px)
  rx: number; // re-entry x (px)
  arcR: number; // loop corner radius, for path + tile keyframe match
  rate: number; // px/ms, constant main-line rate
  mainDurFull: number; // ms, non-kicked left edge -> right edge
  mainDur2: number; // ms, kicked re-entry -> right edge
}

function computeGeometry(w: number, h: number): Geometry {
  const loopY_depth = 0.3 * Math.min(w, h);
  const x0 = Math.min(10, w * 0.03);
  const trackW = Math.max(1, w - x0 * 2);
  const mainY = Math.max(18, Math.min(h - loopY_depth - 14, h * 0.42));
  const loopY = mainY + loopY_depth;
  const dx = x0 + DIVERT_FRAC * trackW;
  const rx = x0 + REENTRY_FRAC * trackW;
  const arcR = Math.max(4, Math.min(loopY_depth * 0.5, (dx - rx) * 0.22));
  const rate = (DIVERT_FRAC * trackW) / T_MAIN1;
  const mainDurFull = trackW / rate;
  const mainDur2 = (x0 + trackW - rx) / rate;
  return { w, h, x0, trackW, mainY, loopY, dx, rx, arcR, rate, mainDurFull, mainDur2 };
}

/** Loop-transit keyframe: swing-end point -> bottom-right corner ->
 * bottom-left corner -> re-entry point, matching the static loop <path>. */
function loopPosition(f: number, g: Geometry, swingEndX: number, swingEndY: number): { x: number; y: number } {
  const p0 = { x: swingEndX, y: swingEndY };
  const p1 = { x: g.dx - g.arcR, y: g.loopY };
  const p2 = { x: g.rx + g.arcR, y: g.loopY };
  const p3 = { x: g.rx, y: g.mainY };
  if (f < 0.2) {
    const t = f / 0.2;
    return { x: p0.x + (p1.x - p0.x) * t, y: p0.y + (p1.y - p0.y) * t };
  }
  if (f < 0.8) {
    const t = (f - 0.2) / 0.6;
    return { x: p1.x + (p2.x - p1.x) * t, y: p1.y };
  }
  const t = (f - 0.8) / 0.2;
  return { x: p2.x + (p3.x - p2.x) * t, y: p2.y + (p3.y - p2.y) * t };
}

interface Pose {
  x: number;
  y: number;
  opacity: number;
  alive: boolean;
  swingActive: boolean;
  swingFrac: number; // 0..1 while swingActive, for the arm
}

function poseAt(t: number, kicked: boolean, g: Geometry): Pose {
  if (!kicked) {
    if (t < g.mainDurFull) {
      return { x: g.x0 + g.rate * t, y: g.mainY, opacity: 1, alive: true, swingActive: false, swingFrac: 0 };
    }
    if (t < g.mainDurFull + T_FADE) {
      const f = (t - g.mainDurFull) / T_FADE;
      return { x: g.x0 + g.trackW, y: g.mainY, opacity: 1 - f, alive: true, swingActive: false, swingFrac: 0 };
    }
    return { x: 0, y: 0, opacity: 0, alive: false, swingActive: false, swingFrac: 0 };
  }

  if (t < T_MAIN1) {
    return { x: g.x0 + g.rate * t, y: g.mainY, opacity: 1, alive: true, swingActive: false, swingFrac: 0 };
  }
  const swingEndX = g.dx - g.arcR * 0.35;
  const swingEndY = g.mainY + (g.loopY - g.mainY) * 0.4;
  if (t < T_MAIN1 + T_SWING) {
    const f = (t - T_MAIN1) / T_SWING;
    return {
      x: g.dx + (swingEndX - g.dx) * f,
      y: g.mainY + (swingEndY - g.mainY) * f,
      opacity: 1,
      alive: true,
      swingActive: true,
      swingFrac: f,
    };
  }
  if (t < T_MAIN1 + T_SWING + T_LOOP) {
    const f = (t - T_MAIN1 - T_SWING) / T_LOOP;
    const p = loopPosition(f, g, swingEndX, swingEndY);
    return { x: p.x, y: p.y, opacity: 1, alive: true, swingActive: false, swingFrac: 0 };
  }
  const t3 = T_MAIN1 + T_SWING + T_LOOP;
  if (t < t3 + g.mainDur2) {
    const local = t - t3;
    return { x: g.rx + g.rate * local, y: g.mainY, opacity: 1, alive: true, swingActive: false, swingFrac: 0 };
  }
  if (t < t3 + g.mainDur2 + T_FADE) {
    const f = (t - t3 - g.mainDur2) / T_FADE;
    return { x: g.x0 + g.trackW, y: g.mainY, opacity: 1 - f, alive: true, swingActive: false, swingFrac: 0 };
  }
  return { x: 0, y: 0, opacity: 0, alive: false, swingActive: false, swingFrac: 0 };
}

function loopPathD(g: Geometry): string {
  return [
    `M${g.dx.toFixed(1)} ${g.mainY.toFixed(1)}`,
    `C ${g.dx.toFixed(1)} ${(g.mainY + (g.loopY - g.mainY) * 0.7).toFixed(1)}, ${g.dx.toFixed(1)} ${g.loopY.toFixed(1)}, ${(g.dx - g.arcR).toFixed(1)} ${g.loopY.toFixed(1)}`,
    `L ${(g.rx + g.arcR).toFixed(1)} ${g.loopY.toFixed(1)}`,
    `C ${g.rx.toFixed(1)} ${g.loopY.toFixed(1)}, ${g.rx.toFixed(1)} ${(g.mainY + (g.loopY - g.mainY) * 0.7).toFixed(1)}, ${g.rx.toFixed(1)} ${g.mainY.toFixed(1)}`,
  ].join(" ");
}

// Fixed reduced-motion freeze frame — named MID_KICKOUT: one tile mid
// diverter-swing (still partially over the main line, already angled onto
// the loop), one tile further along the loop, one ordinary tile mid main
// line — normal transit, the kickout event, and loop transit in one frame.
const FREEZE_SWING_T = T_MAIN1 + T_SWING * 0.5;
const FREEZE_LOOP_T = T_MAIN1 + T_SWING + T_LOOP * 0.72;
const FREEZE_MAIN_T = 800;

export interface JamKickoutLoopProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function JamKickoutLoop({ className = "" }: JamKickoutLoopProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const pathRef = useRef<SVGPathElement>(null);
  const lineRef = useRef<SVGLineElement>(null);
  const armRef = useRef<SVGLineElement>(null);
  const tileRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let geo = computeGeometry(root.clientWidth || 1, root.clientHeight || 1);
    let visible = true;
    let raf = 0;
    let last = 0;
    let spawnAcc = 0;
    let spawnCounter = 0;
    let idSeq = 0;
    let items: Item[] = [];
    let armSwingStart = -Infinity;

    const applyGeometry = () => {
      pathRef.current?.setAttribute("d", loopPathD(geo));
      lineRef.current?.setAttribute("x1", String(geo.x0));
      lineRef.current?.setAttribute("x2", String(geo.x0 + geo.trackW));
      lineRef.current?.setAttribute("y1", String(geo.mainY));
      lineRef.current?.setAttribute("y2", String(geo.mainY));
      const armLen = Math.max(10, geo.arcR * 0.9);
      armRef.current?.setAttribute("x1", String(geo.dx));
      armRef.current?.setAttribute("y1", String(geo.mainY));
      armRef.current?.setAttribute("x2", String(geo.dx + armLen));
      armRef.current?.setAttribute("y2", String(geo.mainY));
    };

    const setTile = (el: HTMLDivElement | null, x: number, y: number, opacity: number) => {
      if (!el) return;
      el.style.transform = `translate3d(${(x - TILE_W / 2).toFixed(1)}px, ${(y - TILE_H / 2).toFixed(1)}px, 0)`;
      el.style.opacity = String(opacity);
    };

    const setArm = (angleDeg: number, emphasis: number) => {
      const el = armRef.current;
      if (!el) return;
      el.setAttribute("transform", `rotate(${angleDeg.toFixed(2)} ${geo.dx.toFixed(1)} ${geo.mainY.toFixed(1)})`);
      el.style.opacity = String(0.55 + 0.45 * emphasis);
    };

    const renderFrame = (now: number) => {
      let i = 0;
      for (; i < items.length && i < POOL_SIZE; i++) {
        const item = items[i];
        if (!item) continue;
        const pose = poseAt(now - item.spawnTime, item.kicked, geo);
        setTile(tileRefs.current[i] ?? null, pose.x, pose.y, pose.opacity);
        if (item.kicked && pose.swingActive) {
          armSwingStart = item.spawnTime + T_MAIN1;
        }
      }
      for (; i < POOL_SIZE; i++) setTile(tileRefs.current[i] ?? null, geo.x0, geo.mainY, 0);

      // Arm: swing out over T_SWING, ease back over the following ~250ms;
      // resting otherwise. Driven off the most recent kick's own timeline,
      // not a separate clock, so it always matches the tile that triggered it.
      const sinceSwing = now - armSwingStart;
      if (sinceSwing >= 0 && sinceSwing < T_SWING) {
        const f = sinceSwing / T_SWING;
        setArm(108 * f, f);
      } else if (sinceSwing >= T_SWING && sinceSwing < T_SWING + 260) {
        const f = 1 - (sinceSwing - T_SWING) / 260;
        setArm(108 * f, f);
      } else {
        setArm(0, 0);
      }
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;

      spawnAcc += dt;
      while (spawnAcc >= SPAWN_MS) {
        spawnAcc -= SPAWN_MS;
        const kicked = spawnCounter % KICK_EVERY === KICK_EVERY - 1;
        spawnCounter += 1;
        items.push({ id: idSeq++, spawnTime: now - spawnAcc, kicked });
      }
      items = items.filter((it) => poseAt(now - it.spawnTime, it.kicked, geo).alive);

      renderFrame(now);
      raf = requestAnimationFrame(loop);
    };

    const seedResting = () => {
      // Populate a believable "already running" resting state instead of an
      // empty track on first paint: back-date a handful of spawn times.
      const now = performance.now();
      items = [];
      spawnCounter = 0;
      const seedSpawns = [-5100, -4200, -3300, -2400, -1500, -600];
      for (const offset of seedSpawns) {
        const kicked = spawnCounter % KICK_EVERY === KICK_EVERY - 1;
        spawnCounter += 1;
        items.push({ id: idSeq++, spawnTime: now + offset, kicked });
      }
      items = items.filter((it) => poseAt(now - it.spawnTime, it.kicked, geo).alive);
      spawnAcc = 600; // next spawn due in 300ms, matching the 900ms cadence
      renderFrame(now);
    };

    const renderFreezeFrame = () => {
      applyGeometry();
      const swing = poseAt(FREEZE_SWING_T, true, geo);
      const loopTile = poseAt(FREEZE_LOOP_T, true, geo);
      const mainTile = poseAt(FREEZE_MAIN_T, false, geo);
      setTile(tileRefs.current[0] ?? null, swing.x, swing.y, 1);
      setTile(tileRefs.current[1] ?? null, loopTile.x, loopTile.y, 1);
      setTile(tileRefs.current[2] ?? null, mainTile.x, mainTile.y, 1);
      for (let i = 3; i < POOL_SIZE; i++) setTile(tileRefs.current[i] ?? null, geo.x0, geo.mainY, 0);
      setArm(108 * swing.swingFrac, swing.swingFrac);
    };

    const start = () => {
      applyGeometry();
      if (reduced) {
        renderFreezeFrame();
        return;
      }
      seedResting();
      last = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed || !root) return;
        geo = computeGeometry(root.clientWidth || 1, root.clientHeight || 1);
        applyGeometry();
        if (reduced) renderFreezeFrame();
      }, 100);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    start();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`relative isolate overflow-hidden bg-background ${className}`}
    >
      <svg aria-hidden="true" focusable="false" className="pointer-events-none absolute inset-0 h-full w-full overflow-visible">
        <line ref={lineRef} stroke="var(--border)" strokeWidth={1} />
        <path ref={pathRef} fill="none" stroke="var(--border)" strokeWidth={1} />
        <line
          ref={armRef}
          stroke="var(--ns-muted)"
          strokeWidth={2}
          strokeLinecap="round"
          style={{ transition: "opacity 150ms ease-out" }}
        />
      </svg>
      <div className="pointer-events-none absolute inset-0">
        {Array.from({ length: POOL_SIZE }).map((_, i) => (
          <div
            key={i}
            ref={(el) => {
              tileRefs.current[i] = el;
            }}
            className="absolute left-0 top-0 rounded-[1px] bg-foreground"
            style={{ width: TILE_W, height: TILE_H, opacity: 0, willChange: "transform" }}
          />
        ))}
      </div>
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// KelvinWake — a real site nav whose active-item indicator is a point source
// drifting along the link row, trailing a genuine KELVIN SHIP WAKE beneath
// it: a V-shaped envelope of transverse + diverging waves held at a
// CONSTANT half-angle of arcsin(1/3) ≈ 19.4712°, independent of how fast the
// source is moving — Lord Kelvin's 1887 result for a point disturbance on
// deep water, and the one truly speed-invariant fact about a ship's wake.
//
// Distinct from hero-vortex-street (also in this registry): that component
// sheds a von Karman vortex street — a cursor-driven point vortex spawning
// alternating-sign rotational eddies that drift downstream and DECAY on
// their own clock, advected/summed via the Biot–Savart-style Lamb-Oseen
// velocity field. This component has no rotation, no decay and no summed
// velocity field at all — it is a STEADY dispersive-wave interference
// pattern that reattaches, whole, to wherever the source currently is and
// however it is currently heading. Different physics entirely: vortex
// shedding (rotational, unsteady, dissipative) vs. surface-wave dispersion
// (irrotational, a fixed geometric envelope that is exactly the same shape
// at every instant regardless of speed).
//
// GEOMETRIC MODEL (a practical, honestly-approximate implementation, not a
// numerical solve of Kelvin's exact stationary-phase integral — see below
// for the two constants that ARE exact and load-bearing). Each transverse
// wave crest n (n = 1, 2, 3…) is drawn as a circular arc of radius
// n·WAVELEN centered ON THE SOURCE, spanning the angular cone
// ±arcsin(1/3) around the "directly behind" heading — i.e. concentric
// wavefronts trailing the source, clipped to Kelvin's cone. Each arc's two
// endpoints are, by construction, cusp points sitting exactly on the
// envelope line, so the crests visibly nest inside a V that never changes
// angle no matter how fast the source is currently travelling. From each
// cusp a short DIVERGING wave segment continues outward along the local
// tangent (perpendicular to the arc's radius, chosen to point forward and
// away from the centerline) — the two systems meeting exactly where the
// real Kelvin pattern's transverse and diverging waves meet: at the
// envelope itself. The two lines of the envelope are also drawn directly,
// so the constant angle is legible on sight, not just implied by where the
// crests happen to end.
//
// The wake is redrawn fresh every frame from the source's CURRENT position
// and heading only — it carries no history of past positions or past
// speeds. That is a deliberate simplification (the real wake has a finite
// relaxation time after a genuine speed change), but it is exact for the
// one claim this component exists to demonstrate: Kelvin's angle is a
// property of deep-water dispersion alone, true instant-by-instant,
// completely independent of the source's current speed.
//
// ALIVE AT REST: the source never stops. With no interaction it patrols the
// full width of the rail on a slow ping-pong sweep (~11s per leg); a real
// click/keyboard-activation of a nav link eases the source, faster, to that
// link's measured center, holds there briefly, then resumes the patrol from
// wherever it ended up — one continuous easing target, exactly the pattern
// hero-vortex-street uses for its pointer-vs-idle-orbit driver, applied here
// to click-vs-patrol. Both speeds leave the same 19.4712° V.
//
// A NAV IS A REAL NAV: real <a> links in a <ul>, aria-current="page" on the
// active one, full keyboard/focus-visible support, normal tab order — none
// of it depends on the canvas. The wake strip is aria-hidden decoration
// layered underneath.
//
// House idiom duplicated on purpose (no shared helpers, per project
// convention): tokens read via getComputedStyle + a MutationObserver on
// documentElement's class, resolved in useLayoutEffect before first paint so
// nothing ever draws with an empty ink string; one rAF loop paused on both
// document visibilitychange and an IntersectionObserver (threshold 0) on
// the strip itself; DPR-capped(2) backing store with a zero-size guard.
//
// prefers-reduced-motion: no rAF loop at all. One static frame is drawn
// with the source parked at 62% along the rail (not 0% or 100%, where the
// wake would either be barely formed or already clipped off the trailing
// edge) so both wave systems and the full envelope read clearly at a glance.
// ---------------------------------------------------------------------------

export interface KelvinWakeLink {
  href: string;
  label: string;
}

export interface KelvinWakeProps {
  /** brand text on the left */
  wordmark?: string;
  /** nav links, in order */
  links?: KelvinWakeLink[];
  /** href of the initially active link (defaults to the first) */
  defaultActiveHref?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_LINKS: KelvinWakeLink[] = [
  { href: "#work", label: "Work" },
  { href: "#process", label: "Process" },
  { href: "#pricing", label: "Pricing" },
  { href: "#contact", label: "Contact" },
];

// The one exact, speed-independent constant this whole component exists to
// show: Kelvin's 1887 half-angle, arcsin(1/3) ≈ 19.4712°.
const PHI_MAX = Math.asin(1 / 3);

const EASE_RATE = 3.4; // 1/s, exponential approach of the driver toward its current target
const PATROL_PERIOD_S = 11; // s per idle leg of the ping-pong sweep — slow, deliberate
const CLICK_HOLD_S = 2.1; // s the driver's target stays pinned to a clicked link
const PATROL_MARGIN = 20; // px inset from each rail edge for the idle sweep
const SOURCE_R = 4; // px, the active-indicator dot
const STATIC_FRACTION = 0.62; // reduced-motion freeze position, see comment above

function clamp(v: number, lo: number, hi: number) {
  return v < lo ? lo : v > hi ? hi : v;
}

// Triangle wave: 0 -> 1 -> 0 over one period — a ping-pong sweep, not a
// snap-back sawtooth.
function triangle(t: number): number {
  const p = t * 2;
  return p > 1 ? 2 - p : p;
}

function centerXFor(el: HTMLElement, canvasRect: DOMRect): number {
  const r = el.getBoundingClientRect();
  return r.left + r.width / 2 - canvasRect.left;
}

export function KelvinWake({
  wordmark = "ns-ui",
  links = DEFAULT_LINKS,
  defaultActiveHref,
  className = "",
}: KelvinWakeProps) {
  const [activeHref, setActiveHref] = useState(
    () => defaultActiveHref ?? links[0]?.href ?? ""
  );

  const navRef = useRef<HTMLElement | null>(null);
  const stripRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const linkRefs = useRef<Map<string, HTMLAnchorElement>>(new Map());
  const clickTimeRef = useRef(-Infinity); // performance.now() ms of the last activation
  const clickTargetXRef = useRef(0);
  const activeHrefRef = useRef(activeHref);
  activeHrefRef.current = activeHref;

  // token derive happens in useLayoutEffect, before first paint, so no rAF /
  // resize / reduced-motion branch can draw with an empty ink string
  useLayoutEffect(() => {
    const strip = stripRef.current;
    const canvas = canvasRef.current;
    if (!strip || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let fg = "";
    let muted = "";
    let accent = "";
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim();
      muted = cs.getPropertyValue("--ns-muted").trim();
      accent = cs.getPropertyValue("--ns-accent").trim();
    };
    readTokens();

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let raf = 0;
    let running = false;
    let visible = true;
    let cssW = 0;
    let cssH = 0;
    let driverX = 0;
    let driverInit = false;
    let lastDriverX = 0;
    let heading = 1; // +1 = rightward, -1 = leftward; held across zero-velocity frames

    const recomputeLinkCenters = () => {
      const canvasRect = canvas.getBoundingClientRect();
      const el = linkRefs.current.get(activeHrefRef.current);
      if (!el) return;
      clickTargetXRef.current = centerXFor(el, canvasRect);
    };

    const patrolX = (nowS: number) => {
      const span = Math.max(1, cssW - PATROL_MARGIN * 2);
      const phase = (nowS % PATROL_PERIOD_S) / PATROL_PERIOD_S;
      return PATROL_MARGIN + triangle(phase) * span;
    };

    const drawWake = (sourceX: number, headingSign: number) => {
      const cy = cssH / 2;
      ctx.clearRect(0, 0, cssW, cssH);
      if (cssW <= 0 || cssH <= 0) return;

      const halfH = cssH / 2;
      // WAVE_MARGIN keeps the whole pattern — envelope, crests AND the
      // diverging tails — inside a budget short of the strip's own edges,
      // so ink never touches the frame and never hard-clips against the
      // canvas bitmap mid-stroke. Budget is in the same lateral units the
      // envelope angle produces (R·sin(PHI_MAX)), so it bounds every drawn
      // element the same way, not just the crest arcs.
      const WAVE_MARGIN = 0.82;
      const budget = halfH * WAVE_MARGIN;
      // WAVELEN scales with the strip's own height, never a fixed px
      // constant, so crest spacing stays proportional at any rail scale.
      // The 0.38 multiplier (down from a naive 0.5) is chosen so that,
      // combined with WAVE_MARGIN above, three rings still fit the budget
      // instead of collapsing to the documented floor of two.
      const wavelen = clamp(cssH * 0.38, 8, 26);
      // sin(PHI_MAX) = 1/3 exactly: k·wavelen·sin(PHI_MAX) is crest k's
      // lateral reach, so the largest k that still fits inside budget is
      // budget / (wavelen·sin(PHI_MAX)) — the exact invariant stays
      // load-bearing here rather than hardcoding 3.
      const n = clamp(Math.floor(budget / (wavelen * Math.sin(PHI_MAX))), 2, 6);

      const behindAngle = headingSign > 0 ? Math.PI : 0;

      // the envelope itself — drawn directly so the constant angle reads at
      // a glance, not only implied by where crests happen to cusp. Length is
      // capped at the same budget (physically correct: the real wake DOES
      // grow taller the further back you draw it, so the strip's height is
      // exactly what limits how far behind the source it can be legibly
      // drawn before it would exceed the frame).
      const envLen = budget / Math.sin(PHI_MAX);
      ctx.strokeStyle = muted || "currentColor";
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.34;
      for (const sign of [-1, 1]) {
        const ang = behindAngle + sign * PHI_MAX;
        ctx.beginPath();
        ctx.moveTo(sourceX, cy);
        ctx.lineTo(sourceX + Math.cos(ang) * envLen, cy + Math.sin(ang) * envLen);
        ctx.stroke();
      }

      // transverse crests (concentric arcs, source-centered) + the diverging
      // segment that continues tangentially from each cusp
      for (let k = n; k >= 1; k--) {
        const r = k * wavelen;
        const t = 1 - (k - 1) / n; // 1 = nearest/freshest crest, fading with k
        const alpha = 0.18 + 0.42 * t;
        ctx.strokeStyle = t > 0.55 ? fg || "currentColor" : muted || "currentColor";
        ctx.lineWidth = 1.15;
        ctx.globalAlpha = alpha;

        const angleA = behindAngle - PHI_MAX;
        const angleB = behindAngle + PHI_MAX;
        ctx.beginPath();
        ctx.arc(sourceX, cy, r, angleA, angleB);
        ctx.stroke();

        // cusp k already sits at k·wavelen·sin(PHI_MAX) of the budget; each
        // ring's diverging tail is clamped to whatever budget remains
        // beyond its own cusp, so the outermost ring's tail shortens
        // instead of shooting past the frame and hard-clipping.
        const cuspLateral = r * Math.sin(PHI_MAX);
        const headroom = Math.max(0, budget - cuspLateral);
        const divLen = Math.min(wavelen * 1.6, headroom / Math.cos(PHI_MAX));
        for (const ang of [angleA, angleB]) {
          const cuspX = sourceX + Math.cos(ang) * r;
          const cuspY = cy + Math.sin(ang) * r;
          // tangent to the arc at the cusp — pick whichever perpendicular
          // points forward (with the current heading) and away from the
          // centerline, the direction a real diverging crest sweeps.
          const p1x = -Math.sin(ang);
          const p1y = Math.cos(ang);
          const forward1 = p1x * headingSign > 0;
          const dx = forward1 ? p1x : -p1x;
          const dy = forward1 ? p1y : -p1y;
          ctx.beginPath();
          ctx.moveTo(cuspX, cuspY);
          ctx.lineTo(cuspX + dx * divLen, cuspY + dy * divLen);
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;

      // the source itself — the active-indicator dot. Legitimate
      // interaction chrome, so --ns-accent is correct here (unlike the
      // wave field above, which is ambient and stays --foreground/--ns-muted).
      ctx.beginPath();
      ctx.fillStyle = accent || "currentColor";
      ctx.arc(sourceX, cy, SOURCE_R, 0, Math.PI * 2);
      ctx.fill();
    };

    const drawStatic = () => {
      recomputeLinkCenters();
      const x = PATROL_MARGIN + STATIC_FRACTION * Math.max(1, cssW - PATROL_MARGIN * 2);
      drawWake(x, 1);
    };

    let last = 0;
    const loop = (ts: number) => {
      if (disposed) return;
      const dt = Math.min((ts - (last || ts)) / 1000, 1 / 30);
      last = ts;
      const nowS = ts / 1000;

      const sinceClick = performance.now() - clickTimeRef.current;
      const target =
        sinceClick < CLICK_HOLD_S * 1000 ? clickTargetXRef.current : patrolX(nowS);

      if (!driverInit) {
        driverX = target;
        lastDriverX = target;
        driverInit = true;
      }
      const ease = 1 - Math.exp(-EASE_RATE * dt);
      driverX += (target - driverX) * ease;

      const delta = driverX - lastDriverX;
      if (Math.abs(delta) > 0.01) heading = delta > 0 ? 1 : -1;
      lastDriverX = driverX;

      drawWake(driverX, heading);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || reduced) return;
      running = true;
      last = 0;
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return; // zero-size guard
      cssW = rect.width;
      cssH = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
      canvas.style.width = `${cssW}px`;
      canvas.style.height = `${cssH}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      recomputeLinkCenters();
      if (reduced) drawStatic();
    };

    const ro = new ResizeObserver(resize);
    ro.observe(strip);
    for (const el of linkRefs.current.values()) ro.observe(el);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[entries.length - 1]?.isIntersecting ?? true;
        if (!reduced) {
          if (visible) wake();
          else sleep();
        }
      },
      { threshold: 0 }
    );
    io.observe(strip);

    const themeObserver = new MutationObserver(() => {
      readTokens();
      if (reduced) drawStatic();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onVis = () => {
      if (reduced) return;
      if (document.hidden) sleep();
      else if (visible) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    resize();
    if (!reduced) wake();
    else drawStatic();

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      themeObserver.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      sleep();
    };
    // re-run only when the link set itself changes; activeHref is read via
    // activeHrefRef so a click never tears down and restarts the driver —
    // that would snap the source to its target instead of easing to it
  }, [links]);

  return (
    <nav
      ref={navRef}
      aria-label="Primary"
      className={`relative w-full border-b border-border bg-background pb-2 ${className}`}
    >
      <div className="mx-auto flex w-full max-w-6xl items-center justify-between px-6 pt-4">
        <a
          href="#top"
          className="shrink-0 rounded-sm font-mono text-[15px] font-semibold tracking-tight text-foreground transition-colors duration-150 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
        >
          {wordmark}
        </a>
        <ul className="flex items-center gap-7">
          {links.map((link) => {
            const isActive = link.href === activeHref;
            return (
              <li key={link.href}>
                <a
                  ref={(el) => {
                    if (el) linkRefs.current.set(link.href, el);
                    else linkRefs.current.delete(link.href);
                  }}
                  href={link.href}
                  aria-current={isActive ? "page" : undefined}
                  onClick={(e) => {
                    // this embed has no real #process section to land on; the
                    // wake/active-link response below is the entire effect of
                    // a click, so stop the browser's own fragment navigation
                    // (matters for autoplay's synthetic clicks on a timer)
                    e.preventDefault();
                    setActiveHref(link.href);
                    const canvas = canvasRef.current;
                    if (canvas) {
                      clickTargetXRef.current = centerXFor(
                        e.currentTarget,
                        canvas.getBoundingClientRect()
                      );
                    }
                    clickTimeRef.current = performance.now();
                  }}
                  className={`rounded-sm text-sm transition-colors duration-150 hover:text-foreground focus-visible:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent ${
                    isActive ? "text-foreground" : "text-ns-muted"
                  }`}
                >
                  {link.label}
                </a>
              </li>
            );
          })}
        </ul>
      </div>

      {/* decorative wake strip beneath the real link row — aria-hidden. It
          illustrates which item is active (the source parks over it after a
          click) and that the rail is alive at rest (the idle patrol); it
          never carries navigation semantics of its own. */}
      <div ref={stripRef} aria-hidden="true" className="relative mx-auto mt-2 h-9 w-full max-w-6xl px-6">
        <canvas ref={canvasRef} className="block h-full w-full" />
      </div>
    </nav>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// KeymapAsciiHeat — an ASCII keyboard layout that accumulates real ink
// density per key as you type into a real text input: every keydown adds
// heat to that key's cell, heat decays on an exponential half-life so a key
// you stop pressing visibly fades back to blank paper, and the legend's
// scale is recomputed against whichever key is currently hottest. Distinct
// from shortcuts-cheat-sheet (a static keycap depresses itself for a listed
// COMBINATION and swallows the keydown — a rehearsal aid, no accumulation,
// no decay, no legend) and from heatmap-year-stipple (density via jittered
// dot count, not a character ramp, and driven by a canned yearly dataset,
// not live keystrokes). The ramp (" .:-=+*#%@") still names each of the 10
// heat steps in the legend, but a key's OWN cell never draws that ramp
// character behind its letter — two glyphs sharing one small cell just
// overlaid into an illegible mess (a real bug this component shipped with:
// hammer A/S/D/F and the ramp character stacks on the letterform itself).
// Heat instead reads as a flat --foreground fill behind the letter, opacity
// scaled 0 -> ~0.55 by the key's decayed ink over the live max, so every key
// shows exactly one legible glyph at every heat level, in both themes. No
// canvas: every cell is real DOM, colored from --foreground via a Tailwind
// opacity utility, no hex.
// ---------------------------------------------------------------------------

const RAMP = [" ", ".", ":", "-", "=", "+", "*", "#", "%", "@"];
const HALF_LIFE_MS = 7000;
const REPAINT_MS = 90;
const SLEEP_EPS = 0.02;

const ROWS: string[][] = [
  ["Q", "W", "E", "R", "T", "Y", "U", "I", "O", "P"],
  ["A", "S", "D", "F", "G", "H", "J", "K", "L"],
  ["Z", "X", "C", "V", "B", "N", "M"],
];

function decay(ink: number, dtMs: number): number {
  return ink * Math.pow(0.5, dtMs / HALF_LIFE_MS);
}

function keyFor(e: { key: string }): string | null {
  if (e.key === " ") return "SPACE";
  if (e.key.length === 1 && /[a-zA-Z]/.test(e.key)) return e.key.toUpperCase();
  return null;
}

export interface KeymapAsciiHeatProps {
  /** placeholder text for the typing input */
  placeholder?: string;
  /** accessible name for the typing input */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function KeymapAsciiHeat({
  placeholder = "Type here — the keys below heat up as you go",
  label = "Type to build heat",
  className = "",
}: KeymapAsciiHeatProps) {
  const inkRef = useRef(new Map<string, { ink: number; lastAt: number }>());
  const rafRef = useRef(0);
  const lastRepaintRef = useRef(0);
  const reducedRef = useRef(false);

  const [levels, setLevels] = useState<Record<string, number>>({});
  const [maxInk, setMaxInk] = useState(0);
  const [hoveredKey, setHoveredKey] = useState<string | null>(null);
  const [text, setText] = useState("");

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const recompute = (now: number) => {
    const raw: Record<string, number> = {};
    let max = 0;
    let anyLive = false;
    inkRef.current.forEach((v, key) => {
      const cur = decay(v.ink, now - v.lastAt);
      if (cur > SLEEP_EPS) anyLive = true;
      raw[key] = cur;
      if (cur > max) max = cur;
    });
    setLevels(raw);
    setMaxInk(max);
    return anyLive;
  };

  const stop = () => {
    cancelAnimationFrame(rafRef.current);
    rafRef.current = 0;
  };

  const step = (now: number) => {
    rafRef.current = 0;
    if (now - lastRepaintRef.current >= REPAINT_MS) {
      lastRepaintRef.current = now;
      const anyLive = recompute(now);
      if (!anyLive) return; // sleep — pulse() wakes it again
    }
    rafRef.current = requestAnimationFrame(step);
  };

  const wake = () => {
    if (!rafRef.current) rafRef.current = requestAnimationFrame(step);
  };

  useEffect(() => stop, []);

  const pulse = (key: string) => {
    const now = performance.now();
    const m = inkRef.current;
    const prev = m.get(key);
    const cur = prev ? decay(prev.ink, now - prev.lastAt) : 0;
    m.set(key, { ink: cur + 1, lastAt: now });
    if (reducedRef.current) {
      lastRepaintRef.current = now;
      recompute(now);
    } else {
      wake();
    }
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const key = keyFor(e);
    if (key) pulse(key);
  };

  const MAX_FILL_OPACITY = 0.55;

  const heatOpacityFor = (key: string): number => {
    const v = levels[key] ?? 0;
    if (maxInk <= SLEEP_EPS) return 0;
    return Math.min(1, v / maxInk) * MAX_FILL_OPACITY;
  };

  const legend = useMemo(() => RAMP.join(""), []);

  const renderKey = (key: string, wide = false) => (
    <div
      key={key}
      aria-hidden
      data-key={key}
      onPointerEnter={() => setHoveredKey(key)}
      onPointerLeave={() => setHoveredKey((h) => (h === key ? null : h))}
      className={`relative flex h-9 items-center justify-center rounded-sm border border-border bg-background text-foreground transition-colors duration-100 motion-reduce:transition-none hover:bg-foreground/[0.06] ${
        wide ? "w-40" : "w-9"
      }`}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-sm bg-foreground"
        style={{ opacity: heatOpacityFor(key) }}
      />
      <span className="relative z-10 select-none text-[11px] font-semibold tracking-wide">
        {key === "SPACE" ? "␣" : key}
      </span>
    </div>
  );

  return (
    <div className={`inline-flex flex-col gap-3 font-mono ${className}`}>
      <input
        type="text"
        value={text}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={onKeyDown}
        placeholder={placeholder}
        aria-label={label}
        className="w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-foreground outline-none transition-colors duration-100 motion-reduce:transition-none placeholder:text-ns-muted focus-visible:ring-2 focus-visible:ring-ns-accent"
      />

      <div className="flex flex-col items-center gap-1.5 rounded-sm border border-border bg-surface p-3">
        {ROWS.map((row, i) => (
          <div key={i} className="flex gap-1.5">
            {row.map((k) => renderKey(k))}
          </div>
        ))}
        <div className="flex gap-1.5 pt-0.5">{renderKey("SPACE", true)}</div>
      </div>

      <div className="flex items-center justify-between gap-3 rounded-sm border border-border bg-background px-3 py-1.5 text-[11px] text-ns-muted">
        <span data-legend className="tabular-nums">
          ink {legend} max={maxInk.toFixed(1)}
        </span>
        <span data-hover-readout className="tabular-nums">
          {hoveredKey ? `${hoveredKey === "SPACE" ? "␣" : hoveredKey}: ${(levels[hoveredKey] ?? 0).toFixed(1)}` : "hover a key"}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// KnifeEdgeRackFocus — a card-scale loader substitute built on the Foucault
// knife-edge test: a knife edge is racked (moved axially) through a mirror's
// point of focus, and the shadow pattern cast back across the aperture
// sweeps from one side to a flat uniform grey exactly at the null, then to
// the other side. A local zone that departs from the ideal sphere crosses
// that null at a slightly different knife position than its neighbours, so
// it reads as a ring rising or sinking out of the otherwise-flat field —
// which is the real diagnostic signal a real optician is looking for.
//
// RENDERING: rather than raster a 2D field, the whole pattern collapses to
// ONE function of radius, L(r, t) = clamp(0.5 + K*(t - offset(r)), 0, 1),
// because each of the 4 baked zonal errors is a concentric shell and every
// point at the same radius shares the same optical path. offset(r) is a
// piecewise-linear interpolation between 4 anchor offsets at r = 0.25, 0.5,
// 0.7, 0.9 (of disc radius), spaced 0.12 apart, extrapolated flat beyond the
// anchors. That single 1D function is sampled at 48 points and painted as
// one radial CanvasGradient per frame — cheap, and the smoothness of a real
// shadow front comes for free from the gradient interpolation instead of a
// pixel raster.
//
// THE RACK is a triangle wave in knife position t, [-1, 1], 8s out + 8s
// back (16s full period) — never a reset, a real tester racks back and
// forth to bracket the null repeatedly. Exactly at a null (|t| < 0.05) the
// drive itself PAUSES for ~0.6s before continuing, mirroring how a real
// tester dwells there; that pause, not the sweep, is the clearest single
// followable event.
//
// Colours: the shadow ramp spans --foreground (dark) to --background
// (light) directly — this is a literal light/shadow phenomenon in both
// themes, so the mapping never inverts, only the read stays a shadow.
// --border is never used as a fill/stroke (it is a separator token only).

const RACK_PERIOD_S = 16; // 8s out + 8s back
const NULL_WINDOW = 0.05; // |t| under this counts as "at the null"
const NULL_DWELL_S = 0.6;
const SHADOW_K = 1.8;
const ZONE_ANCHORS = [0.25, 0.5, 0.7, 0.9];
const ZONE_OFFSETS = [-0.18, -0.06, 0.06, 0.18]; // spaced 0.12 apart
const RADIUS_RATIO = 0.42; // disc radius = 0.42 * min(w, h)
const GRADIENT_STEPS = 48;
const GRADIENT_REACH = 1.05; // sample slightly past the rim for a soft edge

// reduced-motion freeze frame: t = 0.3, named "half-sweep-zoned" — clear
// rise/fall banding across all 4 zones is visible here, unlike the null
// itself (t = 0) which is nearly featureless and would under-inform a
// static viewer. Deliberately not t0/the null.
const FREEZE_LABEL = "half-sweep-zoned";
const FREEZE_T = 0.3;

type RGB = [number, number, number];

function parseHex(raw: string): RGB | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function mixRGB(a: RGB, b: RGB, t: number): RGB {
  const c = Math.max(0, Math.min(1, t));
  return [
    Math.round(a[0] + (b[0] - a[0]) * c),
    Math.round(a[1] + (b[1] - a[1]) * c),
    Math.round(a[2] + (b[2] - a[2]) * c),
  ];
}

function rgbToCss([r, g, b]: RGB): string {
  return `rgb(${r},${g},${b})`;
}

// offset(r): piecewise-linear through the 4 anchors, flat-clamped outside
function zoneOffsetAt(rFrac: number): number {
  if (rFrac <= ZONE_ANCHORS[0]!) return ZONE_OFFSETS[0]!;
  if (rFrac >= ZONE_ANCHORS[ZONE_ANCHORS.length - 1]!) {
    return ZONE_OFFSETS[ZONE_OFFSETS.length - 1]!;
  }
  for (let i = 0; i < ZONE_ANCHORS.length - 1; i++) {
    const a0 = ZONE_ANCHORS[i]!;
    const a1 = ZONE_ANCHORS[i + 1]!;
    if (rFrac >= a0 && rFrac <= a1) {
      const f = (rFrac - a0) / (a1 - a0);
      return ZONE_OFFSETS[i]! + (ZONE_OFFSETS[i + 1]! - ZONE_OFFSETS[i]!) * f;
    }
  }
  return 0;
}

function shadowL(rFrac: number, t: number): number {
  return Math.max(0, Math.min(1, 0.5 + SHADOW_K * (t - zoneOffsetAt(rFrac))));
}

// triangle wave over RACK_PERIOD_S, driveTime -> t in [-1, 1]
function triangleT(driveTime: number): number {
  const ph = ((driveTime / RACK_PERIOD_S) % 1 + 1) % 1;
  return ph < 0.5 ? -1 + 4 * ph : 1 - 4 * (ph - 0.5);
}

// nearest null (t = 0) as a driveTime value, mod RACK_PERIOD_S: nulls occur
// at ph = 0.25 and ph = 0.75
function nearestNullDriveTime(driveTime: number): number {
  const period = RACK_PERIOD_S;
  const ph = ((driveTime / period) % 1 + 1) % 1;
  const candidates = [0.25, 0.75];
  let best = candidates[0]!;
  let bestDist = Infinity;
  for (const c of candidates) {
    const d = Math.min(Math.abs(ph - c), 1 - Math.abs(ph - c));
    if (d < bestDist) {
      bestDist = d;
      best = c;
    }
  }
  const base = Math.floor(driveTime / period) * period;
  return base + best * period;
}

export interface KnifeEdgeRackFocusProps {
  /** accessible status text announced to assistive tech */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function KnifeEdgeRackFocus({
  label = "Testing",
  className = "",
}: KnifeEdgeRackFocusProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let visible = true;
    let raf = 0;

    let w = 0;
    let h = 0;
    let dpr = 1;
    let radius = 0;

    let fg: RGB = [23, 23, 23];
    let bg: RGB = [255, 255, 255];

    // no paint before this first read
    const deriveColors = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseHex(cs.getPropertyValue("--foreground")) ?? fg;
      bg = parseHex(cs.getPropertyValue("--background")) ?? bg;
    };

    const build = () => {
      const rect = container.getBoundingClientRect();
      w = Math.round(rect.width);
      h = Math.round(rect.height);
      if (w < 2 || h < 2) return;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      radius = RADIUS_RATIO * Math.min(w, h);
    };

    // the shadow pattern is one function of radius, painted as a single
    // radial gradient — the smoothness of a real shadow front comes free
    // from gradient interpolation rather than a pixel raster
    const drawDisc = (t: number, showPausedRing: boolean) => {
      if (w < 2 || h < 2 || radius <= 0) return;
      const cx = w / 2;
      const cy = h / 2;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius * GRADIENT_REACH);
      for (let i = 0; i <= GRADIENT_STEPS; i++) {
        const stop = i / GRADIENT_STEPS;
        const rFrac = stop / GRADIENT_REACH;
        const L = shadowL(Math.min(1, rFrac), t);
        grad.addColorStop(stop, rgbToCss(mixRGB(fg, bg, L)));
      }

      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.closePath();
      ctx.fillStyle = grad;
      ctx.fill();

      // a manual "hold" affordance while the user is pausing the rack at a
      // null — foreground only, never --border as a stroke and never accent
      if (showPausedRing) {
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},0.4)`;
        ctx.stroke();
      }
      ctx.restore();
    };

    const drawReduced = () => {
      drawDisc(FREEZE_T, false);
    };

    let driveTime = 0;
    let dwelling = false;
    let dwellElapsed = 0;
    let userPaused = false;
    let pausedDriveTime = 0;
    let last = 0;

    const loop = (now: number) => {
      if (disposed || !visible) {
        raf = 0;
        return;
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      let t: number;
      if (userPaused) {
        t = triangleT(pausedDriveTime);
      } else if (dwelling) {
        dwellElapsed += dt;
        t = triangleT(driveTime);
        if (dwellElapsed >= NULL_DWELL_S) {
          dwelling = false;
          dwellElapsed = 0;
        }
      } else {
        driveTime += dt;
        t = triangleT(driveTime);
        if (Math.abs(t) < NULL_WINDOW) {
          dwelling = true;
          dwellElapsed = 0;
        }
      }

      drawDisc(t, userPaused);
      raf = requestAnimationFrame(loop);
    };

    const startLoop = () => {
      if (!raf && !reduced) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    // press pauses the rack at the nearest null and holds it there; release
    // resumes the sweep from where it paused. Never alters the baked zone
    // profile, never touches SHADOW_K or the offsets.
    const onPointerDown = () => {
      pausedDriveTime = nearestNullDriveTime(driveTime);
      userPaused = true;
      drawDisc(triangleT(pausedDriveTime), true);
    };
    const endPause = () => {
      if (!userPaused) return;
      userPaused = false;
      driveTime = pausedDriveTime;
      dwelling = false;
      dwellElapsed = 0;
    };

    deriveColors();
    build();
    if (reduced) {
      drawReduced();
    } else {
      startLoop();
    }

    const ro = new ResizeObserver(() => {
      build();
      if (reduced) drawReduced();
    });
    ro.observe(container);

    const mo = new MutationObserver(() => {
      deriveColors();
      if (reduced) {
        drawReduced();
      } else if (userPaused) {
        drawDisc(triangleT(pausedDriveTime), true);
      }
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced) startLoop();
    });
    io.observe(container);

    if (!reduced) {
      container.addEventListener("pointerdown", onPointerDown);
      container.addEventListener("pointerup", endPause);
      container.addEventListener("pointercancel", endPause);
      container.addEventListener("pointerleave", endPause);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      container.removeEventListener("pointerdown", onPointerDown);
      container.removeEventListener("pointerup", endPause);
      container.removeEventListener("pointercancel", endPause);
      container.removeEventListener("pointerleave", endPause);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      role="status"
      className={`relative aspect-square w-full max-w-[280px] touch-none overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      <span className="sr-only">{label}</span>
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 h-full w-full" />
    </div>
  );
}

export { FREEZE_LABEL };

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// KnitLadderRun — an ambient status/health feedback card background: a field
// of knit stitches builds downward course by course, and at random intervals
// a dropped stitch opens a ladder ("run") that unravels a few rows before a
// latch-hook repair catches it and reknits the column. Source: weft-knit
// loop formation + latch-hook ladder repair (textile/knitting).
//
// Distinct from text-stitch-unpick (pointer-driven, letter-by-letter,
// irreversible per letter) and optimistic-stitch (a single row's write
// lifecycle, never loops): this is fully ambient, builds continuously, and
// its ladder-run is a RECURRING, SELF-HEALING fault, not a one-shot
// lifecycle or a pointer gesture.
//
// TIMELINE — two clocks, both derived from one elapsed-ms counter, no React
// state:
//   continuousCourse = elapsedMs / COURSE_MS   (smooth fractional scroll)
//   currentCourse    = floor(continuousCourse)  (newest row that exists)
// New courses enter at the bottom edge; existing courses drift upward and
// eventually exit the top (the "continuous fabric take-down" feed) — never
// a fixed-length pass.
//
// LADDER STATE MACHINE (one plain ref object, at most one ladder live):
//   idle -> trigger (random 7-10s gap) picks a column, a length (4-7 rows)
//   and an anchor `dropRow` = currentCourse - length (so the whole span
//   already exists and propagation never has to wait on new courses).
//   OPEN phase: row (dropRow + k) collapses from a stitch to a bare rail
//   at openAt(k) = openStartTime + k*350ms, animated over a 120ms window.
//   REPAIR phase starts once every row has opened (repairStart = openStart
//   + length*350ms) and closes rows bottom-up (the newest/last-opened row
//   closes FIRST) one rung every 300ms, each with a brief latch-hook glyph
//   and a 150ms close animation, until the topmost (drop) row reseals and
//   the column matches its neighbors again — the ladder always finishes.
// ---------------------------------------------------------------------------

const COURSE_MS = 900; // one full course (row) build event
const PITCH_TARGET = 10; // px, target stitch pitch
const MIN_COLS = 14;
const MAX_COLS = 28;

const LADDER_MIN_INTERVAL_MS = 7000;
const LADDER_MAX_INTERVAL_MS = 10000;
const LADDER_MIN_LEN = 4;
const LADDER_MAX_LEN = 7;
const OPEN_STEP_MS = 350;
const OPEN_ANIM_MS = 120;
const CLOSE_STEP_MS = 300;
const CLOSE_ANIM_MS = 150;

const AGE_FADE_ROWS = 14; // rows over which a fresh stitch recedes to the muted baseline
const MUTED_BASE_ALPHA = 0.55;
const FRESH_MAX_ALPHA = 0.75; // "moderate", never full-strength per spec

// reduced-motion freeze: a static ladder frozen mid-run, not derived from RNG
const STATIC_CURRENT_COURSE = 16;
const STATIC_DROP_ROW = 11;
const STATIC_LADDER_LEN = 3; // "2-3 rows open"

function easeOutCubic(x: number): number {
  const t = 1 - x;
  return 1 - t * t * t;
}

interface LadderState {
  active: boolean;
  column: number;
  dropRow: number;
  length: number;
  openStart: number; // elapsedMs
  repairStart: number; // elapsedMs, derived at trigger time
  nextTriggerAt: number; // elapsedMs
}

export interface KnitLadderRunProps {
  className?: string;
}

export function KnitLadderRun({ className = "" }: KnitLadderRunProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "currentColor";
    let muted = "currentColor";
    let width = 0;
    let height = 0;
    let dpr = 1;
    let sized = false;
    let visible = true;

    let pitch = PITCH_TARGET;
    let cols = MIN_COLS;

    const ladder: LadderState = {
      active: false,
      column: 0,
      dropRow: 0,
      length: 0,
      openStart: 0,
      repairStart: 0,
      nextTriggerAt: LADDER_MIN_INTERVAL_MS + Math.random() * (LADDER_MAX_INTERVAL_MS - LADDER_MIN_INTERVAL_MS),
    };

    const readTokens = () => {
      const s = getComputedStyle(document.documentElement);
      fg = s.getPropertyValue("--foreground").trim() || "currentColor";
      muted = s.getPropertyValue("--ns-muted").trim() || fg;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      cols = Math.min(MAX_COLS, Math.max(MIN_COLS, Math.round(width / PITCH_TARGET)));
      pitch = width / cols;
      sized = true;
    };

    // small interlocked loop glyph — two overlapping arcs, the "stitch" unit
    const drawStitchGlyph = (cx: number, cy: number, color: string, alpha: number) => {
      if (alpha <= 0.01) return;
      const r = pitch * 0.28;
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.arc(cx, cy - r * 0.32, r, Math.PI * 0.15, Math.PI * 0.85);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(cx, cy + r * 0.32, r, Math.PI * 1.15, Math.PI * 1.85);
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    const drawNormalStitch = (cx: number, cy: number, age: number, alphaMul: number = 1) => {
      if (alphaMul <= 0.01) return;
      const fresh = Math.min(1, Math.max(0, 1 - age / AGE_FADE_ROWS));
      drawStitchGlyph(cx, cy, muted, MUTED_BASE_ALPHA * alphaMul);
      if (fresh > 0.01) drawStitchGlyph(cx, cy, fg, fresh * FRESH_MAX_ALPHA * alphaMul);
    };

    // a bare vertical rail marking an open rung, plus an optional latch-hook
    // glyph while that rung is actively closing.
    const drawRail = (cx: number, cy: number, alpha: number) => {
      if (alpha <= 0.01) return;
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = fg;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(cx, cy - pitch / 2);
      ctx.lineTo(cx, cy + pitch / 2);
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    const drawHookGlyph = (cx: number, cy: number, alpha: number) => {
      if (alpha <= 0.01) return;
      const s = pitch * 0.24;
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = fg;
      ctx.lineWidth = 1.2;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(cx, cy + s);
      ctx.lineTo(cx, cy - s * 0.2);
      ctx.arc(cx - s * 0.35, cy - s * 0.2, s * 0.35, 0, Math.PI * 1.4);
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    // renders one cell that belongs to the currently active ladder column,
    // returning true if it drew a ladder-specific state (caller skips the
    // normal stitch render in that case).
    const drawLadderCell = (rowIndex: number, cx: number, cy: number, elapsedMs: number, age: number): boolean => {
      if (!ladder.active) return false;
      const rowOffset = rowIndex - ladder.dropRow;
      if (rowOffset < 0 || rowOffset >= ladder.length) return false;

      const openAt = ladder.openStart + rowOffset * OPEN_STEP_MS;
      // rungs close bottom-up: the newest (highest offset) rung closes first
      const closeAt = ladder.repairStart + (ladder.length - 1 - rowOffset) * CLOSE_STEP_MS;

      if (elapsedMs < openAt) {
        drawNormalStitch(cx, cy, age);
        return true;
      }
      if (elapsedMs < openAt + OPEN_ANIM_MS) {
        // the loop glyph visibly collapses to a bare gap: fade the stitch
        // out while the rail fades in over the same 120ms window
        const eased = easeOutCubic((elapsedMs - openAt) / OPEN_ANIM_MS);
        drawNormalStitch(cx, cy, age, 1 - eased);
        drawRail(cx, cy, eased);
        return true;
      }
      if (elapsedMs < closeAt) {
        drawRail(cx, cy, 1);
        return true;
      }
      if (elapsedMs < closeAt + CLOSE_ANIM_MS) {
        // the latch-hook reseals the rung: stitch fades back in as the rail
        // fades out, with the hook glyph visible for the transition
        const p = (elapsedMs - closeAt) / CLOSE_ANIM_MS;
        const eased = easeOutCubic(p);
        drawRail(cx, cy, 1 - eased);
        drawNormalStitch(cx, cy, age, eased);
        drawHookGlyph(cx, cy, 1 - p);
        return true;
      }
      // fully repaired — render as a normal stitch and let this row age out
      // of ladder tracking on the next active-ladder check naturally
      return false;
    };

    const maybeAdvanceLadder = (elapsedMs: number, currentCourse: number) => {
      if (ladder.active) {
        const lastCloseAt = ladder.repairStart + (ladder.length - 1) * CLOSE_STEP_MS + CLOSE_ANIM_MS;
        if (elapsedMs >= lastCloseAt) {
          ladder.active = false;
          ladder.nextTriggerAt =
            elapsedMs + LADDER_MIN_INTERVAL_MS + Math.random() * (LADDER_MAX_INTERVAL_MS - LADDER_MIN_INTERVAL_MS);
        }
        return;
      }
      if (elapsedMs < ladder.nextTriggerAt) return;
      const length = LADDER_MIN_LEN + Math.floor(Math.random() * (LADDER_MAX_LEN - LADDER_MIN_LEN + 1));
      if (currentCourse - length < 0) return; // not enough built history yet, wait
      ladder.active = true;
      ladder.column = Math.floor(Math.random() * cols);
      ladder.length = length;
      ladder.dropRow = currentCourse - length;
      ladder.openStart = elapsedMs;
      ladder.repairStart = elapsedMs + length * OPEN_STEP_MS;
    };

    const drawField = (elapsedMs: number, staticLadder: { column: number; dropRow: number; length: number } | null) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);

      const continuousCourse = elapsedMs / COURSE_MS;
      const currentCourse = Math.floor(continuousCourse);
      const buildEdgeY = height - pitch / 2;

      const minRow = Math.floor(continuousCourse - height / pitch) - 1;

      for (let rowIndex = Math.max(0, minRow); rowIndex <= currentCourse; rowIndex++) {
        const cy = buildEdgeY - (continuousCourse - rowIndex) * pitch;
        if (cy < -pitch || cy > height + pitch) continue;
        const age = currentCourse - rowIndex;

        for (let col = 0; col < cols; col++) {
          const cx = col * pitch + pitch / 2;

          if (staticLadder) {
            const rowOffset = rowIndex - staticLadder.dropRow;
            if (col === staticLadder.column && rowOffset >= 0 && rowOffset < staticLadder.length) {
              drawRail(cx, cy, 1);
              continue;
            }
            drawNormalStitch(cx, cy, age);
            continue;
          }

          if (col === ladder.column && drawLadderCell(rowIndex, cx, cy, elapsedMs, age)) continue;
          drawNormalStitch(cx, cy, age);
        }
      }
    };

    let raf = 0;
    let startTime = 0;

    const loop = (now: number) => {
      if (!startTime) startTime = now;
      const elapsedMs = now - startTime;
      const currentCourse = Math.floor(elapsedMs / COURSE_MS);
      maybeAdvanceLadder(elapsedMs, currentCourse);
      drawField(elapsedMs, null);
      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };

    const drawReducedStatic = () => {
      const elapsedMs = STATIC_CURRENT_COURSE * COURSE_MS + COURSE_MS * 0.5;
      drawField(elapsedMs, { column: Math.floor(cols / 2), dropRow: STATIC_DROP_ROW, length: STATIC_LADDER_LEN });
    };

    const start = () => {
      if (reduced) {
        drawReducedStatic();
        return;
      }
      startTime = 0;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(loop);
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) drawReducedStatic();
      }, 120);
    };

    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible && !reduced) start();
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      if (!document.hidden && visible && !reduced) start();
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced && sized) drawReducedStatic();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    readTokens();
    resize();
    start();

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return <canvas ref={canvasRef} aria-hidden="true" className={`block h-full w-full ${className}`} />;
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// KnotCapsizeCycle — an ambient status gauge that expresses load as knot
// topology instead of a fill bar or needle. A binding knot (drawn as a fixed
// set of parametric bezier strands: two standing ends, two crossing loops)
// is breathed through a real rigging load cycle — ramp, hold, release — and
// at peak load its asymmetric crossings visibly slide and roll into a
// capsized topology before the next release lets it re-dress. This is the
// granny-knot capsize specifically: tied with the same crossings as a
// reef/square knot but the wrong second half-hitch, it slips under load
// into a different, weaker arrangement while a true reef knot would lock.
//
// Every strand is a single cubic bezier with a fixed anchor at the knot's
// core (where it attaches to its neighbour) and a free end. Two named
// control-point sets — DRESSED and CAPSIZED — describe the same four
// strands in two different rope arrangements; a single scalar `load` drives
// a ramp/hold/release cycle, and a second scalar `capsizeT` (0 = dressed,
// 1 = capsized) drives a linear interpolation between the two control-point
// sets, so the transition is always a continuous slide, never a swap. Which
// loop currently reads as "on top" is shown the way rope diagrams show it —
// a short gap cut into the strand passing underneath — and that gap swaps
// sides in lockstep with capsizeT, so the loop that was on top visibly goes
// under as it rolls through the capsize.
// ---------------------------------------------------------------------------

type Pt = { x: number; y: number };
type Cubic = { p0: Pt; p1: Pt; p2: Pt; p3: Pt };

interface KnotGeometry {
  standA: Cubic;
  standB: Cubic;
  loopA: Cubic;
  loopB: Cubic;
}

const CYCLE_MS = 8000;
const RAMP_MS = 4500;
const HOLD_MS = 1500;
const RELEASE_MS = 2000; // RAMP + HOLD + RELEASE === CYCLE_MS

const CAPSIZE_TRIGGER_LOAD = 0.92;
const REDRESS_TRIGGER_LOAD = 0.3;
const CAPSIZE_MS = 900;
const REDRESS_MS = 700;

const STAND_MODULATION = 0.06; // +/-6% standing-end reach with load

// Normalised knot space, roughly [-1, 1]; scaled by the container's smaller
// dimension at render time. Anchors (p0) are the structural attachment
// points shared between a standing end and its loop, so they never move
// between DRESSED and CAPSIZED — only the free geometry (p1, p2, p3) slides.
const DRESSED: KnotGeometry = {
  standA: { p0: { x: -1.35, y: 1.35 }, p1: { x: -0.9, y: 0.75 }, p2: { x: -0.55, y: 0.35 }, p3: { x: -0.28, y: 0.05 } },
  standB: { p0: { x: 1.35, y: -1.35 }, p1: { x: 0.9, y: -0.75 }, p2: { x: 0.55, y: -0.35 }, p3: { x: 0.28, y: -0.05 } },
  loopA: { p0: { x: -0.28, y: 0.05 }, p1: { x: -0.15, y: -0.55 }, p2: { x: 0.45, y: -0.55 }, p3: { x: 0.15, y: 0.1 } },
  loopB: { p0: { x: 0.28, y: -0.05 }, p1: { x: 0.15, y: 0.55 }, p2: { x: -0.45, y: 0.55 }, p3: { x: -0.15, y: -0.1 } },
};

// CAPSIZED: loopA has slipped off its mirror position and rolled to nest
// alongside loopB instead of crossing opposite it — the granny-knot slip.
// loopB shifts slightly too, as the strand receiving the new crossing.
const CAPSIZED: KnotGeometry = {
  standA: DRESSED.standA,
  standB: DRESSED.standB,
  loopA: { p0: { x: -0.28, y: 0.05 }, p1: { x: -0.55, y: -0.15 }, p2: { x: -0.45, y: 0.55 }, p3: { x: 0.15, y: 0.35 } },
  loopB: { p0: { x: 0.28, y: -0.05 }, p1: { x: 0.55, y: 0.15 }, p2: { x: 0.2, y: 0.6 }, p3: { x: -0.2, y: 0.25 } },
};

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

function lerpPt(a: Pt, b: Pt, t: number): Pt {
  return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t) };
}

function lerpCubic(a: Cubic, b: Cubic, t: number): Cubic {
  return { p0: lerpPt(a.p0, b.p0, t), p1: lerpPt(a.p1, b.p1, t), p2: lerpPt(a.p2, b.p2, t), p3: lerpPt(a.p3, b.p3, t) };
}

function easeInOutSine(t: number): number {
  return 0.5 * (1 - Math.cos(Math.PI * t));
}

/** De Casteljau split of a cubic bezier at parameter t: returns the two
 * sub-curves [0,t] and [t,1], each reparametrised to [0,1]. */
function splitCubic(c: Cubic, t: number): { left: Cubic; right: Cubic } {
  const p01 = lerpPt(c.p0, c.p1, t);
  const p12 = lerpPt(c.p1, c.p2, t);
  const p23 = lerpPt(c.p2, c.p3, t);
  const p012 = lerpPt(p01, p12, t);
  const p123 = lerpPt(p12, p23, t);
  const p0123 = lerpPt(p012, p123, t);
  return {
    left: { p0: c.p0, p1: p01, p2: p012, p3: p0123 },
    right: { p0: p0123, p1: p123, p2: p23, p3: c.p3 },
  };
}

/** Sub-curve of `c` covering original parameter range [ta, tb] (0 <= ta < tb <= 1). */
function subCubic(c: Cubic, ta: number, tb: number): Cubic {
  const afterTa = splitCubic(c, ta).right;
  const localTb = (tb - ta) / (1 - ta);
  return splitCubic(afterTa, localTb).left;
}

function cubicToD(c: Cubic, ox: number, oy: number, s: number): string {
  const x = (n: number) => (ox + n * s).toFixed(2);
  const y = (n: number) => (oy + n * s).toFixed(2);
  return `M${x(c.p0.x)} ${y(c.p0.y)}C${x(c.p1.x)} ${y(c.p1.y)},${x(c.p2.x)} ${y(c.p2.y)},${x(c.p3.x)} ${y(c.p3.y)}`;
}

/** Renders a loop strand as one continuous path, or as two segments with a
 * gap cut around t=0.5 when `underAmount` (0..1) is > 0 — the rope-diagram
 * convention for "this strand passes underneath here". Gap half-width
 * grows from 0 to 0.09 in curve-parameter units as underAmount goes 0..1. */
function loopStrandPaths(c: Cubic, underAmount: number, ox: number, oy: number, s: number): string[] {
  if (underAmount <= 0.001) return [cubicToD(c, ox, oy, s)];
  const half = 0.09 * underAmount;
  const segments: string[] = [];
  if (0.5 - half > 0.02) segments.push(cubicToD(subCubic(c, 0, 0.5 - half), ox, oy, s));
  if (0.5 + half < 0.98) segments.push(cubicToD(subCubic(c, 0.5 + half, 1), ox, oy, s));
  return segments;
}

/** Standing-end reach modulates +/-6% with load: pulled taut (longer,
 * straighter) as load rises, slack (shorter reach) as it falls. Only the
 * free end (p0) moves; the anchor stays fixed at the knot core. */
function tightenStand(c: Cubic, load: number): Cubic {
  const scale = 1 + STAND_MODULATION * (load - 0.5) * 2;
  const dx = c.p0.x - c.p3.x;
  const dy = c.p0.y - c.p3.y;
  return { ...c, p0: { x: c.p3.x + dx * scale, y: c.p3.y + dy * scale } };
}

// CAPSIZE_MIDWAY: the reduced-motion freeze frame. capsizeT frozen at 0.5 —
// mid-slide, neither dressed nor capsized, the single most structurally
// informative frame — with load held at the capsize trigger point so the
// standing ends read taut, matching the moment this frame is drawn from.
const REDUCED_MOTION_CAPSIZE_T = 0.5;
const REDUCED_MOTION_LOAD = CAPSIZE_TRIGGER_LOAD;

export interface KnotCapsizeCycleProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function KnotCapsizeCycle({ className = "" }: KnotCapsizeCycleProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const standARef = useRef<SVGPathElement>(null);
  const standBRef = useRef<SVGPathElement>(null);
  const loopAGroupRef = useRef<SVGGElement>(null);
  const loopBGroupRef = useRef<SVGGElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const svg = svgRef.current;
    if (!root || !svg) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let visible = true;
    let w = 0;
    let h = 0;
    let sized = false;
    let raf = 0;

    // capsize state machine: capsizeT 0 = dressed, 1 = capsized.
    let capsizeT = 0;
    let capsizePhase: "idle" | "capsizing" | "capsized" | "redressing" = "idle";
    let capsizeStart = 0;
    let lastCycleIndex = -1;
    let capsizeTriggeredThisCycle = false;
    let redressTriggeredThisCycle = false;

    const render = (load: number, t: number) => {
      const s = Math.min(w, h) * 0.39;
      const ox = w / 2;
      const oy = h / 2;

      const standA = tightenStand(lerpCubic(DRESSED.standA, CAPSIZED.standA, t), load);
      const standB = tightenStand(lerpCubic(DRESSED.standB, CAPSIZED.standB, t), load);
      const loopA = lerpCubic(DRESSED.loopA, CAPSIZED.loopA, t);
      const loopB = lerpCubic(DRESSED.loopB, CAPSIZED.loopB, t);

      // At t=0 (dressed) loopA is under, loopB is over; at t=1 (capsized)
      // that flips. The gap amount tracks the interpolation continuously so
      // the "which one's on top" cue slides in step with the geometry.
      const loopAUnder = 1 - t;
      const loopBUnder = t;

      standARef.current?.setAttribute("d", cubicToD(standA, ox, oy, s));
      standBRef.current?.setAttribute("d", cubicToD(standB, ox, oy, s));

      const paintGroup = (group: SVGGElement | null, c: Cubic, underAmount: number) => {
        if (!group) return;
        const segs = loopStrandPaths(c, underAmount, ox, oy, s);
        while (group.children.length > segs.length) group.removeChild(group.lastChild as ChildNode);
        segs.forEach((d, i) => {
          let path = group.children[i] as SVGPathElement | undefined;
          if (!path) {
            path = document.createElementNS("http://www.w3.org/2000/svg", "path");
            path.setAttribute("fill", "none");
            path.setAttribute("stroke", "currentColor");
            path.setAttribute("stroke-width", "2.5");
            path.setAttribute("stroke-linecap", "round");
            group.appendChild(path);
          }
          path.setAttribute("d", d);
        });
      };

      // draw order: whichever loop is currently "over" is appended last so
      // it visually sits on top of the other at the crossing.
      if (loopAUnder >= loopBUnder) {
        paintGroup(loopAGroupRef.current, loopA, loopAUnder);
        paintGroup(loopBGroupRef.current, loopB, loopBUnder);
        svg.querySelector("#knot-loops")?.append(...[loopAGroupRef.current, loopBGroupRef.current].filter(Boolean) as SVGGElement[]);
      } else {
        paintGroup(loopAGroupRef.current, loopA, loopAUnder);
        paintGroup(loopBGroupRef.current, loopB, loopBUnder);
        svg.querySelector("#knot-loops")?.append(...[loopBGroupRef.current, loopAGroupRef.current].filter(Boolean) as SVGGElement[]);
      }
    };

    const loadAt = (cyclePos: number): number => {
      if (cyclePos < RAMP_MS) return easeInOutSine(cyclePos / RAMP_MS);
      if (cyclePos < RAMP_MS + HOLD_MS) return 1;
      const releaseT = (cyclePos - RAMP_MS - HOLD_MS) / RELEASE_MS;
      return 1 - easeInOutSine(Math.min(1, releaseT));
    };

    const step = (now: number, elapsed: number) => {
      const cyclePos = elapsed % CYCLE_MS;
      const cycleIndex = Math.floor(elapsed / CYCLE_MS);
      if (cycleIndex !== lastCycleIndex) {
        lastCycleIndex = cycleIndex;
        capsizeTriggeredThisCycle = false;
        redressTriggeredThisCycle = false;
      }

      const load = loadAt(cyclePos);
      const inRamp = cyclePos < RAMP_MS;
      const inRelease = cyclePos >= RAMP_MS + HOLD_MS;

      if (inRamp && !capsizeTriggeredThisCycle && load >= CAPSIZE_TRIGGER_LOAD) {
        capsizeTriggeredThisCycle = true;
        capsizePhase = "capsizing";
        capsizeStart = now;
      }
      if (inRelease && capsizeTriggeredThisCycle && !redressTriggeredThisCycle && load <= REDRESS_TRIGGER_LOAD) {
        redressTriggeredThisCycle = true;
        capsizePhase = "redressing";
        capsizeStart = now;
      }

      if (capsizePhase === "capsizing") {
        const p = Math.min(1, (now - capsizeStart) / CAPSIZE_MS);
        capsizeT = easeInOutSine(p);
        if (p >= 1) capsizePhase = "capsized";
      } else if (capsizePhase === "redressing") {
        const p = Math.min(1, (now - capsizeStart) / REDRESS_MS);
        capsizeT = 1 - easeInOutSine(p);
        if (p >= 1) capsizePhase = "idle";
      }

      render(load, capsizeT);
    };

    let startTime = 0;
    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized) return;
      if (startTime === 0) startTime = now;
      step(now, now - startTime);
      raf = requestAnimationFrame(loop);
    };

    const measure = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      sized = w >= 2 && h >= 2;
    };

    const start = () => {
      measure();
      if (!sized) return;
      if (reduced) {
        render(REDUCED_MOTION_LOAD, REDUCED_MOTION_CAPSIZE_T);
        return;
      }
      if (!raf) raf = requestAnimationFrame(loop);
    };

    // no paint before the first size + token-carrying layout is settled
    start();

    let resizeTimer = 0;
    const ro = new ResizeObserver(() => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        measure();
        if (sized && !raf && !reduced) {
          raf = requestAnimationFrame(loop);
        } else if (sized && reduced) {
          render(REDUCED_MOTION_LOAD, REDUCED_MOTION_CAPSIZE_T);
        }
      }, 100);
    });
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && sized && !raf && !reduced) {
        startTime = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
    };
  }, []);

  return (
    <div ref={rootRef} className={`relative aspect-square w-full ${className}`}>
      <svg
        ref={svgRef}
        aria-hidden="true"
        focusable="false"
        className="h-full w-full"
        style={{ color: "var(--foreground)" }}
      >
        <g id="knot-loops">
          <g ref={loopAGroupRef} />
          <g ref={loopBGroupRef} />
        </g>
        <path ref={standARef} d="" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" />
        <path ref={standBRef} d="" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" />
      </svg>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// LcdResponseSmear — an ambient panel-diagnostics status card whose canvas
// strip simulates LCD pixel response time compensation (RTC / overdrive): a
// liquid-crystal cell doesn't switch luminance instantly between grey
// levels, and rise/fall are asymmetric (rise faster, fall slower on typical
// TN/IPS spec sheets). Panel drivers overdrive the transition — push past
// the target voltage, then relax back — producing a brief bright overshoot
// on a rising transition. Falling transitions are usually driven less
// aggressively, so instead of overshooting past the target they UNDERSHOOT
// it: the cell lags behind the ideal step and arrives at its dark target
// later and more gradually. That rise-overshoots / fall-undershoots
// asymmetry is the "inverse ghost" visible trailing fast light-on-dark UI in
// reviews of LCD panels with aggressive overdrive — this card renders it as
// a single sweeping fill boundary crossing a row of cells: cells left of the
// boundary are lit, cells right are unlit, and the boundary ping-pongs
// across the strip. Every cell it newly lights up plays the rise-overshoot
// curve; every cell it newly darkens (boundary retreating past it) plays
// the fall-undershoot curve — both computed relative to each cell's own
// local start/end luminance, never an absolute white/black, so the effect
// self-corrects across light/dark themes for free.
//
// NOT motion blur: kelvin-wake, and this project's other trailing-wake
// components, render a continuous gradient smear. This is a discrete
// per-cell luminance curve with two distinct named keyframes (a peak or dip,
// then a settle) — an instant state change at the moment the boundary
// crosses a cell, not a spatial blur convolved across the frame. NOT
// cursor-subpixel-fringe either — that's a spatial subpixel-geometry
// artifact; this is a purely temporal per-pixel response curve.
//
// REAL NUMBERS (see riseCurve / fallCurve below):
//   rise: overshoots to 1.18x the local luminance delta, settles to 1.0x
//   (spec: t+4ms peak, t+9ms settle, tau_rise ~= 6ms).
//   fall: undershoots — reaches only 0.90x of the local delta before it has
//   fully arrived (spec: t+6ms), then eases the rest of the way, settling
//   to 1.0x (spec: t+15ms, tau_fall ~= 11ms). Falling literally takes
//   longer and lags rather than punching through the target, which is the
//   asymmetry real GtG spec sheets report (fall consistently slower than
//   rise). DEVIATION FROM SPEC, DELIBERATE: those millisecond values are
//   real, but at 220px/s a genuine 9ms/15ms transition only spans ~2-3px —
//   thinner than one CELL_PX floor, i.e. invisible. The keyframe TIMES
//   below are the spec's real numbers x20 (RISE_PEAK/SETTLE_MS,
//   FALL_DIP/SETTLE_MS) so the halo spans several cells and reads as the
//   asymmetric spike it's supposed to be; every RATIO that carries the
//   mechanic's identity (4:9, 6:15, the 6:11 tau ratio, 1.18x, 0.90x) is
//   exactly preserved. The footer readout still states the true panel
//   numbers (6ms / 11ms) — only the on-screen playback speed is dilated,
//   the same way a macro lens dilates space rather than lying about it.
//   sweep velocity v(t) = 220 * (1 + 0.15*sin(2*PI*t / 9.1)) px/s, boundary
//   position ping-pongs off the strip's own edges; the slow, non-round
//   9.1s modulation keeps the bounce from reading as a metronomic loop.
//
// Geometry: CELL_PX = max(6, containerMinDim / 56), a single row of cells
// spanning the strip's own width, containerMinDim taken from the CARD's own
// bounding rect (not the thin strip's) so the pattern scales with the card
// as a whole rather than reading as one fixed pixel size regardless of how
// large the card is laid out.
//
// House idiom duplicated on purpose (no shared helpers, per project
// convention): tokens (--background / --foreground only — this is value,
// never hue) read via getComputedStyle(document.documentElement) inside a
// pre-paint effect and re-read on a MutationObserver watching
// documentElement's class; one rAF loop paused on document visibilitychange
// and an IntersectionObserver on the strip; DPR-capped(2) backing store
// with a ResizeObserver-driven resize and a zero-size guard.
//
// prefers-reduced-motion: no rAF loop. A single frame is composed by
// deterministically replaying the same boundary-integration + per-cell
// crossing logic from t=0 up to STATIC_TIME = 0.85s (so the boundary lands
// somewhere real, not an arbitrary fixed spot), then the render pass pins
// whichever cell was crossed most recently to the exact peak/dip instant of
// its curve (rise: t+4ms, fall: t+6ms) instead of whatever age it actually
// has — guaranteeing the frozen frame always shows the climactic overshoot
// halo rather than risking landing on an already-settled, plain static
// edge for some container sizes.
// ---------------------------------------------------------------------------

const CELL_MIN_PX = 6;
const CELL_DIVISOR = 56;

const SWEEP_BASE_V = 220; // px/s
const SWEEP_MOD_AMP = 0.15;
const SWEEP_MOD_PERIOD = 9.1; // s, deliberately non-round

// x20 time-dilation of the spec's real 4/9/6/15ms keyframes — see the
// header comment. Ratios (4:9, 6:15, 1.18x, 0.90x) are exact; only the
// playback speed is stretched so the halo is wide enough to see.
const TIME_DILATION = 20;
const RISE_PEAK = 1.18;
const RISE_PEAK_MS = 4 * TIME_DILATION;
const RISE_SETTLE_MS = 9 * TIME_DILATION;

const FALL_DIP = 0.9;
const FALL_DIP_MS = 6 * TIME_DILATION;
const FALL_SETTLE_MS = 15 * TIME_DILATION;

// Interior grey levels rather than pure 0/1: at LIT=1 the 18% rise
// overshoot extrapolates past the foreground token and clamps, losing most
// of its visible amplitude. Sitting the settled levels inside the range
// leaves headroom on both sides for the over/undershoot to actually show.
const LIT = 0.86;
const UNLIT = 0.06;

const STATIC_TIME_S = 0.85;

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

function smoothstep(a: number, b: number, x: number): number {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// Fraction of the local luminance delta reached at `ms` since a cell was
// newly lit. Overshoots to RISE_PEAK before easing back down to 1.0.
function riseCurve(ms: number): number {
  if (ms <= 0) return 0;
  if (ms < RISE_PEAK_MS) return smoothstep(0, RISE_PEAK_MS, ms) * RISE_PEAK;
  if (ms < RISE_SETTLE_MS) {
    const t = smoothstep(RISE_PEAK_MS, RISE_SETTLE_MS, ms);
    return RISE_PEAK + (1 - RISE_PEAK) * t;
  }
  return 1;
}

// Fraction of the local luminance delta reached at `ms` since a cell was
// newly darkened. Undershoots (lags short of the target) at FALL_DIP before
// easing the rest of the way in — no overshoot past 1, a slower catch-up.
function fallCurve(ms: number): number {
  if (ms <= 0) return 0;
  if (ms < FALL_DIP_MS) return smoothstep(0, FALL_DIP_MS, ms) * FALL_DIP;
  if (ms < FALL_SETTLE_MS) {
    const t = smoothstep(FALL_DIP_MS, FALL_SETTLE_MS, ms);
    return FALL_DIP + (1 - FALL_DIP) * t;
  }
  return 1;
}

function settleMsFor(kind: 1 | -1): number {
  return kind === 1 ? RISE_SETTLE_MS : FALL_SETTLE_MS;
}
function peakMsFor(kind: 1 | -1): number {
  return kind === 1 ? RISE_PEAK_MS : FALL_DIP_MS;
}

type Vec3 = [number, number, number];

// Same parse+mix idiom used elsewhere in this registry (e.g.
// table-heat-shimmer) — duplicated per house convention rather than shared.
function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0]! + hex[0], 16);
      const g = parseInt(hex[1]! + hex[1], 16);
      const b = parseInt(hex[2]! + hex[2], 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// Lerp (and, for overshoot/undershoot fractions outside [0,1], deliberately
// EXTRAPOLATE) between two colours, clamped per-channel so an 18% overshoot
// never wraps past a byte.
function mixExtrapolate(a: Vec3, b: Vec3, t: number): Vec3 {
  return [
    clamp(Math.round(a[0] + (b[0] - a[0]) * t), 0, 255),
    clamp(Math.round(a[1] + (b[1] - a[1]) * t), 0, 255),
    clamp(Math.round(a[2] + (b[2] - a[2]) * t), 0, 255),
  ];
}

interface CellSim {
  cellCount: number;
  kind: Int8Array; // 0 none, 1 rise, -1 fall
  transStart: Float64Array; // ms, timeline-local
  // Settled target level for a cell with kind === 0 (0 = unlit, 1 = lit).
  // Read directly rather than re-derived from the boundary's current
  // position — deriving it from position instead caused every cell to
  // flicker dark-then-lit right as its transition settled, because
  // crossing detection keys off cell EDGES (floor(idx)) while position
  // comparison keys off cell CENTERS, and those two didn't agree at settle
  // time. `level` is authoritative and updated only at crossing.
  level: Int8Array;
}

function makeSim(cellCount: number, seedPos: number, cellPx: number): CellSim {
  const level = new Int8Array(cellCount);
  for (let i = 0; i < cellCount; i++) {
    level[i] = (i + 0.5) * cellPx < seedPos ? 1 : 0;
  }
  return {
    cellCount,
    kind: new Int8Array(cellCount),
    transStart: new Float64Array(cellCount).fill(-Infinity),
    level,
  };
}

/** One boundary-integration step: advances pos/sign by dtSec at simTimeS,
 * and marks every cell the boundary newly crossed as rise (lighting up,
 * boundary advancing) or fall (darkening, boundary retreating), timestamped
 * at `nowMs` on whatever timeline the caller is running (real or replayed). */
function stepSim(
  sim: CellSim,
  cellPx: number,
  trackW: number,
  state: { pos: number; sign: 1 | -1; simTimeS: number },
  dtSec: number,
  nowMs: number
): void {
  if (trackW <= 0 || dtSec <= 0) return;
  const prevIdxF = state.pos / cellPx;
  state.simTimeS += dtSec;
  const speed = SWEEP_BASE_V * (1 + SWEEP_MOD_AMP * Math.sin((2 * Math.PI * state.simTimeS) / SWEEP_MOD_PERIOD));
  let pos = state.pos + speed * state.sign * dtSec;
  let sign = state.sign;
  if (pos > trackW) {
    pos = 2 * trackW - pos;
    sign = -1;
  } else if (pos < 0) {
    pos = -pos;
    sign = 1;
  }
  state.pos = clamp(pos, 0, trackW);
  state.sign = sign;
  const newIdxF = state.pos / cellPx;

  const cellCount = sim.cellCount;
  if (newIdxF > prevIdxF) {
    const lo = Math.max(0, Math.floor(prevIdxF));
    const hi = Math.min(cellCount - 1, Math.floor(newIdxF));
    for (let i = lo + (prevIdxF > lo ? 1 : 0); i <= hi; i++) {
      sim.kind[i] = 1;
      sim.transStart[i] = nowMs;
      sim.level[i] = 1;
    }
  } else if (newIdxF < prevIdxF) {
    const lo = Math.max(0, Math.floor(newIdxF));
    const hi = Math.min(cellCount - 1, Math.floor(prevIdxF));
    for (let i = hi; i >= lo + 1; i--) {
      sim.kind[i] = -1;
      sim.transStart[i] = nowMs;
      sim.level[i] = 0;
    }
  }
}

function renderSim(
  ctx: CanvasRenderingContext2D,
  sim: CellSim,
  cellPx: number,
  trackW: number,
  h: number,
  nowMs: number,
  bg: Vec3,
  fg: Vec3
): void {
  ctx.clearRect(0, 0, trackW, h);
  const gap = Math.max(1, cellPx * 0.08);
  for (let i = 0; i < sim.cellCount; i++) {
    const kind = sim.kind[i] as 0 | 1 | -1;
    let lum: number;
    if (kind !== 0) {
      let elapsed = nowMs - sim.transStart[i]!;
      const settle = settleMsFor(kind);
      if (elapsed >= settle) {
        sim.kind[i] = 0;
        lum = kind === 1 ? LIT : UNLIT;
      } else {
        if (elapsed < 0) elapsed = 0;
        const frac = kind === 1 ? riseCurve(elapsed) : fallCurve(elapsed);
        const from = kind === 1 ? UNLIT : LIT;
        const to = kind === 1 ? LIT : UNLIT;
        lum = from + (to - from) * frac;
      }
    } else {
      lum = sim.level[i] ? LIT : UNLIT;
    }
    const [r, g, b] = mixExtrapolate(bg, fg, lum);
    ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
    ctx.fillRect(i * cellPx, 0, Math.max(1, cellPx - gap), h);
  }
}

export interface LcdResponseSmearProps {
  /** small mono eyebrow above the title */
  eyebrow?: string;
  /** card title */
  title?: string;
  /** supporting description under the title */
  description?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function LcdResponseSmear({
  eyebrow = "PANEL DIAGNOSTICS",
  title = "Response compensation",
  description = "Overdrive pushes each cell past its target voltage to hit its advertised switching time — the trace below is a simulated row of LCD cells lighting and darkening as a boundary sweeps across them, each rise overshooting its target before settling, each fall lagging behind before it catches up.",
  className = "",
}: LcdResponseSmearProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const stripRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    const strip = stripRef.current;
    const canvas = canvasRef.current;
    if (!root || !strip || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    // No colour literal fallbacks, per project rule — null until the first
    // real token read succeeds, and every draw path below guards on it so
    // nothing can paint before that first read.
    let bg: Vec3 | null = null;
    let fg: Vec3 | null = null;
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      bg = parseColor(cs.getPropertyValue("--background")) ?? bg;
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    readTokens();

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let raf = 0;
    let running = false;
    let visible = true;

    let cellPx = CELL_MIN_PX;
    let trackW = 0;
    let trackH = 0;
    let sim = makeSim(0, 0, CELL_MIN_PX);
    const state = { pos: 0, sign: 1 as 1 | -1, simTimeS: 0 };
    let lastTs = 0;

    const draw = (nowMs: number) => {
      if (!bg || !fg) return; // no paint before the first token read
      renderSim(ctx, sim, cellPx, trackW, trackH, nowMs, bg, fg);
    };

    const drawStatic = () => {
      if (trackW <= 0 || cellPx <= 0 || !bg || !fg) return;
      // Seed the replay at the same t0 boundary position the live loop
      // starts from, so the static frame and the live t0 frame agree.
      const seedPos = 0.38 * trackW;
      const localSim = makeSim(sim.cellCount, seedPos, cellPx);
      const localState = { pos: seedPos, sign: 1 as 1 | -1, simTimeS: 0 };
      const dt = 1 / 240;
      let nowMs = 0;
      const targetMs = STATIC_TIME_S * 1000;
      while (nowMs < targetMs) {
        const step = Math.min(dt, (targetMs - nowMs) / 1000);
        stepSim(localSim, cellPx, trackW, localState, step, nowMs + step * 1000);
        nowMs += step * 1000;
      }
      // Find the most recently triggered transition and pin its render age
      // to its curve's named peak/dip instant, guaranteeing the frozen
      // frame shows the climactic halo rather than an already-settled edge.
      let pinIdx = -1;
      let pinStart = -Infinity;
      for (let i = 0; i < localSim.cellCount; i++) {
        if (localSim.kind[i] !== 0 && localSim.transStart[i]! > pinStart) {
          pinStart = localSim.transStart[i]!;
          pinIdx = i;
        }
      }
      if (pinIdx >= 0) {
        const kind = localSim.kind[pinIdx] as 1 | -1;
        localSim.transStart[pinIdx] = targetMs - peakMsFor(kind);
      }
      renderSim(ctx, localSim, cellPx, trackW, trackH, targetMs, bg, fg);
    };

    const loop = (ts: number) => {
      if (disposed) return;
      const dtMs = lastTs === 0 ? 16 : Math.min(100, ts - lastTs);
      lastTs = ts;
      stepSim(sim, cellPx, trackW, state, dtMs / 1000, ts);
      draw(ts);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || reduced) return;
      running = true;
      lastTs = 0;
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      raf = 0;
      running = false;
    };

    const resize = () => {
      const cardRect = root.getBoundingClientRect();
      const containerMinDim = Math.max(1, Math.min(cardRect.width, cardRect.height));
      cellPx = Math.max(CELL_MIN_PX, containerMinDim / CELL_DIVISOR);

      const rect = strip.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return; // zero-size guard
      trackW = rect.width;
      trackH = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(trackW * dpr);
      canvas.height = Math.round(trackH * dpr);
      canvas.style.width = `${trackW}px`;
      canvas.style.height = `${trackH}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const cellCount = Math.max(4, Math.floor(trackW / cellPx));
      // t0 must be mid-sweep, not blank — seed the boundary partway across
      // the strip rather than at 0 (spec: "t0: edge mid-sweep").
      const seedPos = 0.38 * trackW;
      sim = makeSim(cellCount, seedPos, cellPx);
      state.pos = seedPos;
      state.sign = 1;
      state.simTimeS = 0;
      lastTs = 0;

      if (reduced) drawStatic();
    };

    const ro = new ResizeObserver(resize);
    ro.observe(root);
    ro.observe(strip);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[entries.length - 1]?.isIntersecting ?? true;
        if (!reduced) {
          if (visible) wake();
          else sleep();
        }
      },
      { threshold: 0 }
    );
    io.observe(strip);

    const themeObserver = new MutationObserver(() => {
      readTokens();
      if (reduced) drawStatic();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onVis = () => {
      if (reduced) return;
      if (document.hidden) sleep();
      else if (visible) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    resize();
    if (!reduced) wake();
    else drawStatic();

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      themeObserver.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      sleep();
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`rounded-md border border-border bg-background p-5 ${className}`}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="font-mono text-[11px] tracking-widest text-ns-muted">{eyebrow}</p>
          <h3 className="mt-1 text-base font-semibold text-foreground">{title}</h3>
        </div>
        <span className="shrink-0 rounded-sm border border-border px-2 py-0.5 font-mono text-[10px] text-ns-muted">
          RTC
        </span>
      </div>
      <p className="mt-2 text-sm leading-relaxed text-ns-muted">{description}</p>
      <div
        ref={stripRef}
        aria-hidden="true"
        className="relative mt-4 h-16 w-full overflow-hidden rounded-sm border border-border sm:h-20"
      >
        <canvas ref={canvasRef} className="block h-full w-full" />
      </div>
      <div className="mt-3 flex items-center justify-between font-mono text-[10px] text-ns-muted">
        <span>RISE τ 6ms</span>
        <span>FALL τ 11ms</span>
        <span>OVERDRIVE COMPENSATED</span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// LeavenCrestFall — a sourdough starter jar rendered as a live status
// gauge: the surface dome rises to a blistered peak on CO2 from
// fermentation, then collapses as gas escapes, fed again, and rises again —
// forever. Card-scale SVG only, no canvas.
//
// TIMING. One cycle is 12.6s: an 8s logistic RISE from a residual settled
// height up to 2.4x that baseline, a 4s exponential-decay FALL back down to
// ~1.05x baseline (real starter never returns fully flat — a thin residual
// film/height is what's left before the next feed), then a 600ms FEED pulse
// (a brief brightness flash standing in for fresh flour/water going in)
// before the next rise starts. `n(t)` in [0,1] is the normalised rise
// fraction; the dome's height multiplier is `1 + 1.4*n`, so n=0 is baseline
// (1.0x) and n=1 is peak (2.4x). N_SETTLE = 0.05/1.4 ~= 0.0357 is the floor
// n never goes below after a fall, which is exactly what keeps the fall's
// exponential decay landing at 1.05x rather than 1.0x.
//
// DOME SHAPE. The surface is sampled at DOME_SAMPLES x-positions across the
// jar's interior width every frame; each sample's y-offset above the
// baseline is `riseAmplitude(t) * bump(x)` (a raised-cosine bump, zero at
// the jar walls, 1 at the centre) plus a small two-harmonic ripple that
// slowly rotates phase over wall-clock time — the ripple's job is purely to
// keep the surface visibly non-static during any *flat-ish* stretch of the
// rise/fall curve (e.g. right at the peak hold), independent of the
// rise/fall amplitude itself. Samples are joined into one smooth path with
// successive quadratic curves through each pair's midpoint (a cheap
// Catmull-Rom-ish smoothing that needs no extra library), then closed down
// to the jar's fixed floor to fill the whole starter body.
//
// BUBBLES. Surface blistering is a real Poisson arrival process, not
// decoration bolted on top: during the rise phase only, each frame has a
// `LAMBDA * dt` chance of nucleating one new bubble at a random x along the
// dome, with radius growing as `R0 * age^0.3` up to MAX_R (the real
// power-law growth shape of a gas bubble breaking a viscous surface, capped
// for legibility). During the fall phase the live population is walked DOWN
// to a target count computed directly from n(t) — `target =
// peakCount * (n - N_SETTLE) / (1 - N_SETTLE)` — so the number of bubbles on
// screen is causally tied to the height curve's own decay, not an
// independently-timed decoration; bubbles at or below the target are told to
// pop (radius eased to 0 over 120ms, smallest first) exactly as fast as the
// dome itself is falling. A fixed-size pool of BUBBLE_POOL <circle> elements
// is pre-rendered once and reused (r set to 0 when inactive) so the DOM node
// count never changes across a cycle.
//
// Every per-frame numeric write (the dome path's `d`, each bubble's cx/cy/r,
// the feed-flash overlay's opacity) goes straight to the DOM via refs inside
// one rAF loop — no per-frame setState, so React never re-renders during
// the animation. A single low-frequency (~1Hz) status-text update is the
// only state write once mounted.
//
// prefers-reduced-motion freezes at t=8000ms of the 12.6s cycle (the crest
// exactly at its peak: maximum dome height, maximum bubble count) — the
// most structured, information-dense frame, deliberately not t0. That exact
// state is precomputed once from a small seeded PRNG so a reduced-motion
// render is deterministic rather than "whatever the rAF loop happened to be
// doing when it got told to stop."
//
// Colours are read straight off CSS custom properties in every fill/stroke
// (var(--foreground)/var(--ns-muted)/var(--border)/var(--background)) —
// zero literals, zero getComputedStyle: a theme flip repaints for free.
// Geometry lives in one fixed SVG viewBox scaled by preserveAspectRatio
// ("xMidYMid meet"), which is what makes it read at card scale — the
// coordinate system is uniformly fit to whichever of the container's two
// dimensions is smaller, the same mechanism `cambium-lay` uses.
// ---------------------------------------------------------------------------

export interface LeavenCrestFallProps {
  className?: string;
}

const VB_W = 200;
const VB_H = 220;

const JAR_LEFT = 46;
const JAR_RIGHT = 154;
const JAR_TOP = 20;
const JAR_BOTTOM = 196;
const JAR_CX = (JAR_LEFT + JAR_RIGHT) / 2;

const BASE_Y = 108; // baseline (1.0x) dome surface height
const CREST_MAX_RISE = 48; // viewBox units of headspace the crest can climb into at n=1

const RISE_MS = 8000;
const FALL_MS = 4000;
const FEED_MS = 600;
const CYCLE_MS = RISE_MS + FALL_MS + FEED_MS; // 12600

const N_SETTLE = 0.05 / 1.4; // ~0.0357 — floor n never falls below
const RISE_SIGMOID_K = 9; // logistic steepness

const DOME_SAMPLES = 22;
const RIPPLE_AMPL = 1.1;
const RIPPLE_OMEGA = 0.5; // rad/s — slow phase rotation, keeps the surface alive even mid-plateau

const LAMBDA = 0.8; // bubbles/sec nucleation rate during rise
const R0 = 1.4;
const MAX_R = 3.4;
const POP_MS = 120;
const BUBBLE_POOL = 30;

type Bubble = {
  active: boolean;
  x: number;
  birth: number; // ms, performance.now() timestamp
  r: number;
  poppingAt: number | null;
  poppedFromR: number;
};

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

// normalised sigmoid: sig(0)=0, sig(1)=1
function sigmoidNorm(u: number, k: number): number {
  const s0 = 1 / (1 + Math.exp(k * 0.5));
  const s1 = 1 / (1 + Math.exp(-k * 0.5));
  const s = 1 / (1 + Math.exp(-k * (u - 0.5)));
  return (s - s0) / (s1 - s0);
}

// n(t) for t = ms elapsed within one cycle, in [0, CYCLE_MS)
function riseFraction(cycleT: number): number {
  if (cycleT < RISE_MS) {
    const u = cycleT / RISE_MS;
    return N_SETTLE + (1 - N_SETTLE) * sigmoidNorm(u, RISE_SIGMOID_K);
  }
  if (cycleT < RISE_MS + FALL_MS) {
    const u = (cycleT - RISE_MS) / FALL_MS;
    return N_SETTLE + (1 - N_SETTLE) * Math.exp(-3 * u);
  }
  return N_SETTLE;
}

// derivative-ish phase flag: are we in the fall window right now
function isFalling(cycleT: number): boolean {
  return cycleT >= RISE_MS && cycleT < RISE_MS + FALL_MS;
}

function isFeeding(cycleT: number): boolean {
  return cycleT >= RISE_MS + FALL_MS;
}

function bumpFn(u: number): number {
  // raised cosine (Hann window), u in [0,1]: 0 at both edges, 1 at centre
  return (1 - Math.cos(u * Math.PI * 2)) / 2;
}

function domeAmplitude(n: number): number {
  return CREST_MAX_RISE * n;
}

function buildDomePath(sampleYs: number[], sampleXs: number[]): string {
  const n = sampleYs.length;
  let d = `M ${sampleXs[0]},${sampleYs[0]}`;
  for (let i = 0; i < n - 1; i++) {
    const mx = (sampleXs[i] + sampleXs[i + 1]) / 2;
    const my = (sampleYs[i] + sampleYs[i + 1]) / 2;
    d += ` Q ${sampleXs[i]},${sampleYs[i]} ${mx},${my}`;
  }
  d += ` L ${sampleXs[n - 1]},${sampleYs[n - 1]} L ${JAR_RIGHT},${JAR_BOTTOM} L ${JAR_LEFT},${JAR_BOTTOM} Z`;
  return d;
}

// Deterministic seeded PRNG (mulberry32) so the reduced-motion frame is stable.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildReducedFrame(): { domeD: string; bubbles: { x: number; y: number; r: number }[] } {
  const n = riseFraction(RISE_MS); // exactly the peak, n -> 1
  const amp = domeAmplitude(n);
  const xs: number[] = [];
  const ys: number[] = [];
  for (let i = 0; i < DOME_SAMPLES; i++) {
    const u = i / (DOME_SAMPLES - 1);
    const x = JAR_LEFT + u * (JAR_RIGHT - JAR_LEFT);
    const y = BASE_Y - amp * bumpFn(u);
    xs.push(x);
    ys.push(y);
  }
  const domeD = buildDomePath(ys, xs);

  const rnd = mulberry32(1337);
  const bubbles: { x: number; y: number; r: number }[] = [];
  const count = 14; // representative peak-population count for the frozen frame
  for (let i = 0; i < count; i++) {
    const u = 0.08 + rnd() * 0.84;
    const x = JAR_LEFT + u * (JAR_RIGHT - JAR_LEFT);
    const y = BASE_Y - amp * bumpFn(u) - 1.5;
    const r = R0 + rnd() * (MAX_R - R0);
    bubbles.push({ x, y, r });
  }
  return { domeD, bubbles };
}

export function LeavenCrestFall({ className = "" }: LeavenCrestFallProps) {
  const [reduced, setReduced] = useState(false);
  const [statusText, setStatusText] = useState("sourdough starter rising");

  const domeRef = useRef<SVGPathElement | null>(null);
  const flashRef = useRef<SVGPathElement | null>(null);
  const bubbleRefs = useRef<(SVGCircleElement | null)[]>([]);
  const bubblesRef = useRef<Bubble[]>(
    Array.from({ length: BUBBLE_POOL }, () => ({
      active: false,
      x: 0,
      birth: 0,
      r: 0,
      poppingAt: null,
      poppedFromR: 0,
    })),
  );
  const peakCountRef = useRef(0);
  const wasFallingRef = useRef(false);
  const startRef = useRef(0);
  const rafRef = useRef(0);
  const lastStatusRef = useRef(0);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    if (reduced) return;

    startRef.current = performance.now();
    lastStatusRef.current = 0;

    const step = (now: number) => {
      const elapsed = now - startRef.current;
      const cycleT = elapsed % CYCLE_MS;
      const n = riseFraction(cycleT);
      const amp = domeAmplitude(n);
      const falling = isFalling(cycleT);
      const feeding = isFeeding(cycleT);

      if (falling && !wasFallingRef.current) {
        peakCountRef.current = bubblesRef.current.filter((b) => b.active && b.poppingAt === null).length;
      }
      wasFallingRef.current = falling;

      // -- dome surface --
      const xs: number[] = [];
      const ys: number[] = [];
      const t = elapsed / 1000;
      for (let i = 0; i < DOME_SAMPLES; i++) {
        const u = i / (DOME_SAMPLES - 1);
        const x = JAR_LEFT + u * (JAR_RIGHT - JAR_LEFT);
        const ripple =
          RIPPLE_AMPL *
          (0.6 * Math.sin(3 * u * Math.PI * 2 + t * RIPPLE_OMEGA) +
            0.4 * Math.sin(5 * u * Math.PI * 2 - t * RIPPLE_OMEGA * 1.3)) *
          bumpFn(u);
        const y = BASE_Y - amp * bumpFn(u) + ripple;
        xs.push(x);
        ys.push(y);
      }
      if (domeRef.current) {
        domeRef.current.setAttribute("d", buildDomePath(ys, xs));
      }

      // -- feed flash --
      if (flashRef.current) {
        let flashOpacity = 0;
        if (feeding) {
          const u = (cycleT - RISE_MS - FALL_MS) / FEED_MS;
          flashOpacity = Math.sin(Math.PI * clamp(u, 0, 1)) * 0.35;
        }
        flashRef.current.setAttribute("opacity", flashOpacity.toFixed(3));
      }

      // -- bubbles: nucleate during rise --
      const bubbles = bubblesRef.current;
      if (!falling && !feeding) {
        const dtSpawn = 1 / 60; // approximate per-frame window for the Poisson check
        if (Math.random() < LAMBDA * dtSpawn) {
          const free = bubbles.findIndex((b) => !b.active);
          if (free !== -1) {
            const u = 0.06 + Math.random() * 0.88;
            bubbles[free] = {
              active: true,
              x: JAR_LEFT + u * (JAR_RIGHT - JAR_LEFT),
              birth: now,
              r: 0,
              poppingAt: null,
              poppedFromR: 0,
            };
          }
        }
      }

      // -- bubbles: pop down toward target during fall --
      if (falling) {
        const target = Math.round(
          peakCountRef.current * clamp((n - N_SETTLE) / (1 - N_SETTLE), 0, 1),
        );
        const live = bubbles
          .map((b, i) => ({ b, i }))
          .filter((x) => x.b.active && x.b.poppingAt === null)
          .sort((a, c) => a.b.r - c.b.r); // smallest first
        const excess = live.length - target;
        for (let k = 0; k < excess; k++) {
          const entry = live[k];
          entry.b.poppingAt = now;
          entry.b.poppedFromR = entry.b.r;
        }
      }

      // -- bubbles: advance radius / render --
      for (let i = 0; i < bubbles.length; i++) {
        const b = bubbles[i];
        const el = bubbleRefs.current[i];
        if (!b.active) {
          if (el) el.setAttribute("r", "0");
          continue;
        }
        if (b.poppingAt !== null) {
          const u = clamp((now - b.poppingAt) / POP_MS, 0, 1);
          b.r = b.poppedFromR * (1 - u);
          if (u >= 1) {
            b.active = false;
            b.poppingAt = null;
          }
        } else {
          const ageSec = (now - b.birth) / 1000;
          b.r = Math.min(MAX_R, R0 * Math.pow(Math.max(ageSec, 0.001), 0.3) - R0 * 0.4);
          b.r = clamp(b.r, 0, MAX_R);
        }
        if (el) {
          const u = clamp((b.x - JAR_LEFT) / (JAR_RIGHT - JAR_LEFT), 0, 1);
          const y = BASE_Y - amp * bumpFn(u) - b.r * 0.7;
          el.setAttribute("cx", b.x.toFixed(2));
          el.setAttribute("cy", y.toFixed(2));
          el.setAttribute("r", Math.max(0, b.r).toFixed(2));
        }
      }

      if (now - lastStatusRef.current > 900) {
        lastStatusRef.current = now;
        setStatusText(
          feeding
            ? "sourdough starter fed, beginning to rise"
            : falling
              ? "sourdough starter collapsing"
              : "sourdough starter rising",
        );
      }

      rafRef.current = window.requestAnimationFrame(step);
    };

    rafRef.current = window.requestAnimationFrame(step);
    return () => window.cancelAnimationFrame(rafRef.current);
  }, [reduced]);

  const reducedFrame = reduced ? buildReducedFrame() : null;

  return (
    <div className={`relative h-full w-full overflow-hidden ${className}`} data-leaven-crest-fall>
      <svg
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        width="100%"
        height="100%"
        preserveAspectRatio="xMidYMid meet"
        aria-hidden="true"
        focusable="false"
        className="pointer-events-none block h-full w-full"
      >
        {/* jar outline */}
        <path
          d={`M ${JAR_LEFT},${JAR_TOP} L ${JAR_LEFT},${JAR_BOTTOM - 14} Q ${JAR_LEFT},${JAR_BOTTOM} ${JAR_LEFT + 14},${JAR_BOTTOM} L ${JAR_RIGHT - 14},${JAR_BOTTOM} Q ${JAR_RIGHT},${JAR_BOTTOM} ${JAR_RIGHT},${JAR_BOTTOM - 14} L ${JAR_RIGHT},${JAR_TOP}`}
          fill="none"
          stroke="var(--border)"
          strokeWidth={1.5}
        />
        {/* baseline fill mark, the rubber-band bakers use to track rise */}
        <line
          x1={JAR_LEFT - 4}
          y1={BASE_Y}
          x2={JAR_LEFT + 3}
          y2={BASE_Y}
          stroke="var(--border)"
          strokeWidth={1.5}
        />

        {reduced && reducedFrame ? (
          <>
            <path d={reducedFrame.domeD} fill="var(--ns-muted)" />
            {reducedFrame.bubbles.map((b, i) => (
              <circle
                key={i}
                cx={b.x}
                cy={b.y}
                r={b.r}
                fill="none"
                stroke="var(--foreground)"
                strokeWidth={0.6}
              />
            ))}
          </>
        ) : (
          <>
            <path ref={domeRef} fill="var(--ns-muted)" d="" />
            {Array.from({ length: BUBBLE_POOL }).map((_, i) => (
              <circle
                key={i}
                ref={(el) => {
                  bubbleRefs.current[i] = el;
                }}
                cx={0}
                cy={0}
                r={0}
                fill="none"
                stroke="var(--foreground)"
                strokeWidth={0.6}
              />
            ))}
            <path
              ref={flashRef}
              d={`M ${JAR_LEFT},${BASE_Y} L ${JAR_RIGHT},${BASE_Y} L ${JAR_RIGHT},${JAR_BOTTOM} L ${JAR_LEFT},${JAR_BOTTOM} Z`}
              fill="var(--foreground)"
              opacity={0}
            />
          </>
        )}
      </svg>
      <span role="status" aria-live="polite" className="sr-only">
        {statusText}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AsciiMagnifyLens — a lens that resolves the region under it into DENSER
// glyphs, not a bigger version of the same glyph. Distinct from slider-loupe
// (optically scales the same canvas-drawn tick marks bigger) and from
// text-prism-split (tears a headline into RGB channel offsets): here every
// character has a small 5x7 dot-matrix representation, and the lens redraws
// whichever characters fall inside it as that matrix — a grid of ascii-ramp
// cells finer than the flat glyph outside the lens, i.e. genuinely more
// characters per character. The base text is real, plain DOM text the whole
// time; the lens is a purely decorative aria-hidden canvas overlay on top of
// it, so accessibility is never in question. Direct-DOM rAF: the lens springs
// toward the pointer (slight optical lag) and parks at the block's center at
// rest and on pointer-leave, so the resting screenshot already shows the
// mechanic rather than plain text with nothing happening.
// ---------------------------------------------------------------------------

const CELL_COLS = 5;
const CELL_ROWS = 7;
const RAMP = " .:-=+*#%@";

