    label: "Australia & Pacific",
    cities: [
      "Adelaide", "Auckland", "Brisbane", "Darwin", "Fiji", "Guam",
      "Honolulu", "Melbourne", "Noumea", "Perth", "Port Moresby", "Suva",
      "Sydney", "Tongatapu",
    ],
