"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ScrollFineRegister — a divider/footer band whose "content is streaming
// past" cue is built from the two cooperating registers a tilemap PPU
// (NES/SNES-class hardware) actually scrolls with, not a plain translateX
// tween. A COARSE register steps the visible window one whole tile at a
// time by swapping which tile glyph is addressed; a FINE register sweeps
// 0..cellPx-1 sub-pixel offsets within the current tile before the coarse
// register ticks over. What reads as smooth pixel-by-pixel motion is a
// sawtooth (fine ramping up then snapping to 0) gating a stepped counter
// (coarse incrementing once per sawtooth cycle) — and both registers are
// exposed as a live numeric readout so the mechanism is legible, not just
// its resulting motion.
//
// One totalSteps integer (in px) is the single source of truth: fine =
// totalSteps % cellPx, coarse = floor(totalSteps / cellPx) % tileCount. A
// fixed-rate accumulator ticks totalSteps by 1 every (480ms / cellPx) —
// so a full tile's worth of fine steps always takes exactly 480ms,
// regardless of how many discrete px steps cellPx works out to.
//
// tileCount (24-40) is the COARSE WRAP PERIOD — the pattern of tile
// glyphs repeats every tileCount cells and totalSteps wraps at
// tileCount*cellPx. That is deliberately kept separate from how many
// cells are actually rendered: renderCount = ceil(width/cellPx) +
// tileCount cells are painted (glyph = pattern[j % tileCount]), a
// full period wider than the viewport, so the strip never runs dry as
// totalSteps sweeps across an entire wrap cycle — a doubled-strip trick
// only covers a translate range up to one strip width, this covers the
// whole period.
//
// The glyph sequence itself is not a short repeating ramp: a fixed-seed
// mulberry32 PRNG draws `tileCount` glyph choices once per build, so the
// visual texture's true repeat period is the full tileCount*cellPx wrap
// (11.5-19.2s), not some short arithmetic cycle — otherwise the strip
// would loop every couple of seconds while only the readout kept counting.
//
// A single marker — an absolutely positioned overlay, not a strip cell —
// tracks `MARKER_LEAD` tiles ahead of the live coarse register at screen
// x = MARKER_LEAD*cellPx - fine, so it visibly slides left by cellPx px
// over the 480ms sweep and snaps back at the next coarse tick: the
// sawtooth made literally visible on the one thing a viewer's eye
// follows. Drawn as a full-height --foreground bracket (border-left +
// border-right only, cellPx wide) so it stays legible on top of every
// glyph underneath it, including the solid block.
//
// Geometry is derived from the container's smaller dimension (almost
// always height, for a horizontal band): cellPx = clamp(round(minDim/24),
// 8, 16). Translation is written directly to the track's transform and
// the readout's textContent every tick — no React state on the hot path.
// Pure DOM, zero colour literals: ink is `text-foreground` /
// `text-ns-muted`; `border-border` is used only for the band's own
// dividing rules, never as the marker's paint.
// ---------------------------------------------------------------------------

export interface ScrollFineRegisterProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const MIN_CELL = 8;
const MAX_CELL = 16;
const CELL_DIVISOR = 24;
const SWEEP_MS = 480; // one full fine-register sweep (0..cellPx-1) = one coarse tick
const MIN_TILES = 24;
const MAX_TILES = 40;
const MARKER_LEAD = 4; // marker sits this many tiles ahead of the coarse index
const FROZEN_COARSE_FALLBACK = 12; // reduced-motion freeze target: mid-strip, tile-aligned

// A small "tile ROM" restricted to shading blocks — these are solid
// rectangles in every monospace face, so they read cleanly as tile
// pixels even at an 8px cell where a glyph with descenders/gaps would not.
const GLYPHS = "░▒▓█";

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** One glyph choice per tile index, 0..tileCount-1 — the true visual
 * repeat period, not a short arithmetic ramp. */
function buildPattern(tileCount: number): string[] {
  const rand = mulberry32(0x5f3a11);
  const pattern: string[] = [];
  for (let i = 0; i < tileCount; i++) {
    pattern.push(GLYPHS[Math.floor(rand() * GLYPHS.length)]!);
  }
  return pattern;
}

export function ScrollFineRegister({ className = "" }: ScrollFineRegisterProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const markerRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const coarseRef = useRef<HTMLSpanElement>(null);
  const fineRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const track = trackRef.current;
    const marker = markerRef.current;
    const probe = probeRef.current;
    if (!root || !track || !marker || !probe) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let cellPx = MIN_CELL;
    let tileCount = MIN_TILES; // coarse wrap period, in tiles
    let renderCount = MIN_TILES; // cells actually painted, >= period + viewport
    let stepMs = SWEEP_MS / cellPx;
    let totalSteps = 0; // px units; fine = totalSteps % cellPx, coarse = floor(totalSteps/cellPx) % tileCount
    let acc = 0;
    let last = 0;
    let raf = 0;
    let visible = true;
    let pattern: string[] = [];

    const paint = () => {
      const fine = totalSteps % cellPx;
      const coarse = Math.floor(totalSteps / cellPx) % tileCount;
      track.style.transform = `translate3d(${-totalSteps}px, 0, 0)`;
      marker.style.width = `${cellPx}px`;
      marker.style.transform = `translate3d(${MARKER_LEAD * cellPx - fine}px, 0, 0)`;
      marker.style.visibility = "visible";
      if (coarseRef.current) coarseRef.current.textContent = String(coarse).padStart(2, "0");
      if (fineRef.current) fineRef.current.textContent = String(fine);
    };

    // -- (re)build the tile strip for the current geometry. renderCount is
    // one full coarse period wider than the viewport so every reachable
    // translate offset within a period still fully covers the track. ------
    const build = () => {
      const rect = root.getBoundingClientRect();
      const minDim = Math.min(rect.width, rect.height);
      cellPx = Math.min(MAX_CELL, Math.max(MIN_CELL, Math.round(minDim / CELL_DIVISOR)));
      stepMs = SWEEP_MS / cellPx;

      const visibleTiles = Math.ceil(rect.width / Math.max(1, cellPx));
      tileCount = Math.min(MAX_TILES, Math.max(MIN_TILES, visibleTiles));
      renderCount = visibleTiles + tileCount + MARKER_LEAD + 1;
      pattern = buildPattern(tileCount);

      // measure the real glyph advance at this cellPx (monospace advance
      // is well under 1em) and scale the font so a glyph's rendered width
      // fills the cell — otherwise adjacent tiles read as separated bars,
      // not a contiguous tilemap.
      probe.style.fontSize = `${cellPx}px`;
      const advance = probe.getBoundingClientRect().width || cellPx * 0.6;
      const glyphFontPx = Math.max(6, Math.round(cellPx * Math.min(2.5, cellPx / advance)));

      track.textContent = "";
      for (let j = 0; j < renderCount; j++) {
        const span = document.createElement("span");
        span.setAttribute("aria-hidden", "true");
        span.style.display = "inline-flex";
        span.style.alignItems = "center";
        span.style.justifyContent = "center";
        span.style.width = `${cellPx}px`;
        span.style.height = `${cellPx}px`;
        span.style.overflow = "hidden";
        span.style.fontSize = `${glyphFontPx}px`;
        span.style.lineHeight = "1";
        span.style.flexShrink = "0";
        span.style.boxSizing = "border-box";
        span.className = "text-foreground";
        span.textContent = pattern[j % tileCount]!;
        track.appendChild(span);
      }
      totalSteps = ((totalSteps % (tileCount * cellPx)) + tileCount * cellPx) % (tileCount * cellPx);
    };

    const freeze = () => {
      const frozenCoarse = Math.min(tileCount - 1, FROZEN_COARSE_FALLBACK);
      totalSteps = frozenCoarse * cellPx; // fine === 0 exactly — a tile boundary flush with the viewport edge
      paint();
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      acc += dt;
      while (acc >= stepMs) {
        acc -= stepMs;
        totalSteps += 1;
        if (totalSteps >= tileCount * cellPx) totalSteps -= tileCount * cellPx;
      }
      paint();
      raf = requestAnimationFrame(loop);
    };

    build();

    if (reduced) {
      freeze();
    } else {
      // start a few steps into the sweep so t0 already reads as
      // "mid-motion", not a just-ticked-over frame.
      totalSteps = 3;
      last = 0;
      raf = requestAnimationFrame(loop);
    }

    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        build();
        if (reduced) freeze();
        else paint();
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    document.fonts?.ready?.then(() => {
      if (!disposed) onResize();
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`flex h-12 items-stretch overflow-hidden border-y border-border bg-background ${className}`}
    >
      <div className="relative min-w-0 flex-1 overflow-hidden">
        <span
          ref={probeRef}
          aria-hidden="true"
          className="pointer-events-none absolute -left-[9999px] top-0 font-mono"
          style={{ visibility: "hidden", whiteSpace: "pre" }}
        >
          █
        </span>
        <div ref={trackRef} className="flex h-full items-center font-mono will-change-transform" />
        <div
          ref={markerRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 left-0 border-x border-foreground will-change-transform"
          style={{ visibility: "hidden" }}
        />
      </div>
      <div className="flex shrink-0 items-center gap-2 border-l border-border px-4 font-mono text-[11px] tabular-nums text-foreground">
        <span className="text-ns-muted">C</span>
        <span ref={coarseRef}>00</span>
        <span className="text-ns-muted">F</span>
        <span ref={fineRef}>0</span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// world-space constants
const DEPTH = 4000; // tunnel length in world units
const TRAVEL = 3600; // camera travel across the full scrub
const FOCAL = 600; // perspective focal length: scale = FOCAL / (z - camZ)
const R_MIN = 120; // cylinder shell inner radius
const R_MAX = 900; // cylinder shell outer radius
const NEAR_CLIP = 24; // cull points closer than this to the camera

// streak-factor spring: k = 60, zeta = 0.8 (relaxes lines back to dots)
const SPRING_K = 60;
const SPRING_C = 2 * 0.8 * Math.sqrt(SPRING_K);

// monochrome depth ramp: alpha rises 0.3 -> 1.0 with proximity, color pinned
// to the live --foreground token so contrast against the page background is
// correct in both themes (near = full foreground opacity, far = faded toward bg).
function buildShades(rgb: { r: number; g: number; b: number }) {
  return Array.from({ length: 24 }, (_, i) => {
    const t = i / 23;
    return `rgba(${rgb.r},${rgb.g},${rgb.b},${(0.3 + 0.7 * t).toFixed(3)})`;
  });
}

function parseColor(raw: string): { r: number; g: number; b: number } | null {
  const v = raw.trim();
  if (v.startsWith("#")) {
    const hex = v.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    return null;
  }
  const m = v.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  if (m) return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
  return null;
}

function readForegroundShades() {
  const raw = getComputedStyle(document.documentElement).getPropertyValue("--foreground");
  return buildShades(parseColor(raw) ?? { r: 143, g: 143, b: 143 });
}

// deterministic PRNG so the field is identical across mounts and screenshots
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// seed points in a cylinder shell (uniform over the annulus area)
function seedPoints(count: number) {
  const rand = mulberry32(0x517cc1b7);
  const px = new Float32Array(count);
  const py = new Float32Array(count);
  const pz = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(R_MIN * R_MIN + (R_MAX * R_MAX - R_MIN * R_MIN) * rand());
    px[i] = Math.cos(theta) * r;
    py[i] = Math.sin(theta) * r;
    pz[i] = rand() * DEPTH;
  }
  return { px, py, pz };
}

function labelDepthAt(index: number, count: number) {
  return count <= 1 ? DEPTH / 2 : 700 + (index * 2700) / (count - 1);
}

// Scroll scrubs a camera through a monochrome point tunnel. Scroll velocity
// stretches dots into motion streaks, cursor drift adds parallax, and mono
// labels sit at fixed world depths, snapping into focus as the camera passes.
// Direct-DOM rAF loop — no React state on the hot path; sleeps when settled.
export function ParticleTunnelScrub({
  labels = ["01 SIGNAL", "02 NOISE", "03 FIELD", "04 VOID"],
  pointCount = 3000,
  className = "",
}: {
  /** section labels pinned at fixed depths along the tunnel */
  labels?: string[];
  /** points seeded in the cylinder shell */
  pointCount?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const sectionRef = useRef<HTMLElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const labelRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // full motion path
  useEffect(() => {
    if (reduced) return;
    const section = sectionRef.current;
    const canvas = canvasRef.current;
    if (!section || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const { px, py, pz } = seedPoints(pointCount);
    const prevX = new Float32Array(pointCount);
    const prevY = new Float32Array(pointCount);
    const dirX = new Float32Array(pointCount);
    const dirY = new Float32Array(pointCount);
    let hasPrev = false;
    let shades = readForegroundShades();

    const labelCount = labels.length;
    const labelDepths = labels.map((_, i) => labelDepthAt(i, labelCount));

    let w = 0;
    let h = 0;
    let p = 0; // scroll progress 0..1
    let lastCamZ = 0;
    let vel = 0; // EMA of camZ delta per 60fps frame
    let streak = 0; // spring-smoothed streak length (px)
    let streakV = 0;
    let camX = 0;
    let camY = 0;
    let tX = 0; // parallax targets (world units)
    let tY = 0;
    let raf = 0;
    let lastT = 0;
    let dirty = true;

    const frame = (now: number) => {
      const dt = Math.min(0.05, lastT ? (now - lastT) / 1000 : 1 / 60);
      lastT = now;
      const frames = dt * 60;
      dirty = false;

      // camera scrub + scroll-velocity EMA (alpha = 0.12)
      const camZ = p * TRAVEL;
      const inst = frames > 0 ? (camZ - lastCamZ) / frames : 0;
      lastCamZ = camZ;
      vel += 0.12 * (inst - vel);

      // streak spring toward clamp(|v| * 0.06, 0, 40) px
      const target = Math.min(40, Math.abs(vel) * 0.06);
      streakV += (SPRING_K * (target - streak) - SPRING_C * streakV) * dt;
      streak += streakV * dt;
      if (streak < 0) streak = 0;

      // cursor parallax: lerp 0.08/frame toward pointer offset
      const k = 1 - Math.pow(1 - 0.08, frames);
      camX += (tX - camX) * k;
      camY += (tY - camY) * k;

      ctx.clearRect(0, 0, w, h);
      const cx = w / 2;
      const cy = h / 2;
      const drawStreaks = streak > 0.5;

      for (let i = 0; i < pointCount; i++) {
        const dz = pz[i] - camZ;
        if (dz < NEAR_CLIP) continue; // behind or grazing the camera
        const s = FOCAL / dz;
        const sx = cx + (px[i] - camX) * s;
        const sy = cy + (py[i] - camY) * s;
        if (sx < -60 || sx > w + 60 || sy < -60 || sy > h + 60) {
          prevX[i] = sx;
          prevY[i] = sy;
          continue;
        }
        if (hasPrev) {
          const mx = sx - prevX[i];
          const my = sy - prevY[i];
          const md = Math.hypot(mx, my);
          if (md > 0.3) {
            dirX[i] = mx / md;
            dirY[i] = my / md;
          }
        }
        prevX[i] = sx;
        prevY[i] = sy;

        const near = Math.min(1, 420 / dz);
        const shade = shades[Math.min(23, (near * 23) | 0)] ?? "#8f8f8f";
        const size = Math.min(3.2, Math.max(0.6, s * 1.5));
        if (drawStreaks && (dirX[i] !== 0 || dirY[i] !== 0)) {
          ctx.strokeStyle = shade;
          ctx.lineWidth = size;
          ctx.beginPath();
          ctx.moveTo(sx - dirX[i] * streak, sy - dirY[i] * streak);
          ctx.lineTo(sx, sy);
          ctx.stroke();
        } else {
          ctx.fillStyle = shade;
          ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
        }
      }
      hasPrev = true;

      // labels: focus window +-300 units, fall to blur 6px over the next 900,
      // scale runs 0.92 -> 1.08 through the pass so they fly by
      for (let i = 0; i < labelCount; i++) {
        const el = labelRefs.current[i];
        if (!el) continue;
        const d = (labelDepths[i] ?? 0) - camZ;
        const ad = Math.abs(d);
        let opacity = 0;
        let blur = 6;
        if (ad <= 300) {
          opacity = 1;
          blur = 0;
        } else if (ad <= 1200) {
          const t = (ad - 300) / 900;
          opacity = 1 - t;
          blur = 6 * t;
        }
        const scale = Math.min(1.08, Math.max(0.92, 1 - (d / 1200) * 0.08));
        el.style.opacity = opacity.toFixed(3);
        el.style.filter = blur > 0.02 ? `blur(${blur.toFixed(2)}px)` : "none";
        el.style.transform = `scale(${scale.toFixed(4)})`;
      }

      // sleep when scroll, parallax, and the streak spring are all settled
      const parallaxSettled = Math.abs(tX - camX) < 0.05 && Math.abs(tY - camY) < 0.05;
      const springSettled = streak < 0.05 && Math.abs(streakV) < 0.05 && Math.abs(vel) < 0.05;
      if (!dirty && parallaxSettled && springSettled) {
        raf = 0;
        lastT = 0;
        return;
      }
      raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(frame);
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.lineCap = "round";
      dirty = true;
      wake();
    };

    const readScroll = () => {
      const rect = section.getBoundingClientRect();
      const track = rect.height - window.innerHeight;
      p = track > 0 ? Math.min(1, Math.max(0, -rect.top / track)) : 0;
      dirty = true;
      wake();
    };

    const onPointer = (e: PointerEvent) => {
      tX = (e.clientX - w / 2) * 0.04;
      tY = (e.clientY - h / 2) * 0.04;
      wake();
    };

    // re-derive the shade ramp from --foreground whenever the theme class
    // flips on <html>, so light/dark contrast stays correct without a remount
    const onThemeChange = () => {
      shades = readForegroundShades();
      dirty = true;
      wake();
    };
    const themeObserver = new MutationObserver(onThemeChange);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    resize();
    readScroll();
    lastCamZ = p * TRAVEL; // no phantom velocity on mount mid-page
    wake();

    window.addEventListener("scroll", readScroll, { passive: true });
    window.addEventListener("resize", resize);
    window.addEventListener("pointermove", onPointer, { passive: true });
    return () => {
      cancelAnimationFrame(raf);
      themeObserver.disconnect();
      window.removeEventListener("scroll", readScroll);
      window.removeEventListener("resize", resize);
      window.removeEventListener("pointermove", onPointer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced, pointCount, labels.length]);

  // reduced motion: one static starfield frame, no loop
  useEffect(() => {
    if (!reduced) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const { px, py, pz } = seedPoints(pointCount);
    let shades = readForegroundShades();
    const draw = () => {
      const rect = canvas.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const camZ = DEPTH * 0.3;
      for (let i = 0; i < pointCount; i++) {
        const dz = pz[i] - camZ;
        if (dz < NEAR_CLIP) continue;
        const s = FOCAL / dz;
        const sx = w / 2 + px[i] * s;
        const sy = h / 2 + py[i] * s;
        if (sx < -10 || sx > w + 10 || sy < -10 || sy > h + 10) continue;
        const near = Math.min(1, 420 / dz);
        ctx.fillStyle = shades[Math.min(23, (near * 23) | 0)] ?? "#8f8f8f";
        const size = Math.min(3.2, Math.max(0.6, s * 1.5));
        ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
      }
    };
    draw();
    const onThemeChange = () => {
      shades = readForegroundShades();
      draw();
    };
    const themeObserver = new MutationObserver(onThemeChange);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    window.addEventListener("resize", draw);
    return () => {
      themeObserver.disconnect();
      window.removeEventListener("resize", draw);
    };
  }, [reduced, pointCount]);

  // reduced motion: labels fade in 200ms via IntersectionObserver
  useEffect(() => {
    if (!reduced) return;
    const els = labelRefs.current
      .slice(0, labels.length)
      .filter((el): el is HTMLSpanElement => el !== null);
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          (entry.target as HTMLElement).style.opacity = entry.isIntersecting ? "1" : "0";
        }
      },
      { threshold: 0.4 }
    );
    for (const el of els) {
      el.style.transition = "opacity 200ms ease-out";
      io.observe(el);
    }
    return () => io.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced, labels.length]);

  return (
    <section
      ref={sectionRef}
      className={`relative h-[400vh] bg-background ${className}`}
    >
      <div className="sticky top-0 h-screen w-full overflow-hidden">
        <canvas ref={canvasRef} aria-hidden className="absolute inset-0 h-full w-full" />
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0"
          style={{
            background:
              "radial-gradient(circle at center, transparent 40%, var(--background) 96%)",
          }}
        />
        {!reduced &&
          labels.map((label, i) => (
            <div
              key={`${label}-${i}`}
              className="pointer-events-none absolute inset-0 flex items-center justify-center"
            >
              <span
                ref={(el) => {
                  labelRefs.current[i] = el;
                }}
                className="font-mono text-sm tracking-widest text-foreground will-change-[transform,opacity,filter]"
                style={{ opacity: 0 }}
              >
                {label}
              </span>
            </div>
          ))}
      </div>
      {reduced && (
        <div className="absolute inset-0">
          {labels.map((label, i) => (
            <span
              key={`${label}-${i}`}
              ref={(el) => {
                labelRefs.current[i] = el;
              }}
              className="absolute left-1/2 -translate-x-1/2 -translate-y-1/2 font-mono text-sm tracking-widest text-foreground"
              style={{ top: `${((i + 0.5) * 100) / labels.length}%`, opacity: 0 }}
            >
              {label}
            </span>
          ))}
        </div>
      )}
    </section>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// SprocketScrub — a media scrubber rendered as a physical film strip. Sprocket
// holes (SVG pattern) run both edges of a horizontal track; the track body is
// divided into one cell per second ("perforation") via a percentage-sized
// repeating background so the grid always lines up regardless of width.
// Buffered range renders as faintly noise-filled exposed frames; unbuffered
// range is blank stock.
//
// The playhead is a gate claw. Its motion has two distinct regimes, and
// which one is active is decided per pointer-drag sample from the raw pixel
// speed of the drag itself (not from how the `value` prop happens to change
// externally, which always just glides smoothly — see the "not dragging"
// effect below):
//   - slow drag: the claw disengages and re-engages one perforation at a
//     time. Each time the dragged position crosses into a new whole second
//     it plays a short "pull-in" spring settle to that tooth and commits an
//     integer value.
//   - fast drag: the claw releases — position tracks the pointer 1:1, no
//     rounding, no transition, continuous glide.
// Both are computed from direct-DOM transform writes on refs; no React state
// on the pointermove hot path.
//
// Hovering anywhere on the track (independent of dragging) rises a small
// frame-preview tick above the cursor: a mono timestamp plus a shaded swatch
// standing in for that frame's cell.
//
// Accessibility: the track itself is role="slider" with aria-valuemin/max/now
// and a formatted aria-valuetext, arrow keys step one perforation, PageUp/
// PageDown step ten, Home/End jump to the ends — standard slider semantics,
// which is also why no extra live region is needed: AT already announces
// value changes through the slider's own value text on interaction.
//
// prefers-reduced-motion drops the discrete-step regime entirely: dragging
// always behaves like the fast/glide path, so there is continuous motion
// only, never snap theater.
// ---------------------------------------------------------------------------

export interface SprocketScrubProps {
  /** Controlled position in seconds. Omit for uncontrolled (see defaultValue). */
  value?: number;
  /** Initial position in seconds when uncontrolled. Default 0. */
  defaultValue?: number;
  /** Total duration in seconds. */
  duration: number;
  /** Buffered range from 0, in seconds. Default 0. */
  buffered?: number;
  /** Fires on every committed position change (drag, keyboard). */
  onValueChange?: (value: number) => void;
  /** Accessible name for the slider. Default "Scrub position". */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const SLOW_PX_MS = 0.5; // below this instantaneous drag speed -> discrete regime
const SNAP_MS = 120;
const SNAP_EASE = "cubic-bezier(0.34, 1.56, 0.64, 1)"; // slight overshoot, the "pull-in"
const GLIDE_MS = 220;
const GLIDE_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";

function clamp(v: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, v));
}

function formatTime(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  const m = Math.floor(s / 60);
  const rem = s % 60;
  return `${m}:${String(rem).padStart(2, "0")}`;
}

function writeClaw(el: HTMLDivElement | null, px: number, ms: number, ease: string) {
  if (!el) return;
  el.style.transition = ms > 0 ? `transform ${ms}ms ${ease}` : "none";
  el.style.transform = `translateX(${px}px)`;
}

function writePreview(el: HTMLDivElement | null, px: number) {
  if (!el) return;
  el.style.transform = `translateX(${px}px)`;
}

export function SprocketScrub({
  value: controlledValue,
  defaultValue = 0,
  duration,
  buffered = 0,
  onValueChange,
  label = "Scrub position",
  className = "",
}: SprocketScrubProps) {
  const uid = useId().replace(/:/g, "");
  const [internalValue, setInternalValue] = useState(defaultValue);
  const value = controlledValue ?? internalValue;

  const rootRef = useRef<HTMLDivElement | null>(null);
  const trackRef = useRef<HTMLDivElement | null>(null);
  const clawRef = useRef<HTMLDivElement | null>(null);
  const previewRef = useRef<HTMLDivElement | null>(null);

  const reducedRef = useRef(false);
  const draggingRef = useRef(false);
  const lastXRef = useRef(0);
  const lastTRef = useRef(0);
  const lastQuantRef = useRef(Math.round(value));
  const trackWidthRef = useRef(0);

  const [hovering, setHovering] = useState(false);
  const [previewValue, setPreviewValue] = useState(0);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const commit = useCallback(
    (v: number) => {
      onValueChange?.(v);
      if (controlledValue === undefined) setInternalValue(v);
    },
    [controlledValue, onValueChange]
  );

  const pxForValue = useCallback(
    (v: number) => (duration > 0 ? (v / duration) * trackWidthRef.current : 0),
    [duration]
  );

  // Programmatic position changes (playback advancing, keyboard steps, or any
  // update while not actively dragging) always glide smoothly — the two-
  // regime split belongs to live drag speed only, never to how the value
  // prop itself happens to change.
  useEffect(() => {
    if (draggingRef.current) return;
    const w = trackRef.current?.getBoundingClientRect().width ?? 0;
    trackWidthRef.current = w;
    lastQuantRef.current = Math.round(value);
    writeClaw(clawRef.current, pxForValue(value), reducedRef.current ? 0 : GLIDE_MS, GLIDE_EASE);
  }, [value, duration, pxForValue]);

  const step = useCallback(
    (delta: number) => {
      commit(clamp(Math.round(value) + delta, 0, duration));
    },
    [commit, value, duration]
  );

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    switch (e.key) {
      case "ArrowLeft":
      case "ArrowDown":
        e.preventDefault();
        step(-1);
        break;
      case "ArrowRight":
      case "ArrowUp":
        e.preventDefault();
        step(1);
        break;
      case "PageDown":
        e.preventDefault();
        step(-10);
        break;
      case "PageUp":
        e.preventDefault();
        step(10);
        break;
      case "Home":
        e.preventDefault();
        commit(0);
        break;
      case "End":
        e.preventDefault();
        commit(duration);
        break;
      default:
        break;
    }
  };

  const rawValueAt = (clientX: number) => {
    const rect = trackRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return value;
    const x = clamp(clientX - rect.left, 0, rect.width);
    trackWidthRef.current = rect.width;
    return (x / rect.width) * duration;
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    trackRef.current?.setPointerCapture(e.pointerId);
    draggingRef.current = true;
    lastXRef.current = e.clientX;
    lastTRef.current = performance.now();
    lastQuantRef.current = Math.round(value);
    const raw = rawValueAt(e.clientX);
    writeClaw(clawRef.current, pxForValue(raw), 0, GLIDE_EASE);
    commit(reducedRef.current ? raw : Math.round(raw));
  };

  const onPointerMoveTrack = (e: ReactPointerEvent<HTMLDivElement>) => {
    const rect = trackRef.current?.getBoundingClientRect();
    if (rect && rect.width > 0) {
      const x = clamp(e.clientX - rect.left, 0, rect.width);
      writePreview(previewRef.current, x);
      setPreviewValue((x / rect.width) * duration);
    }

    if (!draggingRef.current) return;

    const now = performance.now();
    const dt = Math.max(1, now - lastTRef.current);
    const dx = Math.abs(e.clientX - lastXRef.current);
    const speed = dx / dt;
    lastXRef.current = e.clientX;
    lastTRef.current = now;

    const raw = rawValueAt(e.clientX);

    if (!reducedRef.current && speed < SLOW_PX_MS) {
      const quant = clamp(Math.round(raw), 0, duration);
      if (quant !== lastQuantRef.current) {
        lastQuantRef.current = quant;
        writeClaw(clawRef.current, pxForValue(quant), SNAP_MS, SNAP_EASE);
        commit(quant);
      }
    } else {
      lastQuantRef.current = Math.round(raw);
      writeClaw(clawRef.current, pxForValue(raw), 0, GLIDE_EASE);
      commit(raw);
    }
  };

  const onPointerUp = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!draggingRef.current) return;
    draggingRef.current = false;
    trackRef.current?.releasePointerCapture(e.pointerId);
    const snapped = clamp(Math.round(value), 0, duration);
    commit(snapped);
    writeClaw(clawRef.current, pxForValue(snapped), reducedRef.current ? 0 : SNAP_MS, SNAP_EASE);
  };

  const bufferedPct = duration > 0 ? clamp((buffered / duration) * 100, 0, 100) : 0;
  const cellPct = duration > 0 ? 100 / duration : 100;
  const holePatternId = `ns-sprocket-holes-${uid}`;

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <style>{CSS}</style>
      <div
        ref={trackRef}
        data-sprocket-track=""
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-orientation="horizontal"
        aria-valuemin={0}
        aria-valuemax={duration}
        aria-valuenow={Math.round(value)}
        aria-valuetext={formatTime(value)}
        className="ns-sprocket-track relative h-16 w-full select-none overflow-hidden rounded-[12px] border border-border bg-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMoveTrack}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onPointerEnter={() => setHovering(true)}
        onPointerLeave={() => setHovering(false)}
        onKeyDown={onKeyDown}
      >
        <svg className="absolute inset-x-0 top-0 h-2 w-full" aria-hidden="true">
          <defs>
            <pattern id={holePatternId} width="12" height="8" patternUnits="userSpaceOnUse">
              <circle cx="6" cy="4" r="1.5" fill="var(--border)" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill={`url(#${holePatternId})`} />
        </svg>

        <div className="absolute inset-x-0 top-2 bottom-2 overflow-hidden">
          {/* blank stock */}
          <div className="absolute inset-0" style={{ backgroundColor: "var(--border)", opacity: 0.12 }} />
          {/* exposed / buffered frames: faint noise fill */}
          <div
            className="absolute inset-y-0 left-0"
            style={{
              width: `${bufferedPct}%`,
              backgroundColor: "var(--foreground)",
              opacity: 0.05,
              backgroundImage:
                "repeating-linear-gradient(45deg, var(--foreground) 0px, var(--foreground) 1px, transparent 1px, transparent 3px)",
            }}
          />
          {/* frame cell dividers */}
          <div
            className="absolute inset-0"
            style={{
              backgroundImage: "linear-gradient(to right, var(--border) 1px, transparent 1px)",
              backgroundSize: `${cellPct}% 100%`,
              opacity: 0.7,
            }}
          />
          {/* gate claw / playhead */}
          <div ref={clawRef} className="ns-sprocket-claw absolute inset-y-0 left-0" style={{ transform: "translateX(0px)" }}>
            <span
              aria-hidden="true"
              className="absolute -top-[7px] left-0 -translate-x-1/2"
              style={{
                width: 0,
                height: 0,
                borderLeft: "4px solid transparent",
                borderRight: "4px solid transparent",
                borderTop: "6px solid var(--foreground)",
              }}
            />
            <span
              aria-hidden="true"
              className="absolute inset-y-0 left-0 -translate-x-1/2"
              style={{ width: 2, backgroundColor: "var(--foreground)" }}
            />
          </div>
        </div>

        <svg className="absolute inset-x-0 bottom-0 h-2 w-full" aria-hidden="true">
          <rect width="100%" height="100%" fill={`url(#${holePatternId})`} />
        </svg>
      </div>

      {hovering && (
        <div
          ref={previewRef}
          aria-hidden="true"
          className="pointer-events-none absolute bottom-full left-0 z-10 mb-2 -translate-x-1/2 rounded-[6px] border border-border bg-background px-1.5 py-1 shadow-sm"
        >
          <div className="mb-1 h-3 w-6 rounded-[2px]" style={{ backgroundColor: "var(--ns-muted)", opacity: 0.3 }} />
          <div className="font-mono text-[10px] tabular-nums text-foreground">{formatTime(previewValue)}</div>
        </div>
      )}
    </div>
  );
}

const CSS = `
.ns-sprocket-claw{will-change:transform;}
@media (prefers-reduced-motion: reduce){
  .ns-sprocket-claw{transition:none !important;}
}
`;

