  {
    label: "Active nodes",
    value: 3412,
    format: (v) => Math.round(v).toLocaleString("en-US"),
    delta: "+86",
    icon: strokeIcon(
      <>
        <circle cx="6" cy="12" r="2.5" />
        <circle cx="18" cy="5.5" r="2.5" />
        <circle cx="18" cy="18.5" r="2.5" />
        <path d="M8.2 10.9l7.5-4.2M8.2 13.1l7.5 4.2" />
      </>
    ),
  },
  {
    label: "Error rate",
    value: 0.07,
    format: (v) => `${v.toFixed(2)}%`,
    icon: strokeIcon(
      <>
        <path d="M12 3.5 2.8 19.5h18.4Z" />
        <path d="M12 10v4" />
        <path d="M12 16.8v.2" />
      </>
    ),
  },
];

// pivot sits at the panel's top-left padding corner (p-6 = 24px)
const PIVOT = 24;
const COUNT_MS = 900; // value count-up
const DELTA_MS = 300; // trend delta fade-in
const BORDER_IN_MS = 200; // --border → --ns-accent
const BORDER_OUT_MS = 1600; // decay back to --border
const TWEEN_MS = BORDER_IN_MS + BORDER_OUT_MS; // hard end for every wake
const RING_SPEED = 320; // px/s expansion
const RING_ALPHA = 0.18;
const MAX_RINGS = 3;

export function ScanSweepStats({
  stats = DEFAULT_STATS,
  title = "Network observatory",
  degPerSec = 30,
  wedgeDeg = 24,
  toleranceDeg = 2,
  className = "",
}: {
  /** KPI cards, clockwise activation order falls out of their bearings */
  stats?: ScanStat[];
  /** heading above the sweep */
  title?: string;
  /** sweep speed in degrees per second (30 = one revolution per 12s) */
  degPerSec?: number;
  /** soft sector width trailing the arm, in degrees */
  wedgeDeg?: number;
  /** transit window around a card's bearing, in degrees */
  toleranceDeg?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const clockRef = useRef<HTMLSpanElement>(null);
  const sweepRef = useRef<HTMLSpanElement>(null);
  const cardEls = useRef<(HTMLDivElement | null)[]>([]);
  const pausedRef = useRef(false);
  const wakeRef = useRef<(() => void) | null>(null);
  const [paused, setPaused] = useState(false);

  const togglePause = () => {
    const next = !pausedRef.current;
    pausedRef.current = next;
    setPaused(next);
    wakeRef.current?.(); // redraw the frozen frame / resume the sweep
  };

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // UTC clock — a 1Hz text swap, torn down with the effect
    const clockTick = () => {
      if (clockRef.current) {
        clockRef.current.textContent = `${new Date()
          .toISOString()
          .slice(11, 19)} UTC`;
      }
    };
    clockTick();
    const clockId = window.setInterval(clockTick, 1000);

    if (reduced) {
      // static fallback: no sweep, no rings, no loop. Cards render settled at
      // their server-marked final values with static --border; hover raise
      // stays pure CSS. The canvas draws nothing.
      return () => window.clearInterval(clockId);
    }

    // ---- token inks: derived at mount, re-derived live on class flips ------
    let fg: RGB = { r: 237, g: 237, b: 237 };
    let accent: RGB = { r: 0, g: 107, b: 255 };
    let borderC: RGB = { r: 46, g: 46, b: 46 };
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
      accent = parseColor(cs.getPropertyValue("--ns-accent")) ?? accent;
      borderC = parseColor(cs.getPropertyValue("--border")) ?? borderC;
    };
    derive();

    // ---- card records: DOM handles + tween state, refs only ----------------
    type Rec = {
      el: HTMLDivElement;
      valueEl: HTMLElement;
      deltaEl: HTMLElement | null;
      target: number;
      format: (v: number) => string;
      angle: number; // bearing from pivot, 0..360°
      next: number; // next unwrapped transit angle (Infinity until measured)
      active: boolean;
      accent: boolean; // sweep-earned border glow vs plain hover replay
      wakeAt: number;
      lastText: string;
    };
    const records: Rec[] = [];
    stats.forEach((s, i) => {
      const el = cardEls.current[i];
      if (!el) return;
      const valueEl = el.querySelector<HTMLElement>("[data-value]");
      if (!valueEl) return;
      records.push({
        el,
        valueEl,
        deltaEl: el.querySelector<HTMLElement>("[data-delta]"),
        target: s.value,
        format: s.format ?? defaultFormat,
        angle: 0,
        next: Number.POSITIVE_INFINITY,
        active: false,
        accent: false,
        wakeAt: 0,
        lastText: "",
      });
    });

    // ---- geometry / sizing -------------------------------------------------
    let w = 0;
    let h = 0;
    let dpr = 1;
    let maxR = 0;
    let sized = false;
    let T = 0; // unwrapped sweep angle in degrees, monotonic
    let lastRev = 0;
    const rings: { r: number }[] = [{ r: 0 }]; // one live ring at mount

    const measure = () => {
      const rr = root.getBoundingClientRect();
      if (rr.width < 2 || rr.height < 2) {
        sized = false; // zero-size guard — loop no-ops until RO wakes us
        return;
      }
      w = rr.width;
      h = rr.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      // canvas is a replaced element — inset does not size it; explicit CSS
      // size keeps the dpr backing store from rendering at raw scale
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      maxR = Math.hypot(w, h);
      // card bearings from panel-relative rects (offset coords, never page)
      const phase = ((T % 360) + 360) % 360;
      for (const c of records) {
        const cr = c.el.getBoundingClientRect();
        const dx = cr.left - rr.left + cr.width / 2 - PIVOT;
        const dy = cr.top - rr.top + cr.height / 2 - PIVOT;
        c.angle = ((Math.atan2(dy, dx) * 180) / Math.PI + 360) % 360;
        c.next = T + ((c.angle - phase + 360) % 360);
      }
      sized = true;
    };
    measure();

    // ---- painting: full clear each frame, pruned lists re-stroked ----------
    const DEG = Math.PI / 180;
    const draw = () => {
      if (!sized) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h); // explicit clear — no destination-in fading
      const a = (((T % 360) + 360) % 360) * DEG;
      const wr = wedgeDeg * DEG;

      // wedge: soft angular gradient trailing the arm, foreground 0 → 0.10
      let wedgeFill: CanvasGradient | string;
      if (typeof ctx.createConicGradient === "function") {
        const g = ctx.createConicGradient(a - wr, PIVOT, PIVOT);
        const f = wedgeDeg / 360;
        g.addColorStop(0, rgba(fg, 0));
        g.addColorStop(f, rgba(fg, 0.1));
        g.addColorStop(Math.min(1, f + 0.002), rgba(fg, 0));
        g.addColorStop(1, rgba(fg, 0));
        wedgeFill = g;
      } else {
        wedgeFill = rgba(fg, 0.05);
      }
      ctx.beginPath();
      ctx.moveTo(PIVOT, PIVOT);
      ctx.arc(PIVOT, PIVOT, maxR, a - wr, a);
      ctx.closePath();
      ctx.fillStyle = wedgeFill;
      ctx.fill();

      // sonar rings — stroked, alpha 0.18 → 0 across their travel
      ctx.lineWidth = 1;
      for (const ring of rings) {
        const alpha = RING_ALPHA * Math.max(0, 1 - ring.r / maxR);
        if (alpha <= 0.002 || ring.r <= 0) continue;
        ctx.beginPath();
        ctx.arc(PIVOT, PIVOT, ring.r, 0, Math.PI * 2);
        ctx.strokeStyle = rgba(fg, alpha);
        ctx.stroke();
      }

      // arm: 1px leading line — the only accent ink in the piece
      ctx.beginPath();
      ctx.moveTo(PIVOT, PIVOT);
      ctx.lineTo(PIVOT + Math.cos(a) * maxR, PIVOT + Math.sin(a) * maxR);
      ctx.strokeStyle = rgba(accent, 0.9);
      ctx.stroke();
    };

    // ---- card wake + tween ticking (direct DOM, hard end times) ------------
    const wakeCard = (c: Rec, earned: boolean) => {
      // re-targets on a second crossing: wakeAt resets, nothing stacks
      c.active = true;
      c.accent = earned;
      c.wakeAt = performance.now();
      c.valueEl.classList.remove("text-ns-muted");
      c.valueEl.classList.add("text-foreground");
      wake();
    };

    const tickCards = (now: number) => {
      let any = false;
      for (const c of records) {
        if (!c.active) continue;
        const t = now - c.wakeAt;
        if (t >= TWEEN_MS) {
          // forced completion at the stated durations — settle back to rest
          c.active = false;
          const done = c.format(c.target);
          if (c.lastText !== done) {
            c.valueEl.textContent = done;
            c.lastText = done;
          }
          c.el.style.borderColor = ""; // fall back to class border-border
          if (c.deltaEl) c.deltaEl.style.opacity = "1";
          c.valueEl.classList.remove("text-foreground");
          c.valueEl.classList.add("text-ns-muted");
          continue;
        }
        any = true;
        const txt = c.format(
          c.target * easeOutExpo(Math.min(1, t / COUNT_MS))
        );
        if (txt !== c.lastText) {
          c.valueEl.textContent = txt;
          c.lastText = txt;
        }
        if (c.deltaEl) {
          c.deltaEl.style.opacity = String(Math.min(1, t / DELTA_MS));
        }
        if (c.accent) {
          const k =
            t <= BORDER_IN_MS
              ? t / BORDER_IN_MS
              : Math.max(0, 1 - (t - BORDER_IN_MS) / BORDER_OUT_MS);
          const m = mixRGB(borderC, accent, k);
          c.el.style.borderColor = `rgb(${m.r},${m.g},${m.b})`;
        }
      }
      return any;
    };

    // ---- rAF loop: ambient sweep; sleeps offscreen/hidden/paused-settled ---
    let raf = 0;
    let last = 0;
    let visible = true;

    const loop = (now: number) => {
      raf = 0;
      if (!visible || document.hidden || !sized) {
        last = 0;
        return; // observers / visibilitychange wake us
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      if (!pausedRef.current) {
        T += degPerSec * dt;
        const rev = Math.floor(T / 360);
        if (rev > lastRev) {
          lastRev = rev;
          rings.push({ r: 0 }); // one ring per full revolution
          while (rings.length > MAX_RINGS) rings.shift();
          if (sweepRef.current) {
            sweepRef.current.textContent = `SWEEP ${String(rev + 1).padStart(3, "0")}`;
          }
        }
        for (const c of records) {
          if (T + toleranceDeg >= c.next) {
            wakeCard(c, true); // sweep-earned: accent border allowed
            c.next += 360; // logged once per pass — re-arm for next revolution
          }
        }
        for (const ring of rings) ring.r += RING_SPEED * dt;
        for (let i = rings.length - 1; i >= 0; i--) {
          if ((rings[i]?.r ?? 0) > maxR) rings.splice(i, 1); // pruned
        }
      }

      const tweening = tickCards(now);
      draw();

      if (pausedRef.current && !tweening) {
        last = 0;
        return; // frozen frame drawn above — genuinely asleep until resume
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    wakeRef.current = wake;

    // ---- observers + listeners ---------------------------------------------
    const ro = new ResizeObserver(() => {
      measure();
      wake();
    });
    ro.observe(root);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(root);
    const mo = new MutationObserver(() => {
      derive(); // live theme re-derive — next frame paints with new inks
      wake();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    // hover/focus wakes a card immediately — replay only, accent stays earned
    // `data-raised` mirrors group-hover/group-focus-visible so the CSS-only
    // raise overlay also responds to the site's synthetic autoplay driver,
    // which dispatches trusted-looking pointerenter/pointerleave but never
    // moves Chromium's real :hover state machine.
    const hoverBound: Array<[HTMLElement, string, () => void]> = [];
    for (const c of records) {
      const h = () => wakeCard(c, c.active && c.accent);
      const raise = () => {
        c.el.dataset.raised = "true";
      };
      const lower = () => {
        c.el.dataset.raised = "false";
      };
      c.el.addEventListener("pointerenter", h);
      c.el.addEventListener("focus", h);
      c.el.addEventListener("pointerenter", raise);
      c.el.addEventListener("focus", raise);
      c.el.addEventListener("pointerleave", lower);
      c.el.addEventListener("blur", lower);
      hoverBound.push(
        [c.el, "pointerenter", h],
        [c.el, "focus", h],
        [c.el, "pointerenter", raise],
        [c.el, "focus", raise],
        [c.el, "pointerleave", lower],
        [c.el, "blur", lower],
      );
    }

    wake();

    return () => {
      window.clearInterval(clockId);
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      for (const [el, type, h] of hoverBound) {
        el.removeEventListener(type, h);
      }
      wakeRef.current = null;
    };
  }, [stats, degPerSec, wedgeDeg, toleranceDeg]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      {/* radar layer — under the card grid, visible in gutters and padding */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute left-0 top-0 z-0"
      />
      {/* pivot: click to pause/resume the sweep */}
      <button
        type="button"
        onClick={togglePause}
        aria-pressed={paused}
        aria-label={paused ? "Resume radar sweep" : "Pause radar sweep"}
        className="absolute left-3.5 top-3.5 z-20 flex h-5 w-5 items-center justify-center rounded-full border border-border bg-surface text-ns-muted transition-colors duration-200 hover:border-foreground/25 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-foreground/70"
      >
        {paused ? (
          <span aria-hidden className="flex gap-[3px]">
            <span className="h-1.5 w-[2px] bg-current" />
            <span className="h-1.5 w-[2px] bg-current" />
          </span>
        ) : (
          <span aria-hidden className="h-1.5 w-1.5 rounded-full bg-current" />
        )}
      </button>
      <div className="relative z-10 p-6">
        <div className="mb-5 flex items-center gap-3 pl-7">
          <h3 className="text-sm font-medium tracking-tight text-foreground">
            {title}
          </h3>
          {paused ? (
            <span className="font-mono text-[10px] tracking-widest text-ns-muted">
              PAUSED
            </span>
          ) : null}
          <span
            ref={clockRef}
            suppressHydrationWarning
            className="ml-auto font-mono text-[11px] tabular-nums text-ns-muted"
          />
        </div>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          {stats.map((s, i) => (
            <div
              key={s.label}
              ref={(el) => {
                cardEls.current[i] = el;
              }}
              tabIndex={0}
              role="group"
              aria-label={`${s.label}: ${(s.format ?? defaultFormat)(s.value)}${
                s.delta ? `, ${s.delta}` : ""
              }`}
              className="group relative rounded-md border border-border bg-surface p-4 outline-none focus-visible:ring-2 focus-visible:ring-foreground/70"
            >
              {/* surface-step raise on hover/focus — token-relative, no accent
                  (`data-raised` mirrors group-hover/group-focus-visible so this
                  overlay also responds to the site's synthetic autoplay driver,
                  which never moves Chromium's real :hover state machine) */}
              <div
                aria-hidden
                className="pointer-events-none absolute inset-0 rounded-md bg-foreground/[0.045] opacity-0 transition-opacity duration-200 group-hover:opacity-100 group-focus-visible:opacity-100 group-data-[raised=true]:opacity-100"
              />
              <div className="relative">
                <div className="flex items-center gap-1.5 text-ns-muted">
                  {s.icon}
                  <span className="font-mono text-[10px] uppercase tracking-widest">
                    {s.label}
                  </span>
                </div>
                <div className="mt-2.5 flex items-baseline gap-2">
                  <span
                    data-value
                    className="font-mono text-lg tabular-nums text-ns-muted transition-colors duration-500"
                  >
                    {(s.format ?? defaultFormat)(s.value)}
                  </span>
                  {s.delta ? (
                    <span
                      data-delta
                      className="font-mono text-[11px] tabular-nums text-ns-muted"
                    >
                      {s.delta}
                    </span>
                  ) : null}
                </div>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-5 flex items-center justify-between font-mono text-[10px] tracking-widest text-ns-muted">
          <span ref={sweepRef}>SWEEP 001</span>
          <span>
            {stats.length} SENSORS · {Math.round(360 / Math.max(1, degPerSec))}S
            INTERVAL
          </span>
        </div>
      </div>
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// BeaconCadence — an inline status glyph for agent/AI work where the MOTION
// PATTERN is the signal, not color and not a swapped icon. One field of six
// SVG dots (a hexagonal ring) plus a center accent; each state gives that
// same field a distinct cadence: working spins it steadily, searching sweeps
// a bright cluster back and forth across a bounded arc, awaiting-input holds
// everything still but breathes a center dot, blocked snap-jitters the ring
// through a broken gap, done stops moving entirely on a complete ring with a
// settle-in checkmark. Every dot's resting (non-animated) opacity is chosen
// so the shape alone reads as that state — that resting frame is also
// exactly what prefers-reduced-motion falls back to, so reduced motion never
// collapses two states into the same frozen spinner. Pure CSS keyframes on
// SVG transforms, all ink from --foreground, zero dependencies.
// ---------------------------------------------------------------------------

export type BeaconCadenceState =
  | "working"
  | "searching"
  | "awaiting-input"
  | "blocked"
  | "done";

const STATE_LABEL: Record<BeaconCadenceState, string> = {
  working: "Working",
  searching: "Searching",
  "awaiting-input": "Awaiting input",
  blocked: "Blocked",
  done: "Done",
};

// six ring positions on a 24x24 viewBox, clock-style starting at 12 o'clock,
// clockwise — a hexagon reads cleanly at 20px where 8+ dots start to smear.
const RING: ReadonlyArray<readonly [number, number]> = [
  [12, 4],
  [18.93, 8],
  [18.93, 16],
  [12, 20],
  [5.07, 16],
  [5.07, 8],
];

// Per-state resting opacity for the six ring dots. This is the shape a
// screen-off, motion-off viewer gets, so each row has to be legible as its
// state entirely on its own — not a coincidence of where a rotation stopped.
const RING_OPACITY: Record<BeaconCadenceState, readonly number[]> = {
  working: [1, 0.83, 0.66, 0.49, 0.32, 0.15], // decaying comet trail
  searching: [1, 0.7, 0.15, 0.15, 0.15, 0.15], // small bright beam cluster
  "awaiting-input": [0.22, 0.22, 0.22, 0.22, 0.22, 0.22], // even + dim, center carries it
  blocked: [0, 0.55, 0.55, 0.55, 0.55, 0.55], // one dot missing — the ring can't close
  done: [1, 1, 1, 1, 1, 1], // complete
};

const DOT_R = 1.7;

const CSS = `
.ns-bc-ring{transform-box:fill-box;transform-origin:center;}
.ns-bc-center{transform-box:fill-box;transform-origin:center;}
.ns-bc-check{transform-box:fill-box;transform-origin:center;}
.ns-bc-spin{animation:ns-bc-spin 1.2s linear infinite;}
.ns-bc-sweep{animation:ns-bc-sweep 1.7s cubic-bezier(.45,0,.55,1) infinite;}
.ns-bc-tremor{animation:ns-bc-tremor 1.5s steps(1) infinite;}
.ns-bc-pulse{animation:ns-bc-pulse 1.9s ease-in-out infinite;}
.ns-bc-settle{animation:ns-bc-settle .42s cubic-bezier(.34,1.56,.64,1) both;}
@keyframes ns-bc-spin{to{transform:rotate(360deg)}}
@keyframes ns-bc-sweep{
  0%,100%{transform:rotate(-35deg)}
  50%{transform:rotate(35deg)}
}
@keyframes ns-bc-tremor{
  0%,58%,100%{transform:rotate(0deg)}
  15%{transform:rotate(9deg)}
  30%{transform:rotate(-5deg)}
  44%{transform:rotate(3deg)}
}
@keyframes ns-bc-pulse{
  0%,100%{transform:scale(.8);opacity:.5}
  50%{transform:scale(1.22);opacity:1}
}
@keyframes ns-bc-settle{
  from{transform:scale(.5);opacity:0}
  to{transform:scale(1);opacity:1}
}
@media (prefers-reduced-motion: reduce){
  .ns-bc-spin,.ns-bc-sweep,.ns-bc-tremor,.ns-bc-pulse,.ns-bc-settle{animation:none;}
}
`;

const RING_ANIMATION_CLASS: Record<BeaconCadenceState, string> = {
  working: "ns-bc-spin",
  searching: "ns-bc-sweep",
  "awaiting-input": "",
  blocked: "ns-bc-tremor",
  done: "",
};

export interface BeaconCadenceProps {
  /** which cadence to render — the motion pattern IS the state, color never is */
  state: BeaconCadenceState;
  /** glyph size in px, meant to sit inline beside a text label. legible 20-64. */
  size?: number;
  /**
   * accessible text announced via the component's own aria-live region on
   * every state change (e.g. "Solving…"). Defaults to a plain state name.
   * If the consumer already renders a visible adjacent label that updates
   * with state, either pass that same string here (redundant but harmless
   * for sighted users) or aria-hide their own label to avoid a double
   * announcement — the glyph is the one guaranteed to announce transitions.
   */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BeaconCadence({
  state,
  size = 24,
  label,
  className = "",
}: BeaconCadenceProps) {
  const opacities = RING_OPACITY[state];
  const ringClass = RING_ANIMATION_CLASS[state];

  return (
    <span
      role="status"
      aria-live="polite"
      className={`inline-flex shrink-0 items-center justify-center ${className}`}
      style={{ width: size, height: size }}
    >
      <style>{CSS}</style>
      <svg
        key={state}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        aria-hidden="true"
        focusable="false"
      >
        <g className={ringClass ? `ns-bc-ring ${ringClass}` : "ns-bc-ring"}>
          {RING.map(([x, y], i) => (
            <circle
              key={i}
              cx={x}
              cy={y}
              r={DOT_R}
              style={{ fill: "var(--foreground)", opacity: opacities[i] }}
            />
          ))}
        </g>

        {state === "awaiting-input" && (
          <circle
            className="ns-bc-center ns-bc-pulse"
            cx={12}
            cy={12}
            r={2.8}
            style={{ fill: "var(--foreground)" }}
          />
        )}

        {state === "done" && (
          <path
            className="ns-bc-check"
            d="M8.3 12.4l2.5 2.5 4.9-5.4"
            fill="none"
            stroke="var(--foreground)"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        )}
      </svg>
      <span className="sr-only">{label ?? STATE_LABEL[state]}</span>
    </span>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MetaballMerge — group membership drawn as an IMPLICIT SURFACE. Every item is
// a charge in an inverse-square scalar field, F(x,y) = Σ rᵢ² / (dᵢ² + 1e-3),
// and the only thing ever painted is the marching-squares isoline at F = 1,
// stroked as a bare hairline. Nothing is filled, so the frame stays almost
// entirely empty and the SHAPE carries the whole message: charges close enough
// together share one necked contour, and an item that leaves visibly pinches
// off into its own closed loop. No legend, no caption, no colour code.
// ---------------------------------------------------------------------------

export interface MetaballItem {
  id: string;
  label: string;
  /** starts inside the group (default true) */
  member?: boolean;
}

export interface MetaballMergeProps {
  /** the mergeable blobs */
  items?: MetaballItem[];
  /** names the group for assistive tech */
  label?: string;
  /** called with the full list of selected (merged) ids after any toggle */
  onChange?: (memberIds: string[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_ITEMS: MetaballItem[] = [
  { id: "mara", label: "Mara Chen" },
  { id: "jonas", label: "Jonas Weber" },
  { id: "aiko", label: "Aiko Tanaka" },
  { id: "ravi", label: "Ravi Patel", member: false },
];

// --- field / isoline ------------------------------------------------------
const GRID = 4; // px lattice for marching squares
const ISO = 1.0; // threshold — a lone charge's contour is exactly its radius
const EPS = 1e-3; // softening, keeps F finite at a charge centre
const STROKE_W = 1.25;
const STROKE_A = 0.85;

// --- layout ---------------------------------------------------------------
const IN_F = 0.5; // member anchor, as a fraction of the cluster radius Rc
const OUT_F = 1.35; // non-member anchor — comfortably past the merge distance
const FIT = 0.47; // outermost anchor + its radius, as a fraction of min(w,h)
// Charge radius is derived from the member-to-member chord rather than picked
// by eye: two equal charges a chord S apart neck at half-width
// √(2r² − S²/4), so r = 0.4·S puts the waist at ~0.66r — thin enough to read
// as a genuine neck, thick enough that the ±6% ambient breathing never
// severs it. Member slots sit one ARC step apart, so that chord is constant.
const R_OF_CHORD = 0.4;
const HOVER_SWELL = 1.18;

// --- motion ---------------------------------------------------------------
const K = 120; // spring stiffness, s^-2
const ZETA = 1.0; // critically damped
const C = 2 * ZETA * Math.sqrt(K);
const ORBIT_R = 3; // px ambient orbit radius
const ORBIT_HZ = 0.11;
const BREATHE = 0.06; // ±6% radius
const BREATHE_HZ = 0.07;
const DT_MAX = 0.05;
const SETTLED = 0.02;
const TAU = Math.PI * 2;

// 16-case marching-squares segment table; corner bits are TL=1 TR=2 BR=4 BL=8
// and an edge index is 0=top 1=right 2=bottom 3=left. Cases 5 and 10 are the
// saddles and are resolved from the cell-centre sample instead.
const CASES: number[][] = [
  [],
  [3, 0],
  [0, 1],
  [3, 1],
  [1, 2],
  [],
  [0, 2],
  [3, 2],
  [2, 3],
  [2, 0],
  [],
  [2, 1],
  [1, 3],
  [1, 0],
  [0, 3],
  [],
];

function hash01(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}

/** shortest signed angle from a to b, in (-π, π] */
function angleDelta(a: number, b: number): number {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d <= -Math.PI) d += TAU;
  return d;
}

type Charge = {
  id: string;
  home: number; // the item's own direction from the centroid
  slot: number; // the direction it is currently anchored along
  dist: number; // anchor distance as a fraction of Rc
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  vr: number;
  phase: number;
  breathPhase: number;
  member: boolean;
  hover: boolean;
};

export function MetaballMerge({
  items = DEFAULT_ITEMS,
  label = "Group",
  onChange,
  className = "",
}: MetaballMergeProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [members, setMembers] = useState<string[]>(() =>
    items.filter((it) => it.member !== false).map((it) => it.id)
  );
  const membersRef = useRef(members);
  membersRef.current = members;
  const engineRef = useRef<{
    sync: () => void;
    setHover: (index: number, on: boolean) => void;
  } | null>(null);

  useEffect(() => {
    engineRef.current?.sync();
  }, [members]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const n = items.length;
    // Member slots are one ARC_STEP apart on the inner circle. 2π/(n+2)
    // guarantees the arc still has a 3-step gap even with every item inside,
    // so the cluster is always an open chain and never closes into a ring
    // with a hole punched through the middle.
    const ARC_STEP = TAU / (n + 2);
    const CHORD = 2 * IN_F * Math.sin(ARC_STEP / 2); // in units of Rc
    const R_F = R_OF_CHORD * CHORD; // charge radius, in units of Rc

    const charges: Charge[] = items.map((it, i) => {
      const home = -Math.PI / 2 + (TAU * i) / Math.max(1, n);
      return {
        id: it.id,
        home,
        slot: home,
        dist: OUT_F,
        x: 0,
        y: 0,
        vx: 0,
        vy: 0,
        r: 0,
        vr: 0,
        phase: hash01(it.id) * TAU,
        breathPhase: hash01(it.id + "~b") * TAU,
        member: false,
        hover: false,
      };
    });

    let ink = "currentColor";
    let w = 0;
    let h = 0;
    let cx = 0;
    let cy = 0;
    let rc = 0;
    let gw = 0;
    let gh = 0;
    let field = new Float32Array(0);
    let sized = false;
    let seeded = false;
    let raf = 0;
    let last = 0;
    let t = 0;

    const readInk = () => {
      ink = getComputedStyle(canvas).color;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 8 || rect.height < 8) {
        sized = false;
        return;
      }
      w = rect.width;
      h = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cx = w / 2;
      cy = h / 2;
      // the outermost anchor plus its own radius has to stay inside the box
      rc = (FIT * Math.min(w, h)) / (OUT_F + R_F);
      gw = Math.floor(w / GRID) + 1;
      gh = Math.floor(h / GRID) + 1;
      if (field.length !== gw * gh) field = new Float32Array(gw * gh);
      sized = true;
    };

    // Membership decides BOTH the anchor distance and which slot the item
    // takes: members are packed onto consecutive slots of an arc centred on
    // their own mean direction, so every member is a neighbour of another
    // member and the group is always one connected contour — never two
    // "grouped" items sitting too far apart to merge. Non-members keep their
    // own direction and are pushed out to 1.35·Rc.
    const relayout = () => {
      const set = membersRef.current;
      for (const c of charges) c.member = set.includes(c.id);
      const mem = charges.filter((c) => c.member);
      for (const c of charges) {
        if (!c.member) {
          c.slot = c.home;
          c.dist = OUT_F;
        }
      }
      if (mem.length === 0) return;
      let sx = 0;
      let sy = 0;
      for (const c of mem) {
        sx += Math.cos(c.home);
        sy += Math.sin(c.home);
      }
      const mean =
        sx === 0 && sy === 0 ? charges[0]!.home : Math.atan2(sy, sx);
      // keep the members' original circular order so slots never cross
      mem.sort((a, b) => angleDelta(mean, a.home) - angleDelta(mean, b.home));
      const half = (mem.length - 1) / 2;
      mem.forEach((c, k) => {
        c.slot = mean + (k - half) * ARC_STEP;
        c.dist = IN_F;
      });
    };

    const targetOf = (c: Charge) => ({
      x: cx + Math.cos(c.slot) * c.dist * rc,
      y: cy + Math.sin(c.slot) * c.dist * rc,
      r: R_F * rc * (c.hover ? HOVER_SWELL : 1),
    });

    const seed = () => {
      for (const c of charges) {
        const tg = targetOf(c);
        c.x = tg.x;
        c.y = tg.y;
        c.r = tg.r;
        c.vx = c.vy = c.vr = 0;
      }
      seeded = true;
    };

    // integrate every spring one step; returns true while anything still moves
    const step = (dt: number) => {
      let moving = false;
      for (const c of charges) {
        const tg = targetOf(c);
        const ax = -K * (c.x - tg.x) - C * c.vx;
        const ay = -K * (c.y - tg.y) - C * c.vy;
        const ar = -K * (c.r - tg.r) - C * c.vr;
        c.vx += ax * dt;
        c.vy += ay * dt;
        c.vr += ar * dt;
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        c.r += c.vr * dt;
        if (
          Math.abs(c.x - tg.x) > SETTLED ||
          Math.abs(c.y - tg.y) > SETTLED ||
          Math.abs(c.r - tg.r) > SETTLED ||
          Math.abs(c.vx) > SETTLED ||
          Math.abs(c.vy) > SETTLED ||
          Math.abs(c.vr) > SETTLED
        ) {
          moving = true;
        }
      }
      return moving;
    };

    // resolved charge positions/radii for this frame, ambient pulse folded in
    const px = new Float64Array(n);
    const py = new Float64Array(n);
    const pr2 = new Float64Array(n);

    const resolve = (time: number) => {
      for (let i = 0; i < n; i++) {
        const c = charges[i]!;
        if (reduced) {
          px[i] = c.x;
          py[i] = c.y;
          pr2[i] = c.r * c.r;
          continue;
        }
        const a = TAU * ORBIT_HZ * time + c.phase;
        px[i] = c.x + Math.cos(a) * ORBIT_R;
        py[i] = c.y + Math.sin(a) * ORBIT_R;
        const br =
          c.r * (1 + BREATHE * Math.sin(TAU * BREATHE_HZ * time + c.breathPhase));
        pr2[i] = br * br;
      }
    };

    const fieldAt = (x: number, y: number) => {
      let f = 0;
      for (let i = 0; i < n; i++) {
        const dx = x - px[i]!;
        const dy = y - py[i]!;
        f += pr2[i]! / (dx * dx + dy * dy + EPS);
      }
      return f;
    };

    const render = () => {
      if (!sized) return;
      ctx.clearRect(0, 0, w, h);

      for (let gy = 0; gy < gh; gy++) {
        const y = gy * GRID;
        const row = gy * gw;
        for (let gx = 0; gx < gw; gx++) {
          field[row + gx] = fieldAt(gx * GRID, y);
        }
      }

      const path = new Path2D();
      // linear interpolation along a cell edge — a midpoint placement here is
      // what makes a marching-squares contour look visibly stair-stepped
      const lerp = (fa: number, fb: number) => {
        const d = fb - fa;
        if (Math.abs(d) < 1e-9) return 0.5;
        const tx = (ISO - fa) / d;
        return tx < 0 ? 0 : tx > 1 ? 1 : tx;
      };

      for (let gy = 0; gy < gh - 1; gy++) {
        const r0 = gy * gw;
        const r1 = r0 + gw;
        const y0 = gy * GRID;
        const y1 = y0 + GRID;
        for (let gx = 0; gx < gw - 1; gx++) {
          const f00 = field[r0 + gx]!;
          const f10 = field[r0 + gx + 1]!;
          const f11 = field[r1 + gx + 1]!;
          const f01 = field[r1 + gx]!;
          let mask = 0;
          if (f00 >= ISO) mask |= 1;
          if (f10 >= ISO) mask |= 2;
          if (f11 >= ISO) mask |= 4;
          if (f01 >= ISO) mask |= 8;
          if (mask === 0 || mask === 15) continue;

          const x0 = gx * GRID;
          const x1 = x0 + GRID;

          let segs = CASES[mask]!;
          if (mask === 5 || mask === 10) {
            // saddle: the cell-centre sample decides whether the two inside
            // corners are joined through the middle or genuinely separate,
            // which is what makes a neck pinch instead of resolving as an X
            const inside = fieldAt(x0 + GRID / 2, y0 + GRID / 2) >= ISO;
            if (mask === 5) segs = inside ? [0, 1, 2, 3] : [3, 0, 1, 2];
            else segs = inside ? [3, 0, 1, 2] : [0, 1, 2, 3];
          }

          for (let s = 0; s < segs.length; s += 2) {
            const ea = segs[s]!;
            const eb = segs[s + 1]!;
            for (let k = 0; k < 2; k++) {
              const e = k === 0 ? ea : eb;
              let ptx = 0;
              let pty = 0;
              if (e === 0) {
                ptx = x0 + lerp(f00, f10) * GRID;
                pty = y0;
              } else if (e === 1) {
                ptx = x1;
                pty = y0 + lerp(f10, f11) * GRID;
              } else if (e === 2) {
                ptx = x1 - lerp(f11, f01) * GRID;
                pty = y1;
              } else {
                ptx = x0;
                pty = y1 - lerp(f01, f00) * GRID;
              }
              if (k === 0) path.moveTo(ptx, pty);
              else path.lineTo(ptx, pty);
            }
          }
        }
      }

      ctx.strokeStyle = ink;
      ctx.lineWidth = STROKE_W;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.globalAlpha = STROKE_A;
      ctx.stroke(path);
      ctx.globalAlpha = 1;
    };

    const drawStill = () => {
      if (!sized) return;
      resolve(0);
      render();
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const moving = step(dt);
      resolve(t);
      render();
      // the loop only sleeps when the springs have settled AND there is no
      // ambient pulse left to render — i.e. never, unless motion is reduced
      raf = document.hidden || (reduced && !moving) ? 0 : requestAnimationFrame(loop);
    };

    const start = () => {
      if (reduced || raf) return;
      last = 0;
      raf = requestAnimationFrame(loop);
    };

    const sync = () => {
      relayout();
      if (!sized) return;
      if (reduced) {
        // no ambient motion, no glide: jump the anchors and repaint one frame
        seed();
        drawStill();
      } else {
        start();
      }
    };

    engineRef.current = {
      sync,
      setHover: (index, on) => {
        // reduced motion: the swell is a pointer-driven animation, so it is
        // dropped entirely rather than jumped to — the chip's own focus ring
        // still carries the cue
        if (reduced) return;
        const c = charges[index];
        if (!c) return;
        c.hover = on;
        start();
      },
    };

    const ro = new ResizeObserver(() => {
      const before = sized;
      resize();
      if (!sized) return;
      if (!before || !seeded) seed();
      if (reduced) drawStill();
      else start();
    });
    ro.observe(canvas);

    const mo = new MutationObserver(() => {
      readInk();
      if (reduced) drawStill();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onVis = () => {
      if (!document.hidden) start();
    };
    document.addEventListener("visibilitychange", onVis);

    readInk();
    relayout();
    resize();
    if (sized) seed();
    if (reduced) drawStill();
    else start();

    return () => {
      engineRef.current = null;
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [items]);

  const toggle = (id: string) => {
    setMembers((prev) => {
      const next = prev.includes(id)
        ? prev.filter((m) => m !== id)
        : [...prev, id];
      onChange?.(next);
      return next;
    });
  };

  const count = members.length;

  return (
    <div className={`flex w-full flex-col gap-4 ${className}`}>
      <div className="relative w-full" style={{ aspectRatio: "6 / 5" }}>
        <canvas
          ref={canvasRef}
          aria-hidden
          className="absolute inset-0 block h-full w-full text-foreground"
        />
      </div>

      <div className="flex flex-col items-center gap-3">
        <div
          role="group"
          aria-label={label}
          className="flex flex-wrap items-center justify-center gap-2"
        >
          {items.map((it, i) => {
            const isMember = members.includes(it.id);
            return (
              <button
                key={it.id}
                type="button"
                aria-pressed={isMember}
                onClick={() => toggle(it.id)}
                onPointerEnter={() => engineRef.current?.setHover(i, true)}
                onPointerLeave={() => engineRef.current?.setHover(i, false)}
                onFocus={() => engineRef.current?.setHover(i, true)}
                onBlur={() => engineRef.current?.setHover(i, false)}
                className={`flex items-center gap-2 rounded-full border px-3 py-1.5 font-mono text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
                  isMember
                    ? "border-foreground/40 text-foreground"
                    : "border-border text-ns-muted"
                }`}
              >
                <span
                  aria-hidden
                  className={`size-1.5 rounded-full ${
                    isMember ? "bg-foreground" : "bg-border"
                  }`}
                />
                {it.label}
              </button>
            );
          })}
        </div>

        <p
          aria-hidden
          data-merged={count}
          className="font-mono text-[10px] uppercase tracking-[0.18em] text-ns-muted"
        >
          {count} of {items.length} in {label}
        </p>
        <span aria-live="polite" className="sr-only">
          {`${count} ${count === 1 ? "item" : "items"} grouped`}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GyreMote — an AI "thinking" indicator rendered as a rotating sphere of dots,
// pure SVG (<circle> pool) + one direct-DOM rAF loop, NO canvas and NO WebGL.
// ~80-140 points are placed on a unit sphere by a Fibonacci/golden-spiral
// distribution so they read as an even field, spun about a tilted vertical
// axis, projected to 2D, then depth-sorted and repainted back-to-front every
// frame. Depth is the whole signature: a dot near the viewer is larger, fully
// opaque and inked with --foreground; a dot on the far side is smaller, dim,
// and inked with --ns-muted — that size+opacity ramp is what makes the field read
// as a SPHERE and not a flat ring. Four states are distinct by MOTION, not
// color: thinking = steady spin; searching = spin plus an accent latitude band
// that sweeps pole to pole; done = the sphere contracts and decelerates to a
// calm, brighter, settled ball; idle = a very slow drift with a gentle axis
// wobble. Every color is a CSS custom property already in scope, so both
// themes inherit correctly. prefers-reduced-motion freezes the loop and leaves
// a static, still-depth-cued sphere whose state stays legible (searching keeps
// a static band, done keeps its settled contracted look). One rAF loop, paused
// when the tab is hidden, cancelled on unmount. Zero dependencies.
// ---------------------------------------------------------------------------

export type GyreMoteState = "thinking" | "searching" | "done" | "idle";

const STATE_LABEL: Record<GyreMoteState, string> = {
  thinking: "Thinking…",
  searching: "Searching…",
  done: "Done",
  idle: "Idle",
};

// viewBox is a fixed 100x100 box; all geometry is in those units and scales
// with the pixel `size`, so nothing has to be recomputed per pixel size.
const VB = 100;
const CX = VB / 2;
const CY = VB / 2;
const SPHERE_R = 38; // sphere radius in viewBox units
const GOLDEN = Math.PI * (3 - Math.sqrt(5)); // ~2.399963 rad
const TILT = -0.42; // fixed view tilt (radians) — look slightly from above
const TAU = Math.PI * 2;

// per-state target angular velocity (rad/s) and resting sphere scale
const STATE_VEL: Record<GyreMoteState, number> = {
  thinking: 0.72,
  searching: 0.52,
  done: 0.05,
  idle: 0.13,
};
const STATE_SCALE: Record<GyreMoteState, number> = {
  thinking: 1,
  searching: 1,
  done: 0.84, // contracts to a calm, smaller ball
  idle: 1,
};

// dot count scales with size for legibility: fewer, cleaner dots when tiny;
// a denser field when it is a showpiece.
function dotCount(size: number): number {
  const n = Math.round(80 + (size - 24) * 0.34);
  return Math.max(80, Math.min(140, n));
}

export interface GyreMoteProps {
  /** diameter in px. legible from ~24 inline to ~200 as a showpiece. default 96. */
  size?: number;
  /** which cadence to render — the motion pattern is the signal, not color. default "thinking". */
  state?: GyreMoteState;
  /**
   * accessible text announced via the component's own aria-live region on
   * every state change. Defaults to a plain state name ("Thinking…"). Pass the
   * same string you show in an adjacent visible label so the two never diverge.
   */
  label?: string;
  /** render `label` as a visible text node beside the sphere (still announced). */
  showLabel?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GyreMote({
  size = 96,
  state = "thinking",
  label,
  showLabel = false,
  className = "",
}: GyreMoteProps) {
  const N = dotCount(size);

  const svgRef = useRef<SVGSVGElement>(null);
  const circleEls = useRef<(SVGCircleElement | null)[]>([]);
  const stateRef = useRef<GyreMoteState>(state);
  const drawRef = useRef<(() => void) | null>(null);
  const doneStartRef = useRef(-1);

  // main animation effect — rebuilt only when the point count changes.
  useEffect(() => {
    const circles = circleEls.current.slice(0, N);
    if (circles.some((c) => !c)) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // Fibonacci sphere — even golden-spiral distribution. bx/by/bz is the
    // resting point; by (latitude) is invariant under the Y-axis spin, so a
    // latitude band stays a clean horizontal ring while the sphere rotates.
    const bx = new Float64Array(N);
    const by = new Float64Array(N);
    const bz = new Float64Array(N);
    for (let i = 0; i < N; i++) {
      const y = 1 - (i / (N - 1)) * 2;
      const rad = Math.sqrt(Math.max(0, 1 - y * y));
      const th = i * GOLDEN;
      bx[i] = Math.cos(th) * rad;
      by[i] = y;
      bz[i] = Math.sin(th) * rad;
    }

    // scratch buffers for the projected frame + a depth-sort index
    const sx = new Float64Array(N);
    const sy = new Float64Array(N);
    const sr = new Float64Array(N);
    const so = new Float64Array(N);
    const sd = new Float64Array(N); // view depth zv, the sort key
    const sf = new Uint8Array(N); // 0 muted, 1 foreground, 2 accent (band)
    const order = new Int32Array(N);
    for (let i = 0; i < N; i++) order[i] = i;

    const cosT = Math.cos(TILT);
    const sinT = Math.sin(TILT);

    // dot radii in viewBox units — near dots ~2.7x the far dots.
    const R_FAR = 1.15;
    const R_NEAR = 3.15;

    // compute one frame and paint it back-to-front into the circle pool.
    const drawFrame = (
      angle: number,
      scale: number,
      bandCenter: number | null,
      dimFar: number
    ) => {
      const ca = Math.cos(angle);
      const sa = Math.sin(angle);
      const r = SPHERE_R * scale;

      for (let i = 0; i < N; i++) {
        const x0 = bx[i]!;
        const y0 = by[i]!;
        const z0 = bz[i]!;
        // spin about Y
        const xr = x0 * ca + z0 * sa;
        const zr = -x0 * sa + z0 * ca;
        // tilt about X (view)
        const yv = y0 * cosT - zr * sinT;
        const zv = y0 * sinT + zr * cosT;

        const depth = (zv + 1) * 0.5; // 0 back .. 1 front
        const persp = 1 / (1 - zv * 0.16); // mild bulge toward the viewer

        sx[i] = CX + xr * r * persp;
        sy[i] = CY - yv * r * persp;
        sd[i] = zv;

        let rr = R_FAR + depth * (R_NEAR - R_FAR);
        let oo = (0.12 + depth * 0.88) * dimFar; // idle drops presence
        let fill: number = depth >= 0.5 ? 1 : 0; // fg near / muted far

        // searching: an accent latitude band sweeping pole to pole. by is
        // spin-invariant, so this is a horizontal ring gliding vertically.
        if (bandCenter !== null) {
          const d = Math.abs(y0 - bandCenter);
          if (d < 0.26) {
            const k = 1 - d / 0.26; // 0 edge .. 1 centre of band
            rr += k * 1.4;
            oo = Math.min(1, oo + k * 0.6);
            fill = 2;
          }
        }

        sr[i] = rr;
        so[i] = oo;
        sf[i] = fill;
      }

      // depth sort: back (small zv) first so near dots paint over far ones.
      // insertion sort — stable and near-linear on the nearly-sorted frames.
      for (let a = 1; a < N; a++) {
        const v = order[a]!;
        const kz = sd[v]!;
        let b = a - 1;
        while (b >= 0 && sd[order[b]!]! > kz) {
          order[b + 1] = order[b]!;
          b--;
        }
        order[b + 1] = v;
      }

      for (let k = 0; k < N; k++) {
        const i = order[k]!;
        const c = circles[k]!;
        c.setAttribute("cx", sx[i]!.toFixed(2));
        c.setAttribute("cy", sy[i]!.toFixed(2));
        c.setAttribute("r", sr[i]!.toFixed(2));
        c.style.opacity = so[i]!.toFixed(3);
        c.style.fill =
          sf[i] === 2
            ? "var(--ns-accent)"
            : sf[i] === 1
              ? "var(--foreground)"
              : "var(--ns-muted)";
      }
    };

    // ---- reduced motion: one static, depth-cued frame, no loop ----
    if (reduced) {
      const paint = () => {
        const st = stateRef.current;
        const band = st === "searching" ? 0.12 : null;
        const scale = st === "done" ? STATE_SCALE.done : 1;
        const dim = st === "idle" ? 0.6 : 1;
        drawFrame(0.7, scale, band, dim);
      };
      drawRef.current = paint;
      paint();
      return () => {
        drawRef.current = null;
      };
    }

    // ---- animated: one rAF loop, sole DOM writer ----
    let raf = 0;
    let last = 0;
    let angle = 0.3;
    let vel = STATE_VEL[stateRef.current];
    let scale = STATE_SCALE[stateRef.current];

    const loop = (now: number) => {
      const t = now / 1000;
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, t - last);
      last = t;

      const st = stateRef.current;
      const targetVel = STATE_VEL[st];
      const targetScale = STATE_SCALE[st];

      // ease angular velocity + sphere scale toward their per-state targets
      vel += (targetVel - vel) * (1 - Math.exp(-dt * 4));
      scale += (targetScale - scale) * (1 - Math.exp(-dt * 5));

      // idle: gentle axis wobble layered on the slow drift
      let ang = angle;
      if (st === "idle") ang += Math.sin(t * 0.5) * 0.12;
      angle += vel * dt;

      // searching: latitude band sweeps pole to pole on a 2.4s cosine
      const band =
        st === "searching" ? Math.cos(t * (TAU / 2.4)) * 0.92 : null;

      // done: brief inward convergence overshoot on entry, then holds calm.
      let sc = scale;
      let dim = 1;
      if (st === "done") {
        const ds = doneStartRef.current;
        if (ds >= 0) {
          const p = (now - ds) / 620;
          if (p < 1) {
            // ease-out with a small settle dip below the resting scale
            const e = 1 - Math.pow(1 - p, 3);
            sc = scale - Math.sin(p * Math.PI) * 0.06 * (1 - e * 0.4);
          } else {
            doneStartRef.current = -1;
          }
        }
      }
      if (st === "idle") dim = 0.62;

      drawFrame(ang, sc, band, dim);
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (raf === 0 && !document.hidden) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const stop = () => {
      if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
        last = 0;
      }
    };
    // pause when the tab is hidden — no wasted frames, no leaked loop
    const onVis = () => (document.hidden ? stop() : start());
    document.addEventListener("visibilitychange", onVis);

    drawRef.current = null; // animated path owns the DOM; no external repaint
    start();

    return () => {
      stop();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [N]);

  // state lives in a ref so the loop is never torn down on a state change.
  // On entering `done`, stamp the convergence start; under reduced motion,
  // repaint the static frame so the new state reads immediately.
  useEffect(() => {
    const prev = stateRef.current;
    stateRef.current = state;
    if (state === "done" && prev !== "done") {
      doneStartRef.current =
        typeof performance !== "undefined" ? performance.now() : 0;
    }
    drawRef.current?.();
  }, [state]);

  const text = label ?? STATE_LABEL[state];

  return (
    <span
      role="status"
      aria-live="polite"
      className={`inline-flex shrink-0 items-center gap-2.5 ${className}`}
    >
      <svg
        ref={svgRef}
        viewBox={`0 0 ${VB} ${VB}`}
        width={size}
        height={size}
        aria-hidden="true"
        focusable="false"
        className="block overflow-visible"
      >
        {Array.from({ length: N }, (_, i) => (
          <circle
            key={i}
            ref={(el) => {
              circleEls.current[i] = el;
            }}
            cx={CX}
            cy={CY}
            r={1.5}
            style={{ fill: "var(--ns-muted)" }}
          />
        ))}
      </svg>
      {showLabel ? (
        <span className="text-sm text-ns-muted">{text}</span>
      ) : (
        <span className="sr-only">{text}</span>
      )}
    </span>
  );
}

"use client";

import { useEffect, useId, useRef } from "react";

// ---------------------------------------------------------------------------
// SteamTrapBatchFlush — an inline sync-status glyph modelled on a
// float-and-thermostatic steam trap: condensate (locally-buffered pending
// events) collects in a small chamber until a float trips a discharge valve
// open, the chamber blows down fast, and it starts refilling immediately.
// The read is entirely motion + fill level, no colour swap, no icon change.
//
// Real numbers from the spec: fill takes 3.2s to go from empty (0%) to the
// trip line (88% of chamber height) — that sets a constant fill rate of
// 0.88/3.2 = 0.275 fraction/s, applied continuously whenever the chamber is
// filling, including the post-blowdown refill that resumes from 6% rather
// than 0%. Blowdown itself is 340ms, fraction falling 88% -> 6% on an
// eased-out curve (fast, front-loaded — the real mechanical blowdown is far
// quicker than the fill it releases). The float rides the top of the fill
// and overshoots 2 (viewBox) units below the falling fill line during
// blowdown before settling back onto the new level over a short damped
// window — the mechanical snap-back read that separates this from a plain
// sawtooth reset.
//
// Because refill resumes from 6% (not 0%) at the same constant rate, the
// steady-state loop is genuinely periodic: fill 6% -> 88% takes
// (0.88-0.06)/0.275 ~= 2.98s, plus the 340ms blowdown, for a full cycle of
// ~3.32s — close to the spec's "~3.6s", the difference being that a
// constant, spec-derived fill rate is preserved exactly rather than padding
// the cycle to hit the round number.
// ---------------------------------------------------------------------------

const TRIP_FRACTION = 0.88;
const LOW_FRACTION = 0.06;
const FILL_DURATION_MS = 3200; // empty (0) -> trip (0.88), sets the rate
const FILL_RATE = TRIP_FRACTION / (FILL_DURATION_MS / 1000); // fraction / s
const BLOWDOWN_MS = 340;
const OVERSHOOT_UNITS = 2; // viewBox units the float dips past the settled line
const OVERSHOOT_SETTLE_MS = 180;

// chamber geometry, 24x24 viewBox
const CHAMBER = { x: 5, y: 3, w: 14, h: 18, rx: 2 };
const FILL_X = 6;
const FILL_W = 12;
const FILL_BOTTOM = 20; // chamber inner floor
const FILL_TOP_MAX = 4; // chamber inner ceiling (fraction = 1)
const FILL_SPAN = FILL_BOTTOM - FILL_TOP_MAX; // 16 units of usable height
const FLOAT_CX = FILL_X + FILL_W / 2;
const FLOAT_R = 1.4;
const STROKE_WIDTH = 1.25; // physical px via non-scaling-stroke, floors > 1px

function fractionToY(fraction: number): number {
  return FILL_BOTTOM - fraction * FILL_SPAN;
}

function easeOutCubic(t: number): number {
  const u = 1 - t;
  return 1 - u * u * u;
}

function clamp01(t: number): number {
  return t < 0 ? 0 : t > 1 ? 1 : t;
}

export interface SteamTrapBatchFlushProps {
  /** glyph size in px, meant to sit inline beside a text label. legible 24-64. */
  size?: number;
  /** accessible label for the static role="img" description */
  label?: string;
  /**
   * renders as a focusable button that forces an early blowdown on press —
   * omit for the pure ambient/status read (default). The forced blowdown
   * reuses the exact same 340ms eased-out curve and never changes the trip
   * threshold; it just starts blowdown from whatever fraction the chamber
   * is currently at instead of waiting for the 88% trip.
   */
  interactive?: boolean;
  /** called once a forced or natural blowdown starts, only when interactive */
  onFlush?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SteamTrapBatchFlush({
  size = 24,
  label = "Syncing",
  interactive = false,
  onFlush,
  className = "",
}: SteamTrapBatchFlushProps) {
  const clipId = useId();
  const fillRef = useRef<SVGRectElement>(null);
  const floatRef = useRef<SVGCircleElement>(null);
  const rootRef = useRef<HTMLSpanElement | HTMLButtonElement>(null);
  const forceFlushRef = useRef<() => void>(() => {});

  useEffect(() => {
    const fillEl = fillRef.current;
    const floatEl = floatRef.current;
    const root = rootRef.current;
    if (!fillEl || !floatEl || !root) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const applyFrame = (fraction: number, overshoot: number) => {
      const y = fractionToY(fraction);
      fillEl.setAttribute("y", y.toFixed(2));
      fillEl.setAttribute("height", Math.max(0, FILL_BOTTOM - y).toFixed(2));
      floatEl.setAttribute("cy", (y + overshoot).toFixed(2));
    };

    if (reduced) {
      // TRIP_POINT freeze frame: fill at 88%, float at its highest point,
      // the instant before blowdown — the most information-dense frame,
      // showing the full chamber, the trip threshold and the float at once.
      applyFrame(TRIP_FRACTION, 0);
      return;
    }

    let disposed = false;
    let visible = true;
    let raf = 0;

    type Phase = "filling" | "blowdown";
    let phase: Phase = "filling";
    let fraction = LOW_FRACTION + Math.random() * (TRIP_FRACTION - LOW_FRACTION);
    let blowdownStart = 0;
    let blowdownFrom = TRIP_FRACTION;
    let settleStart = -Infinity;
    let settleFrom = 0;
    let last = 0;

    const startBlowdown = (now: number, from: number) => {
      phase = "blowdown";
      blowdownStart = now;
      blowdownFrom = from;
      onFlush?.();
    };

    forceFlushRef.current = () => {
      if (phase !== "filling") return;
      startBlowdown(performance.now(), fraction);
    };

    const tick = (now: number) => {
      raf = 0;
      if (!visible) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last) / 1000;
      last = now;

      let overshoot = 0;

      if (phase === "filling") {
        fraction = Math.min(TRIP_FRACTION, fraction + FILL_RATE * dt);
        if (fraction >= TRIP_FRACTION) startBlowdown(now, TRIP_FRACTION);
      } else {
        const t = clamp01((now - blowdownStart) / BLOWDOWN_MS);
        const eased = easeOutCubic(t);
        fraction = blowdownFrom + (LOW_FRACTION - blowdownFrom) * eased;
        overshoot = OVERSHOOT_UNITS * eased;
        if (t >= 1) {
          phase = "filling";
          settleStart = now;
          settleFrom = OVERSHOOT_UNITS;
        }
      }

      if (now - settleStart < OVERSHOOT_SETTLE_MS) {
        const st = clamp01((now - settleStart) / OVERSHOOT_SETTLE_MS);
        overshoot = settleFrom * (1 - easeOutCubic(st));
      }

      applyFrame(fraction, overshoot);
      raf = requestAnimationFrame(tick);
    };

    raf = requestAnimationFrame(tick);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !raf) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    });
    io.observe(root);

    return () => {
      disposed = true;
      void disposed;
      cancelAnimationFrame(raf);
      raf = 0;
      io.disconnect();
      forceFlushRef.current = () => {};
    };
  }, [onFlush]);

  const glyph = (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      aria-hidden="true"
      focusable="false"
    >
      <defs>
        <clipPath id={clipId}>
          <rect
            x={CHAMBER.x}
            y={CHAMBER.y}
            width={CHAMBER.w}
            height={CHAMBER.h}
            rx={CHAMBER.rx}
          />
        </clipPath>
      </defs>

      <g clipPath={`url(#${clipId})`}>
        <rect
          ref={fillRef}
          x={FILL_X}
          y={FILL_BOTTOM}
          width={FILL_W}
          height={0}
          style={{ fill: "var(--foreground)", opacity: 0.7 }}
        />
      </g>

      <rect
        x={CHAMBER.x}
        y={CHAMBER.y}
        width={CHAMBER.w}
        height={CHAMBER.h}
        rx={CHAMBER.rx}
        fill="none"
        stroke="var(--ns-muted)"
        strokeWidth={STROKE_WIDTH}
        vectorEffect="non-scaling-stroke"
      />

      <circle
        ref={floatRef}
        cx={FLOAT_CX}
        cy={fractionToY(TRIP_FRACTION)}
        r={FLOAT_R}
        style={{ fill: "var(--foreground)" }}
      />
    </svg>
  );

  if (interactive) {
    return (
      <button
        ref={rootRef as React.RefObject<HTMLButtonElement>}
        type="button"
        onClick={() => forceFlushRef.current()}
        aria-label={label}
        className={`inline-flex shrink-0 items-center justify-center rounded-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
        style={{ width: size, height: size }}
      >
        {glyph}
      </button>
    );
  }

  return (
    <span
      ref={rootRef as React.RefObject<HTMLSpanElement>}
      role="img"
      aria-label={label}
      className={`inline-flex shrink-0 items-center justify-center ${className}`}
      style={{ width: size, height: size }}
    >
      {glyph}
    </span>
  );
}

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// StemSift — a stem-and-leaf plot that stays a live instrument instead of a
// static printout: the `records` prop is a rolling window of raw
// { id, value, meta } values, and every arrival is rendered as one Geist
// Mono digit — the ones-digit of its rounded value — inserted into its
// tens-stem row in ascending order. Nothing is pre-aggregated: the glyphs
// ARE the data, every leaf is a real focusable record, not a pixel a
// histogram would have thrown away.
//
// MECHANISM: rows are real <table> rows (<th scope="row"> for the stem
// range, <td> holding a flex row of leaf digits) so the count and every
// value are exposed to assistive tech the way a table naturally reads them.
// A new leaf is measured against a decorative staging slot above the table
// (aria-hidden) and, on mount into its sorted position, is given an inverted
// transform equal to (staging rect - final rect) with transitions off, then
// one rAF later the transform is cleared with a spring transition — a
// two-keyframe fly from the staging point into its row. Every *existing*
// sibling leaf whose position changed because of that insertion (the
// "shoulder nudge") gets the same FLIP treatment computed from its own
// previous vs. current rect, so a row's leaves visibly part to make room
// rather than snapping to a new layout. Row length is never a separate bar —
// the flex row's own width IS the bar, doubling as both data and chart.
//
// A11y: native table semantics (caption states n/median/range), leaves are
// real <button>s with a roving tabindex (one Tab stop per component, Arrow
// keys move within a row and Up/Down step to the nearest populated row),
// each leaf's accessible name is its full raw value + optional meta so a
// screen reader gets the actual record, not just a digit. Hover or focus any
// leaf and it lifts 2px and the footer readout swaps from the resting
// n/median/range summary to that record. Arrivals are batched into a
// debounced role=status live region ("3 new values, median now 141ms")
// rather than announcing every tick. FLIP + fly-in are both skipped under
// prefers-reduced-motion — leaves place at their final position instantly,
// the table stays fully readable and navigable either way.
//
// Pure DOM + CSS, no canvas. All ink is token-relative (--foreground digits
// and staging box, --border rules and empty-row dashes, --ns-muted labels,
// --ns-accent only on the keyboard focus ring).
// ---------------------------------------------------------------------------

export interface StemSiftRecord {
  /** stable id — leaves are keyed by it so an entry FLIPs, not remounts */
  id: string | number;
  value: number;
  /** short source tag shown in the detail readout, e.g. "req-4821" */
  meta?: string;
}

export interface StemSiftProps {
  /** rolling window of raw samples, oldest first */
  records: StemSiftRecord[];
  /** unit suffix for readouts and stem labels, e.g. "ms" */
  unit?: string;
  /** heading above the plot */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const TRAVEL_MS = 440; // staging slot -> row, fly-in
const REFLOW_MS = 320; // shoulder-nudge of existing siblings
const SPRING_EASE = "cubic-bezier(0.34, 1.56, 0.64, 1)";
const STAGING_HOLD_MS = 360;
const ANNOUNCE_DEBOUNCE_MS = 900;

interface Leaf {
  sid: string;
  id: string | number;
  value: number; // rounded, used for stem/leaf math
  raw: number; // original value, shown in detail
  digit: number;
  meta?: string;
}

interface StemRow {
  stem: number;
  lo: number;
  hi: number;
  leaves: Leaf[];
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function formatValue(v: number): string {
  return Number.isInteger(v) ? String(v) : v.toFixed(1);
}

function buildRows(records: StemSiftRecord[]): StemRow[] {
  if (records.length === 0) return [];
  const items = records.map((r) => {
    const rounded = Math.round(r.value);
    return {
      sid: String(r.id),
      id: r.id,
      value: rounded,
      raw: r.value,
      digit: ((rounded % 10) + 10) % 10,
      meta: r.meta,
    };
  });
  const stems = items.map((it) => Math.floor(it.value / 10));
  const minStem = Math.min(...stems);
  const maxStem = Math.max(...stems);
  const rows: StemRow[] = [];
  for (let s = minStem; s <= maxStem; s++) {
    const leaves = items
      .filter((it) => Math.floor(it.value / 10) === s)
      .sort((a, b) => a.digit - b.digit); // Array#sort is stable: ties keep arrival order
    rows.push({ stem: s, lo: s * 10, hi: s * 10 + 9, leaves });
  }
  return rows;
}

function stepRow(rows: StemRow[], ri: number, dir: 1 | -1): number {
  let next = ri + dir;
  while (next >= 0 && next < rows.length && rows[next].leaves.length === 0) {
    next += dir;
  }
  if (next < 0 || next >= rows.length || rows[next].leaves.length === 0) return ri;
  return next;
}

function median(sortedVals: number[]): number {
  const n = sortedVals.length;
  if (n === 0) return 0;
  const mid = Math.floor(n / 2);
  return n % 2 ? sortedVals[mid] : (sortedVals[mid - 1] + sortedVals[mid]) / 2;
}

export function StemSift({ records, unit = "", label = "Distribution", className = "" }: StemSiftProps) {
  const rows = useMemo(() => buildRows(records), [records]);
  const reducedMotion = useReducedMotion();

  const wrapRefs = useRef(new Map<string, HTMLSpanElement>());
  const btnRefs = useRef(new Map<string, HTMLButtonElement>());
  const prevRectsRef = useRef(new Map<string, DOMRect>());
  const prevIdsRef = useRef(new Set<string>());
  const stagingRef = useRef<HTMLSpanElement>(null);
  const mountedRef = useRef(false);

  const [activeId, setActiveId] = useState<string | null>(null);
  const [detailId, setDetailId] = useState<string | null>(null);
  const [stagingDigit, setStagingDigit] = useState<number | null>(null);
  const stagingTimer = useRef<number | undefined>(undefined);

  const [announce, setAnnounce] = useState("");
  const pendingCountRef = useRef(0);
  const announceTimer = useRef<number | undefined>(undefined);

  const stats = useMemo(() => {
    const vals = records.map((r) => Math.round(r.value)).sort((a, b) => a - b);
    const n = vals.length;
    return {
      n,
      median: median(vals),
      min: n ? vals[0] : 0,
      max: n ? vals[n - 1] : 0,
    };
  }, [records]);
  const statsRef = useRef(stats);
  statsRef.current = stats;

  // resolve which leaf currently owns the single Tab stop, falling back to
  // the first populated row's first leaf if the previous choice aged out
  const validActiveId = useMemo(() => {
    if (activeId && rows.some((r) => r.leaves.some((l) => l.sid === activeId))) return activeId;
    const first = rows.find((r) => r.leaves.length > 0)?.leaves[0];
    return first ? first.sid : null;
  }, [activeId, rows]);

  // FLIP: measure every leaf's rect before this commit's arrivals/removals
  // are accounted for, diff against what we measured last time, and either
  // fly entering leaves in from the staging slot or nudge existing ones from
  // their old position to the new one. useLayoutEffect (not useEffect) so
  // the invert transform is applied before the browser paints the new,
  // already-inserted DOM position — otherwise the leaf would flash at its
  // final spot for one frame before jumping back to start the animation.
  useLayoutEffect(() => {
    const currentIds = new Set<string>();
    rows.forEach((r) => r.leaves.forEach((l) => currentIds.add(l.sid)));
    const prevIds = prevIdsRef.current;
    const enteringSids: string[] = [];
    currentIds.forEach((sid) => {
      if (!prevIds.has(sid)) enteringSids.push(sid);
    });

    const nextRects = new Map<string, DOMRect>();
    const plays: { el: HTMLSpanElement; dx: number; dy: number; enter: boolean }[] = [];
    const stageRect = stagingRef.current?.getBoundingClientRect();

    currentIds.forEach((sid) => {
      const el = wrapRefs.current.get(sid);
      if (!el) return;
      const rect = el.getBoundingClientRect();
      nextRects.set(sid, rect);
      if (reducedMotion) return;
      const entering = enteringSids.includes(sid);
      if (entering) {
        if (stageRect) {
          const dx = stageRect.left - rect.left;
          const dy = stageRect.top - rect.top;
          plays.push({ el, dx, dy, enter: true });
        }
      } else {
        const prevRect = prevRectsRef.current.get(sid);
        if (!prevRect) return;
        const dx = prevRect.left - rect.left;
        const dy = prevRect.top - rect.top;
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5) {
          plays.push({ el, dx, dy, enter: false });
        }
      }
    });

    if (plays.length) {
      plays.forEach(({ el, dx, dy }) => {
        el.style.transition = "none";
        el.style.opacity = "";
        el.style.transform = `translate(${dx}px, ${dy}px)`;
      });
      requestAnimationFrame(() => {
        plays.forEach(({ el, enter }) => {
          el.style.transition = `transform ${enter ? TRAVEL_MS : REFLOW_MS}ms ${SPRING_EASE}`;
          el.style.transform = "translate(0px, 0px)";
        });
      });
    }

    prevRectsRef.current = nextRects;
    prevIdsRef.current = currentIds;

    // staging slot flashes the most recent arrival's digit, then clears
    if (!reducedMotion && enteringSids.length && mountedRef.current) {
      const lastSid = enteringSids[enteringSids.length - 1];
      const leaf = rows.flatMap((r) => r.leaves).find((l) => l.sid === lastSid);
      if (leaf) {
        window.clearTimeout(stagingTimer.current);
        setStagingDigit(leaf.digit);
        stagingTimer.current = window.setTimeout(() => setStagingDigit(null), STAGING_HOLD_MS);
      }
    }

    // batched arrival announcement, debounced so a burst of ticks reads as
    // one sentence instead of one interruption per value
    if (mountedRef.current && enteringSids.length) {
      pendingCountRef.current += enteringSids.length;
      window.clearTimeout(announceTimer.current);
      announceTimer.current = window.setTimeout(() => {
        const count = pendingCountRef.current;
        pendingCountRef.current = 0;
        const { median: med, n } = statsRef.current;
        if (count > 0 && n > 0) {
          setAnnounce(`${count} new value${count === 1 ? "" : "s"}, median now ${formatValue(med)}${unit}.`);
        }
      }, ANNOUNCE_DEBOUNCE_MS);
    }

    mountedRef.current = true;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows, reducedMotion]);

  useEffect(
    () => () => {
      window.clearTimeout(stagingTimer.current);
      window.clearTimeout(announceTimer.current);
    },
    []
  );

  const onKeyDown = (e: React.KeyboardEvent<HTMLTableSectionElement>) => {
    if (!validActiveId) return;
    let ri = -1;
    let li = -1;
    for (let r = 0; r < rows.length; r++) {
      const idx = rows[r].leaves.findIndex((l) => l.sid === validActiveId);
      if (idx !== -1) {
        ri = r;
        li = idx;
        break;
      }
    }
    if (ri === -1) return;

    switch (e.key) {
      case "ArrowRight":
        li = Math.min(rows[ri].leaves.length - 1, li + 1);
        break;
      case "ArrowLeft":
        li = Math.max(0, li - 1);
        break;
      case "ArrowDown":
        ri = stepRow(rows, ri, 1);
        li = Math.min(li, rows[ri].leaves.length - 1);
        break;
      case "ArrowUp":
        ri = stepRow(rows, ri, -1);
        li = Math.min(li, rows[ri].leaves.length - 1);
        break;
      case "Home":
        li = 0;
        break;
      case "End":
        li = rows[ri].leaves.length - 1;
        break;
      default:
        return;
    }
    e.preventDefault();
    const target = rows[ri]?.leaves[li];
    if (!target) return;
    setActiveId(target.sid);
    setDetailId(target.sid);
    btnRefs.current.get(target.sid)?.focus();
  };

  const detail = detailId ? rows.flatMap((r) => r.leaves).find((l) => l.sid === detailId) : null;

  return (
    <div className={`w-full ${className}`}>
      <div className="mb-2 flex items-baseline justify-between gap-4">
        <span className="font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted">{label}</span>
        <span
          ref={stagingRef}
          aria-hidden="true"
          className="ns-sift-staging"
          data-active={stagingDigit !== null || undefined}
        >
          {stagingDigit ?? "·"}
        </span>
      </div>

      <div className="ns-sift-frame overflow-x-auto rounded-sm border border-border bg-background">
        <table className="ns-sift-table w-full border-collapse">
          <caption className="sr-only">
            {label} stem-and-leaf plot. {stats.n} value{stats.n === 1 ? "" : "s"}, median{" "}
            {formatValue(stats.median)}
            {unit}, range {formatValue(stats.min)}
            {unit} to {formatValue(stats.max)}
            {unit}. Each row is a stem of ten{unit ? ` ${unit}` : ""}; each leaf digit is one value's
            ones digit.
          </caption>
          <tbody onKeyDown={onKeyDown}>
            {rows.map((row) => (
              <tr key={row.stem} className="ns-sift-row">
                <th scope="row" className="ns-sift-stem">
                  {row.lo}–{row.hi}
                  {unit ? ` ${unit}` : ""}
                  <span className="sr-only">
                    {" "}
                    &middot; {row.leaves.length} value{row.leaves.length === 1 ? "" : "s"}
                  </span>
                </th>
                <td className="ns-sift-cell">
                  <div className="ns-sift-leaves">
                    {row.leaves.length === 0 && (
                      <span aria-hidden="true" className="ns-sift-empty">
                        &mdash;
                      </span>
                    )}
                    {row.leaves.map((leaf) => {
                      const tabbable = leaf.sid === validActiveId;
                      const ariaLabel = `${formatValue(leaf.raw)}${unit ? ` ${unit}` : ""}${
                        leaf.meta ? `, ${leaf.meta}` : ""
                      }`;
                      return (
                        <span
                          key={leaf.sid}
                          ref={(el) => {
                            if (el) wrapRefs.current.set(leaf.sid, el);
                            else wrapRefs.current.delete(leaf.sid);
                          }}
                          className="ns-sift-leaf-wrap"
                        >
                          <button
                            ref={(el) => {
                              if (el) btnRefs.current.set(leaf.sid, el);
                              else btnRefs.current.delete(leaf.sid);
                            }}
                            type="button"
                            className="ns-sift-leaf"
                            tabIndex={tabbable ? 0 : -1}
                            aria-label={ariaLabel}
                            data-detail={leaf.sid === detailId || undefined}
                            onClick={() => {
                              setActiveId(leaf.sid);
                              setDetailId(leaf.sid);
                            }}
                            onFocus={() => {
                              setActiveId(leaf.sid);
                              setDetailId(leaf.sid);
                            }}
                            onBlur={() => setDetailId((d) => (d === leaf.sid ? null : d))}
                            onMouseEnter={() => setDetailId(leaf.sid)}
                            onMouseLeave={() => setDetailId((d) => (d === leaf.sid ? null : d))}
                          >
                            {leaf.digit}
                          </button>
                        </span>
                      );
                    })}
                  </div>
                </td>
              </tr>
            ))}
            {rows.length === 0 && (
              <tr>
                <td colSpan={2} className="ns-sift-none">
                  no data yet
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="mt-1.5 flex items-baseline justify-between font-mono text-[10px] tabular-nums text-ns-muted">
        <span>n {stats.n}</span>
        <span className="text-foreground/80" aria-live="off">
          {detail
            ? `${formatValue(detail.raw)}${unit}${detail.meta ? ` · ${detail.meta}` : ""}`
            : `median ${formatValue(stats.median)}${unit} · range ${formatValue(stats.min)}–${formatValue(
                stats.max
              )}${unit}`}
        </span>
        <span>stem = tens</span>
      </div>

      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>

      <style>{`
        .ns-sift-staging {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          width: 1.7em;
          height: 1.5em;
          border: 1px dashed var(--border);
          border-radius: 6px;
          font-family: var(--font-mono);
          font-size: 11px;
          color: var(--ns-muted);
          transition: color 200ms ease, border-color 200ms ease;
        }
        .ns-sift-staging[data-active] {
          color: var(--foreground);
          border-style: solid;
          border-color: var(--foreground);
        }

        .ns-sift-table {
          font-family: var(--font-mono);
        }
        .ns-sift-row + .ns-sift-row .ns-sift-stem,
        .ns-sift-row + .ns-sift-row .ns-sift-cell {
          border-top: 1px solid var(--border);
        }
        .ns-sift-stem {
          text-align: right;
          vertical-align: baseline;
          white-space: nowrap;
          padding: 5px 10px 5px 8px;
          font-size: 11px;
          font-weight: 400;
          color: var(--ns-muted);
          border-right: 1px solid var(--border);
        }
        .ns-sift-cell {
          padding: 5px 8px;
          vertical-align: baseline;
          width: 100%;
        }
        .ns-sift-none {
          padding: 20px 8px;
          text-align: center;
          font-size: 12px;
          color: var(--ns-muted);
        }
        .ns-sift-leaves {
          display: flex;
          align-items: baseline;
          flex-wrap: wrap;
          gap: 1px;
          min-height: 1.5em;
        }
        .ns-sift-empty {
          font-size: 11px;
          color: var(--border);
          padding-left: 2px;
        }
        .ns-sift-leaf-wrap {
          display: inline-block;
        }
        .ns-sift-leaf {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          width: 1.6em;
          height: 1.5em;
          padding: 0;
          border: none;
          border-radius: 4px;
          background: transparent;
          color: var(--foreground);
          font-family: var(--font-mono);
          font-size: 13px;
          cursor: pointer;
          -webkit-tap-highlight-color: transparent;
          transition: transform 120ms ease-out, background-color 120ms ease-out;
        }
        .ns-sift-leaf:hover,
        .ns-sift-leaf[data-detail] {
          transform: translateY(-2px);
          background: color-mix(in oklab, var(--foreground) 6%, transparent);
        }
        .ns-sift-leaf:focus-visible {
          outline: 2px solid var(--ns-accent);
          outline-offset: 2px;
          transform: translateY(-2px);
        }

        @media (prefers-reduced-motion: reduce) {
          .ns-sift-staging {
            transition: none;
          }
          .ns-sift-leaf {
            transition: background-color 120ms ease-out;
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type KeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// StencilFill — a reusable pattern-masked input. The full template is
// visible at rest as a muted stencil (e.g. "XXXX-XXXX-XXXX", literal
// separators already in place); each typed character inks its own cell from
// --ns-muted to --foreground. One native <input> (transparent text/caret,
// positioned exactly over the decorative glyph grid — the same "real control
// drives, decorative layer displays" split as card-number-emboss) owns
// focus, value, label and autocomplete semantics, so the emitted value keeps
// its separators. A rejected character prints in its own cell at 40% muted,
// shakes on a spring, then falls away — the signature "show what was
// refused" beat — while aria-describedby states the format contract before
// the first keystroke, rather than auto-inserting separators as you type.
//
// This is the reusable MASK MECHANISM (license keys, IBANs, phone numbers,
// ticket IDs — any 'X'-templated string), not a format-specific treatment:
// card-number-emboss embosses one fixed payment layout, this stencils
// whatever mask you hand it.
// ---------------------------------------------------------------------------

export interface StencilFillProps {
  /** Template string: 'X' = editable cell, any other character = literal separator (auto-skipped, never typed). */
  mask: string;
  /** Accessible name for the underlying input. */
  label: string;
  /** Overrides the auto-derived aria-describedby copy. */
  formatDescription?: string;
  /** Per-character acceptance check. Defaults to A-Z / 0-9. */
  validate?: (char: string) => boolean;
  /** Normalizes an accepted character before it's inked. Defaults to uppercase. */
  transform?: (char: string) => string;
  /** Builds the polite live-region message for a refused character. */
  rejectMessage?: (char: string) => string;
  name?: string;
  autoComplete?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  className?: string;
}

interface MaskToken {
  kind: "slot" | "sep";
  char: string;
}

function parseMask(mask: string): MaskToken[] {
  return mask.split("").map((char) => (char === "X" ? { kind: "slot", char } : { kind: "sep", char }));
}

function deriveFormatDescription(mask: string): string {
  const groups = mask.match(/X+/g) ?? [];
  const seps = Array.from(new Set(mask.replace(/X/g, "").split("").filter(Boolean)));
  const firstGroupLen = groups[0]?.length ?? 0;
  if (groups.length > 1 && groups.every((g) => g.length === firstGroupLen) && seps.length === 1) {
    return `Format: ${groups.length} groups of ${firstGroupLen} characters, separated by ${seps[0]}`;
  }
  if (groups.length === 1 && seps.length === 0) {
    return `Format: ${firstGroupLen} characters`;
  }
  return `Format: ${mask}`;
}

function defaultValidate(char: string): boolean {
  return /^[A-Za-z0-9]$/.test(char);
}

function defaultTransform(char: string): string {
  return char.toUpperCase();
}

function defaultRejectMessage(char: string): string {
  return /^[a-zA-Z]$/.test(char) ? `Letter ${char.toUpperCase()} not allowed` : `Character "${char}" not allowed`;
}

function buildValue(tokens: MaskToken[], typed: string[]): string {
  let out = "";
  let i = 0;
  for (const t of tokens) {
    if (t.kind === "slot") {
      if (i >= typed.length) break;
      out += typed[i];
      i += 1;
    } else {
      if (i === 0) break;
      out += t.char;
    }
  }
  return out;
}

let rejectSeq = 0;

export function StencilFill({
  mask,
  label,
  formatDescription,
  validate = defaultValidate,
  transform = defaultTransform,
  rejectMessage = defaultRejectMessage,
  name,
  autoComplete = "off",
  defaultValue = "",
  onValueChange,
  className = "",
}: StencilFillProps) {
  const autoId = useId().replace(/:/g, "");
  const tokens = useMemo(() => parseMask(mask), [mask]);
  const totalSlots = useMemo(() => tokens.filter((t) => t.kind === "slot").length, [tokens]);
  const separatorChars = useMemo(
    () => new Set(tokens.filter((t) => t.kind === "sep").map((t) => t.char)),
    [tokens],
  );
  const description = formatDescription ?? deriveFormatDescription(mask);

  const [typed, setTyped] = useState<string[]>(() => {
    const chars: string[] = [];
    for (const ch of defaultValue) {
      if (chars.length >= totalSlots) break;
      if (/[A-Za-z0-9]/.test(ch)) chars.push(ch.toUpperCase());
    }
    return chars;
  });
  const [focused, setFocused] = useState(false);
  // Mirrors `focused` for the caret's visibility so the caret still shows up
  // under autoplay: the demo subtree is `inert` there, and `inert` elements
  // are not focusable, so the driver's synthetic keydowns never produce a
  // real `focus` event even though they do drive typing. Set on any handled
  // key/paste, cleared on blur — under real interaction it always coincides
  // with `focused`, so behavior for a real user is unchanged.
  const [armed, setArmed] = useState(false);
  const [rejected, setRejected] = useState<{ slot: number; char: string; id: number } | null>(null);
  const [announce, setAnnounce] = useState("");

  const typedRef = useRef(typed);
  typedRef.current = typed;
  const reducedRef = useRef(false);
  const rejectFallbackRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const cascadeTimersRef = useRef<ReturnType<typeof setTimeout>[]>([]);
  const announceTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(
    () => () => {
      clearTimeout(rejectFallbackRef.current);
      clearTimeout(announceTimerRef.current);
      cascadeTimersRef.current.forEach(clearTimeout);
    },
    [],
  );

  const commitTyped = useCallback(
    (next: string[]) => {
      setTyped(next);
      onValueChange?.(buildValue(tokens, next));
    },
    [tokens, onValueChange],
  );

  const say = useCallback((msg: string) => {
    clearTimeout(announceTimerRef.current);
    setAnnounce("");
    announceTimerRef.current = setTimeout(() => setAnnounce(msg), 30);
  }, []);

  const triggerReject = useCallback(
    (slot: number, char: string) => {
      clearTimeout(rejectFallbackRef.current);
      rejectSeq += 1;
      const id = rejectSeq;
      setRejected({ slot, char, id });
      say(rejectMessage(char));
      rejectFallbackRef.current = setTimeout(() => {
        setRejected((r) => (r?.id === id ? null : r));
      }, 900);
    },
    [rejectMessage, say],
  );

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLInputElement>) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;

      if (e.key === "Backspace" || e.key === "Delete") {
        e.preventDefault();
        setArmed(true);
        clearTimeout(rejectFallbackRef.current);
        setRejected(null);
        if (typedRef.current.length) commitTyped(typedRef.current.slice(0, -1));
        return;
      }

      if (e.key.length !== 1) return; // let Tab, Enter, arrows, Escape through natively
      e.preventDefault();
      setArmed(true);

      if (separatorChars.has(e.key)) return; // literal separator: auto-skipped, not a rejection
      if (typedRef.current.length >= totalSlots) return; // full: no-op, not a rejection

      if (validate(e.key)) {
        clearTimeout(rejectFallbackRef.current);
        setRejected(null);
        commitTyped([...typedRef.current, transform(e.key)]);
      } else {
        triggerReject(typedRef.current.length, e.key);
      }
    },
    [commitTyped, separatorChars, totalSlots, transform, triggerReject, validate],
  );

  const handlePaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      e.preventDefault();
      setArmed(true);
      const text = e.clipboardData.getData("text");
      const accepted: string[] = [];
      for (const ch of text) {
        if (typedRef.current.length + accepted.length >= totalSlots) break;
        if (separatorChars.has(ch)) continue;
        if (validate(ch)) accepted.push(transform(ch));
      }
      if (!accepted.length) return;

      cascadeTimersRef.current.forEach(clearTimeout);
      cascadeTimersRef.current = [];
      const step = reducedRef.current ? 0 : 45;
      accepted.forEach((ch, i) => {
        const timer = setTimeout(() => {
          if (typedRef.current.length >= totalSlots) return;
          commitTyped([...typedRef.current, ch]);
        }, step * i);
        cascadeTimersRef.current.push(timer);
      });
    },
    [commitTyped, separatorChars, totalSlots, transform, validate],
  );

  // Safety net for paths that never fire our own keydown handler — IME
  // composition landing its result, browser autofill, drag-and-drop text,
  // or a mobile virtual keyboard that reports `key: "Unidentified"` — all of
  // which still produce a real `input`/`change` event. Every ordinary
  // keystroke is already `preventDefault()`-ed above, so the DOM input's
  // displayed value never actually changes on that path and this handler is
  // a no-op for it; it only ever runs for value writes we didn't intercept.
  const handleChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      const next: string[] = [];
      for (const ch of e.target.value) {
        if (next.length >= totalSlots) break;
        if (separatorChars.has(ch)) continue;
        if (validate(ch)) next.push(transform(ch));
      }
      const prev = typedRef.current;
      if (next.length === prev.length && next.every((c, i) => c === prev[i])) return;
      commitTyped(next);
    },
    [commitTyped, separatorChars, totalSlots, transform, validate],
  );

  const value = useMemo(() => buildValue(tokens, typed), [tokens, typed]);
  const describedById = `sf-desc-${autoId}`;
  const inputId = `sf-input-${autoId}`;

  let slotIndex = -1;

  return (
    <div className={`relative inline-block ${className}`}>
      <style>{CSS}</style>
      <span id={describedById} className="sr-only">
        {description}
      </span>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </span>
      <label htmlFor={inputId} className="sr-only">
        {label}
      </label>

      <div
        className="relative inline-flex h-[2.7em] items-center rounded-[0.67em] border border-border bg-background px-[0.67em]"
        style={{ fontSize: "var(--sf-size, 1.125rem)" }}
      >
        <input
          id={inputId}
          name={name}
          type="text"
          inputMode="text"
          autoComplete={autoComplete}
          autoCapitalize="characters"
          spellCheck={false}
          aria-describedby={describedById}
          value={value}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          onPaste={handlePaste}
          onFocus={() => setFocused(true)}
          onBlur={() => {
            setFocused(false);
            setArmed(false);
          }}
          className="ns-sf-input absolute inset-0 z-10 h-full w-full rounded-[12px]"
        />
        <div
          aria-hidden="true"
          data-sf-glyphs
          className="pointer-events-none flex items-center font-mono"
        >
          {tokens.map((t, i) => {
            if (t.kind === "sep") {
              return (
                <span key={i} className="ns-sf-cell ns-sf-sep">
                  {t.char}
                </span>
              );
            }
            slotIndex += 1;
            const mySlot = slotIndex;
            const filled = mySlot < typed.length;
            const isNextOpen = mySlot === typed.length;
            const isRejected = rejected?.slot === mySlot;
            return (
              <span key={i} className="ns-sf-cell relative inline-flex items-center justify-center">
                {(focused || armed) && isNextOpen && !isRejected && (
                  <span aria-hidden="true" className="ns-sf-caret" />
                )}
                <span className={`ns-sf-glyph ${filled ? "ns-sf-ink" : "ns-sf-stencil"}`}>
                  {filled ? typed[mySlot] : "X"}
                </span>
                {isRejected && rejected && (
                  <span
                    key={rejected.id}
                    aria-hidden="true"
                    className="ns-sf-reject"
                    onAnimationEnd={() => setRejected((r) => (r?.id === rejected.id ? null : r))}
                  >
                    {rejected.char}
                  </span>
                )}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}

