export default TuftingGunLoopPile;

"use client";

import { useEffect, useId, useRef } from "react";

// ---------------------------------------------------------------------------
// TurbiditeGradedBed — a submarine-fan stratigraphic column: an ambient
// "history is accumulating" strip where each discrete flow-pulse event
// deposits ONE new graded bed at the top, coarse grains settling first at
// its sharp base and progressively finer grains capping it as the current
// loses competence (a real Bouma-sequence fining-upward signature). The
// stack keeps growing pulse by pulse, oldest beds compressing slightly under
// the newer overburden and eventually scrolling off the bottom.
//
// Every layer's internal grain-size gradient is a fixed set of dot
// descriptors (position/radius-factor/alpha-factor, colour-free) computed
// ONCE at deposit time and cached; painting that dot set into pixels happens
// once per theme read, never per frame — the per-frame cost is just a
// handful of drawImage calls compositing already-rendered layer bitmaps
// into the visible strip. The one animated thing each pulse is the reveal:
// the coarse base appears first, then a fining sweep uncovers the rest of
// the layer moving upward — the followable event, ~530ms once every ~3.2s
// on average, slow enough to watch form.
//
// Basal scour: the instant a new pulse starts, the layer it is about to
// bury gets an irregular scalloped notch eaten into its cap over 80ms (an
// overpaint in --background tracing a jittered curve, never a straight
// line) with a thin --border stroke tracing the resulting erosive contact —
// the real signature that separates one event's bed from the next, distinct
// from a flat stacking seam.
// ---------------------------------------------------------------------------

export interface TurbiditeGradedBedProps {
  /** average seconds between flow-pulse events (irregular, 1.8-5.5s bounds). @default 3.2 */
  pulseIntervalSeconds?: number;
  /** freezes on the reduced-motion still without unmounting */
  paused?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

interface Dot {
  x: number; // local px, 0..layerWidth
  y: number; // local px, 0 = layer's fine cap, baseHeight = layer's coarse base
  rf: number; // radius factor 0..1 (already includes per-dot jitter)
  af: number; // alpha factor 0..1 (already includes per-dot jitter)
}

interface Layer {
  baseHeight: number; // deposited height, px, never mutated
  height: number; // current rendered height after compaction
  compression: number; // 0..COMPRESSION_CAP
  yTop: number; // current top offset in strip-space, recomputed every pulse
  dots: Dot[];
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  texW: number; // css px width the canvas was baked at
  depositStart: number; // ms, performance.now() at deposit start; -1 once settled
  scourPoints: number[] | null; // depth px per sample, set once this layer is buried
  scourStart: number; // ms; -1 until scour begins
  scourSettled: boolean;
}

const MIN_INTERVAL_MS = 1800;
const MAX_INTERVAL_MS = 5500;
const MEAN_INTERVAL_MS = 3200;

const SCOUR_MS = 80;
const DEPOSIT_BASE_MS = 120; // coarse base appears
const DEPOSIT_FINE_MS = 330; // fining sweep upward through the rest
const DEPOSIT_TOTAL_MS = DEPOSIT_BASE_MS + DEPOSIT_FINE_MS;

const LAYER_MIN_PX = 14;
const LAYER_MAX_PX = 34;

const COMPRESSION_PER_EVENT = 0.003; // 0.3% per subsequent event
const COMPRESSION_CAP = 0.4;
const BOTTOM_ZONE_FRAC = 0.8; // bottom 20% of the visible strip compacts

const DOT_RADIUS_MIN = 0.5;
const DOT_RADIUS_MAX = 2.1;
const DOT_DENSITY_MIN = 3; // dots per ~40px row-width at the fine cap
const DOT_DENSITY_MAX = 11; // dots per ~40px row-width at the coarse base
const DOT_ALPHA_MIN = 0.2; // perceptual floor kept clear of zero for light theme
const DOT_ALPHA_MAX = 0.9;
const ROW_STEP = 1.6;

const CULL_MARGIN_PX = 48;
const REDUCED_MOTION_LAYERS = 6; // enough to fill+overflow a typical card

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

// exponential-ish irregular spacing, clamped to bounds proportional to the
// requested mean (default mean 3.2s -> the documented 1.8-5.5s bounds)
function nextInterval(rand: () => number, meanMs: number): number {
  const raw = -meanMs * Math.log(1 - rand() * 0.98);
  const min = meanMs * (MIN_INTERVAL_MS / MEAN_INTERVAL_MS);
  const max = meanMs * (MAX_INTERVAL_MS / MEAN_INTERVAL_MS);
  return clamp(raw, min, max);
}

// skewed strength scalar: most pulses modest, occasional ones large
function pulseHeight(rand: () => number, scale: number): number {
  const strength = Math.pow(rand(), 3); // concentrated near 0, tail toward 1
  return (LAYER_MIN_PX + (LAYER_MAX_PX - LAYER_MIN_PX) * strength) * scale;
}

function buildDots(baseHeight: number, texW: number, rand: () => number): Dot[] {
  const dots: Dot[] = [];
  for (let y = 0; y < baseHeight; y += ROW_STEP) {
    const t = baseHeight > 0 ? y / baseHeight : 0; // 0 cap(fine) -> 1 base(coarse)
    const density = DOT_DENSITY_MIN + (DOT_DENSITY_MAX - DOT_DENSITY_MIN) * t;
    const count = Math.max(1, Math.round((density * texW) / 40));
    for (let i = 0; i < count; i++) {
      dots.push({
        x: rand() * texW,
        y: y + (rand() - 0.5) * ROW_STEP,
        rf: t * (0.65 + rand() * 0.45),
        af: t * (0.7 + rand() * 0.3),
      });
    }
  }
  return dots;
}

function paintLayerCanvas(layer: Layer, colors: { fg: string; bg: string }, dpr: number) {
  const c = layer.canvas;
  const w = layer.texW;
  const h = layer.baseHeight;
  const pw = Math.max(1, Math.round(w * dpr));
  const ph = Math.max(1, Math.round(h * dpr));
  if (c.width !== pw || c.height !== ph) {
    c.width = pw;
    c.height = ph;
  }
  const ctx = layer.ctx;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = colors.bg;
  ctx.fillRect(0, 0, w, h);
  for (const d of layer.dots) {
    const r = DOT_RADIUS_MIN + (DOT_RADIUS_MAX - DOT_RADIUS_MIN) * d.rf;
    const a = DOT_ALPHA_MIN + (DOT_ALPHA_MAX - DOT_ALPHA_MIN) * d.af;
    ctx.globalAlpha = a;
    ctx.fillStyle = colors.fg;
    ctx.beginPath();
    ctx.arc(d.x, d.y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function buildScourPoints(rand: () => number, samples: number): number[] {
  const maxDepth = 2 + rand() * 2; // 2-4px
  const phase = rand() * Math.PI * 2;
  const pts: number[] = [];
  for (let i = 0; i < samples; i++) {
    const u = i / (samples - 1);
    const wobble = 0.5 + 0.5 * Math.sin(u * Math.PI * 3.1 + phase);
    const jitter = (rand() - 0.5) * 0.6;
    pts.push(clamp(maxDepth * (wobble + jitter), 0.4, maxDepth));
  }
  return pts;
}

export function TurbiditeGradedBed({
  pulseIntervalSeconds = 3.2,
  paused = false,
  className = "",
  style,
}: TurbiditeGradedBedProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const uid = useId();
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    const ctx = canvas.getContext("2d", { alpha: true });
    if (!ctx) return;

    let disposed = false;
    let raf = 0;
    let running = false;
    let staticMode = false;
    let onScreen = true;

    let w = 0;
    let h = 0;
    let dpr = 1;
    let scale = 1; // derived from the strip's own (smaller) dimension: width

    let layers: Layer[] = [];
    let pulseTimer = 0;
    const rand = mulberry32(0x7b1d3e);
    const meanMs = Math.max(200, pulseIntervalSeconds * 1000);

    let colors = { fg: "#171717", bg: "#ffffff", border: "#e5e5e5" };
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      colors = {
        fg: cs.getPropertyValue("--foreground").trim() || "#171717",
        bg: cs.getPropertyValue("--background").trim() || "#ffffff",
        border: cs.getPropertyValue("--border").trim() || "#e5e5e5",
      };
    };
    readColors();

    const makeLayer = (heightPx: number): Layer => {
      const c = document.createElement("canvas");
      const lctx = c.getContext("2d")!;
      const layer: Layer = {
        baseHeight: heightPx,
        height: heightPx,
        compression: 0,
        yTop: 0,
        dots: buildDots(heightPx, w, rand),
        canvas: c,
        ctx: lctx,
        texW: w,
        depositStart: -1,
        scourPoints: null,
        scourStart: -1,
        scourSettled: true,
      };
      paintLayerCanvas(layer, colors, dpr);
      return layer;
    };

    // -- one deposit: shift the whole stack down by the new layer's height,
    // start eroding the (now-buried) previous top layer's cap, then start
    // the new layer's own base-then-fining reveal. ------------------------
    const depositPulse = (nowMs: number) => {
      const heightPx = pulseHeight(rand, scale);
      const newLayer = makeLayer(heightPx);
      newLayer.depositStart = nowMs;

      const prevTop = layers[0];
      for (const l of layers) l.yTop += heightPx;
      layers.unshift(newLayer);

      if (prevTop) {
        prevTop.scourPoints = buildScourPoints(rand, 10);
        prevTop.scourStart = nowMs;
        prevTop.scourSettled = false;
      }

      // compaction: any layer whose current span sits in the bottom 20% of
      // the visible strip squeezes a little further under the new overburden
      for (const l of layers) {
        if (l === newLayer) continue;
        if (l.yTop + l.height > BOTTOM_ZONE_FRAC * h) {
          l.compression = Math.min(COMPRESSION_CAP, l.compression + COMPRESSION_PER_EVENT);
          l.height = l.baseHeight * (1 - l.compression);
        }
      }
      recomputeStack();

      // cull anything fully scrolled past the bottom edge
      while (layers.length && (layers[layers.length - 1]?.yTop ?? 0) > h + CULL_MARGIN_PX) {
        layers.pop();
      }
    };

    const recomputeStack = () => {
      let y = 0;
      for (const l of layers) {
        l.yTop = y;
        y += l.height;
      }
    };

    const scheduleNextPulse = () => {
      window.clearTimeout(pulseTimer);
      pulseTimer = window.setTimeout(() => {
        if (disposed || staticMode) return;
        depositPulse(performance.now());
        scheduleNextPulse();
      }, nextInterval(rand, meanMs));
    };

    // -- composite the whole visible strip from cached layer bitmaps; the
    // only per-frame work is a reveal clip (depositing layer) and a scour
    // overpaint (freshly buried layer), both driven off elapsed time, never
    // by recomputing the dot fields themselves. ---------------------------
    const drawScene = (nowMs: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      for (let i = layers.length - 1; i >= 0; i--) {
        const l = layers[i];
        if (!l) continue;
        if (l.yTop > h || l.yTop + l.height < 0) continue;

        let revealTopLocal = 0; // texture-local y above which nothing is drawn yet
        if (l.depositStart >= 0) {
          const elapsed = nowMs - l.depositStart;
          if (elapsed < DEPOSIT_BASE_MS) {
            // coarse base appears first: reveal only the bottom slice
            const baseSliceFrac = 0.28;
            revealTopLocal = l.baseHeight * (1 - baseSliceFrac);
          } else if (elapsed < DEPOSIT_TOTAL_MS) {
            const fineT = (elapsed - DEPOSIT_BASE_MS) / DEPOSIT_FINE_MS;
            const startFrac = 0.72; // matches (1 - baseSliceFrac) above
            revealTopLocal = l.baseHeight * startFrac * (1 - fineT);
          } else {
            l.depositStart = -1;
            revealTopLocal = 0;
          }
        }

        const srcH = Math.max(0, l.baseHeight - revealTopLocal);
        if (srcH <= 0) continue;
        const destFracH = srcH / l.baseHeight;
        const destY = l.yTop + l.height * (revealTopLocal / l.baseHeight);
        const destH = l.height * destFracH;

        ctx.drawImage(
          l.canvas,
          0,
          revealTopLocal * dpr,
          l.texW * dpr,
          srcH * dpr,
          0,
          destY,
          w,
          destH
        );

        // erosive basal scour on the layer that just got buried
        if (l.scourPoints && !l.scourSettled) {
          const elapsed = nowMs - l.scourStart;
          const progress = clamp(elapsed / SCOUR_MS, 0, 1);
          if (progress >= 1) l.scourSettled = true;
          drawScourNotch(l, progress);
        } else if (l.scourPoints) {
          drawScourNotch(l, 1);
        }
      }
    };

    const drawScourNotch = (l: Layer, progress: number) => {
      const pts = l.scourPoints;
      if (!pts) return;
      const n = pts.length;
      ctx.beginPath();
      ctx.moveTo(0, l.yTop);
      for (let k = 0; k < n; k++) {
        const x = (k / (n - 1)) * w;
        const y = l.yTop + pts[k]! * progress;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(w, l.yTop);
      ctx.closePath();
      ctx.fillStyle = colors.bg;
      ctx.fill();

      ctx.beginPath();
      for (let k = 0; k < n; k++) {
        const x = (k / (n - 1)) * w;
        const y = l.yTop + pts[k]! * progress;
        if (k === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = colors.border;
      ctx.lineWidth = 1;
      ctx.stroke();
    };

    // -- deterministic reduced-motion / paused still: several complete
    // graded beds stacked, the freshest one fully formed and settled, its
    // own basal scour fully baked, no active deposit/scour in flight. -----
    const drawStaticFrame = () => {
      layers = [];
      let y = 0;
      let prevTop: Layer | null = null;
      for (let i = 0; i < REDUCED_MOTION_LAYERS; i++) {
        const heightPx = pulseHeight(rand, scale);
        const l = makeLayer(heightPx);
        l.depositStart = -1;
        if (prevTop) {
          prevTop.scourPoints = buildScourPoints(rand, 10);
          prevTop.scourSettled = true;
        }
        layers.unshift(l);
        for (const other of layers) if (other !== l) other.yTop += heightPx;
        prevTop = l;
        y += heightPx;
      }
      recomputeStack();
      drawScene(performance.now());
    };

    const resetAll = () => {
      window.clearTimeout(pulseTimer);
      layers = [];
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
    };

    const loop = (nowMs: number) => {
      if (!running) return;
      drawScene(nowMs);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || disposed || staticMode) return;
      running = true;
      raf = requestAnimationFrame(loop);
      scheduleNextPulse();
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      raf = 0;
      running = false;
      window.clearTimeout(pulseTimer);
    };

    const applySize = () => {
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      const changed = Math.abs(rect.width - w) > 0.5 || Math.abs(rect.height - h) > 0.5;
      w = rect.width;
      h = rect.height;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      scale = clamp(w / 220, 0.6, 1.6);
      const pw = Math.max(2, Math.round(w * dpr));
      const ph = Math.max(2, Math.round(h * dpr));
      if (canvas.width !== pw || canvas.height !== ph) {
        canvas.width = pw;
        canvas.height = ph;
      }
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      if (changed) {
        // baked layer bitmaps are sized to the old strip width — a resize
        // invalidates them, so restart cleanly rather than rescale in place
        if (staticMode) drawStaticFrame();
        else {
          resetAll();
          if (!pausedRef.current) wake();
        }
      }
    };

    const ro = new ResizeObserver(applySize);
    ro.observe(wrap);
    applySize();

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const applyMode = () => {
      if (reduced || pausedRef.current) {
        staticMode = true;
        sleep();
        drawStaticFrame();
      } else {
        if (staticMode) resetAll();
        staticMode = false;
        if (onScreen && !document.hidden) wake();
      }
    };
    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);

    const io = new IntersectionObserver(
      (entries) => {
        onScreen = entries.some((en) => en.isIntersecting);
        if (!onScreen) sleep();
        else if (!staticMode && !document.hidden) wake();
      },
      { threshold: 0 }
    );
    io.observe(wrap);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!staticMode && onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);
    applyMode();

    let lastPolledPaused = pausedRef.current;
    let poll = 0;
    const pollPaused = () => {
      if (pausedRef.current !== lastPolledPaused) {
        lastPolledPaused = pausedRef.current;
        applyMode();
      }
      poll = window.setTimeout(pollPaused, 140);
    };
    pollPaused();

    const themeObserver = new MutationObserver(() => {
      readColors();
      for (const l of layers) paintLayerCanvas(l, colors, dpr);
      if (staticMode) drawScene(performance.now());
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      window.clearTimeout(poll);
      sleep();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pulseIntervalSeconds]);

  return (
    <div
      ref={wrapRef}
      data-turbidite-graded-bed={uid}
      role="img"
      aria-label="Accumulating stratigraphic record, one graded sediment layer per flow event"
      className={`relative h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 block h-full w-full" />
    </div>
  );
}

TurbiditeGradedBed.displayName = "TurbiditeGradedBed";

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// TurntableSwitcher — a multi-tenant org switcher modeled as a locomotive
// roundhouse turntable. The popover holds an SVG turntable: a pivoting bridge
// (your session) and a fan of fixed stalls (the tenants), each a real button
// carrying the org's initial and name. One governing scalar, bridge angle
// theta, moves on an intentionally underdamped spring (zeta 0.75) so a hop
// overshoots by a couple degrees and settles in ~500ms — critical damping
// would read as a digital snap and erase the sense that switching exclusive
// authority has mass. Rail continuity between the bridge tip and a stall's
// fixed spur is a computed dash junction: solid only within +/-1.5deg of
// exact alignment, otherwise gapped or absent, so the geometry itself shows
// the "aligned with nothing" middle of every swing. Org-scoped nav mirrors
// that: it drops to 40% opacity with a hairline gap under each label the
// instant a switch starts, and — this is the falsifiable part — it does NOT
// re-enable when the bridge reaches the stall angle. It re-enables only once
// theta is exactly on target AND confirmSwitch(id) has resolved. Until then
// the bridge is deliberately parked short of the stall (outside the join
// tolerance) rather than showing a spinner: "almost switched" gets a face.
// Selecting a different org before confirmation arrives cancels the stale
// wait via a sequence counter, never an optimistic re-enable. Rail-mate fires
// a 1px translate impulse on the popover — a physical clunk, not a fade.
// Direct-DOM rAF hot path for theta only (a ref'd rotated <g> plus per-stall
// junction <line> refs); discrete state (open, connected, active option)
// stays plain React. Reduced motion teleports theta but keeps the same two-
// phase hold-then-final structure and the nav opacity transition (150ms,
// opacity only) — the disconnected middle is correctness, not garnish.
// ---------------------------------------------------------------------------

export interface TurntableOrg {
  id: string;
  name: string;
  /** single glyph shown on the stall/trigger avatar; defaults to the first letter of name */
  initial?: string;
}

const DEFAULT_ORGS: TurntableOrg[] = [
  { id: "acme", name: "Acme" },
  { id: "globex", name: "Globex" },
  { id: "initech", name: "Initech" },
  { id: "umbrella", name: "Umbrella" },
  { id: "soylent", name: "Soylent" },
];

const DEFAULT_NAV_ITEMS = ["Dashboard", "Members", "Billing", "Settings"];

// -- geometry: fixed SVG user-space, scale-independent (no ResizeObserver needed) --
const VB_W = 300;
const VB_H = 176;
const HUB_X = 150;
const HUB_Y = 158;
const R_INNER = 26; // bridge rail visual start, near the hub
const R_MATE = 100; // mating radius: bridge tip meets each stall's fixed spur here
const R_OUTER = 124; // stall button anchor radius
const R_RIM = R_OUTER + 10; // decorative pit rim
const STEP_DEG = 24; // angular spacing between adjacent stalls
const NEAR_DEG = 11; // a junction only renders when the bridge is within this of a stall
const JOIN_TOLERANCE_DEG = 1.5; // dash junction reads solid/continuous only within this
const HOLD_SHORT_DEG = 2.4; // parked short of mating while awaiting confirmation — outside JOIN_TOLERANCE_DEG on purpose

// -- physics: underdamped spring, tuned for a 3-stall hop to settle in ~500ms
// with a couple degrees of overshoot (amplitude-independent for a linear spring —
// a 1-stall hop settles in the same time with proportionally less overshoot) --
const SPRING_K = 114; // s^-2
const SPRING_ZETA = 0.75;
const SPRING_C = 2 * SPRING_ZETA * Math.sqrt(SPRING_K);
const SETTLE_POS_EPS = 0.04; // deg
const SETTLE_VEL_EPS = 1.2; // deg/s
const SETTLE_DEADLINE_MS = 900; // backstop; never trusts the epsilon alone

// deliberately slower than the hold-phase spring settle (~700-900ms for a
// single hop): a server round trip that resolves before the bridge even
// finishes traveling would mean the hold-short/unjoined state never has time
// to actually render, silently deleting the falsifiable middle the whole
// component exists to make honest.
const CONFIRM_MIN_MS = 950;
const CONFIRM_MAX_MS = 1350;

async function defaultConfirmSwitch(): Promise<void> {
  const latency = CONFIRM_MIN_MS + Math.random() * (CONFIRM_MAX_MS - CONFIRM_MIN_MS);
  await new Promise<void>((resolve) => setTimeout(resolve, latency));
}

function angleOf(index: number, count: number): number {
  return (index - (count - 1) / 2) * STEP_DEG;
}

function ptAt(deg: number, r: number): { x: number; y: number } {
  const a = (deg * Math.PI) / 180;
  return { x: HUB_X + r * Math.sin(a), y: HUB_Y - r * Math.cos(a) };
}

function pct(v: number, total: number): string {
  return `${((v / total) * 100).toFixed(3)}%`;
}

function arcPath(r: number): string {
  const p0 = ptAt(-54, r);
  const p1 = ptAt(54, r);
  return `M ${p0.x.toFixed(2)} ${p0.y.toFixed(2)} A ${r} ${r} 0 0 1 ${p1.x.toFixed(2)} ${p1.y.toFixed(2)}`;
}

export function TurntableSwitcher({
  orgs = DEFAULT_ORGS,
  defaultValue,
  onValueChange,
  confirmSwitch,
  navItems = DEFAULT_NAV_ITEMS,
  label = "Organization",
  defaultOpen = false,
  className = "",
}: {
  /** the tenants, arranged in fixed order along the turntable's fan */
  orgs?: TurntableOrg[];
  /** uncontrolled initial connected org id */
  defaultValue?: string;
  /** fires once the bridge is exactly on target AND the switch is confirmed */
  onValueChange?: (id: string) => void;
  /** simulates (or performs) the server round trip; reject to hold short indefinitely */
  confirmSwitch?: (id: string) => Promise<void>;
  /** labels for the bundled org-scoped nav strip; pass [] to omit it */
  navItems?: string[];
  /** accessible label for the switcher trigger and listbox */
  label?: string;
  /** starts the popover open — showcase/demo use only */
  defaultOpen?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const uid = useId();
  const optId = (i: number) => `${uid}-stall-${i}`;

  const positioned = useMemo(
    () => orgs.map((o, i) => ({ ...o, angle: angleOf(i, orgs.length) })),
    [orgs]
  );

  const [open, setOpen] = useState(defaultOpen);
  const [activeIndex, setActiveIndex] = useState(0);
  const initialId = defaultValue ?? positioned[0]?.id ?? "";
  const [committedId, setCommittedId] = useState(initialId);
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [connected, setConnected] = useState(true);
  const [statusText, setStatusText] = useState("");

  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const listboxRef = useRef<HTMLDivElement>(null);
  const bridgeGroupRef = useRef<SVGGElement>(null);
  const junctionRefs = useRef<(SVGLineElement | null)[]>([]);

  const listRef = useRef(positioned);
  listRef.current = positioned;
  const confirmRef = useRef(confirmSwitch ?? defaultConfirmSwitch);
  confirmRef.current = confirmSwitch ?? defaultConfirmSwitch;
  const onValueChangeRef = useRef(onValueChange);
  onValueChangeRef.current = onValueChange;

  const engineRef = useRef<{
    selectOrg: (id: string) => void;
    onOpen: () => void;
  } | null>(null);

  // -- physics + rail engine: one mount effect, direct-DOM hot path for theta --
  useEffect(() => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const dests = () => listRef.current;
    const angleOfId = (id: string) => dests().find((d) => d.id === id)?.angle ?? 0;
    const nameOfId = (id: string) => dests().find((d) => d.id === id)?.name ?? id;

    let theta = angleOfId(initialId);
    let vel = 0; // deg/s
    let mode: "idle" | "springing" = "idle";
    let springTarget = 0;
    let phase: "hold" | "final" | null = null;
    let springDeadline = 0;
    let raf = 0;
    let last = 0;
    let seq = 0;
    let pendingLocal: string | null = null;
    let committedLocal = initialId;

    const render = () => {
      const g = bridgeGroupRef.current;
      if (g) g.setAttribute("transform", `rotate(${theta.toFixed(2)} ${HUB_X} ${HUB_Y})`);
      const tip = ptAt(theta, R_MATE);
      const arr = dests();
      for (let i = 0; i < arr.length; i++) {
        const line = junctionRefs.current[i];
        if (!line) continue;
        const diff = theta - arr[i]!.angle;
        const absDiff = Math.abs(diff);
        if (absDiff > NEAR_DEG) {
          line.style.opacity = "0";
          continue;
        }
        const stallPt = ptAt(arr[i]!.angle, R_MATE);
        line.setAttribute("x1", tip.x.toFixed(2));
        line.setAttribute("y1", tip.y.toFixed(2));
        line.setAttribute("x2", stallPt.x.toFixed(2));
        line.setAttribute("y2", stallPt.y.toFixed(2));
        const joined = absDiff <= JOIN_TOLERANCE_DEG;
        line.setAttribute("stroke-dasharray", joined ? "0" : "2 3");
        line.style.opacity = joined ? "1" : (0.35 + 0.4 * (1 - absDiff / NEAR_DEG)).toFixed(3);
      }
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.032, (now - last) / 1000) : 1 / 60;
      last = now;
      if (mode === "springing") {
        vel += (-SPRING_K * (theta - springTarget) - SPRING_C * vel) * dt;
        theta += vel * dt;
        const settled =
          now >= springDeadline ||
          (Math.abs(theta - springTarget) < SETTLE_POS_EPS && Math.abs(vel) < SETTLE_VEL_EPS);
        if (settled) {
          theta = springTarget;
          vel = 0;
          mode = "idle";
          onSettled();
        }
      }
      render();
      if (mode === "springing") raf = requestAnimationFrame(loop);
    };

    const onSettled = () => {
      if (phase === "final" && pendingLocal !== null) {
        commitNow(pendingLocal);
      }
      // "hold" phase settling is silent: the bridge just sits short, unjoined,
      // waiting on confirmSwitch — nothing to announce until it resolves.
      phase = null;
    };

    const springTo = (target: number, ph: "hold" | "final") => {
      if (reduced) {
        theta = target;
        vel = 0;
        mode = "idle";
        render();
        if (ph === "final") onSettledInstant();
        return;
      }
      springTarget = target;
      phase = ph;
      mode = "springing";
      springDeadline = performance.now() + SETTLE_DEADLINE_MS;
      wake();
    };

    // reduced-motion settle path: same two-phase structure, no animation
    const onSettledInstant = () => {
      if (pendingLocal !== null) commitNow(pendingLocal);
    };

    const commitNow = (id: string) => {
      pendingLocal = null;
      committedLocal = id;
      setPendingId(null);
      setCommittedId(id);
      setConnected(true);
      setStatusText(`${nameOfId(id)}, connected.`);
      onValueChangeRef.current?.(id);
      if (!reduced && panelRef.current) {
        panelRef.current.animate(
          [{ transform: "translateX(0)" }, { transform: "translateX(1px)" }, { transform: "translateX(0)" }],
          { duration: 90, easing: "ease-out" }
        );
      }
    };

    const selectOrg = (id: string) => {
      if (id === pendingLocal) return;
      // only a no-op when nothing is in flight — reselecting the committed
      // org WHILE a different switch is pending (still holding short,
      // awaiting confirmSwitch) must redirect the bridge back, not stall.
      if (id === committedLocal && pendingLocal === null) return;
      const arr = dests();
      const target = arr.find((d) => d.id === id);
      if (!target) return;
      seq += 1;
      const mySeq = seq;
      pendingLocal = id;
      setPendingId(id);
      setConnected(false);
      setStatusText(`Switching to ${target.name}…`);

      const targetAngle = target.angle;
      const dir = Math.sign(targetAngle - theta) || 1;
      const holdAngle = targetAngle - dir * HOLD_SHORT_DEG;
      springTo(holdAngle, "hold");

      confirmRef.current(id).then(
        () => {
          if (seq !== mySeq) return; // superseded by a later selection
          springTo(targetAngle, "final");
        },
        () => {
          if (seq !== mySeq) return;
          setStatusText(`Couldn't confirm ${target.name} — holding.`);
          // stays parked HOLD_SHORT_DEG short, rails unjoined, until a new
          // selection is made or the consumer retries via confirmSwitch.
        }
      );
    };

    render();
    engineRef.current = { selectOrg, onOpen: render };

    return () => {
      cancelAnimationFrame(raf);
      engineRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- refs-only hot path, mount once
  }, []);

  useEffect(() => {
    if (open) {
      engineRef.current?.onOpen();
      const idx = positioned.findIndex((d) => d.id === (pendingId ?? committedId));
      setActiveIndex(idx >= 0 ? idx : 0);
      requestAnimationFrame(() => listboxRef.current?.focus({ preventScroll: true }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only react to open toggling
  }, [open]);

  // close on outside pointerdown / Escape from anywhere in the root
  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open]);

  // idempotent: opening never toggles closed. A prior automated press against
  // this same trigger (before a gate check re-clicks it) must not undo the
  // open state — only Escape, outside click, or Home-position navigation close it.
  const openMenu = () => setOpen(true);
  const closeMenu = (focusTrigger: boolean) => {
    setOpen(false);
    if (focusTrigger) triggerRef.current?.focus();
  };

  const commitIndex = (i: number) => {
    const org = positioned[i];
    if (!org) return;
    setActiveIndex(i);
    engineRef.current?.selectOrg(org.id);
  };

  const onTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " " || e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      openMenu();
    }
  };

  const onListKeyDown = (e: React.KeyboardEvent) => {
    const n = positioned.length;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(n - 1, i + 1));
    } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setActiveIndex(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setActiveIndex(n - 1);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      commitIndex(activeIndex);
    } else if (e.key === "Escape") {
      e.preventDefault();
      closeMenu(true);
    }
  };

  const currentOrg = positioned.find((o) => o.id === committedId) ?? positioned[0];
  const pendingOrg = pendingId ? positioned.find((o) => o.id === pendingId) : null;
  const triggerSub = pendingOrg ? `Switching to ${pendingOrg.name}…` : connected ? "Connected" : "Holding…";

  return (
    <div ref={rootRef} className={`relative inline-block ${className}`}>
      <div className="flex items-center gap-4">
        <button
          ref={triggerRef}
          type="button"
          aria-haspopup="listbox"
          aria-expanded={open}
          onClick={openMenu}
          onKeyDown={onTriggerKeyDown}
          className="flex items-center gap-2.5 rounded-md border border-border bg-background px-3 py-2 text-left outline-none transition-colors hover:border-foreground/25 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          <span
            aria-hidden
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full border border-border bg-foreground/[0.04] font-mono text-[11px] font-semibold text-foreground"
          >
            {(currentOrg?.initial ?? currentOrg?.name.charAt(0) ?? "?").toUpperCase()}
          </span>
          <span className="flex flex-col leading-tight">
            <span className="text-sm font-medium text-foreground">{currentOrg?.name ?? label}</span>
            <span className="font-mono text-[10px] uppercase tracking-widest text-ns-muted">
              {triggerSub}
            </span>
          </span>
          <svg aria-hidden viewBox="0 0 16 16" fill="none" className="ml-1 h-3.5 w-3.5 shrink-0 text-ns-muted">
            <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>

        {navItems.length > 0 ? (
          <nav aria-label="Org-scoped navigation" className="flex items-center gap-4">
            {navItems.map((item) => (
              <span key={item} className="flex flex-col items-start gap-1">
                <span
                  className={`text-sm transition-opacity duration-150 ${
                    connected ? "text-foreground/85 opacity-100" : "text-foreground/85 opacity-40"
                  }`}
                >
                  {item}
                </span>
                <span aria-hidden className="flex h-px w-full items-center gap-1">
                  {connected ? (
                    <span className="h-px w-full bg-border" />
                  ) : (
                    <>
                      <span className="h-px w-[38%] bg-border" />
                      <span className="h-px flex-1" />
                      <span className="h-px w-[38%] bg-border" />
                    </>
                  )}
                </span>
              </span>
            ))}
          </nav>
        ) : null}
      </div>

      {open ? (
        <div
          ref={panelRef}
          className="absolute left-0 top-full z-30 mt-2 w-[19rem] rounded-md border border-border bg-background shadow-[0_8px_16px_-4px_color-mix(in_oklab,var(--foreground)_20%,transparent),0_20px_48px_-12px_color-mix(in_oklab,var(--foreground)_35%,transparent)]"
        >
          <div className="border-b border-border px-3 py-2">
            <p className="font-mono text-[10px] uppercase tracking-widest text-ns-muted">
              {label}
            </p>
            <p aria-hidden className="mt-0.5 truncate font-mono text-[11px] text-ns-muted">
              {statusText || "Bridge aligned · rails joined"}
            </p>
          </div>

          <div className="relative">
            <svg viewBox={`0 0 ${VB_W} ${VB_H}`} className="block w-full" aria-hidden>
              <path d={arcPath(R_RIM)} fill="none" stroke="var(--border)" strokeWidth="1" opacity="0.5" />
              <circle cx={HUB_X} cy={HUB_Y} r={R_INNER - 6} fill="none" stroke="var(--border)" strokeWidth="1" />

              {/* fixed spurs: one per stall, never rotate */}
              {positioned.map((o) => {
                const inner = ptAt(o.angle, R_MATE);
                const outer = ptAt(o.angle, R_OUTER);
                return (
                  <g key={o.id}>
                    <line
                      x1={inner.x}
                      y1={inner.y}
                      x2={outer.x}
                      y2={outer.y}
                      stroke="var(--border)"
                      strokeWidth="2"
                    />
                    <circle cx={inner.x} cy={inner.y} r="2" fill="var(--border)" />
                  </g>
                );
              })}

              {/* per-stall dash junction: computed live from theta each frame */}
              {positioned.map((o, i) => (
                <line
                  key={`j-${o.id}`}
                  ref={(el) => {
                    junctionRefs.current[i] = el;
                  }}
                  stroke="var(--foreground)"
                  strokeWidth="1.5"
                  style={{ opacity: 0 }}
                />
              ))}

              {/* the bridge: your session. rotates as one rigid group. */}
              <g ref={bridgeGroupRef}>
                <line
                  x1={HUB_X - 4}
                  y1={HUB_Y - R_INNER}
                  x2={HUB_X - 4}
                  y2={HUB_Y - R_MATE}
                  stroke="var(--foreground)"
                  strokeWidth="2"
                />
                <line
                  x1={HUB_X + 4}
                  y1={HUB_Y - R_INNER}
                  x2={HUB_X + 4}
                  y2={HUB_Y - R_MATE}
                  stroke="var(--foreground)"
                  strokeWidth="2"
                />
                {Array.from({ length: 4 }).map((_, k) => {
                  const y = HUB_Y - (R_INNER + ((R_MATE - R_INNER) * (k + 0.5)) / 4);
                  return (
                    <line
                      key={k}
                      x1={HUB_X - 7}
                      y1={y}
                      x2={HUB_X + 7}
                      y2={y}
                      stroke="var(--foreground)"
                      strokeWidth="1.5"
                      opacity="0.6"
                    />
                  );
                })}
              </g>
              <circle cx={HUB_X} cy={HUB_Y} r="3" fill="var(--foreground)" />
            </svg>

            {/* stalls: real buttons, positioned over the SVG by percentage so
                they scale with it without a ResizeObserver */}
            <div
              ref={listboxRef}
              role="listbox"
              tabIndex={-1}
              aria-label={label}
              aria-activedescendant={optId(activeIndex)}
              onKeyDown={onListKeyDown}
              className="absolute inset-0 outline-none"
            >
              {positioned.map((o, i) => {
                const p = ptAt(o.angle, R_OUTER);
                const isActive = i === activeIndex;
                const isSelected = o.id === (pendingId ?? committedId);
                return (
                  <button
                    key={o.id}
                    id={optId(i)}
                    type="button"
                    role="option"
                    aria-selected={isSelected}
                    tabIndex={-1}
                    onPointerDown={(e) => e.preventDefault()}
                    onClick={() => commitIndex(i)}
                    onPointerMove={() => setActiveIndex(i)}
                    style={{ left: pct(p.x, VB_W), top: pct(p.y, VB_H) }}
                    className={`pointer-events-auto absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-0.5 rounded-sm px-1.5 py-1 outline-none transition-colors ${
                      isActive ? "bg-foreground/[0.07]" : ""
                    }`}
                  >
                    <span
                      aria-hidden
                      className={`flex h-6 w-6 items-center justify-center rounded-full border font-mono text-[10px] font-semibold ${
                        isSelected ? "border-foreground text-foreground" : "border-border text-ns-muted"
                      }`}
                    >
                      {(o.initial ?? o.name.charAt(0)).toUpperCase()}
                    </span>
                    <span className="whitespace-nowrap text-[11px] text-foreground">{o.name}</span>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex items-center justify-between gap-3 border-t border-border px-3 py-2">
            <p className="font-mono text-[10px] text-ns-muted">arrows move &middot; enter connects</p>
            <p className="font-mono text-[10px] text-ns-muted">esc closes</p>
          </div>
        </div>
      ) : null}

      <p role="status" className="sr-only">
        {statusText}
      </p>
    </div>
  );
}

"use client";

import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// TremorTrace — multi-user typing/presence as a live seismograph strip. One
// row per participant: a hairline SVG polyline that scrolls slowly leftward,
// spiking with amplitude proportional to that person's REAL keystroke
// cadence, decaying flat on pause, ending in a small terminal tick when they
// disconnect. Every number on screen originates from a real event the
// consumer feeds in (pulse() per throttled keystroke, `status` per presence
// update) — this component holds no rhythm of its own, unlike text-ekg-baseline's
// internal bpm timer. It never sees keystroke content, only that one
// occurred, coarse enough it can't leak timing beyond "someone is typing".
//
// Ring buffer: 31 fixed x-slots per row (30 visible + 1 incoming off the
// right edge), ticked every ~200ms (~5Hz). Scrolling is one CSS transform on
// a <g>, not per-frame point recomputation: each tick snaps the group back
// to translateX(0) instantly, shifts the buffer, appends the new sample,
// redraws the polyline's `points` attribute once, then animates
// translateX(-step) over the same 200ms until the next tick — a standard
// treadmill scroll, cheap and GPU-friendly. All of this happens on refs;
// React state only drives row list membership, status styling and the
// announced text.
// ---------------------------------------------------------------------------

export type TremorStatus = "typing" | "idle" | "disconnected";

export interface TremorUser {
  id: string;
  name: string;
  status: TremorStatus;
}

export interface TremorTraceHandle {
  /**
   * Register one throttled keystroke event for a user. Call this from a real
   * input handler — already throttled upstream is fine, this further buckets
   * calls into ~5Hz ticks itself. Never pass keystroke content, only the
   * fact one happened; cadence (count per tick), not timing, is the signal.
   */
  pulse: (userId: string) => void;
}

export interface TremorTraceProps {
  /** the currently-typing users */
  users: TremorUser[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const POINTS = 30;
const TICK_MS = 200; // ~5Hz sampling
const VIEW_W = 360;
const VIEW_H = 24;
const BASE_Y = VIEW_H / 2;
const AMP_PX = 9; // max spike half-height
const STEP = VIEW_W / POINTS;
const EXPECTED_PULSES = 2; // pulses/tick treated as "fully active" cadence
const RISE = 0.6;
const DECAY = Math.pow(2, -10 * (TICK_MS / 1000)); // ease-out-expo decay per tick

// Distinct fixed opacity per row so several traces are legible without color
// — this repo's token set has no red/green to spend on "who is who".
const OPACITY_STEPS = [1, 0.72, 0.5, 0.34];

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function flatPoints() {
  const pts: string[] = [];
  for (let i = 0; i <= POINTS; i++) pts.push(`${(i * STEP).toFixed(2)},${BASE_Y}`);
  return pts.join(" ");
}

interface TraceRowProps {
  name: string;
  status: TremorStatus;
  opacity: number;
  reducedMotion: boolean;
  counterRef: { current: number };
}

function TraceRow({ name, status, opacity, reducedMotion, counterRef }: TraceRowProps) {
  const groupRef = useRef<SVGGElement | null>(null);
  const polylineRef = useRef<SVGPolylineElement | null>(null);
  const markerRef = useRef<SVGLineElement | null>(null);

  const bufferRef = useRef<number[]>(Array(POINTS + 1).fill(0));
  const terminalFlagRef = useRef<number[]>(Array(POINTS + 1).fill(0));
  const ampRef = useRef(0);
  const parityRef = useRef(0);
  const endedRef = useRef(false);
  const statusRef = useRef<TremorStatus>(status);
  statusRef.current = status;

  const draw = () => {
    const poly = polylineRef.current;
    if (poly) {
      let pts = "";
      const buf = bufferRef.current;
      for (let i = 0; i < buf.length; i++) {
        pts += `${(i * STEP).toFixed(2)},${(BASE_Y - buf[i] * AMP_PX).toFixed(2)} `;
      }
      poly.setAttribute("points", pts.trim());
    }
    const marker = markerRef.current;
    if (marker) {
      const flags = terminalFlagRef.current;
      const idx = flags.lastIndexOf(1);
      if (idx === -1) {
        marker.style.opacity = "0";
      } else {
        const x = (idx * STEP).toFixed(2);
        marker.setAttribute("x1", x);
        marker.setAttribute("x2", x);
        marker.style.opacity = "1";
      }
    }
  };

  useEffect(() => {
    draw();
    // reduced motion: freeze flat, no interval at all — legibility never
    // depends on motion running.
    if (reducedMotion) {
      // a disconnected peer still gets its static terminal mark even at rest.
      if (status === "disconnected") {
        terminalFlagRef.current[POINTS] = 1;
        endedRef.current = true;
        draw();
      }
      return;
    }

    const id = setInterval(() => {
      const g = groupRef.current;
      if (!g) return;

      // snap the previous tick's animation back to rest, instantly
      g.style.transition = "none";
      g.style.transform = "translateX(0px)";

      bufferRef.current.shift();
      terminalFlagRef.current.shift();

      let value = 0;
      let flag = 0;

      if (endedRef.current) {
        value = 0; // a peer that has left produces no further cadence
      } else if (statusRef.current === "disconnected") {
        flag = 1; // the small terminal tick, once
        endedRef.current = true;
      } else {
        const count = counterRef.current;
        counterRef.current = 0;
        const target = Math.min(1, count / EXPECTED_PULSES);
        ampRef.current = count > 0 ? lerp(ampRef.current, target, RISE) : ampRef.current * DECAY;
        if (ampRef.current < 0.015) ampRef.current = 0;
        parityRef.current ^= 1;
        const sign = parityRef.current ? 1 : -1;
        const wobble = 0.65 + 0.35 * Math.random();
        value = ampRef.current * sign * wobble;
      }

      bufferRef.current.push(value);
      terminalFlagRef.current.push(flag);
      draw();

      // force reflow so the transition below actually animates from 0
      void g.getBoundingClientRect();
      g.style.transition = `transform ${TICK_MS}ms linear`;
      g.style.transform = `translateX(-${STEP}px)`;
    }, TICK_MS);

    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reducedMotion, status]);

  const showTypingTag = reducedMotion && status === "typing";
  const showEndedLabel = status === "disconnected";

  return (
    <div className="flex items-center gap-3" style={{ opacity }}>
      <span
        className={[
          "w-16 shrink-0 truncate font-mono text-[11px]",
          showEndedLabel ? "text-ns-muted" : "text-foreground",
        ].join(" ")}
      >
        {name}
      </span>

      <div
        className="h-4 min-w-0 flex-1"
        style={{
          maskImage: "linear-gradient(to right, transparent, black 6%, black 94%, transparent)",
          WebkitMaskImage:
            "linear-gradient(to right, transparent, black 6%, black 94%, transparent)",
        }}
      >
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          preserveAspectRatio="none"
          className="h-full w-full text-foreground"
          aria-hidden="true"
        >
          <g ref={groupRef}>
            <polyline
              ref={polylineRef}
              points={flatPoints()}
              fill="none"
              stroke="currentColor"
              strokeWidth={1}
              vectorEffect="non-scaling-stroke"
            />
            <line
              ref={markerRef}
              x1={VIEW_W}
              x2={VIEW_W}
              y1={BASE_Y - AMP_PX}
              y2={BASE_Y + AMP_PX}
              stroke="currentColor"
              strokeWidth={1.5}
              vectorEffect="non-scaling-stroke"
              style={{ opacity: 0 }}
            />
          </g>
        </svg>
      </div>

      {showTypingTag ? (
        <span className="shrink-0 font-mono text-[10px] uppercase tracking-wide text-ns-muted">
          typing
        </span>
      ) : null}
    </div>
  );
}

export const TremorTrace = forwardRef<TremorTraceHandle, TremorTraceProps>(function TremorTrace(
  { users, className = "" },
  ref
) {
  const [reducedMotion, setReducedMotion] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const countersRef = useRef<Map<string, { current: number }>>(new Map());
  const prevStatusRef = useRef<Map<string, TremorStatus>>(new Map());

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReducedMotion(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useImperativeHandle(
    ref,
    () => ({
      pulse(userId: string) {
        const counters = countersRef.current;
        let c = counters.get(userId);
        if (!c) {
          c = { current: 0 };
          counters.set(userId, c);
        }
        c.current += 1;
      },
    }),
    []
  );

  useEffect(() => {
    const prev = prevStatusRef.current;
    let msg = "";
    for (const u of users) {
      const before = prev.get(u.id);
      if (before === undefined) {
        prev.set(u.id, u.status);
        continue; // never announce the initial mount state
      }
      if (before !== u.status) {
        if (u.status === "typing") msg = `${u.name} started typing`;
        else if (u.status === "disconnected") msg = `${u.name} left`;
        else if (u.status === "idle" && before === "typing") msg = `${u.name} stopped`;
        prev.set(u.id, u.status);
      }
    }
    if (msg) setAnnouncement(msg);
  }, [users]);

  function counterFor(id: string) {
    const counters = countersRef.current;
    let c = counters.get(id);
    if (!c) {
      c = { current: 0 };
      counters.set(id, c);
    }
    return c;
  }

  return (
    <div className={["w-full rounded-md border border-border bg-surface p-4", className].join(" ")}>
      <div className="flex flex-col gap-3">
        {users.map((u, i) => (
          <TraceRow
            key={u.id}
            name={u.name}
            status={u.status}
            opacity={OPACITY_STEPS[i % OPACITY_STEPS.length]}
            reducedMotion={reducedMotion}
            counterRef={counterFor(u.id)}
          />
        ))}
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
});

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// UndertowDrift — inline undo for destructive list actions where POSITION,
// not a number, is the clock. Deleting a row spring-collapses it in place to
// a compact 28px bar holding the title + an undo arrow; once collapsed the
// bar drifts, via a single linear WAAPI transform, toward the row's trailing
// edge over the grace window — distance already traveled reads as time
// already spent, distance left as time left. Reaching the edge fades the bar
// and finalizes the delete (list reflows). Clicking/Enter-ing the bar cancels
// with an ease-out-back spring on both its position and the row height,
// plus a one-shot border flash (--border -> --foreground -> --border).
// Hover or keyboard focus on the bar pauses the underlying Animation object
// directly, so the countdown genuinely stops rather than racing a separate
// timer. prefers-reduced-motion keeps the collapse (a state change, not a
// decoration) but never drifts the bar horizontally — instead a static
// visible "Ns" readout ticks down next to the title, since time-as-distance
// is an enhancement layered on top of a countdown that must survive without
// it, never the sole channel.
// ---------------------------------------------------------------------------

export interface UndertowItem {
  id: string;
  title: string;
}

export interface UndertowDriftProps {
  /** the deletable rows */
  items: UndertowItem[];
  /** ms the collapsed bar takes to drift fully across before the delete commits */
  graceMs?: number;
  /** called immediately when a row's delete is triggered, before the grace window */
  onDelete?: (item: UndertowItem) => void;
  /** called if the delete is undone within the grace window */
  onRestore?: (item: UndertowItem) => void;
  /** fires once the grace window elapses (or the bar is dismissed) and the item is gone for good */
  onExpire?: (item: UndertowItem) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const BAR_HEIGHT = 28; // px — the collapsed bar's fixed height
const COLLAPSE_MS = 250; // height spring: full row -> bar
const SNAPBACK_MS = 420; // cancel: bar position + row height spring back together
// no-overshoot deceleration for the collapse (matches the "glide" curve used
// elsewhere in this registry for settle/collapse transitions)
const COLLAPSE_EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
// ease-out-back: the explicit overshoot the brief calls for on cancel only
const SNAPBACK_EASE = "cubic-bezier(0.34, 1.56, 0.64, 1)";

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function TrashIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path
        d="M3 4.5h10M6.5 4.5V3a1 1 0 0 1 1-1h1a1 1 0 0 1 1 1v1.5M4.5 4.5l.6 8.2a1 1 0 0 0 1 .8h3.8a1 1 0 0 0 1-.8l.6-8.2"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ReturnArrowIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3 w-3 shrink-0" fill="none" aria-hidden>
      <path
        d="M11.5 5.5H6a2.5 2.5 0 0 0 0 5h2.5"
        stroke="currentColor"
        strokeWidth="1.3"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M8.6 3.4 11.5 5.5 8.6 7.6"
        stroke="currentColor"
        strokeWidth="1.3"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Row({
  item,
  onDelete,
}: {
  item: UndertowItem;
  onDelete: (fromHeight: number) => void;
}) {
  const rowRef = useRef<HTMLDivElement>(null);
  return (
    <li className="border-b border-border last:border-b-0" data-uw-row>
      <div ref={rowRef} className="flex items-center gap-3 px-4 py-3">
        <p className="min-w-0 flex-1 truncate text-sm text-foreground">{item.title}</p>
        <button
          type="button"
          data-uw-delete
          onClick={() => onDelete(rowRef.current?.getBoundingClientRect().height ?? 0)}
          aria-label={`Delete ${item.title}`}
          className="shrink-0 rounded-sm p-1.5 text-ns-muted transition-colors hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          <TrashIcon />
        </button>
      </div>
    </li>
  );
}

function BarRow({
  item,
  graceMs,
  reduced,
  fromHeight,
  onRestore,
  onExpire,
}: {
  item: UndertowItem;
  graceMs: number;
  reduced: boolean;
  fromHeight: number;
  onRestore: () => void;
  onExpire: () => void;
}) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const barRef = useRef<HTMLButtonElement>(null);
  const driftRef = useRef<Animation | null>(null);
  const collapseRef = useRef<Animation | null>(null);
  const travelRef = useRef(0);
  const hoverRef = useRef(false);
  const focusRef = useRef(false);
  const settledRef = useRef(false); // true once restored or expired — guards double-fire
  const flashTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const [remaining, setRemaining] = useState(Math.ceil(graceMs / 1000));
  const [flash, setFlash] = useState(false);

  useLayoutEffect(() => {
    const wrap = wrapRef.current;
    const track = trackRef.current;
    const bar = barRef.current;
    if (!wrap || !track || !bar) return;

    // focus moves to the bar the instant it exists — Enter is immediate undo,
    // independent of whether the collapse has visually finished yet
    bar.focus();

    const startDrift = () => {
      const trackWidth = track.clientWidth;
      const barWidth = bar.offsetWidth;
      const travel = Math.max(0, trackWidth - barWidth);
      travelRef.current = travel;
      const targetX = reduced ? 0 : travel;
      const anim = bar.animate(
        [{ transform: "translateX(0px)" }, { transform: `translateX(${targetX}px)` }],
        { duration: Math.max(1, graceMs), easing: "linear", fill: "forwards" }
      );
      driftRef.current = anim;
      anim.onfinish = () => {
        if (settledRef.current) return;
        settledRef.current = true;
        const fade = bar.animate(
          [{ opacity: 1 }, { opacity: 0 }],
          { duration: reduced ? 1 : 200, easing: "ease-out", fill: "forwards" }
        );
        fade.onfinish = () => onExpire();
      };
    };

    if (reduced) {
      // reduced motion: no clock to race visually, but the state change
      // (full row -> bar) still happens, just without the spring
      wrap.style.height = `${BAR_HEIGHT}px`;
      startDrift();
    } else {
      wrap.style.height = `${fromHeight}px`;
      const anim = wrap.animate(
        [{ height: `${fromHeight}px` }, { height: `${BAR_HEIGHT}px` }],
        { duration: COLLAPSE_MS, easing: COLLAPSE_EASE, fill: "forwards" }
      );
      collapseRef.current = anim;
      anim.onfinish = () => {
        wrap.style.height = `${BAR_HEIGHT}px`;
        startDrift();
      };
    }

    return () => {
      driftRef.current?.cancel();
      collapseRef.current?.cancel();
      if (flashTimerRef.current) clearTimeout(flashTimerRef.current);
    };
    // fromHeight/graceMs/reduced are fixed for this bar's lifetime — a prop
    // change mid-flight shouldn't restart the clock out from under it
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // aria-label's "N seconds left" updates on a coarse 1s tick, reading the
  // live Animation.currentTime rather than keeping a second, racy clock
  useEffect(() => {
    const tick = () => {
      const anim = driftRef.current;
      const elapsed = anim ? Number(anim.currentTime) || 0 : 0;
      setRemaining(Math.max(0, Math.ceil((graceMs - elapsed) / 1000)));
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [graceMs]);

  function pause() {
    (driftRef.current ?? collapseRef.current)?.pause();
  }
  function maybeResume() {
    if (hoverRef.current || focusRef.current) return;
    const anim = driftRef.current ?? collapseRef.current;
    if (anim && anim.playState === "paused") anim.play();
  }

  function handleUndo() {
    if (settledRef.current) return;
    settledRef.current = true;

    const wrap = wrapRef.current;
    const bar = barRef.current;

    flashTimerRef.current = setTimeout(() => setFlash(false), 300);
    setFlash(true);

    if (!wrap || !bar) {
      onRestore();
      return;
    }

    // read live state before cancelling — cancel() nulls Animation.currentTime
    const currentWrapHeight = wrap.getBoundingClientRect().height;
    const driftAnim = driftRef.current;
    const elapsed = driftAnim ? Number(driftAnim.currentTime) || 0 : 0;
    const frac = graceMs > 0 ? Math.min(1, elapsed / graceMs) : 0;
    const barX = frac * travelRef.current;

    driftAnim?.cancel();
    collapseRef.current?.cancel();

    if (reduced) {
      wrap.style.height = `${fromHeight}px`;
      onRestore();
      return;
    }

    bar.animate(
      [{ transform: `translateX(${barX}px)` }, { transform: "translateX(0px)" }],
      { duration: SNAPBACK_MS, easing: SNAPBACK_EASE, fill: "forwards" }
    );
    const grow = wrap.animate(
      [{ height: `${currentWrapHeight}px` }, { height: `${fromHeight}px` }],
      { duration: SNAPBACK_MS, easing: SNAPBACK_EASE, fill: "forwards" }
    );
    grow.onfinish = () => onRestore();
  }

  return (
    <li className="border-b border-border last:border-b-0" data-uw-row>
      <div ref={wrapRef} className="overflow-hidden">
        <div ref={trackRef} className="relative" style={{ height: BAR_HEIGHT }}>
          <button
            ref={barRef}
            type="button"
            data-uw-bar
            onClick={handleUndo}
            onPointerEnter={() => {
              hoverRef.current = true;
              pause();
            }}
            onPointerLeave={() => {
              hoverRef.current = false;
              maybeResume();
            }}
            onFocus={() => {
              focusRef.current = true;
              pause();
            }}
            onBlur={() => {
              focusRef.current = false;
              maybeResume();
            }}
            aria-label={`Deleted ${item.title}, undo, ${remaining} second${remaining === 1 ? "" : "s"} left`}
            className={[
              "absolute left-0 top-0 inline-flex h-full max-w-[65%] items-center gap-1.5 overflow-hidden whitespace-nowrap rounded-sm border bg-surface px-2 font-mono text-xs text-ns-muted",
              "transition-colors duration-150 hover:text-foreground",
              flash ? "border-foreground" : "border-border hover:border-foreground/50",
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
            ].join(" ")}
          >
            <ReturnArrowIcon />
            <span className="truncate">{item.title}</span>
            {reduced && (
              <span aria-hidden className="tabular-nums text-ns-muted">
                {remaining}s
              </span>
            )}
          </button>
        </div>
      </div>
    </li>
  );
}

export function UndertowDrift({
  items,
  graceMs = 6000,
  onDelete,
  onRestore,
  onExpire,
  className = "",
}: UndertowDriftProps) {
  const [rows, setRows] = useState(() =>
    items.map((it) => ({ ...it, pending: false, fromHeight: 0 }))
  );
  const [announcement, setAnnouncement] = useState("");
  const reduced = useReducedMotion();
  const rowsRef = useRef(rows);
  rowsRef.current = rows;

  function handleDelete(id: string, fromHeight: number) {
    const item = rowsRef.current.find((r) => r.id === id);
    if (!item) return;
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, pending: true, fromHeight } : r)));
    onDelete?.(item);
    setAnnouncement(`Deleted ${item.title}. Undo available for ${Math.round(graceMs / 1000)} seconds.`);
  }

  function handleRestore(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, pending: false } : r)));
    if (item) {
      onRestore?.(item);
      setAnnouncement(`Restored ${item.title}.`);
    }
  }

  function handleExpire(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.filter((r) => r.id !== id));
    if (item) onExpire?.(item);
  }

  return (
    <div className={className}>
      {rows.length === 0 ? (
        <p className="rounded-md border border-dashed border-border px-4 py-6 text-center text-sm text-ns-muted">
          Nothing here.
        </p>
      ) : (
        <ul data-uw-list className="overflow-hidden rounded-md border border-border bg-surface">
          {rows.map((r) =>
            r.pending ? (
              <BarRow
                key={r.id}
                item={r}
                graceMs={graceMs}
                reduced={reduced}
                fromHeight={r.fromHeight}
                onRestore={() => handleRestore(r.id)}
                onExpire={() => handleExpire(r.id)}
              />
            ) : (
              <Row key={r.id} item={r} onDelete={(h) => handleDelete(r.id, h)} />
            )
          )}
        </ul>
      )}
      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AfterImageList — inline undo for destructive list actions, no toast. On
// delete, a row swaps in place for a same-height ghost: 1px dashed --border,
// the item title at 40% opacity, a real "Undo delete: <title>" button. The
// ghost's height is driven directly by the Web Animations API (linear,
// ~8s, full height -> 0) so remaining time reads as remaining height —
// siblings below ride the shrink smoothly since it's plain document flow.
// Hover or focus pauses the Animation object in place; a click cancels it,
// reads the live height, and starts a second animation back up to full
// height with an ease-out-expo curve, restoring the row on finish. Deletion
// announces the undo window through an aria-live region; the timer is
// genuinely paused while the ghost has keyboard focus, so assistive tech is
// never raced by the clock. prefers-reduced-motion holds the ghost at full
// height indefinitely (no auto-collapse) and adds an explicit dismiss
// button, since there is no longer a timeout to rely on.
// ---------------------------------------------------------------------------

export interface AfterImageItem {
  id: string;
  title: string;
  subtitle?: string;
}

export interface AfterImageListProps {
  /** the deletable rows */
  items: AfterImageItem[];
  /** ms the ghost takes to collapse to zero height and finalize the delete */
  ghostMs?: number;
  /** called immediately when a row's delete is triggered, before the ghost window */
  onDelete?: (item: AfterImageItem) => void;
  /** called if the delete is undone within the ghost window */
  onRestore?: (item: AfterImageItem) => void;
  /** fires once the ghost window elapses (or is dismissed) and the item is gone for good */
  onExpire?: (item: AfterImageItem) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// Re-inflate curve: an ease-out-expo approximation, matching the house
// spring-adjacent easing used elsewhere in this registry (see approval-inline-diff's
// collapse transition) rather than inventing a new one.
const REINFLATE_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const REINFLATE_MS = 380;

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function TrashIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path
        d="M3 4.5h10M6.5 4.5V3a1 1 0 0 1 1-1h1a1 1 0 0 1 1 1v1.5M4.5 4.5l.6 8.2a1 1 0 0 0 1 .8h3.8a1 1 0 0 0 1-.8l.6-8.2"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function UndoIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5 shrink-0" fill="none" aria-hidden>
      <path
        d="M4 6.5H10.5a3 3 0 0 1 0 6H8"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M6.2 4 4 6.5l2.2 2.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
