}

function Row({ item, onDelete }: { item: AfterImageItem; onDelete: () => void }) {
  return (
    <li className="border-b border-border last:border-b-0">
      <div className="flex items-center gap-3 px-4 py-3">
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm text-foreground">{item.title}</p>
          {item.subtitle ? (
            <p className="truncate text-xs text-ns-muted">{item.subtitle}</p>
          ) : null}
        </div>
        <button
          type="button"
          data-afterimage-delete
          onClick={onDelete}
          aria-label={`Delete ${item.title}`}
          className="shrink-0 rounded-sm p-1.5 text-ns-muted transition-colors hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          <TrashIcon />
        </button>
      </div>
    </li>
  );
}

function GhostRow({
  item,
  ghostMs,
  reduced,
  onRestore,
  onExpire,
}: {
  item: AfterImageItem;
  ghostMs: number;
  reduced: boolean;
  onRestore: () => void;
  onExpire: () => void;
}) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const animRef = useRef<Animation | null>(null);
  const fullRef = useRef(0);
  const hoverRef = useRef(false);
  const focusRef = useRef(false);
  const settledRef = useRef(false); // true once restored or expired — guards double-fire

  useLayoutEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const full = el.scrollHeight;
    fullRef.current = full;
    el.style.height = `${full}px`;

    if (reduced) return; // static: no clock to race, dismiss button finalizes instead

    const anim = el.animate(
      [{ height: `${full}px` }, { height: "0px" }],
      { duration: ghostMs, easing: "linear", fill: "forwards" }
    );
    animRef.current = anim;
    anim.onfinish = () => {
      if (settledRef.current) return;
      settledRef.current = true;
      onExpire();
    };
    return () => {
      anim.cancel();
    };
    // ghostMs/onExpire intentionally fixed for this ghost's lifetime — a
    // prop change mid-collapse shouldn't restart the clock out from under it
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  function pause() {
    animRef.current?.pause();
  }

  function maybeResume() {
    if (hoverRef.current || focusRef.current) return;
    const anim = animRef.current;
    if (anim && anim.playState === "paused") anim.play();
  }

  function handleRestore() {
    if (settledRef.current) return;
    settledRef.current = true;
    const el = wrapRef.current;
    const anim = animRef.current;
    if (!el || reduced || !anim) {
      onRestore();
      return;
    }
    const currentHeight = el.getBoundingClientRect().height;
    anim.cancel();
    const reinflate = el.animate(
      [{ height: `${currentHeight}px` }, { height: `${fullRef.current}px` }],
      { duration: REINFLATE_MS, easing: REINFLATE_EASE, fill: "forwards" }
    );
    animRef.current = reinflate;
    reinflate.onfinish = () => onRestore();
  }

  return (
    <li className="border-b border-border last:border-b-0">
      <div ref={wrapRef} className="overflow-hidden">
        <div
          className="flex items-center gap-2 border border-dashed border-border px-4 py-3"
          onPointerEnter={() => {
            hoverRef.current = true;
            pause();
          }}
          onPointerLeave={() => {
            hoverRef.current = false;
            maybeResume();
          }}
          onFocus={() => {
            focusRef.current = true;
            pause();
          }}
          onBlur={() => {
            focusRef.current = false;
            maybeResume();
          }}
        >
          <button
            type="button"
            data-afterimage-undo
            onClick={handleRestore}
            aria-label={`Undo delete: ${item.title}`}
            className="flex min-w-0 flex-1 items-center gap-2 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            <UndoIcon />
            <span className="truncate text-sm text-foreground/40">{item.title}</span>
          </button>
          {reduced ? (
            <button
              type="button"
              onClick={() => {
                if (settledRef.current) return;
                settledRef.current = true;
                onExpire();
              }}
              aria-label={`Dismiss: finish deleting ${item.title}`}
              className="shrink-0 rounded-sm p-1.5 text-ns-muted transition-colors hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              <XIcon />
            </button>
          ) : (
            <span className="shrink-0 font-mono text-[10px] uppercase tracking-wide text-ns-muted">
              Undo
            </span>
          )}
        </div>
      </div>
    </li>
  );
}

export function AfterImageList({
  items,
  ghostMs = 8000,
  onDelete,
  onRestore,
  onExpire,
  className = "",
}: AfterImageListProps) {
  const [rows, setRows] = useState(() => items.map((it) => ({ ...it, ghosted: false })));
  const [announcement, setAnnouncement] = useState("");
  const reduced = useReducedMotion();
  const rowsRef = useRef(rows);
  rowsRef.current = rows;

  function handleDelete(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    if (!item) return;
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, ghosted: true } : r)));
    onDelete?.(item);
    setAnnouncement(
      reduced
        ? `Deleted ${item.title}. Undo available until dismissed.`
        : `Deleted ${item.title}. Undo available for ${Math.round(ghostMs / 1000)} seconds.`
    );
  }

  function handleRestore(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, ghosted: false } : r)));
    if (item) {
      onRestore?.(item);
      setAnnouncement(`Restored ${item.title}.`);
    }
  }

  function handleExpire(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.filter((r) => r.id !== id));
    if (item) onExpire?.(item);
  }

  return (
    <div className={className}>
      {rows.length === 0 ? (
        <p className="rounded-md border border-dashed border-border px-4 py-6 text-center text-sm text-ns-muted">
          Nothing here.
        </p>
      ) : (
        <ul className="overflow-hidden rounded-md border border-border bg-surface">
          {rows.map((r) =>
            r.ghosted ? (
              <GhostRow
                key={r.id}
                item={r}
                ghostMs={ghostMs}
                reduced={reduced}
                onRestore={() => handleRestore(r.id)}
                onExpire={() => handleExpire(r.id)}
              />
            ) : (
              <Row key={r.id} item={r} onDelete={() => handleDelete(r.id)} />
            )
          )}
        </ul>
      )}
      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

"use client";

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type FormEvent,
} from "react";

// ---------------------------------------------------------------------------
// PunchList — form-error handling as a contractor's punch list. A failed
// submit doesn't paint every field red and leave the user to hunt: it pins a
// compact numbered defect list (Geist Mono) to the top of the form. Picking
// an item scrolls to its field and draws a temporary hairline SVG leader
// line from the list entry to the field's bounding box (stroke-dashoffset
// draw, 300ms, fading out ~1.5s later) while the field's own error border
// pulses once. Fixing a field draws a scaleX(0->1) strike-through rule over
// its list entry (house ease-out-expo, cubic-bezier(0.16,1,0.3,1)),
// decrements a remaining-count badge with a short number-settle, and once
// every item is struck the whole list collapses itself away.
//
// Unlike a stock WCAG error-summary (a static list of links into the form)
// this adds three things that pattern never renders: the spatial leader
// link between summary and field, live strike-through as items get fixed,
// and self-dismissal at zero — the summary is a live progress artifact, not
// a one-shot dump. Unlike approval-inline-diff (a single tool-call approved/denied
// once and never reopened) this is per-field, revalidates live, and can
// re-arm on a second failed submit.
//
// A11Y: the summary is a real role=alert region that receives focus on a
// failed submit; every item is a plain <a href="#field-id"> so Tab reaches
// it and Enter/click both work with no JS. Every field carries aria-invalid
// and aria-describedby pointing at its own inline error paragraph. Leader
// lines and strikes are aria-hidden decoration; a dedicated aria-live=polite
// region separately announces each resolution ("Email resolved, 2
// remaining"). Reduced motion: lines and strikes render at their end state
// instantly, no timers spent waiting on animation before state settles.
//
// Colors: --background/--foreground/--ns-muted/--border/--ns-accent throughout;
// error state reads the semantic --error custom property (house convention
// for status-only red, e.g. validation-inline-wick / toast-gravity-stack / stepper-needle)
// with a literal fallback so the component still reads correctly for a
// consumer who hasn't set --error. --ns-accent is reserved for the submit
// button and focus rings — never used to indicate the error itself.
// ---------------------------------------------------------------------------

const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // house ease-out-expo approximation
const ERROR = "var(--error, #ea001d)";

const LEADER_DRAW_MS = 300;
const LEADER_HOLD_MS = 1500;
const LEADER_FADE_MS = 300;
const PULSE_MS = 520;
const RESOLVE_HOLD_MS = 700;
const ROW_COLLAPSE_MS = 240;
const PANEL_COLLAPSE_MS = 320;
const DISMISS_DELAY_MS = 260;

export interface PunchListField {
  /** also becomes the input's DOM id and the list item's #anchor target */
  id: string;
  label: string;
  type?: "text" | "email" | "tel" | "textarea";
  placeholder?: string;
  defaultValue?: string;
  /** return an error message, or null when the value is valid */
  validate: (value: string) => string | null;
}

export interface PunchListProps {
  /** the form fields, in order */
  fields: PunchListField[];
  /** heading above the form */
  title?: string;
  /** submit button text */
  submitLabel?: string;
  /** called with all field values, keyed by field id, once submission passes validation */
  onSubmit?: (values: Record<string, string>) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Rect = { x1: number; y1: number; x2: number; y2: number };
type Leader = Rect & { id: string; drawn: boolean; fading: boolean };

function useReducedMotion() {
  const ref = useRef(false);
  useEffect(() => {
    ref.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);
  return ref;
}

export function PunchList({
  fields,
  title = "Punch list",
  submitLabel = "Submit",
  onSubmit,
  className = "",
}: PunchListProps) {
  const fieldsById = useMemo(() => {
    const m = new Map<string, PunchListField>();
    for (const f of fields) m.set(f.id, f);
    return m;
  }, [fields]);

  const [values, setValues] = useState<Record<string, string>>(() =>
    Object.fromEntries(fields.map((f) => [f.id, f.defaultValue ?? ""])),
  );
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [numberMap, setNumberMap] = useState<Record<string, number>>({});
  const [resolving, setResolving] = useState<Set<string>>(new Set());
  const [collapsing, setCollapsing] = useState<Set<string>>(new Set());
  const [attempted, setAttempted] = useState(false);
  const [dismissed, setDismissed] = useState(true);
  const [statusText, setStatusText] = useState("Nothing submitted yet.");
  const [liveMessage, setLiveMessage] = useState("");
  const [leader, setLeader] = useState<Leader | null>(null);
  const [pulseId, setPulseId] = useState<string | null>(null);

  const reducedRef = useReducedMotion();

  const containerRef = useRef<HTMLDivElement | null>(null);
  const summaryRef = useRef<HTMLDivElement | null>(null);
  const itemRefs = useRef<Record<string, HTMLAnchorElement | null>>({});
  const fieldWrapRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const inputRefs = useRef<
    Record<string, HTMLInputElement | HTMLTextAreaElement | null>
  >({});

  const leaderTimers = useRef<{
    fallback?: ReturnType<typeof setTimeout>;
    fade?: ReturnType<typeof setTimeout>;
    remove?: ReturnType<typeof setTimeout>;
    onEnd?: () => void;
  }>({});
  const resolveTimers = useRef<Record<string, ReturnType<typeof setTimeout>[]>>({});

  useEffect(() => {
    return () => {
      const lt = leaderTimers.current;
      clearTimeout(lt.fallback);
      clearTimeout(lt.fade);
      clearTimeout(lt.remove);
      if (lt.onEnd) window.removeEventListener("scrollend", lt.onEnd);
      Object.values(resolveTimers.current).forEach((arr) =>
        arr.forEach((t) => clearTimeout(t)),
      );
    };
  }, []);

  // self-dismiss once every open defect has drained and finished animating
  useEffect(() => {
    if (!attempted || dismissed) return;
    if (Object.keys(errors).length === 0 && resolving.size === 0) {
      const t = setTimeout(
        () => {
          setDismissed(true);
          setStatusText("All clear — nothing left to fix.");
        },
        reducedRef.current ? 0 : DISMISS_DELAY_MS,
      );
      return () => clearTimeout(t);
    }
  }, [attempted, dismissed, errors, resolving, reducedRef]);

  const orderedIds = useMemo(
    () =>
      fields
        .map((f) => f.id)
        .filter((id) => id in errors || resolving.has(id))
        .sort((a, b) => (numberMap[a] ?? 0) - (numberMap[b] ?? 0)),
    [fields, errors, resolving, numberMap],
  );

  const remaining = Object.keys(errors).length;

  function clearLeaderTimers() {
    const lt = leaderTimers.current;
    clearTimeout(lt.fallback);
    clearTimeout(lt.fade);
    clearTimeout(lt.remove);
    if (lt.onEnd) window.removeEventListener("scrollend", lt.onEnd);
    leaderTimers.current = {};
  }

  function pulseField(id: string) {
    if (reducedRef.current) return;
    setPulseId(null);
    // restart the CSS animation without remounting — same trick as the
    // house checkbox settle-pop: drop the class, force reflow, re-add it.
    requestAnimationFrame(() => setPulseId(id));
  }

  function drawLeader(id: string) {
    const container = containerRef.current;
    const item = itemRefs.current[id];
    const fieldWrap = fieldWrapRefs.current[id];
    if (!container || !item || !fieldWrap) return;
    const cRect = container.getBoundingClientRect();
    const iRect = item.getBoundingClientRect();
    const fRect = fieldWrap.getBoundingClientRect();
    const next: Leader = {
      id,
      x1: iRect.right - cRect.left,
      y1: iRect.top + iRect.height / 2 - cRect.top,
      x2: fRect.left - cRect.left,
      y2: fRect.top + fRect.height / 2 - cRect.top,
      drawn: false,
      fading: false,
    };
    setLeader(next);
    pulseField(id);
    if (reducedRef.current) {
      setLeader({ ...next, drawn: true });
      return;
    }
    requestAnimationFrame(() => setLeader((cur) => (cur ? { ...cur, drawn: true } : cur)));
    leaderTimers.current.fade = setTimeout(() => {
      setLeader((cur) => (cur ? { ...cur, fading: true } : cur));
    }, LEADER_DRAW_MS + LEADER_HOLD_MS);
    leaderTimers.current.remove = setTimeout(() => {
      setLeader(null);
    }, LEADER_DRAW_MS + LEADER_HOLD_MS + LEADER_FADE_MS);
  }

  function selectItem(id: string) {
    const input = inputRefs.current[id];
    const fieldWrap = fieldWrapRefs.current[id];
    if (!input || !fieldWrap) return;
    clearLeaderTimers();
    input.focus({ preventScroll: true });
    if (reducedRef.current) {
      fieldWrap.scrollIntoView({ behavior: "auto", block: "center" });
      drawLeader(id);
      return;
    }
    fieldWrap.scrollIntoView({ behavior: "smooth", block: "center" });
    let done = false;
    const onEnd = () => {
      if (done) return;
      done = true;
      window.removeEventListener("scrollend", onEnd);
      drawLeader(id);
    };
    leaderTimers.current.onEnd = onEnd;
    window.addEventListener("scrollend", onEnd, { once: true });
    leaderTimers.current.fallback = setTimeout(onEnd, 450);
  }

  function resolveField(id: string) {
    const field = fieldsById.get(id);
    if (!field) return;
    const nextRemaining = Object.keys(errors).length - 1;
    setErrors((prev) => {
      const n = { ...prev };
      delete n[id];
      return n;
    });
    setResolving((prev) => new Set(prev).add(id));
    setLiveMessage(
      `${field.label} resolved, ${nextRemaining} remaining.`,
    );
    (resolveTimers.current[id] ??= []).forEach((t) => clearTimeout(t));
    resolveTimers.current[id] = [];

    const finish = () => {
      setResolving((prev) => {
        const n = new Set(prev);
        n.delete(id);
        return n;
      });
      setCollapsing((prev) => {
        const n = new Set(prev);
        n.delete(id);
        return n;
      });
    };

    if (reducedRef.current) {
      finish();
      return;
    }

    const t1 = setTimeout(() => {
      setCollapsing((prev) => new Set(prev).add(id));
      const t2 = setTimeout(finish, ROW_COLLAPSE_MS);
      resolveTimers.current[id].push(t2);
    }, RESOLVE_HOLD_MS);
    resolveTimers.current[id].push(t1);
  }

  function handleChange(id: string, val: string) {
    setValues((prev) => ({ ...prev, [id]: val }));
    if (!(id in errors)) return;
    const field = fieldsById.get(id);
    if (!field) return;
    const msg = field.validate(val);
    if (msg) {
      setErrors((prev) => ({ ...prev, [id]: msg }));
      return;
    }
    resolveField(id);
  }

  function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const nextErrors: Record<string, string> = {};
    for (const f of fields) {
      const msg = f.validate(values[f.id] ?? "");
      if (msg) nextErrors[f.id] = msg;
    }

    if (Object.keys(nextErrors).length === 0) {
      onSubmit?.(values);
      setErrors({});
      setAttempted(false);
      setDismissed(true);
      setStatusText("Submitted — no open issues.");
      setLiveMessage("Form submitted.");
      return;
    }

    const nm: Record<string, number> = {};
    let n = 0;
    for (const f of fields) if (nextErrors[f.id]) nm[f.id] = ++n;

    setErrors(nextErrors);
    setNumberMap(nm);
    setResolving(new Set());
    setCollapsing(new Set());
    setAttempted(true);
    setDismissed(false);
    setStatusText("");
    setLiveMessage("");
    requestAnimationFrame(() => summaryRef.current?.focus());
  }

  const showPanel = attempted && !dismissed;

  return (
    <div
      ref={containerRef}
      className={`relative w-full rounded-md border border-border bg-surface p-5 ${className}`}
    >
      <style>{`
        .ns-punch-strike {
          position: absolute;
          left: 0;
          right: 0;
          top: 50%;
          height: 1px;
          background: var(--foreground);
          transform: scaleX(0);
          transform-origin: left;
          transition: transform 260ms ${EASE};
        }
        .ns-punch-strike[data-on="true"] { transform: scaleX(1); }
        .ns-punch-pulse { animation: ns-punch-pulse ${PULSE_MS}ms ease-out; }
        @keyframes ns-punch-pulse {
          0% { box-shadow: 0 0 0 0 color-mix(in srgb, ${ERROR} 55%, transparent); }
          65% { box-shadow: 0 0 0 5px color-mix(in srgb, ${ERROR} 0%, transparent); }
          100% { box-shadow: 0 0 0 0 transparent; }
        }
        .ns-punch-settle { animation: ns-punch-settle 240ms ${EASE}; }
        @keyframes ns-punch-settle {
          from { transform: translateY(30%); opacity: 0; }
          to { transform: translateY(0); opacity: 1; }
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-punch-strike { transition: none; }
          .ns-punch-pulse { animation: none; }
          .ns-punch-settle { animation: none; }
        }
      `}</style>

      <div aria-live="polite" className="sr-only">
        {liveMessage}
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateRows: showPanel ? "1fr" : "0fr",
          transition: reducedRef.current
            ? "none"
            : `grid-template-rows ${PANEL_COLLAPSE_MS}ms ${EASE}`,
        }}
      >
        <div className="overflow-hidden">
          <div
            ref={summaryRef}
            role="alert"
            tabIndex={-1}
            data-punch-summary
            className="sticky top-2 z-10 mb-4 rounded-md border border-border bg-background p-3 font-mono outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
          >
            <div className="mb-2 flex items-center justify-between gap-3">
              <h2 className="text-[11px] uppercase tracking-wide text-foreground">
                {title} — {orderedIds.length ? "unresolved" : "clear"}
              </h2>
              <span className="relative inline-flex h-4 min-w-[2ch] items-center justify-end overflow-hidden text-[11px] tabular-nums text-ns-muted">
                <span key={remaining} className={reducedRef.current ? "" : "ns-punch-settle"}>
                  {remaining} open
                </span>
              </span>
            </div>
            <ol className="flex flex-col gap-0.5">
              {orderedIds.map((id) => {
                const field = fieldsById.get(id)!;
                const isResolving = resolving.has(id);
                const isCollapsing = collapsing.has(id);
                return (
                  <li
                    key={id}
                    style={{
                      display: "grid",
                      gridTemplateRows: isCollapsing ? "0fr" : "1fr",
                      opacity: isCollapsing ? 0 : 1,
                      transition: reducedRef.current
                        ? "none"
                        : `grid-template-rows ${ROW_COLLAPSE_MS}ms ${EASE}, opacity ${ROW_COLLAPSE_MS}ms ease`,
                    }}
                  >
                    <div className="overflow-hidden">
                      <a
                        ref={(el) => {
                          itemRefs.current[id] = el;
                        }}
                        href={`#${id}`}
                        data-punch-item
                        onClick={(e) => {
                          e.preventDefault();
                          selectItem(id);
                        }}
                        className="flex items-baseline gap-2 rounded-sm px-2 py-1.5 text-sm text-foreground outline-none transition-colors hover:bg-border/40 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-1 focus-visible:ring-offset-background"
                      >
                        <span className="shrink-0 text-ns-muted tabular-nums">
                          {numberMap[id]}.
                        </span>
                        <span className="relative inline-block">
                          {field.label}
                          <span aria-hidden data-on={isResolving} className="ns-punch-strike" />
                        </span>
                      </a>
                    </div>
                  </li>
                );
              })}
            </ol>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} noValidate className="flex flex-col gap-4">
        {fields.map((field) => {
          const errId = `${field.id}-error`;
          const hasError = field.id in errors;
          const inputClassName =
            "w-full rounded-sm border bg-background px-3 py-2 text-sm text-foreground outline-none transition-colors placeholder:text-ns-muted focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface";
          const inputStyle = hasError ? { borderColor: ERROR } : undefined;
          return (
            <div key={field.id} className="flex flex-col gap-1.5">
              <label
                htmlFor={field.id}
                className="font-mono text-[11px] uppercase tracking-wide text-ns-muted"
              >
                {field.label}
              </label>
              <div
                ref={(el) => {
                  fieldWrapRefs.current[field.id] = el;
                }}
                className={`rounded-sm ${pulseId === field.id ? "ns-punch-pulse" : ""}`}
                onAnimationEnd={() => setPulseId((cur) => (cur === field.id ? null : cur))}
              >
                {field.type === "textarea" ? (
                  <textarea
                    id={field.id}
                    ref={(el) => {
                      inputRefs.current[field.id] = el;
                    }}
                    rows={3}
                    value={values[field.id] ?? ""}
                    placeholder={field.placeholder}
                    onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
                      handleChange(field.id, e.target.value)
                    }
                    aria-invalid={hasError || undefined}
                    aria-describedby={hasError ? errId : undefined}
                    className={inputClassName}
                    style={inputStyle}
                  />
                ) : (
                  <input
                    id={field.id}
                    ref={(el) => {
                      inputRefs.current[field.id] = el;
                    }}
                    type={field.type ?? "text"}
                    value={values[field.id] ?? ""}
                    placeholder={field.placeholder}
                    onChange={(e: ChangeEvent<HTMLInputElement>) =>
                      handleChange(field.id, e.target.value)
                    }
                    aria-invalid={hasError || undefined}
                    aria-describedby={hasError ? errId : undefined}
                    className={inputClassName}
                    style={inputStyle}
                  />
                )}
              </div>
              {hasError ? (
                <p id={errId} className="text-xs" style={{ color: ERROR }}>
                  {errors[field.id]}
                </p>
              ) : null}
            </div>
          );
        })}

        <div className="mt-1 flex items-center gap-3">
          <button
            type="submit"
            data-punch-submit
            className="inline-flex items-center justify-center rounded-md bg-ns-accent px-4 py-2 text-sm font-medium text-white outline-none transition-colors hover:bg-ns-accent-hover focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
          >
            {submitLabel}
          </button>
          {!showPanel && statusText ? (
            <span className="font-mono text-[11px] text-ns-muted">{statusText}</span>
          ) : null}
        </div>
      </form>

      <svg
        aria-hidden
        focusable="false"
        className="pointer-events-none absolute inset-0 z-20 overflow-visible"
        width="100%"
        height="100%"
      >
        {leader ? (
          <path
            d={`M ${leader.x1} ${leader.y1} L ${leader.x2} ${leader.y2}`}
            pathLength={1}
            fill="none"
            stroke="var(--foreground)"
            strokeWidth={1.25}
            strokeDasharray={1}
            style={{
              strokeDashoffset: leader.drawn ? 0 : 1,
              opacity: leader.fading ? 0 : 0.85,
              transition: reducedRef.current
                ? "none"
                : `stroke-dashoffset ${LEADER_DRAW_MS}ms ${EASE}, opacity ${LEADER_FADE_MS}ms ease`,
            }}
          />
        ) : null}
      </svg>
    </div>
  );
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
} from "react";

// ---------------------------------------------------------------------------
// LitmusWick — inline per-field validation where the field's bottom border
// behaves like litmus paper. A validator either resolves synchronously
// ("definitely wrong", fast decisive soak) or returns a Promise ("still
// checking", slow tentative soak that pulses while pending). Either way the
// error tint doesn't flash on as a flat colored border — it diffuses in from
// the exact x-position of the character that broke the pattern (measured via
// an off-screen mirror span) and, once fixed, wicks back out and converges
// on that same point. Two registered custom properties (--validation-inline-wick-left/
// -right, percentages) drive the stop positions of the wick div's own
// mask-image, so a CSS transition on those properties genuinely animates the
// diffusion front with real easing rather than a border-color crossfade —
// unregistered custom properties can't be transitioned at all, which is
// exactly why @property is load-bearing here, not decorative.
//
// The wick is pure decoration (aria-hidden): the real, assistive-tech-facing
// surface is a plain native <input> with aria-invalid and an aria-describedby
// message naming the position ("Character 4: space not allowed"), living in
// one aria-live=polite paragraph that also carries async "still checking" /
// resolution announcements. Keyboard flow is an untouched plain input — no
// key interception anywhere.
//
// Deliberately unlike approval-inline-diff: this is per-field and positional (the tint
// originates under the offending character and the field stays live/editable
// the whole time), not a form-level approve/deny gate that collapses once
// and never reopens.
// ---------------------------------------------------------------------------

export type LitmusOutcome =
  | { valid: true }
  | { valid: false; index: number; reason: string };

export type LitmusStatus = "idle" | "checking" | "valid" | "invalid";

export interface LitmusWickProps {
  /** field label, rendered above the input and bound to it via htmlFor */
  label: string;
  /** name for the underlying `<input>`, for native form submission */
  name?: string;
  /** id for the underlying `<input>`. Auto-generated when omitted. */
  id?: string;
  /** placeholder text for the field */
  placeholder?: string;
  /** uncontrolled initial value */
  defaultValue?: string;
  /** controlled value; omit for uncontrolled */
  value?: string;
  /** called on every keystroke with the raw input value */
  onValueChange?: (value: string) => void;
  /**
   * Return synchronously for an instantly-known rule ("definitely wrong" —
   * fast, decisive diffusion) or return a Promise for anything that has to
   * ask elsewhere first (uniqueness, server-side rules — "still checking",
   * slower, tentative, pulsing diffusion until it settles).
   */
  validate?: (value: string) => LitmusOutcome | Promise<LitmusOutcome>;
  /** ms after the last keystroke before validate runs. Default 260. */
  debounceMs?: number;
  /** marks the underlying `<input>` as `required` for native form validation */
  required?: boolean;
  /** blocks the underlying `<input>` */
  disabled?: boolean;
  /** passed straight through to the underlying `<input autoComplete>` */
  autoComplete?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// ease-out-expo-shaped — same curve approval-inline-diff's collapse and truncation-taper-fade's
// spring both use, kept consistent across the registry rather than inventing
// a new feel for the same "settle" grammar.
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const CHECK_HALF_SPAN = 16; // % either side of origin while "still checking"

function isPromiseLike(v: unknown): v is Promise<LitmusOutcome> {
  return (
    !!v &&
    (typeof v === "object" || typeof v === "function") &&
    typeof (v as { then?: unknown }).then === "function"
  );
}

// Measures where the offending character sits, in percent of the input's
// own box, using a hidden mirror span that copies the input's real computed
// font — the only reliable way to turn a character index into an x position
// without a canvas.
function measureOriginPercent(
  input: HTMLInputElement,
  mirror: HTMLSpanElement,
  text: string,
  index: number
): number {
  const cs = getComputedStyle(input);
  mirror.style.font = cs.font;
  mirror.style.letterSpacing = cs.letterSpacing;
  const clamped = Math.max(0, Math.min(index, text.length));

  mirror.textContent = text.slice(0, clamped);
  const prefixWidth = mirror.offsetWidth;

  mirror.textContent = text.slice(0, clamped) + (text[clamped] ?? " ");
  const throughWidth = mirror.offsetWidth;
  const charWidth = Math.max(1, throughWidth - prefixWidth);

  const paddingLeft = parseFloat(cs.paddingLeft) || 0;
  const total = input.clientWidth || 1;
  const centerPx = paddingLeft + prefixWidth + charWidth / 2;
  return Math.max(0, Math.min(100, (centerPx / total) * 100));
}

export function LitmusWick({
  label,
  name,
  id,
  placeholder,
  defaultValue = "",
  value,
  onValueChange,
  validate,
  debounceMs = 260,
  required,
  disabled,
  autoComplete,
  className = "",
}: LitmusWickProps) {
  const uid = useId();
  const inputId = id ?? `litmus-${uid}`;
  const msgId = `litmus-msg-${uid}`;

  const inputRef = useRef<HTMLInputElement>(null);
  const mirrorRef = useRef<HTMLSpanElement>(null);
  const requestIdRef = useRef(0);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const isControlled = value !== undefined;
  const [inner, setInner] = useState(defaultValue);
  const current = isControlled ? (value as string) : inner;

  const [status, setStatus] = useState<LitmusStatus>("idle");
  const [message, setMessage] = useState("");
  const [origin, setOrigin] = useState(50);

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  function settle(
    id: number,
    text: string,
    outcome: LitmusOutcome,
    wasAsync: boolean
  ) {
    // A newer keystroke already superseded this in-flight check — a stale
    // async result must never overwrite what the user is looking at now.
    if (id !== requestIdRef.current) return;
    if (outcome.valid) {
      setStatus("valid");
      // Only the async path gets an explicit "it's fine" announcement —
      // that's the one case where the user was genuinely waiting on a
      // result. A sync rule quietly clearing on every valid keystroke would
      // just be aria-live noise while someone types normally.
      setMessage(wasAsync ? "Looks good." : "");
      return;
    }
    const input = inputRef.current;
    const mirror = mirrorRef.current;
    if (input && mirror) {
      setOrigin(measureOriginPercent(input, mirror, text, outcome.index));
    }
    setStatus("invalid");
    setMessage(`Character ${outcome.index + 1}: ${outcome.reason}`);
  }

  function runValidate(text: string) {
    const id = ++requestIdRef.current;
    if (!validate) return;
    const result = validate(text);
    if (isPromiseLike(result)) {
      // Origin while pending: the end of what's currently typed — an async
      // check (uniqueness, server rule) judges the value as a whole, not one
      // character, so the tentative blot grows from the caret's neighborhood
      // rather than claiming to already know where a fault is.
      const input = inputRef.current;
      const mirror = mirrorRef.current;
      if (input && mirror) {
        setOrigin(measureOriginPercent(input, mirror, text, text.length));
      }
      setStatus("checking");
      setMessage("Checking…");
      result.then(
        (o) => settle(id, text, o, true),
        () =>
          settle(
            id,
            text,
            { valid: false, index: Math.max(0, text.length - 1), reason: "check failed" },
            true
          )
      );
    } else {
      settle(id, text, result, false);
    }
  }

  function handleChange(next: string) {
    if (!isControlled) setInner(next);
    onValueChange?.(next);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (next === "") {
      requestIdRef.current++; // invalidates any in-flight async check
      setStatus("idle");
      setMessage("");
      return;
    }
    debounceRef.current = setTimeout(() => runValidate(next), debounceMs);
  }

  const left =
    status === "invalid"
      ? 0
      : status === "checking"
        ? Math.max(0, origin - CHECK_HALF_SPAN)
        : origin;
  const right =
    status === "invalid"
      ? 100
      : status === "checking"
        ? Math.min(100, origin + CHECK_HALF_SPAN)
        : origin;

  const wickStyle = {
    "--validation-inline-wick-left": `${left}%`,
    "--validation-inline-wick-right": `${right}%`,
    backgroundColor: "var(--error, #ea001d)",
  } as CSSProperties;

  const messageStyle: CSSProperties | undefined =
    status === "invalid" ? { color: "var(--error, #ea001d)" } : undefined;

  return (
    <div className={className}>
      <style>{`
        @property --validation-inline-wick-left {
          syntax: '<percentage>';
          inherits: false;
          initial-value: 50%;
        }
        @property --validation-inline-wick-right {
          syntax: '<percentage>';
          inherits: false;
          initial-value: 50%;
        }
        .ns-validation-inline-wick {
          transition:
            --validation-inline-wick-left 480ms ${EASE},
            --validation-inline-wick-right 480ms ${EASE},
            opacity 480ms ease;
          opacity: 1;
          mask-image: linear-gradient(
            to right,
            transparent 0%, transparent var(--validation-inline-wick-left),
            black var(--validation-inline-wick-left), black var(--validation-inline-wick-right),
            transparent var(--validation-inline-wick-right), transparent 100%
          );
          -webkit-mask-image: linear-gradient(
            to right,
            transparent 0%, transparent var(--validation-inline-wick-left),
            black var(--validation-inline-wick-left), black var(--validation-inline-wick-right),
            transparent var(--validation-inline-wick-right), transparent 100%
          );
        }
        .ns-validation-inline-wick[data-phase="checking"] {
          transition-duration: 1100ms;
          opacity: .6;
          animation: ns-litmus-pulse 900ms ease-in-out infinite;
        }
        .ns-validation-inline-wick[data-phase="invalid"] {
          transition-duration: 420ms;
          opacity: 1;
        }
        @keyframes ns-litmus-pulse {
          0%, 100% { opacity: .4; }
          50% { opacity: .72; }
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-validation-inline-wick {
            transition: none;
          }
          .ns-validation-inline-wick[data-phase="checking"] {
            animation: none;
            opacity: .6;
          }
        }
      `}</style>

      <label
        htmlFor={inputId}
        className="block font-mono text-[11px] uppercase tracking-wide text-ns-muted"
      >
        {label}
      </label>

      <div className="group relative mt-1.5">
        <input
          ref={inputRef}
          id={inputId}
          name={name}
          type="text"
          placeholder={placeholder}
          required={required}
          disabled={disabled}
          autoComplete={autoComplete}
          value={current}
          onChange={(e) => handleChange(e.target.value)}
          aria-invalid={status === "invalid"}
          aria-describedby={msgId}
          // `focus-visible:ring-*`, not `focus-visible:outline-*`: the previous
          // pair set `outline-none` (which is `outline-style: none`) and then
          // only a focus WIDTH and COLOR — never a style — so the outline had
          // nothing to draw and this input rendered no visible focus state at
          // all. It went unnoticed because the gate's interaction block only
          // looked for `button, a, [role=button]`, and this component exposes
          // neither, so focus was never checked here. Ring is what the rest of
          // the codebase uses and it composes with `outline-none`.
          className="w-full bg-transparent px-0 py-2 text-sm text-foreground outline-none placeholder:text-ns-muted disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-ns-accent"
        />

        {/* baseline border — the field's resting bottom edge */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-x-0 bottom-0 h-[2px] bg-border transition-colors group-hover:bg-foreground/25"
        />

        {/* the wick — decorative only, masked to the diffused span */}
        <div
          aria-hidden
          data-phase={status}
          className="ns-validation-inline-wick pointer-events-none absolute inset-x-0 bottom-0 h-[2px]"
          style={wickStyle}
        />

        {/* off-screen mirror: measures the x-position of a given character
            index against the input's real computed font. Never read by AT
            (empty at rest, visibility hidden, not part of layout flow). */}
        <span
          ref={mirrorRef}
          aria-hidden
          className="pointer-events-none absolute left-0 top-0 -z-10 whitespace-pre"
          style={{ visibility: "hidden" }}
        />
      </div>

      <p
        id={msgId}
        aria-live="polite"
        className="mt-1.5 min-h-[1em] font-mono text-xs text-ns-muted"
        style={messageStyle}
      >
        {message}
      </p>
    </div>
  );
}

"use client";

import {
  useCallback,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type CSSProperties,
} from "react";

// ---------------------------------------------------------------------------
// VellumScrape — version scrubbing as palimpsest. A vertical rail (a native
// input[type=range]) carries a scrape depth `d` across a version history.
// The document itself is a sequence of "runs" — some plain, some carrying a
// single prior layer (a ghost: the text a later save wrote over, and the
// initial of whoever wrote over it). Dragging the rail back past a run's
// `revealedAt` threshold reveals that run's ghost exactly where it lived in
// the paragraph — real DOM text, never an image or a strikethrough overlay,
// so the revealed past stays selectable and readable.
//
// MECHANISM: every run-with-a-ghost carries a static per-run custom property
// `--rd` (its revealedAt threshold). The document root carries the one
// value that actually changes on drag, `--scrape-depth`. Each run computes
// its own reveal fraction from those two in pure CSS:
//
//   --show: clamp(0, calc(var(--scrape-depth) - var(--rd) + 1), 1)
//
// which is always exactly 0 or exactly 1 for any integer depth vs. any
// integer threshold — a clean step, no JS per-run bookkeeping. Setting the
// single `--scrape-depth` var on the doc root is what "a hundred runs move
// as a single surface" means literally: one style write, and every run's
// `opacity`/`color`/`filter` (ordinary animatable CSS properties, each with
// `transition: … 420ms` declared on the rule, not on the custom property)
// picks up the step and eases across it. The current text crossfades toward
// `--ns-muted` at 35% opacity; the ghost fades in at reduced weight with a
// 0.5px blur that eases in alongside it.
//
// A run that has never been overwritten has no ghost and no `--rd` — it is
// a plain span, untouched by any of this.
//
// RESTORE: a per-run button (never a descendant of the faded ghost element,
// so it never inherits its opacity/blur) opens an inline confirm strip.
// Confirming sets that run's `restored` flag, which a `data-restored`
// override on the shared run wrapper uses to permanently pin the ghost to
// full `--foreground` ink (no blur, no muted crossfade) and hide the now-
// superseded current text, animating over 500ms ease-out-expo — the "one
// wet stroke" re-inking. The confirm trigger is never removed from the DOM
// (only the confirm strip beside it toggles), and opening it is idempotent
// (`setConfirmingId(id)`, never a toggle) — a control that's already open
// stays open if clicked again, so a verifier's press pass landing on it
// before the gate check can never leave the gate looking at a closed state.
//
// A11Y: the rail is a native input[type=range] (min 0, max versions.length-1)
// with an aria-valuetext naming the version, its author and when it was
// saved — standard slider semantics, arrow keys/Home/End work for free. A
// visible + aria-live=polite summary line separately announces what the
// current depth revealed ("Showing version 4 of 9: 2 paragraphs differ"),
// independent of whether the slider itself has focus. Reduced motion is a
// pure CSS switch: every transition this component declares is zeroed under
// prefers-reduced-motion, so layers swap instantly with no JS branching
// needed anywhere in the drag or reveal path.
// ---------------------------------------------------------------------------

export interface VellumScrapeVersion {
  id: string;
  /** full name, used in the rail's aria-valuetext */
  author: string;
  /** short initial shown on scraped-region badges, e.g. "D" */
  initial: string;
  /** human timestamp, e.g. "Tue 14:02" */
  savedAt: string;
}

export interface VellumScrapeRun {
  id: string;
  /** index into the rendered paragraph list this run belongs to */
  paragraph: number;
  /** text visible at any depth below `revealedAt` (or always, if no ghost) */
  current: string;
  /** the text `current` overwrote — omit for a run with no history */
  ghost?: string;
  /** rail depth at and beyond which the ghost is revealed. Required with `ghost`. */
  revealedAt?: number;
  /** initial of the author who wrote `current` over `ghost` — required with `ghost` */
  overwrittenBy?: string;
}

export interface VellumScrapeProps {
  /** versions, NEWEST FIRST — index 0 is the current save, depth 0 on the rail */
  versions?: VellumScrapeVersion[];
  /** the document, as an ordered flat list of runs */
  runs?: VellumScrapeRun[];
  /** controlled scrape depth (index into `versions`) */
  depth?: number;
  /** initial scrape depth when uncontrolled. Default 0. */
  defaultDepth?: number;
  /** fires whenever the rail commits a new depth */
  onDepthChange?: (depth: number) => void;
  /** fires when a run's ghost is re-inked as the run's true content */
  onRestore?: (runId: string) => void;
  /** accessible name for the rail. Default "Scrape depth". */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const EXPO_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";

function groupByParagraph(runs: VellumScrapeRun[]): VellumScrapeRun[][] {
  const map = new Map<number, VellumScrapeRun[]>();
  for (const run of runs) {
    const list = map.get(run.paragraph) ?? [];
    list.push(run);
    map.set(run.paragraph, list);
  }
  return Array.from(map.keys())
    .sort((a, b) => a - b)
    .map((k) => map.get(k) as VellumScrapeRun[]);
}

export function VellumScrape({
  versions = DEFAULT_VERSIONS,
  runs = DEFAULT_RUNS,
  depth: controlledDepth,
  defaultDepth = 0,
  onDepthChange,
  onRestore,
  label = "Scrape depth",
  className = "",
}: VellumScrapeProps) {
  const [internalDepth, setInternalDepth] = useState(defaultDepth);
  const depth = controlledDepth ?? internalDepth;

  const [confirmingId, setConfirmingId] = useState<string | null>(null);
  const [restoredIds, setRestoredIds] = useState<ReadonlySet<string>>(new Set());
  const [announcement, setAnnouncement] = useState("");

  const railRef = useRef<HTMLInputElement | null>(null);

  const paragraphs = useMemo(() => groupByParagraph(runs), [runs]);
  const maxDepth = Math.max(0, versions.length - 1);
  const version = versions[depth] ?? versions[versions.length - 1];
  const versionNumber = versions.length - depth;

  const valueText = version
    ? `Version ${versionNumber} of ${versions.length}, saved by ${version.author}, ${version.savedAt}`
    : `Version ${versionNumber} of ${versions.length}`;

  const commitDepth = useCallback(
    (next: number) => {
      const clamped = Math.min(maxDepth, Math.max(0, next));
      onDepthChange?.(clamped);
      if (controlledDepth === undefined) setInternalDepth(clamped);

      const revealedParagraphs = new Set<number>();
      for (const run of runs) {
        if (run.revealedAt !== undefined && clamped >= run.revealedAt) {
          revealedParagraphs.add(run.paragraph);
        }
      }
      const count = revealedParagraphs.size;
      const v = versions[clamped] ?? versions[versions.length - 1];
      setAnnouncement(
        `Showing version ${versions.length - clamped} of ${versions.length}` +
          (v ? `, saved by ${v.author}` : "") +
          `: ${count} paragraph${count === 1 ? "" : "s"} differ.`
      );
    },
    [maxDepth, onDepthChange, controlledDepth, runs, versions]
  );

  const onRailInput = (e: ChangeEvent<HTMLInputElement>) => {
    commitDepth(e.target.valueAsNumber);
  };

  const openConfirm = (runId: string) => setConfirmingId(runId);
  const cancelConfirm = () => setConfirmingId(null);

  const confirmRestore = (runId: string) => {
    setRestoredIds((prev) => {
      const next = new Set(prev);
      next.add(runId);
      return next;
    });
    setConfirmingId(null);
    onRestore?.(runId);
  };

  return (
    <div className={`flex items-stretch gap-5 ${className}`}>
      <style>{CSS}</style>

      <div className="ns-vellum-rail relative w-8 shrink-0" data-vellum-rail="">
        <div className="ns-vellum-ticks pointer-events-none absolute inset-y-1 left-1/2 flex -translate-x-1/2 flex-col justify-between">
          {versions.map((v, i) => (
            <span key={v.id} className="ns-vellum-tick" data-crossed={i <= depth || undefined} />
          ))}
        </div>
        <input
          ref={railRef}
          type="range"
          min={0}
          max={maxDepth}
          step={1}
          value={depth}
          onChange={onRailInput}
          aria-label={label}
          aria-valuetext={valueText}
          className="ns-vellum-range"
        />
      </div>

      <div className="min-w-0 flex-1">
        <p aria-live="polite" className="mb-3 font-mono text-[11px] tabular-nums text-ns-muted">
          {announcement || `Showing version ${versionNumber} of ${versions.length}.`}
        </p>

        <div
          className="ns-vellum-doc space-y-4 text-sm leading-relaxed text-foreground"
          style={{ "--scrape-depth": depth } as CSSProperties}
        >
          {paragraphs.map((paraRuns, pIdx) => (
            <p key={pIdx}>
              {paraRuns.map((run) => {
                if (!run.ghost || run.revealedAt === undefined) {
                  return <span key={run.id}>{run.current}</span>;
                }

                const restored = restoredIds.has(run.id);
                const revealed = restored || depth >= run.revealedAt;

                return (
                  <span
                    key={run.id}
                    className="ns-vellum-run"
                    data-restored={restored || undefined}
                    style={{ "--rd": run.revealedAt } as CSSProperties}
                  >
                    <span className="ns-vellum-run-current">{run.current}</span>
                    {revealed && (
                      <span className="ns-vellum-ghost-wrap">
                        <span className="ns-vellum-run-fade">
                          <span className="ns-vellum-badge" aria-hidden="true">
                            {run.overwrittenBy}
                          </span>
                          <span>{run.ghost}</span>
                        </span>
                        {!restored &&
                          (confirmingId === run.id ? (
                            <span
                              className="ns-vellum-confirm"
                              role="group"
                              aria-label={`Confirm restoring the text ${run.overwrittenBy} overwrote here`}
                            >
                              <button
                                type="button"
                                data-restore-confirm=""
                                onClick={() => confirmRestore(run.id)}
                                className="ns-vellum-btn ns-vellum-btn-accent"
                              >
                                Restore
                              </button>
                              <button
                                type="button"
                                onClick={cancelConfirm}
                                className="ns-vellum-btn"
                              >
                                Cancel
                              </button>
                            </span>
                          ) : (
                            <button
                              type="button"
                              data-restore-trigger=""
                              aria-expanded={confirmingId === run.id}
                              aria-label={`Restore the text ${run.overwrittenBy} overwrote here`}
                              onClick={() => openConfirm(run.id)}
                              className="ns-vellum-btn"
                            >
                              Restore
                            </button>
                          ))}
                      </span>
                    )}
                  </span>
                );
              })}
            </p>
          ))}
        </div>
      </div>
    </div>
  );
}

