/** Screen apertures, coarsest first. The last deck is the pan: nothing leaves it. */
const DECKS = ["2.00 mm", "1.00 mm", "500 µm", "250 µm", "pan"] as const;
const NDECK = DECKS.length;
/**
 * Share of the stack height each deck's band gets. Coarse decks carry big type;
 * the pan gets the deepest bed because everything a query rejects ends up in it.
 */
const BAND_W = [0.32, 0.16, 0.13, 0.13, 0.26];
/** Height reserved under each mesh for its aperture label. */
const LABEL_H = 20;
/** Spacing of the drawn mesh openings, px — the aperture, made visible. */
const MESH_GAP = [30, 20, 13, 8];
/** Type scale of a grain sitting on deck k. */
const DECK_SCALE = [1.85, 1.12, 0.84, 0.63, 0.46];
/** Ink strength of a grain on deck k. */
const DECK_INK = [1, 0.74, 0.56, 0.42, 0.32];

// Slow gravity on purpose: at true scale a grain crosses a deck in 90 ms and the
// separation is over before it can be read. 1500 px/s^2 keeps a fall legible.
const G = 1500; // px/s^2
const SHAKE_HZ = 3.05;
const SHAKE_AMP = 10; // px, at unit energy
const IDLE_ENERGY = 0.34;

/** Deterministic per-item grain size, used when there is no query to sort by. */
function grainOf(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 8) % 1000) / 1000;
}

/**
 * Subsequence match with contiguity, word-boundary and prefix bonuses.
 * Returns 0 for no match, otherwise a 0..1 score that becomes a grain size.
 */
function score(label: string, meta: string, q: string) {
  if (!q) return -1;
  const hay = (label + " " + meta).toLowerCase();
  const needle = q.toLowerCase().replace(/\s+/g, "");
  if (!needle) return -1;
  let hi = 0;
  let hits = 0;
  let run = 0;
  let best = 0;
  let boundary = 0;
  for (let ni = 0; ni < needle.length; ni++) {
    const c = needle[ni];
    const found = hay.indexOf(c, hi);
    if (found === -1) return 0;
    if (found === hi && ni > 0) run++;
    else run = 1;
    best = Math.max(best, run);
    if (found === 0 || hay[found - 1] === " " || hay[found - 1] === "/") boundary++;
    hits++;
    hi = found + 1;
  }
  const density = hits / Math.max(1, hi);
  const contiguity = best / needle.length;
  const bonus = boundary / needle.length;
  const s = 0.16 + contiguity * 0.52 + bonus * 0.2 + density * 0.12;
  return Math.min(1, s);
}

/** Grain size -> which screen it can no longer pass. */
function deckFor(s: number) {
  // Below the finest aperture nothing is retained: it goes to the pan. A real
  // match never scores under 0.16, so this only ever catches fine natural grain.
  if (s < 0.12) return NDECK - 1;
  if (s >= 0.72) return 0;
  if (s >= 0.56) return 1;
  if (s >= 0.42) return 2;
  return 3;
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const on = () => setReduced(mq.matches);
    on();
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);
  return reduced;
}

type Grain = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  tx: number;
  ty: number;
  phase: number;
  air: boolean;
  /** Seconds still to be worked across the mesh before this grain can pass. */
  wait: number;
  /** The deck it was last flowed onto, so a change of screen can be detected. */
  deck: number;
  /** Height of this grain above its screen — the bed it sits in. */
  bed: number;
};

type Fine = { x: number; y: number; vy: number; ty: number; ph: number; k: number; deck: number; bed: number };

/**
 * A full-screen search overlay built as a gyratory sieve shaker. The corpus is a
 * charge of grain lying on a stack of five screens; the query is the grain
 * SIZE. Every keystroke re-sizes each grain, so grains that no longer pass their
 * screen ride up on the throw and grains that got smaller drop through the mesh,
 * deck by deck, until the strong matches are the only thing left on the coarse
 * top screen and everything else has worked its way into the pan.
 *
 * Nothing restarts on a keystroke: the deck keeps shaking, targets change, and
 * grains migrate from wherever they currently are. The result text is real DOM
 * type throughout — only its position, scale and ink are driven by the sim. The
 * canvas behind it carries the fines, which follow the same sort.
 */
export function SieveThrow({
  items = DEFAULT_ITEMS,
  triggerLabel = "Search",
  label = "Search the charge",
  fieldLabel = "Query — sets the grain size",
  placeholder = "Type to size the charge",
  defaultOpen = false,
  onSelect,
  children,
  className,
}: SieveThrowProps) {
  const reduced = usePrefersReducedMotion();
  const uid = React.useId();
  const listId = `${uid}-deck`;
  const inputId = `${uid}-q`;

  const [open, setOpen] = React.useState(defaultOpen);
  const [query, setQuery] = React.useState("");
  const [active, setActive] = React.useState(0);

  // Opened by the user (rather than mounted open for display) is what turns the
  // overlay into a real modal: autofocus and the focus trap only engage then, so
  // a page that renders the deck at rest does not steal focus from the document.
  const userOpened = React.useRef(false);

  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const overlayRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const stackRef = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const n = items.length;

  // Grain size per item for the current query. -1 means "no query": fall back to
  // the item's own natural grain so the resting deck is a spread charge, not a
  // single heap on the top screen.
  const sizes = React.useMemo(
    () =>
      items.map((it) => {
        const s = score(it.label, it.meta ?? "", query);
        return s < 0 ? grainOf(it.label) * 0.98 : s;
      }),
    [items, query],
  );
  const matched = query.trim().length > 0;
  const decks = React.useMemo(() => sizes.map(deckFor), [sizes]);

  /** Selectable results, ranked. With no query every grain is still a result. */
  const results = React.useMemo(() => {
    const idx = items.map((_, i) => i).filter((i) => (matched ? sizes[i] > 0 : true));
    idx.sort((a, b) => sizes[b] - sizes[a] || a - b);
    return idx;
  }, [items, sizes, matched]);

  const retained = React.useMemo(() => decks.filter((d) => d === 0).length, [decks]);
  const rejected = matched ? n - results.length : 0;

  React.useEffect(() => {
    setActive(0);
  }, [query]);

  // ---- simulation state -------------------------------------------------
  const grains = React.useRef<Grain[]>([]);
  if (grains.current.length !== n) {
    grains.current = Array.from({ length: n }, (_, i) => ({
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      tx: 0,
      ty: 0,
      phase: (grainOf(items[i]?.label ?? String(i)) * Math.PI * 2) as number,
      air: false,
      wait: 0,
      deck: -1,
      bed: 0,
    }));
  }
  const fines = React.useRef<Fine[]>([]);
  const widths = React.useRef<number[]>([]);
  const box = React.useRef({ w: 0, h: 0 });
  /** Grain size actually in use on each screen — see the fit in `layout`. */
  const scaleOf = React.useRef<number[]>([...DECK_SCALE]);
  /**
   * Where the screens currently sit, and where the current load says they
   * should. The stack is sprung: a screen carrying material opens up and its
   * neighbours close, so there is never a band of empty deck for its own sake.
   */
  const fracs = React.useRef<number[]>([...BAND_W]);
  const fracTarget = React.useRef<number[]>([...BAND_W]);
  const lineRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const energy = React.useRef(IDLE_ENERGY);
  const clock = React.useRef(0);
  const raf = React.useRef(0);
  const lastT = React.useRef(0);
  const running = React.useRef(false);
  const visible = React.useRef(true);
  // Seeded from the cascade at mount; never a literal on screen (the first paint
  // happens inside the token effect below, which runs before any frame).
  const ink = React.useRef({ muted: "transparent", border: "transparent" });
  const placed = React.useRef(false);

  /** Bottom edge (the screen surface) of deck k, in stack pixels. */
  const deckLine = React.useCallback((k: number) => {
    const h = box.current.h;
    let acc = 0;
    for (let i = 0; i <= k; i++) acc += fracs.current[i];
    // The pan is the floor of the stack, so its share ends exactly at the
    // bottom edge and its aperture label — which prints under every mesh —
    // would fall off screen. Lift that last line clear by the label's height.
    return k === NDECK - 1 ? Math.min(acc * h, h - LABEL_H) : acc * h;
  }, []);

  /**
   * Flow the grains along each screen: left to right from the feed edge,
   * piling upward off the mesh when a line is full. Layout only runs when the
   * charge is re-sized or the stack is resized — never per frame.
   */
  const layout = React.useCallback(() => {
    const w = box.current.w;
    if (!w) return;
    const pad = Math.min(48, w * 0.045);
    const order = items.map((_, i) => i);
    order.sort((a, b) => decks[a] - decks[b] || sizes[b] - sizes[a] || a - b);

    // Flow one screen at its trial grain size and report the bed it produces.
    const flow = (deck: number[], sc: number) => {
      let x = pad;
      let line = 0;
      const at: { x: number; line: number }[] = [];
      for (const i of deck) {
        const gw = (widths.current[i] || 140) * sc;
        if (x + gw > w - pad && x > pad) {
          x = pad;
          line += 1;
        }
        at.push({ x, line });
        x += gw + 10 + 12 * sc;
      }
      return { at, lines: line + 1 };
    };

    // How much deck each screen is entitled to: half its standing share, half
    // the share of the charge it is actually carrying. A cleared screen closes
    // up, a loaded one opens, and the stack has no dead freeboard in any state.
    const load = Array.from({ length: NDECK }, (_, k) => decks.filter((d) => d === k).length);
    const total = Math.max(1, load.reduce((a, b) => a + b, 0));
    // The load term is capped: a pan holding three quarters of the charge should
    // open up, but not swallow the stack and leave the retained screens as slots.
    const raw = load.map((l, k) => Math.max(0.07, 0.5 * BAND_W[k] + 0.5 * Math.min(0.45, l / total)));
    const sum = raw.reduce((a, b) => a + b, 0);
    fracTarget.current = raw.map((r) => r / sum);

    const line = new Array<number>(items.length).fill(0);
    const xs = new Array<number>(items.length).fill(pad);
    for (let k = 0; k < NDECK; k++) {
      const deck = order.filter((i) => decks[i] === k);
      const band = fracTarget.current[k] * box.current.h - LABEL_H;
      // A screen's grain is set as large as its own bed allows: the top screen
      // holding the whole charge is a fine, tightly packed bed, and as a query
      // sheds material off it the survivors coarsen into headline type. The size
      // is chosen so the pile always fits between the mesh and the label above.
      let sc = DECK_SCALE[k];
      let f = flow(deck, sc);
      for (let guard = 0; guard < 10 && f.lines * (34 * sc + 8) > band && sc > 0.3; guard++) {
        sc = Math.max(0.3, sc * 0.86);
        f = flow(deck, sc);
      }
      scaleOf.current[k] = sc;
      deck.forEach((i, j) => {
        xs[i] = f.at[j].x;
        line[i] = f.at[j].line;
      });
    }
    const pitch = scaleOf.current.map((sc) => 34 * sc + 8);

    for (const i of order) {
      const k = decks[i];
      const sc = scaleOf.current[k];
      const g = grains.current[i];
      if (g.deck !== k) {
        // A charge does not all pass at once: each grain has to be worked across
        // the mesh before it finds a hole, and how long that takes is what makes
        // the separation a cascade rather than a cut. Deeper drops start sooner
        // — the undersize is what a screen sheds first.
        const drop = Math.abs(k - (g.deck < 0 ? k : g.deck));
        g.wait = 0.04 + (g.phase / (Math.PI * 2)) * 0.5 - Math.min(0.2, drop * 0.05);
        g.deck = k;
      }
      g.tx = xs[i];
      // Grains rest ON the mesh, so their height is held as an offset above it,
      // not an absolute y: when the stack re-springs, the bed rides with it.
      g.bed = 3 + line[i] * pitch[k] + 34 * sc;
    }
    // Fines belong to a grain each, so the dust migrates with the sort and the
    // bed on a loaded screen is visibly deeper than the bed on a cleared one.
    for (let i = 0; i < fines.current.length; i++) {
      const f = fines.current[i];
      const k = decks[f.k];
      if (k === undefined) continue;
      const depth = Math.min(fracTarget.current[k] * box.current.h * 0.5, 5 + load[k] * 2.4);
      // sqrt bias: dust packs densest against the mesh and thins upward.
      const r = Math.sqrt(((i * 37) % 101) / 101);
      f.deck = k;
      f.bed = 2 + r * depth;
    }
  }, [items, decks, sizes]);

  /** Snap everything to its target. Used for the first paint and reduced motion. */
  const settle = React.useCallback(() => {
    fracs.current = [...fracTarget.current];
    for (const g of grains.current) g.ty = deckLine(Math.max(0, g.deck)) - g.bed;
    for (const f of fines.current) f.ty = deckLine(f.deck) - f.bed;
    for (const g of grains.current) {
      g.x = g.tx;
      g.y = g.ty;
      g.vx = 0;
      g.vy = 0;
      g.air = false;
    }
    for (const f of fines.current) {
      f.y = f.ty;
      f.vy = 0;
    }
  }, [deckLine]);

  const paintGrains = React.useCallback(
    (gx: number, gy: number, e: number) => {
      const t = clock.current;
      // The screens ride the throw with everything on them.
      for (let k = 0; k < NDECK; k++) {
        const el = lineRefs.current[k];
        if (el) el.style.transform = `translate3d(0, ${(deckLine(k) + gy).toFixed(1)}px, 0)`;
      }
      for (let i = 0; i < grains.current.length; i++) {
        const el = chipRefs.current[i];
        if (!el) continue;
        const g = grains.current[i];
        // Grains on a running screen never sit still: each hops on the throw,
        // out of phase with its neighbours.
        const hop = g.air ? 0 : Math.max(0, Math.sin(t * SHAKE_HZ * 2 * Math.PI + g.phase)) * 3.2 * e;
        el.style.transform = `translate3d(${(g.x + gx).toFixed(1)}px, ${(g.y + gy - hop).toFixed(1)}px, 0) scale(${scaleOf.current[decks[i]].toFixed(3)})`;
      }
    },
    [decks, deckLine],
  );

  const drawFines = React.useCallback(
    (gx: number, gy: number) => {
      const cv = canvasRef.current;
      const ctx = cv?.getContext("2d");
      if (!cv || !ctx) return;
      const { w, h } = box.current;
      ctx.clearRect(0, 0, w, h);

      // The screens themselves, drawn to their aperture: a coarse mesh is a few
      // wide openings, the pan is a solid floor. The hairline under each is DOM;
      // this is the weave sitting on it, and it moves with the throw.
      ctx.fillStyle = ink.current.border;
      ctx.globalAlpha = 0.85;
      for (let k = 0; k < NDECK - 1; k++) {
        const y = deckLine(k) + gy;
        const gap = MESH_GAP[k];
        for (let x = ((gx % gap) + gap) % gap; x < w; x += gap) ctx.fillRect(x, y - 3, 1, 3);
      }

      // The fines: dust bound to a grain each, so the dust migrates with the
      // sort. It banks up on a loaded screen and clears off an empty one.
      ctx.fillStyle = ink.current.muted;
      for (const f of fines.current) {
        const g = grains.current[f.k];
        if (!g) continue;
        ctx.globalAlpha = 0.14 + DECK_INK[decks[f.k]] * 0.46;
        const s = 1 + (f.ph % 3) * 0.5;
        ctx.fillRect(f.x + gx, f.y + gy, s, s);
      }
      ctx.globalAlpha = 1;
    },
    [decks, deckLine],
  );

  /**
   * Resolve every bed against where the screens currently are. Beds are stored
   * as a height above the mesh, so a screen that moves carries its material.
   */
  const resolve = React.useCallback(() => {
    for (const g of grains.current) g.ty = deckLine(Math.max(0, g.deck)) - g.bed;
    for (const f of fines.current) f.ty = deckLine(f.deck) - f.bed;
  }, [deckLine]);

  /** One fixed sim substep. Vertical motion is ballistic, horizontal is conveyed. */
  const step = React.useCallback((dt: number) => {
    const t = clock.current;
    const throwPhase = Math.sin(t * SHAKE_HZ * 2 * Math.PI);
    // The stack itself is sprung toward the spacing the current load asks for.
    for (let k = 0; k < NDECK; k++) {
      fracs.current[k] += (fracTarget.current[k] - fracs.current[k]) * Math.min(1, dt * 5);
    }
    resolve();
    for (const g of grains.current) {
      // Conveyed along the screen: a damped pull toward the flow position.
      const k = 62;
      g.vx += (-k * (g.x - g.tx) - 2 * Math.sqrt(k) * g.vx) * dt;
      g.x += g.vx * dt;

      if (g.wait > 0) {
        g.wait -= dt;
        continue;
      }

      const dy = g.ty - g.y;
      if (!g.air) {
        // The threshold is a whole band, not a pixel: a resting grain follows
        // its screen as the stack re-springs, and only a genuine change of deck
        // is enough to put it in the air.
        if (dy > 20) {
          // The grain passed its screen: it is through the mesh and falling.
          g.air = true;
        } else if (dy < -20 && throwPhase > 0.94) {
          // It no longer fits through: the throw kicks it back up a deck, and
          // it only leaves the screen at the top of the stroke, like real grain.
          g.vy = -Math.sqrt(2 * G * Math.abs(dy)) * 1.04;
          g.air = true;
        } else {
          g.y += dy * Math.min(1, 12 * dt);
        }
      }
      if (g.air) {
        g.vy += G * dt;
        g.y += g.vy * dt;
        if (g.y >= g.ty && g.vy > 0) {
          g.y = g.ty;
          if (g.vy > 120) g.vy = -g.vy * 0.24;
          else {
            g.vy = 0;
            g.air = false;
          }
        }
      }
    }
    for (const f of fines.current) {
      const dy = f.ty - f.y;
      if (Math.abs(dy) < 0.6) {
        f.vy = 0;
        f.y = f.ty;
      } else if (dy > 0) {
        f.vy += G * 0.55 * dt;
        f.y += f.vy * dt;
        if (f.y > f.ty) {
          f.y = f.ty;
          f.vy = 0;
        }
      } else {
        if (throwPhase > 0.9 && f.vy === 0) f.vy = -Math.sqrt(2 * G * 0.55 * Math.abs(dy)) * 1.02;
        f.vy += G * 0.55 * dt;
        f.y += f.vy * dt;
        if (f.vy > 0 && f.y >= f.ty) {
          f.y = f.ty;
          f.vy = 0;
        }
      }
    }
  }, [resolve]);

  const frame = React.useCallback(
    (now: number) => {
      if (!running.current) return;
      const dtWall = Math.min(0.05, (now - (lastT.current || now)) / 1000);
      lastT.current = now;
      clock.current += dtWall;
      // Energy decays back to the idle throw between keystrokes.
      energy.current += (IDLE_ENERGY - energy.current) * Math.min(1, dtWall * 2.4);
      let acc = dtWall;
      while (acc > 0) {
        const dt = Math.min(1 / 180, acc);
        acc -= dt;
        step(dt);
      }
      const e = energy.current;
      const t = clock.current;
      // Gyratory throw: the whole deck orbits, so the charge is walked along it.
      const gx = Math.cos(t * SHAKE_HZ * 2 * Math.PI) * SHAKE_AMP * e;
      const gy = Math.sin(t * SHAKE_HZ * 4 * Math.PI) * SHAKE_AMP * 0.34 * e;
      paintGrains(gx, gy, e);
      drawFines(gx, gy);
      raf.current = requestAnimationFrame(frame);
    },
    [step, paintGrains, drawFines],
  );

  const start = React.useCallback(() => {
    if (running.current || reduced) return;
    running.current = true;
    lastT.current = 0;
    raf.current = requestAnimationFrame(frame);
  }, [frame, reduced]);

  const stop = React.useCallback(() => {
    running.current = false;
    if (raf.current) cancelAnimationFrame(raf.current);
    raf.current = 0;
  }, []);

  // Tokens, read from the cascade and re-read whenever the theme flips.
  React.useEffect(() => {
    if (!open) return;
    const read = () => {
      const cs = getComputedStyle(document.documentElement);
      ink.current = {
        muted: cs.getPropertyValue("--ns-muted").trim() || cs.getPropertyValue("--foreground").trim(),
        border: cs.getPropertyValue("--border").trim() || cs.getPropertyValue("--ns-muted").trim(),
      };
    };
    read();
    const mo = new MutationObserver(read);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change", read);
    return () => {
      mo.disconnect();
      mq.removeEventListener("change", read);
    };
  }, [open]);

  // Measure the stack and the grains, size the canvas, seed the fines.
  React.useLayoutEffect(() => {
    if (!open) return;
    const stack = stackRef.current;
    if (!stack) return;
    const measure = () => {
      const r = stack.getBoundingClientRect();
      box.current = { w: r.width, h: r.height };
      const cv = canvasRef.current;
      if (cv) {
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        cv.width = Math.max(1, Math.round(r.width * dpr));
        cv.height = Math.max(1, Math.round(r.height * dpr));
        cv.style.width = `${r.width}px`;
        cv.style.height = `${r.height}px`;
        const ctx = cv.getContext("2d");
        if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
      for (let i = 0; i < n; i++) {
        const el = chipRefs.current[i];
        if (el) widths.current[i] = el.offsetWidth;
      }
      if (fines.current.length !== n * 16) {
        fines.current = Array.from({ length: n * 16 }, (_, i) => ({
          x: 0,
          y: 0,
          vy: 0,
          ty: 0,
          ph: i % 11,
          k: i % n,
          deck: 0,
          bed: 0,
        }));
      }
      const pad = Math.min(48, r.width * 0.045);
      for (let i = 0; i < fines.current.length; i++) {
        const f = fines.current[i];
        f.x = pad + ((i * 61) % 997) / 997 * Math.max(1, r.width - pad * 2);
      }
      layout();
      if (!placed.current) {
        settle();
        placed.current = true;
      }
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(stack);
    return () => ro.disconnect();
  }, [open, n, layout, settle]);

  // Re-flow on every query change. The sim is NOT reset — grains migrate from
  // wherever they are, which is what makes typing a continuous re-sort.
  React.useEffect(() => {
    if (!open) return;
    layout();
    if (reduced) {
      settle();
      paintGrains(0, 0, 0);
      drawFines(0, 0);
    }
  }, [open, layout, reduced, settle, paintGrains, drawFines]);

  // Run the shaker only while the overlay is open, on screen and in a live tab.
  React.useEffect(() => {
    if (!open) return;
    if (reduced) {
      settle();
      paintGrains(0, 0, 0);
      drawFines(0, 0);
      return;
    }
    start();
    const stack = stackRef.current;
    const io = stack
      ? new IntersectionObserver(
          (entries) => {
            visible.current = entries.some((e) => e.isIntersecting);
            if (visible.current && !document.hidden) start();
            else stop();
          },
          { threshold: 0 },
        )
      : null;
    if (stack && io) io.observe(stack);
    const onVis = () => {
      if (document.hidden) stop();
      else if (visible.current) start();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      stop();
      io?.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [open, reduced, start, stop, settle, paintGrains, drawFines]);

  // Escape closes whenever the overlay is open, however it was opened.
  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setOpen(false);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);

  // Focus and the modal trap. Only for an overlay the user opened: an overlay
  // rendered open for display must not seize the page's focus on mount.
  React.useEffect(() => {
    if (!open) return;
    const root = overlayRef.current;
    if (!root) return;
    if (!userOpened.current) return;
    inputRef.current?.focus();

    const focusables = () =>
      Array.from(
        root.querySelectorAll<HTMLElement>(
          'input:not([disabled]), a[href], button:not([disabled]):not([tabindex="-1"]), [tabindex]:not([tabindex="-1"])',
        ),
      ).filter((el) => el.offsetParent !== null || el === document.activeElement);

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setOpen(false);
        return;
      }
      if (e.key !== "Tab") return;
      const f = focusables();
      if (f.length === 0) return;
      const first = f[0];
      const last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    // Tab wrapping alone is not a trap: focus can arrive from outside onto the
    // trigger, which is still in the DOM behind the overlay.
    const onFocusIn = (ev: FocusEvent) => {
      const t = ev.target as Node | null;
      if (t && !root.contains(t)) {
        ev.stopPropagation();
        inputRef.current?.focus();
      }
    };
    root.addEventListener("keydown", onKey);
    document.addEventListener("keydown", onKey);
    document.addEventListener("focusin", onFocusIn);
    return () => {
      root.removeEventListener("keydown", onKey);
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("focusin", onFocusIn);
      triggerRef.current?.focus();
    };
  }, [open]);

  const close = React.useCallback(() => setOpen(false), []);

  const commit = React.useCallback(
    (i: number) => {
      const it = items[i];
      if (!it) return;
      onSelect?.(it);
      setOpen(false);
    },
    [items, onSelect],
  );

  const onInputKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (results.length === 0) return;
      setActive((a) => {
        const d = e.key === "ArrowDown" ? 1 : -1;
        return (a + d + results.length) % results.length;
      });
      return;
    }
    if (e.key === "Home" && results.length) {
      e.preventDefault();
      setActive(0);
      return;
    }
    if (e.key === "End" && results.length) {
      e.preventDefault();
      setActive(results.length - 1);
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      const i = results[active];
      if (i !== undefined) commit(i);
      return;
    }
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    }
  };

  const activeIndex = results[active];

  return (
    <div className={["relative isolate", className].filter(Boolean).join(" ")}>
      {children}

      {open ? (
        <div
          ref={overlayRef}
          role="dialog"
          aria-modal="true"
          aria-label={label}
          className="fixed inset-0 z-40 flex flex-col bg-background"
        >
          {/* Feed head: the query field IS the sizing control. */}
          <div className="shrink-0 border-b border-border px-5 pb-4 pt-5 sm:px-10 sm:pt-8">
            <div className="flex items-baseline justify-between gap-6">
              <label
                htmlFor={inputId}
                className="font-mono text-[10px] uppercase tracking-[0.3em] text-ns-muted sm:text-[11px]"
              >
                {fieldLabel}
              </label>
              <span className="hidden font-mono text-[10px] uppercase tracking-[0.3em] text-ns-muted sm:block sm:text-[11px]">
                gyratory throw / {SHAKE_HZ.toFixed(2)} hz
              </span>
            </div>
            <div className="mt-2 flex items-center gap-4 sm:gap-6">
              <input
                ref={inputRef}
                id={inputId}
                type="text"
                role="combobox"
                aria-expanded="true"
                aria-controls={listId}
                aria-autocomplete="list"
                aria-activedescendant={activeIndex !== undefined ? `${listId}-${activeIndex}` : undefined}
                autoComplete="off"
                spellCheck={false}
                value={query}
                placeholder={placeholder}
                onChange={(ev) => {
                  setQuery(ev.target.value);
                  // Every keystroke is a kick of energy into the deck. The sort
                  // itself is scheduled work; nothing heavy runs here.
                  energy.current = Math.min(1.7, energy.current + 0.85);
                }}
                onKeyDown={onInputKey}
                className="min-w-0 flex-1 border-0 bg-transparent p-0 font-medium text-[clamp(1.6rem,5.2vw,3.4rem)] leading-none tracking-tight text-foreground placeholder:text-ns-muted focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
              />
              <button
                type="button"
                onClick={close}
                className="group shrink-0 rounded-sm border border-border px-3 py-2 font-mono text-[10px] uppercase tracking-[0.24em] text-ns-muted transition-colors duration-150 hover:border-ns-accent hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent sm:px-4 sm:text-[11px]"
              >
                Esc / close
              </button>
            </div>
            <p aria-live="polite" aria-atomic="true" className="sr-only">
              {matched
                ? `${results.length} of ${n} matching, ${retained} retained on the top screen, ${rejected} passed to the pan.`
                : `${n} on the deck, nothing sized yet.`}
            </p>
          </div>

          {/* The deck stack. */}
          <div ref={stackRef} className="relative min-h-0 flex-1 overflow-hidden">
            <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 h-full w-full" />

            {/* Screens. Each hairline is the mesh the grains above it are sitting on. */}
            <div aria-hidden="true" className="absolute inset-0">
              {DECKS.map((ap, k) => (
                <div
                  key={ap}
                  ref={(el) => {
                    lineRefs.current[k] = el;
                  }}
                  className="absolute inset-x-0 top-0"
                  style={{
                    transform: `translate3d(0, ${BAND_W.slice(0, k + 1).reduce((a, b) => a + b, 0) * 100}vh, 0)`,
                  }}
                >
                  <div
                    className="h-px w-full bg-border"
                    style={{ opacity: k === NDECK - 1 ? 1 : 0.4 + (1 - k / NDECK) * 0.6 }}
                  />
                  <div className="flex items-center justify-between px-5 pt-1 font-mono text-[9px] uppercase tracking-[0.3em] text-ns-muted sm:px-10 sm:text-[10px]">
                    <span>
                      {String(k + 1).padStart(2, "0")} / {ap}
                    </span>
                    <span>{decks.filter((d) => d === k).length} on screen</span>
                  </div>
                </div>
              ))}
            </div>

            {/* The charge. Real DOM type; the sim only writes transforms. */}
            <div
              id={listId}
              role="listbox"
              aria-label={`${label} — sieve deck`}
              className="absolute inset-0"
            >
              {items.map((it, i) => {
                const k = decks[i];
                const isActive = i === activeIndex;
                const dead = matched && sizes[i] <= 0;
                return (
                  <button
                    key={it.label}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    id={`${listId}-${i}`}
                    role="option"
                    type="button"
                    tabIndex={-1}
                    aria-selected={isActive}
                    aria-disabled={dead || undefined}
                    onClick={() => !dead && commit(i)}
                    className={[
                      "absolute left-0 top-0 flex origin-top-left items-center gap-3 whitespace-nowrap rounded-sm border px-3 py-2 text-left transition-[color,border-color,background-color] duration-150",
                      isActive
                        ? "border-ns-accent bg-background text-foreground"
                        : "border-transparent bg-transparent text-foreground hover:border-border",
                    ].join(" ")}
                    // No will-change: the grain's scale changes when it changes
                    // deck, and promoting it would rasterize the type once at
                    // the old scale and ship a smeared bitmap of the result.
                    style={{ opacity: isActive ? 1 : DECK_INK[k] }}
                  >
                    {isActive ? (
                      <span aria-hidden="true" className="font-mono text-[11px] text-ns-accent">
                        &rarr;
                      </span>
                    ) : null}
                    <span className="text-[15px] font-medium leading-none tracking-tight">
                      {it.label}
                    </span>
                    {it.meta ? (
                      <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-ns-muted">
                        {it.meta}
                      </span>
                    ) : null}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex shrink-0 items-center justify-between gap-6 border-t border-border px-5 py-3 font-mono text-[10px] uppercase tracking-[0.3em] text-ns-muted sm:px-10 sm:text-[11px]">
            <span>
              {matched ? `${results.length} pass / ${rejected} to pan` : `${n} on deck`}
            </span>
            <span className="hidden sm:block">&uarr;&darr; move &middot; &crarr; open &middot; esc close</span>
          </div>
        </div>
      ) : null}

      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => {
          userOpened.current = true;
          setOpen(true);
        }}
        style={{ visibility: open ? "hidden" : "visible" }}
        className="group fixed right-5 top-5 z-30 inline-flex items-center gap-3 rounded-sm border border-border bg-background/80 px-4 py-2.5 text-sm font-medium text-foreground backdrop-blur transition-colors duration-150 hover:border-ns-accent hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent sm:right-8 sm:top-8"
      >
        <span aria-hidden="true" className="relative flex h-3.5 w-5 flex-col justify-between">
          <span className="h-px w-full bg-current" />
          <span className="h-px w-full bg-current opacity-70" />
          <span className="h-px w-full bg-current opacity-40" />
        </span>
        {triggerLabel}
      </button>
    </div>
  );
}

export default SieveThrow;

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChladniTune — a precision-tuning slider whose readout is a plate of sand.
// A few thousand grains random-walk across a square Canvas 2D plate; how far
// the slider sits from an unstated `target` sets both how hard they jitter
// and how strongly they're pulled onto the nodal lines of a Chladni figure
// sin(n*pi*x)*sin(m*pi*y) - sin(m*pi*x)*sin(n*pi*y) = 0 for a mode (n, m)
// picked deterministically from `target`. Off target the grains churn in a
// formless haze; on target they lock into the crisp symmetric figure and
// hold still. Distance-to-correct is encoded as PATTERN COHERENCE — a
// continuous, directionless "how close" signal, the way you'd tune an
// instrument by ear rather than by reading a number.
//
// MECHANISM: rather than integrating a force field (expensive, and force
// magnitude near a saddle of |f| doesn't actually read as "coherence"), each
// grain proposes a small random step and the step is judged by whether it
// makes |f(x, y)| bigger or smaller — a Metropolis-style accept/reject, the
// standard trick real-time Chladni-sand demos use. A step that improves
// (shrinks) |f| is always taken. A step that worsens it is taken anyway with
// probability normalizedDetune^1.4 — that probability IS the "attraction
// strength = 1 - normalizedDetune" the brief describes, just expressed as a
// rejection rate instead of a force: at detune 0 worse moves are almost
// never accepted, so grains that reach the zero set stay there (locked,
// motionless); at detune 1 they're accepted almost always, so the walk is
// unbiased and grains never accumulate anywhere (pure scatter). Jitter
// magnitude also scales linearly with detune, so besides drifting or holding,
// off-target grains visibly move harder. No dt-scaling: this is a discrete
// per-frame Markov step, not a velocity integration, so running it once per
// rAF tick (not scaled by elapsed time) is the correct thing to do, same as
// any other frame-stepped cellular automaton.
//
// Grain positions live in a plain Float32Array pair, updated in place —
// never React state. Canvas ink (plate = --background, grains = --foreground
// at low alpha) is read via getComputedStyle at mount and re-derived on a
// MutationObserver watching documentElement's class attribute, so a theme
// flip repaints correctly instead of leaving stale colors baked into a
// gradient. The rAF loop pauses via IntersectionObserver while offscreen and
// on document.hidden; it never fully sleeps otherwise, because even a locked
// plate still carries a small residual jitter (real sand vibrates, it
// doesn't teleport to a stop) — that's deliberate, not a missed easing.
//
// A11Y: the slider is a real native <input type="range"> (role=slider, full
// arrow/Home/End/PageUp/PageDown keyboard support for free), aria-valuetext
// reporting both the number and a categorical proximity phrase ("42.1, very
// close to target"). The canvas is aria-hidden; a Geist Mono readout beneath
// the slider duplicates the same value/coherence numbers in text, so the
// sand is never the only channel carrying the signal. A dedicated
// aria-live=polite region announces "On target." exactly on the transition
// into lock (empty otherwise, so it never spams on every drag tick).
// REDUCED MOTION: the whole simulation is replaced by a static, non-canvas
// SVG figure with three fixed point sets (scattered / forming / locked)
// computed once per mode; the live detune/lock state just selects which of
// the three to render — an instant swap, never an animation. Zero deps.
// ---------------------------------------------------------------------------

type Vec3 = readonly [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (!s) return null;
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// canonical asymmetric (n, m) pairs — n === m makes the Chladni expression
// identically zero everywhere (a degenerate, non-figure "target"), so every
// entry here deliberately keeps n !== m.
const CHLADNI_MODES: readonly (readonly [number, number])[] = [
  [2, 1],
  [3, 1],
  [3, 2],
  [4, 1],
  [4, 3],
  [5, 2],
  [5, 3],
  [5, 4],
  [6, 1],
  [6, 5],
];

function hash01(n: number): number {
  const s = Math.sin(n * 12.9898) * 43758.5453;
  return s - Math.floor(s);
}

function modeForTarget(target: number): readonly [number, number] {
  const idx = Math.floor(hash01(target) * CHLADNI_MODES.length) % CHLADNI_MODES.length;
  return CHLADNI_MODES[idx] ?? CHLADNI_MODES[0];
}

function chladni(n: number, m: number, x: number, y: number): number {
  return (
    Math.sin(n * Math.PI * x) * Math.sin(m * Math.PI * y) -
    Math.sin(m * Math.PI * x) * Math.sin(n * Math.PI * y)
  );
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

function proximityWord(detune: number, locked: boolean): string {
  if (locked) return "on target";
  if (detune < 0.15) return "very close to target";
  if (detune < 0.4) return "close to target";
  if (detune < 0.75) return "off target";
  return "far from target";
}

function stateBucket(detune: number, locked: boolean): "locked" | "converging" | "scattered" {
  if (locked) return "locked";
  return detune < 0.55 ? "converging" : "scattered";
}

function useReducedMotionPref(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

const REDUCED_GRID = 44; // sample grid resolution for the static figure
const REDUCED_COUNT = 220; // point count in every static bucket

function computeLockedPoints(n: number, m: number): readonly (readonly [number, number])[] {
  const candidates: { x: number; y: number; a: number }[] = [];
  for (let i = 0; i <= REDUCED_GRID; i++) {
    for (let j = 0; j <= REDUCED_GRID; j++) {
      const x = i / REDUCED_GRID;
      const y = j / REDUCED_GRID;
      candidates.push({ x, y, a: Math.abs(chladni(n, m, x, y)) });
    }
  }
  candidates.sort((p, q) => p.a - q.a);
  return candidates.slice(0, REDUCED_COUNT).map((p) => [p.x, p.y] as const);
}

function computeScatteredPoints(): readonly (readonly [number, number])[] {
  const pts: (readonly [number, number])[] = [];
  for (let i = 0; i < REDUCED_COUNT; i++) {
    pts.push([hash01(i * 12.9898 + 1.7), hash01(i * 78.233 + 4.1)] as const);
  }
  return pts;
}

function computeFormingPoints(
  scattered: readonly (readonly [number, number])[],
  locked: readonly (readonly [number, number])[]
): readonly (readonly [number, number])[] {
  return scattered.map(([sx, sy], i) => {
    const [lx, ly] = locked[i % locked.length] ?? [sx, sy];
    return [sx + (lx - sx) * 0.55, sy + (ly - sy) * 0.55] as const;
  });
}

function ReducedFigure({
  bucket,
  scattered,
  forming,
  locked,
}: {
  bucket: "locked" | "converging" | "scattered";
  scattered: readonly (readonly [number, number])[];
  forming: readonly (readonly [number, number])[];
  locked: readonly (readonly [number, number])[];
}) {
  const points = bucket === "locked" ? locked : bucket === "converging" ? forming : scattered;
  return (
    <svg
      aria-hidden
      viewBox="0 0 100 100"
      className="absolute inset-0 h-full w-full"
      preserveAspectRatio="none"
    >
      {points.map(([x, y], i) => (
        <circle
          key={i}
          cx={x * 100}
          cy={y * 100}
          r={0.9}
          className="fill-foreground/45"
        />
      ))}
    </svg>
  );
}

export interface ChladniTuneProps {
  /** controlled value; omit for uncontrolled */
  value?: number;
  /** uncontrolled initial value */
  defaultValue?: number;
  /** the value the plate resolves at — never rendered as a number in the UI */
  target: number;
  /** minimum allowed value */
  min?: number;
  /** maximum allowed value */
  max?: number;
  /** increment per keyboard/drag step */
  step?: number;
  /** value distance at which detune reaches 1 (full chaos). default: 25% of the range */
  detuneSpan?: number;
  /** value distance within which the plate is considered locked. default: max(step, 0.5% of the range) */
  lockEpsilon?: number;
  /** override the auto-derived Chladni mode (n, m); n === m is rejected as degenerate */
  mode?: readonly [number, number];
  /** sand grain count on the canvas plate. default 2200 */
  grainCount?: number;
  /** called with the new value on every drag/keyboard change */
  onValueChange?: (value: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the slider */
  "aria-label"?: string;
}

export function ChladniTune({
  value,
  defaultValue = 50,
  target,
  min = 0,
  max = 100,
  step = 0.1,
  detuneSpan,
  lockEpsilon,
  mode,
  grainCount = 2200,
  onValueChange,
  className = "",
  "aria-label": ariaLabel = "Tuning value",
}: ChladniTuneProps) {
  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() => clamp(defaultValue, min, max));
  const current = isControlled ? (value as number) : internal;
  const currentRef = useRef(current);
  currentRef.current = current;

  const span = Math.max(1e-9, max - min);
  const dSpan = detuneSpan ?? span * 0.25;
  const lockEps = lockEpsilon ?? Math.max(step, span * 0.005);

  const rawMode = mode ?? modeForTarget(target);
  const resolvedMode: readonly [number, number] =
    rawMode[0] === rawMode[1] ? modeForTarget(target + 1) : rawMode;
  const [n, m] = resolvedMode;

  const detune = clamp(Math.abs(current - target) / Math.max(1e-9, dSpan), 0, 1);
  const locked = Math.abs(current - target) <= lockEps;
  const coherencePct = Math.round((1 - detune) * 100);
  const word = proximityWord(detune, locked);
  const bucket = stateBucket(detune, locked);

  const reduced = useReducedMotionPref();

  const detuneRef = useRef(detune);
  detuneRef.current = detune;
  const modeRef = useRef(resolvedMode);
  modeRef.current = resolvedMode;

  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (reduced) return;
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    // -- token-derived ink: read at mount, re-derived on theme class flips --
    let plateColor = "#ffffff";
    let grainColor = "rgba(23,23,23,0.5)";
    const deriveColors = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = parseColor(cs.getPropertyValue("--background"));
      const fg = parseColor(cs.getPropertyValue("--foreground"));
      if (bg) plateColor = `rgb(${bg[0]}, ${bg[1]}, ${bg[2]})`;
      if (fg) grainColor = `rgba(${fg[0]}, ${fg[1]}, ${fg[2]}, 0.5)`;
    };
    deriveColors();

    const count = Math.max(200, Math.floor(grainCount));
    const xs = new Float32Array(count);
    const ys = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      xs[i] = Math.random();
      ys[i] = Math.random();
    }

    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    let raf = 0;
    let visible = true;

    const resize = () => {
      const rect = container.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        sized = false;
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      sized = true;
    };
    resize();

    const GRAIN_PX = 1.4;
    const JITTER_MIN = 0.0016; // normalized-unit step at detune 0 — a held-still shimmer, not zero
    const JITTER_MAX = 0.03; // normalized-unit step at detune 1 — a visibly churning haze

    const stepGrains = () => {
      const [cn, cm] = modeRef.current;
      const d = detuneRef.current;
      const jitter = JITTER_MIN + (JITTER_MAX - JITTER_MIN) * d;
      const chaosAccept = Math.pow(d, 1.4); // probability a worse move is kept anyway
      for (let i = 0; i < count; i++) {
        const x = xs[i];
        const y = ys[i];
        const f0 = chladni(cn, cm, x, y);
        let nx = x + (Math.random() - 0.5) * jitter;
        let ny = y + (Math.random() - 0.5) * jitter;
        if (nx < 0) nx = -nx;
        else if (nx > 1) nx = 2 - nx;
        if (ny < 0) ny = -ny;
        else if (ny > 1) ny = 2 - ny;
        const f1 = chladni(cn, cm, nx, ny);
        if (Math.abs(f1) <= Math.abs(f0) || Math.random() < chaosAccept) {
          xs[i] = nx;
          ys[i] = ny;
        }
      }
    };

    const render = () => {
      if (!sized) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = plateColor;
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = grainColor;
      const g = GRAIN_PX;
      for (let i = 0; i < count; i++) {
        ctx.fillRect(xs[i] * w - g / 2, ys[i] * h - g / 2, g, g);
      }
    };

    const loop = () => {
      stepGrains();
      render();
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (!raf && sized && visible && !document.hidden) raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      raf = 0;
    };

    render();
    wake();

    const ro = new ResizeObserver(() => {
      resize();
      render();
    });
    ro.observe(container);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
      else sleep();
    });
    io.observe(container);

    // theme toggle flips the `dark` class on <html> — re-derive plate/grain
    // ink from the tokens, or the wrong theme's colors stay baked in
    const mo = new MutationObserver(() => {
      deriveColors();
      render();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onVis = () => {
      if (document.hidden) sleep();
      else wake();
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      sleep();
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // grainCount and the resolved mode are the only things that require a
    // fresh grain field / redraw cadence; detune/current flow through refs
    // so ordinary slider movement never tears down and re-seeds the plate.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced, grainCount, n, m]);

  const scattered = useMemo(() => computeScatteredPoints(), []);
  const lockedPts = useMemo(() => computeLockedPoints(n, m), [n, m]);
  const forming = useMemo(() => computeFormingPoints(scattered, lockedPts), [scattered, lockedPts]);

  // -- custom track: a real native <input type=range> carries keyboard a11y
  // (sr-only, not display:none, so Tab reaches it and arrow/Home/End/PageUp/
  // PageDown come free from native semantics) while a plain DOM track+thumb
  // pair carries pointer interaction and the visible "core-styled" look.
  // This split (compare-crack-seam's / slider-range-shear's pattern in this registry)
  // matters beyond taste: a synthetic pointerdown/pointermove dispatched at
  // a native range's thumb is not guaranteed to move it — that native
  // click-drag-to-set-value behavior is UA-internal, not something a script
  // can reliably trigger with untrusted events — so autoplay's "drag" mode
  // needs a plain element whose own onPointer* handlers do the mapping.
  const trackRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);
  const draggingRef = useRef(false);

  const commit = (clientX: number) => {
    const track = trackRef.current;
    if (!track) return;
    const r = track.getBoundingClientRect();
    const frac = clamp(r.width > 0 ? (clientX - r.left) / r.width : 0, 0, 1);
    const raw = min + frac * span;
    const snapped = Math.round((raw - min) / step) * step + min;
    const v = clamp(Number(snapped.toFixed(6)), min, max);
    if (!isControlled) setInternal(v);
    onValueChange?.(v);
  };

  const onTrackPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      // synthetic (autoplay) pointerIds match no live pointer — drag still works
    }
    draggingRef.current = true;
    inputRef.current?.focus();
    commit(e.clientX);
  };
  const onTrackPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!draggingRef.current) return;
    commit(e.clientX);
  };
  const onTrackPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    draggingRef.current = false;
    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      // no-op — see onTrackPointerDown
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = clamp(Number(e.target.value), min, max);
    if (!isControlled) setInternal(v);
    onValueChange?.(v);
  };

  const pct = span > 0 ? ((current - min) / span) * 100 : 0;

  return (
    <div className={`flex w-full flex-col items-center gap-5 ${className}`}>
      <div
        ref={containerRef}
        aria-hidden
        className="relative aspect-square w-full max-w-xs overflow-hidden rounded-md border border-border bg-background"
      >
        {!reduced && <canvas ref={canvasRef} aria-hidden className="absolute inset-0 h-full w-full" />}
        {reduced && (
          <ReducedFigure bucket={bucket} scattered={scattered} forming={forming} locked={lockedPts} />
        )}
      </div>

      <div className="flex w-full max-w-xs flex-col gap-2.5">
        <div
          ref={trackRef}
          onPointerDown={onTrackPointerDown}
          onPointerMove={onTrackPointerMove}
          onPointerUp={onTrackPointerUp}
          onPointerCancel={onTrackPointerUp}
          className="chladni-track relative flex h-4 w-full cursor-pointer touch-none select-none items-center"
        >
          <div aria-hidden className="pointer-events-none h-1.5 w-full rounded-full bg-border">
            <div
              aria-hidden
              className="h-full rounded-full bg-foreground/70"
              style={{ width: `${pct}%` }}
            />
          </div>
          <div
            aria-hidden
            className={`pointer-events-none absolute top-1/2 h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-foreground transition-shadow duration-150 ${
              focused ? "ring-2 ring-ns-accent ring-offset-2 ring-offset-background" : ""
            }`}
            style={{ left: `${pct}%` }}
          />
          <input
            ref={inputRef}
            type="range"
            min={min}
            max={max}
            step={step}
            value={current}
            onChange={handleInputChange}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            aria-label={ariaLabel}
            aria-valuetext={`${current.toFixed(1)}, ${word}`}
            className="sr-only"
          />
        </div>

        <div className="flex items-baseline justify-between font-mono text-xs text-ns-muted tabular-nums">
          <span>VALUE {current.toFixed(1)}</span>
          <span>COHERENCE {String(Math.max(0, coherencePct)).padStart(3, "0")}%</span>
        </div>
        <p className="font-mono text-[11px] uppercase tracking-[0.16em] text-ns-muted">
          {bucket === "locked" ? "locked" : bucket === "converging" ? "converging" : "scattered"}
        </p>

        <p aria-live="polite" className="sr-only">
          {locked ? "On target." : ""}
        </p>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// SparkTestId — a file dropzone that identifies a specimen the way a
// machinist identifies unknown steel: SPARK TESTING. Held to a grinding
// wheel, different alloys throw different SPARK STREAMS — carrier-line
// length, how many times each burst forks, how dense the shower runs. The
// wheel idles with a low continuous shower before anything is dropped, so
// the canvas is never a dead frame. Dropping/selecting a file classifies it
// into a coarse type family and swaps the shower's spawn rate, carrier
// length, fork probability and fork depth to that family's characteristic
// signature — the identification is legible from the spark pattern itself,
// same as reading a real stream off a bench grinder. Discrete ballistic
// particles with branching fork events, arced by gravity from one contact
// point — distinct from file-upload-thermal's continuous rising wisps (no
// discrete burst/fork topology) and file-upload-seal's vector spring
// outline (no particles at all). Real sparks are hue-coded; this adaptation
// carries intensity as LUMINANCE only, stated plainly below, not as a claim
// of color fidelity. Direct-DOM canvas rAF, no React state in the hot path;
// ink derived from CSS tokens at mount and re-derived on documentElement
// class changes.
// ---------------------------------------------------------------------------

type TypeFamily =
  | "idle"
  | "image"
  | "text"
  | "avmedia"
  | "archive"
  | "unknown";

interface SparkSignature {
  label: string; // spoken/visible description of the metallurgical analogue
  spawnRate: number; // primary sparks per second
  speedMul: number; // carrier speed relative to base
  carrierMul: number; // carrier-line length relative to base
  forkProb: number; // probability a spark forks at its burst point
  maxForkDepth: number; // how many generations of forking are possible
  sprigMin: number;
  sprigMax: number;
  spreadDeg: number; // half-angle of the shower cone
  intensity: number; // 0..1, luminance ceiling for this signature
}

