const MAX_PARTICLES = 260;

interface Spark {
  x: number;
  y: number;
  px: number; // previous frame position, for the trail segment
  py: number;
  vx: number;
  vy: number;
  age: number;
  life: number;
  forkAt: number; // fraction of life at which a fork can trigger
  forked: boolean;
  depth: number;
  intensity: number;
}

function classify(name: string, type: string): TypeFamily {
  const lower = name.toLowerCase();
  if (type.startsWith("image/") || /\.(png|jpe?g|gif|webp|svg|bmp|avif)$/.test(lower)) {
    return "image";
  }
  if (
    type.startsWith("video/") ||
    type.startsWith("audio/") ||
    /\.(mp4|mov|webm|mkv|mp3|wav|flac|ogg|m4a)$/.test(lower)
  ) {
    return "avmedia";
  }
  if (
    /\.(zip|rar|7z|tar|gz|tgz|bz2|dmg|exe|iso)$/.test(lower) ||
    type === "application/zip" ||
    type === "application/x-tar" ||
    type === "application/gzip"
  ) {
    return "archive";
  }
  if (
    type.startsWith("text/") ||
    type === "application/json" ||
    type === "application/pdf" ||
    /\.(txt|md|json|js|ts|tsx|jsx|css|html|csv|log|pdf|docx?|xml|yml|yaml)$/.test(lower)
  ) {
    return "text";
  }
  return "unknown";
}

function familyDisplayName(f: TypeFamily): string {
  switch (f) {
    case "image":
      return "Image";
    case "avmedia":
      return "Audio/video";
    case "archive":
      return "Archive/binary";
    case "text":
      return "Text/document";
    case "unknown":
      return "Unrecognized";
    default:
      return "Idle";
  }
}

function formatSize(bytes: number): string {
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${bytes} B`;
}

function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const STATIC_TIME = 1.35; // s — reduced-motion freeze: a long-exposure window
// with several carrier lines and at least one fully-formed fork visible,
// never a t0 frame (t0 for the idle signature is a bare shower start).

export interface SparkTestIdFile {
  id: string;
  name: string;
  size: number;
  type: string;
  family: TypeFamily;
}

export function SparkTestId({
  accept = [],
  maxSizeBytes,
  onFileChange,
  className = "",
  "aria-label": ariaLabel = "Upload a file to identify its type",
}: {
  /** allowed extensions/mimes (".png", "image/*"); empty = any */
  accept?: string[];
  /** rejects a file larger than this. No default — unlimited. */
  maxSizeBytes?: number;
  /** called with the identified file, or null when cleared */
  onFileChange?: (file: SparkTestIdFile | null) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the dropzone control */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const zoneRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const signatureRef = useRef<TypeFamily>("idle");
  const reducedRef = useRef(false);

  const [file, setFile] = useState<SparkTestIdFile | null>(null);
  const [isOver, setIsOver] = useState(false);
  const [announce, setAnnounce] = useState("Wheel idling. No specimen held.");
  const hintId = useId();
  const liveId = useId();

  const acceptFile = useCallback(
    (f: File): { ok: true; family: TypeFamily } | { ok: false; reason: string } => {
      if (maxSizeBytes != null && f.size > maxSizeBytes) {
        return { ok: false, reason: `exceeds size limit (${formatSize(maxSizeBytes)})` };
      }
      if (accept.length > 0) {
        const lower = f.name.toLowerCase();
        const matches = accept.some((a) => {
          if (a.startsWith(".")) return lower.endsWith(a.toLowerCase());
          if (a.endsWith("/*")) return f.type.startsWith(a.slice(0, -1));
          return f.type === a;
        });
        if (!matches) return { ok: false, reason: "type not accepted" };
      }
      return { ok: true, family: classify(f.name, f.type) };
    },
    [accept, maxSizeBytes]
  );

  const handleFiles = useCallback(
    (list: FileList | null) => {
      if (!list || list.length === 0) return;
      const f = list[0];
      const result = acceptFile(f);
      if (!result.ok) {
        setAnnounce(`Specimen rejected: ${f.name}, ${result.reason}.`);
        return;
      }
      const next: SparkTestIdFile = {
        id: `spk-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        name: f.name,
        size: f.size,
        type: f.type || "unknown",
        family: result.family,
      };
      setFile(next);
      signatureRef.current = result.family;
      const sig = SIGNATURES[result.family];
      setAnnounce(
        `Detected type: ${familyDisplayName(result.family)}, ${f.type || "unknown MIME type"}. Spark signature: ${sig.label}.`
      );
      onFileChange?.(next);
    },
    [acceptFile, onFileChange]
  );

  const clearFile = useCallback(() => {
    setFile(null);
    signatureRef.current = "idle";
    setAnnounce("Specimen cleared. Wheel idling. No specimen held.");
    onFileChange?.(null);
    if (inputRef.current) inputRef.current.value = "";
  }, [onFileChange]);

  const onDrop = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      setIsOver(false);
      handleFiles(e.dataTransfer.files);
    },
    [handleFiles]
  );

  const onKeyDown = useCallback((e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      inputRef.current?.click();
    }
  }, []);

  // -- engine: spark shower canvas, direct-DOM only --------------------------
  useLayoutEffect(() => {
    const root = rootRef.current;
    const zone = zoneRef.current;
    const canvas = canvasRef.current;
    if (!root || !zone || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    reducedRef.current = reduced;

    // token ink — read at mount, re-derived live on theme class change.
    // fields start empty and are assigned unconditionally before any paint.
    let fg = "";
    let muted = "";
    let bg = "";
    let border = "";
    const deriveTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim();
      muted = cs.getPropertyValue("--ns-muted").trim();
      bg = cs.getPropertyValue("--background").trim();
      border = cs.getPropertyValue("--border").trim();
    };
    deriveTokens();
    const mo = new MutationObserver(deriveTokens);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    const DPR_CAP = 2;

    const resize = () => {
      const rect = zone.getBoundingClientRect();
      w = Math.max(1, rect.width);
      h = Math.max(1, rect.height);
      dpr = Math.min(DPR_CAP, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = w > 1 && h > 1;
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(zone);

    let visible = true;
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) visible = entry.isIntersecting;
      },
      { threshold: 0 }
    );
    io.observe(zone);
    let pageVisible = document.visibilityState === "visible";
    const onVis = () => {
      pageVisible = document.visibilityState === "visible";
    };
    document.addEventListener("visibilitychange", onVis);

    let particles: Spark[] = [];
    let spawnAcc = 0;

    // origin: the "wheel contact point" — centre-left rather than the
    // corner, scaled to the container's smaller dimension so density/length
    // read at any preview size, per the scale rule. Sitting mid-height
    // leaves the ballistic cone room to arc up through the top of the
    // frame and fall back down without colliding with the label block
    // pinned to the bottom of the dropzone.
    const scaleDim = () => Math.min(w, h);
    const originX = () => w * 0.22;
    const originY = () => h * 0.52;
    const baseAngle = -55; // degrees, up-and-right cone axis
    const gravity = () => scaleDim() * 1.7; // px/s^2, arcs the stream down
    const baseSpeed = () => scaleDim() * 1.55; // px/s
    const baseLife = 0.78; // s, before signature carrierMul

    const spawnSpark = (
      arr: Spark[],
      rng: () => number,
      sig: SparkSignature,
      depth: number,
      x: number,
      y: number,
      angleDeg: number,
      speedScale: number
    ) => {
      if (arr.length >= MAX_PARTICLES) return;
      const jitter = (rng() - 0.5) * 2 * sig.spreadDeg;
      const angle = ((angleDeg + jitter) * Math.PI) / 180;
      const speed = baseSpeed() * sig.speedMul * speedScale * (0.85 + rng() * 0.3);
      const life =
        depth === 0
          ? baseLife * sig.carrierMul * (0.8 + rng() * 0.4)
          : (0.12 + rng() * 0.1) * (1 + sig.carrierMul * 0.15); // short terminal sprig
      arr.push({
        x,
        y,
        px: x,
        py: y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        age: 0,
        life,
        forkAt: 0.35 + rng() * 0.3,
        forked: depth >= sig.maxForkDepth,
        depth,
        intensity: sig.intensity * (depth === 0 ? 1 : 0.85),
      });
    };

    const drawWheel = () => {
      const ox = originX();
      const oy = originY();
      const r = scaleDim() * 0.09;
      ctx.save();
      ctx.strokeStyle = muted;
      ctx.globalAlpha = 0.55;
      ctx.lineWidth = Math.max(1, scaleDim() * 0.008);
      ctx.beginPath();
      ctx.arc(ox - r * 0.7, oy, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.arc(ox - r * 0.7, oy, r * 0.35, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    };

    const stepSpark = (s: Spark, dt: number, sig: SparkSignature, rng: () => number, out: Spark[]) => {
      s.px = s.x;
      s.py = s.y;
      s.vy += gravity() * dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.age += dt;
      if (!s.forked && s.age >= s.life * s.forkAt && s.depth < sig.maxForkDepth) {
        s.forked = true;
        if (rng() < sig.forkProb) {
          const count = sig.sprigMin + Math.floor(rng() * (sig.sprigMax - sig.sprigMin + 1));
          const parentAngle = (Math.atan2(s.vy, s.vx) * 180) / Math.PI;
          for (let i = 0; i < count; i++) {
            const branch = parentAngle + (rng() - 0.5) * 70;
            spawnSpark(out, rng, sig, s.depth + 1, s.x, s.y, branch, 0.55 + rng() * 0.2);
          }
        }
      }
    };

    const drawSpark = (s: Spark) => {
      const a = Math.max(0, 1 - s.age / s.life);
      if (a <= 0) return;
      // glow halo in muted, bright core in foreground — luminance-only "hot"
      // read, no hue; per the monochrome adaptation this stands in for the
      // real spark-stream color signal.
      ctx.strokeStyle = muted;
      ctx.globalAlpha = a * s.intensity * 0.5;
      ctx.lineWidth = Math.max(1, scaleDim() * 0.006);
      ctx.beginPath();
      ctx.moveTo(s.px, s.py);
      ctx.lineTo(s.x, s.y);
      ctx.stroke();
      ctx.strokeStyle = fg;
      ctx.globalAlpha = a * s.intensity;
      ctx.lineWidth = Math.max(0.75, scaleDim() * 0.0032);
      ctx.beginPath();
      ctx.moveTo(s.px, s.py);
      ctx.lineTo(s.x, s.y);
      ctx.stroke();
    };

    // ---- reduced motion: one deterministic long-exposure freeze frame -----
    const renderStaticFrame = () => {
      if (!sized) return;
      const sig = SIGNATURES[signatureRef.current];
      const rng = mulberry32(signatureRef.current.length * 7919 + 13);
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);
      drawWheel();
      let arr: Spark[] = [];
      let acc = 0;
      const dt = 1 / 60;
      let t = 0;
      while (t < STATIC_TIME) {
        acc += sig.spawnRate * dt;
        while (acc >= 1) {
          spawnSpark(arr, rng, sig, 0, originX(), originY(), baseAngle, 1);
          acc -= 1;
        }
        const spawned: Spark[] = [];
        for (const s of arr) {
          stepSpark(s, dt, sig, rng, spawned);
        }
        arr = arr.concat(spawned);
        t += dt;
      }
      // paint every particle's final segment plus a short fading trail so
      // carrier lines and forks are both legible in one static composite —
      // this is a long exposure, not a literal single instant.
      for (const s of arr) {
        if (s.age >= s.life * 1.4) continue; // long-dead, would just be noise
        drawSpark(s);
      }
      ctx.globalAlpha = 1;
      if (border) {
        // legitimate --border use: the dropzone's own outline, drawn by CSS,
        // not touched here — canvas leaves the frame edge alone.
      }
    };

    let raf = 0;
    let last = 0;
    const loop = (now: number) => {
      raf = requestAnimationFrame(loop);
      if (!sized || !visible || !pageVisible) {
        last = now;
        return;
      }
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      const sig = SIGNATURES[signatureRef.current];

      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);
      drawWheel();

      spawnAcc += sig.spawnRate * dt;
      const rng = Math.random;
      while (spawnAcc >= 1 && particles.length < MAX_PARTICLES) {
        spawnSpark(particles, rng, sig, 0, originX(), originY(), baseAngle, 1);
        spawnAcc -= 1;
      }

      const spawned: Spark[] = [];
      const alive: Spark[] = [];
      for (const s of particles) {
        stepSpark(s, dt, sig, rng, spawned);
        if (s.age < s.life && s.y < h + 40) alive.push(s);
      }
      particles = alive.concat(spawned).slice(-MAX_PARTICLES);

      for (const s of particles) drawSpark(s);
      ctx.globalAlpha = 1;
    };

    if (reduced) {
      renderStaticFrame();
    } else {
      raf = requestAnimationFrame(loop);
    }

    // re-render the static frame if the signature changes while reduced
    // motion is active, or if tokens flip theme — both need a fresh paint
    // since there is no running loop to pick it up on its own.
    const staticRerender = () => {
      if (reducedRef.current) renderStaticFrame();
    };
    const moForStatic = new MutationObserver(() => {
      deriveTokens();
      staticRerender();
    });
    moForStatic.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      moForStatic.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [file?.id]);

  return (
    <div ref={rootRef} className={`relative w-full ${className}`}>
      <div
        ref={zoneRef}
        role="button"
        tabIndex={0}
        aria-label={ariaLabel}
        aria-describedby={hintId}
        onClick={() => inputRef.current?.click()}
        onKeyDown={onKeyDown}
        onDragOver={(e) => {
          e.preventDefault();
          setIsOver(true);
        }}
        onDragLeave={() => setIsOver(false)}
        onDrop={onDrop}
        className={`relative isolate flex min-h-56 w-full flex-col items-center justify-end overflow-hidden rounded-md border outline-none transition-colors ${
          isOver ? "border-ns-accent" : "border-border"
        } focus-visible:ring-2 focus-visible:ring-ns-accent/30`}
      >
        <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" aria-hidden="true" />
        <div className="relative z-10 flex w-full flex-col items-center gap-1 px-4 pb-4 pt-10">
          <p className="font-mono text-xs uppercase tracking-[0.18em] text-ns-muted">
            {file ? file.name : "Drop a file on the wheel"}
          </p>
          <p className="text-xs text-ns-muted">
            {file
              ? `${familyDisplayName(file.family)} · ${formatSize(file.size)}`
              : "or press Enter to browse"}
          </p>
        </div>
      </div>

      <input
        ref={inputRef}
        type="file"
        accept={accept.join(",") || undefined}
        onChange={(e) => handleFiles(e.target.files)}
        className="sr-only"
        tabIndex={-1}
        aria-hidden="true"
      />

      <div className="mt-3 flex items-center justify-between gap-3">
        <p id={hintId} className="text-xs text-ns-muted">
          {accept.length > 0 ? `Accepts ${accept.join(", ")}` : "Accepts any file type"}
          {maxSizeBytes != null ? ` · up to ${formatSize(maxSizeBytes)}` : ""}
        </p>
        {file && (
          <button
            type="button"
            onClick={clearFile}
            className="text-xs text-ns-muted underline decoration-border underline-offset-2 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent/30"
          >
            Clear
          </button>
        )}
      </div>

      <div id={liveId} role="status" aria-live="polite" className="sr-only">
        {announce}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// SpiralChuteAccrete — a full-bleed ambient background reproducing a gravity
// spiral chute: the helical slide sorting facilities and department-store
// stockrooms use to move parcels/mail sacks between floors without powered
// conveyance. Small parcels enter at the top, slide down a continuous
// helical ramp under gravity alone (friction + the helix's banking keeps
// speed roughly bounded rather than accelerating), and pile up in a landing
// area at the base until the pile is swept clear.
//
// EVERYTHING IS A PURE FUNCTION OF ONE CLOCK. Rather than mutating an array
// of live parcel/tile objects frame to frame, every quantity drawn — which
// parcels are in flight, where each sits on the helix, which tiles are in
// the current pile, which are mid-sweep-out — is derived straight from the
// elapsed clock t (ms) and a fixed spawn index k. That is what makes the
// state reproducible for prefers-reduced-motion: freezing the clock at a
// named STATIC_T freezes the exact same layout every time, with no history
// to serialize.
//
//   spawn(k)   = k * SPAWN_INTERVAL_MS                      (top of chute)
//   land(k)    = spawn(k) + TRANSIT_MS                      (base of chute)
//   in flight  = spawn(k) <= t < land(k)   -> theta = (t-spawn(k))/TRANSIT_MS * THETA_MAX
//   landed     = land(k) <= t              -> becomes one pile tile
//
// PILE / SWEEP: the base landing area fills with one tile per landed
// parcel, positioned by a period-9 deterministic jitter sequence keyed off
// k % 9 (never per-frame randomness, so the pile shape is exactly
// reproducible). Every SWEEP_PERIOD_MS the chute's current 9s fill cycle
// ends and the NEXT cycle's landings start a fresh pile; the tiles that
// belong to the cycle which just ended slide off to one side over
// SWEEP_DURATION_MS, staggered SWEEP_STAGGER_MS apart, for the first
// SWEEP_DURATION_MS of the new cycle only. This is derived directly from
// `t % SWEEP_PERIOD_MS`, so a pile can never accumulate past one fill
// cycle's worth of tiles and never breaches the canvas edge.
//
// REAL NUMBERS (all fixed, real-world-derived, not tuned per frame): a
// parcel takes TRANSIT_MS to cross THE FULL 3.5 turns of the helix — this
// is one of the rare cases where the legible rate and the real rate are
// close, so descent renders close to real proportion instead of being
// artificially decoupled. New parcels spawn every SPAWN_INTERVAL_MS, which
// at a 3.6s transit keeps 2-3 parcels in flight simultaneously, each at a
// different theta so they never overlap on the same winding — this
// simultaneous-parcel count, not a faster descent, is the intended legible
// signal for "alive," per the spec's own kill criteria.
//
// TOKENS: the ramp track itself is the least important thing on screen —
// it renders at --ns-muted, a low, border-like contrast step, so it reads
// as track rather than subject. Parcels and pile tiles are the moving
// subject and render at --foreground so they clear the ramp with a real
// luminance step in both themes. --ns-accent never appears; nothing here
// is interaction chrome, and the pile-sweep moment (this component's one
// climactic event) is a --foreground fade/slide only.
// ---------------------------------------------------------------------------

const TRANSIT_MS = 3600; // one parcel's full top-to-bottom transit
const SPAWN_INTERVAL_MS = 1300; // cadence of new parcels entering at the top
const TURNS = 3.5; // total revolutions top -> bottom
const THETA_MAX = TURNS * Math.PI * 2;
const SWEEP_PERIOD_MS = 9000; // pile fill/clear cycle length
const SWEEP_DURATION_MS = 500; // how long a sweep-out takes
const SWEEP_STAGGER_MS = 30; // stagger between tiles sliding away
const RADIUS_FACTOR = 0.32; // spiral radius, as a fraction of min(w,h)
const RAMP_TOP_FRAC = 0.1; // top margin, fraction of container height
const RAMP_HEIGHT_FRAC = 0.68; // vertical extent of the helix, fraction of height
const RAMP_SAMPLES = 240; // points used to build the cached ramp path
const PARCEL_SIZE_FRAC = 0.05; // parcel edge length, fraction of min(w,h)
const PILE_JITTER_FRAC = 0.075; // pile scatter radius, fraction of min(w,h)

// deterministic period-9 jitter sequence (unit-ish offsets), keyed by
// spawn index k % 9 — fixed, not per-frame random, so the pile shape is
// reproducible frame to frame and across prefers-reduced-motion runs.
const PILE_OFFSETS: readonly [number, number][] = [
  [0.12, -0.22],
  [-0.38, 0.14],
  [0.44, 0.3],
  [-0.14, -0.42],
  [0.05, 0.42],
  [-0.46, -0.08],
  [0.26, -0.36],
  [-0.2, 0.36],
  [0.4, 0.04],
];

// prefers-reduced-motion freeze frame: named MID_DESCENT. Chosen mid-cycle
// (71.7% into a 9s fill) so the pile is roughly half of a full cycle's
// worth of tiles (3 landed of ~5 max) rather than freshly swept or about
// to overflow, with two parcels still in flight at clearly different theta
// — spiral, motion-implying spacing and an in-progress pile all visible
// in one static composition.
const STATIC_T = 6450;

// live-mode warm start: t=0 on a bare clock is a near-empty chute (one
// parcel just spawned, pile empty) — the spec's own t0 requirement is
// "2-3 parcels visible at different points on the spiral, plus a partial
// pile." Starting the live clock here instead of at 0 makes t0 already
// alive without changing any rate: k=2/k=3 in flight (theta .71/.35),
// pile at 2 tiles. Deliberately a different phase than STATIC_T so the
// reduced-motion freeze is never mistaken for "just t0."
const WARM_START_MS = 5150;

function landTimeForIndex(k: number): number {
  return k * SPAWN_INTERVAL_MS + TRANSIT_MS;
}

interface FlightParcel {
  k: number;
  progress: number; // 0..1 along the helix
}

interface PileTile {
  k: number;
  sweepProgress: number; // 0 = resting in pile, 1 = fully slid away
}

/** Parcels currently in flight (spawned, not yet landed) at clock t. */
function computeFlight(t: number): FlightParcel[] {
  const out: FlightParcel[] = [];
  const maxK = Math.floor(t / SPAWN_INTERVAL_MS);
  for (let k = Math.max(0, maxK - 4); k <= maxK; k++) {
    const spawnAt = k * SPAWN_INTERVAL_MS;
    if (spawnAt < 0 || spawnAt > t) continue;
    const landAt = landTimeForIndex(k);
    if (t >= landAt) continue;
    out.push({ k, progress: (t - spawnAt) / TRANSIT_MS });
  }
  return out;
}

/**
 * The pile as it should render at clock t: tiles landed in the CURRENT
 * fill cycle (sweepProgress 0, resting), plus — for the first
 * SWEEP_DURATION_MS of a new cycle only — the previous cycle's tiles,
 * staggered mid-slide-away.
 */
function computePile(t: number): PileTile[] {
  if (t < 0) return [];
  const cycleIndex = Math.floor(t / SWEEP_PERIOD_MS);
  const cycleStart = cycleIndex * SWEEP_PERIOD_MS;
  const sinceCycleStart = t - cycleStart;

  const out: PileTile[] = [];

  // current cycle's own landings so far
  const currentMaxK = Math.floor((t - TRANSIT_MS) / SPAWN_INTERVAL_MS);
  for (let k = Math.max(0, currentMaxK - 8); k <= currentMaxK; k++) {
    const landAt = landTimeForIndex(k);
    if (landAt > cycleStart && landAt <= t) {
      out.push({ k, sweepProgress: 0 });
    }
  }

  // previous cycle's tiles, still sliding away in the first
  // SWEEP_DURATION_MS of this cycle
  if (cycleIndex > 0 && sinceCycleStart < SWEEP_DURATION_MS) {
    const prevCycleStart = cycleStart - SWEEP_PERIOD_MS;
    const prevMaxK = Math.floor((cycleStart - TRANSIT_MS) / SPAWN_INTERVAL_MS);
    const prevTiles: number[] = [];
    for (let k = Math.max(0, prevMaxK - 8); k <= prevMaxK; k++) {
      const landAt = landTimeForIndex(k);
      if (landAt > prevCycleStart && landAt <= cycleStart) prevTiles.push(k);
    }
    prevTiles.sort((a, b) => a - b);
    prevTiles.forEach((k, i) => {
      const localStart = i * SWEEP_STAGGER_MS;
      const local = sinceCycleStart - localStart;
      const span = SWEEP_DURATION_MS - localStart;
      const p = span <= 0 ? 1 : Math.max(0, Math.min(1, local / span));
      if (p < 1) out.push({ k, sweepProgress: p });
    });
  }

  return out;
}

function easeOut(p: number): number {
  return 1 - (1 - p) * (1 - p);
}

export interface SpiralChuteAccreteProps {
  /** headline / CTA rendered centered over the chute */
  children?: ReactNode;
  /** extra classes merged onto the root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: React.CSSProperties;
}

export function SpiralChuteAccrete({
  children,
  className = "",
  style,
}: SpiralChuteAccreteProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // token fields start empty; nothing paints until readTokens() has run
    // at least once (guarded in draw() below) — closes every path (rAF
    // start, resize, IntersectionObserver resume) that could otherwise
    // paint a literal color before the first token read.
    let mutedColor = "";
    let fgColor = "";
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      mutedColor = cs.getPropertyValue("--ns-muted").trim();
      fgColor = cs.getPropertyValue("--foreground").trim();
    };

    let w = 0;
    let h = 0;
    let cx = 0;
    let radius = 0;
    let topY = 0;
    let rampHeight = 0;
    let baseX = 0;
    let baseY = 0;
    let parcelSize = 0;
    let pileJitter = 0;
    let sized = false;
    let visible = true;
    let raf = 0;
    let last = 0;
    let t = reduced ? STATIC_T : WARM_START_MS;

    // cached ramp path samples, rebuilt only on resize (geometry never
    // changes per frame — only scale/position do).
    let rampPath: Path2D | null = null;

    const pointOnHelix = (theta: number) => {
      const x = cx + radius * Math.sin(theta);
      const y = topY + (theta / THETA_MAX) * rampHeight;
      return [x, y] as const;
    };

    const buildRampPath = () => {
      const path = new Path2D();
      for (let i = 0; i <= RAMP_SAMPLES; i++) {
        const theta = (i / RAMP_SAMPLES) * THETA_MAX;
        const [x, y] = pointOnHelix(theta);
        if (i === 0) path.moveTo(x, y);
        else path.lineTo(x, y);
      }
      rampPath = path;
      const [bx, by] = pointOnHelix(THETA_MAX);
      baseX = bx;
      baseY = by;
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      const isCard = !!canvas.closest("[data-autoplay-root]");
      const dpr = isCard
        ? Math.min(0.75, window.devicePixelRatio || 1)
        : Math.min(window.devicePixelRatio || 1, 1.5);
      w = rect.width;
      h = rect.height;
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const minDim = Math.min(w, h);
      cx = w / 2;
      // clamp against w/2 as well as min(w,h) — a container taller than
      // wide would otherwise let the helix clip both side edges.
      radius = Math.min(RADIUS_FACTOR * minDim, w * 0.4);
      topY = h * RAMP_TOP_FRAC;
      rampHeight = h * RAMP_HEIGHT_FRAC;
      parcelSize = Math.max(3, minDim * PARCEL_SIZE_FRAC);
      pileJitter = minDim * PILE_JITTER_FRAC;
      sized = true;
      buildRampPath();
    };

    const drawSquare = (x: number, y: number, size: number, alpha: number) => {
      ctx.globalAlpha = alpha;
      ctx.fillRect(x - size / 2, y - size / 2, size, size);
    };

    const draw = () => {
      if (!sized || !fgColor || !mutedColor || !rampPath) return;
      ctx.clearRect(0, 0, w, h);

      // ramp track: the track, not the subject — low, border-like contrast
      ctx.globalAlpha = 1;
      ctx.strokeStyle = mutedColor;
      // floored well above the raw radius*0.02 scale — at card-preview
      // size (~400px, dpr 0.75) that scale alone thins under 2px and the
      // ramp risks disappearing on a light background, the exact failure
      // the spec calls out. Alpha raised to match; parcels/pile still
      // dominate at 0.92-0.95 --foreground.
      ctx.globalAlpha = 0.55;
      ctx.lineWidth = Math.max(1.5, radius * 0.02);
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.stroke(rampPath);

      // pile: current cycle's tiles plus any mid-sweep leftovers
      ctx.fillStyle = fgColor;
      const pile = computePile(t);
      for (const tile of pile) {
        const [ox, oy] = PILE_OFFSETS[((tile.k % 9) + 9) % 9];
        const slideX = tile.sweepProgress > 0 ? easeOut(tile.sweepProgress) * (w * 0.7) : 0;
        const x = baseX + ox * pileJitter + slideX;
        const y = baseY + oy * pileJitter * 0.6;
        const alpha = 0.92 * (1 - tile.sweepProgress);
        if (alpha > 0.01) drawSquare(x, y, parcelSize * 0.9, alpha);
      }

      // in-flight parcels on the helix
      const flight = computeFlight(t);
      for (const parcel of flight) {
        const theta = parcel.progress * THETA_MAX;
        const [x, y] = pointOnHelix(theta);
        drawSquare(x, y, parcelSize, 0.95);
      }

      ctx.globalAlpha = 1;
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(50, now - last) : 1000 / 60;
      last = now;
      t += dt;
      draw();
      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const ro = new ResizeObserver(() => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw();
      }, 120);
    });
    ro.observe(root);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible && !reduced && !raf) {
          last = 0;
          raf = requestAnimationFrame(loop);
        }
      },
      { threshold: 0 }
    );
    io.observe(root);

    const onVis = () => {
      if (!document.hidden && visible && !reduced && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced || !raf) draw();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    readTokens();
    resize();

    if (reduced) {
      draw();
    } else {
      raf = requestAnimationFrame(loop);
    }

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`relative isolate min-h-screen w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute inset-0 block h-full w-full"
      />
      {children ? (
        <div className="relative z-10 flex min-h-screen w-full flex-col items-center justify-center gap-4 px-6 text-center">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// StackStepCarousel — a full-bleed background modelling vacuum thin-film
// deposition on a planetary carrier: mirror/lens blanks ride a rotating
// carrier past a fixed evaporation/sputter source, each pass under the
// source depositing one quarter-wave layer and stepping that blank's
// reflectance up a notch.
//
// GEOMETRY: 8 substrate discs (N_DISCS) sit on station points evenly spaced
// (45deg apart) around a single "sun ring" of radius 0.32*min(w,h), disc
// radius 0.09*min(w,h). PLANET_PERIOD_S = 3.5s is each disc's own orbital
// period around the center — the spec's "planet (substrate) spin" — this IS
// what actually carries every station through the fixed 30deg source arc at
// the top of the frame, so a single disc's own crossing cadence is exactly
// once per 3.5s, matching the spec's legibility line literally rather than
// by inference. CARRIER_PERIOD_S = 14s (the spec's "sun ring" period) gets
// its own, separate, purely structural screen presence: a slow-rotating
// armature of small index ticks around the guide ring, decoupled from the
// discs' own fast motion — the classic epicyclic-gearing relationship (a
// slower carrier arm, faster individual planet motion) rendered as two
// visually distinct rotations rather than one number driving the other.
//
// CROSSING / LAYERS: each disc's total completed orbits by time t is
// totalLaps_i(t) = floor(t/PLANET_PERIOD_S + stationAngle_i/2*PI) — a step
// function that ticks up by exactly 1 once per disc's own 3.5s orbit, offset
// per disc by its station angle, so with 8 evenly-spaced discs a new
// crossing lands somewhere on the ring roughly every 3.5/8 ~= 0.44s even
// though any single disc's own personal cadence stays exactly 3.5s. Layer
// count is (seedOffset_i + totalLaps_i(t)) mod 13 — a 13-state cycle (0 =
// fresh bare blank through 12 = full stack) so the crossing that WOULD push
// a disc past 12 instead wraps it back to a fresh blank, i.e. the staggered
// swap the spec calls for; seedOffset_i (a fixed, non-random per-disc
// integer 0..12 from a seeded PRNG) staggers the 8 discs' initial phase in
// the cycle, and because every disc's own cycle rate is identical that
// stagger persists forever — the batch structurally cannot resync into a
// single synchronized reload.
//
// REFLECTANCE: luminance is not a linear layer count, it is the real
// quarter-wave-stack reflectance recursion — Y(N) = n_sub*(n_L/n_H)^N,
// R(N) = ((1-Y)/(1+Y))^2 for a symmetric H/L quarter-wave stack (n_H=2.35
// TiO2-like, n_L=1.38 SiO2-like, n_sub=1.52 glass-like, n_0=1 air) — giving
// R(0) ~4% (bare glass) climbing to R(12) ~99% (a realistic 12-layer HR
// mirror) with the real diminishing-returns shape late in the stack.
// Normalized to 0..1 across N=0..12, this fraction is a plain linear RGB mix
// between --ns-muted (0) and --foreground (1): since --foreground is
// defined, in every theme, as the maximum-contrast token against
// --background, "fully stacked reads as the higher-contrast extreme" is
// true by construction with no separate bias/contrast retune needed — the
// weld-pool convention's intent (never literally inverted to a different
// hue relationship) is satisfied structurally rather than by a tuned pair.
//
// SOURCE-CROSSING GLOW: the envelope is referenced to the disc's ARC-ENTRY
// angle (-15deg), not the arc center, so it starts ramping as the disc
// actually enters the 30deg window, peaks almost exactly as the disc passes
// the arc's center (peak time = the real entry-to-center transit time, ~half
// the arc's own transit duration), then keeps fading a while after physical
// exit for legibility — arrives, brightens, departs, never a blink. The
// fixed source arc is drawn from --ns-muted (not --border — a full-bleed
// background's fixed reference the whole mechanic points at cannot be the
// ~1.1:1 separator token) and brightens toward --foreground while any disc
// is under it.
//
// POINTER: canvas-local pointermove finds the nearest disc within 1.3x its
// radius and eases a hover ring toward full over ~150ms — a plain
// --foreground outline whose alpha reflects that disc's OWN current
// reflectance fraction (a legible "here's how far along this one is"), no
// tint, no orbit/carrier rate change.
//
// The clock is real elapsed wall time from mount (t = (now-startMs)/1000)
// with no loop reset at all: the process genuinely never finishes, matching
// the batch-deposition source ("the chamber runs planetary rotation for the
// whole cycle, not a one-shot flash"). Hidden tabs simply stop paint via the
// IntersectionObserver; because position is derived from absolute elapsed
// time, not accumulated per-frame deltas, the carrier is always exactly
// where continuous real-time rotation would have put it on resume.
// ---------------------------------------------------------------------------

const N_DISCS = 8;
const PLANET_PERIOD_S = 3.5; // each disc's own orbit — the crossing cadence
const CARRIER_PERIOD_S = 14; // slow armature-tick rotation, decorative
const SOURCE_ARC_RAD = (30 * Math.PI) / 180; // 30deg source arc at top of frame
const ARC_HALF_FRAC = SOURCE_ARC_RAD / 2 / (Math.PI * 2); // entry offset as a fraction of one orbit
const GLOW_PEAK_MS = ARC_HALF_FRAC * PLANET_PERIOD_S * 1000; // entry -> center transit time
const GLOW_MS = 800; // arrives-brightens-departs envelope per crossing
const LAYER_CAP = 12; // 0..12, 13-state reload cycle
const HOVER_EASE_MS = 150;
const N_ARMATURE_TICKS = 16;

// quarter-wave stack indices — TiO2/SiO2-like alternating pair on glass
const N_AIR = 1.0;
const N_HIGH = 2.35;
const N_LOW = 1.38;
const N_SUB = 1.52;

function stackY(n: number): number {
  return N_SUB * Math.pow(N_LOW / N_HIGH, n);
}
function stackR(n: number): number {
  const y = stackY(n);
  const rho = (N_AIR - y) / (N_AIR + y);
  return rho * rho;
}
const R0 = stackR(0);
const R12 = stackR(LAYER_CAP);
function reflectanceFrac(layer: number): number {
  const r = stackR(layer);
  return Math.max(0, Math.min(1, (r - R0) / (R12 - R0)));
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Station {
  angle: number; // radians, 0 = top, increasing clockwise
  angleFrac: number; // angle / 2*PI, cached
  seedOffset: number; // 0..12, staggers the reload cycle
}

function buildStations(): Station[] {
  const rand = mulberry32(0x5ea70c1e);
  const stations: Station[] = [];
  for (let i = 0; i < N_DISCS; i++) {
    const angle = (i / N_DISCS) * Math.PI * 2;
    stations.push({
      angle,
      angleFrac: i / N_DISCS,
      seedOffset: Math.floor(rand() * (LAYER_CAP + 1)),
    });
  }
  return stations;
}

/** orbit phase referenced to the disc sitting exactly at the arc's center (top) */
function centerPhase(station: Station, tSec: number): number {
  return tSec / PLANET_PERIOD_S + station.angleFrac;
}

function layerAt(station: Station, tSec: number): number {
  const laps = Math.floor(centerPhase(station, tSec));
  return (((station.seedOffset + laps) % (LAYER_CAP + 1)) + (LAYER_CAP + 1)) % (LAYER_CAP + 1);
}

/** seconds since this disc last entered the source arc's leading (-15deg) edge */
function glowAge(station: Station, tSec: number): number {
  const shifted = centerPhase(station, tSec) + ARC_HALF_FRAC;
  const frac = shifted - Math.floor(shifted);
  return frac * PLANET_PERIOD_S;
}

function glowAlpha(ageSec: number): number {
  const ageMs = ageSec * 1000;
  if (ageMs >= GLOW_MS) return 0;
  if (ageMs <= GLOW_PEAK_MS) return ageMs / GLOW_PEAK_MS;
  return 1 - (ageMs - GLOW_PEAK_MS) / (GLOW_MS - GLOW_PEAK_MS);
}

/** deterministically solves for a t where `station` sits at its glow peak with `laps` completed orbits */
function solveGlowPeakTime(station: Station, laps: number): number {
  const targetPhase = laps - ARC_HALF_FRAC + GLOW_PEAK_MS / 1000 / PLANET_PERIOD_S;
  return (targetPhase - station.angleFrac) * PLANET_PERIOD_S;
}

interface Tokens {
  fg: [number, number, number];
  muted: [number, number, number];
  border: string;
}

function parseHex(hex: string): [number, number, number] | null {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m || !m[1]) return null;
  const v = m[1];
  return [parseInt(v.slice(0, 2), 16), parseInt(v.slice(2, 4), 16), parseInt(v.slice(4, 6), 16)];
}

function readTokens(): Tokens | null {
  if (typeof document === "undefined") return null;
  const cs = getComputedStyle(document.documentElement);
  const fgHex = cs.getPropertyValue("--foreground").trim();
  const mutedHex = cs.getPropertyValue("--ns-muted").trim();
  const border = cs.getPropertyValue("--border").trim();
  const fg = parseHex(fgHex);
  const muted = parseHex(mutedHex);
  if (!fg || !muted || !border) return null; // not loaded yet — no paint before this
  return { fg, muted, border };
}

function mixRGB(a: [number, number, number], b: [number, number, number], t: number): string {
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return `rgb(${r}, ${g}, ${bl})`;
}

export interface StackStepCarouselProps {
  /** Global simulation speed multiplier. @default 1 */
  speed?: number;
  /** Freezes the carrier on its current frame without unmounting. */
  paused?: boolean;
  /** Rendered in the DOM over the field — this layer alone is aria-hidden. */
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export function StackStepCarousel({
  speed = 1,
  paused = false,
  children,
  className = "",
  style,
}: StackStepCarouselProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const speedRef = useRef(speed);
  speedRef.current = speed;
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const stations = buildStations();

    let disposed = false;
    let tokens: Tokens | null = null;
    let dpr = 1;
    let W = 0;
    let H = 0;
    let minDim = 0;
    let cx = 0;
    let cy = 0;
    let sunRingRadius = 0;
    let discRadius = 0;
    let sized = false;
    let visible = true;

    let startMs = 0;
    let elapsedFrozenSec: number | null = null; // set once under reduced motion
    let hoverIndex = -1;
    let hoverAlpha = 0;

    let raf = 0;
    let tokenWaitRaf = 0;

    const fitCanvas = () => {
      canvas.width = Math.max(1, Math.round(W * dpr));
      canvas.height = Math.max(1, Math.round(H * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const stationPos = (angle: number): [number, number] => [
      cx + sunRingRadius * Math.sin(angle),
      cy - sunRingRadius * Math.cos(angle),
    ];

    const draw = (tSec: number) => {
      if (!tokens || !sized) return;
      ctx.clearRect(0, 0, W, H);

      // carrier guide ring — non-load-bearing separator, --border only
      ctx.save();
      ctx.strokeStyle = tokens.border;
      ctx.globalAlpha = 0.5;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(cx, cy, sunRingRadius, 0, Math.PI * 2);
      ctx.stroke();

      // carrier armature: a slow-rotating (14s) ring of index ticks — the
      // sun ring's own structural motion, fully decoupled from the discs'
      // 3.5s orbit
      const carrierAngle = (tSec / CARRIER_PERIOD_S) * Math.PI * 2;
      ctx.globalAlpha = 0.35;
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let k = 0; k < N_ARMATURE_TICKS; k++) {
        const a = (k / N_ARMATURE_TICKS) * Math.PI * 2 + carrierAngle;
        const inner = sunRingRadius * 0.94;
        const outer = sunRingRadius * 1.06;
        ctx.moveTo(cx + inner * Math.sin(a), cy - inner * Math.cos(a));
        ctx.lineTo(cx + outer * Math.sin(a), cy - outer * Math.cos(a));
      }
      ctx.stroke();
      ctx.restore();

      // fixed source arc at the top of the frame — must stay legible in
      // light theme, so it is --ns-muted brightening toward --foreground,
      // never the near-invisible --border
      const maxGlow = stations.reduce((m, s) => Math.max(m, glowAlpha(glowAge(s, tSec))), 0);
      ctx.save();
      ctx.strokeStyle = mixRGB(tokens.muted, tokens.fg, 0.35 + maxGlow * 0.65);
      ctx.globalAlpha = 0.75 + maxGlow * 0.25;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(cx, cy, sunRingRadius, -SOURCE_ARC_RAD / 2 - Math.PI / 2, SOURCE_ARC_RAD / 2 - Math.PI / 2);
      ctx.stroke();
      ctx.restore();

      for (let i = 0; i < stations.length; i++) {
        const st = stations[i]!;
        const [x, y] = stationPos(st.angle);
        const layer = layerAt(st, tSec);
        const frac = reflectanceFrac(layer);
        const fill = mixRGB(tokens.muted, tokens.fg, frac);
        const glow = glowAlpha(glowAge(st, tSec));

        if (glow > 0) {
          ctx.save();
          ctx.globalAlpha = glow * 0.5;
          ctx.fillStyle = mixRGB(tokens.muted, tokens.fg, 1);
          ctx.beginPath();
          ctx.arc(x, y, discRadius * 1.45, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
        }

        ctx.save();
        ctx.fillStyle = fill;
        ctx.beginPath();
        ctx.arc(x, y, discRadius, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        if (i === hoverIndex && hoverAlpha > 0.01) {
          ctx.save();
          ctx.globalAlpha = hoverAlpha * (0.3 + frac * 0.4);
          ctx.strokeStyle = mixRGB(tokens.muted, tokens.fg, 1);
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(x, y, discRadius * 1.2, 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();
        }
      }
    };

    const resizeAll = () => {
      if (!tokens) return;
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = rect.width;
      H = rect.height;
      minDim = Math.min(W, H);
      cx = W / 2;
      cy = H / 2;
      sunRingRadius = minDim * 0.32;
      discRadius = minDim * 0.09;
      fitCanvas();
      sized = true;
      if (elapsedFrozenSec != null) draw(elapsedFrozenSec);
    };

    const loop = (nowRaf: number) => {
      if (disposed) return;
      if (!visible) {
        raf = 0; // IntersectionObserver re-arms this on re-entering view
        return;
      }
      raf = requestAnimationFrame(loop);
      if (pausedRef.current) return; // stay armed; resumes the instant paused clears
      if (!sized || !tokens) return;
      if (startMs === 0) startMs = nowRaf;
      const tSec = ((nowRaf - startMs) / 1000) * speedRef.current;
      hoverAlpha += ((hoverIndex >= 0 ? 1 : 0) - hoverAlpha) * Math.min(1, 16 / HOVER_EASE_MS);
      draw(tSec);
    };

    let started = false;
    const kick = () => {
      if (started || disposed || !tokens || !sized) return;
      started = true;
      if (reduced) {
        // "carrier-crossing": station 3 pinned at its glow peak with 2 laps
        // already completed, the other 7 stations at their own staggered
        // positions and pre-crossing layer counts — deterministic, no rAF
        elapsedFrozenSec = solveGlowPeakTime(stations[3]!, 2);
        draw(elapsedFrozenSec);
        return; // no rAF loop, no timers, no observers driving motion
      }
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (disposed) return;
      tokens = readTokens();
      if (!tokens) {
        tokenWaitRaf = requestAnimationFrame(start);
        return;
      }
      resizeAll();
      kick();
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = wrap.getBoundingClientRect();
      const px = e.clientX - rect.left;
      const py = e.clientY - rect.top;
      let nearest = -1;
      let nearestD = Infinity;
      for (let i = 0; i < stations.length; i++) {
        const [x, y] = stationPos(stations[i]!.angle);
        const d = Math.hypot(px - x, py - y);
        if (d < discRadius * 1.3 && d < nearestD) {
          nearestD = d;
          nearest = i;
        }
      }
      hoverIndex = nearest;
      if (reduced && elapsedFrozenSec != null) draw(elapsedFrozenSec);
    };
    const onPointerLeave = () => {
      hoverIndex = -1;
      if (reduced && elapsedFrozenSec != null) draw(elapsedFrozenSec);
    };
    wrap.addEventListener("pointermove", onPointerMove);
    wrap.addEventListener("pointerleave", onPointerLeave);

    const ro = new ResizeObserver(() => {
      if (!tokens) return;
      resizeAll();
      kick();
    });
    ro.observe(wrap);

    const mo = new MutationObserver(() => {
      tokens = readTokens();
      if (tokens) {
        resizeAll();
        kick();
      }
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible && !reduced && tokens && !raf) {
        tokens = readTokens() ?? tokens; // pick up any theme flip that happened while hidden
        resizeAll();
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(wrap);

    start();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      cancelAnimationFrame(tokenWaitRaf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      wrap.removeEventListener("pointermove", onPointerMove);
      wrap.removeEventListener("pointerleave", onPointerLeave);
    };
  }, []);

  return (
    <div
      ref={wrapRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 block h-full w-full" />
      {children ? <div className="relative z-[1] h-full w-full">{children}</div> : null}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// DecalPeel — a vinyl sticker you can actually peel. The printed face is pure
// CSS/inline-SVG (accent-colored base, dark bolt monogram, halftone print
// dots, kiss-cut pale border); no image assets. Peeling is the classic CSS 3D
// two-layer trick: a perspective parent holds (1) the front face clipped by a
// clip-path polygon to the still-stuck region and (2) an adhesive-pale
// underside flap clipped to the inverse region and folded over the moving
// fold line with a 2D reflection matrix plus a rotate3d lift about the fold
// axis — the lift angle (the "curl radius") tightens as peel progress grows,
// and a specular sheen band sweeps the flap while any peel is in progress.
//
// Geometry (corner-local frame, peel corner mapped to (S,S)): peel progress
// p in [0,1] places the fold line at u = x + y = c where c = 2S(1-p). Front
// keeps u <= c; the flap is the u >= c region clipped in its own untransformed
// coordinates and then reflected across the fold line via
// matrix(0,-1,-1,0,c,c) (generalized per corner with sign flips), so the
// peeled-back copy folds exactly over the fold. rotate3d about the fold-line
// axis with transform-origin at the fold midpoint lifts the flap tip toward
// the viewer under the parent's perspective.
//
// Interaction: pointerdown grabs the nearest corner; drag distance from that
// corner sets progress; recent drag velocity tilts the whole decal
// (rotateY/rotateZ) with decay. Release below 0.7 re-sticks on an
// underdamped spring that overshoots below zero once (a slappy single flap,
// sold as a small squash pulse). Release at/after 0.7 (or a completed
// Space-hold ramp) tears the decal free: a rAF flutter phase rocks it under
// decaying oscillation while it drifts to the drop point, then a resettle
// phase blooms the drop shadow and flattens it back to fully stuck at the
// new position. Every continuous per-frame number lives in refs/locals and is
// written straight to element styles — React state only carries discrete
// facts (grab cursor, live-region text).
//
// Reduced motion: drag/hold still track progress directly (the interaction
// works), but every release lands instantly at its resolved state — no
// spring, no flutter, no sheen sweep, no velocity tilt.
// ---------------------------------------------------------------------------

export interface DecalPeelProps {
  /**
   * Self-driving mode for gallery screenshots: an internal script peels to
   * ~40% (re-stick), then ~90% (tear + flutter + resettle) on a loop, using
   * the same progress/release code paths as real input, and pauses itself
   * whenever a real pointer or keyboard interaction is active.
   */
  demo?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the sticker */
  "aria-label"?: string;
}

type Phase = "stuck" | "peeling" | "restick" | "flutter" | "resettle";

interface Corner {
  kx: 0 | 1;
  ky: 0 | 1;
}

interface Engine {
  pointerDown(x: number, y: number, id: number): void;
  pointerMove(x: number, y: number, id: number): void;
  pointerUp(x: number, y: number, id: number): void;
  holdStart(): void;
  holdEnd(): void;
  autoPeel(target: number, rampMs: number): boolean;
  userActive(): boolean;
}

const S = 220; // decal size px
const TEAR = 0.7; // release at/after this progress tears free
const HOLD_RAMP_S = 1.2; // Space-hold reaches 1.0 over this long
const DRAG_NORM = S * 1.2; // drag px that maps to progress 1
const FLUTTER_S = 0.85;
const RESETTLE_S = 0.38;
const MAX_OFF = 44; // clamp for drop offsets inside the 320px root

const SCRIPT_DROPS = [
  { x: 34, y: 26 },
  { x: -30, y: 16 },
  { x: 0, y: 0 },
] as const;

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));
const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

function poly(pts: [number, number][]): string {
  return `polygon(${pts
    .map(([x, y]) => `${x.toFixed(1)}px ${y.toFixed(1)}px`)
    .join(", ")})`;
}

export function DecalPeel({
  demo = false,
  className = "",
  "aria-label": ariaLabel = "Peel sticker — drag a corner, or press and hold Space",
}: DecalPeelProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const shadowRef = useRef<HTMLDivElement | null>(null);
  const frontRef = useRef<HTMLDivElement | null>(null);
  const castRef = useRef<HTMLDivElement | null>(null);
  const flapRef = useRef<HTMLDivElement | null>(null);
  const engineRef = useRef<Engine | null>(null);

  const parityRef = useRef(false);
  const [announceText, setAnnounceText] = useState("");
  const [grabbing, setGrabbing] = useState(false);

  // Zero-width-space parity toggle: repeated identical messages still change
  // the text node, which is what actually re-triggers an aria-live read.
  const announce = useCallback((msg: string) => {
    parityRef.current = !parityRef.current;
    setAnnounceText(msg + (parityRef.current ? "​" : ""));
  }, []);

  useEffect(() => {
    const root = rootRef.current;
    const wrap = wrapRef.current;
    const shadow = shadowRef.current;
    const front = frontRef.current;
    const cast = castRef.current;
    const flap = flapRef.current;
    if (!root || !wrap || !shadow || !front || !cast || !flap) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const onMq = () => {
      reduced = mq.matches;
    };
    mq.addEventListener("change", onMq);

    // -- hot-path state: locals only, never React state ---------------------
    let phase: Phase = "stuck";
    let progress = 0;
    let corner: Corner = { kx: 1, ky: 1 };
    let homeX = 0; // decal center offset from root center; persists after tear
    let homeY = 0;
    let raf = 0;
    let last = 0;
    let peelClass = false;

    let drag: {
      id: number;
      px: number;
      py: number;
      cx: number;
      cy: number;
    } | null = null;
    let velX = 0;
    let velY = 0;
    let lastMoveT = 0;
    let tiltY = 0;
    let tiltZ = 0;

    let hold = false;
    let script: { target: number; rate: number; releaseAt: number } | null =
      null;
    let scriptDrop = 0;

    let restick: { q: number; v: number; silent: boolean } | null = null;
    let squash = 1;
    let flut: {
      t: number;
      sx: number;
      sy: number;
      tx: number;
      ty: number;
      p0: number;
      silent: boolean;
    } | null = null;
    let fx = 0;
    let fy = 0;
    let flutRot = 0;
    let resettleT = -1;
    let resettleSilent = false;
    let shadowBloom = 0;

    const timeouts = new Set<number>();
    const later = (fn: () => void, ms: number) => {
      const id = window.setTimeout(() => {
        timeouts.delete(id);
        fn();
      }, ms);
      timeouts.add(id);
    };

    const applyCornerStyle = () => {
      const { kx, ky } = corner;
      // underside shading: darker at the fold, palest at the flap tip corner
      const angle = kx ? (ky ? 135 : 45) : ky ? 225 : 315;
      flap.style.setProperty("--dp-flap-angle", `${angle}deg`);
    };

    // -- renderers ----------------------------------------------------------
    const renderPeel = (pRaw: number) => {
      const p = clamp(pRaw, 0, 1);
      const { kx, ky } = corner;
      const mapPt = (x: number, y: number): [number, number] => [
        kx ? x : S - x,
        ky ? y : S - y,
      ];
      const wantClass = p > 0.01;
      if (wantClass !== peelClass) {
        peelClass = wantClass;
        wrap.classList.toggle("ns-dp-peeling", wantClass);
      }
      if (p <= 0.004) {
        front.style.clipPath = "";
        cast.style.backgroundImage = "";
        flap.style.opacity = "0";
        return;
      }
      const c = 2 * S * (1 - p); // fold line: x~ + y~ = c in corner-local frame
      let frontPts: [number, number][];
      let flapPts: [number, number][];
      if (c > S) {
        frontPts = [
          [0, 0],
          [S, 0],
          [S, c - S],
          [c - S, S],
          [0, S],
        ];
        flapPts = [
          [S, c - S],
          [S, S],
          [c - S, S],
        ];
      } else if (c > 0.5) {
        frontPts = [
          [0, 0],
          [c, 0],
          [0, c],
        ];
        flapPts = [
          [c, 0],
          [S, 0],
          [S, S],
          [0, S],
          [0, c],
        ];
      } else {
        frontPts = [
          [0, 0],
          [0.1, 0],
          [0, 0.1],
        ];
        flapPts = [
          [0, 0],
          [S, 0],
          [S, S],
          [0, S],
        ];
      }
      front.style.clipPath = poly(frontPts.map(([x, y]) => mapPt(x, y)));
      flap.style.clipPath = poly(flapPts.map(([x, y]) => mapPt(x, y)));
      flap.style.opacity = "1";
      // reflection across the fold line, generalized from the bottom-right
      // corner via sign flips: x' = m*y + ex*k, y' = m*x + ey*k
      const ex = kx ? 1 : -1;
      const ey = ky ? 1 : -1;
      const ox = kx ? 0 : S;
      const oy = ky ? 0 : S;
      const k = c - ox - oy;
      const m = -ex * ey;
      // curl radius tightens with progress: steeper lift the further you peel
      const lift = ex * ey * (10 + 42 * p);
      const fmx = kx ? c / 2 : S - c / 2;
      const fmy = ky ? c / 2 : S - c / 2;
      flap.style.transformOrigin = `${fmx.toFixed(1)}px ${fmy.toFixed(1)}px`;
      flap.style.transform = `matrix(0, ${m}, ${m}, 0, ${(ex * k).toFixed(2)}, ${(ey * k).toFixed(2)}) rotate3d(${ex}, ${-ey}, 0, ${lift.toFixed(2)}deg)`;
      // cast shadow on the still-stuck face just beyond the fold line
      const ax = kx ? S : 0;
      const ay = ky ? S : 0;
      const r = Math.SQRT2 * S * p;
      cast.style.backgroundImage = `radial-gradient(circle at ${ax}px ${ay}px, rgba(0,0,0,0.36) ${(r * 0.9).toFixed(1)}px, rgba(0,0,0,0) ${(r * 1.3).toFixed(1)}px)`;
    };

    const renderPose = () => {
      wrap.style.transform = `translate3d(${(homeX + fx).toFixed(2)}px, ${(homeY + fy).toFixed(2)}px, 0) rotateY(${tiltY.toFixed(2)}deg) rotateZ(${(tiltZ + flutRot).toFixed(2)}deg) scale(${squash.toFixed(3)})`;
    };

    const renderShadow = () => {
      const p = clamp(progress, 0, 1);
      let dy = 10 + p * 12;
      let blur = 24 + p * 26;
      let a = 0.38 - p * 0.06;
      if (flut) {
        dy = 28;
        blur = 52;
        a = 0.24;
      }
      blur += 30 * shadowBloom;
      a += 0.12 * shadowBloom;
      shadow.style.boxShadow = `0 ${dy.toFixed(1)}px ${blur.toFixed(1)}px rgba(0,0,0,${a.toFixed(3)})`;
    };

    // -- release outcomes ---------------------------------------------------
    const doRestick = (silent: boolean) => {
      script = null;
      phase = "restick";
      if (reduced) {
        progress = 0;
        phase = "stuck";
        renderPeel(0);
        renderPose();
        renderShadow();
        if (!silent) announce("Re-stuck");
        return;
      }
      restick = { q: progress, v: 0, silent };
      wake();
    };

    const tear = (drop: { x: number; y: number }, silent: boolean) => {
      script = null;
      const tx = clamp(drop.x, -MAX_OFF, MAX_OFF);
      const ty = clamp(drop.y, -MAX_OFF, MAX_OFF);
      if (!silent) announce("Torn free");
      if (reduced) {
        homeX = tx;
        homeY = ty;
        progress = 0;
        fx = 0;
        fy = 0;
        flutRot = 0;
        phase = "stuck";
        renderPeel(0);
        renderPose();
        renderShadow();
        if (!silent) later(() => announce("Re-adhered"), 350);
        return;
      }
      phase = "flutter";
      flut = {
        t: 0,
        sx: homeX,
        sy: homeY,
        tx,
        ty,
        p0: clamp(progress, 0, 1),
        silent,
      };
      wake();
    };

    // -- rAF loop -----------------------------------------------------------
    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      let active = false;

      if (drag) {
        const dist = Math.hypot(drag.px - drag.cx, drag.py - drag.cy);
        progress = clamp(dist / DRAG_NORM, 0, 1);
        velX *= Math.exp(-5 * dt);
        velY *= Math.exp(-5 * dt);
        active = true;
      }
      if (hold) {
        progress = clamp(progress + dt / HOLD_RAMP_S, 0, 1);
        if (progress >= 1) {
          // natural completion of the hold ramp: same tear path as a release
          hold = false;
          setGrabbing(false);
          tear({ x: homeX + 8, y: homeY + 30 }, false);
        }
        active = true;
      }
      if (script) {
        progress = reduced
          ? script.target
          : Math.min(script.target, progress + script.rate * dt);
        if (progress >= script.target - 1e-4) {
          if (script.releaseAt === 0) {
            // brief apex hold so the pose is legible before release
            script.releaseAt = now + (reduced ? 600 : 150);
          } else if (now >= script.releaseAt) {
            const t = script.target;
            script = null;
            if (t >= TEAR) {
              const d = SCRIPT_DROPS[scriptDrop % SCRIPT_DROPS.length]!;
              scriptDrop += 1;
              tear({ x: d.x, y: d.y }, true);
            } else {
              doRestick(true);
            }
          }
        }
        active = true;
      }

      // velocity tilt, decaying back to level when the pointer rests
      if (!reduced) {
        const peeling = drag || hold || script;
        const peelTilt = peeling
          ? -4 * clamp(progress, 0, 1) * (corner.kx ? 1 : -1)
          : 0;
        const tyT = clamp(velX * 0.018, -12, 12) + peelTilt;
        const tzT = clamp(velX * 0.008 - velY * 0.008, -8, 8);
        tiltY += (tyT - tiltY) * Math.min(1, dt * 9);
        tiltZ += (tzT - tiltZ) * Math.min(1, dt * 9);
        if (Math.abs(tiltY) > 0.03 || Math.abs(tiltZ) > 0.03) active = true;
      } else {
        tiltY = 0;
        tiltZ = 0;
      }

      if (restick) {
        // underdamped spring: one overshoot below zero = the corner flapping
        // once as the adhesive slaps back down
        const K = 210;
        const Z = 0.42;
        const cDamp = 2 * Z * Math.sqrt(K);
        restick.v += (-K * restick.q - cDamp * restick.v) * dt;
        restick.q += restick.v * dt;
        progress = Math.max(0, restick.q);
        squash = restick.q < 0 ? 1 + Math.min(0.05, -restick.q * 0.35) : 1;
        if (Math.abs(restick.q) < 0.004 && Math.abs(restick.v) < 0.03) {
          const silent = restick.silent;
          restick = null;
          squash = 1;
          progress = 0;
          phase = "stuck";
          if (!silent) announce("Re-stuck");
        } else {
          active = true;
        }
      }

      if (flut) {
        flut.t += dt;
        const u = clamp(flut.t / FLUTTER_S, 0, 1);
        const e = easeOutCubic(u); // fast detach, air-resistance deceleration
        fx = (flut.tx - flut.sx) * e + Math.sin(flut.t * 9) * 9 * (1 - u);
        fy = (flut.ty - flut.sy) * e;
        flutRot = 16 * Math.exp(-2.2 * flut.t) * Math.sin(flut.t * 9.5);
        progress = flut.p0 * (1 - e); // the sticker flattens as it falls
        if (u >= 1) {
          homeX = flut.tx;
          homeY = flut.ty;
          const silent = flut.silent;
          flut = null;
          fx = 0;
          fy = 0;
          flutRot = 0;
          progress = 0;
          phase = "resettle";
          resettleT = 0;
          resettleSilent = silent;
        }
        active = true;
      }

      if (resettleT >= 0) {
        resettleT += dt;
        const s = clamp(resettleT / RESETTLE_S, 0, 1);
        shadowBloom = Math.sin(Math.PI * s); // bloom, then flatten
        squash = 1 + 0.045 * Math.sin(Math.PI * s);
        if (s >= 1) {
          resettleT = -1;
          shadowBloom = 0;
          squash = 1;
          phase = "stuck";
          if (!resettleSilent) announce("Re-adhered");
        }
        active = true;
      }

      renderPeel(progress);
      renderPose();
      renderShadow();
      if (active) raf = requestAnimationFrame(loop);
      else last = 0;
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const rootCenter = () => {
      const r = root.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    };

    // -- public api ---------------------------------------------------------
    const api: Engine = {
      pointerDown(x, y, id) {
        if (phase === "flutter" || phase === "resettle") return;
        script = null;
        restick = null;
        squash = 1;
        const c0 = rootCenter();
        const cx0 = c0.x + homeX;
        const cy0 = c0.y + homeY;
        corner = { kx: x >= cx0 ? 1 : 0, ky: y >= cy0 ? 1 : 0 };
        applyCornerStyle();
        drag = {
          id,
          px: x,
          py: y,
          cx: cx0 + (corner.kx ? S / 2 : -S / 2),
          cy: cy0 + (corner.ky ? S / 2 : -S / 2),
        };
        velX = 0;
        velY = 0;
        lastMoveT = performance.now();
        hold = false;
        phase = "peeling";
        setGrabbing(true);
        announce("Peeling");
        wake();
      },
      pointerMove(x, y, id) {
        if (!drag || drag.id !== id) return;
        const now = performance.now();
        const dtm = Math.max(1, now - lastMoveT) / 1000;
        velX += ((x - drag.px) / dtm - velX) * 0.4;
        velY += ((y - drag.py) / dtm - velY) * 0.4;
        lastMoveT = now;
        drag.px = x;
        drag.py = y;
        wake();
      },
      pointerUp(x, y, id) {
        if (!drag || drag.id !== id) return;
        drag = null;
        setGrabbing(false);
        if (progress >= TEAR) {
          const c0 = rootCenter();
          tear({ x: x - c0.x, y: y - c0.y }, false); // re-adheres where dropped
        } else {
          doRestick(false);
        }
        wake();
      },
      holdStart() {
        if (hold || drag) return;
        if (phase === "flutter" || phase === "resettle") return;
        script = null;
        restick = null;
        squash = 1;
        corner = { kx: 1, ky: 1 };
        applyCornerStyle();
        hold = true;
        phase = "peeling";
        setGrabbing(true);
        announce("Peeling");
        wake();
      },
      holdEnd() {
        if (!hold) return;
        hold = false;
        setGrabbing(false);
        if (progress >= TEAR) tear({ x: homeX + 8, y: homeY + 30 }, false);
        else doRestick(false);
      },
      autoPeel(target, rampMs) {
        if (drag || hold) return false;
        if (phase !== "stuck") return false;
        corner = { kx: 1, ky: 1 };
        applyCornerStyle();
        phase = "peeling";
        script = { target, rate: target / (rampMs / 1000), releaseAt: 0 };
        wake();
        return true;
      },
      userActive: () => Boolean(drag || hold),
    };
    engineRef.current = api;

    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    applyCornerStyle();
    renderPeel(0);
    renderPose();
    renderShadow();

    return () => {
      cancelAnimationFrame(raf);
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      timeouts.forEach((id) => window.clearTimeout(id));
      timeouts.clear();
      engineRef.current = null;
    };
  }, [announce]);

  // Self-driving demo script: same code paths as real input, guarded so it
  // pauses while any real pointer/keyboard interaction is in progress.
  useEffect(() => {
    if (!demo) return;
    let alive = true;
    let timer: number | undefined;
    const STEPS = [
      { target: 0.42, ramp: 800, wait: 2400 }, // partial peel -> spring re-stick
      { target: 0.92, ramp: 900, wait: 3400 }, // past threshold -> tear + flutter
    ];
    let i = 0;
    const tick = () => {
      if (!alive) return;
      const eng = engineRef.current;
      const step = STEPS[i % STEPS.length]!;
      if (eng && !eng.userActive() && eng.autoPeel(step.target, step.ramp)) {
        i += 1;
        timer = window.setTimeout(tick, step.ramp + step.wait);
      } else {
        timer = window.setTimeout(tick, 900);
      }
    };
    timer = window.setTimeout(tick, 1000);
    return () => {
      alive = false;
      window.clearTimeout(timer);
    };
  }, [demo]);

  return (
    <div
      ref={rootRef}
      role="button"
      tabIndex={0}
      aria-label={ariaLabel}
      className={`ns-dp-root ${grabbing ? "ns-dp-grabbing" : ""} ${className}`}
      onPointerDown={(e: ReactPointerEvent<HTMLDivElement>) => {
        e.currentTarget.setPointerCapture(e.pointerId);
        engineRef.current?.pointerDown(e.clientX, e.clientY, e.pointerId);
      }}
      onPointerMove={(e: ReactPointerEvent<HTMLDivElement>) =>
        engineRef.current?.pointerMove(e.clientX, e.clientY, e.pointerId)
      }
      onPointerUp={(e: ReactPointerEvent<HTMLDivElement>) =>
        engineRef.current?.pointerUp(e.clientX, e.clientY, e.pointerId)
      }
      onPointerCancel={(e: ReactPointerEvent<HTMLDivElement>) =>
        engineRef.current?.pointerUp(e.clientX, e.clientY, e.pointerId)
      }
      onKeyDown={(e: ReactKeyboardEvent<HTMLDivElement>) => {
        if (e.key === " " || e.code === "Space") {
          e.preventDefault();
          if (!e.repeat) engineRef.current?.holdStart();
        }
      }}
      onKeyUp={(e: ReactKeyboardEvent<HTMLDivElement>) => {
        if (e.key === " " || e.code === "Space") {
          e.preventDefault();
          engineRef.current?.holdEnd();
        }
      }}
      onBlur={() => engineRef.current?.holdEnd()}
    >
      <style>{CSS}</style>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announceText}
      </span>

      <div ref={wrapRef} className="ns-dp-wrap" aria-hidden="true">
        <div ref={shadowRef} className="ns-dp-shadow" />
        <div ref={frontRef} className="ns-dp-front">
          <div className="ns-dp-gloss" />
          <div className="ns-dp-dots" />
          <div className="ns-dp-art">
            <svg
              width="110"
              height="110"
              viewBox="0 0 24 24"
              aria-hidden="true"
              focusable="false"
            >
              <path
                d="M13 2 L4 14 H11 L10 22 L20 9 H12.5 Z"
                fill="var(--background)"
                fillOpacity="0.92"
                stroke="rgba(0,0,0,0.25)"
                strokeWidth="0.4"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <div ref={castRef} className="ns-dp-cast" />
        </div>
        <div ref={flapRef} className="ns-dp-flap">
          <div className="ns-dp-sheen" />
        </div>
      </div>
    </div>
  );
}

const CSS = `
.ns-dp-root{
  position:relative;
  width:320px;height:320px;
  display:flex;align-items:center;justify-content:center;
  border-radius:16px;
  border:1px solid var(--border);
  background:color-mix(in srgb, var(--foreground) 3%, var(--background));
  box-shadow:0 6px 20px rgba(0,0,0,0.25);
  cursor:grab;
  touch-action:none;
  user-select:none;
  -webkit-user-select:none;
  perspective:900px;
  overflow:hidden;
